window.LAW_SEARCH_IDX = window.LAW_SEARCH_IDX || {};
window.LAW_SEARCH_IDX["生态环境部"] = {"qiyehuanjingxinxiyifapiluguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范企业环境信息依法披露活动，加强社会监督，根据《中华人民共和国环境保护法》《中华人民共和国清洁生产促进法》《公共企事业单位信息公开规定制定办法》《环境信息依法披露制度改革方案》等相关法律法规和文件，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于企业依法披露环境信息及其监督管理活动。"},{"i":3,"n":"第三条","txt":"生态环境部负责全国环境信息依法披露的组织、指导、监督和管理。 设区的市级以上地方生态环境主管部门负责本行政区域环境信息依法披露的组织实施和监督管理。"},{"i":4,"n":"第四条","txt":"企业是环境信息依法披露的责任主体。 企业应当建立健全环境信息依法披露管理制度，规范工作规程，明确工作职责，建立准确的环境信息管理台账，妥善保存相关原始记录，科学统计归集相关环境信息。 企业披露环境信息所使用的相关数据及表述应当符合环境监测、环境统计等方面的标准和技术规范要求，优先使用符合国家监测规范的污染物监测数据、排污许可证执行报告数据等。"},{"i":5,"n":"第五条","txt":"企业应当依法、及时、真实、准确、完整地披露环境信息，披露的环境信息应当简明清晰、通俗易懂，不得有虚假记载、误导性陈述或者重大遗漏。"},{"i":6,"n":"第六条","txt":"企业披露涉及国家秘密、战略高新技术和重要领域核心关键技术、商业秘密的环境信息，依照有关法律法规的规定执行；涉及重大环境信息披露的，应当按照国家有关规定请示报告。 任何公民、法人或者其他组织不得非法获取企业环境信息，不得非法修改披露的环境信息。"},{"i":7,"n":"第七条","txt":"下列企业应当按照本办法的规定披露环境信息： （一）重点排污单位； （二）实施强制性清洁生产审核的企业； （三）符合本办法第八条规定的上市公司及合并报表范围内的各级子公司（以下简称上市公司）； （四）符合本办法第八条规定的发行企业债券、公司债券、非金融企业债务融资工具的企业（以下简称发债企业）； （五）法律法规规定的其他应当披露环境信息的企业。"},{"i":8,"n":"第八条","txt":"上一年度有下列情形之一的上市公司和发债企业，应当按照本办法的规定披露环境信息： （一）因生态环境违法行为被追究刑事责任的； （二）因生态环境违法行为被依法处以十万元以上罚款的； （三）因生态环境违法行为被依法实施按日连续处罚的； （四）因生态环境违法行为被依法实施限制生产、停产整治的； （五）因生态环境违法行为被依法吊销生态环境相关许可证件的； （六）因生态环境违法行为，其法定代表人、主要负责人、直接负责的主管人员或者其他直接责任人员被依法处以行政拘留的。"},{"i":9,"n":"第九条","txt":"设区的市级生态环境主管部门组织制定本行政区域内的环境信息依法披露企业名单（以下简称企业名单）。 设区的市级生态环境主管部门应当于每年3月底前确定本年度企业名单，并向社会公布。企业名单公布前应当在政府网站上进行公示，征求公众意见；公示期限不得少于十个工作日。 对企业名单公布后新增的符合纳入企业名单要求的企业，设区的市级生态环境主管部门应当将其纳入下一年度企业名单。 设区的市级生态环境主管部门应当在企业名单公布后十个工作日内报送省级生态环境主管部门。省级生态环境主管部门应当于每年4月底前，将本行政区域的企业名单报送生态环境部。"},{"i":10,"n":"第十条","txt":"重点排污单位应当自列入重点排污单位名录之日起，纳入企业名单。 实施强制性清洁生产审核的企业应当自列入强制性清洁生产审核名单后，纳入企业名单，并延续至该企业完成强制性清洁生产审核验收后的第三年。 上市公司、发债企业应当连续三年纳入企业名单；期间再次发生本办法第八条规定情形的，应当自三年期限届满后，再连续三年纳入企业名单。 对同时符合本条规定的两种以上情形的企业，应当按照最长期限纳入企业名单。"},{"i":11,"n":"第十一条","txt":"生态环境部负责制定企业环境信息依法披露格式准则（以下简称准则），并根据生态环境管理需要适时进行调整。 企业应当按照准则编制年度环境信息依法披露报告和临时环境信息依法披露报告，并上传至企业环境信息依法披露系统。"},{"i":12,"n":"第十二条","txt":"企业年度环境信息依法披露报告应当包括以下内容： （一）企业基本信息，包括企业生产和生态环境保护等方面的基础信息； （二）企业环境管理信息，包括生态环境行政许可、环境保护税、环境污染责任保险、环保信用评价等方面的信息； （三）污染物产生、治理与排放信息，包括污染防治设施，污染物排放，有毒有害物质排放，工业固体废物和危险废物产生、贮存、流向、利用、处置，自行监测等方面的信息； （四）碳排放信息，包括排放量、排放设施等方面的信息； （五）生态环境应急信息，包括突发环境事件应急预案、重污染天气应急响应等方面的信息； （六）生态环境违法信息； （七）本年度临时环境信息依法披露情况； （八）法律法规规定的其他环境信息。"},{"i":13,"n":"第十三条","txt":"重点排污单位披露年度环境信息时，应当披露本办法第十二条规定的环境信息。"},{"i":14,"n":"第十四条","txt":"实施强制性清洁生产审核的企业披露年度环境信息时，除了披露本办法第十二条规定的环境信息外，还应当披露以下信息： （一）实施强制性清洁生产审核的原因； （二）强制性清洁生产审核的实施情况、评估与验收结果。"},{"i":15,"n":"第十五条","txt":"上市公司和发债企业披露年度环境信息时，除了披露本办法第十二条规定的环境信息外，还应当按照以下规定披露相关信息： （一）上市公司通过发行股票、债券、存托凭证、中期票据、短期融资券、超短期融资券、资产证券化、银行贷款等形式进行融资的，应当披露年度融资形式、金额、投向等信息，以及融资所投项目的应对气候变化、生态环境保护等相关信息； （二）发债企业通过发行股票、债券、存托凭证、可交换债、中期票据、短期融资券、超短期融资券、资产证券化、银行贷款等形式融资的，应当披露年度融资形式、金额、投向等信息，以及融资所投项目的应对气候变化、生态环境保护等相关信息。 上市公司和发债企业属于强制性清洁生产审核企业的，还应当按照本办法第十四条的规定披露相关环境信息。"},{"i":16,"n":"第十六条","txt":"企业未产生本办法规定的环境信息的，可以不予披露。"},{"i":17,"n":"第十七条","txt":"企业应当自收到相关法律文书之日起五个工作日内，以临时环境信息依法披露报告的形式，披露以下环境信息： （一）生态环境行政许可准予、变更、延续、撤销等信息； （二）因生态环境违法行为受到行政处罚的信息； （三）因生态环境违法行为，其法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员被依法处以行政拘留的信息； （四）因生态环境违法行为，企业或者其法定代表人、主要负责人、直接负责的主管人员和其他直接责任人员被追究刑事责任的信息； （五）生态环境损害赔偿及协议信息。 企业发生突发环境事件的，应当依照有关法律法规规定披露相关信息。"},{"i":18,"n":"第十八条","txt":"企业可以根据实际情况对已披露的环境信息进行变更；进行变更的，应当以临时环境信息依法披露报告的形式变更，并说明变更事项和理由。"},{"i":19,"n":"第十九条","txt":"企业应当于每年3月15日前披露上一年度1月1日至12月31日的环境信息。"},{"i":20,"n":"第二十条","txt":"企业在企业名单公布前存在本办法第十七条规定的环境信息的，应当于企业名单公布后十个工作日内以临时环境信息依法披露报告的形式披露本年度企业名单公布前的相关信息。"},{"i":21,"n":"第二十一条","txt":"生态环境部、设区的市级以上地方生态环境主管部门应当依托政府网站等设立企业环境信息依法披露系统，集中公布企业环境信息依法披露内容，供社会公众免费查询，不得向企业收取任何费用。"},{"i":22,"n":"第二十二条","txt":"生态环境主管部门应当加强企业环境信息依法披露系统与全国排污许可证管理信息平台等生态环境相关信息系统的互联互通，充分利用信息化手段避免企业重复填报。 生态环境主管部门应当加强企业环境信息依法披露系统与信用信息共享平台、金融信用信息基础数据库对接，推动环境信息跨部门、跨领域、跨地区互联互通、共享共用，及时将相关环境信息提供给有关部门。"},{"i":23,"n":"第二十三条","txt":"设区的市级生态环境主管部门应当于每年3月底前，将上一年度本行政区域环境信息依法披露情况报送省级生态环境主管部门。省级生态环境主管部门应当于每年4月底前将相关情况报送生态环境部。 报送的环境信息依法披露情况应当包括以下内容： （一）企业开展环境信息依法披露的总体情况； （二）对企业环境信息依法披露的监督检查情况； （三）其他应当报送的信息。"},{"i":24,"n":"第二十四条","txt":"生态环境主管部门应当会同有关部门加强对企业环境信息依法披露活动的监督检查，及时受理社会公众举报，依法查处企业未按规定披露环境信息的行为。鼓励生态环境主管部门运用大数据分析、人工智能等技术手段开展监督检查。"},{"i":25,"n":"第二十五条","txt":"公民、法人或者其他组织发现企业有违反本办法规定行为的，有权向生态环境主管部门举报。接受举报的生态环境主管部门应当依法进行核实处理，并对举报人的相关信息予以保密，保护举报人的合法权益。 生态环境主管部门应当畅通投诉举报渠道，引导社会公众、新闻媒体等对企业环境信息依法披露进行监督。"},{"i":26,"n":"第二十六条","txt":"设区的市级以上生态环境主管部门应当按照国家有关规定，将环境信息依法披露纳入企业信用管理，作为评价企业信用的重要指标，并将企业违反环境信息依法披露要求的行政处罚信息记入信用记录。"},{"i":27,"n":"第二十七条","txt":"法律法规对企业环境信息公开或者披露规定了法律责任的，依照其规定执行。"},{"i":28,"n":"第二十八条","txt":"企业违反本办法规定，不披露环境信息，或者披露的环境信息不真实、不准确的，由设区的市级以上生态环境主管部门责令改正，通报批评，并可以处一万元以上十万元以下的罚款。"},{"i":29,"n":"第二十九条","txt":"企业违反本办法规定，有下列行为之一的，由设区的市级以上生态环境主管部门责令改正，通报批评，并可以处五万元以下的罚款： （一）披露环境信息不符合准则要求的; （二）披露环境信息超过规定时限的； （三）未将环境信息上传至企业环境信息依法披露系统的。"},{"i":30,"n":"第三十条","txt":"设区的市级以上地方生态环境主管部门在企业环境信息依法披露监督管理中有玩忽职守、滥用职权、徇私舞弊行为的，依法依纪对直接负责的主管人员或者其他直接责任人员给予处分。"},{"i":31,"n":"第三十一条","txt":"事业单位依法披露环境信息的，参照本办法执行。"},{"i":32,"n":"第三十二条","txt":"本办法由生态环境部负责解释。"},{"i":33,"n":"第三十三条","txt":"本办法自2022年2月8日起施行。《企业事业单位环境信息公开办法》（环境保护部令第31号）同时废止。"}],"ruhepaiwukoujianduguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强入河排污口监督管理，控制入河污染物排放，保护和改善水生态环境，根据《中华人民共和国水污染防治法》《中华人民共和国水法》等法律和国务院相关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"入河排污口设置审批、登记以及相关监督管理活动，适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称入河排污口，是指直接或者通过管道、沟、渠等排污通道向江河、湖泊、运河、水库等水体排放污水的口门。 本办法所称入河排污口设置，包括新设、改设或者扩大入河排污口。新设，是指入河排污口的首次建造或者使用；改设，是指已有入河排污口的排放位置、排放方式等事项的重大改变；扩大，是指已有入河排污口排污能力的提高。"},{"i":4,"n":"第四条","txt":"国务院生态环境主管部门负责指导全国入河排污口设置和监督管理。 国务院生态环境主管部门所属流域生态环境监督管理机构（以下简称流域生态环境监督管理机构）负责指导流域内入河排污口设置，承办国务院生态环境主管部门授权范围内入河排污口设置审批和监督管理。 地方生态环境主管部门按照规定权限负责本行政区域入河排污口设置审批、登记和监督管理。"},{"i":5,"n":"第五条","txt":"入河排污口应当明确责任主体。责任主体负责源头治理以及入河排污口的设置申请或者登记、整治、规范化建设、维护管理等。 多个排污单位共用同一入河排污口的，所有排污单位均为责任主体，各自承担的责任由所有排污单位协商确定。"},{"i":6,"n":"第六条","txt":"入河排污口按照其责任主体所属行业以及排放特征，分为工业排污口、城镇污水处理厂排污口、农业排口、其他排口四种类型。 工业排污口包括工矿企业排污口和雨洪排口、工业以及其他各类园区污水处理厂排污口和雨洪排口等；农业排口包括规模化畜禽养殖排污口、规模化水产养殖排污口等；其他排口包括大中型灌区排口、规模以下畜禽养殖排污口、规模以下水产养殖排污口、农村污水处理设施排污口、农村生活污水散排口等。"},{"i":7,"n":"第七条","txt":"编制生态环境保护规划、江河湖泊水功能区划等，应当充分考虑入河排污口布局和管控要求。 开展工业、农业、畜牧业、林业、能源、水利、交通、城市建设、旅游、自然资源开发的有关专项规划的环境影响评价，应当将入河排污口设置有关规定落实情况作为重要内容。"},{"i":8,"n":"第八条","txt":"国家加强入河排污口管理基础性研究和专业技术人才培养。鼓励开展遥感监测、水面航测、水下探测、管线排查等实用技术和装备的研发集成和推广应用。"},{"i":9,"n":"第九条","txt":"鼓励地方加大财政资金投入力度，吸引社会资本参与入河排污口整治、规范化建设、维护管理等。"},{"i":10,"n":"第十条","txt":"对在入河排污口监督管理工作中做出优异成绩的单位和个人，可以按照国家或者地方的有关规定给予表彰、奖励。"},{"i":11,"n":"第十一条","txt":"设置工矿企业排污口、工业以及其他各类园区污水处理厂排污口和城镇污水处理厂排污口，应当按照本办法的规定，报有审批权的流域生态环境监督管理机构或者地方生态环境主管部门（以下简称审批部门）审批；未经批准的，禁止通过上述入河排污口排放污水。"},{"i":12,"n":"第十二条","txt":"设置本办法第十一条规定的入河排污口，符合下列条件之一的，由流域生态环境监督管理机构负责审批： （一）建设项目环境影响评价文件由国务院生态环境主管部门审批的； （二）位于省界缓冲区的； （三）位于国际河湖或者国境边界河湖的； （四）存在省际争议的。 前款规定范围外的入河排污口设置审批权限，由入河排污口所在的省级生态环境主管部门确定，并向社会公开。"},{"i":13,"n":"第十三条","txt":"入河排污口设置审批程序包括申请、受理、审查、决定。 （一）申请。责任主体应当在入河排污口设置前向审批部门提出设置申请。多个排污单位共用同一入河排污口的，可以委托其中一个责任主体提出申请。 （二）受理。审批部门对申请材料齐全、符合法定形式的，予以受理。 （三）审查。审批部门对受理的申请材料进行审查，并可以根据需要，组织专家评审、听证或者现场查勘。组织专家评审、听证或者现场查勘，不得向申请单位收取任何费用。 （四）决定。审批部门应当自受理入河排污口设置申请之日起二十个工作日内作出准予许可或者不予许可的决定。对准予许可的，颁发同意设置入河排污口的决定书（以下简称决定书）；对不符合许可条件的，不予许可并书面说明理由。决定书应当公开，供公众查询。 开展专家评审、听证、现场查勘等活动所需时间，不计算在本条规定的许可期限内。"},{"i":14,"n":"第十四条","txt":"申请设置入河排污口的，应当提交入河排污口设置申请书、入河排污口设置论证报告或者简要分析材料、建设项目依据文件。 有下列情形之一的，应当提交入河排污口设置论证报告： （一）责任主体属于造纸、焦化、氮肥、化工、印染、农副食品加工、制革、电镀、冶金、有色金属、原料药制造、农药等行业的； （二）排放放射性物质、重金属以及其他有毒有害水污染物的； （三）污水或者污染物排放量达到国务院生态环境主管部门确定的规模标准的。 前款规定以外的入河排污口设置申请，应当提交入河排污口设置简要分析材料。"},{"i":15,"n":"第十五条","txt":"入河排污口设置论证报告应当包括下列内容： （一）责任主体基本情况。 （二）入河排污口所在水域水生态环境现状。 （三）入河排污口设置地点，污水排放方式、排放去向。 （四）入河排污口污水排放量，入河排污口重点污染物排放种类、排放浓度和排放量。 （五）入河排污口设置对周边环境影响以及相关环境风险分析。 （六）水生态环境保护措施以及效果分析；排放放射性物质的，还应当论证放射性物质管控措施以及效果。 （七）论证结论。 （八）需要分析或者说明的其他事项。 入河排污口设置简要分析材料应当包括前款规定的第一项、第二项、第三项、第四项内容。"},{"i":16,"n":"第十六条","txt":"多个排污单位共用同一入河排污口的，入河排污口设置论证报告和简要分析材料中还应当明确每个责任主体的入河排污口污水排放量，入河排污口重点污染物排放种类、排放浓度和排放量，并区分各自责任。"},{"i":17,"n":"第十七条","txt":"入河排污口责任主体可以自行或者委托技术单位开展入河排污口设置论证，编制入河排污口设置论证报告或者简要分析材料。责任主体对入河排污口设置论证报告或者简要分析材料的内容和结论负责。 任何单位和个人不得为责任主体指定编制入河排污口设置论证报告或者简要分析材料的技术单位。"},{"i":18,"n":"第十八条","txt":"有下列情形之一的，禁止设置入河排污口： （一）在饮用水水源保护区内； （二）在风景名胜区水体、重要渔业水体和其他具有特殊经济文化价值的水体的保护区内； （三）不符合法律、行政法规规定的其他情形。 对流域水生态环境质量不达标的水功能区，除城镇污水处理厂等重要民生工程的入河排污口外，严格控制入河排污口设置。"},{"i":19,"n":"第十九条","txt":"入河排污口责任主体依法取得排污许可证的，入河排污口设置审批应当与排污许可证记载事项做好衔接。"},{"i":20,"n":"第二十条","txt":"决定书应当记载下列信息： （一）责任主体基本情况。 （二）入河排污口名称、编码、设置地点，污水排放方式、排放去向。 （三）入河排污口污水排放量，入河排污口重点污染物排放种类、排放浓度和排放量，特殊时段的限制排放要求。 （四）信息公开要求。 （五）水污染事故应急预案以及环境风险防范措施。 （六）水生态环境保护措施；排放放射性物质的，还应当明确放射性物质管控措施。 （七）法律、行政法规规定的其他事项。 多个排污单位共用同一入河排污口的，决定书中还应当记载每个责任主体的入河排污口污水排放量，入河排污口重点污染物排放种类、排放浓度和排放量，特殊时段的限制排放要求，并区分各自责任。"},{"i":21,"n":"第二十一条","txt":"入河排污口责任主体名称、生产经营场所地址、法定代表人或者主要负责人以及联系方式等信息发生变更的，应当自变更之日起三十日内，向审批部门申请办理决定书变更手续。对符合要求的，审批部门应当在十个工作日内予以变更。"},{"i":22,"n":"第二十二条","txt":"设置本办法第十一条规定以外的入河排污口，应当在入河排污口设置前，向所在的设区的市级生态环境主管部门提交入河排污口登记表。对符合要求的，生态环境主管部门应当在十个工作日内予以确认并登记。 已登记的入河排污口，责任主体所属行业以及排放特征发生变动，符合本办法第十一条规定情形的，应当按照本办法的规定办理入河排污口设置审批。"},{"i":23,"n":"第二十三条","txt":"入河排污口不再使用的，责任主体应当自行拆除或者关闭入河排污口，并自拆除或者关闭之日起三十日内，申请注销决定书或者登记表。"},{"i":24,"n":"第二十四条","txt":"国务院生态环境主管部门负责全国入河排污口信息化管理工作，组织建立并动态更新入河排污口管理台账，加强入河排污口设置审批、登记、排查整治、日常监督检查等信息管理。"},{"i":25,"n":"第二十五条","txt":"生态环境主管部门、流域生态环境监督管理机构应当根据国家有关规定和监测规范，加强对入河排污口的监督监测。水生态环境质量较差的地方应当适当增加入河排污口监测频次。"},{"i":26,"n":"第二十六条","txt":"流域生态环境监督管理机构应当加大对流域内入河排污口的监督检查力度，发现问题及时通报有关单位。    地方生态环境主管部门应当加强对入河排污口的现场检查，必要时可以会同有关部门开展联合监督检查。"},{"i":27,"n":"第二十七条","txt":"国务院生态环境主管部门应当按照国家有关规定，组织开展入河排污口排查整治，加强对地方排查整治工作的指导。 流域生态环境监督管理机构和地方生态环境主管部门应当按照职责分工将入河排污口排查整治情况纳入入河排污口管理台账。 鼓励开展入河排污口整治、规范化建设标杆工程创建，发挥引领示范作用。"},{"i":28,"n":"第二十八条","txt":"入河排污口责任主体应当定期巡查维护排污通道、口门以及附属设施等；发现他人借道排污等情形的，应当立即向所在地生态环境主管部门报告并留存证据。"},{"i":29,"n":"第二十九条","txt":"鼓励入河排污口责任主体安装视频监控系统，加强入河排污口日常管理维护。"},{"i":30,"n":"第三十条","txt":"入河排污口监测采样点、检查井、标识牌等设置应当符合国务院生态环境主管部门规范化建设标准要求。责任主体应当按照国务院生态环境主管部门规定，在污水入河处或者监测采样点等醒目位置设置标识牌。"},{"i":31,"n":"第三十一条","txt":"入河排污口责任主体应当通过标识牌、显示屏、二维码标识或者网络媒体等主动向社会公开入河排污口相关信息。"},{"i":32,"n":"第三十二条","txt":"入河排污口排放污染物造成或者可能造成水污染事故时，责任主体应当立即启动应急预案，并依法向事故发生地的县级以上地方人民政府或者生态环境主管部门报告，接受调查处理，同时采取应急措施切断或者控制事故污染源，拦截、导流、分流事故污水并进行妥善处置。"},{"i":33,"n":"第三十三条","txt":"生态环境主管部门应当建立健全公众监督举报机制，鼓励社会公众、新闻媒体对入河排污口排污情况等进行监督。"},{"i":34,"n":"第三十四条","txt":"公民、法人和其他组织发现有违反本办法规定行为的，有权向生态环境主管部门举报。接受举报的生态环境主管部门应当依法处理，并按照有关规定向举报人反馈处理结果，同时为举报人保密。"},{"i":35,"n":"第三十五条","txt":"违反本办法规定，在饮用水水源保护区内设置入河排污口的，依照《中华人民共和国水污染防治法》第八十四条第一款的规定予以处罚。 违反本办法规定，有下列情形之一的，由生态环境主管部门依照《中华人民共和国水污染防治法》第八十四条第二款、第三款的规定予以处罚： （一）在风景名胜区水体、重要渔业水体和其他具有特殊经济文化价值的水体的保护区等设置入河排污口的； （二）未经审批擅自设置入河排污口的； （三）未按照决定书要求设置入河排污口的； （四）其他违反法律、行政法规和国务院生态环境主管部门的规定设置入河排污口的。"},{"i":36,"n":"第三十六条","txt":"入河排污口设置申请书、决定书，入河排污口登记表等文书格式，由国务院生态环境主管部门另行制定。"},{"i":37,"n":"第三十七条","txt":"本办法施行前已经依法取得的同意设置入河排污口决定，本办法施行后继续有效。"},{"i":38,"n":"第三十八条","txt":"入河排污口设置审批、登记、监督管理等涉及国家秘密的，应当遵守国家有关保密法律法规的规定。"},{"i":39,"n":"第三十九条","txt":"入河排污口设置审批、登记、监督管理，本办法未作规定的，适用其他相关法律、行政法规、国务院文件的规定。"},{"i":40,"n":"第四十条","txt":"本办法自2025年1月1日起施行。"}],"nongyongdituranghuanjingguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强农用地土壤环境保护监督管理，保护农用地土壤环境，管控农用地土壤环境风险，保障农产品质量安全，根据《中华人民共和国环境保护法》《中华人民共和国农产品质量安全法》等法律法规和《土壤污染防治行动计划》，制定本办法。"},{"i":2,"n":"第二条","txt":"农用地土壤污染防治相关活动及其监督管理适用本办法。 前款所指的农用地土壤污染防治相关活动，是指对农用地开展的土壤污染预防、土壤污染状况调查、环境监测、环境质量类别划分、分类管理等活动。 本办法所称的农用地土壤环境质量类别划分和分类管理，主要适用于耕地。园地、草地、林地可参照本办法。"},{"i":3,"n":"第三条","txt":"环境保护部对全国农用地土壤环境保护工作实施统一监督管理；县级以上地方环境保护主管部门对本行政区域内农用地土壤污染防治相关活动实施统一监督管理。 农业部对全国农用地土壤安全利用、严格管控、治理与修复等工作实施监督管理；县级以上地方农业主管部门负责本行政区域内农用地土壤安全利用、严格管控、治理与修复等工作的组织实施。 农用地土壤污染预防、土壤污染状况调查、环境监测、环境质量类别划分、农用地土壤优先保护、监督管理等工作，由县级以上环境保护和农业主管部门按照本办法有关规定组织实施。"},{"i":4,"n":"第四条","txt":"环境保护部会同农业部制定农用地土壤污染状况调查、环境监测、环境质量类别划分等技术规范。 农业部会同环境保护部制定农用地土壤安全利用、严格管控、治理与修复、治理与修复效果评估等技术规范。"},{"i":5,"n":"第五条","txt":"县级以上地方环境保护和农业主管部门在编制本行政区域的环境保护规划和农业发展规划时，应当包含农用地土壤污染防治工作的内容。"},{"i":6,"n":"第六条","txt":"环境保护部会同农业部等部门组织建立全国农用地土壤环境管理信息系统（以下简称农用地环境信息系统），实行信息共享。 县级以上地方环境保护主管部门、农业主管部门应当按照国家有关规定，在本行政区域内组织建设和应用农用地环境信息系统，并加强农用地土壤环境信息统计工作，健全农用地土壤环境信息档案，定期上传农用地环境信息系统，实行信息共享。"},{"i":7,"n":"第七条","txt":"受委托从事农用地土壤污染防治相关活动的专业机构，以及受委托从事治理与修复效果评估的第三方机构，应当遵守有关环境保护标准和技术规范，并对其出具的技术文件的真实性、准确性、完整性负责。 受委托从事治理与修复的专业机构，应当遵守国家有关环境保护标准和技术规范，在合同约定范围内开展工作，对治理与修复活动及其效果负责。 受委托从事治理与修复的专业机构在治理与修复活动中弄虚作假，对造成的环境污染和生态破坏负有责任的，除依照有关法律法规接受处罚外，还应当依法与造成环境污染和生态破坏的其他责任者承担连带责任。"},{"i":8,"n":"第八条","txt":"排放污染物的企业事业单位和其他生产经营者应当采取有效措施，确保废水、废气排放和固体废物处理、处置符合国家有关规定要求，防止对周边农用地土壤造成污染。 从事固体废物和化学品储存、运输、处置的企业，应当采取措施防止固体废物和化学品的泄露、渗漏、遗撒、扬散污染农用地。"},{"i":9,"n":"第九条","txt":"县级以上地方环境保护主管部门应当加强对企业事业单位和其他生产经营者排污行为的监管，将土壤污染防治作为环境执法的重要内容。 设区的市级以上地方环境保护主管部门应当根据本行政区域内工矿企业分布和污染排放情况，确定土壤环境重点监管企业名单，上传农用地环境信息系统，实行动态更新，并向社会公布。"},{"i":10,"n":"第十条","txt":"从事规模化畜禽养殖和农产品加工的单位和个人，应当按照相关规范要求，确定废物无害化处理方式和消纳场地。 县级以上地方环境保护主管部门、农业主管部门应当依据法定职责加强畜禽养殖污染防治工作，指导畜禽养殖废弃物综合利用，防止畜禽养殖活动对农用地土壤环境造成污染。"},{"i":11,"n":"第十一条","txt":"县级以上地方农业主管部门应当加强农用地土壤污染防治知识宣传，提高农业生产者的农用地土壤环境保护意识，引导农业生产者合理使用肥料、农药、兽药、农用薄膜等农业投入品，根据科学的测土配方进行合理施肥，鼓励采取种养结合、轮作等良好农业生产措施。"},{"i":12,"n":"第十二条","txt":"禁止在农用地排放、倾倒、使用污泥、清淤底泥、尾矿（渣）等可能对土壤造成污染的固体废物。 农田灌溉用水应当符合相应的水质标准，防止污染土壤、地下水和农产品。禁止向农田灌溉渠道排放工业废水或者医疗污水。向农田灌溉渠道排放城镇污水以及未综合利用的畜禽养殖废水、农产品加工废水的，应当保证其下游最近的灌溉取水点的水质符合农田灌溉水质标准。"},{"i":13,"n":"第十三条","txt":"环境保护部会同农业部等部门建立农用地土壤污染状况定期调查制度，制定调查工作方案，每十年开展一次。"},{"i":14,"n":"第十四条","txt":"环境保护部会同农业部等部门建立全国土壤环境质量监测网络，统一规划农用地土壤环境质量国控监测点位，规定监测要求，并组织实施全国农用地土壤环境监测工作。 农用地土壤环境质量国控监测点位应当重点布设在粮食生产功能区、重要农产品生产保护区、特色农产品优势区以及污染风险较大的区域等。 县级以上地方环境保护主管部门会同农业等有关部门，可以根据工作需要，布设地方农用地土壤环境质量监测点位，增加特征污染物监测项目，提高监测频次，有关监测结果应当及时上传农用地环境信息系统。"},{"i":15,"n":"第十五条","txt":"县级以上农业主管部门应当根据不同区域的农产品质量安全情况，组织实施耕地土壤与农产品协同监测，开展风险评估，根据监测评估结果，优化调整安全利用措施，并将监测结果及时上传农用地环境信息系统。"},{"i":16,"n":"第十六条","txt":"省级农业主管部门会同环境保护主管部门，按照国家有关技术规范，根据土壤污染程度、农产品质量情况，组织开展耕地土壤环境质量类别划分工作，将耕地划分为优先保护类、安全利用类和严格管控类，划分结果报省级人民政府审定，并根据土地利用变更和土壤环境质量变化情况，定期对各类别农用地面积、分布等信息进行更新，数据上传至农用地环境信息系统。"},{"i":17,"n":"第十七条","txt":"县级以上地方农业主管部门应当根据永久基本农田划定工作要求，积极配合相关部门将符合条件的优先保护类耕地划为永久基本农田，纳入粮食生产功能区和重要农产品生产保护区建设，实行严格保护，确保其面积不减少，耕地污染程度不上升。在优先保护类耕地集中的地区，优先开展高标准农田建设。"},{"i":18,"n":"第十八条","txt":"严格控制在优先保护类耕地集中区域新建有色金属冶炼、石油加工、化工、焦化、电镀、制革等行业企业，有关环境保护主管部门依法不予审批可能造成耕地土壤污染的建设项目环境影响报告书或者报告表。优先保护类耕地集中区域现有可能造成土壤污染的相关行业企业应当按照有关规定采取措施，防止对耕地造成污染。"},{"i":19,"n":"第十九条","txt":"对安全利用类耕地，应当优先采取农艺调控、替代种植、轮作、间作等措施，阻断或者减少污染物和其他有毒有害物质进入农作物可食部分，降低农产品超标风险。 对严格管控类耕地，主要采取种植结构调整或者按照国家计划经批准后进行退耕还林还草等风险管控措施。 对需要采取治理与修复工程措施的安全利用类或者严格管控类耕地，应当优先采取不影响农业生产、不降低土壤生产功能的生物修复措施，或辅助采取物理、化学治理与修复措施。"},{"i":20,"n":"第二十条","txt":"县级以上地方农业主管部门应当根据农用地土壤安全利用相关技术规范要求，结合当地实际情况，组织制定农用地安全利用方案，报所在地人民政府批准后实施，并上传农用地环境信息系统。 农用地安全利用方案应当包括以下风险管控措施： （一）针对主要农作物种类、品种和农作制度等具体情况，推广低积累品种替代、水肥调控、土壤调理等农艺调控措施，降低农产品有害物质超标风险； （二）定期开展农产品质量安全监测和调查评估，实施跟踪监测，根据监测和评估结果及时优化调整农艺调控措施。"},{"i":21,"n":"第二十一条","txt":"对需要采取治理与修复工程措施的受污染耕地，县级以上地方农业主管部门应当组织制定土壤污染治理与修复方案，报所在地人民政府批准后实施，并上传农用地环境信息系统。"},{"i":22,"n":"第二十二条","txt":"从事农用地土壤污染治理与修复活动的单位和个人应当采取必要措施防止产生二次污染，并防止对被修复土壤和周边环境造成新的污染。治理与修复过程中产生的废水、废气和固体废物，应当按照国家有关规定进行处理或者处置，并达到国家或者地方规定的环境保护标准和要求。"},{"i":23,"n":"第二十三条","txt":"县级以上地方环境保护主管部门应当对农用地土壤污染治理与修复的环境保护措施落实情况进行监督检查。 治理与修复活动结束后，县级以上地方农业主管部门应当委托第三方机构对治理与修复效果进行评估，评估结果上传农用地环境信息系统。"},{"i":24,"n":"第二十四条","txt":"县级以上地方农业主管部门应当对严格管控类耕地采取以下风险管控措施： （一）依法提出划定特定农产品禁止生产区域的建议； （二）会同有关部门按照国家退耕还林还草计划，组织制定种植结构调整或者退耕还林还草计划，报所在地人民政府批准后组织实施，并上传农用地环境信息系统。"},{"i":25,"n":"第二十五条","txt":"对威胁地下水、饮用水水源安全的严格管控类耕地，县级环境保护主管部门应当会同农业等主管部门制定环境风险管控方案，报同级人民政府批准后组织实施，并上传农用地环境信息系统。"},{"i":26,"n":"第二十六条","txt":"设区的市级以上地方环境保护主管部门应当定期对土壤环境重点监管企业周边农用地开展监测，监测结果作为环境执法和风险预警的重要依据，并上传农用地环境信息系统。 设区的市级以上地方环境保护主管部门应当督促土壤环境重点监管企业自行或者委托专业机构开展土壤环境监测，监测结果向社会公开，并上传农用地环境信息系统。"},{"i":27,"n":"第二十七条","txt":"县级以上环境保护主管部门和县级以上农业主管部门，有权对本行政区域内的农用地土壤污染防治相关活动进行现场检查。被检查单位应当予以配合，如实反映情况，提供必要的资料。实施现场检查的部门、机构及其工作人员应当为被检查单位保守商业秘密。"},{"i":28,"n":"第二十八条","txt":"突发环境事件可能造成农用地土壤污染的，县级以上地方环境保护主管部门应当及时会同农业主管部门对可能受到污染的农用地土壤进行监测，并根据监测结果及时向当地人民政府提出应急处置建议。"},{"i":29,"n":"第二十九条","txt":"违反本办法规定，受委托的专业机构在从事农用地土壤污染防治相关活动中，不负责任或者弄虚作假的，由县级以上地方环境保护主管部门、农业主管部门将该机构失信情况记入其环境信用记录，并通过企业信用信息系统向社会公开。"},{"i":30,"n":"第三十条","txt":"本办法自2017年11月1日起施行。"}],"weixianfeiwuchukouhezhunguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范危险废物出口管理，防止环境污染，根据《控制危险废物越境转移及其处置巴塞尔公约》（以下简称《巴塞尔公约》）和有关法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内产生的危险废物应当尽量在境内进行无害化处置，减少出口量，降低危险废物出口转移的环境风险。 禁止向《巴塞尔公约》非缔约方出口危险废物。"},{"i":3,"n":"第三条","txt":"产生、收集、贮存、处置、利用危险废物的单位，向中华人民共和国境外《巴塞尔公约》缔约方出口危险废物，必须取得危险废物出口核准。 本办法所称危险废物，是指列入国家危险废物名录或者根据国家规定的危险废物鉴别标准和鉴别方法认定的具有危险特性的固体废物。 《巴塞尔公约》规定的“危险废物”和“其他废物”，以及进口缔约方或者过境缔约方立法确定的“危险废物”，其出口核准管理也适用本办法。"},{"i":4,"n":"第四条","txt":"国务院环境保护行政主管部门负责核准危险废物出口申请，并进行监督管理。 县级以上地方人民政府环境保护行政主管部门依据本办法的规定，对本行政区域内危险废物出口活动进行监督管理。"},{"i":5,"n":"第五条","txt":"申请出口危险废物，应当向国务院环境保护行政主管部门提交下列材料： （一）申请书。 （二）越境转移通知书（中、英文）。 （三）出口者与进口国（地区）的处置者或者利用者签订的书面协议。 （四）危险废物的基本情况数据表、物质安全技术说明书（MSDS）或者化学品安全技术说明书（CSDS）。 （五）危险废物产生情况的说明文件，主要包括危险废物的产生过程、地点、工艺和设备的说明。 （六）危险废物在进口国（地区）处置或者利用情况的说明文件，主要包括危险废物处置或者利用设施的地点、类型、处理能力以及处置或者利用中产生的废水、废气、废渣的处理方法等。 （七）处置者或者利用者在进口国（地区）获得的有关危险废物处置或者利用的授权或者许可的有效凭证。 （八）危险废物运输突发环境污染事件应急预案。 （九）危险废物运输的路线说明文件，主要包括境内运输路线（包括途经的省、市、县）、离境地点、过境国（地区）过境地点、"},{"i":6,"n":"第六条","txt":"国务院环境保护行政主管部门根据下列情况分别作出处理： （一）申请材料齐全、符合要求的，予以受理； （二）申请材料不齐全或者不符合要求的，应当当场或者在5个工作日内一次告知申请单位需要补正的全部内容。"},{"i":7,"n":"第七条","txt":"国务院环境保护行政主管部门对符合下列条件之一的，应当自受理之日起15个工作日内，作出初步核准出口决定： （一）进口国（地区）的利用者需要将该危险废物作为再循环或者回收工业的原材料，且有相应的技术能力、必要设施、设备和场所，能以环境无害化方式利用该危险废物； （二）中华人民共和国没有以环境无害化方式处置该危险废物所需的足够的技术能力和必要的设施、设备或者适当的处置场所，且进口国（地区）的处置者有相应的技术能力、必要设施、设备和场所，并能以环境无害化方式处置该危险废物。 国务院环境保护行政主管部门对不符合前款所列条件的，应当自受理之日起15个工作日内，作出不予核准出口决定，并书面通知申请单位。 国务院环境保护行政主管部门对受理的申请进行书面审查。需要现场核查的，应当指派两名以上工作人员进行核查。"},{"i":8,"n":"第八条","txt":"对已作出初步核准决定的危险废物出口申请，国务院环境保护行政主管部门应当向进口国（地区）和过境国（地区）主管部门发出书面征求意见的函，并自收到同意进口和同意过境的书面意见之日起5个工作日内，作出核准出口决定。 对进口国（地区）主管部门或者过境国（地区）主管部门不同意危险废物出口或者过境的，不予核准出口申请，并书面通知申请单位。"},{"i":9,"n":"第九条","txt":"国务院环境保护行政主管部门应当自作出核准决定之日起10个工作日内，向申请单位签发危险废物出口核准通知单。 国务院环境保护行政主管部门根据危险废物出口者提供的境内运输路线说明文件，将核准结果通知危险废物所在地和境内运输途经地区的省级人民政府环境保护行政主管部门。 省级人民政府环境保护行政主管部门应当将核准结果通知本行政区域内有关设区的市级和县级人民政府环境保护行政主管部门。"},{"i":10,"n":"第十条","txt":"有下列情形之一的，应当重新提出申请： （一）改变或者增加出口危险废物类别或者数量的； （二）改变出口者、进口国（地区）的处置者或者利用者的； （三）改变进口国（地区）、过境国（地区）的； （四）改变出口目的的； （五）改变出口时限的。"},{"i":11,"n":"第十一条","txt":"危险废物出口核准通知单的有效期限不超过1年。"},{"i":12,"n":"第十二条","txt":"危险废物出口者应当对每一批出口的危险废物，填写《危险废物越境转移—转移单据》，一式二份。 转移单据应当随出口的危险废物从转移起点直至处置或者利用地点，并由危险废物出口者、承运人和进口国（地区）的进口者、处置者或者利用者及有关国家（地区）海关部门填写相关信息。 危险废物出口者应当将信息填写完整的转移单据，一份报国务院环境保护行政主管部门，一份自留存档。 危险废物出口者应当妥善保存自留存档的转移单据，不得擅自损毁。转移单据的保存期应不少于5年。国务院环境保护行政主管部门要求延长转移单据保存期限的，有关单位应当按照要求延长转移单据的保存期限。"},{"i":13,"n":"第十三条","txt":"国务院环境保护行政主管部门有权检查转移单据的运行情况，也可以委托县级以上地方人民政府环境保护行政主管部门检查转移单据的运行情况。被检查单位应当接受检查，如实汇报情况。"},{"i":14,"n":"第十四条","txt":"在危险废物运输开始10个工作日之前，危险废物出口者应当填写《运输前信息报告单》，并将其连同填写的转移单据复印件，一并报送国务院环境保护行政主管部门，并抄送危险废物移出地和境内运输途经地区的省级、设区的市级和县级人民政府环境保护行政主管部门。"},{"i":15,"n":"第十五条","txt":"自危险废物离境之日起10个工作日内，危险废物出口者应当填写《离境信息报告单》，并将其连同危险废物出口者和相关承运人填写的转移单据复印件和危险废物出口报关单复印件，报送国务院环境保护行政主管部门。"},{"i":16,"n":"第十六条","txt":"自危险废物进口者接收危险废物之日起10个工作日内，危险废物出口者应当填写《抵达进口国（地区）信息报告单》，并将其连同危险废物出口者、相关承运人、危险废物进口者及过境国（地区）海关、进口国（地区）海关填写完毕的转移单据复印件，一并报送国务院环境保护行政主管部门。"},{"i":17,"n":"第十七条","txt":"自危险废物处置或者利用完毕之日起40个工作日内，危险废物出口者应当填写《处置或者利用完毕信息报告单》，并将其连同危险废物出口者、相关承运人、危险废物进口者、进口国（地区）的危险废物处置者或者利用者及过境国（地区）海关、进口国（地区）海关填写完毕的转移单据原件，一并报送国务院环境保护行政主管部门。"},{"i":18,"n":"第十八条","txt":"自危险废物出口核准通知单有效期届满之日起20个工作日内，危险废物出口者应当填写《危险废物出口总结信息报告单》，并报送国务院环境保护行政主管部门。"},{"i":19,"n":"第十九条","txt":"危险废物出口者应当将按照第十五条、第十六条、第十七条和第十八条的规定向国务院环境保护行政主管部门报送的有关材料，同时抄送危险废物移出地省级、设区的市级和县级人民政府环境保护行政主管部门。"},{"i":20,"n":"第二十条","txt":"禁止伪造、变造或者买卖危险废物出口核准通知单。"},{"i":21,"n":"第二十一条","txt":"违反本办法规定，无危险废物出口核准通知单或者不按照危险废物出口核准通知单出口危险废物的，由县级以上人民政府环境保护行政主管部门责令改正，并处3万元以下的罚款。 不按照危险废物出口核准通知单出口危险废物，情节严重的，还可以由国务院环境保护行政主管部门撤销危险废物出口核准通知单。"},{"i":22,"n":"第二十二条","txt":"违反本办法规定，申请危险废物出口核准的单位隐瞒有关情况或者提供虚假材料的，国务院环境保护行政主管部门不予受理其申请或者不予核准其申请，给予警告，并记载其不良记录。"},{"i":23,"n":"第二十三条","txt":"违反本办法规定，有下列行为之一的，由县级以上人民政府环境保护行政主管部门责令改正，并处以罚款： （一）未按规定填写转移单据的； （二）未按规定运行转移单据的； （三）未按规定的存档期限保管转移单据的； （四）拒绝接受环境保护行政主管部门对转移单据执行情况进行检查的。 有前款第（一）项、第（二）项、第（三）项行为的，处3万元以下罚款；有前款第（四）项行为的，依据《固体废物污染环境防治法》第七十条的规定，予以处罚。 有前款第（一）项、第（二）项、第（四）项行为，情节严重的，由国务院环境保护行政主管部门撤销危险废物出口核准通知单。"},{"i":24,"n":"第二十四条","txt":"违反本办法规定，未将有关信息报送国务院环境保护行政主管部门，或者未抄报有关地方人民政府环境保护行政主管部门的，由县级以上人民政府环境保护行政主管部门责令限期改正；逾期不改正的，由县级以上人民政府环境保护行政主管部门处3万元以下罚款，并记载危险废物出口者的不良记录。"},{"i":25,"n":"第二十五条","txt":"违反本办法规定，伪造、变造或者买卖危险废物出口核准通知单的，由公安机关依据《中华人民共和国治安管理处罚法》进行处罚。"},{"i":26,"n":"第二十六条","txt":"以欺骗、贿赂等不正当手段取得危险废物出口核准通知单的，依据《中华人民共和国行政许可法》的规定，由国务院环境保护行政主管部门撤销危险废物出口核准通知单，并处3万元以下罚款。"},{"i":27,"n":"第二十七条","txt":"危险废物出口未能按照书面协议的规定完成时，如果在进口国通知国务院环境保护行政主管部门和《巴塞尔公约》秘书处之后90日内或者在有关国家同意的另一期限内不能作出环境上无害的处置替代安排，出口者应当负责将废物退运回国，并承担该废物的运输与处置或者利用等相关费用。"},{"i":28,"n":"第二十八条","txt":"负责危险废物出口核准管理工作的人员玩忽职守、徇私舞弊或者滥用职权的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":29,"n":"第二十九条","txt":"从中华人民共和国台湾地区向其他《巴塞尔公约》缔约方出口危险废物的核准，参照本办法执行。"},{"i":30,"n":"第三十条","txt":"本办法自2008年3月1日起施行。"}],"weixianfeiwuzhuanyiguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对危险废物转移活动的监督管理，防止污染环境，根据《中华人民共和国固体废物污染环境防治法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国境内转移危险废物及其监督管理活动。 转移符合豁免要求的危险废物的，按照国家相关规定实行豁免管理。 在海洋转移危险废物的，不适用本办法。"},{"i":3,"n":"第三条","txt":"危险废物转移应当遵循就近原则。 跨省、自治区、直辖市转移（以下简称跨省转移）处置危险废物的，应当以转移至相邻或者开展区域合作的省、自治区、直辖市的危险废物处置设施，以及全国统筹布局的危险废物处置设施为主。"},{"i":4,"n":"第四条","txt":"生态环境主管部门依法对危险废物转移污染环境防治工作以及危险废物转移联单运行实施监督管理，查处危险废物污染环境违法行为。 各级交通运输主管部门依法查处危险废物运输违反危险货物运输管理相关规定的违法行为。 公安机关依法查处危险废物运输车辆的交通违法行为，打击涉危险废物污染环境犯罪行为。"},{"i":5,"n":"第五条","txt":"生态环境主管部门、交通运输主管部门和公安机关应当建立健全协作机制，共享危险废物转移联单信息、运输车辆行驶轨迹动态信息和运输车辆限制通行区域信息，加强联合监管执法。"},{"i":6,"n":"第六条","txt":"转移危险废物的，应当执行危险废物转移联单制度，法律法规另有规定的除外。 危险废物转移联单的格式和内容由生态环境部另行制定。"},{"i":7,"n":"第七条","txt":"转移危险废物的，应当通过国家危险废物信息管理系统（以下简称信息系统）填写、运行危险废物电子转移联单，并依照国家有关规定公开危险废物转移相关污染环境防治信息。 生态环境部负责建设、运行和维护信息系统。"},{"i":8,"n":"第八条","txt":"运输危险废物的，应当遵守国家有关危险货物运输管理的规定。未经公安机关批准，危险废物运输车辆不得进入危险货物运输车辆限制通行的区域。"},{"i":9,"n":"第九条","txt":"危险废物移出人、危险废物承运人、危险废物接受人（以下分别简称移出人、承运人和接受人）在危险废物转移过程中应当采取防扬散、防流失、防渗漏或者其他防止污染环境的措施，不得擅自倾倒、堆放、丢弃、遗撒危险废物，并对所造成的环境污染及生态破坏依法承担责任。 移出人、承运人、接受人应当依法制定突发环境事件的防范措施和应急预案，并报有关部门备案；发生危险废物突发环境事件时，应当立即采取有效措施消除或者减轻对环境的污染危害，并按相关规定向事故发生地有关部门报告，接受调查处理。"},{"i":10,"n":"第十条","txt":"移出人应当履行以下义务： （一）对承运人或者接受人的主体资格和技术能力进行核实，依法签订书面合同，并在合同中约定运输、贮存、利用、处置危险废物的污染防治要求及相关责任； （二）制定危险废物管理计划，明确拟转移危险废物的种类、重量（数量）和流向等信息； （三）建立危险废物管理台账，对转移的危险废物进行计量称重，如实记录、妥善保管转移危险废物的种类、重量（数量）和接受人等相关信息； （四）填写、运行危险废物转移联单，在危险废物转移联单中如实填写移出人、承运人、接受人信息，转移危险废物的种类、重量（数量）、危险特性等信息，以及突发环境事件的防范措施等； （五）及时核实接受人贮存、利用或者处置相关危险废物情况； （六）法律法规规定的其他义务。 移出人应当按照国家有关要求开展危险废物鉴别。禁止将危险废物以副产品等名义提供或者委托给无危险废物经营许可证的单位或者其他生产经营者从事收集、贮存、利用、"},{"i":11,"n":"第十一条","txt":"承运人应当履行以下义务： （一）核实危险废物转移联单，没有转移联单的，应当拒绝运输； （二）填写、运行危险废物转移联单，在危险废物转移联单中如实填写承运人名称、运输工具及其营运证件号，以及运输起点和终点等运输相关信息，并与危险货物运单一并随运输工具携带； （三）按照危险废物污染环境防治和危险货物运输相关规定运输危险废物，记录运输轨迹，防范危险废物丢失、包装破损、泄漏或者发生突发环境事件； （四）将运输的危险废物运抵接受人地址，交付给危险废物转移联单上指定的接受人，并将运输情况及时告知移出人； （五）法律法规规定的其他义务。"},{"i":12,"n":"第十二条","txt":"接受人应当履行以下义务： （一）核实拟接受的危险废物的种类、重量（数量）、包装、识别标志等相关信息； （二）填写、运行危险废物转移联单，在危险废物转移联单中如实填写是否接受的意见，以及利用、处置方式和接受量等信息； （三）按照国家和地方有关规定和标准，对接受的危险废物进行贮存、利用或者处置； （四）将危险废物接受情况、利用或者处置结果及时告知移出人； （五）法律法规规定的其他义务。"},{"i":13,"n":"第十三条","txt":"危险废物托运人（以下简称托运人）应当按照国家危险货物相关标准确定危险废物对应危险货物的类别、项别、编号等，并委托具备相应危险货物运输资质的单位承运危险废物，依法签订运输合同。 采用包装方式运输危险废物的，应当妥善包装，并按照国家有关标准在外包装上设置相应的识别标志。 装载危险废物时，托运人应当核实承运人、运输工具及收运人员是否具有相应经营范围的有效危险货物运输许可证件，以及待转移的危险废物识别标志中的相关信息与危险废物转移联单是否相符；不相符的，应当不予装载。装载采用包装方式运输的危险废物的，应当确保将包装完好的危险废物交付承运人。"},{"i":14,"n":"第十四条","txt":"危险废物转移联单应当根据危险废物管理计划中填报的危险废物转移等备案信息填写、运行。"},{"i":15,"n":"第十五条","txt":"危险废物转移联单实行全国统一编号，编号由十四位阿拉伯数字组成。第一至四位数字为年份代码；第五、六位数字为移出地省级行政区划代码；第七、八位数字为移出地设区的市级行政区划代码；其余六位数字以移出地设区的市级行政区域为单位进行流水编号。"},{"i":16,"n":"第十六条","txt":"移出人每转移一车（船或者其他运输工具）次同类危险废物，应当填写、运行一份危险废物转移联单；每车（船或者其他运输工具）次转移多类危险废物的，可以填写、运行一份危险废物转移联单，也可以每一类危险废物填写、运行一份危险废物转移联单。 使用同一车（船或者其他运输工具）一次为多个移出人转移危险废物的，每个移出人应当分别填写、运行危险废物转移联单。"},{"i":17,"n":"第十七条","txt":"采用联运方式转移危险废物的，前一承运人和后一承运人应当明确运输交接的时间和地点。后一承运人应当核实危险废物转移联单确定的移出人信息、前一承运人信息及危险废物相关信息。"},{"i":18,"n":"第十八条","txt":"接受人应当对运抵的危险废物进行核实验收，并在接受之日起五个工作日内通过信息系统确认接受。 运抵的危险废物的名称、数量、特性、形态、包装方式与危险废物转移联单填写内容不符的，接受人应当及时告知移出人，视情况决定是否接受，同时向接受地生态环境主管部门报告。"},{"i":19,"n":"第十九条","txt":"对不通过车（船或者其他运输工具），且无法按次对危险废物计量的其他方式转移危险废物的，移出人和接受人应当分别配备计量记录设备，将每天危险废物转移的种类、重量（数量）、形态和危险特性等信息纳入相关台账记录，并根据所在地设区的市级以上地方生态环境主管部门的要求填写、运行危险废物转移联单。"},{"i":20,"n":"第二十条","txt":"危险废物电子转移联单数据应当在信息系统中至少保存十年。 因特殊原因无法运行危险废物电子转移联单的，可以先使用纸质转移联单，并于转移活动完成后十个工作日内在信息系统中补录电子转移联单。"},{"i":21,"n":"第二十一条","txt":"跨省转移危险废物的，应当向危险废物移出地省级生态环境主管部门提出申请。移出地省级生态环境主管部门应当商经接受地省级生态环境主管部门同意后，批准转移该危险废物。未经批准的，不得转移。 鼓励开展区域合作的移出地和接受地省级生态环境主管部门按照合作协议简化跨省转移危险废物审批程序。"},{"i":22,"n":"第二十二条","txt":"申请跨省转移危险废物的，移出人应当填写危险废物跨省转移申请表，并提交下列材料： （一）接受人的危险废物经营许可证复印件； （二）接受人提供的贮存、利用或者处置危险废物方式的说明； （三）移出人与接受人签订的委托协议、意向或者合同； （四）危险废物移出地的地方性法规规定的其他材料。 移出人应当在危险废物跨省转移申请表中提出拟开展危险废物转移活动的时间期限。 省级生态环境主管部门应当向社会公开办理危险废物跨省转移需要的申请材料。 危险废物跨省转移申请表的格式和内容，由生态环境部另行制定。"},{"i":23,"n":"第二十三条","txt":"对于申请材料齐全、符合要求的，受理申请的省级生态环境主管部门应当立即予以受理；申请材料存在可以当场更正的错误的，应当允许申请人当场更正；申请材料不齐全或者不符合要求的，应当当场或者在五个工作日内一次性告知移出人需要补正的全部内容，逾期不告知的，自收到申请材料之日起即为受理。"},{"i":24,"n":"第二十四条","txt":"危险废物移出地省级生态环境主管部门应当自受理申请之日起五个工作日内，根据移出人提交的申请材料和危险废物管理计划等信息，提出初步审核意见。初步审核同意移出的，通过信息系统向危险废物接受地省级生态环境主管部门发出跨省转移商请函；不同意移出的，书面答复移出人，并说明理由。"},{"i":25,"n":"第二十五条","txt":"危险废物接受地省级生态环境主管部门应当自收到移出地省级生态环境主管部门的商请函之日起十个工作日内，出具是否同意接受的意见，并通过信息系统函复移出地省级生态环境主管部门；不同意接受的，应当说明理由。"},{"i":26,"n":"第二十六条","txt":"危险废物移出地省级生态环境主管部门应当自收到接受地省级生态环境主管部门复函之日起五个工作日内作出是否批准转移该危险废物的决定；不同意转移的，应当说明理由。危险废物移出地省级生态环境主管部门应当将批准信息通报移出地省级交通运输主管部门和移入地等相关省级生态环境主管部门和交通运输主管部门。"},{"i":27,"n":"第二十七条","txt":"批准跨省转移危险废物的决定，应当包括批准转移危险废物的名称，类别，废物代码，重量（数量），移出人，接受人，贮存、利用或者处置方式等信息。 批准跨省转移危险废物的决定的有效期为十二个月，但不得超过移出人申请开展危险废物转移活动的时间期限和接受人危险废物经营许可证的剩余有效期限。 跨省转移危险废物的申请经批准后，移出人应当按照批准跨省转移危险废物的决定填写、运行危险废物转移联单，实施危险废物转移活动。移出人可以按照批准跨省转移危险废物的决定在有效期内多次转移危险废物。"},{"i":28,"n":"第二十八条","txt":"发生下列情形之一的，移出人应当重新提出危险废物跨省转移申请： （一）计划转移的危险废物的种类发生变化或者重量（数量）超过原批准重量（数量）的； （二）计划转移的危险废物的贮存、利用、处置方式发生变化的； （三）接受人发生变更或者接受人不再具备拟接受危险废物的贮存、利用或者处置条件的。"},{"i":29,"n":"第二十九条","txt":"违反本办法规定，未填写、运行危险废物转移联单，将危险废物以副产品等名义提供或者委托给无危险废物经营许可证的单位或者其他生产经营者从事收集、贮存、利用、处置活动，或者未经批准擅自跨省转移危险废物的，由生态环境主管部门和公安机关依照《中华人民共和国固体废物污染环境防治法》有关规定进行处罚。 违反危险货物运输管理相关规定运输危险废物的，由交通运输主管部门、公安机关和生态环境主管部门依法进行处罚。 违反本办法规定，未规范填写、运行危险废物转移联单，及时改正，且没有造成危害后果的，依法不予行政处罚；主动消除或者减轻危害后果的，生态环境主管部门可以依法从轻或者减轻行政处罚。"},{"i":30,"n":"第三十条","txt":"违反本办法规定，构成违反治安管理行为的，由公安机关依法进行处罚；构成犯罪的，依法追究刑事责任。 生态环境主管部门、交通运输主管部门在监督检查时，发现涉嫌犯罪的案件，应当按照行政执法和刑事司法相衔接相关规定及时移送公安机关。"},{"i":31,"n":"第三十一条","txt":"本办法下列用语的含义： （一）转移，是指以贮存、利用或者处置危险废物为目的，将危险废物从移出人的场所移出，交付承运人并移入接受人场所的活动。 （二）移出人，是指危险废物转移的起始单位，包括危险废物产生单位、危险废物收集单位等。 （三）承运人，是指承担危险废物运输作业任务的单位。 （四）接受人，是指危险废物转移的目的地单位，即危险货物的收货人。 （五）托运人，是指委托承运人运输危险废物的单位，只能由移出人或者接受人担任。"},{"i":32,"n":"第三十二条","txt":"本办法自2022年1月1日起施行。《危险废物转移联单管理办法》（原国家环境保护总局令第5号）同时废止。"}],"gudingwuranyuanpaiwuxukefenleiguanliminglu":[{"i":1,"n":"第一条","txt":"为实施排污许可分类管理，根据《中华人民共和国环境保护法》等有关法律法规和《国务院办公厅关于印发控制污染物排放许可制实施方案的通知》的相关规定，制定本名录。"},{"i":2,"n":"第二条","txt":"国家根据排放污染物的企业事业单位和其他生产经营者（以下简称排污单位）污染物产生量、排放量、对环境的影响程度等因素，实行排污许可重点管理、简化管理和登记管理。 对污染物产生量、排放量或者对环境的影响程度较大的排污单位，实行排污许可重点管理；对污染物产生量、排放量和对环境的影响程度较小的排污单位，实行排污许可简化管理。对污染物产生量、排放量和对环境的影响程度很小的排污单位，实行排污登记管理。 实行登记管理的排污单位，不需要申请取得排污许可证，应当在全国排污许可证管理信息平台填报排污登记表，登记基本信息、污染物排放去向、执行的污染物排放标准以及采取的污染防治措施等信息。"},{"i":3,"n":"第三条","txt":"本名录依据《国民经济行业分类》（GB/T 4754-2017）划分行业类别。"},{"i":4,"n":"第四条","txt":"现有排污单位应当在生态环境部规定的实施时限内申请取得排污许可证或者填报排污登记表。新建排污单位应当在启动生产设施或者发生实际排污之前申请取得排污许可证或者填报排污登记表。"},{"i":5,"n":"第五条","txt":"同一排污单位在同一场所从事本名录中两个以上行业生产经营的，申请一张排污许可证。"},{"i":6,"n":"第六条","txt":"属于本名录第1至107类行业的排污单位，按照本名录第109至112类规定的锅炉、工业炉窑、表面处理、水处理等通用工序实施重点管理或者简化管理的，只需对其涉及的通用工序申请取得排污许可证，不需要对其他生产设施和相应的排放口等申请取得排污许可证。"},{"i":7,"n":"第七条","txt":"属于本名录第108类行业的排污单位，涉及本名录规定的通用工序重点管理、简化管理或者登记管理的，应当对其涉及的本名录第109至112类规定的锅炉、工业炉窑、表面处理、水处理等通用工序申请领取排污许可证或者填报排污登记表；有下列情形之一的，还应当对其生产设施和相应的排放口等申请取得重点管理排污许可证： （一）被列入重点排污单位名录的； （二）二氧化硫或者氮氧化物年排放量大于250吨的； （三）烟粉尘年排放量大于500吨的； （四）化学需氧量年排放量大于30吨，或者总氮年排放量大于10吨，或者总磷年排放量大于0.5吨的； （五）氨氮、石油类和挥发酚合计年排放量大于30吨的； （六）其他单项有毒有害大气、水污染物污染当量数大于3000的。污染当量数按照《中华人民共和国环境保护税法》的规定计算。"},{"i":8,"n":"第八条","txt":"本名录未作规定的排污单位，确需纳入排污许可管理的，其排污许可管理类别由省级生态环境主管部门提出建议，报生态环境部确定。"},{"i":9,"n":"第九条","txt":"本名录由生态环境部负责解释，并适时修订。"},{"i":10,"n":"第十条","txt":"本名录自发布之日起施行。《固定污染源排污许可分类管理名录（2017年版）》同时废止。 序号 行业类别 重点管理 简化管理 登记管理 一、畜牧业03 1 牲畜饲养031，家禽饲养032 设有污水排放口的规模化畜禽养殖场、养殖小区（具体规模化标准按《畜禽规模养殖污染防治条例》执行） / 无污水排放口的规模化畜禽养殖场、养殖小区，设有污水排放口的规模以下畜禽养殖场、养殖小区 2 其他畜牧业039 / / 设有污水排放口的养殖场、养殖小区 二、煤炭开采和洗选业06 3 烟煤和无烟煤开采洗选061，褐煤开采洗选062，其他煤炭洗选069 涉及通用工序重点管理的 涉及通用工序简化管理的 其他 三、石油和天然气开采业07 4 石油开采071，天然气开采072 涉及通用工序重点管理的 涉及通用工序简化管理的 其他 四、黑色金属矿采选业08 5 铁矿采选081，锰矿、铬矿采选082，其他黑色金属矿采选0"}],"guojiaweixianfeiwuminglu-2":[{"i":1,"n":"第一条","txt":""},{"i":2,"n":"第二条","txt":""},{"i":3,"n":"第三条","txt":""},{"i":4,"n":"第四条","txt":""},{"i":5,"n":"第五条","txt":""},{"i":6,"n":"第六条","txt":""},{"i":7,"n":"第七条","txt":""},{"i":8,"n":"第八条","txt":""}],"guojiaweixianfeiwuminglu":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国固体废物污染环境防治法》的有关规定，制定本名录。"},{"i":2,"n":"第二条","txt":"具有下列情形之一的固体废物（包括液态废物），列入本名录： （一）具有毒性、腐蚀性、易燃性、反应性或者感染性一种或者几种危险特性的； （二）不排除具有危险特性，可能对生态环境或者人体健康造成有害影响，需要按照危险废物进行管理的。"},{"i":3,"n":"第三条","txt":"列入本名录附录《危险废物豁免管理清单》中的危险废物，在所列的豁免环节，且满足相应的豁免条件时，可以按照豁免内容的规定实行豁免管理。"},{"i":4,"n":"第四条","txt":"危险废物与其他物质混合后的固体废物，以及危险废物利用处置后的固体废物的属性判定，按照国家规定的危险废物鉴别标准执行。"},{"i":5,"n":"第五条","txt":"本名录中有关术语的含义如下： （一）废物类别，是在《控制危险废物越境转移及其处置巴塞尔公约》划定的类别基础上，结合我国实际情况对危险废物进行的分类。 （二）行业来源，是指危险废物的产生行业。 （三）废物代码，是指危险废物的唯一代码，为8位数字。其中，第1-3位为危险废物产生行业代码（依据《国民经济行业分类（GB/T 4754-2017）》确定），第4-6位为危险废物顺序代码，第7-8位为危险废物类别代码。 （四）危险特性，是指对生态环境和人体健康具有有害影响的毒性（Toxicity, T）、腐蚀性（Corrosivity, C）、易燃性（Ignitability, I）、反应性（Reactivity, R）和感染性（Infectivity, In）。"},{"i":6,"n":"第六条","txt":"对不明确是否具有危险特性的固体废物，应当按照国家规定的危险废物鉴别标准和鉴别方法予以认定。 经鉴别具有危险特性的，属于危险废物，应当根据其主要有害成分和危险特性对照本名录中已有废物代码进行归类；无法按已有废物代码归类的，应当确定其所属废物类别，按代码“900-000-××”（××为危险废物类别代码）进行归类管理。 经鉴别不具有危险特性的，不属于危险废物。"},{"i":7,"n":"第七条","txt":"本名录根据实际情况实行动态调整。"},{"i":8,"n":"第八条","txt":"本名录自2025年1月1日起施行。《国家危险废物名录（2021年版）》（生态环境部、国家发展和改革委员会、公安部、交通运输部、国家卫生健康委员会令第15号）同时废止。 附件：国家危险废物名录（2025年版）附表.pdf"}],"guojiajiziranbaohuqujiandujianchabanfa":[{"i":1,"n":"第一条","txt":"为加强对国家级自然保护区的监督管理，提高国家级自然保护区的建设和管理水平，根据《中华人民共和国环境保护法》、《中华人民共和国自然保护区条例》以及其他有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于国务院环境保护行政主管部门组织的对全国各类国家级自然保护区的监督检查。"},{"i":3,"n":"第三条","txt":"国务院环境保护行政主管部门在依照法律法规和本办法的规定履行监督检查职责时，有权采取下列措施： （一）进入国家级自然保护区进行实地检查； （二）要求国家级自然保护区管理机构汇报建设和管理情况； （三）查阅或者复制有关资料、凭证； （四）向有关单位和人员调查了解相关情况； （五）法律、法规规定有权采取的其他措施。 监督检查人员在履行监督检查职责时，应当严格遵守国家有关法律法规规定的程序，出示证件，并为被检查单位保守技术和业务秘密。"},{"i":4,"n":"第四条","txt":"有关单位或者人员对依法进行的监督检查应当给予支持与配合，如实反映情况，提供有关资料，不得拒绝或者妨碍监督检查工作。"},{"i":5,"n":"第五条","txt":"任何单位和个人都有权对污染或者破坏国家级自然保护区的单位、个人以及不履行或者不依法履行国家级自然保护区监督管理职责的机构进行检举或者控告。"},{"i":6,"n":"第六条","txt":"国务院环境保护行政主管部门应当向社会公开国家级自然保护区监督检查的有关情况，接受社会监督。"},{"i":7,"n":"第七条","txt":"国务院环境保护行政主管部门组织对国家级自然保护区的建设和管理状况进行定期评估。 国务院环境保护行政主管部门组织成立国家级自然保护区评估委员会，对国家级自然保护区的建设和管理状况进行定期评估，并根据评估结果提出整改建议。 对每个国家级自然保护区的建设和管理状况的定期评估，每五年不少于一次。"},{"i":8,"n":"第八条","txt":"国家级自然保护区定期评估的内容应当包括： （一）管护设施状况； （二）面积和功能分区适宜性、范围、界线和土地权属； （三）管理规章、规划的制定及其实施情况； （四）资源本底、保护及利用情况； （五）科研、监测、档案和标本情况； （六）自然保护区内建设项目管理情况； （七）旅游和其他人类活动情况； （八）与周边社区的关系状况； （九）宣传教育、培训、交流与合作情况； （十）管理经费情况； （十一）其他应当评估的内容。 国家级自然保护区定期评估标准由国务院环境保护行政主管部门另行制定。"},{"i":9,"n":"第九条","txt":"国务院环境保护行政主管部门组织国家级自然保护区定期评估时，应当在评估开始20个工作日前通知拟被评估的国家级自然保护区管理机构及其行政主管部门。"},{"i":10,"n":"第十条","txt":"国家级自然保护区评估结果分为优、良、中和差四个等级。 国务院环境保护行政主管部门应当及时将评估结果和整改建议向被评估的国家级自然保护区管理机构反馈，并抄送该自然保护区行政主管部门及所在地省级人民政府。 被评估的国家级自然保护区管理机构对评估结果有异议的，可以向国务院环境保护行政主管部门申请复核；国务院环境保护行政主管部门应当及时进行审查核实。"},{"i":11,"n":"第十一条","txt":"国家级自然保护区定期评估结果由国务院环境保护行政主管部门统一发布。"},{"i":12,"n":"第十二条","txt":"国务院环境保护行政主管部门对国家级自然保护区进行执法检查。 执法检查分为定期检查、专项检查、抽查和专案调查等。"},{"i":13,"n":"第十三条","txt":"国家级自然保护区执法检查的内容应当包括： （一）国家级自然保护区的设立、范围和功能区的调整以及名称的更改是否符合有关规定； （二）国家级自然保护区内是否存在违法砍伐、放牧、狩猎、捕捞、采药、开垦、烧荒、开矿、采石、挖沙、影视拍摄以及其他法律法规禁止的活动； （三）国家级自然保护区内是否存在违法的建设项目，排污单位的污染物排放是否符合环境保护法律、法规及自然保护区管理的有关规定，超标排污单位限期治理的情况； （四）涉及国家级自然保护区且其环境影响评价文件依法由地方环境保护行政主管部门审批的建设项目在审批前，其环境影响评价文件中的生态影响专题报告是否征得省级环境保护行政主管部门的同意； （五）国家级自然保护区内是否存在破坏、侵占、非法转让自然保护区的土地或者其他自然资源的行为； （六）在国家级自然保护区的实验区开展参观、旅游活动的，自然保护区管理机构是否编制方案，编制的方案是否符合自然保护"},{"i":14,"n":"第十四条","txt":"对在定期评估或者执法检查中发现的违反国家级自然保护区建设和管理规定的国家级自然保护区管理机构，除依照本办法第十九条的规定处理外，国务院环境保护行政主管部门应当责令限期整改，并可酌情予以通报。 对于整改不合格且保护对象受到严重破坏，不再符合国家级自然保护区条件的国家级自然保护区，国务院环境保护行政主管部门应当向国家级自然保护区评审委员会提出对该国家级自然保护区予以降级的建议，经评审通过并报国务院批准后，给予降级处理。"},{"i":15,"n":"第十五条","txt":"因有关行政机关或者国家级自然保护区管理机构滥用职权、玩忽职守、徇私舞弊，导致该国家级自然保护区被降级的，对其直接负责的主管人员和其他直接责任人员，国务院环境保护行政主管部门可以向其上级机关或者有关监察机关提出行政处分建议。"},{"i":16,"n":"第十六条","txt":"被降级的国家级自然保护区，五年之内不得再次申报设立国家级自然保护区。"},{"i":17,"n":"第十七条","txt":"国务院环境保护行政主管部门应当及时向社会公布对国家级自然保护区执法检查的结果、被责令整改的国家级自然保护区名单及其整改情况和被降级的国家级自然保护区名单。"},{"i":18,"n":"第十八条","txt":"县级以上地方人民政府及其有关行政主管部门，违反有关规定，有下列行为之一的，对直接负责的主管人员和其他直接责任人员，国务院环境保护行政主管部门可以向其上级机关或者有关监察机关提出行政处分建议： （一）未经批准，擅自撤销国家级自然保护区或者擅自调整、改变国家级自然保护区的范围、界限、功能区划的； （二）违法批准在国家级自然保护区内建设污染或者破坏生态环境的项目的； （三）违法批准在国家级自然保护区内开展旅游或者开采矿产资源的； （四）对本辖区内发生的违反环境保护法律法规中有关国家级自然保护区管理规定的行为，不予制止或者不予查处的； （五）制定或者采取与环境保护法律法规中有关国家级自然保护区管理规定相抵触的规定或者措施，经指出仍不改正的； （六）干预或者限制环境保护行政主管部门依法对国家级自然保护区实施监督检查的； （七）其他违反国家级自然保护区管理规定的行为。"},{"i":19,"n":"第十九条","txt":"国家级自然保护区管理机构违反有关规定，有下列行为之一的，国务院环境保护行政主管部门应当责令限期改正；对直接负责的主管人员和其他直接责任人员，可以向设立该管理机构的自然保护区行政主管部门或者有关监察机关提出行政处分建议： （一）擅自调整、改变自然保护区的范围、界限和功能区划的； （二）开展参观、旅游活动未编制方案或者编制的方案不符合自然保护区管理目标的； （三）开设与自然保护区保护方向不一致的参观、旅游项目的； （四）不按照编制的方案开展参观、旅游活动的； （五）对国家级自然保护区内发生的违反环境保护法律法规中有关国家级自然保护区管理规定的行为，不予制止或者不予查处的； （六）阻挠或者妨碍监督检查人员依法履行职责的； （七）挪用、滥用国家级自然保护区建设和管理经费的； （八）对监督检查人员、检举和控告人员进行打击报复的； （九）其他不依法履行自然保护区建设和管理职责的行为。"},{"i":20,"n":"第二十条","txt":"国家级自然保护区管理机构拒绝国务院环境保护行政主管部门对国家级自然保护区的监督检查，或者在监督检查中弄虚作假的，由国务院环境保护行政主管部门依照《自然保护区条例》的有关规定给予处罚。"},{"i":21,"n":"第二十一条","txt":"省级人民政府环境保护行政主管部门对本行政区域内地方级自然保护区的监督检查，可以参照本办法执行。 县级以上地方人民政府环境保护行政主管部门对本行政区域内的国家级自然保护区的执法检查内容，可以参照本办法执行；在执法检查中发现国家级自然保护区管理机构有违反国家级自然保护区建设和管理规定行为的，可以将有关情况逐级上报国务院环境保护行政主管部门，由国务院环境保护行政主管部门经核实后依照本办法的有关规定处理。"},{"i":22,"n":"第二十二条","txt":"本办法自2006年12月1日起施行。"}],"weikuangwuranhuanjingfangzhiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了防治尾矿污染环境，保护和改善生态环境，根据《中华人民共和国环境保护法》《中华人民共和国固体废物污染环境防治法》《中华人民共和国土壤污染防治法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内尾矿的污染环境防治（以下简称污染防治）及其监督管理。 伴生放射性矿开发利用活动中产生的铀（钍）系单个核素活度浓度超过1Bq/g 的尾矿，以及铀（钍）矿尾矿的污染防治及其监督管理，适用放射性污染防治有关法律法规的规定，不适用本办法。"},{"i":3,"n":"第三条","txt":"尾矿污染防治坚持预防为主、污染担责的原则。 产生、贮存、运输、综合利用尾矿的单位，以及尾矿库运营、管理单位，应当采取措施，防止或者减少尾矿对环境的污染，对所造成的环境污染依法承担责任。 对产生尾矿的单位和尾矿库运营、管理单位实施控股管理的企业集团，应当加强对其下属企业的监督管理，督促、指导其履行尾矿污染防治主体责任。"},{"i":4,"n":"第四条","txt":"国务院生态环境主管部门对全国尾矿污染防治工作实施监督管理。 地方各级生态环境主管部门负责本行政区域尾矿污染防治工作的监督管理。 国务院生态环境主管部门所属的流域生态环境监督管理机构依据法律法规规定的职责或者国务院生态环境主管部门的委托，对管辖范围内的尾矿污染防治工作进行指导、协调和监督。"},{"i":5,"n":"第五条","txt":"尾矿库污染防治实行分类分级环境监督管理。 国务院生态环境主管部门负责制定尾矿库分类分级环境监督管理技术规程，根据尾矿所属矿种类型、尾矿库周边环境敏感程度、尾矿库环境保护水平等因素，将尾矿库分为一级、二级和三级环境监督管理尾矿库，并明确不同等级的尾矿库环境监督管理要求。 省级生态环境主管部门负责确定本行政区域尾矿库分类分级环境监督管理清单，并加强监督管理。 设区的市级生态环境主管部门根据省级生态环境主管部门确定的尾矿库分类分级环境监督管理清单，对尾矿库进行分类分级管理。"},{"i":6,"n":"第六条","txt":"产生尾矿的单位应当建立健全尾矿产生、贮存、运输、综合利用等全过程的污染防治责任制度，确定承担污染防治工作的部门和专职技术人员，明确单位负责人和相关人员的责任。"},{"i":7,"n":"第七条","txt":"产生尾矿的单位和尾矿库运营、管理单位应当建立尾矿环境管理台账。 产生尾矿的单位应当在尾矿环境管理台账中如实记录生产运营中产生尾矿的种类、数量、流向、贮存、综合利用等信息；尾矿库运营、管理单位应当在尾矿环境管理台账中如实记录尾矿库的污染防治设施建设和运行情况、环境监测情况、污染隐患排查治理情况、突发环境事件应急预案及其落实情况等信息。 尾矿环境管理台账保存期限不得少于五年，其中尾矿库运营、管理单位的环境管理台账信息应当永久保存。 产生尾矿的单位和尾矿库运营、管理单位应当于每年1月31日之前通过全国固体废物污染环境防治信息平台填报上一年度产生的相关信息。"},{"i":8,"n":"第八条","txt":"产生尾矿的单位委托他人贮存、运输、综合利用尾矿，或者尾矿库运营、管理单位委托他人运输、综合利用尾矿的，应当对受托方的主体资格和技术能力进行核实，依法签订书面合同，在合同中约定污染防治要求。"},{"i":9,"n":"第九条","txt":"新建、改建、扩建尾矿库的，应当依法进行环境影响评价，并遵守国家有关建设项目环境保护管理的规定，落实尾矿污染防治的措施。 尾矿库选址，应当符合生态环境保护有关法律法规和强制性标准要求。禁止在生态保护红线区域、永久基本农田集中区域、河道湖泊行洪区和其他需要特别保护的区域内建设尾矿库以及其他贮存尾矿的场所。"},{"i":10,"n":"第十条","txt":"新建、改建、扩建尾矿库的，应当根据国家有关规定和尾矿库实际情况，配套建设防渗、渗滤液收集、废水处理、环境监测、环境应急等污染防治设施。"},{"i":11,"n":"第十一条","txt":"尾矿库防渗设施的设计和建设，应当充分考虑地质、水文等条件，并符合相应尾矿属性类别管理要求。 尾矿库配套的渗滤液收集池、回水池、环境应急事故池等设施的防渗要求应当不低于该尾矿库的防渗要求，并设置防漫流设施。"},{"i":12,"n":"第十二条","txt":"新建尾矿库的排尾管道、回水管道应当避免穿越农田、河流、湖泊；确需穿越的，应当建设管沟、套管等设施，防止渗漏造成环境污染。"},{"i":13,"n":"第十三条","txt":"采用传送带方式输送尾矿的，应当采取封闭等措施，防止尾矿流失和扬散。 通过车辆运输尾矿的，应当采取遮盖等措施，防止尾矿遗撒和扬散。"},{"i":14,"n":"第十四条","txt":"依法实行排污许可管理的产生尾矿的单位，应当申请取得排污许可证或者填报排污登记表，按照排污许可管理的规定排放尾矿及污染物，并落实相关环境管理要求。"},{"i":15,"n":"第十五条","txt":"尾矿库运营、管理单位应当采取防扬散、防流失、防渗漏或者其他防止污染环境的措施，加强对尾矿库污染防治设施的管理和维护，保证其正常运行和使用，防止尾矿污染环境。"},{"i":16,"n":"第十六条","txt":"尾矿库运营、管理单位应当采取库面抑尘、边坡绿化等措施防止扬尘污染，美化环境。"},{"i":17,"n":"第十七条","txt":"尾矿水应当优先返回选矿工艺使用；向环境排放的，应当符合国家和地方污染物排放标准，不得与尾矿库外的雨水混合排放，并按照有关规定设置污染物排放口，设立标志，依法安装流量计和视频监控。 污染物排放口的流量计监测记录保存期限不得少于五年，视频监控记录保存期限不得少于三个月。"},{"i":18,"n":"第十八条","txt":"尾矿库运营、管理单位应当按照国家有关标准和规范，建设地下水水质监测井。 尾矿库上游、下游和可能出现污染扩散的尾矿库周边区域，应当设置地下水水质监测井。"},{"i":19,"n":"第十九条","txt":"尾矿库运营、管理单位应当按照国家有关规定开展地下水环境监测以及土壤污染状况监测和评估。 排放尾矿水的，尾矿库运营、管理单位应当在排放期间，每月至少开展一次水污染物排放监测；排放有毒有害水污染物的，还应当每季度对受纳水体等周边环境至少开展一次监测。 尾矿库运营、管理单位应当依法公开污染物排放监测结果等相关信息。"},{"i":20,"n":"第二十条","txt":"尾矿库运营、管理单位应当建立健全尾矿库污染隐患排查治理制度，组织开展尾矿库污染隐患排查治理；发现污染隐患的，应当制定整改方案，及时采取措施消除隐患。 尾矿库运营、管理单位应当于每年汛期前至少开展一次全面的污染隐患排查。"},{"i":21,"n":"第二十一条","txt":"尾矿库运营、管理单位在环境监测等活动中发现尾矿库周边土壤和地下水存在污染物渗漏或者含量升高等污染迹象的，应当及时查明原因，采取措施及时阻止污染物泄漏，并按照国家有关规定开展环境调查与风险评估，根据调查与风险评估结果采取风险管控或者治理修复等措施。 生态环境主管部门在监督检查中发现尾矿库周边土壤和地下水存在污染物渗漏或者含量升高等污染迹象的，应当及时督促尾矿库运营、管理单位采取相应措施。"},{"i":22,"n":"第二十二条","txt":"尾矿库运营、管理单位应当按照国务院生态环境主管部门有关规定，开展尾矿库突发环境事件风险评估，编制、修订、备案尾矿库突发环境事件应急预案，建设并完善环境风险防控与应急设施，储备环境应急物资，定期组织开展尾矿库突发环境事件应急演练。"},{"i":23,"n":"第二十三条","txt":"发生突发环境事件时，尾矿库运营、管理单位应当立即启动尾矿库突发环境事件应急预案，采取应急措施，消除或者减轻事故影响，及时通报可能受到危害的单位和居民，并向本行政区域县级生态环境主管部门报告。 县级以上生态环境主管部门在发现或者得知尾矿库突发环境事件信息后，应当按照有关规定做好应急处置、环境影响和损失调查、评估等工作。"},{"i":24,"n":"第二十四条","txt":"尾矿库运营、管理单位应当在尾矿库封场期间及封场后，采取措施保证渗滤液收集设施、尾矿水排放监测设施继续正常运行，并定期开展水污染物排放监测，确保污染物排放符合国家和地方排放标准。 尾矿库的渗滤液收集设施、尾矿水排放监测设施应当正常运行至尾矿库封场后连续两年内没有渗滤液产生或者产生的渗滤液不经处理即可稳定达标排放。 尾矿库运营、管理单位应当在尾矿库封场后，采取措施保证地下水水质监测井继续正常运行，并按照国家有关规定持续进行地下水水质监测，直到下游地下水水质连续两年不超出上游地下水水质或者所在区域地下水水质本底水平。"},{"i":25,"n":"第二十五条","txt":"开展尾矿充填、回填以及利用尾矿提取有价组分和生产建筑材料等尾矿综合利用单位，应当按照国家有关规定采取相应措施，防止造成二次环境污染。"},{"i":26,"n":"第二十六条","txt":"国务院生态环境主管部门应当加强尾矿污染防治工作信息化建设，强化环境管理信息系统对接与数据共享。"},{"i":27,"n":"第二十七条","txt":"省级生态环境主管部门应当加强对新建、改建、扩建尾矿库建设项目环境影响评价审批程序、审批结果的监督与评估；发现设区的市、县级生态环境主管部门不具备尾矿库建设项目环境影响评价审批能力，或者在审批过程中存在突出问题的，应当依法调整上收环境影响评价审批权限。"},{"i":28,"n":"第二十八条","txt":"设区的市级生态环境主管部门应当将一级和二级环境监督管理尾矿库的运营、管理单位列入重点排污单位名录，实施重点管控。"},{"i":29,"n":"第二十九条","txt":"鼓励地方各级生态环境主管部门综合利用远程视频监控、无人机、遥感、地理信息系统等手段进行尾矿污染防治监督管理。"},{"i":30,"n":"第三十条","txt":"产生尾矿的单位或者尾矿库运营、管理单位违反本办法规定，有下列行为之一的，依照《中华人民共和国固体废物污染环境防治法》《中华人民共和国水污染防治法》《中华人民共和国土壤污染防治法》等法律法规的规定予以处罚： （一）未建立尾矿环境管理台账并如实记录的； （二）超过水污染物排放标准排放水污染物的； （三）未依法报批建设项目环境影响评价文件，擅自开工建设的； （四）未按规定开展土壤和地下水环境监测的； （五）未依法开展尾矿库突发环境事件应急处置的； （六）擅自倾倒、堆放、丢弃、遗撒尾矿，或者未采取相应防范措施，造成尾矿扬散、流失、渗漏或者其他环境污染的； （七）其他违反法律法规规定的行为。"},{"i":31,"n":"第三十一条","txt":"产生尾矿的单位或者尾矿库运营、管理单位违反本办法规定，未按时通过全国固体废物污染环境防治信息平台填报上一年度产生的相关信息的，由设区的市级以上地方生态环境主管部门责令改正，给予警告；拒不改正的，处三万元以下的罚款。"},{"i":32,"n":"第三十二条","txt":"违反本办法规定，向环境排放尾矿水，未按照国家有关规定设置污染物排放口标志的，由设区的市级以上地方生态环境主管部门责令改正，给予警告；拒不改正的，处五万元以下的罚款。"},{"i":33,"n":"第三十三条","txt":"尾矿库运营、管理单位违反本办法规定，未按要求组织开展污染隐患排查治理的，由设区的市级以上生态环境主管部门责令改正，给予警告；拒不改正的，处十万元以下的罚款。"},{"i":34,"n":"第三十四条","txt":"本办法中下列用语的含义： （一）尾矿，是指金属非金属矿山开采出的矿石，经选矿厂选出有价值的精矿后产生的固体废物。 （二）尾矿库，是指用以贮存尾矿的场所。 （三）封场，是指尾矿库停止使用后，对尾矿库采取关闭的措施，也称闭库。 （四）尾矿库运营、管理单位，包括尾矿库所属企业和地方人民政府指定的尾矿库管理维护单位。"},{"i":35,"n":"第三十五条","txt":"本办法自2022年7月1日起施行。《防治尾矿污染环境管理规定》（国家环境保护局令第11号）同时废止。"}],"gongkuangyongdituranghuanjingguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强工矿用地土壤和地下水环境保护监督管理，防治工矿用地土壤和地下水污染，根据《中华人民共和国环境保护法》《中华人民共和国水污染防治法》等法律法规和国务院印发的《土壤污染防治行动计划》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于从事工业、矿业生产经营活动的土壤环境污染重点监管单位用地土壤和地下水的环境现状调查、环境影响评价、污染防治设施的建设和运行管理、污染隐患排查、环境监测和风险评估、污染应急、风险管控和治理与修复等活动，以及相关环境保护监督管理。 矿产开采作业区域用地，固体废物集中贮存、填埋场所用地，不适用本办法。"},{"i":3,"n":"第三条","txt":"土壤环境污染重点监管单位（以下简称重点单位）包括： （一）有色金属冶炼、石油加工、化工、焦化、电镀、制革等行业中应当纳入排污许可重点管理的企业； （二）有色金属矿采选、石油开采行业规模以上企业； （三）其他根据有关规定纳入土壤环境污染重点监管单位名录的企事业单位。 重点单位以外的企事业单位和其他生产经营者生产经营活动涉及有毒有害物质的，其用地土壤和地下水环境保护相关活动及相关环境保护监督管理，可以参照本办法执行。"},{"i":4,"n":"第四条","txt":"生态环境部对全国工矿用地土壤和地下水环境保护工作实施统一监督管理。 县级以上地方生态环境主管部门负责本行政区域内的工矿用地土壤和地下水环境保护相关活动的监督管理。"},{"i":5,"n":"第五条","txt":"设区的市级以上地方生态环境主管部门应当制定公布本行政区域的土壤环境污染重点监管单位名单，并动态更新。"},{"i":6,"n":"第六条","txt":"工矿企业是工矿用地土壤和地下水环境保护的责任主体，应当按照本办法的规定开展相关活动。 造成工矿用地土壤和地下水污染的企业应当承担治理与修复的主体责任。"},{"i":7,"n":"第七条","txt":"重点单位新、改、扩建项目，应当在开展建设项目环境影响评价时，按照国家有关技术规范开展工矿用地土壤和地下水环境现状调查，编制调查报告，并按规定上报环境影响评价基础数据库。 重点单位应当将前款规定的调查报告主要内容通过其网站等便于公众知晓的方式向社会公开。"},{"i":8,"n":"第八条","txt":"重点单位新、改、扩建项目用地应当符合国家或者地方有关建设用地土壤污染风险管控标准。 重点单位通过新、改、扩建项目的土壤和地下水环境现状调查，发现项目用地污染物含量超过国家或者地方有关建设用地土壤污染风险管控标准的，土地使用权人或者污染责任人应当参照污染地块土壤环境管理有关规定开展详细调查、风险评估、风险管控、治理与修复等活动。"},{"i":9,"n":"第九条","txt":"重点单位建设涉及有毒有害物质的生产装置、储罐和管道，或者建设污水处理池、应急池等存在土壤污染风险的设施，应当按照国家有关标准和规范的要求，设计、建设和安装有关防腐蚀、防泄漏设施和泄漏监测装置，防止有毒有害物质污染土壤和地下水。"},{"i":10,"n":"第十条","txt":"重点单位现有地下储罐储存有毒有害物质的，应当在本办法公布后一年之内，将地下储罐的信息报所在地设区的市级生态环境主管部门备案。 重点单位新、改、扩建项目地下储罐储存有毒有害物质的，应当在项目投入生产或者使用之前，将地下储罐的信息报所在地设区的市级生态环境主管部门备案。 地下储罐的信息包括地下储罐的使用年限、类型、规格、位置和使用情况等。"},{"i":11,"n":"第十一条","txt":"重点单位应当建立土壤和地下水污染隐患排查治理制度，定期对重点区域、重点设施开展隐患排查。发现污染隐患的，应当制定整改方案，及时采取技术、管理措施消除隐患。隐患排查、治理情况应当如实记录并建立档案。 重点区域包括涉及有毒有害物质的生产区，原材料及固体废物的堆存区、储放区和转运区等；重点设施包括涉及有毒有害物质的地下储罐、地下管线，以及污染治理设施等。"},{"i":12,"n":"第十二条","txt":"重点单位应当按照相关技术规范要求，自行或者委托第三方定期开展土壤和地下水监测，重点监测存在污染隐患的区域和设施周边的土壤、地下水，并按照规定公开相关信息。"},{"i":13,"n":"第十三条","txt":"重点单位在隐患排查、监测等活动中发现工矿用地土壤和地下水存在污染迹象的，应当排查污染源，查明污染原因，采取措施防止新增污染，并参照污染地块土壤环境管理有关规定及时开展土壤和地下水环境调查与风险评估，根据调查与风险评估结果采取风险管控或者治理与修复等措施。"},{"i":14,"n":"第十四条","txt":"重点单位拆除涉及有毒有害物质的生产设施设备、构筑物和污染治理设施的，应当按照有关规定，事先制定企业拆除活动污染防治方案，并在拆除活动前十五个工作日报所在地县级生态环境、工业和信息化主管部门备案。 企业拆除活动污染防治方案应当包括被拆除生产设施设备、构筑物和污染治理设施的基本情况、拆除活动全过程土壤污染防治的技术要求、针对周边环境的污染防治要求等内容。 重点单位拆除活动应当严格按照有关规定实施残留物料和污染物、污染设备和设施的安全处理处置，并做好拆除活动相关记录，防范拆除活动污染土壤和地下水。拆除活动相关记录应当长期保存。"},{"i":15,"n":"第十五条","txt":"重点单位突发环境事件应急预案应当包括防止土壤和地下水污染相关内容。 重点单位突发环境事件造成或者可能造成土壤和地下水污染的，应当采取应急措施避免或者减少土壤和地下水污染；应急处置结束后，应当立即组织开展环境影响和损害评估工作，评估认为需要开展治理与修复的，应当制定并落实污染土壤和地下水治理与修复方案。"},{"i":16,"n":"第十六条","txt":"重点单位终止生产经营活动前，应当参照污染地块土壤环境管理有关规定，开展土壤和地下水环境初步调查，编制调查报告，及时上传全国污染地块土壤环境管理信息系统。 重点单位应当将前款规定的调查报告主要内容通过其网站等便于公众知晓的方式向社会公开。 土壤和地下水环境初步调查发现该重点单位用地污染物含量超过国家或者地方有关建设用地土壤污染风险管控标准的，应当参照污染地块土壤环境管理有关规定开展详细调查、风险评估、风险管控、治理与修复等活动。"},{"i":17,"n":"第十七条","txt":"县级以上生态环境主管部门有权对本行政区域内的重点单位进行现场检查。被检查单位应当予以配合，如实反映情况，提供必要的资料。实施现场检查的部门、机构及其工作人员应当为被检查单位保守商业秘密。"},{"i":18,"n":"第十八条","txt":"县级以上生态环境主管部门对重点单位进行监督检查时，有权采取下列措施： （一）进入被检查单位进行现场核查或者监测； （二）查阅、复制相关文件、记录以及其他有关资料； （三）要求被检查单位提交有关情况说明。"},{"i":19,"n":"第十九条","txt":"重点单位未按本办法开展工矿用地土壤和地下水环境保护相关活动或者弄虚作假的，由县级以上生态环境主管部门将该企业失信情况记入其环境信用记录，并通过全国信用信息共享平台、国家企业信用信息公示系统向社会公开。"},{"i":20,"n":"第二十条","txt":"本办法所称的下列用语的含义： （一）矿产开采作业区域用地，指露天采矿区用地、排土场等与矿业开采作业直接相关的用地。 （二）有毒有害物质，是指下列物质： 1.列入《中华人民共和国水污染防治法》规定的有毒有害水污染物名录的污染物； 2.列入《中华人民共和国大气污染防治法》规定的有毒有害大气污染物名录的污染物； 3.《中华人民共和国固体废物污染环境防治法》规定的危险废物； 4.国家和地方建设用地土壤污染风险管控标准管控的污染物； 5.列入优先控制化学品名录内的物质； 6.其他根据国家法律法规有关规定应当纳入有毒有害物质管理的物质。 （三）土壤和地下水环境现状调查，指对重点单位新、改、扩建项目用地的土壤和地下水环境质量进行的调查评估，其主要调查内容包括土壤和地下水中主要污染物的含量等。 （四）土壤和地下水污染隐患，指相关设施设备因设计、建设、运行管理等不完善，而导致相关有毒有害物质泄漏、渗漏、"},{"i":21,"n":"第二十一条","txt":"本办法自2018年8月1日起施行。"}],"feiqidianqidianzichanpinchulizigexukeguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范废弃电器电子产品处理资格许可工作，防止废弃电器电子产品处理污染环境，根据《中华人民共和国行政许可法》、《中华人民共和国固体废物污染环境防治法》、《废弃电器电子产品回收处理管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于废弃电器电子产品处理资格的申请、审批及相关监督管理活动。 本办法所称“废弃电器电子产品”，是指列入国家发展和改革委员会、环境保护部、工业和信息化部发布的《废弃电器电子产品处理目录》的产品。"},{"i":3,"n":"第三条","txt":"国家对废弃电器电子产品实行集中处理制度，鼓励废弃电器电子产品处理的规模化、产业化、专业化发展。 省级人民政府环境保护主管部门应当会同同级人民政府相关部门编制本地区废弃电器电子产品处理发展规划，报环境保护部备案。 编制废弃电器电子产品处理发展规划应当依照集中处理的要求，合理布局废弃电器电子产品处理企业。 废弃电器电子产品处理发展规划应当根据本地区经济社会发展、产业结构、处理企业变化等有关情况，每五年修订一次。"},{"i":4,"n":"第四条","txt":"处理废弃电器电子产品，应当符合国家有关资源综合利用、环境保护、劳动安全和保障人体健康的要求。 禁止采用国家明令淘汰的技术和工艺处理废弃电器电子产品。"},{"i":5,"n":"第五条","txt":"设区的市级人民政府环境保护主管部门依照本办法的规定，负责废弃电器电子产品处理资格的许可工作。"},{"i":6,"n":"第六条","txt":"县级以上人民政府环境保护主管部门依照《废弃电器电子产品回收处理管理条例》和本办法的有关规定，负责废弃电器电子产品处理的监督管理工作。"},{"i":7,"n":"第七条","txt":"申请废弃电器电子产品处理资格的企业应当依法成立，符合本地区废弃电器电子产品处理发展规划的要求，具有增值税一般纳税人企业法人资格，并具备下列条件： （一）具备与其申请处理能力相适应的废弃电器电子产品处理车间和场地、贮存场所、拆解处理设备及配套的数据信息管理系统、污染防治设施等； （二）具有与所处理的废弃电器电子产品相适应的分拣、包装设备以及运输车辆、搬运设备、压缩打包设备、专用容器及中央监控设备、计量设备、事故应急救援和处理设备等； （三）具有健全的环境管理制度和措施，包括对不能完全处理的废弃电器电子产品的妥善利用或者处置方案，突发环境事件的防范措施和应急预案等； （四）具有相关安全、质量和环境保护的专业技术人员。"},{"i":8,"n":"第八条","txt":"申请废弃电器电子产品处理资格的企业，应当向废弃电器电子产品处理设施所在地设区的市级人民政府环境保护主管部门提交书面申请，并提供相关证明材料。"},{"i":9,"n":"第九条","txt":"设区的市级人民政府环境保护主管部门应当自受理申请之日起3个工作日内对申请的有关信息进行公示，征求公众意见。公示期限不得少于10个工作日。 对公众意见，受理申请的环境保护主管部门应当进行核实。"},{"i":10,"n":"第十条","txt":"设区的市级人民政府环境保护主管部门应当自受理申请之日起60日内，对企业提交的材料进行审查，并组织进行现场核查。对符合条件的，颁发废弃电器电子产品处理资格证书，并予以公告；不符合条件的，书面通知申请企业并说明理由。"},{"i":11,"n":"第十一条","txt":"废弃电器电子产品处理资格证书包括下列主要内容： （一）法人名称、法定代表人、住所； （二）处理设施地址； （三）处理的废弃电器电子产品类别； （四）主要处理设施、设备及运行参数； （五）处理能力； （六）有效期限； （七）颁发日期和证书编号。 废弃电器电子产品处理资格证书格式，由环境保护部统一规定。"},{"i":12,"n":"第十二条","txt":"废弃电器电子产品处理企业变更法人名称、法定代表人或者住所的，应当自工商变更登记之日起15个工作日内，向原发证机关申请办理废弃电器电子产品处理资格变更手续。"},{"i":13,"n":"第十三条","txt":"有下列情形之一的，废弃电器电子产品处理企业应当按照原申请程序，重新申请废弃电器电子产品处理资格： （一）增加废弃电器电子产品处理类别的； （二）新建处理设施的； （三）改建、扩建原有处理设施的； （四）处理废弃电器电子产品超过资格证书确定的处理能力20%以上的。"},{"i":14,"n":"第十四条","txt":"废弃电器电子产品处理发展规划修订后，原发证机关应当根据本地区经济社会发展、废弃电器电子产品处理市场变化等有关情况，对拟继续从事废弃电器电子产品处理活动的企业进行审查，符合条件的，换发废弃电器电子产品处理资格证书。"},{"i":15,"n":"第十五条","txt":"废弃电器电子产品处理企业拟终止处理活动的，应当对经营设施、场所采取污染防治措施，对未处置的废弃电器电子产品作出妥善处理，并在采取上述措施之日起20日内向原发证机关提出注销申请，由原发证机关进行现场核查合格后注销其废弃电器电子产品处理资格。 终止废弃电器电子产品处理活动的企业，应当对其经营设施、场所进行环境调查与风险评估；经评估需要治理修复的，应当依法承担治理修复责任。"},{"i":16,"n":"第十六条","txt":"禁止无废弃电器电子产品处理资格证书或者不按照废弃电器电子产品处理资格证书的规定处理废弃电器电子产品。 禁止将废弃电器电子产品提供或者委托给无废弃电器电子产品处理资格证书的单位和个人从事处理活动。 禁止伪造、变造、转让废弃电器电子产品处理资格证书。"},{"i":17,"n":"第十七条","txt":"设区的市级人民政府环境保护主管部门应当于每年3月31日前将上一年度废弃电器电子产品处理资格证书颁发情况报省级人民政府环境保护主管部门备案。 省级以上人民政府环境保护主管部门应当加强对设区的市级人民政府环境保护主管部门审批、颁发废弃电器电子产品处理资格证书情况的监督检查，及时纠正违法行为。"},{"i":18,"n":"第十八条","txt":"县级以上地方人民政府环境保护主管部门应当通过书面核查和实地检查等方式，加强对废弃电器电子产品处理活动的监督检查，并将监督检查情况和处理结果予以记录，由监督检查人员签字后归档。 公众可以依法向县级以上地方人民政府环境保护主管部门申请公开监督检查的处理结果。"},{"i":19,"n":"第十九条","txt":"废弃电器电子产品处理企业应当制定年度监测计划，对污染物排放进行日常监测。监测报告应当保存3年以上。 县级以上地方人民政府环境保护主管部门应当加强对废弃电器电子产品处理企业污染物排放情况的监督性监测。监督性监测每半年不得少于1次。"},{"i":20,"n":"第二十条","txt":"废弃电器电子产品处理企业应当建立数据信息管理系统，定期向发证机关报送废弃电器电子产品处理的基本数据和有关情况，并向社会公布。有关要求由环境保护部另行制定。"},{"i":21,"n":"第二十一条","txt":"废弃电器电子产品处理企业有下列行为之一的，由县级以上地方人民政府环境保护主管部门责令停止违法行为，限期改正，处3万元以下罚款；逾期未改正的，由发证机关收回废弃电器电子产品处理资格证书： （一）不按照废弃电器电子产品处理资格证书的规定处理废弃电器电子产品的； （二）未按规定办理废弃电器电子产品处理资格变更、换证、注销手续的。"},{"i":22,"n":"第二十二条","txt":"废弃电器电子产品处理企业有下列行为之一的，除按照有关法律法规进行处罚外，由发证机关收回废弃电器电子产品处理资格证书： （一）擅自关闭、闲置、拆除或者不正常使用污染防治设施、场所的，经县级以上人民政府环境保护主管部门责令限期改正，逾期未改正的； （二）造成较大以上级别的突发环境事件的。"},{"i":23,"n":"第二十三条","txt":"废弃电器电子产品处理企业将废弃电器电子产品提供或者委托给无废弃电器电子产品处理资格证书的单位和个人从事处理活动的，由县级以上地方人民政府环境保护主管部门责令停止违法行为，限期改正，处3万元以下罚款；情节严重的，由发证机关收回废弃电器电子产品处理资格证书。"},{"i":24,"n":"第二十四条","txt":"伪造、变造废弃电器电子产品处理资格证书的，由县级以上地方人民政府环境保护主管部门收缴伪造、变造的处理资格证书，处3万元以下罚款；构成违反治安管理行为的，移送公安机关依法予以治安管理处罚；构成犯罪的，移送司法机关依法追究其刑事责任。 倒卖、出租、出借或者以其他形式非法转让废弃电器电子产品处理资格证书的，由县级以上地方人民政府环境保护主管部门责令停止违法行为，限期改正，处3万元以下罚款；情节严重的，由发证机关收回废弃电器电子产品处理资格证书；构成犯罪的，移送司法机关依法追究其刑事责任。"},{"i":25,"n":"第二十五条","txt":"违反本办法的其他规定，按照《中华人民共和国固体废物污染环境防治法》、《废弃电器电子产品回收处理管理条例》以及其他相关法律法规的规定进行处罚。"},{"i":26,"n":"第二十六条","txt":"本办法施行前已经从事废弃电器电子产品处理活动的企业，应当于本办法施行之日起60日内，向废弃电器电子产品处理设施所在地设区的市级人民政府环境保护主管部门提交废弃电器电子产品处理资格申请；逾期不申请的，不得继续从事废弃电器电子产品处理活动。"},{"i":27,"n":"第二十七条","txt":"本办法自2011年1月1日起施行。"}],"jianshexiangmuhuanjingyingxianghoupingjiaguanlibanae575d":[{"i":1,"n":"第一条","txt":"为规范建设项目环境影响后评价工作，根据《中华人民共和国环境影响评价法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称环境影响后评价，是指编制环境影响报告书的建设项目在通过环境保护设施竣工验收且稳定运行一定时期后，对其实际产生的环境影响以及污染防治、生态保护和风险防范措施的有效性进行跟踪监测和验证评价，并提出补救方案或者改进措施，提高环境影响评价有效性的方法与制度。"},{"i":3,"n":"第三条","txt":"下列建设项目运行过程中产生不符合经审批的环境影响报告书情形的，应当开展环境影响后评价： （一）水利、水电、采掘、港口、铁路行业中实际环境影响程度和范围较大，且主要环境影响在项目建成运行一定时期后逐步显现的建设项目，以及其他行业中穿越重要生态环境敏感区的建设项目； （二）冶金、石化和化工行业中有重大环境风险，建设地点敏感，且持续排放重金属或者持久性有机污染物的建设项目； （三）审批环境影响报告书的环境保护主管部门认为应当开展环境影响后评价的其他建设项目。"},{"i":4,"n":"第四条","txt":"环境影响后评价应当遵循科学、客观、公正的原则，全面反映建设项目的实际环境影响，客观评估各项环境保护措施的实施效果。"},{"i":5,"n":"第五条","txt":"建设项目环境影响后评价的管理，由审批该建设项目环境影响报告书的环境保护主管部门负责。 环境保护部组织制定环境影响后评价技术规范，指导跨行政区域、跨流域和重大敏感项目的环境影响后评价工作。"},{"i":6,"n":"第六条","txt":"建设单位或者生产经营单位负责组织开展环境影响后评价工作，编制环境影响后评价文件，并对环境影响后评价结论负责。 建设单位或者生产经营单位可以委托环境影响评价机构、工程设计单位、大专院校和相关评估机构等编制环境影响后评价文件。编制建设项目环境影响报告书的环境影响评价机构，原则上不得承担该建设项目环境影响后评价文件的编制工作。 建设单位或者生产经营单位应当将环境影响后评价文件报原审批环境影响报告书的环境保护主管部门备案，并接受环境保护主管部门的监督检查。"},{"i":7,"n":"第七条","txt":"建设项目环境影响后评价文件应当包括以下内容： （一）建设项目过程回顾。包括环境影响评价、环境保护措施落实、环境保护设施竣工验收、环境监测情况，以及公众意见收集调查情况等； （二）建设项目工程评价。包括项目地点、规模、生产工艺或者运行调度方式，环境污染或者生态影响的来源、影响方式、程度和范围等； （三）区域环境变化评价。包括建设项目周围区域环境敏感目标变化、污染源或者其他影响源变化、环境质量现状和变化趋势分析等； （四）环境保护措施有效性评估。包括环境影响报告书规定的污染防治、生态保护和风险防范措施是否适用、有效，能否达到国家或者地方相关法律、法规、标准的要求等； （五）环境影响预测验证。包括主要环境要素的预测影响与实际影响差异，原环境影响报告书内容和结论有无重大漏项或者明显错误，持久性、累积性和不确定性环境影响的表现等； （六）环境保护补救方案和改进措施； （七）环境影响后评价结论。"},{"i":8,"n":"第八条","txt":"建设项目环境影响后评价应当在建设项目正式投入生产或者运营后三至五年内开展。原审批环境影响报告书的环境保护主管部门也可以根据建设项目的环境影响和环境要素变化特征，确定开展环境影响后评价的时限。"},{"i":9,"n":"第九条","txt":"建设单位或者生产经营单位可以对单个建设项目进行环境影响后评价，也可以对在同一行政区域、流域内存在叠加、累积环境影响的多个建设项目开展环境影响后评价。"},{"i":10,"n":"第十条","txt":"建设单位或者生产经营单位完成环境影响后评价后，应当依法公开环境影响评价文件，接受社会监督。"},{"i":11,"n":"第十一条","txt":"对未按规定要求开展环境影响后评价，或者不落实补救方案、改进措施的建设单位或者生产经营单位，审批该建设项目环境影响报告书的环境保护主管部门应当责令其限期改正，并向社会公开。"},{"i":12,"n":"第十二条","txt":"环境保护主管部门可以依据环境影响后评价文件，对建设项目环境保护提出改进要求，并将其作为后续建设项目环境影响评价管理的依据。"},{"i":13,"n":"第十三条","txt":"建设项目环境影响报告书经批准后，其性质、规模、地点、工艺或者环境保护措施发生重大变动的，依照《中华人民共和国环境影响评价法》第二十四条的规定执行，不适用本办法。"},{"i":14,"n":"第十四条","txt":"本办法由环境保护部负责解释。"},{"i":15,"n":"第十五条","txt":"本办法自2016年1月1日起施行。"}],"jianshexiangmuhuanjingyingxiangbaogaoshubianzhijiadb663e":[{"i":1,"n":"第一条","txt":"为规范建设项目环境影响报告书和环境影响报告表（以下简称环境影响报告书（表））编制行为,加强监督管理，保障环境影响评价工作质量，维护环境影响评价技术服务市场秩序，根据《中华人民共和国环境影响评价法》《建设项目环境保护管理条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"建设单位可以委托技术单位对其建设项目开展环境影响评价，编制环境影响报告书（表）；建设单位具备环境影响评价技术能力的，可以自行对其建设项目开展环境影响评价，编制环境影响报告书（表）。 技术单位不得与负责审批环境影响报告书（表）的生态环境主管部门或者其他有关审批部门存在任何利益关系。任何单位和个人不得为建设单位指定编制环境影响报告书（表）的技术单位。 本办法所称技术单位，是指具备环境影响评价技术能力、接受委托为建设单位编制环境影响报告书（表）的单位。"},{"i":3,"n":"第三条","txt":"建设单位应当对环境影响报告书（表）的内容和结论负责；技术单位对其编制的环境影响报告书（表）承担相应责任。"},{"i":4,"n":"第四条","txt":"编制单位应当加强环境影响评价技术能力建设，提高专业技术水平。环境影响报告书（表）编制能力建设指南由生态环境部另行制定。 鼓励建设单位优先选择信用良好和符合能力建设指南要求的技术单位为其编制环境影响报告书（表）。 本办法所称编制单位，是指主持编制环境影响报告书（表）的单位，包括主持编制环境影响报告书（表）的技术单位和自行主持编制环境影响报告书（表）的建设单位。"},{"i":5,"n":"第五条","txt":"编制人员应当具备专业技术知识，不断提高业务能力。 本办法所称编制人员，是指环境影响报告书（表）的编制主持人和主要编制人员。编制主持人是环境影响报告书（表）的编制负责人。主要编制人员包括环境影响报告书各章节的编写人员和环境影响报告表主要内容的编写人员。"},{"i":6,"n":"第六条","txt":"设区的市级以上生态环境主管部门（以下简称市级以上生态环境主管部门）应当加强对编制单位的监督管理和质量考核，开展环境影响报告书（表）编制行为监督检查和编制质量问题查处，并对编制单位和编制人员实施信用管理。"},{"i":7,"n":"第七条","txt":"生态环境部负责建设全国统一的环境影响评价信用平台（以下简称信用平台），组织建立编制单位和编制人员诚信档案管理体系。信用平台纳入全国生态环境领域信用信息平台统一管理。 编制单位和编制人员的基础信息等相关信息应当通过信用平台公开。具体办法由生态环境部另行制定。"},{"i":8,"n":"第八条","txt":"编制单位和编制人员应当坚持公正、科学、诚信的原则，遵守有关环境影响评价法律法规、标准和技术规范等规定，确保环境影响报告书（表）内容真实、客观、全面和规范。"},{"i":9,"n":"第九条","txt":"编制单位应当是能够依法独立承担法律责任的单位。 前款规定的单位中，下列单位不得作为技术单位编制环境影响报告书（表）： （一）生态环境主管部门或者其他负责审批环境影响报告书（表）的审批部门设立的事业单位； （二）由生态环境主管部门作为业务主管单位或者挂靠单位的社会组织，或者由其他负责审批环境影响报告书（表）的审批部门作为业务主管单位或者挂靠单位的社会组织； （三）由本款前两项中的事业单位、社会组织出资的单位及其再出资的单位; （四）受生态环境主管部门或者其他负责审批环境影响报告书（表）的审批部门委托，开展环境影响报告书（表）技术评估的单位； （五）本款第四项中的技术评估单位出资的单位及其再出资的单位； （六）本款第四项中的技术评估单位的出资单位，或者由本款第四项中的技术评估单位出资人出资的其他单位，或者由本款第四项中的技术评估单位法定代表人出资的单位。 个体工商户、农村承包经营户以及本条"},{"i":10,"n":"第十条","txt":"编制单位应当具备环境影响评价技术能力。环境影响报告书（表）的编制主持人和主要编制人员应当为编制单位中的全职人员，环境影响报告书（表）的编制主持人还应当为取得环境影响评价工程师职业资格证书的人员。"},{"i":11,"n":"第十一条","txt":"编制单位和编制人员应当通过信用平台提交本单位和本人的基本情况信息。 生态环境部在信用平台建立编制单位和编制人员的诚信档案，并生成编制人员信用编号，公开编制单位名称、统一社会信用代码等基础信息以及编制人员姓名、从业单位等基础信息。 编制单位和编制人员应当对提交信息的真实性、准确性和完整性负责。相关信息发生变化的，应当自发生变化之日起二十个工作日内在信用平台变更。"},{"i":12,"n":"第十二条","txt":"环境影响报告书（表）应当由一个单位主持编制，并由该单位中的一名编制人员作为编制主持人。 建设单位委托技术单位编制环境影响报告书（表）的，应当与主持编制的技术单位签订委托合同，约定双方的权利、义务和费用。"},{"i":13,"n":"第十三条","txt":"编制单位应当建立和实施覆盖环境影响评价全过程的质量控制制度，落实环境影响评价工作程序，并在现场踏勘、现状监测、数据资料收集、环境影响预测等环节以及环境影响报告书（表）编制审核阶段形成可追溯的质量管理机制。有其他单位参与编制或者协作的，编制单位应当对参与编制单位或者协作单位提供的技术报告、数据资料等进行审核。 编制主持人应当全过程组织参与环境影响报告书（表）编制工作，并加强统筹协调。 委托技术单位编制环境影响报告书（表）的建设单位，应当如实提供相关基础资料，落实环境保护投入和资金来源，加强环境影响评价过程管理，并对环境影响报告书（表）的内容和结论进行审核。"},{"i":14,"n":"第十四条","txt":"除涉及国家秘密的建设项目外，编制单位和编制人员应当在建设单位报批环境影响报告书（表）前，通过信用平台提交编制完成的环境影响报告书（表）基本情况信息，并对提交信息的真实性、准确性和完整性负责。信用平台生成项目编号，并公开环境影响报告书（表）相关建设项目名称、类别以及建设单位、编制单位和编制人员等基础信息。 报批的环境影响报告书（表）应当附具编制单位和编制人员情况表（格式附后）。建设单位、编制单位和相关人员应当在情况表相应位置盖章或者签字。除涉及国家秘密的建设项目外，编制单位和编制人员情况表应当由信用平台导出。"},{"i":15,"n":"第十五条","txt":"建设单位应当将环境影响报告书（表）及其审批文件存档。 编制单位应当建立环境影响报告书（表）编制工作完整档案。档案中应当包括项目基础资料、现场踏勘记录和影像资料、质量控制记录、环境影响报告书（表）以及其他相关资料。开展环境质量现状监测和调查、环境影响预测或者科学试验的，还应当将相关监测报告和数据资料、预测过程文件或者试验报告等一并存档。 建设单位委托技术单位主持编制环境影响报告书（表）的，建设单位和受委托的技术单位应当分别将委托合同存档。 存档材料应当为原件。"},{"i":16,"n":"第十六条","txt":"环境影响报告书（表）编制行为监督检查包括编制规范性检查、编制质量检查以及编制单位和编制人员情况检查。"},{"i":17,"n":"第十七条","txt":"环境影响报告书（表）编制规范性检查包括下列内容： （一）编制单位和编制人员是否符合本办法第九条和第十条的规定，以及是否列入本办法规定的限期整改名单或者本办法规定的环境影响评价失信“黑名单”（以下简称“黑名单”）; （二）编制单位和编制人员是否按照本办法第十一条和第十四条第一款的规定在信用平台提交相关信息； （三）环境影响报告书（表）是否符合本办法第十二条第一款和第十四条第二款的规定。"},{"i":18,"n":"第十八条","txt":"环境影响报告书（表）编制质量检查的内容包括环境影响报告书（表）是否符合有关环境影响评价法律法规、标准和技术规范等规定，以及环境影响报告书（表）的基础资料是否明显不实，内容是否存在重大缺陷、遗漏或者虚假，环境影响评价结论是否正确、合理。"},{"i":19,"n":"第十九条","txt":"编制单位和编制人员情况检查包括下列内容： （一）编制单位和编制人员在信用平台提交的相关情况信息是否真实、准确、完整； （二）编制单位建立和实施环境影响评价质量控制制度情况； （三）编制单位环境影响报告书（表）相关档案管理情况； （四）其他应当检查的内容。"},{"i":20,"n":"第二十条","txt":"各级生态环境主管部门在环境影响报告书（表）受理过程中，应当对报批的环境影响报告书（表）进行编制规范性检查。 受理环境影响报告书（表）的生态环境主管部门发现环境影响报告书（表）不符合本办法第十二条第一款、第十四条第二款的规定，或者由不符合本办法第九条、第十条规定的编制单位、编制人员编制，或者编制单位、编制人员未按照本办法第十一条、第十四条第一款规定在信用平台提交相关信息的，应当在五个工作日内一次性告知建设单位需补正的全部内容；发现环境影响报告书（表）由列入本办法规定的限期整改名单或者本办法规定的“黑名单”的编制单位、编制人员编制的，不予受理。"},{"i":21,"n":"第二十一条","txt":"各级生态环境主管部门在环境影响报告书（表）审批过程中，应当对报批的环境影响报告书（表）进行编制质量检查；发现环境影响报告书（表）基础资料明显不实，内容存在重大缺陷、遗漏或者虚假，或者环境影响评价结论不正确、不合理的，不予批准。"},{"i":22,"n":"第二十二条","txt":"生态环境部定期或者根据实际工作需要不定期抽取一定比例地方生态环境主管部门或者其他有关审批部门审批的环境影响报告书（表）开展复核，对抽取的环境影响报告书（表）进行编制规范性检查和编制质量检查。 省级生态环境主管部门可以对本行政区域内下级生态环境主管部门或者其他有关审批部门审批的环境影响报告书（表）开展复核。 鼓励利用大数据手段开展复核工作。"},{"i":23,"n":"第二十三条","txt":"生态环境部定期或者根据实际工作需要不定期通过抽查的方式，开展编制单位和编制人员情况检查。省级和市级生态环境主管部门可以对住所在本行政区域内或者在本行政区域内开展环境影响评价的编制单位及其编制人员相关情况进行抽查。"},{"i":24,"n":"第二十四条","txt":"单位或者个人向生态环境主管部门举报环境影响报告书（表）编制规范性问题、编制质量问题，或者编制单位和编制人员违反本办法规定的，生态环境主管部门应当及时组织开展调查核实。"},{"i":25,"n":"第二十五条","txt":"生态环境主管部门进行监督检查时，被监督检查的单位和人员应当如实说明情况，提供相关材料。"},{"i":26,"n":"第二十六条","txt":"在监督检查过程中发现环境影响报告书（表）不符合有关环境影响评价法律法规、标准和技术规范等规定、存在下列质量问题之一的，由市级以上生态环境主管部门对建设单位、技术单位和编制人员给予通报批评： （一）评价因子中遗漏建设项目相关行业污染源源强核算或者污染物排放标准规定的相关污染物的； （二）降低环境影响评价工作等级，降低环境影响评价标准，或者缩小环境影响评价范围的； （三）建设项目概况描述不全或者错误的； （四）环境影响因素分析不全或者错误的； （五）污染源源强核算内容不全，核算方法或者结果错误的； （六）环境质量现状数据来源、监测因子、监测频次或者布点等不符合相关规定，或者所引用数据无效的； （七）遗漏环境保护目标，或者环境保护目标与建设项目位置关系描述不明确或者错误的； （八）环境影响评价范围内的相关环境要素现状调查与评价、区域污染源调查内容不全或者结果错误的； （九）环境影响预测与评价"},{"i":27,"n":"第二十七条","txt":"在监督检查过程中发现环境影响报告书（表）存在下列严重质量问题之一的，由市级以上生态环境主管部门依照《中华人民共和国环境影响评价法》第三十二条的规定，对建设单位及其相关人员、技术单位、编制人员予以处罚： （一）建设项目概况中的建设地点、主体工程及其生产工艺，或者改扩建和技术改造项目的现有工程基本情况、污染物排放及达标情况等描述不全或者错误的； （二）遗漏自然保护区、饮用水水源保护区或者以居住、医疗卫生、文化教育为主要功能的区域等环境保护目标的； （三）未开展环境影响评价范围内的相关环境要素现状调查与评价，或者编造相关内容、结果的； （四）未开展相关环境要素或者环境风险预测与评价，或者编造相关内容、结果的； （五）所提环境保护措施无法确保污染物排放达到国家和地方排放标准或者有效预防和控制生态破坏，未针对建设项目可能产生的或者原有环境污染和生态破坏提出有效防治措施的； （六）建设项目所在区域"},{"i":28,"n":"第二十八条","txt":"生态环境主管部门在作出通报批评和处罚决定前，应当向建设单位、技术单位和相关人员告知查明的事实和作出决定的理由及依据，并告知其享有的权利。相关单位和人员可在规定时间内作出书面陈述和申辩。 生态环境主管部门应当对相关单位和人员在陈述和申辩中提出的事实、理由或者证据进行核实。"},{"i":29,"n":"第二十九条","txt":"生态环境主管部门应当将作出的通报批评和处罚决定向社会公开。处理和处罚决定应当包括相关单位及其人员基础信息、事实、理由及依据、处理处罚结果等内容。"},{"i":30,"n":"第三十条","txt":"在监督检查过程中发现经批准的环境影响报告书（表）有下列情形之一的，实施监督检查的生态环境主管部门应当重新对其进行编制质量检查： （一）不符合本办法第十二条第一款、第十四条第二款规定的； （二）编制单位和编制人员未按照本办法第十一条、第十四条第一款规定在信用平台提交相关信息的； （三）由不符合本办法第十条规定的编制人员编制的。 在监督检查过程中发现经批准的环境影响报告书（表）存在本办法第二十六条第二款、第二十七条所列问题的，或者由不符合本办法第九条规定以及由受理时已列入本办法规定的限期整改名单或者本办法规定的“黑名单”的编制单位或者编制人员编制的，生态环境主管部门或者其他负责审批环境影响报告书（表）的审批部门应当依法撤销相应批准文件。 在监督检查过程中发现经批准的环境影响报告书（表）存在本办法第二十六条、第二十七条所列问题的，原审批部门应当督促建设单位采取措施避免建设项目产生不良环境影响"},{"i":31,"n":"第三十一条","txt":"市级以上生态环境主管部门应当将编制单位和编制人员作为环境影响评价信用管理对象（以下简称信用管理对象）纳入信用管理；在环境影响报告书（表）编制行为监督检查过程中，发现信用管理对象存在失信行为的，应当实施失信记分。 生态环境部另行制定信用管理对象失信行为记分办法，对信用管理对象失信行为的记分规则、记分周期、警示分数和限制分数等作出规定。"},{"i":32,"n":"第三十二条","txt":"信用管理对象的失信行为包括下列情形： （一）编制单位不符合本办法第九条规定或者编制人员不符合本办法第十条规定的； （二）未按照本办法及生态环境部相关规定在信用平台提交相关情况信息或者及时变更相关情况信息，或者提交的相关情况信息不真实、不准确、不完整的； （三）违反本办法规定，由两家以上单位主持编制环境影响报告书（表）或者由两名以上编制人员作为环境影响报告书（表）编制主持人的； （四）技术单位未按照本办法规定与建设单位签订主持编制环境影响报告书（表）委托合同的； （五）未按照本办法规定进行环境影响评价质量控制的； （六）未按照本办法规定在环境影响报告书（表）中附具编制单位和编制人员情况表并盖章或者签字的； （七）未按照本办法规定将相关资料存档的； （八）未按照本办法规定接受生态环境主管部门监督检查或者在接受监督检查时弄虚作假的； （九）因环境影响报告书（表）存在本办法第二十六条第一款所列"},{"i":33,"n":"第三十三条","txt":"实施失信记分应当履行告知、决定和记录等程序。 市级以上生态环境主管部门在监督检查过程中发现信用管理对象存在失信行为的，应当向其告知查明的事实、记分情况以及相关依据。信用管理对象可以在规定时间内作出书面陈述和申辩。 市级以上生态环境主管部门应当对信用管理对象在陈述和申辩中提出的事实、理由或者证据进行核实。 市级以上生态环境主管部门应当对经核实无误的失信行为记分作出书面决定，并向社会公开。失信行为记分决定应当包括信用管理对象基础信息、失信行为事实、失信记分及依据、涉及的建设项目和建设单位名称等内容。 市级以上生态环境主管部门应当在作出失信行为记分决定后五个工作日内，将书面决定及有关情况上传至信用平台并记入信用管理对象诚信档案。 因环境影响报告书（表）存在本办法第二十六条、第二十七条所列问题，生态环境主管部门对信用管理对象作出处理处罚决定的，实施失信记分的告知、决定程序应当与处理处罚相关程序"},{"i":34,"n":"第三十四条","txt":"失信行为和失信记分相关情况在信用平台的公开期限为五年。禁止从事环境影响报告书（表）编制工作的技术单位和终身禁止从事环境影响报告书（表）编制工作的编制人员，其失信行为和失信记分永久公开。 失信行为和失信记分公开的起始时间为生态环境主管部门作出失信记分决定的时间。"},{"i":35,"n":"第三十五条","txt":"信用平台对信用管理对象在一个记分周期内各级生态环境主管部门实施的失信记分予以动态累计，并将记分周期内累计失信记分情况作为对其实行守信激励和失信惩戒的依据。"},{"i":36,"n":"第三十六条","txt":"信用管理对象连续两个记分周期的每个记分周期内编制过十项以上经批准的环境影响报告书（表）且无失信记分的，信用平台在后续两个记分周期内将其列入守信名单，并将相关情况记入其诚信档案。生态环境主管部门应当减少对列入守信名单的信用管理对象编制的环境影响报告书（表）复核抽取比例和抽取频次。 信用管理对象在列入守信名单期间有失信记分的，信用平台将其从守信名单中移出，并将移出情况记入其诚信档案。"},{"i":37,"n":"第三十七条","txt":"信用管理对象在一个记分周期内累计失信记分达到警示分数的，信用平台在后续两个记分周期内将其列入重点监督检查名单，并将相关情况记入其诚信档案。生态环境主管部门应当提高对列入重点监督检查名单的信用管理对象编制的环境影响报告书（表）复核抽取比例和抽取频次。"},{"i":38,"n":"第三十八条","txt":"信用管理对象在一个记分周期内的失信记分实时累计达到限制分数的，信用平台将其列入限期整改名单，并将相关情况记入其诚信档案。限期整改期限为六个月，自达到限制分数之日起计算。 信用管理对象在限期整改期间的失信记分再次累计达到限制分数的,应当自再次达到限制分数之日起限期整改六个月。"},{"i":39,"n":"第三十九条","txt":"信用管理对象因环境影响报告书（表）存在本办法第二十六条第二款、第二十七条所列问题，受到禁止从事环境影响报告书（表）编制工作处罚的，失信记分直接记为限制分数。信用平台将其列入“黑名单”，并将相关情况记入其诚信档案。列入“黑名单”的期限与处罚决定中禁止从事环境影响报告书（表）编制工作的期限一致。 对信用管理对象中列入“黑名单”单位的出资人，由列入“黑名单”单位或者其法定代表人出资的单位，以及由列入“黑名单”单位出资人出资的其他单位，信用平台将其列入重点监督检查名单，并将相关情况记入其诚信档案。列入重点监督检查名单的期限为二年，自列入“黑名单”单位达到限制分数之日起计算。生态环境主管部门应当提高对上述信用管理对象编制的环境影响报告书（表）的复核抽取比例和抽取频次。"},{"i":40,"n":"第四十条","txt":"信用管理对象列入本办法规定的守信名单、重点监督检查名单、限期整改名单和“黑名单”的相关情况在信用平台的公开期限为五年。 生态环境部每半年对列入本办法规定的限期整改名单和本办法规定的“黑名单”的信用管理对象以及相关情况予以通报，并向社会公开。"},{"i":41,"n":"第四十一条","txt":"因环境影响报告书（表）存在本办法第二十六条第二款、第二十七条所列问题，信用管理对象受到处罚的，作出处罚决定的生态环境主管部门应当及时将其相关违法信息推送至国家企业信用信息公示系统和全国信用信息共享平台。"},{"i":42,"n":"第四十二条","txt":"上级生态环境主管部门发现下级生态环境主管部门未按照本办法规定对发现的失信行为实施失信记分的，应当责令其限期改正。"},{"i":43,"n":"第四十三条","txt":"鼓励环境影响评价行业组织加强行业自律，开展技术单位和编制人员水平评价。"},{"i":44,"n":"第四十四条","txt":"本办法所称全职，是指与编制单位订立劳动合同（非全日制用工合同除外）并由该单位缴纳社会保险或者在事业单位类型的编制单位中在编等用工形式。 本办法所称从业单位，是指编制人员全职工作的编制单位。"},{"i":45,"n":"第四十五条","txt":"负责审批环境影响报告书（表）的其他有关审批部门可以参照本办法对环境影响报告书（表）编制实施监督管理。"},{"i":46,"n":"第四十六条","txt":"本办法由生态环境部负责解释。"},{"i":47,"n":"第四十七条","txt":"本办法自2019年11月1日起施行。《建设项目环境影响评价资质管理办法》(环境保护部令第36号)同时废止。"}],"jianshexiangmuhuanjingyingxiangdengjibiaobeianguanca510c":[{"i":1,"n":"第一条","txt":"为规范建设项目环境影响登记表备案，依据《环境影响评价法》和《建设项目环境保护管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于按照《建设项目环境影响评价分类管理名录》规定应当填报环境影响登记表的建设项目。"},{"i":3,"n":"第三条","txt":"填报环境影响登记表的建设项目，建设单位应当依照本办法规定，办理环境影响登记表备案手续。"},{"i":4,"n":"第四条","txt":"填报环境影响登记表的建设项目应当符合法律法规、政策、标准等要求。 建设单位对其填报的建设项目环境影响登记表内容的真实性、准确性和完整性负责。"},{"i":5,"n":"第五条","txt":"县级环境保护主管部门负责本行政区域内的建设项目环境影响登记表备案管理。 按照国家有关规定，县级环境保护主管部门被调整为市级环境保护主管部门派出分局的，由市级环境保护主管部门组织所属派出分局开展备案管理。"},{"i":6,"n":"第六条","txt":"建设项目的建设地点涉及多个县级行政区域的，建设单位应当分别向各建设地点所在地的县级环境保护主管部门备案。"},{"i":7,"n":"第七条","txt":"建设项目环境影响登记表备案采用网上备案方式。 对国家规定需要保密的建设项目，建设项目环境影响登记表备案采用纸质备案方式。"},{"i":8,"n":"第八条","txt":"环境保护部统一布设建设项目环境影响登记表网上备案系统（以下简称网上备案系统）。 省级环境保护主管部门在本行政区域内组织应用网上备案系统，通过提供地址链接方式，向县级环境保护主管部门分配网上备案系统使用权限。 县级环境保护主管部门应当向社会公告网上备案系统地址链接信息。 各级环境保护主管部门应当将环境保护法律、法规、规章以及规范性文件中与建设项目环境影响登记表备案相关的管理要求，及时在其网站的网上备案系统中公开，为建设单位办理备案手续提供便利。"},{"i":9,"n":"第九条","txt":"建设单位应当在建设项目建成并投入生产运营前，登录网上备案系统, 在网上备案系统注册真实信息，在线填报并提交建设项目环境影响登记表。"},{"i":10,"n":"第十条","txt":"建设单位在办理建设项目环境影响登记表备案手续时，应当认真查阅、核对《建设项目环境影响评价分类管理名录》，确认其备案的建设项目属于按照《建设项目环境影响评价分类管理名录》规定应当填报环境影响登记表的建设项目。 对按照《建设项目环境影响评价分类管理名录》规定应当编制环境影响报告书或者报告表的建设项目，建设单位不得擅自降低环境影响评价等级，填报环境影响登记表并办理备案手续。"},{"i":11,"n":"第十一条","txt":"建设单位填报建设项目环境影响登记表时，应当同时就其填报的环境影响登记表内容的真实、准确、完整作出承诺，并在登记表中的相应栏目由该建设单位的法定代表人或者主要负责人签署姓名。"},{"i":12,"n":"第十二条","txt":"建设单位在线提交环境影响登记表后，网上备案系统自动生成备案编号和回执，该建设项目环境影响登记表备案即为完成。 建设单位可以自行打印留存其填报的建设项目环境影响登记表及建设项目环境影响登记表备案回执。 建设项目环境影响登记表备案回执是环境保护主管部门确认收到建设单位环境影响登记表的证明。"},{"i":13,"n":"第十三条","txt":"建设项目环境影响登记表备案完成后，建设单位或者其法定代表人或者主要负责人在建设项目建成并投入生产运营前发生变更的，建设单位应当依照本办法规定再次办理备案手续。"},{"i":14,"n":"第十四条","txt":"建设项目环境影响登记表备案完成后，建设单位应当严格执行相应污染物排放标准及相关环境管理规定，落实建设项目环境影响登记表中填报的环境保护措施，有效防治环境污染和生态破坏。"},{"i":15,"n":"第十五条","txt":"建设项目环境影响登记表备案完成后，县级环境保护主管部门通过其网站的网上备案系统同步向社会公开备案信息，接受公众监督。对国家规定需要保密的建设项目，县级环境保护主管部门严格执行国家有关保密规定，备案信息不公开。 县级环境保护主管部门应当根据国务院关于加强环境监管执法的有关规定，将其完成备案的建设项目纳入有关环境监管网格管理范围。"},{"i":16,"n":"第十六条","txt":"公民、法人和其他组织发现建设单位有以下行为的，有权向环境保护主管部门或者其他负有环境保护监督管理职责的部门举报： （一）环境影响登记表存在弄虚作假的； （二）有污染环境和破坏生态行为的； （三）对按照《建设项目环境影响评价分类管理名录》规定应当编制环境影响报告书或者报告表的建设项目，建设单位擅自降低环境影响评价等级，填报环境影响登记表并办理备案手续的。 举报应当采取书面形式，有明确的被举报人，并提供相关事实和证据。"},{"i":17,"n":"第十七条","txt":"环境保护主管部门或者其他负有环境保护监督管理职责的部门可以采取抽查、根据举报进行检查等方式，对建设单位遵守本办法规定的情况开展监督检查，并根据监督检查认定的事实，按照以下情形处理： （一）构成行政违法的，依照有关环境保护法律法规和规定，予以行政处罚； （二）构成环境侵权的，依法承担环境侵权责任； （三）涉嫌构成犯罪的，依法移送司法机关。"},{"i":18,"n":"第十八条","txt":"建设单位未依法备案建设项目环境影响登记表的，由县级环境保护主管部门根据《环境影响评价法》第三十一条第三款的规定，责令备案，处五万元以下的罚款。"},{"i":19,"n":"第十九条","txt":"违反本办法规定，建设单位违反承诺，在填报建设项目环境影响登记表时弄虚作假，致使备案内容失实的，由县级环境保护主管部门将该建设单位违反承诺情况记入其环境信用记录，向社会公布。"},{"i":20,"n":"第二十条","txt":"违反本办法规定，对按照《建设项目环境影响评价分类管理名录》应当编制环境影响报告书或者报告表的建设项目，建设单位擅自降低环境影响评价等级，填报环境影响登记表并办理备案手续，经查证属实的，县级环境保护主管部门认定建设单位已经取得的备案无效，向社会公布，并按照以下规定处理： （一）未依法报批环境影响报告书或者报告表，擅自开工建设的，依照《环境保护法》第六十一条和《环境影响评价法》第三十一条第一款的规定予以处罚、处分。 （二）未依法报批环境影响报告书或者报告表，擅自投入生产或者经营的，分别依照《环境影响评价法》第三十一条第一款和《建设项目环境保护管理条例》的有关规定作出相应处罚。"},{"i":21,"n":"第二十一条","txt":"对依照本办法第十八条、第二十条规定处理的建设单位，由县级环境保护主管部门将该建设单位违法失信信息记入其环境信用记录，向社会公布。"},{"i":22,"n":"第二十二条","txt":"本办法自2017年1月1日起施行。 附:建设项目环境影响登记表 填 表 说 明 1.填表人应当仔细阅读《建设项目环境影响登记表备案管理办法》，知晓相关的权利和义务。 2.建设项目符合《建设项目环境影响登记表备案管理办法》的规定。 3.建设单位自觉接受环境保护主管部门或者其他负有环境保护监督管理职责的部门的日常监督管理。"}],"jianshexiangmuhuanjingyingxiangpingjiafenleiguanli315d9d":[{"i":1,"n":"第一条","txt":"为了实施建设项目环境影响评价分类管理，根据《中华人民共和国环境影响评价法》的有关规定，制定本名录。"},{"i":2,"n":"第二条","txt":"根据建设项目特征和所在区域的环境敏感程度，综合考虑建设项目可能对环境产生的影响，对建设项目的环境影响评价实行分类管理。 建设单位应当按照本名录的规定，分别组织编制建设项目环境影响报告书、环境影响报告表或者填报环境影响登记表。"},{"i":3,"n":"第三条","txt":"本名录所称环境敏感区是指依法设立的各级各类保护区域和对建设项目产生的环境影响特别敏感的区域，主要包括下列区域： （一）国家公园、自然保护区、风景名胜区、世界文化和自然遗产地、海洋特别保护区、饮用水水源保护区； （二）除（一）外的生态保护红线管控范围，永久基本农田、基本草原、自然公园（森林公园、地质公园、海洋公园等）、重要湿地、天然林，重点保护野生动物栖息地，重点保护野生植物生长繁殖地，重要水生生物的自然产卵场、索饵场、越冬场和洄游通道，天然渔场，水土流失重点预防区和重点治理区、沙化土地封禁保护区、封闭及半封闭海域； （三）以居住、医疗卫生、文化教育、科研、行政办公为主要功能的区域，以及文物保护单位。 环境影响报告书、环境影响报告表应当就建设项目对环境敏感区的影响做重点分析。"},{"i":4,"n":"第四条","txt":"建设单位应当严格按照本名录确定建设项目环境影响评价类别，不得擅自改变环境影响评价类别。 建设内容涉及本名录中两个及以上项目类别的建设项目，其环境影响评价类别按照其中单项等级最高的确定。 建设内容不涉及主体工程的改建、扩建项目，其环境影响评价类别按照改建、扩建的工程内容确定。"},{"i":5,"n":"第五条","txt":"本名录未作规定的建设项目，不纳入建设项目环境影响评价管理；省级生态环境主管部门对本名录未作规定的建设项目，认为确有必要纳入建设项目环境影响评价管理的，可以根据建设项目的污染因子、生态影响因子特征及其所处环境的敏感性质和敏感程度等，提出环境影响评价分类管理的建议，报生态环境部认定后实施。"},{"i":6,"n":"第六条","txt":"本名录由生态环境部负责解释，并适时修订公布。"},{"i":7,"n":"第七条","txt":"本名录自2021年1月1日起施行。《建设项目环境影响评价分类管理名录》（环境保护部令第44号）及《关于修改〈建设项目环境影响评价分类管理名录〉部分内容的决定》（生态环境部令第1号）同时废止。 环评类别 项目类别 报 告 书 报 告 表 登 记 表 本栏目环境敏感区含义 一、农业01、林业02 1 农产品基地项目（含药材基地） / 涉及环境敏感区的 其他 第三条（一）中的全部区域；第三条（二）中的除（一）外的生态保护红线管控范围，基本草原、重要湿地，水土流失重点预防区和重点治理区 2 经济林基地项目 / 原料林基地 其他 二、畜牧业 03 3 牲畜饲养 031；家禽饲养 032；其他畜牧业 039 年出栏生猪5000头（其他畜禽种类折合猪的养殖量）及以上的规模化畜禽养殖；存栏生猪2500头（其他畜禽种类折合猪的养殖规模）及以上无出栏量的规模化畜禽养殖；涉及环境敏感区的规模化畜禽养殖 /"}],"jianshexiangmuhuanjingyingxiangpingjiawenjianfenjic56c30":[{"i":1,"n":"第一条","txt":"为进一步加强和规范建设项目环境影响评价文件审批，提高审批效率，明确审批权责，根据《环境影响评价法》等有关规定，制定本规定。"},{"i":2,"n":"第二条","txt":"建设对环境有影响的项目，不论投资主体、资金来源、项目性质和投资规模，其环境影响评价文件均应按照本规定确定分级审批权限。 有关海洋工程和军事设施建设项目的环境影响评价文件的分级审批，依据有关法律和行政法规执行。"},{"i":3,"n":"第三条","txt":"各级环境保护部门负责建设项目环境影响评价文件的审批工作。"},{"i":4,"n":"第四条","txt":"建设项目环境影响评价文件的分级审批权限，原则上按照建设项目的审批、核准和备案权限及建设项目对环境的影响性质和程度确定。"},{"i":5,"n":"第五条","txt":"环境保护部负责审批下列类型的建设项目环境影响评价文件： （一）核设施、绝密工程等特殊性质的建设项目； （二）跨省、自治区、直辖市行政区域的建设项目； （三）由国务院审批或核准的建设项目，由国务院授权有关部门审批或核准的建设项目，由国务院有关部门备案的对环境可能造成重大影响的特殊性质的建设项目。"},{"i":6,"n":"第六条","txt":"环境保护部可以将法定由其负责审批的部分建设项目环境影响评价文件的审批权限，委托给该项目所在地的省级环境保护部门，并应当向社会公告。 受委托的省级环境保护部门，应当在委托范围内，以环境保护部的名义审批环境影响评价文件。 受委托的省级环境保护部门不得再委托其他组织或者个人。 环境保护部应当对省级环境保护部门根据委托审批环境影响评价文件的行为负责监督，并对该审批行为的后果承担法律责任。"},{"i":7,"n":"第七条","txt":"环境保护部直接审批环境影响评价文件的建设项目的目录、环境保护部委托省级环境保护部门审批环境影响评价文件的建设项目的目录，由环境保护部制定、调整并发布。"},{"i":8,"n":"第八条","txt":"第五条规定以外的建设项目环境影响评价文件的审批权限，由省级环境保护部门参照第四条及下述原则提出分级审批建议，报省级人民政府批准后实施，并抄报环境保护部。 （一）有色金属冶炼及矿山开发、钢铁加工、电石、铁合金、焦炭、垃圾焚烧及发电、制浆等对环境可能造成重大影响的建设项目环境影响评价文件由省级环境保护部门负责审批。 （二）化工、造纸、电镀、印染、酿造、味精、柠檬酸、酶制剂、酵母等污染较重的建设项目环境影响评价文件由省级或地级市环境保护部门负责审批。 （三）法律和法规关于建设项目环境影响评价文件分级审批管理另有规定的，按照有关规定执行。"},{"i":9,"n":"第九条","txt":"建设项目可能造成跨行政区域的不良环境影响，有关环境保护部门对该项目的环境影响评价结论有争议的，其环境影响评价文件由共同的上一级环境保护部门审批。"},{"i":10,"n":"第十条","txt":"下级环境保护部门超越法定职权、违反法定程序或者条件做出环境影响评价文件审批决定的，上级环境保护部门可以按照下列规定处理： （一）依法撤销或者责令其撤销超越法定职权、违反法定程序或者条件做出的环境影响评价文件审批决定。 （二）对超越法定职权、违反法定程序或者条件做出环境影响评价文件审批决定的直接责任人员，建议由任免机关或者监察机关依照《环境保护违法违纪行为处分暂行规定》的规定，对直接责任人员，给予警告、记过或者记大过处分；情节较重的，给予降级处分；情节严重的，给予撤职处分。"},{"i":11,"n":"第十一条","txt":"本规定自2009年3月1日起施行。2002年11月1日原国家环境保护总局发布的《建设项目环境影响评价文件分级审批规定》（原国家环境保护总局令第15号）同时废止。"}],"jianshexiangmuhuanjingyingxiangpingjiaxingweizhunz335017":[{"i":1,"n":"第一条","txt":"为规范建设项目环境影响评价行为，加强建设项目环境影响评价管理和廉政建设，保证建设项目环境保护管理工作廉洁高效依法进行，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于建设项目环境影响评价、技术评估、竣工环境保护验收监测或验收调查（以下简称“验收监测或调查”）工作，以及建设项目环境影响评价文件审批和建设项目竣工环境保护验收的行为。"},{"i":3,"n":"第三条","txt":"承担建设项目环境影响评价、技术评估、验收监测或调查工作的单位和个人，以及生态环境主管部门及其工作人员，应当遵守国家有关法律、法规、规章、政策和本规定的要求，坚持廉洁、独立、客观、公正的原则，并自觉接受有关方面的监督。"},{"i":4,"n":"第四条","txt":"承担建设项目环境影响评价工作的机构（以下简称“评价机构”）或者其环境影响评价技术人员，应当遵守下列规定： （一）评价机构及评价项目负责人应当对环境影响评价结论负责； （二）建立严格的环境影响评价文件质量审核制度和质量保证体系，明确责任，落实环境影响评价质量保证措施，并接受生态环境主管部门的日常监督检查； （三）不得为违反国家产业政策以及国家明令禁止建设的建设项目进行环境影响评价； （四）必须依照有关的技术规范要求编制环境影响评价文件； （五）应当合理收费，不得随意抬高、压低评价费用或者采取其他不正当竞争手段； （六）评价机构不得无任何正当理由拒绝承担环境影响评价工作； （七）不得转包或者变相转包环境影响评价业务； （八）应当为建设单位保守技术秘密和业务秘密； （九）在环境影响评价工作中不得隐瞒真实情况、提供虚假材料、编造数据或者实施其他弄虚作假行为； （十）应当按照生态环境主管部门的要"},{"i":5,"n":"第五条","txt":"承担环境影响评价技术评估工作的单位（以下简称“技术评估机构”）或者其技术评估人员、评审专家等，应当遵守下列规定： （一）技术评估机构及其主要负责人应当对环境影响评价文件的技术评估结论负责； （二）应当以科学态度和方法，严格依照技术评估工作的有关规定和程序，实事求是，独立、客观、公正地对项目做出技术评估或者提出意见，并接受生态环境主管部门的日常监督检查； （三）禁止索取或收受建设单位、评价机构或个人馈赠的财物或给予的其他不当利益，不得让建设单位、评价机构或个人报销应由评估机构或者其技术评估人员、评审专家个人负担的费用(按有关规定收取的咨询费等除外)； （四）禁止向建设单位、评价机构或个人提出与技术评估工作无关的要求或暗示，不得接受邀请，参加旅游、社会营业性娱乐场所的活动以及任何赌博性质的活动； （五）技术评估人员、评审专家不得以个人名义参加环境影响报告书编制工作或者对环境影响评价大纲和环"},{"i":6,"n":"第六条","txt":"承担验收监测或调查工作的单位及其验收监测或调查人员，应当遵守下列规定： （一）验收监测或调查单位及其主要负责人应当对建设项目竣工环境保护验收监测报告或验收调查报告结论负责； （二）建立严格的质量审核制度和质量保证体系，严格按照国家有关法律法规规章、技术规范和技术要求，开展验收监测或调查工作和编制验收监测或验收调查报告，并接受生态环境主管部门的日常监督检查； （三）验收监测报告或验收调查报告应当如实反映建设项目环境影响评价文件的落实情况及其效果； （四）禁止泄露建设项目技术秘密和业务秘密； （五）在验收监测或调查过程中不得隐瞒真实情况、提供虚假材料、编造数据或者实施其他弄虚作假行为； （六）验收监测或调查收费应当严格执行国家和地方有关规定； （七）不得在验收监测或调查工作中为个人谋取私利； （八）不得进行其他妨碍验收监测或调查工作廉洁、独立、客观、公正的行为。"},{"i":7,"n":"第七条","txt":"建设单位应当依法开展环境影响评价，办理建设项目环境影响评价文件的审批手续，接受并配合技术评估机构的评估、验收监测或调查单位的监测或调查，按要求提供与项目有关的全部资料和信息。 建设单位应当遵守下列规定： （一）不得在建设项目环境影响评价、技术评估、验收监测或调查和环境影响评价文件审批及环境保护验收过程中隐瞒真实情况、提供虚假材料、编造数据或者实施其他弄虚作假行为； （二）不得向组织或承担建设项目环境影响评价、技术评估、验收监测或调查和环境影响评价文件审批及环境保护验收工作的单位或个人馈赠或者许诺馈赠财物或给予其他不当利益； （三）不得进行其他妨碍建设项目环境影响评价、技术评估、验收监测或调查和环境影响评价文件审批及环境保护验收工作廉洁、独立、客观、公正开展的活动。"},{"i":8,"n":"第八条","txt":"生态环境主管部门应当坚持标本兼治、综合治理、惩防并举、注重预防的方针，建立健全教育、制度、监督并重的惩治和预防腐败体系。 生态环境主管部门的工作人员在环境影响评价文件审批和环境保护验收工作中应当遵循政治严肃、纪律严明、作风严谨、管理严格和形象严整的原则，在思想上、政治上、言论上、行动上与党中央保持一致，立党为公、执政为民，坚决执行廉政建设规定，开展反腐倡廉活动，严格依法行政，严格遵守组织纪律，密切联系群众，自觉维护公务员形象。"},{"i":9,"n":"第九条","txt":"在建设项目环境影响评价文件审批及环境保护验收工作中，生态环境主管部门及其工作人员应当遵守下列规定： （一）不得利用工作之便向任何单位指定评价机构，推销环保产品，引荐环保设计、环保设施运营单位，参与有偿中介活动； （二）不得接受咨询费、评审费、专家费等一切相关费用； （三）不得参加一切与建设项目环境影响评价文件审批及环境保护验收工作有关的、或由公款支付的宴请； （四）不得利用工作之便吃、拿、卡、要，收取礼品、礼金、有价证券或物品，或以权谋私搞交易； （五）不得参与用公款支付的一切娱乐消费活动，严禁参加不健康的娱乐活动； （六）不得在接待来访或电话咨询中出现冷漠、生硬、蛮横、推诿等态度； （七）不得有越权、渎职、徇私舞弊，或违反办事公平、公正、公开要求的行为； （八）不得进行其他妨碍建设项目环境影响评价文件审批及环境保护验收工作廉洁、独立、客观、公正的活动。"},{"i":10,"n":"第十条","txt":"生态环境主管部门按照建设项目环境影响评价文件的审批权限，对建设项目环境影响评价、技术评估、验收监测或调查工作进行监督检查。 驻生态环境主管部门的纪检监察部门对建设项目环境影响评价文件审批和环境保护验收工作，进行监督检查。 上一级生态环境主管部门应对下一级生态环境主管部门的建设项目环境影响评价文件审批和环境保护验收工作，进行监督检查。"},{"i":11,"n":"第十一条","txt":"对建设项目环境影响评价、技术评估、验收监测或调查和建设项目环境影响评价文件审批、环境保护验收工作的监督检查工作，可以采取经常性监督检查和专项性监督检查的形式。 经常性监督检查是指对建设项目环境影响评价、技术评估、验收监测或调查和建设项目环境影响评价文件审批、环境保护验收工作进行全过程的监督检查。 专项性监督检查是指对建设项目环境影响评价、技术评估、验收监测或调查和建设项目环境影响评价文件审批、环境保护验收工作的某个环节或某类项目进行监督检查。 对于重大项目的环境影响评价、技术评估、验收监测或调查和建设项目环境影响评价文件审批、环境保护验收工作，应当采取专项性监督检查方式。"},{"i":12,"n":"第十二条","txt":"任何单位和个人发现建设项目环境影响评价、技术评估、验收监测或调查和建设项目环境影响评价文件审批、环境保护验收工作中存在问题的，可以向生态环境主管部门或者纪检监察部门举报和投诉。 对举报或投诉，应当按照下列规定处理： （一）对署名举报的，应当为举报人保密。在对反映的问题调查核实、依法做出处理后，应当将核实、处理结果告知举报人并听取意见。对捏造事实，进行诬告陷害的，应依据有关规定处理。 （二）对匿名举报的材料，有具体事实的，应当进行初步核实，并确定处理办法，对重要问题的处理结果，应当在适当范围内通报；没有具体事实的，可登记留存。 （三）对投诉人的投诉，应当严格按照信访工作的有关规定及时办理。"},{"i":13,"n":"第十三条","txt":"生态环境主管部门对建设项目环境影响评价、技术评估、验收监测或调查和建设项目环境影响评价文件审批、环境保护验收工作进行监督检查时，可以采取下列方式： （一）听取各方当事人的汇报或意见； （二）查阅与活动有关的文件、合同和其他有关材料； （三）向有关单位和个人调查核实； （四）其他适当方式。"},{"i":14,"n":"第十四条","txt":"评价机构违反本规定的，依照《环境影响评价法》、《建设项目环境保护管理条例》和《建设项目环境影响评价资质管理办法》以及其他有关法律法规的规定,视情节轻重，分别给予警告、通报批评、责令限期整改、缩减评价范围、降低资质等级或者取消评价资质，并采取适当方式向社会公布。"},{"i":15,"n":"第十五条","txt":"技术评估机构违反本规定的，由生态环境主管部门责令改正，并根据情节轻重，给予警告、通报批评、宣布评估意见无效或者禁止该技术评估机构承担或者参加相关技术评估工作。"},{"i":16,"n":"第十六条","txt":"验收监测或调查单位违反本规定的，按照《建设项目竣工环境保护验收管理办法》的有关规定予以处罚。"},{"i":17,"n":"第十七条","txt":"从事环境影响评价、技术评估、验收监测或调查工作的人员违反本规定，依照国家法律法规规章或者其他有关规定给予行政处分或者纪律处分；非法收受财物的，按照国家有关规定没收、追缴或责令退还所收受财物；构成犯罪的，依法移送司法机关追究刑事责任。 对技术评估机构的评估人员或者评估专家，禁止其承担或者参加相关技术评估工作。"},{"i":18,"n":"第十八条","txt":"建设单位违反本规定的，生态环境主管部门应当责令改正，并根据情节轻重，给予记录不良信用、给予警告、通报批评，并采取适当方式向社会公布。"},{"i":19,"n":"第十九条","txt":"生态环境主管部门违反本规定的，按照《环境影响评价法》、《建设项目环境保护管理条例》和有关环境保护违法违纪行为处分办法以及其他有关法律法规规章的规定给予处理。 生态环境主管部门的工作人员违反本规定的，按照《环境影响评价法》、《建设项目环境保护管理条例》和有关环境保护违法违纪行为处分办法以及其他有关法律法规规章的规定给予行政处分；构成犯罪的，依法移送司法机关追究刑事责任。"},{"i":20,"n":"第二十条","txt":"规划环境影响评价行为准则与廉政规定可参照本规定执行。"},{"i":21,"n":"第二十一条","txt":"本规定自2006年1月1日起施行。"}],"paiwuxukeguanlibanfa":[{"i":1,"n":"第一条","txt":"为了规范排污许可管理，根据《中华人民共和国环境保护法》《中华人民共和国海洋环境保护法》和大气、水、固体废物、土壤、噪声等专项污染防治法律，以及《排污许可管理条例》（以下简称《条例》），制定本办法。"},{"i":2,"n":"第二条","txt":"排污许可证的申请、审批、执行以及与排污许可相关的监督管理等行为，适用本办法。"},{"i":3,"n":"第三条","txt":"依照法律规定实行排污许可管理的企业事业单位和其他生产经营者（以下简称排污单位），应当依法申请取得排污许可证，并按照排污许可证的规定排放污染物；未取得排污许可证的，不得排放污染物。 依法需要填报排污登记表的企业事业单位和其他生产经营者（以下简称排污登记单位），应当在全国排污许可证管理信息平台进行排污登记。"},{"i":4,"n":"第四条","txt":"根据污染物产生量、排放量、对环境的影响程度等因素，对企业事业单位和其他生产经营者实行排污许可重点管理、简化管理和排污登记管理。 实行排污许可重点管理、简化管理的排污单位具体范围，依照固定污染源排污许可分类管理名录规定执行。实行排污登记管理的排污登记单位具体范围由国务院生态环境主管部门制定并公布。"},{"i":5,"n":"第五条","txt":"国务院生态环境主管部门负责全国排污许可的统一监督管理。 省级生态环境主管部门和设区的市级生态环境主管部门负责本行政区域排污许可的监督管理。"},{"i":6,"n":"第六条","txt":"生态环境主管部门对排污单位的大气污染物、水污染物、工业固体废物、工业噪声等污染物排放行为实行综合许可管理。"},{"i":7,"n":"第七条","txt":"国务院生态环境主管部门对排污单位及其生产设施、污染防治设施和排放口实行统一编码管理。"},{"i":8,"n":"第八条","txt":"国务院生态环境主管部门负责建设、运行、维护、管理全国排污许可证管理信息平台。 排污许可证的申请、受理、审查、审批决定、变更、延续、注销、撤销、信息公开等应当通过全国排污许可证管理信息平台办理。排污单位申请取得排污许可证的，也可以通过信函等方式提交书面申请。 全国排污许可证管理信息平台中记录的排污许可证相关电子信息与排污许可证正本、副本记载的信息依法具有同等效力。"},{"i":9,"n":"第九条","txt":"排污许可证执行报告中报告的污染物实际排放量，可以作为开展年度生态环境统计、重点污染物排放总量考核、污染源排放清单编制等工作的依据。 排污许可证应当作为排污权的确认凭证和排污权交易的管理载体。"},{"i":10,"n":"第十条","txt":"排污许可证由正本和副本构成。 设区的市级以上地方人民政府生态环境主管部门可以依据地方性法规，增加需要在排污许可证中记载的内容。"},{"i":11,"n":"第十一条","txt":"排污许可证正本应当记载《条例》第十三条第一、二项规定的基本信息，排污许可证副本应当记载《条例》第十三条规定的所有信息。 法律法规规定的排污单位应当遵守的大气污染物、水污染物、工业固体废物、工业噪声等控制污染物排放的要求，重污染天气等特殊时段禁止或者限制污染物排放的要求，以及土壤污染重点监管单位的控制有毒有害物质排放、土壤污染隐患排查、自行监测等要求，应当在排污许可证副本中记载。"},{"i":12,"n":"第十二条","txt":"排污单位承诺执行更加严格的排放限值的，应当在排污许可证副本中记载。"},{"i":13,"n":"第十三条","txt":"排污登记表应当记载下列信息： （一）排污登记单位名称、统一社会信用代码、生产经营场所所在地、行业类别、法定代表人或者实际负责人等基本信息； （二）污染物排放去向、执行的污染物排放标准及采取的污染防治措施等。"},{"i":14,"n":"第十四条","txt":"排污单位应当在实际排污行为发生之前，向其生产经营场所所在地设区的市级以上地方人民政府生态环境主管部门（以下简称审批部门）申请取得排污许可证。 海洋工程排污单位申请取得排污许可证的，依照有关法律、行政法规的规定执行。"},{"i":15,"n":"第十五条","txt":"排污单位有两个以上生产经营场所排放污染物的，应当分别向生产经营场所所在地的审批部门申请取得排污许可证。"},{"i":16,"n":"第十六条","txt":"实行排污许可重点管理的排污单位在提交排污许可证首次申请或者重新申请材料前，应当通过全国排污许可证管理信息平台向社会公开基本信息和拟申请许可事项，并提交说明材料。公开时间不得少于五个工作日。"},{"i":17,"n":"第十七条","txt":"排污单位在填报排污许可证申请表时，应当承诺排污许可证申请材料的完整性、真实性和合法性，承诺按照排污许可证的规定排放污染物，落实排污许可证规定的环境管理要求，并由法定代表人或者主要负责人签字或者盖章。"},{"i":18,"n":"第十八条","txt":"排污单位应当依照《条例》第七条、第八条规定提交相应材料，并可以对申请材料进行补充说明，一并提交审批部门。 排污单位申请许可排放量的，应当一并提交排放量限值计算过程。重点污染物排放总量控制指标通过排污权交易获取的，还应当提交排污权交易指标的证明材料。 污染物排放口已经建成的排污单位，应当提交有关排放口规范化的情况说明。"},{"i":19,"n":"第十九条","txt":"排污单位在申请排污许可证时，应当按照自行监测技术指南，编制自行监测方案。 自行监测方案应当包括以下内容： （一）监测点位及示意图、监测指标、监测频次； （二）使用的监测分析方法； （三）监测质量保证与质量控制要求； （四）监测数据记录、整理、存档要求； （五）监测数据信息公开要求。"},{"i":20,"n":"第二十条","txt":"审批部门收到排污单位提交的申请材料后，依照《条例》第九条、第十条要求作出处理。 审批部门可以组织技术机构对排污许可证申请材料进行技术评估，并承担相应费用。技术机构应当遵循科学、客观、公正的原则，提出技术评估意见，并对技术评估意见负责，不得向排污单位收取任何费用。 技术机构开展技术评估应当遵守国家相关法律法规、标准规范，保守排污单位商业秘密。"},{"i":21,"n":"第二十一条","txt":"排污单位采用相应污染防治可行技术的，或者新建、改建、扩建建设项目排污单位采用环境影响报告书（表）批准文件要求的污染防治技术的，审批部门可以认为排污单位采用的污染防治设施或者措施能够达到许可排放浓度要求。 不符合前款规定情形的，排污单位可以通过提供监测数据证明其采用的污染防治设施可以达到许可排放浓度要求。监测数据应当通过使用符合国家有关环境监测、计量认证规定和技术规范的监测设备取得；对于国内首次采用的污染防治技术，应当提供工程试验数据予以证明。"},{"i":22,"n":"第二十二条","txt":"对具备下列条件的排污单位，颁发排污许可证： （一）依法取得建设项目环境影响报告书（表）批准文件，或者已经办理环境影响登记表备案手续； （二）污染物排放符合污染物排放标准要求，重点污染物排放符合排污许可证申请与核发技术规范、环境影响报告书（表）批准文件、重点污染物排放总量控制要求；其中，排污单位生产经营场所位于未达到国家环境质量标准的重点区域、流域的，还应当符合有关地方人民政府关于改善生态环境质量的特别要求； （三）采用污染防治设施可以达到许可排放浓度要求或者符合污染防治可行技术； （四）自行监测方案的监测点位、指标、频次等符合国家自行监测规范。"},{"i":23,"n":"第二十三条","txt":"审批部门应当在法定审批期限内作出审批决定，对符合条件的颁发排污许可证；对不符合条件的应当出具不予许可决定书，书面告知排污单位不予许可的理由，以及依法申请行政复议或者提起行政诉讼的权利。 依法需要听证、检验、检测、专家评审的，所需时间不计算在审批期限内，审批部门应当将所需时间书面告知排污单位。"},{"i":24,"n":"第二十四条","txt":"排污单位依照《条例》第十四条第二款规定提出延续排污许可证时，应当按照规定提交延续申请表。审批部门作出延续排污许可证决定的，延续后的排污许可证有效期自原排污许可证有效期届满的次日起计算。 排污单位未依照《条例》第十四条第二款规定提前六十日提交延续申请表，审批部门依法在原排污许可证有效期届满之后作出延续排污许可证决定的，延续后的排污许可证有效期自作出延续决定之日起计算；审批部门依法在原排污许可证有效期届满之前作出延续排污许可证决定的，延续后的排污许可证有效期自原排污许可证有效期届满的次日起计算。"},{"i":25,"n":"第二十五条","txt":"对符合《条例》第十五条规定的应当重新申请排污许可证情形的，排污单位应当在实际排污行为变化之前重新申请取得排污许可证。排污单位应当提交排污许可证申请表、由排污单位法定代表人或者主要负责人签字或者盖章的承诺书以及与重新申请排污许可证有关的其他材料，并说明重新申请原因。 重新申请的排污许可证有效期自审批部门作出重新申请审批决定之日起计算。"},{"i":26,"n":"第二十六条","txt":"排污单位名称、住所、法定代表人或者主要负责人等排污许可证正本中记载的基本信息发生变更的，排污单位应当自变更之日起三十日内，向审批部门提交变更排污许可证申请表以及与变更排污许可证有关的其他材料。 审批部门应当自受理之日起十个工作日内作出变更决定，按规定换发排污许可证正本，相关变更内容载入排污许可证副本中的变更、延续记录。 排污许可证记载信息的变更，不影响排污许可证的有效期。"},{"i":27,"n":"第二十七条","txt":"排污单位适用的污染物排放标准、重点污染物排放总量控制要求发生变化，需要对排污许可证进行变更的，审批部门应当在标准生效之前和总量控制指标变化后依法对排污许可证相应事项进行变更。"},{"i":28,"n":"第二十八条","txt":"除本办法第二十五条、第二十六条、第二十七条规定情形外，排污许可证记载内容发生变化的，排污单位可以主动向审批部门提出调整排污许可证内容的申请，审批部门应当及时对排污许可证记载内容进行调整。"},{"i":29,"n":"第二十九条","txt":"有下列情形之一的，审批部门应当依法办理排污许可证的注销手续，并在全国排污许可证管理信息平台上公告： （一）排污许可证有效期届满未延续的； （二）排污单位依法终止的； （三）排污许可证依法被撤销、吊销的； （四）应当注销的其他情形。"},{"i":30,"n":"第三十条","txt":"有下列情形之一的，可以依法撤销排污许可证，并在全国排污许可证管理信息平台上公告： （一）超越法定职权审批排污许可证的； （二）违反法定程序审批排污许可证的； （三）审批部门工作人员滥用职权、玩忽职守审批排污许可证的； （四）对不具备申请资格或者不符合法定条件的排污单位审批排污许可证的； （五）依法可以撤销排污许可证的其他情形。 排污单位以欺骗、贿赂等不正当手段取得排污许可证的，应当依法予以撤销。"},{"i":31,"n":"第三十一条","txt":"上级生态环境主管部门可以对具有审批权限的下级生态环境主管部门的排污许可证审批和执行情况进行监督检查和指导，发现属于《条例》第三十二条规定违法情形的，上级生态环境主管部门应当责令改正。"},{"i":32,"n":"第三十二条","txt":"排污许可证发生遗失、损毁的，排污单位可以向审批部门申请补领。已经办理排污许可证电子证照的排污单位可以根据需要自行打印排污许可证。"},{"i":33,"n":"第三十三条","txt":"排污单位应当依照《条例》规定，严格落实环境保护主体责任，建立健全环境管理制度，按照排污许可证规定严格控制污染物排放。 排污登记单位应当依照国家生态环境保护法律法规规章等管理规定运行和维护污染防治设施，建设规范化排放口，落实排污主体责任，控制污染物排放。"},{"i":34,"n":"第三十四条","txt":"排污单位应当按照排污许可证规定和有关标准规范，依法开展自行监测，保存原始监测记录。原始监测记录保存期限不得少于五年。 排污单位对自行监测数据的真实性、准确性负责，不得篡改、伪造。"},{"i":35,"n":"第三十五条","txt":"实行排污许可重点管理的排污单位，应当依法安装、使用、维护污染物排放自动监测设备，并与生态环境主管部门的监控设备联网。 排污单位发现污染物排放自动监测设备传输数据异常的，应当及时报告生态环境主管部门，并进行检查、修复。"},{"i":36,"n":"第三十六条","txt":"排污单位应当按照排污许可证规定的格式、内容和频次要求记录环境管理台账，主要包括以下内容： （一）与污染物排放相关的主要生产设施运行情况；发生异常情况的，应当记录原因和采取的措施。 （二）污染防治设施运行情况及管理信息；发生异常情况的，应当记录原因和采取的措施。 （三）污染物实际排放浓度和排放量；发生超标排放情况的，应当记录超标原因和采取的措施。 （四）其他按照相关技术规范应当记录的信息。 环境管理台账记录保存期限不得少于五年。"},{"i":37,"n":"第三十七条","txt":"排污单位应当按照排污许可证规定的执行报告内容、频次和时间要求，在全国排污许可证管理信息平台上填报、提交排污许可证执行报告。 排污许可证执行报告包括年度执行报告、季度执行报告和月执行报告。 季度执行报告和月执行报告应当包括以下内容： （一）根据自行监测结果说明污染物实际排放浓度和排放量及达标判定分析； （二）排污单位超标排放或者污染防治设施异常情况的说明。 年度执行报告可以替代当季度或者当月的执行报告，并增加以下内容： （一）排污单位基本生产信息； （二）污染防治设施运行情况； （三）自行监测执行情况； （四）环境管理台账记录执行情况； （五）信息公开情况； （六）排污单位内部环境管理体系建设与运行情况； （七）其他排污许可证规定的内容执行情况。 建设项目竣工环境保护设施验收报告中污染源监测数据等与污染物排放相关的主要内容，应当由排污单位记载在该项目竣工环境保护设施验收完成当年的排污许可"},{"i":38,"n":"第三十八条","txt":"排污单位应当按照排污许可证规定，如实在全国排污许可证管理信息平台上公开污染物排放信息。 污染物排放信息应当包括污染物排放种类、排放浓度和排放量，以及污染防治设施的建设运行情况、排污许可证执行报告、自行监测数据等；水污染物排入市政排水管网的，还应当包括污水接入市政排水管网位置、排放方式等信息。"},{"i":39,"n":"第三十九条","txt":"排污登记单位应当在实际排污行为发生之前，通过全国排污许可证管理信息平台填报排污登记表，提交后即时生成登记编号和回执，由排污登记单位自行留存。排污登记单位应当对填报信息的真实性、准确性、完整性负责。 排污登记表自获得登记编号之日起生效，有效期限依照相关法律法规规定执行。 排污登记信息发生变动的，排污登记单位应当自发生变动之日起二十日内进行变更登记。 排污登记单位因关闭等原因不再排污的，应当及时在全国排污许可证管理信息平台注销排污登记表。 排污登记单位因生产和排污情况发生变化等原因，依法需要申领排污许可证的，应当依照相关法律法规和本办法的规定及时申请取得排污许可证并注销排污登记表。"},{"i":40,"n":"第四十条","txt":"生态环境主管部门应当将排污许可证和排污登记信息纳入执法监管数据库，将排污许可执法检查纳入生态环境执法年度计划，加强对排污许可证记载事项的清单式执法检查。 对未取得排污许可证排放污染物、不按照排污许可证要求排放污染物、未按规定填报排污登记表等违反排污许可管理的行为，依照相关法律法规和《条例》有关规定进行处理。"},{"i":41,"n":"第四十一条","txt":"生态环境主管部门应当定期组织开展排污许可证执行报告落实情况的检查，重点检查排污单位提交执行报告的及时性、报告内容的完整性、排污行为的合规性、污染物排放量数据的准确性以及各项管理要求的落实情况等内容。 排污许可证执行报告检查依托全国排污许可证管理信息平台开展。生态环境主管部门可以要求排污单位补充提供环境管理台账记录、自行监测数据等相关材料，必要时可以组织开展现场核查。"},{"i":42,"n":"第四十二条","txt":"生态环境主管部门应当加强排污许可证质量管理，建立质量审核机制，定期开展排污许可证质量核查。"},{"i":43,"n":"第四十三条","txt":"排污单位应当树立持证排污、按证排污意识，及时公开排污信息，自觉接受公众监督。 鼓励社会公众依法参与监督排污单位和排污登记单位排污行为。任何单位和个人对违反本办法规定的行为，均有权向生态环境主管部门举报。接到举报的生态环境主管部门应当依法处理，按照有关规定向举报人反馈处理结果，并为举报人保密。"},{"i":44,"n":"第四十四条","txt":"排污许可证正本、副本、承诺书样本和申请、延续、变更排污许可证申请表格式，由国务院生态环境主管部门制定。"},{"i":45,"n":"第四十五条","txt":"排污单位涉及国家秘密的，其排污许可、排污登记及相关的监督管理等应当遵守国家有关保密法律法规的规定。"},{"i":46,"n":"第四十六条","txt":"本办法自2024年7月1日起施行。原环境保护部发布的《排污许可管理办法（试行）》（环境保护部令第48号）同时废止。"}],"fangshexingtongweisuyushexianzhuangzhianquanhefangc8b6ae":[{"i":1,"n":"第一条","txt":"为了加强放射性同位素与射线装置的安全和防护管理，根据《中华人民共和国放射性污染防治法》和《放射性同位素与射线装置安全和防护条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于生产、销售、使用放射性同位素与射线装置的场所、人员的安全和防护，废旧放射源与被放射性污染的物品的管理以及豁免管理等相关活动。"},{"i":3,"n":"第三条","txt":"生产、销售、使用放射性同位素与射线装置的单位，应当对本单位的放射性同位素与射线装置的辐射安全和防护工作负责，并依法对其造成的放射性危害承担责任。"},{"i":4,"n":"第四条","txt":"县级以上人民政府环境保护主管部门，应当依照《中华人民共和国放射性污染防治法》、《放射性同位素与射线装置安全和防护条例》和本办法的规定，对放射性同位素与射线装置的安全和防护工作实施监督管理。"},{"i":5,"n":"第五条","txt":"生产、销售、使用、贮存放射性同位素与射线装置的场所，应当按照国家有关规定设置明显的放射性标志，其入口处应当按照国家有关安全和防护标准的要求，设置安全和防护设施以及必要的防护安全联锁、报警装置或者工作信号。 射线装置的生产调试和使用场所，应当具有防止误操作、防止工作人员和公众受到意外照射的安全措施。 放射性同位素的包装容器、含放射性同位素的设备和射线装置，应当设置明显的放射性标识和中文警示说明；放射源上能够设置放射性标识的，应当一并设置。运输放射性同位素和含放射源的射线装置的工具，应当按照国家有关规定设置明显的放射性标志或者显示危险信号。"},{"i":6,"n":"第六条","txt":"生产、使用放射性同位素与射线装置的场所，应当按照国家有关规定采取有效措施，防止运行故障，并避免故障导致次生危害。"},{"i":7,"n":"第七条","txt":"放射性同位素和被放射性污染的物品应当单独存放，不得与易燃、易爆、腐蚀性物品等一起存放，并指定专人负责保管。 贮存、领取、使用、归还放射性同位素时，应当进行登记、检查，做到账物相符。对放射性同位素贮存场所应当采取防火、防水、防盗、防丢失、防破坏、防射线泄漏的安全措施。 对放射源还应当根据其潜在危害的大小，建立相应的多重防护和安全措施，并对可移动的放射源定期进行盘存，确保其处于指定位置，具有可靠的安全保障。"},{"i":8,"n":"第八条","txt":"在室外、野外使用放射性同位素与射线装置的，应当按照国家安全和防护标准的要求划出安全防护区域，设置明显的放射性标志，必要时设专人警戒。"},{"i":9,"n":"第九条","txt":"生产、销售、使用放射性同位素与射线装置的单位，应当按照国家环境监测规范，对相关场所进行辐射监测，并对监测数据的真实性、可靠性负责；不具备自行监测能力的，可以委托经省级人民政府环境保护主管部门认定的环境监测机构进行监测。"},{"i":10,"n":"第十条","txt":"建设项目竣工环境保护验收涉及的辐射监测和退役核技术利用项目的终态辐射监测，由生产、销售、使用放射性同位素与射线装置的单位委托经省级以上人民政府环境保护主管部门批准的有相应资质的辐射环境监测机构进行。"},{"i":11,"n":"第十一条","txt":"生产、销售、使用放射性同位素与射线装置的单位，应当加强对本单位放射性同位素与射线装置安全和防护状况的日常检查。发现安全隐患的，应当立即整改；安全隐患有可能威胁到人员安全或者有可能造成环境污染的，应当立即停止辐射作业并报告发放辐射安全许可证的环境保护主管部门（以下简称“发证机关”），经发证机关检查核实安全隐患消除后，方可恢复正常作业。"},{"i":12,"n":"第十二条","txt":"生产、销售、使用放射性同位素与射线装置的单位，应当对本单位的放射性同位素与射线装置的安全和防护状况进行年度评估，并于每年1月31日前向发证机关提交上一年度的评估报告。 安全和防护状况年度评估报告应当包括下列内容： （一）辐射安全和防护设施的运行与维护情况； （二）辐射安全和防护制度及措施的制定与落实情况； （三）辐射工作人员变动及接受辐射安全和防护知识教育培训（以下简称“辐射安全培训”）情况； （四）放射性同位素进出口、转让或者送贮情况以及放射性同位素、射线装置台账； （五）场所辐射环境监测和个人剂量监测情况及监测数据； （六）辐射事故及应急响应情况； （七）核技术利用项目新建、改建、扩建和退役情况； （八）存在的安全隐患及其整改情况； （九）其他有关法律、法规规定的落实情况。 年度评估发现安全隐患的，应当立即整改。"},{"i":13,"n":"第十三条","txt":"使用Ⅰ类、Ⅱ类、Ⅲ类放射源的场所，生产放射性同位素的场所，按照《电离辐射防护与辐射源安全基本标准》（以下简称《基本标准》）确定的甲级、乙级非密封放射性物质使用场所，以及终结运行后产生放射性污染的射线装置，应当依法实施退役。 依照前款规定实施退役的生产、使用放射性同位素与射线装置的单位，应当在实施退役前完成下列工作： （一）将有使用价值的放射源按照《放射性同位素与射线装置安全和防护条例》的规定转让； （二）将废旧放射源交回生产单位、返回原出口方或者送交有相应资质的放射性废物集中贮存单位贮存。"},{"i":14,"n":"第十四条","txt":"依法实施退役的生产、使用放射性同位素与射线装置的单位，应当在实施退役前编制环境影响评价文件，报原辐射安全许可证发证机关审查批准；未经批准的，不得实施退役。"},{"i":15,"n":"第十五条","txt":"退役工作完成后六十日内，依法实施退役的生产、使用放射性同位素与射线装置的单位，应当向原辐射安全许可证发证机关申请退役核技术利用项目终态验收，并提交退役项目辐射环境终态监测报告或者监测表。 依法实施退役的生产、使用放射性同位素与射线装置的单位，应当自终态验收合格之日起二十日内，到原发证机关办理辐射安全许可证变更或者注销手续。"},{"i":16,"n":"第十六条","txt":"生产、销售、使用放射性同位素与射线装置的单位，在依法被撤销、依法解散、依法破产或者因其他原因终止前，应当确保环境辐射安全，妥善实施辐射工作场所或者设备的退役，并承担退役完成前所有的安全责任。"},{"i":17,"n":"第十七条","txt":"生产、销售、使用放射性同位素与射线装置的单位，应当按照环境保护部审定的辐射安全培训和考试大纲，对直接从事生产、销售、使用活动的操作人员以及辐射防护负责人进行辐射安全培训，并进行考核；考核不合格的，不得上岗。"},{"i":18,"n":"第十八条","txt":"辐射安全培训分为高级、中级和初级三个级别。 从事下列活动的辐射工作人员，应当接受中级或者高级辐射安全培训: （一）生产、销售、使用Ⅰ类放射源的； （二）在甲级非密封放射性物质工作场所操作放射性同位素的； （三）使用Ⅰ类射线装置的； （四）使用伽玛射线移动探伤设备的。 从事前款所列活动单位的辐射防护负责人，以及从事前款所列装置、设备和场所设计、安装、调试、倒源、维修以及其他与辐射安全相关技术服务活动的人员，应当接受中级或者高级辐射安全培训。 本条第二款、第三款规定以外的其他辐射工作人员，应当接受初级辐射安全培训。"},{"i":19,"n":"第十九条","txt":"从事辐射安全培训的单位，应当具备下列条件： （一）有健全的培训管理制度并有专职培训管理人员； （二）有常用的辐射监测设备； （三）有与培训规模相适应的教学、实践场地与设施； （四）有核物理、辐射防护、核技术应用及相关专业本科以上学历的专业教师。 拟开展初级辐射安全培训的单位，应当有五名以上专业教师，其中至少两名具有注册核安全工程师执业资格。 拟开展中级或者高级辐射安全培训的单位，应当有十名以上专业教师，其中至少五名具有注册核安全工程师执业资格，外聘教师不得超过教师总数的30%。 从事辐射安全培训的专业教师应当接受环境保护部组织的培训，具体办法由环境保护部另行制定。"},{"i":20,"n":"第二十条","txt":"省级以上人民政府环境保护主管部门对从事辐射安全培训的单位进行评估，择优向社会推荐。 环境保护部评估并推荐的单位可以开展高级、中级和初级辐射安全培训；省级人民政府环境保护主管部门评估并推荐的单位可以开展初级辐射安全培训。 省级以上人民政府环境保护主管部门应当向社会公布其推荐的从事辐射安全培训的单位名单，并定期对名单所列从事辐射安全培训的单位进行考核；对考核不合格的，予以除名，并向社会公告。"},{"i":21,"n":"第二十一条","txt":"从事辐射安全培训的单位负责对参加辐射安全培训的人员进行考核，并对考核合格的人员颁发辐射安全培训合格证书。辐射安全培训合格证书的格式由环境保护部规定。 取得高级别辐射安全培训合格证书的人员，不需再接受低级别的辐射安全培训。"},{"i":22,"n":"第二十二条","txt":"取得辐射安全培训合格证书的人员，应当每四年接受一次再培训。 辐射安全再培训包括新颁布的相关法律、法规和辐射安全与防护专业标准、技术规范，以及辐射事故案例分析与经验反馈等内容。 不参加再培训的人员或者再培训考核不合格的人员，其辐射安全培训合格证书自动失效。"},{"i":23,"n":"第二十三条","txt":"生产、销售、使用放射性同位素与射线装置的单位，应当按照法律、行政法规以及国家环境保护和职业卫生标准，对本单位的辐射工作人员进行个人剂量监测；发现个人剂量监测结果异常的，应当立即核实和调查，并将有关情况及时报告辐射安全许可证发证机关。 生产、销售、使用放射性同位素与射线装置的单位，应当安排专人负责个人剂量监测管理，建立辐射工作人员个人剂量档案。个人剂量档案应当包括个人基本信息、工作岗位、剂量监测结果等材料。个人剂量档案应当保存至辐射工作人员年满七十五周岁，或者停止辐射工作三十年。 辐射工作人员有权查阅和复制本人的个人剂量档案。辐射工作人员调换单位的，原用人单位应当向新用人单位或者辐射工作人员本人提供个人剂量档案的复制件。"},{"i":24,"n":"第二十四条","txt":"生产、销售、使用放射性同位素与射线装置的单位，不具备个人剂量监测能力的，应当委托具备下列条件的机构进行个人剂量监测： （一）具有保证个人剂量监测质量的设备、技术； （二）经省级以上人民政府计量行政主管部门计量认证； （三）法律法规规定的从事个人剂量监测的其他条件。"},{"i":25,"n":"第二十五条","txt":"环境保护部对从事个人剂量监测的机构进行评估，择优向社会推荐。 环境保护部定期对其推荐的从事个人剂量监测的机构进行监测质量考核；对考核不合格的，予以除名，并向社会公告。"},{"i":26,"n":"第二十六条","txt":"接受委托进行个人剂量监测的机构，应当按照国家有关技术规范的要求进行个人剂量监测，并对监测结果负责。 接受委托进行个人剂量监测的机构，应当及时向委托单位出具监测报告，并将监测结果以书面和网上报送方式，直接报告委托单位所在地的省级人民政府环境保护主管部门。"},{"i":27,"n":"第二十七条","txt":"环境保护部应当建立全国统一的辐射工作人员个人剂量数据库，并与卫生等相关部门实现数据共享。"},{"i":28,"n":"第二十八条","txt":"生产、进口放射源的单位销售Ⅰ类、Ⅱ类、Ⅲ类放射源给其他单位使用的，应当与使用放射源的单位签订废旧放射源返回协议。 转让Ⅰ类、Ⅱ类、Ⅲ类放射源的，转让双方应当签订废旧放射源返回协议。进口放射源转让时，转入单位应当取得原出口方负责回收的承诺文件副本。"},{"i":29,"n":"第二十九条","txt":"使用Ⅰ类、Ⅱ类、Ⅲ类放射源的单位应当在放射源闲置或者废弃后三个月内，按照废旧放射源返回协议规定，将废旧放射源交回生产单位或者返回原出口方。确实无法交回生产单位或者返回原出口方的，送交具备相应资质的放射性废物集中贮存单位（以下简称“废旧放射源收贮单位”）贮存，并承担相关费用。 废旧放射源收贮单位，应当依法取得环境保护部颁发的使用（含收贮）辐射安全许可证，并在资质许可范围内收贮废旧放射源和被放射性污染的物品。"},{"i":30,"n":"第三十条","txt":"使用放射源的单位依法被撤销、依法解散、依法破产或者因其他原因终止的，应当事先将本单位的放射源依法转让、交回生产单位、返回原出口方或者送交废旧放射源收贮单位贮存，并承担上述活动完成前所有的安全责任。"},{"i":31,"n":"第三十一条","txt":"使用放射源的单位应当在废旧放射源交回生产单位或者送交废旧放射源收贮单位贮存活动完成之日起二十日内，报其所在地的省级人民政府环境保护主管部门备案。 废旧放射源返回原出口方的，应当在返回活动完成之日起二十日内，将放射性同位素出口表报其所在地的省级人民政府环境保护主管部门备案。"},{"i":32,"n":"第三十二条","txt":"废旧放射源收贮单位，应当建立废旧放射源的收贮台账和相应的计算机管理系统。 废旧放射源收贮单位，应当于每季度末对已收贮的废旧放射源进行汇总统计，每年年底对已贮存的废旧放射源进行核实，并将统计和核实结果分别上报环境保护部和所在地省级人民政府环境保护主管部门。"},{"i":33,"n":"第三十三条","txt":"对已经收贮入库或者交回生产单位的仍有使用价值的放射源，可以按照《放射性同位素与射线装置安全和防护条例》的规定办理转让手续后进行再利用。具体办法由环境保护部另行制定。 对拟被再利用的放射源，应当由放射源生产单位按照生产放射源的要求进行安全性验证或者加工，满足安全和技术参数要求后，出具合格证书，明确使用条件，并进行放射源编码。"},{"i":34,"n":"第三十四条","txt":"单位和个人发现废弃放射源或者被放射性污染的物品的，应当及时报告所在地县级以上地方人民政府环境保护主管部门；经所在地省级人民政府环境保护主管部门同意后，送废旧放射源收贮单位贮存。 废旧放射源收贮单位应当对废弃放射源或者被放射性污染的物品妥善收贮。 禁止擅自转移、贮存、退运废弃放射源或者被放射性污染的物品。"},{"i":35,"n":"第三十五条","txt":"废旧金属回收熔炼企业，应当建立辐射监测系统，配备足够的辐射监测人员，在废旧金属原料入炉前、产品出厂前进行辐射监测，并将放射性指标纳入产品合格指标体系中。 新建、改建、扩建建设项目含有废旧金属回收熔炼工艺的，应当配套建设辐射监测设施；未配套建设辐射监测设施的，环境保护主管部门不予通过其建设项目竣工环境保护验收。 辐射监测人员在进行废旧金属辐射监测和应急处理时，应当佩戴个人剂量计等防护器材，做好个人防护。"},{"i":36,"n":"第三十六条","txt":"废旧金属回收熔炼企业发现并确认辐射监测结果明显异常时，应当立即采取相应控制措施并在四小时内向所在地县级以上人民政府环境保护主管部门报告。 环境保护主管部门接到报告后，应当对辐射监测结果进行核实，查明导致辐射水平异常的原因，并责令废旧金属回收熔炼企业采取措施，防止放射性污染。 禁止缓报、瞒报、谎报或者漏报辐射监测结果异常信息。"},{"i":37,"n":"第三十七条","txt":"废旧金属回收熔炼企业送贮废弃放射源或者被放射性污染物品所产生的费用，由废弃放射源或者被放射性污染物品的原持有者或者供货方承担。 无法查明废弃放射源或者被放射性污染物品来源的，送贮费用由废旧金属回收熔炼企业承担；其中，对已经开展辐射监测的废旧金属回收熔炼企业，经所在地省级人民政府环境保护主管部门核实、同级财政部门同意后，省级人民政府环境保护主管部门所属废旧放射源收贮单位可以酌情减免其相关处理费用。"},{"i":38,"n":"第三十八条","txt":"省级以上人民政府环境保护主管部门应当对其依法颁发辐射安全许可证的单位进行监督检查。 省级以上人民政府环境保护主管部门委托下一级环境保护主管部门颁发辐射安全许可证的，接受委托的环境保护主管部门应当对其颁发辐射安全许可证的单位进行监督检查。"},{"i":39,"n":"第三十九条","txt":"县级以上人民政府环境保护主管部门应当结合本行政区域的工作实际，配备辐射防护安全监督员。 各级辐射防护安全监督员应当具备三年以上辐射工作相关经历。 省级以上人民政府环境保护主管部门辐射防护安全监督员应当具备大学本科以上学历，并通过中级以上辐射安全培训。 设区的市级、县级人民政府环境保护主管部门辐射防护安全监督员应当具备大专以上学历，并通过初级以上辐射安全培训。"},{"i":40,"n":"第四十条","txt":"省级以上人民政府环境保护主管部门辐射防护安全监督员由环境保护部认可，设区的市级、县级人民政府环境保护主管部门辐射防护安全监督员由省级人民政府环境保护主管部门认可。 辐射防护安全监督员应当定期接受专业知识培训和考核。 取得高级职称并从事辐射安全与防护监督检查工作十年以上，或者取得注册核安全工程师资格的辐射防护安全监督员，可以免予辐射安全培训。"},{"i":41,"n":"第四十一条","txt":"省级以上人民政府环境保护主管部门应当制定监督检查大纲，明确辐射安全与防护监督检查的组织体系、职责分工、实施程序、报告制度、重要问题管理等内容，并根据国家相关法律法规、标准制定相应的监督检查技术程序。"},{"i":42,"n":"第四十二条","txt":"县级以上人民政府环境保护主管部门应当根据放射性同位素与射线装置生产、销售、使用活动的类别，制定本行政区域的监督检查计划。 监督检查计划应当按照辐射安全风险大小，规定不同的监督检查频次。"},{"i":43,"n":"第四十三条","txt":"县级以上人民政府环境保护主管部门应当会同同级公安、卫生、财政、新闻、宣传等部门编制辐射事故应急预案，报本级人民政府批准。 辐射事故应急预案应当包括下列内容： （一）应急机构和职责分工； （二）应急人员的组织、培训以及应急和救助的装备、资金、物资准备； （三）辐射事故分级与应急响应措施； （四）辐射事故的调查、报告和处理程序； （五）辐射事故信息公开、公众宣传方案。 辐射事故应急预案还应当包括可能引发辐射事故的运行故障的应急响应措施及其调查、报告和处理程序。 生产、销售、使用放射性同位素与射线装置的单位，应当根据可能发生的辐射事故的风险，制定本单位的应急方案，做好应急准备。"},{"i":44,"n":"第四十四条","txt":"发生辐射事故或者发生可能引发辐射事故的运行故障时，生产、销售、使用放射性同位素与射线装置的单位应当立即启动本单位的应急方案，采取应急措施，并在两小时内填写初始报告，向当地人民政府环境保护主管部门报告。 发生辐射事故的，生产、销售、使用放射性同位素与射线装置的单位还应当同时向当地人民政府、公安部门和卫生主管部门报告。"},{"i":45,"n":"第四十五条","txt":"接到辐射事故或者可能引发辐射事故的运行故障报告的环境保护主管部门，应当立即派人赶赴现场，进行现场调查，采取有效措施，控制并消除事故或者故障影响，并配合有关部门做好信息公开、公众宣传等外部应急响应工作。"},{"i":46,"n":"第四十六条","txt":"接到辐射事故报告或者可能发生辐射事故的运行故障报告的环境保护部门，应当在两小时内，将辐射事故或者故障信息报告本级人民政府并逐级上报至省级人民政府环境保护主管部门；发生重大或者特别重大辐射事故的，应当同时向环境保护部报告。 接到含Ⅰ类放射源装置重大运行故障报告的环境保护部门，应当在两小时内将故障信息逐级上报至原辐射安全许可证发证机关。"},{"i":47,"n":"第四十七条","txt":"省级人民政府环境保护主管部门接到辐射事故报告，确认属于特别重大辐射事故或者重大辐射事故的，应当及时通报省级人民政府公安部门和卫生主管部门，并在两小时内上报环境保护部。 环境保护部在接到事故报告后，应当立即组织核实，确认事故类型，在两小时内报告国务院，并通报公安部和卫生部。"},{"i":48,"n":"第四十八条","txt":"发生辐射事故或者运行故障的单位，应当按照应急预案的要求，制定事故或者故障处置实施方案，并在当地人民政府和辐射安全许可证发证机关的监督、指导下实施具体处置工作。 辐射事故和运行故障处置过程中的安全责任，以及由事故、故障导致的应急处置费用，由发生辐射事故或者运行故障的单位承担。"},{"i":49,"n":"第四十九条","txt":"省级人民政府环境保护主管部门应当每半年对本行政区域内发生的辐射事故和运行故障情况进行汇总，并将汇总报告报送环境保护部，同时抄送同级公安部门和卫生主管部门。"},{"i":50,"n":"第五十条","txt":"省级以上人民政府环境保护主管部门依据《基本标准》及国家有关规定，负责对射线装置、放射源或者非密封放射性物质管理的豁免出具备案证明文件。"},{"i":51,"n":"第五十一条","txt":"已经取得辐射安全许可证的单位，使用低于《基本标准》规定豁免水平的射线装置、放射源或者少量非密封放射性物质的，经所在地省级人民政府环境保护主管部门备案后，可以被豁免管理。 前款所指单位提请所在地省级人民政府环境保护主管部门备案时，应当提交其使用的射线装置、放射源或者非密封放射性物质辐射水平低于《基本标准》豁免水平的证明材料。"},{"i":52,"n":"第五十二条","txt":"符合下列条件之一的使用单位，报请所在地省级人民政府环境保护主管部门备案时，除提交本办法第五十一条第二款规定的证明材料外，还应当提交射线装置、放射源或者非密封放射性物质的使用量、使用条件、操作方式以及防护管理措施等情况的证明： （一）已取得辐射安全许可证，使用较大批量低于《基本标准》规定豁免水平的非密封放射性物质的； （二）未取得辐射安全许可证，使用低于《基本标准》规定豁免水平的射线装置、放射源以及非密封放射性物质的。"},{"i":53,"n":"第五十三条","txt":"对装有超过《基本标准》规定豁免水平放射源的设备，经检测符合国家有关规定确定的辐射水平的，设备的生产或者进口单位向环境保护部报请备案后，该设备和相关转让、使用活动可以被豁免管理。 前款所指单位，报请环境保护部备案时，应当提交下列材料： （一）辐射安全分析报告，包括活动正当性分析，放射源在设备中的结构，放射源的核素名称、活度、加工工艺和处置方式，对公众和环境的潜在辐射影响，以及可能的用户等内容。 （二）有相应资质的单位出具的证明设备符合《基本标准》有条件豁免要求的辐射水平检测报告。"},{"i":54,"n":"第五十四条","txt":"省级人民政府环境保护主管部门应当将其出具的豁免备案证明文件，报环境保护部。 环境保护部对已获得豁免备案证明文件的活动或者活动中的射线装置、放射源或者非密封放射性物质定期公告。 经环境保护部公告的活动或者活动中的射线装置、放射源或者非密封放射性物质，在全国有效，可以不再逐一办理豁免备案证明文件。"},{"i":55,"n":"第五十五条","txt":"违反本办法规定，生产、销售、使用放射性同位素与射线装置的单位有下列行为之一的，由原辐射安全许可证发证机关给予警告，责令限期改正；逾期不改正的，处一万元以上三万元以下的罚款： （一）未按规定对相关场所进行辐射监测的； （二）未按规定时间报送安全和防护状况年度评估报告的； （三）未按规定对辐射工作人员进行辐射安全培训的； （四）未按规定开展个人剂量监测的； （五）发现个人剂量监测结果异常，未进行核实与调查，并未将有关情况及时报告原辐射安全许可证发证机关的。"},{"i":56,"n":"第五十六条","txt":"违反本办法规定，废旧放射源收贮单位有下列行为之一的，由省级以上人民政府环境保护主管部门责令停止违法行为，限期改正；逾期不改正的，由原发证机关收回辐射安全许可证： （一）未按规定建立废旧放射源收贮台账和计算机管理系统的； （二）未按规定对已收贮的废旧放射源进行统计，并将统计结果上报的。"},{"i":57,"n":"第五十七条","txt":"违反本办法规定，废旧放射源收贮单位有下列行为之一的，依照《放射性同位素与射线装置安全和防护条例》第五十二条的有关规定，由县级以上人民政府环境保护主管部门责令停止违法行为，限期改正；逾期不改正的，责令停业或者由原发证机关吊销辐射安全许可证；有违法所得的，没收违法所得；违法所得十万元以上的，并处违法所得一倍以上五倍以下的罚款；没有违法所得或者违法所得不足十万元的，并处一万元以上十万元以下的罚款。 （一）未取得环境保护部颁发的使用（含收贮）辐射安全许可证，从事废旧放射源收贮的； （二）未经批准，擅自转让已收贮入库废旧放射源的。"},{"i":58,"n":"第五十八条","txt":"违反本办法规定，废旧金属回收熔炼企业未开展辐射监测或者发现辐射监测结果明显异常未如实报告的，由县级以上人民政府环境保护主管部门责令改正，处一万元以上三万元以下的罚款。"},{"i":59,"n":"第五十九条","txt":"生产、销售、使用放射性同位素与射线装置的单位违反本办法的其他规定，按照《中华人民共和国放射性污染防治法》、《放射性同位素与射线装置安全和防护条例》以及其他相关法律法规的规定进行处罚。"},{"i":60,"n":"第六十条","txt":"本办法下列用语的含义： （一）废旧放射源，是指已超过生产单位或者有关标准规定的使用寿命，或者由于生产工艺的改变、生产产品的更改等因素致使不再用于初始目的的放射源。 （二）退役，是指采取去污、拆除和清除等措施，使核技术利用项目不再使用的场所或者设备的辐射剂量满足国家相关标准的要求，主管部门不再对这些核技术利用项目进行辐射安全与防护监管。"},{"i":61,"n":"第六十一条","txt":"本办法自2011年 5月1日起施行。"}],"fangshexingtongweisuyushexianzhuangzhianquanxukegu4b9f7e":[{"i":1,"n":"第一条","txt":"为实施《放射性同位素与射线装置安全和防护条例》规定的辐射安全许可制度，制定本办法。"},{"i":2,"n":"第二条","txt":"在中华人民共和国境内生产、销售、使用放射性同位素与射线装置的单位（以下简称“辐射工作单位”），应当依照本办法的规定，取得辐射安全许可证（以下简称“许可证”）。 进口、转让放射性同位素，进行放射性同位素野外示踪试验，应当依照本办法的规定报批。 出口放射性同位素,应当依照本办法的规定办理有关手续。 使用放射性同位素的单位将放射性同位素转移到外省、自治区、直辖市使用的，应当依照本办法的规定备案。 本办法所称放射性同位素包括放射源和非密封放射性物质。"},{"i":3,"n":"第三条","txt":"根据放射源与射线装置对人体健康和环境的潜在危害程度，从高到低，将放射源分为Ⅰ类、Ⅱ类、Ⅲ类、Ⅳ类、Ⅴ类，将射线装置分为Ⅰ类、Ⅱ类、Ⅲ类。"},{"i":4,"n":"第四条","txt":"除医疗使用Ⅰ类放射源、制备正电子发射计算机断层扫描用放射性药物自用的单位外，生产放射性同位素、销售和使用Ⅰ类放射源、销售和使用Ⅰ类射线装置的辐射工作单位的许可证，由国务院生态环境主管部门审批颁发。 除国务院生态环境主管部门审批颁发的许可证外，其他辐射工作单位的许可证，由省、自治区、直辖市人民政府生态环境主管部门审批颁发。 一个辐射工作单位生产、销售、使用多类放射源、射线装置或者非密封放射性物质的，只需要申请一个许可证。 辐射工作单位需要同时分别向国务院生态环境主管部门和省级生态环境主管部门申请许可证的，其许可证由国务院生态环境主管部门审批颁发。 生态环境主管部门应当将审批颁发许可证的情况通报同级公安部门、卫生主管部门。"},{"i":5,"n":"第五条","txt":"省级以上人民政府生态环境主管部门可以委托下一级人民政府生态环境主管部门审批颁发许可证。"},{"i":6,"n":"第六条","txt":"国务院生态环境主管部门负责对列入限制进出口目录的放射性同位素的进口进行审批。 国务院生态环境主管部门依照我国有关法律和缔结或者参加的国际条约、协定的规定，办理列入限制进出口目录的放射性同位素出口的有关手续。 省级生态环境主管部门负责以下活动的审批或备案： （一）转让放射性同位素； （二）转移放射性同位素到外省、自治区、直辖市使用； （三）放射性同位素野外示踪试验；但有可能造成跨省界环境影响的放射性同位素野外示踪试验,由国务院生态环境主管部门审批。"},{"i":7,"n":"第七条","txt":"辐射工作单位在申请领取许可证前，应当组织编制或者填报环境影响评价文件，并依照国家规定程序报生态环境主管部门审批。"},{"i":8,"n":"第八条","txt":"根据放射性同位素与射线装置的安全和防护要求及其对环境的影响程度，对环境影响评价文件实行分类管理。 转让放射性同位素和射线装置的活动不需要编制环境影响评价文件。"},{"i":9,"n":"第九条","txt":"申请领取许可证的辐射工作单位从事下列活动的，应当组织编制环境影响报告书： （一）生产放射性同位素的（制备PET用放射性药物的除外）； （二）使用Ⅰ类放射源的（医疗使用的除外）； （三）销售（含建造）、使用Ⅰ类射线装置的。"},{"i":10,"n":"第十条","txt":"申请领取许可证的辐射工作单位从事下列活动的，应当组织编制环境影响报告表： （一）制备PET用放射性药物的； （二）销售Ⅰ类、Ⅱ类、Ⅲ类放射源的； （三）医疗使用Ⅰ类放射源的； （四）使用Ⅱ类、Ⅲ类放射源的； （五）生产、销售、使用Ⅱ类射线装置的。"},{"i":11,"n":"第十一条","txt":"申请领取许可证的辐射工作单位从事下列活动的，应当填报环境影响登记表： （一）销售、使用Ⅳ类、Ⅴ类放射源的； （二）生产、销售、使用Ⅲ类射线装置的。"},{"i":12,"n":"第十二条","txt":"辐射工作单位组织编制或者填报环境影响评价文件时，应当按照其规划设计的放射性同位素与射线装置的生产、销售、使用规模进行评价。 前款所称的环境影响评价文件，除按照国家有关环境影响评价的要求编制或者填报外，还应当包括对辐射工作单位从事相应辐射活动的技术能力、辐射安全和防护措施进行评价的内容。"},{"i":13,"n":"第十三条","txt":"生产放射性同位素的单位申请领取许可证，应当具备下列条件 （一）设有专门的辐射安全与环境保护管理机构。 （二）有不少于5名核物理、放射化学、核医学和辐射防护等相关专业的技术人员，其中具有高级职称的不少于1名。 生产半衰期大于60天的放射性同位素的单位，前项所指的专业技术人员应当不少于30名，其中具有高级职称的不少于6名。 （三）从事辐射工作的人员必须通过辐射安全和防护专业知识及相关法律法规的培训和考核，其中辐射安全关键岗位应当由注册核安全工程师担任。 （四）有与设计生产规模相适应，满足辐射安全和防护、实体保卫要求的放射性同位素生产场所、生产设施、暂存库或暂存设备，并拥有生产场所和生产设施的所有权。 （五）具有符合国家相关规定要求的运输、贮存放射性同位素的包装容器 （六）具有符合国家放射性同位素运输要求的运输工具，并配备有5年以上驾龄的专职司机。 （七）配备与辐射类型和辐射水平相适应的防护"},{"i":14,"n":"第十四条","txt":"销售放射性同位素的单位申请领取许可证，应当具备下列条件 （一）设有专门的辐射安全与环境保护管理机构,或者至少有1名具有本科以上学历的技术人员专职负责辐射安全与环境保护管理工作。 （二）从事辐射工作的人员必须通过辐射安全和防护专业知识及相关法律法规的培训和考核。 （三）需要暂存放射性同位素的，有满足辐射安全和防护、实体保卫要求的暂存库或设备。 （四）需要安装调试放射性同位素的，有满足防止误操作、防止工作人员和公众受到意外照射要求的安装调试场所。 （五）具有符合国家相关规定要求的贮存、运输放射性同位素的包装容器。 （六）运输放射性同位素能使用符合国家放射性同位素运输要求的运输工 （七）配备与辐射类型和辐射水平相适应的防护用品和监测仪器，包括个人剂量测量报警、便携式辐射监测、表面污染监测等仪器。 （八）有健全的操作规程、岗位职责、安全保卫制度、辐射防护措施、台帐管理制度、人员培训计划和监测方"},{"i":15,"n":"第十五条","txt":"生产、销售射线装置的单位申请领取许可证，应当具备下列条件： （一）设有专门的辐射安全与环境保护管理机构，或至少有1名具有本科以上学历的技术人员专职负责辐射安全与环境保护管理工作。 （二）从事辐射工作的人员必须通过辐射安全和防护专业知识及相关法律法规的培训和考核。 （三）射线装置生产、调试场所满足防止误操作、防止工作人员和公众受到意外照射的安全要求。 （四）配备必要的防护用品和监测仪器。 （五）有健全的操作规程、岗位职责、辐射防护措施、台帐管理制度、培训计划和监测方案。 （六）有辐射事故应急措施。"},{"i":16,"n":"第十六条","txt":"使用放射性同位素、射线装置的单位申请领取许可证，应当具备下列条件： （一）使用Ⅰ类、Ⅱ类、Ⅲ类放射源，使用Ⅰ类、Ⅱ类射线装置的，应当设有专门的辐射安全与环境保护管理机构,或者至少有1名具有本科以上学历的技术人员专职负责辐射安全与环境保护管理工作；其他辐射工作单位应当有1名具有大专以上学历的技术人员专职或者兼职负责辐射安全与环境保护管理工作；依据辐射安全关键岗位名录，应当设立辐射安全关键岗位的，该岗位应当由注册核安全工程师担任。 （二）从事辐射工作的人员必须通过辐射安全和防护专业知识及相关法律法规的培训和考核。 （三）使用放射性同位素的单位应当有满足辐射防护和实体保卫要求的放射源暂存库或设备。 （四）放射性同位素与射线装置使用场所有防止误操作、防止工作人员和公众受到意外照射的安全措施。 （五）配备与辐射类型和辐射水平相适应的防护用品和监测仪器，包括个人剂量测量报警、辐射监测等仪器。使用非"},{"i":17,"n":"第十七条","txt":"将购买的放射源装配在设备中销售的辐射工作单位，按照销售和使用放射性同位素申请领取许可证。"},{"i":18,"n":"第十八条","txt":"申请领取许可证的辐射工作单位应当向有审批权的生态环境主管部门提交下列材料： （一）辐射安全许可证申请表（见附件一）； （二）满足本办法第十三条至第十六条相应规定的证明材料； （三）单位现存的和拟新增加的放射源和射线装置明细表。"},{"i":19,"n":"第十九条","txt":"生态环境主管部门在受理申请时，应当告知申请单位按照环境影响评价文件中描述的放射性同位素与射线装置的生产、销售、使用的规划设计规模申请许可证。 生态环境主管部门应当自受理申请之日起20个工作日内完成审查，符合条件的，颁发许可证，并予以公告；不符合条件的，书面通知申请单位并说明理由。"},{"i":20,"n":"第二十条","txt":"许可证包括下列主要内容： （一）单位的名称、地址、法定代表人； （二）所从事活动的种类和范围； （三）有效期限； （四）发证日期和证书编号。 许可证中活动的种类分为生产、销售和使用三类；活动的范围是指辐射工作单位生产、销售、使用的所有放射性同位素的类别、总活度和射线装置的类别、数量。 许可证分为正本和副本（具体格式和内容见附件二），具有同等效力。"},{"i":21,"n":"第二十一条","txt":"取得生产、销售、使用高类别放射性同位素与射线装置的许可证的辐射工作单位，从事低类别的放射性同位素与射线装置的生产、销售、使用活动，不需要另行申请低类别的放射性同位素与射线装置的许可证。"},{"i":22,"n":"第二十二条","txt":"辐射工作单位变更单位名称、地址和法定代表人的，应当自变更登记之日起20日内，向原发证机关申请办理许可证变更手续，并提供许可证变更申请报告。 原发证机关审查同意后，换发许可证。"},{"i":23,"n":"第二十三条","txt":"有下列情形之一的，持证单位应当按照本办法规定的许可证申请程序，重新申请领取许可证： （一）改变许可证规定的活动的种类或者范围的； （二）新建或者改建、扩建生产、销售、使用设施或者场所的。"},{"i":24,"n":"第二十四条","txt":"许可证有效期为5年。有效期届满，需要延续的，应当于许可证有效期届满30日前向原发证机关提出延续申请，并提供下列材料： （一）许可证延续申请报告； （二）监测报告； （三）许可证有效期内的辐射安全防护工作总结。 原发证机关应当自受理延续申请之日起，在许可证有效期届满前完成审查，符合条件的，予以延续，换发许可证，并使用原许可证的编号；不符合条件的，书面通知申请单位并说明理由。"},{"i":25,"n":"第二十五条","txt":"辐射工作单位部分终止或者全部终止生产、销售、使用放射性同位素与射线装置活动的，应当向原发证机关提出部分变更或者注销许可证申请，由原发证机关核查合格后，予以变更或者注销许可证。"},{"i":26,"n":"第二十六条","txt":"辐射工作单位因故遗失许可证的，应当及时到所在地省级报刊上刊登遗失公告，并于公告30日后的一个月内持公告到原发证机关申请补发。"},{"i":27,"n":"第二十七条","txt":"进口列入限制进出口目录的放射性同位素的单位，应当在进口前报国务院生态环境主管部门审批；获得批准后，由国务院对外贸易主管部门依据对外贸易的有关规定签发进口许可证。国务院生态环境主管部门在批准放射源进口申请时，给定放射源编码。 分批次进口非密封放射性物质的单位，应当每6个月报国务院生态环境主管部门审批一次。"},{"i":28,"n":"第二十八条","txt":"申请进口列入限制进出口目录的放射性同位素的单位，应当向国务院生态环境主管部门提交放射性同位素进口审批表，并提交下列材料： （一）放射性同位素使用期满后的处理方案，其中，进口I类、II类、III类放射源的，应当提供原出口方负责从最终用户回收放射源的承诺文件复印件； （二）进口放射源的明确标号和必要的说明文件的影印件或者复印件，其中，I类、II类、III类放射源的标号应当刻制在放射源本体或者密封包壳体上，Ⅳ类、Ⅴ类放射源的标号应当记录在相应说明文件中； （三）进口单位与原出口方之间签订的有效协议复印件； （四）将进口的放射性同位素销售给其他单位使用的，还应当提供与使用单位签订的有效协议复印件。 放射性同位素进口审批表的具体格式和内容见附件三。"},{"i":29,"n":"第二十九条","txt":"国务院生态环境主管部门应当自受理放射性同位素进口申请之日起10个工作日内完成审查，符合条件的，予以批准；不符合条件的，书面通知申请单位并说明理由。 进口单位和使用单位应当在进口活动完成之日起20日内，分别将批准的放射性同位素进口审批表报送各自所在地的省级生态环境主管部门。"},{"i":30,"n":"第三十条","txt":"出口列入限制进出口目录的放射性同位素的单位，应当向国务院生态环境主管部门提交放射性同位素出口表，并提交下列材料： （一）国外进口方可以合法持有放射性同位素的中文或英文证明材料； （二）出口单位与国外进口方签订的有效协议复印件。 放射性同位素出口表的具体格式和内容见附件四。 出口单位应当在出口活动完成之日起20日内，将放射性同位素出口表报送所在地的省级生态环境主管部门。 出口放射性同位素的单位应当遵守国家对外贸易的有关规定。"},{"i":31,"n":"第三十一条","txt":"转让放射性同位素的，转入单位应当在每次转让前报所在地省级生态环境主管部门审查批准。 分批次转让非密封放射性物质的，转入单位可以每6个月报所在地省级生态环境主管部门审查批准。 放射性同位素只能在持有许可证的单位之间转让。禁止向无许可证或者超出许可证规定的种类和范围的单位转让放射性同位素。 未经批准不得转让放射性同位素。"},{"i":32,"n":"第三十二条","txt":"转入放射性同位素的单位应当于转让前向所在地省级生态环境主管部门提交放射性同位素转让审批表，并提交下列材料： （一）放射性同位素使用期满后的处理方案； （二）转让双方签订的转让协议。 放射性同位素转让审批表的具体格式和内容见附件五。 生态环境主管部门应当自受理申请之日起15个工作日内完成审查，符合条件的，予以批准；不符合条件的，书面通知申请单位并说明理由。"},{"i":33,"n":"第三十三条","txt":"转入、转出放射性同位素的单位应当在转让活动完成之日起20日内，分别将一份放射性同位素转让审批表报送各自所在地省级生态环境主管部门。"},{"i":34,"n":"第三十四条","txt":"在野外进行放射性同位素示踪试验的单位，应当在每次试验前编制环境影响报告表，并经试验所在地省级生态环境主管部门商同级有关部门审查批准后方可进行。 放射性同位素野外示踪试验有可能造成跨省界环境影响的，其环境影响报告表应当报国务院生态环境主管部门商同级有关部门审查批准。"},{"i":35,"n":"第三十五条","txt":"使用放射性同位素的单位需要将放射性同位素转移到外省、自治区、直辖市使用的，应当于活动实施前10日内向使用地省级生态环境主管部门备案，书面报告移出地省级生态环境主管部门，并接受使用地生态环境主管部门的监督管理。 书面报告的内容应当包括该放射性同位素的核素、活度、转移时间和地点、辐射安全负责人和联系电话等内容；转移放射源的还应提供放射源标号和编码。 使用单位应当在活动结束后20日内到使用地省级生态环境主管部门办理备案注销手续，并书面告知移出地省级生态环境主管部门。"},{"i":36,"n":"第三十六条","txt":"辐射工作单位应当按照许可证的规定从事放射性同位素和射线装置的生产、销售、使用活动。 禁止无许可证或者不按照许可证规定的种类和范围从事放射性同位素和射线装置的生产、销售、使用活动。"},{"i":37,"n":"第三十七条","txt":"生产放射性同位素与射线装置的单位，应当在放射性同位素的包装容器、含放射性同位素的设备和射线装置上设置明显的放射性标识和中文警示说明；放射源上能够设置放射性标识的，应当一并设置。 含放射源设备的说明书应当告知用户该设备含有放射源及其相关技术参数和结构特性，并告知放射源的潜在辐射危害及相应的安全防护措施。"},{"i":38,"n":"第三十八条","txt":"生产、进口放射源的单位在销售Ⅰ类、Ⅱ类、Ⅲ类放射源时，应当与使用放射源的单位签订废旧放射源返回合同。 使用Ⅰ类、Ⅱ类、Ⅲ类放射源的单位应当按照废旧放射源返回合同规定，在放射源闲置或者废弃后3个月内将废旧放射源交回生产单位或者返回原出口方。确实无法交回生产单位或者返回原出口方的，送交有相应资质的放射性废物集中贮存单位贮存。 使用Ⅳ类、Ⅴ类放射源的单位应当按照国务院生态环境主管部门的规定，在放射源闲置或者废弃后3个月内将废旧放射源进行包装整备后送交有相应资质的放射性废物集中贮存单位贮存。 使用放射源的单位应当在废旧放射源交回、返回或者送交活动完成之日起20日内，向其所在地省级生态环境主管部门备案。"},{"i":39,"n":"第三十九条","txt":"销售、使用放射源的单位在本办法实施前已经贮存的废旧放射源，应当自本办法实施之日起1年内交回放射源生产单位或者返回原出口方，或送交有相应资质的放射性废物集中贮存单位。"},{"i":40,"n":"第四十条","txt":"生产放射性同位素的场所、产生放射性污染的放射性同位素销售和使用场所、产生放射性污染的射线装置及其场所，终结运行后应当依法实施退役。退役完成后，有关辐射工作单位方可申请办理许可证变更或注销手续。"},{"i":41,"n":"第四十一条","txt":"辐射工作单位应当建立放射性同位素与射线装置台帐，记载放射性同位素的核素名称、出厂时间和活度、标号、编码、来源和去向，及射线装置的名称、型号、射线种类、类别、用途、来源和去向等事项。 放射性同位素与射线装置台帐、个人剂量档案和职业健康监护档案应当长期保存。"},{"i":42,"n":"第四十二条","txt":"辐射工作单位应当编写放射性同位素与射线装置安全和防护状况年度评估报告，于每年1月31日前报原发证机关。 年度评估报告应当包括放射性同位素与射线装置台帐、辐射安全和防护设施的运行与维护、辐射安全和防护制度及措施的建立和落实、事故和应急以及档案管理等方面的内容。"},{"i":43,"n":"第四十三条","txt":"县级以上人民政府生态环境主管部门应当对辐射工作单位进行监督检查，对存在的问题，应当提出书面的现场检查意见和整改要求，由检查人员签字或检查单位盖章后交被检查单位，并由被检查单位存档备案。"},{"i":44,"n":"第四十四条","txt":"省级生态环境主管部门应当编写辐射工作单位监督管理年度总结报告，于每年3月1日前报国务院生态环境主管部门。 报告内容应当包括辐射工作单位数量、放射源数量和类别、射线装置数量和类别、许可证颁发与注销情况、事故及其处理情况、监督检查与处罚情况等内容。"},{"i":45,"n":"第四十五条","txt":"辐射工作单位违反本办法的有关规定，有下列行为之一的，由县级以上人民政府生态环境主管部门责令停止违法行为，限期改正；逾期不改正的，处1万元以上3万元以下的罚款： （一）未在含放射源设备的说明书中告知用户该设备含有放射源的； （二）销售、使用放射源的单位未在本办法实施之日起1年内将其贮存的废旧放射源交回、返回或送交有关单位的。 辐射工作单位违反本办法的其他规定，按照《中华人民共和国放射性污染防治法》、《放射性同位素与射线装置安全和防护条例》及其他相关法律法规的规定进行处罚。"},{"i":46,"n":"第四十六条","txt":"省级以上人民政府生态环境主管部门依据《电离辐射防护与辐射源安全基本标准》（GB18871－2002）及国家有关规定负责对放射性同位素与射线装置管理的豁免出具证明文件。"},{"i":47,"n":"第四十七条","txt":"本办法自2006年3月1日起施行。 附件：1.辐射安全许可证申请表 　　　2.辐射安全许可证副本 　　　3.放射性同位素进口审批表 　　　4.放射性同位素出口表 　　　5.放射性同位素转让审批表"}],"fangshexinggutifeiwuzhucunhechuzhixukeguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强放射性固体废物贮存和处置活动的监督管理，规范放射性固体废物贮存和处置许可,根据《中华人民共和国放射性污染防治法》和《放射性废物安全管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于放射性固体废物贮存和处置许可证的申请和审批管理。"},{"i":3,"n":"第三条","txt":"在中华人民共和国境内专门从事放射性固体废物贮存、处置活动的单位,应当依照本办法规定取得放射性固体废物贮存许可证（以下简称“贮存许可证”）或者放射性固体废物处置许可证（以下简称“处置许可证”），并按照许可证规定的种类、范围和规模从事放射性固体废物贮存或者处置活动。 　　同时从事放射性固体废物贮存和处置活动的单位，应当分别取得贮存许可证和处置许可证。 　　核设施营运单位利用与核设施配套建设的贮存设施，贮存本单位产生的放射性固体废物的，不需要申请领取贮存许可证；贮存其他单位产生的放射性固体废物的，应当依照本办法的规定申请领取贮存许可证。"},{"i":4,"n":"第四条","txt":"贮存许可证和处置许可证，由国务院环境保护主管部门审批、颁发。"},{"i":5,"n":"第五条","txt":"持有贮存许可证或者处置许可证的单位（以下简称“持证单位”）应当依法承担其所贮存或者处置的放射性固体废物的安全责任。"},{"i":6,"n":"第六条","txt":"从事放射性固体废物贮存或者处置活动的人员，应当通过有关放射性废物管理、辐射防护或者环境监测专业知识的培训和考核。"},{"i":7,"n":"第七条","txt":"申请从事放射性固体废物贮存活动的单位，应当具备下列条件： 　　（一）有法人资格； 　　（二）有能保证贮存设施安全运行的组织机构，包括负责贮存设施运行、安全防护（含辐射监测）和质量保证等部门； 　　（三）有三名以上放射性废物管理、辐射防护、环境监测方面的专业技术人员，其中至少有一名注册核安全工程师； 　　（四）有符合国家有关放射性污染防治标准和国务院环境保护主管部门规定的放射性固体废物接收、贮存设施和场所。同时从事放射性废物处理活动的，还应当具有符合国家有关放射性污染防治标准和国务院环境保护主管部门规定的处理设施； 　　（五）有符合国家有关放射性污染防治标准和国务院环境保护主管部门规定的放射性检测、辐射防护和环境监测设备； 　　（六）建立记录档案制度，记录所贮存的放射性固体废物的来源、数量、特征、贮存位置、清洁解控或者送交处置等相关信息； 　　（七）有健全的管理制度以及符合核安全监督管理"},{"i":8,"n":"第八条","txt":"申请领取贮存许可证的单位，应当向国务院环境保护主管部门提出书面申请，填写放射性固体废物贮存许可证申请表，并提交下列材料： 　　（一）企业法人营业执照正、副本的复印件，或者事业单位法人证书正、副本的复印件，以及法定代表人身份证的复印件； 　　（二）放射性检测、辐射防护和环境监测设备清单； 　　（三）放射性固体废物贮存管理制度证明文件，包括贮存操作规程、质量保证大纲及程序文件清单、辐射监测计划、贮存设施运行监测计划、应急预案、记录档案管理文件等； 　　（四）满足本办法第七条规定的其他证明材料。"},{"i":9,"n":"第九条","txt":"申请从事低、中水平放射性固体废物处置活动的单位，应当具备下列条件： 　　（一）有国有或者国有控股的企业法人资格，有不少于三千万元的注册资金； 　　（二）有能保证处置设施安全运行的组织机构，包括负责处置设施运行、安全防护（含辐射监测）和质量保证等部门； 　　（三）有十名以上放射性废物管理、辐射防护、环境监测方面的专业技术人员，其中注册核安全工程师不少于三名； 　　（四）有符合国家有关放射性污染防治标准和国务院环境保护主管部门规定的放射性固体废物接收、处置设施和场所； 　　（五）有符合国家有关放射性污染防治标准和国务院环境保护主管部门规定的放射性检测、辐射防护和环境监测设备，以及必要的辐射防护器材； 　　（六）有能保证其处置活动持续进行直至安全监护期满的财务担保； 　　（七）建立记录档案制度和相应的信息管理系统，能记录和管理所处置的放射性固体废物的来源、数量、特征、处置位置等与处置活动有关"},{"i":10,"n":"第十条","txt":"申请从事高水平放射性固体废物处置和α放射性固体废物处置活动的单位，除满足本办法第九条第（二）项、第（四）项、第（五）项、第（六）项、第（七）项和第（八）项规定的条件外，还应当具备下列条件： 　　（一）有国有或者国有控股的企业法人资格，有不低于一亿元的注册资金； 　　（二）有二十名以上放射性废物管理、辐射防护、环境监测方面的专业技术人员，其中注册核安全工程师不少于五名。"},{"i":11,"n":"第十一条","txt":"申请领取处置许可证的单位，应当向国务院环境保护主管部门提出书面申请，填写放射性固体废物处置许可证申请表，并提交下列材料： 　　（一）企业法人营业执照正、副本复印件，法定代表人身份证复印件； 　　（二）从事放射性固体废物处置管理和操作人员的培训和考核证明，注册核安全工程师证书复印件； 　　（三）放射性检测、辐射防护和环境监测设备清单； 　　（四）财务担保证明； 　　（五）放射性固体废物处置管理制度证明文件，包括处置操作规程、质量保证大纲及程序文件清单、处置设施运行监测计划、辐射监测计划、应急预案、记录档案管理文件、信息管理系统证明文件等； 　　（六）满足本办法第九条、第十条规定的其他证明材料。"},{"i":12,"n":"第十二条","txt":"国务院环境保护主管部门应当自受理许可证申请之日起二十个工作日内完成审查，对符合条件的颁发许可证，予以公告；对不符合条件的，书面通知申请单位并说明理由。 　　国务院环境保护主管部门在审查过程中，应当组织专家进行技术评审，并征求国务院其他有关部门意见。技术评审所需时间不包括在审批期限内，并应当书面告知申请单位。"},{"i":13,"n":"第十三条","txt":"贮存许可证和处置许可证应当载明下列内容： 　　（一）单位名称、地址和法定代表人； 　　（二）准予从事的活动种类、范围和规模； 　　（三）有效期限； 　　（四）发证机关、发证日期和证书编号。 　　前款所指准予从事活动的种类和范围，是指贮存或者处置废放射源，低、中、高水平放射性固体废物或者α放射性固体废物；规模是指贮存、处置放射性固体废物空间的容积。"},{"i":14,"n":"第十四条","txt":"贮存许可证和处置许可证的有效期为十年。 　　许可证有效期届满，从事放射性固体废物贮存或者处置活动的单位需要继续从事贮存或者处置活动的，应当于许可证有效期届满九十日前，向国务院环境保护主管部门提出延续申请，并提交下列材料： 　　（一）许可证延续申请文件； 　　（二）许可证有效期内的贮存或者处置活动总结报告； 　　（三）辐射监测报告； 　　（四）国务院环境保护主管部门要求的其他材料。 　　国务院环境保护主管部门应当在许可证有效期届满前完成审查，对符合条件的准予延续；对不符合条件的，书面通知申请单位并说明理由。"},{"i":15,"n":"第十五条","txt":"持证单位名称、地址、法定代表人发生变更的，应当自变更登记之日起二十日内，向国务院环境保护主管部门申请办理许可证变更手续，并提交下列材料： 　　（一）许可证变更申请文件； 　　（二）变更后的企业法人营业执照正、副本复印件，或者事业单位法人证书正、副本的复印件，以及法定代表人身份证复印件； 　　（三）国务院环境保护主管部门要求的其他材料。 　　国务院环境保护主管部门核实后，换发许可证。"},{"i":16,"n":"第十六条","txt":"许可证载明的活动种类、范围、规模发生变更，或者许可证有效期满未获延续的，应当按照本办法第七条、第九条、第十条的规定，重新申请领取许可证。"},{"i":17,"n":"第十七条","txt":"持证单位因故遗失许可证的，应当及时在所在地省级报刊上刊登遗失公告，公告期为三十日。持证单位应当于公告期满后的一个月内持公告到国务院环境保护主管部门申请补发许可证。"},{"i":18,"n":"第十八条","txt":"持证单位应当按照国家有关放射性污染防治标准和国务院环境保护主管部门的规定，在许可证规定的种类、范围和规模内从事放射性固体废物贮存或者处置活动。 　　禁止伪造、变造、转让许可证。禁止无许可证从事放射性固体废物贮存或者处置活动。"},{"i":19,"n":"第十九条","txt":"贮存许可证持证单位应当如实完整地记录所收贮放射性固体废物来源、数量、特征、贮存位置、清洁解控或者送交处置等相关信息。 　　贮存许可证持证单位应当于每年3月31日前，向国务院环境保护主管部门提交上一年度贮存活动总结报告，包括废物贮存、清洁解控、送交处置、辐射监测等内容。"},{"i":20,"n":"第二十条","txt":"处置许可证持证单位应当如实完整地记录所处置放射性固体废物的来源、数量、特征、处置位置等与处置活动有关的信息。放射性固体废物处置档案记录应当永久保存。 　　处置许可证持证单位应当于每年3月31日前，向国务院环境保护主管部门提交上一年度处置活动总结报告，包括废物接收、处置设施运行、辐射监测等内容。"},{"i":21,"n":"第二十一条","txt":"放射性固体废物贮存、处置许可审批部门及其工作人员违反本办法的规定，有下列行为之一的，对直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法移送司法机关追究刑事责任： 　　（一）违反本办法规定核发贮存许可证或者处置许可证的； 　　（二）在许可证审批及监督管理过程中，索取、收受他人财物或者谋取其他利益的； 　　（三）发现有违反本办法的行为而不依法予以查处的； 　　（四）有其他徇私舞弊、滥用职权、玩忽职守行为的。"},{"i":22,"n":"第二十二条","txt":"未取得相应许可证擅自从事放射性固体废物贮存、处置活动，或者未按照许可证规定的活动种类、范围、规模、期限从事放射性固体废物贮存、处置活动的，依照《放射性废物安全管理条例》第三十八条的规定处罚。"},{"i":23,"n":"第二十三条","txt":"有下列行为之一的，由国务院环境保护部门责令限期改正，处三万元以下罚款，涉嫌构成犯罪的，依法移送司法机关追究刑事责任： 　　（一）伪造、变造、转让许可证的； 　　（二）未按本办法的规定及时申请变更许可证的。"},{"i":24,"n":"第二十四条","txt":"对违反本办法其他规定的，按照《中华人民共和国放射性污染防治法》、《放射性废物安全管理条例》及其他相关法律法规的规定进行处罚。"},{"i":25,"n":"第二十五条","txt":"本办法规定的贮存许可证申请表、处置许可证申请表、贮存许可证和处置许可证样式等文件格式由国务院环境保护主管部门统一制定并公布。"},{"i":26,"n":"第二十六条","txt":"本办法由国务院环境保护主管部门负责解释。"},{"i":27,"n":"第二十七条","txt":"本办法自2014年3月1日起施行。"}],"fangshexingfeiwuanquanjianduguanliguiding":[],"fangshexingwupinyunshuanquanjianduguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强对放射性物品运输安全的监督管理，依据《放射性物品运输安全管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于对放射性物品运输和放射性物品运输容器的设计、制造和使用过程的监督管理。"},{"i":3,"n":"第三条","txt":"国务院核安全监管部门负责对全国放射性物品运输的核与辐射安全实施监督管理，具体职责为： 　　（一）负责对放射性物品运输容器的设计、制造和使用等进行监督检查； 　　（二）负责对放射性物品运输过程中的核与辐射事故应急给予支持和指导； 　　（三）负责对放射性物品运输安全监督管理人员进行辐射防护与安全防护知识培训。"},{"i":4,"n":"第四条","txt":"省、自治区、直辖市环境保护主管部门负责对本行政区域内放射性物品运输的核与辐射安全实施监督管理，具体职责为： 　　（一）负责对本行政区域内放射性物品运输活动的监督检查； 　　（二）负责在本行政区域内放射性物品运输过程中的核与辐射事故的应急准备和应急响应工作； 　　（三）负责对本行政区域内放射性物品运输安全监督管理人员进行辐射防护与安全防护知识培训。"},{"i":5,"n":"第五条","txt":"放射性物品运输单位和放射性物品运输容器的设计、制造和使用单位，应当对其活动负责，并配合国务院核安全监管部门和省、自治区、直辖市环境保护主管部门进行监督检查，如实反映情况，提供必要的资料。"},{"i":6,"n":"第六条","txt":"监督检查人员应当依法实施监督检查，并为被检查者保守商业秘密。"},{"i":7,"n":"第七条","txt":"放射性物品运输容器设计单位应当具备与设计工作相适应的设计人员、工作场所和设计手段，按照放射性物品运输容器设计的相关规范和标准从事设计活动，并为其设计的放射性物品运输容器的制造和使用单位提供必要的技术支持。从事一类放射性物品运输容器设计的单位应当依法取得设计批准书。 　　放射性物品运输容器设计单位应当在设计阶段明确首次使用前对运输容器的结构、包容、屏蔽、传热和核临界安全功能进行检查的方法和要求。"},{"i":8,"n":"第八条","txt":"放射性物品运输容器设计单位应当加强质量管理，建立健全质量保证体系，编制质量保证大纲并有效实施。 　　放射性物品运输容器设计单位对其所从事的放射性物品运输容器设计活动负责。"},{"i":9,"n":"第九条","txt":"放射性物品运输容器设计单位应当通过试验验证或者分析论证等方式，对其设计的放射性物品运输容器的安全性能进行评价。 　　安全性能评价应当贯穿整个设计过程，保证放射性物品运输容器的设计满足所有的安全要求。"},{"i":10,"n":"第十条","txt":"放射性物品运输容器设计单位应当按照国务院核安全监管部门规定的格式和内容编制设计安全评价文件。 　　设计安全评价文件应当包括结构评价、热评价、包容评价、屏蔽评价、临界评价、货包（放射性物品运输容器与其放射性内容物）操作规程、验收试验和维修大纲，以及运输容器的工程图纸等内容。"},{"i":11,"n":"第十一条","txt":"放射性物品运输容器设计单位对其设计的放射性物品运输容器进行试验验证的，应当在验证开始前至少二十个工作日提请国务院核安全监管部门进行试验见证，并提交下列文件： 　　（一）初步设计说明书和计算报告； 　　（二）试验验证方式和试验大纲； 　　（三）试验验证计划。 　　国务院核安全监管部门应当及时组织对设计单位的试验验证过程进行见证，并做好相应的记录。 　　开展特殊形式和低弥散放射性物品设计试验验证的单位，应当依照本条第一款的规定提请试验见证。"},{"i":12,"n":"第十二条","txt":"国务院核安全监管部门应当对放射性物品运输容器设计活动进行监督检查。 　　申请批准一类放射性物品运输容器的设计，国务院核安全监管部门原则上应当对该设计活动进行一次现场检查；对于二类、三类放射性物品运输容器的设计，国务院核安全监管部门应当结合试验见证情况进行现场抽查。 　　国务院核安全监管部门可以结合放射性物品运输容器的制造和使用情况，对放射性物品运输容器设计单位进行监督检查。"},{"i":13,"n":"第十三条","txt":"国务院核安全监管部门对放射性物品运输容器设计单位进行监督检查时，应当检查质量保证大纲和试验验证的实施情况、人员配备、设计装备、设计文件、安全性能评价过程记录、以往监督检查发现问题的整改落实情况等。"},{"i":14,"n":"第十四条","txt":"一类放射性物品运输容器设计批准书颁发前的监督检查中，发现放射性物品运输容器设计单位的设计活动不符合法律法规要求的，国务院核安全监管部门应当暂缓或者不予颁发设计批准书。 　　监督检查中发现经批准的一类放射性物品运输容器设计确有重大设计安全缺陷的，国务院核安全监管部门应当责令停止该型号运输容器的制造或者使用，撤销一类放射性物品运输容器设计批准书。"},{"i":15,"n":"第十五条","txt":"放射性物品运输容器制造单位应当具备与制造活动相适应的专业技术人员、生产条件和检测手段，采用经设计单位确认的设计图纸和文件。一类放射性物品运输容器制造单位应当依法取得一类放射性物品运输容器制造许可证后，方可开展制造活动。 　　放射性物品运输容器制造单位应当在制造活动开始前，依据设计提出的技术要求编制制造过程工艺文件，并严格执行；采用特种工艺的，应当进行必要的工艺试验或者工艺评定。"},{"i":16,"n":"第十六条","txt":"放射性物品运输容器制造单位应当加强质量管理，建立健全质量保证体系，编制质量保证大纲并有效实施。 　　放射性物品运输容器制造单位对其所从事的放射性物品运输容器制造质量负责。"},{"i":17,"n":"第十七条","txt":"放射性物品运输容器制造单位应当按照设计要求和有关标准，对放射性物品运输容器的零部件和整体容器进行质量检验，编制质量检验报告。未经质量检验或者经检验不合格的放射性物品运输容器，不得交付使用。"},{"i":18,"n":"第十八条","txt":"一类、二类放射性物品运输容器制造单位，应当按照本办法规定的编码规则，对其制造的一类、二类放射性物品运输容器进行统一编码。 　　一类、二类放射性物品运输容器制造单位，应当于每年1月31日前将上一年度制造的运输容器的编码清单报国务院核安全监管部门备案。 　　三类放射性物品运输容器制造单位，应当于每年1月31日前将上一年度制造的运输容器的型号及其数量、设计总图报国务院核安全监管部门备案。"},{"i":19,"n":"第十九条","txt":"一类放射性物品运输容器制造单位应当在每次制造活动开始前至少三十日，向国务院核安全监管部门提交制造质量计划。国务院核安全监管部门应当根据制造活动的特点选取检查点并通知制造单位。 　　一类放射性物品运输容器制造单位应当根据制造活动的实际进度，在国务院核安全监管部门选取的检查点制造活动开始前，至少提前十个工作日书面报告国务院核安全监管部门。"},{"i":20,"n":"第二十条","txt":"国务院核安全监管部门应当对放射性物品运输容器的制造过程进行监督检查。 　　对一类放射性物品运输容器的制造活动应当至少组织一次现场检查；对二类放射性物品运输容器的制造，应当对制造过程进行不定期抽查；对三类放射性物品运输容器的制造，应当根据每年的备案情况进行不定期抽查。"},{"i":21,"n":"第二十一条","txt":"国务院核安全监管部门对放射性物品运输容器制造单位进行现场监督检查时，应当检查以下内容： 　　（一）一类放射性物品运输容器制造单位遵守制造许可证的情况； 　　（二）质量保证体系的运行情况； 　　（三）人员资格情况； 　　（四）生产条件和检测手段与所从事制造活动的适应情况； 　　（五）编制的工艺文件与采用的技术标准以及有关技术文件的符合情况； 　　（六）工艺过程的实施情况以及零部件采购过程中的质量保证情况； 　　（七）制造过程记录； 　　（八）重大质量问题的调查和处理，以及整改要求的落实情况等。"},{"i":22,"n":"第二十二条","txt":"国务院核安全监管部门在监督检查中，发现一类放射性物品运输容器制造单位有不符合制造许可证规定情形的，由国务院核安全监管部门责令限期整改。 　　监督检查中发现放射性物品运输容器制造确有重大质量问题或者违背设计要求的，由国务院核安全监管部门责令停止该型号运输容器的制造或者使用。"},{"i":23,"n":"第二十三条","txt":"一类放射性物品运输容器的使用单位在采购境外单位制造的运输容器时，应当在对外贸易合同中明确运输容器的设计、制造符合我国放射性物品运输安全法律法规要求，以及境外单位配合国务院核安全监管部门监督检查的义务。 　　采购境外单位制造的一类放射性物品运输容器的使用单位，应当在相应制造活动开始前至少三个月通知国务院核安全监管部门，并配合国务院核安全监管部门对境外单位一类放射性物品运输容器制造活动实施监督检查。 　　采购境外单位制造的一类放射性物品运输容器成品的使用单位，应当在使用批准书申请时提交相应的文件，证明该容器质量满足设计要求。"},{"i":24,"n":"第二十四条","txt":"托运人对放射性物品运输的核与辐射安全和应急工作负责，对拟托运物品的合法性负责，并依法履行各项行政审批手续。托运一类放射性物品的托运人应当依法取得核与辐射安全分析报告批复后方可从事运输活动。托运人应当对直接从事放射性物品运输的工作人员进行运输安全和应急响应知识的培训和考核，并建立职业健康档案。 　　承运人应当对直接从事放射性物品运输的工作人员进行运输安全和应急响应知识的培训和考核，并建立职业健康档案。对托运人提交的有关资料，承运人应当进行查验、收存，并配合托运人做好运输过程中的安全保卫和核与辐射事故应急工作。 　　放射性物品运输应当有明确并且具备核与辐射安全法律法规规定条件的接收人。接收人应当对所接收的放射性物品进行核对验收，发现异常应当及时通报托运人和承运人。"},{"i":25,"n":"第二十五条","txt":"托运人应当根据拟托运放射性物品的潜在危害建立健全应急响应体系，针对具体运输活动编制应急响应指南，并在托运前提交承运人。 　　托运人应当会同承运人定期开展相应的应急演习。"},{"i":26,"n":"第二十六条","txt":"托运人应当对每个放射性物品运输容器在制造完成后、首次使用前进行详细检查，确保放射性物品运输容器的包容、屏蔽、传热、核临界安全功能符合设计要求。"},{"i":27,"n":"第二十七条","txt":"托运人应当按照运输容器的特点，制定每次启运前检查或者试验程序，并按照程序进行检查。检查时应当核实内容物符合性，并对运输容器的吊装设备、密封性能、温度、压力等进行检测和检查，确保货包的热和压力已达到平衡、稳定状态，密闭性能完好。 　　对装有易裂变材料的放射性物品运输容器，还应当检查中子毒物和其他临界控制措施是否符合要求。 　　每次检查或者试验应当由获得托运人授权的操作人员进行，并制作书面记录。 　　检查不符合要求的，不得启运。"},{"i":28,"n":"第二十八条","txt":"托运一类放射性物品的，托运人应当委托有资质的辐射监测机构在启运前对其表面污染和辐射水平实施监测，辐射监测机构应当出具辐射监测报告。 　　托运二类、三类放射性物品的，托运人应当对其表面污染和辐射水平实施监测，并编制辐射监测报告，存档备查。 　　监测结果不符合国家放射性物品运输安全标准的，不得托运。"},{"i":29,"n":"第二十九条","txt":"托运人应当根据放射性物品运输安全标准，限制单个运输工具上放射性物品货包的数量。 　　承运人应当按照托运人的要求运输货包。放射性物品运输和中途贮存期间，承运人应当妥善堆放，采取必要的隔离措施，并严格执行辐射防护和监测要求。"},{"i":30,"n":"第三十条","txt":"托运人和承运人应当采取措施，确保货包和运输工具外表面的非固定污染不超过放射性物品运输安全标准的要求。 　　在运输途中货包受损、发生泄漏或者有泄漏可能的，托运人和承运人应当立即采取措施保护现场，限制非专业人员接近，并由具备辐射防护与安全防护知识的专业技术人员按放射性物品运输安全标准要求评定货包的污染程度和辐射水平，消除或者减轻货包泄漏、损坏造成的后果。 　　经评定，货包泄漏量超过放射性物品运输安全标准要求的，托运人和承运人应当立即报告事故发生地的县级以上环境保护主管部门，并在环境保护主管部门监督下将货包移至临时场所。货包完成修理和去污之后，方可向外发送。"},{"i":31,"n":"第三十一条","txt":"放射性物品运输中发生核与辐射安全事故时，托运人和承运人应当根据核与辐射事故应急响应指南的要求，做好事故应急工作，并立即报告事故发生地的县级以上环境保护主管部门。相关部门应当按照应急预案做好事故应急响应工作。"},{"i":32,"n":"第三十二条","txt":"一类放射性物品启运前，托运人应当将放射性物品运输的核与辐射安全分析报告批准书、辐射监测报告，报启运地的省、自治区、直辖市环境保护主管部门备案。 　　启运地的省、自治区、直辖市环境保护主管部门收到托运人的备案材料后，应当将一类放射性物品运输辐射监测备案表及时通报途经地和抵达地的省、自治区、直辖市环境保护主管部门。"},{"i":33,"n":"第三十三条","txt":"对一类放射性物品的运输，启运地的省、自治区、直辖市环境保护主管部门应当在启运前对放射性物品运输托运人的运输准备情况进行监督检查。 　　对运输频次比较高、运输活动比较集中的地区，可以根据实际情况制定监督检查计划，原则上检查频次每月不少于一次；对二类放射性物品的运输，可以根据实际情况开展抽查，原则上检查频次每季度不少于一次；对三类放射性物品的运输，可以根据实际情况实施抽查，原则上检查频次每年不少于一次。 　　途经地和抵达地的省、自治区、直辖市环境保护主管部门不得中途拦截检查；发生特殊情况的除外。"},{"i":34,"n":"第三十四条","txt":"省、自治区、直辖市环境保护主管部门应当根据运输货包的类别和数量，按照放射性物品运输安全标准对本行政区域内放射性物品运输货包的表面污染和辐射水平开展启运前的监督性监测。监督性监测不得收取费用。 　　辐射监测机构和托运人应当妥善保存原始记录和监测报告，并配合省、自治区、直辖市环境保护主管部门进行监督性监测。"},{"i":35,"n":"第三十五条","txt":"放射性物品从境外运抵中华人民共和国境内，或者途经中华人民共和国境内运输的，应当根据放射性物品的分类，分别按照法律法规规定的一类、二类、三类放射性物品运输的核与辐射安全监督管理要求进行运输。"},{"i":36,"n":"第三十六条","txt":"放射性物品运输容器使用单位应当按照放射性物品运输安全标准和设计要求制定容器的维修和维护程序，严格按照程序进行维修和维护，并建立维修、维护和保养档案。放射性物品运输容器达到设计使用年限，或者发现放射性物品运输容器存在安全隐患的，应当停止使用，进行处理。"},{"i":37,"n":"第三十七条","txt":"一类放射性物品运输容器使用单位应当对其使用的一类放射性物品运输容器每两年进行一次安全性能评价。安全性能评价应当在两年使用期届满前至少三个月进行，并在使用期届满前至少两个月编制定期安全性能评价报告。 　　定期安全性能评价报告，应当包括运输容器的运行历史和现状、检查和检修及发现问题的处理情况、定期检查和试验等内容。使用单位应当做好接受监督检查的准备。必要时，国务院核安全监管部门可以根据运输容器使用特点和使用情况，选取检查点并组织现场检查。 　　一类放射性物品运输容器使用单位应当于两年使用期届满前至少三十日，将安全性能评价结果报国务院核安全监管部门备案。"},{"i":38,"n":"第三十八条","txt":"放射性物品启运前的监督检查包括以下内容： 　　（一）运输容器及放射性内容物：检查运输容器的日常维修和维护记录、定期安全性能评价记录（限一类放射性物品运输容器）、编码（限一类、二类放射性物品运输容器）等，确保运输容器及内容物均符合设计的要求； 　　（二）托运人启运前辐射监测情况,以及随车辐射监测设备的配备； 　　（三）表面污染和辐射水平； 　　（四）标记、标志和标牌是否符合要求； 　　（五）运输说明书，包括特殊的装卸作业要求、安全防护指南、放射性物品的品名、数量、物理化学形态、危害风险以及必要的运输路线的指示等； 　　（六）核与辐射事故应急响应指南； 　　（七）核与辐射安全分析报告批准书、运输容器设计批准书等相关证书的持有情况； 　　（八）直接从事放射性物品运输的工作人员的运输安全、辐射防护和应急响应知识的培训和考核情况； 　　（九）直接从事放射性物品运输的工作人员的辐射防护管理情况。"},{"i":39,"n":"第三十九条","txt":"国务院核安全监管部门和省、自治区、直辖市环境保护主管部门在监督检查中发现放射性物品运输活动有不符合国家放射性物品运输安全标准情形的，应当责令限期整改；发现放射性物品运输活动可能对人体健康和环境造成核与辐射危害的，应当责令停止运输。"},{"i":40,"n":"第四十条","txt":"本办法自2016年5月1日起施行。 　　附 放射性物品运输容器统一编码规则 　　1.1一类、二类放射性物品运输容器编码规则 C N / X X X / X - X X - （NNSA） 　　其中： 　　第1－2位：国家或地区代码，CN代表中国。 　　第3位：“/”，隔离符。 　　第4－6位：主管部门为该设计指定的设计批准编号或备案编号。 　　第7位：“/”，隔离符。 　　第8位：批准书类型或容器类型： 　　一类放射性物品运输容器设计批准书类型： 　　AF：易裂变A型运输容器设计批准书 　　B（U）：B(U)型运输容器设计批准书 　　B（U）F：易裂变材料B(U)型运输容器设计批准书 　　B（M）：B(M)型运输容器设计批准书 　　B（M）F：易裂变材料B(M)型运输容器设计批准书 　　C：C型运输容器设计批准书 　　CF：易裂变材料C型运输容器设计批准书 　　IF：易裂变材料工业运输容"}],"fangshexingwupinyunshuanquanxukeguanlibanfa":[{"i":1,"n":"第一条","txt":"[立法目的]为了加强对放射性物品运输的安全管理，实施《放射性物品运输安全管理条例》规定的运输安全许可制度，制定本办法。"},{"i":2,"n":"第二条","txt":"[适用范围]从事放射性物品运输和放射性物品运输容器设计、制造等活动，应当按照本办法的规定，办理有关许可和备案手续。"},{"i":3,"n":"第三条","txt":"[分类管理]国家对放射性物品运输实施分类管理，根据放射性物品的特性及其对人体健康和环境的潜在危害程度，将放射性物品分为一类、二类和三类。 放射性物品的具体分类和名录，由国务院核安全监管部门按照《放射性物品运输安全管理条例》的规定，会同国务院公安、卫生、海关、交通运输、铁路、民航、核工业行业主管部门制定。"},{"i":4,"n":"第四条","txt":"[设计基本要求]一类放射性物品运输容器的设计，应当在首次用于制造前报国务院核安全监管部门审查批准。 二类放射性物品运输容器的设计，应当在首次用于制造前报国务院核安全监管部门备案。"},{"i":5,"n":"第五条","txt":"[设计记录]放射性物品运输容器设计单位应当建立健全质量保证体系并有效实施，加强档案管理，如实记录放射性物品运输容器的设计和安全性能评价过程。"},{"i":6,"n":"第六条","txt":"[安全性能评价]放射性物品运输容器的设计应当满足国家放射性物品运输安全标准。 设计单位应当通过试验验证，采用可靠、保守的分析论证，或者采取两者相结合的方式，对设计的放射性物品运输容器的安全性能进行评价。"},{"i":7,"n":"第七条","txt":"[设计单位条件]申请领取一类放射性物品运输容器设计批准书的单位，应当符合下列条件： （一）具有法人资格； （二）具有与所从事设计活动相关或者相近的工作业绩； （三）具有与所从事设计活动相适应并经考核合格的专业技术人员； （四）具有健全的管理制度和完善的质量保证体系，以及符合国家有关核安全监督管理规定的质量保证大纲。"},{"i":8,"n":"第八条","txt":"[设计申请]　申请批准一类放射性物品运输容器的设计，设计单位应当向国务院核安全监管部门提出书面申请，并提交下列材料： （一）设计总图及其设计说明书； （二）设计安全评价报告书； （三）符合国家有关核安全监督管理规定的质量保证大纲。 放射性物品运输容器设计安全评价报告书的标准格式和内容，由国务院核安全监管部门另行规定。"},{"i":9,"n":"第九条","txt":"[设计审查]国务院核安全监管部门应当自受理一类放射性物品运输容器的设计批准申请之日起45个工作日内完成审查。对符合国家放射性物品运输安全标准的，颁发一类放射性物品运输容器设计批准书，并公告设计批准编号；对不符合国家放射性物品运输安全标准的，书面通知申请单位并说明理由。 国务院核安全监管部门在审查过程中，应当组织专家进行技术评审。技术评审方式包括文件审查、审评对话、现场见证等。 技术评审所需时间，不计算在本条第一款规定的期限内。"},{"i":10,"n":"第十条","txt":"[设计批准书]一类放射性物品运输容器设计批准书应当包括下列主要内容： （一）设计单位名称、住所和法定代表人； （二）运输容器类型和设计批准编号； （三）放射性内容物特性； （四）运输容器设计说明及适用的相关技术标准等； （五）操作要求、运输方式、使用环境温度； （六）有效期限； （七）批准日期和批准书编号。"},{"i":11,"n":"第十一条","txt":"[设计批准延续]一类放射性物品运输容器设计批准书有效期为5年。 设计批准书有效期届满，需要延续的，持证单位应当于设计批准书有效期届满6个月前，向国务院核安全监管部门提出书面延续申请，并提交下列材料： （一）质量保证大纲实施效果的说明； （二）设计依据标准如有变化，是否符合新标准的说明。 对于设计单位提出的批准书延续申请，国务院核安全监管部门应当在设计批准书有效期届满前作出是否准予延续的决定。"},{"i":12,"n":"第十二条","txt":"[设计变更]设计单位修改已批准的一类放射性物品运输容器设计中有关安全内容的，应当按照原申请程序向国务院核安全监管部门重新申请领取设计批准书。 一类放射性物品运输容器设计单位变更单位名称、住所或者法定代表人的，应当自工商变更登记之日起20日内，向国务院核安全监管部门办理设计批准书变更手续，并提交变更申请、工商注册登记文件以及其他证明材料。"},{"i":13,"n":"第十三条","txt":"[特殊形式批准]为了控制放射性物品在运输过程中可能产生的弥散，放射性物品设计成特殊形式或者低弥散形式的，其防弥散的形式可视为放射性物品运输容器包容系统的组成部分。 特殊形式放射性物品和低弥散放射性物品的设计方案，应当符合国家放射性物品运输安全标准的有关要求，并报国务院核安全监管部门审查批准。 特殊形式放射性物品和低弥散放射性物品的设计单位，应当向国务院核安全监管部门提交其设计方案符合国家放射性物品运输安全标准有关要求的证明材料。 国务院核安全监管部门对符合国家放射性物品运输安全标准有关要求的，颁发相应的设计批准书，并公告设计批准编号；对不符合国家放射性物品运输安全标准有关要求的，书面通知申请单位并说明理由。 对于特殊形式放射性物品和低弥散放射性物品设计的延续、变更依据本办法第十一条和第十二条规定进行。"},{"i":14,"n":"第十四条","txt":"[设计备案要求]二类放射性物品运输容器的设计单位应当按照国家放射性物品运输安全标准进行设计，并在首次用于制造30日前，将下列文件报国务院核安全监管部门备案： （一）设计总图及其设计说明书； （二）设计安全评价报告表。 国务院核安全监管部门应当定期公布已备案的二类放射性物品运输容器的设计备案编号。"},{"i":15,"n":"第十五条","txt":"[制造基本要求]从事一类放射性物品运输容器制造活动的单位，应当向国务院核安全监管部门申请领取制造许可证。 从事二类放射性物品运输容器制造活动的单位，应当报国务院核安全监管部门备案。"},{"i":16,"n":"第十六条","txt":"[制造单位条件]申请领取制造许可证的单位，应当具备下列条件： （一）具有法人资格； （二）有与所从事制造活动相关或者相近的工作业绩； （三）有与所从事制造活动相适应的机械、焊接、材料和热处理、铸造和锻造等相关专业技术人员，以及取得焊工、焊接操作工或者无损检验资格证书的专业技术人员； （四）有与所从事的制造活动相适应的生产条件和检测手段； （五）有健全的管理制度、完善的质量保证体系和符合国家有关核安全监督管理规定的质量保证大纲。"},{"i":17,"n":"第十七条","txt":"[制造申请]申请领取放射性物品运输容器制造许可证的单位，应当向国务院核安全监管部门提交申请书，并提交符合规定条件的证明文件。"},{"i":18,"n":"第十八条","txt":"[制造审查]国务院核安全监管部门应当自受理申请之日起45个工作日内完成审查，对符合条件的，颁发制造许可证，并予以公告；对不符合条件的，书面通知申请单位并说明理由。 国务院核安全监管部门在审查过程中，应当组织专家进行技术评审。技术评审可以采取文件审查、审评对话和现场检查等方式。 技术评审所需时间，不计算在本条第一款规定的期限内。"},{"i":19,"n":"第十九条","txt":"[制造许可证]一类放射性物品运输容器制造许可证应当载明下列内容： （一）制造单位名称、住所和法定代表人； （二）许可制造的运输容器设计批准编号； （三）有效期限； （四）发证机关、发证日期和证书编号。"},{"i":20,"n":"第二十条","txt":"[制造许可延续]一类放射性物品运输容器制造许可证有效期为5年。 制造许可证有效期届满，需要延续的，制造单位应当于制造许可证有效期届满6个月前，向国务院核安全监管部门提出书面延续申请，并提交下列材料： （一）原制造许可证有效期内的制造活动情况；　　 （二）原制造许可证有效期内所制造运输容器的质量情况； （三）原制造许可证有效期内变更情况的说明。 国务院核安全监管部门应当在制造许可证有效期届满前作出是否准予延续的决定。"},{"i":21,"n":"第二十一条","txt":"[制造许可变更]一类放射性物品运输容器制造单位制造与原许可制造的设计批准编号不同的运输容器的，应当按照原申请程序向国务院核安全监管部门重新申请领取制造许可证。 一类放射性物品运输容器制造单位变更单位名称、住所或者法定代表人的，应当自工商变更登记之日起20日内，向国务院核安全监管部门办理制造许可证变更手续，并提交变更申请、工商注册登记文件以及其他证明材料。"},{"i":22,"n":"第二十二条","txt":"[制造禁止事项]禁止无制造许可证或者超出制造许可证规定范围从事一类放射性物品运输容器制造活动。 禁止委托未取得相应制造许可证的单位进行一类放射性物品运输容器制造活动。 禁止伪造、变造、转让制造许可证。"},{"i":23,"n":"第二十三条","txt":"[制造单位备案]从事二类放射性物品运输容器制造活动的单位，应当在首次制造活动开始30日前，将下列材料报国务院核安全监管部门备案： （一）所制造运输容器的设计备案编号； （二）具备与从事制造活动相适应的专业技术人员、生产条件、检测手段的证明材料； （三）具有健全管理制度的证明材料； （四）质量保证大纲。 国务院核安全监管部门应当定期公布已备案的二类放射性物品运输容器制造单位。"},{"i":24,"n":"第二十四条","txt":"[使用基本要求]使用境外单位制造的一类放射性物品运输容器的，应当在首次使用前报国务院核安全监管部门审查批准。 使用境外单位制造的二类放射性物品运输容器的，应当在首次使用前报国务院核安全监管部门备案。"},{"i":25,"n":"第二十五条","txt":"[使用申请]申请使用境外单位制造的一类放射性物品运输容器的单位，应当向国务院核安全监管部门提出书面申请，并提交下列材料： （一）设计单位所在国核安全监管部门颁发的设计批准文件的复印件； （二）设计单位出具的设计安全评价报告书； （三）制造单位相关业绩的证明材料； （四）制造单位出具的质量合格证明； （五）符合中华人民共和国法律、行政法规规定，以及国家放射性物品运输安全标准或者经国务院核安全监管部门认可的标准的说明材料。"},{"i":26,"n":"第二十六条","txt":"[使用审查]国务院核安全监管部门应当自受理申请之日起45个工作日内完成审查，对符合国家放射性物品运输安全标准的，颁发使用批准书；对不符合国家放射性物品运输安全标准的，书面通知申请单位并说明理由。 在审查过程中，国务院核安全监管部门可以组织专家进行技术评审。技术评审所需时间不计算在前款规定的期限内。"},{"i":27,"n":"第二十七条","txt":"[使用批准书]境外单位制造的一类放射性物品运输容器使用批准书应当载明下列内容： （一）使用单位名称、住所和法定代表人； （二）设计单位名称、制造单位名称； （三）原设计批准编号； （四）操作要求、运输方式、使用环境温度； （五）运输容器编码； （六）有效期限； （七）批准日期和批准书编号。"},{"i":28,"n":"第二十八条","txt":"[使用批准延续]境外单位制造的一类放射性物品运输容器使用批准书有效期为5年。 使用批准书有效期届满，需要延续的，使用单位应当于使用批准书有效期届满6个月前，向国务院核安全监管部门提出书面延续申请，并提交下列材料： （一）原使用批准书有效期内运输容器使用情况报告； （二）原使用批准书有效期内质量保证大纲实施效果的说明； （三）原使用批准书有效期内运输容器维护、维修和安全性能评价情况说明。 对于使用单位提出的批准书延续申请，国务院核安全监管部门应当在使用批准书有效期届满前作出是否准予延续的决定。"},{"i":29,"n":"第二十九条","txt":"[使用批准变更]持有境外单位制造的一类放射性物品运输容器使用批准书的使用单位，变更单位名称、住所或者法定代表人的，应当自工商登记之日起20日内，向国务院核安全监管部门办理使用批准书变更手续，并提交变更申请、工商注册登记文件以及其他证明材料。"},{"i":30,"n":"第三十条","txt":"[使用备案]使用境外单位制造的二类放射性物品运输容器的，应当在首次使用前将下列文件报国务院核安全监管部门备案： （一）制造单位出具的质量合格证明； （二）设计单位出具的设计安全评价报告表； （三）符合中华人民共和国法律、行政法规规定，以及国家放射性物品运输安全标准或者经国务院核安全监管部门认可的标准的说明材料。 国务院核安全监管部门办理使用境外单位制造的二类放射性物品运输容器备案手续，应当同时为运输容器确定编码。"},{"i":31,"n":"第三十一条","txt":"[运输基本要求]托运一类放射性物品的，托运人应当编制放射性物品运输的核与辐射安全分析报告书，报国务院核安全监管部门审查批准。 一类放射性物品从境外运抵中华人民共和国境内，或者途经中华人民共和国境内运输的，托运人应当编制放射性物品运输的核与辐射安全分析报告书，报国务院核安全监管部门审查批准。 二类、三类放射性物品从境外运抵中华人民共和国境内，或者途经中华人民共和国境内运输的，托运人应当编制放射性物品运输的辐射监测报告，报国务院核安全监管部门备案。"},{"i":32,"n":"第三十二条","txt":"[报告书编制]托运人可以自行或者委托技术单位编制放射性物品运输的核与辐射安全分析报告书。 放射性物品运输的核与辐射安全分析报告书的格式和内容，由国务院核安全监管部门规定。"},{"i":33,"n":"第三十三条","txt":"[运输审查]国务院核安全监管部门应当自受理放射性物品运输的核与辐射安全分析报告书之日起45个工作日内完成审查，对符合国家放射性物品运输安全标准的，颁发核与辐射安全分析报告批准书；对不符合国家放射性物品运输安全标准的，书面通知申请单位并说明理由。 在审查过程中，国务院核安全监管部门可以组织专家进行技术评审。技术评审所需时间不计算在前款规定的期限内。"},{"i":34,"n":"第三十四条","txt":"[运输批准书]放射性物品运输的核与辐射安全分析报告批准书应当载明下列主要内容： （一）托运人的名称、地址、法定代表人； （二）运输放射性物品的品名、数量； （三）运输容器设计批准编号、运输方式和运输方案； （四）操作管理附加措施和规定； （五）有效期限； （六）批准日期和批准书编号。"},{"i":35,"n":"第三十五条","txt":"[运输批准延续]一类放射性物品运输的核与辐射安全分析报告批准书有效期为5年。 核与辐射安全分析报告批准书有效期届满，需要延续的，托运人应当于核与辐射安全分析报告批准书有效期届满6个月前，向国务院核安全监管部门提出书面延续申请，并提交下列材料： （一）原核与辐射安全分析报告批准书有效期内运输容器使用情况报告，包括维护、维修和安全性能评价情况说明； （二）运输活动情况报告，包括运输方案、辐射防护措施和应急措施执行情况说明。 对于托运人提出的批准书延续申请，国务院核安全监管部门应当在核与辐射安全分析报告批准书有效期届满前作出是否准予延续的决定。"},{"i":36,"n":"第三十六条","txt":"[运输批准变更]持有核与辐射安全分析报告批准书的单位，变更单位名称、地址或者法定代表人的，应当自工商变更登记之日起20日内，向国务院核安全监管部门办理核与辐射安全分析报告批准书变更手续，并提交变更申请、工商注册登记文件以及其他证明材料。"},{"i":37,"n":"第三十七条","txt":"[启运备案]一类放射性物品启运前，托运人应当将下列材料报启运地的省、自治区、直辖市人民政府生态环境主管部门备案： （一）一类放射性物品运输辐射监测备案表； （二）辐射监测报告。 前款规定的辐射监测报告，在托运人委托有资质的辐射监测机构对拟托运一类放射性物品的表面污染和辐射水平实施监测后，由辐射监测机构出具。 收到备案材料的省、自治区、直辖市人民政府生态环境主管部门，应当在启运前将备案表通报放射性物品运输的途经地和抵达地的省、自治区、直辖市人民政府生态环境主管部门。"},{"i":38,"n":"第三十八条","txt":"[特殊安排]有下列情形之一，放射性物品运输容器无法完全符合国家放射性物品运输安全标准，需要通过特殊安排来提高运输安全水平的，托运人应当编制放射性物品运输的核与辐射安全分析报告书，在运输前报经国务院核安全监管部门审查同意： （一）因形状特异不适宜专门设计和制造运输容器的； （二）只是一次性运输，专门设计和制造符合国家放射性物品运输安全标准的运输容器经济上明显不合理的。"},{"i":39,"n":"第三十九条","txt":"[过境运输审批]一类放射性物品从境外运抵中华人民共和国境内，或者途经中华人民共和国境内运输的，托运人或者其委托代理人应当编制放射性物品运输的核与辐射安全分析报告书，报国务院核安全监管部门审查批准。审查批准程序依照本办法第三十三条的规定执行。 托运人获得国务院核安全监管部门颁发的核与辐射安全分析报告批准书后，方可将一类放射性物品运抵中华人民共和国境内或者途经中华人民共和国境内运输。"},{"i":40,"n":"第四十条","txt":"[过境运输备案]二类、三类放射性物品从境外运抵中华人民共和国境内，或者途经中华人民共和国境内运输的，托运人应当委托有资质的单位监测，编制放射性物品运输的辐射监测报告，报国务院核安全监管部门备案。国务院核安全监管部门应当出具相应的放射性物品运输的辐射监测报告备案证明。 对于运输容器相同，放射性内容物相同，且半衰期小于60天的放射性物品，进口单位可以每半年办理一次辐射监测报告备案手续。"},{"i":41,"n":"第四十一条","txt":"[过境海关手续]放射性物品从境外运抵中华人民共和国境内，或者途经中华人民共和国境内运输的，托运人、承运人或者其代理人向海关办理有关手续时，应当提交相关许可证件和国务院核安全监管部门颁发的放射性物品运输的核与辐射安全分析报告批准书或者放射性物品运输的辐射监测报告备案证明。"},{"i":42,"n":"第四十二条","txt":"[运输资质]托运人应当委托具有放射性物品运输资质的承运人承运放射性物品。 自行运输本单位放射性物品的单位和在放射性废物收贮过程中的从事放射性物品运输的省、自治区、直辖市城市放射性废物库运营单位，应当取得非营业性道路危险货物运输资质。"},{"i":43,"n":"第四十三条","txt":"[术语]本办法下列用语的含义： （一）特殊形式放射性物品：不弥散的固体放射性物品或者装有放射性物品的密封件。 （二）低弥散放射性物品：固体放射性物品，或者装在密封件里的固体放射性物品，其弥散性已受到限制且不呈粉末状。 （三）托运人：将托运货物提交运输的单位或者个人。 （四）承运人：使用任何运输手段承担放射性物质运输的单位或者个人。"},{"i":44,"n":"第四十四条","txt":"[生效日期]本办法自2010年11月1日起施行。 附一： 一类放射性物品运输容器设计和核与辐射安全分析报告批准编号规则 其中： 第1－2位：国家或地区代码，CN代表中国。 第3位：“/”，隔离符。 第4－6位：主管部门为该设计指定的设计批准编号或核与辐射安全分析报告批准编号,一类放射性物品运输容器设计批准编号范围为001－500。 第7位：“/”，隔离符。 第8位：批准书类型： AF： 易裂变A型运输容器设计批准书 B（U）：B(U)型运输容器设计批准书 B（U）F：易裂变材料B(U)型运输容器设计批准书 B（M）：B(M)型运输容器设计批准书 B（M）F：易裂变材料B(M)型运输容器设计批准书 C：C型运输容器设计批准书 CF：易裂变材料C型运输容器设计批准书 IF：易裂变材料工业运输容器设计批准书 S ：特殊形式放射性物品设计批准书 LD：低弥散放射性物品设计批准书 T：核与辐射安"}],"xinhuaxuewuzhihuanjingguanlidengjibanfa":[{"i":1,"n":"第一条","txt":"为规范新化学物质环境管理登记行为，科学、有效评估和管控新化学物质环境风险，聚焦对环境和健康可能造成较大风险的新化学物质，保护生态环境，保障公众健康，根据有关法律法规以及《国务院对确需保留的行政审批项目设定行政许可的决定》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于在中华人民共和国境内从事新化学物质研究、生产、进口和加工使用活动的环境管理登记，但进口后在海关特殊监管区内存放且未经任何加工即全部出口的新化学物质除外。 下列产品或者物质不适用本办法： （一）医药、农药、兽药、化妆品、食品、食品添加剂、饲料、饲料添加剂、肥料等产品，但改变为其他工业用途的，以及作为上述产品的原料和中间体的新化学物质除外； （二）放射性物质。 设计为常规使用时有意释放出所含新化学物质的物品，所含的新化学物质适用本办法。"},{"i":3,"n":"第三条","txt":"本办法所称新化学物质，是指未列入《中国现有化学物质名录》的化学物质。 已列入《中国现有化学物质名录》的化学物质，按照现有化学物质进行环境管理；但在《中国现有化学物质名录》中规定实施新用途环境管理的化学物质，用于允许用途以外的其他工业用途的，按照新化学物质进行环境管理。 《中国现有化学物质名录》由国务院生态环境主管部门组织制定、调整并公布，包括2003年10月15日前已在中华人民共和国境内生产、销售、加工使用或者进口的化学物质，以及2003年10月15日以后根据新化学物质环境管理有关规定列入的化学物质。"},{"i":4,"n":"第四条","txt":"国家对新化学物质实行环境管理登记制度。 新化学物质环境管理登记分为常规登记、简易登记和备案。新化学物质的生产者或者进口者，应当在生产前或者进口前取得新化学物质环境管理常规登记证或者简易登记证(以下统称登记证)或者办理新化学物质环境管理备案。"},{"i":5,"n":"第五条","txt":"新化学物质环境管理登记，遵循科学、高效、公开、公平、公正和便民的原则，坚持源头准入、风险防范、分类管理，重点管控具有持久性、生物累积性、对环境或者健康危害性大，或者在环境中可能长期存在并可能对环境和健康造成较大风险的新化学物质。"},{"i":6,"n":"第六条","txt":"国务院生态环境主管部门负责组织开展全国新化学物质环境管理登记工作，制定新化学物质环境管理登记相关政策、技术规范和指南等配套文件以及登记评审规则，加强新化学物质环境管理登记信息化建设。 国务院生态环境主管部门组织成立化学物质环境风险评估专家委员会（以下简称专家委员会）。专家委员会由化学、化工、健康、环境、经济等方面的专家组成，为新化学物质环境管理登记评审提供技术支持。 设区的市级以上地方生态环境主管部门负责对本行政区域内研究、生产、进口和加工使用新化学物质的相关企业事业单位落实本办法的情况进行环境监督管理。 国务院生态环境主管部门所属的化学物质环境管理技术机构参与新化学物质环境管理登记评审，承担新化学物质环境管理登记具体工作。"},{"i":7,"n":"第七条","txt":"从事新化学物质研究、生产、进口和加工使用的企业事业单位，应当遵守本办法的规定，采取有效措施，防范和控制新化学物质的环境风险，并对所造成的损害依法承担责任。"},{"i":8,"n":"第八条","txt":"国家鼓励和支持新化学物质环境风险评估及控制技术的科学研究与推广应用，鼓励环境友好型化学物质及相关技术的研究与应用。"},{"i":9,"n":"第九条","txt":"一切单位和个人对违反本办法规定的行为，有权向生态环境主管部门举报。"},{"i":10,"n":"第十条","txt":"新化学物质年生产量或者进口量10吨以上的，应当办理新化学物质环境管理常规登记（以下简称常规登记）。 新化学物质年生产量或者进口量1吨以上不足10吨的，应当办理新化学物质环境管理简易登记（以下简称简易登记）。 符合下列条件之一的，应当办理新化学物质环境管理备案（以下简称备案）： （一）新化学物质年生产量或者进口量不足1吨的； （二）新化学物质单体或者反应体含量不超过2％的聚合物或者属于低关注聚合物的。"},{"i":11,"n":"第十一条","txt":"办理新化学物质环境管理登记的申请人，应当为中华人民共和国境内依法登记能够独立承担法律责任的，从事新化学物质生产或者进口的企业事业单位。 拟向中华人民共和国境内出口新化学物质的生产或者贸易企业，也可以作为申请人，但应当指定在中华人民共和国境内依法登记能够独立承担法律责任的企业事业单位作为代理人，共同履行新化学物质环境管理登记及登记后环境管理义务，并依法承担责任。 本办法第二条规定的医药、农药、兽药、化妆品、食品、食品添加剂、饲料、饲料添加剂、肥料等产品属于新化学物质，且拟改变为其他工业用途的，相关产品的生产者、进口者或者加工使用者均可以作为申请人。 已列入《中国现有化学物质名录》且实施新用途环境管理的化学物质，拟用于允许用途以外的其他工业用途的，相关化学物质的生产者、进口者或者加工使用者均可以作为申请人。"},{"i":12,"n":"第十二条","txt":"申请办理新化学物质环境管理登记的，申请人应当向国务院生态环境主管部门提交登记申请或者备案材料，并对登记申请或者备案材料的真实性、完整性、准确性和合法性负责。 国家鼓励申请人共享新化学物质环境管理登记数据。"},{"i":13,"n":"第十三条","txt":"申请人认为其提交的登记申请或者备案材料涉及商业秘密且要求信息保护的，应当在申请登记或者办理备案时提出，并提交申请商业秘密保护的必要性说明材料。对可能对环境、健康公共利益造成重大影响的信息，国务院生态环境主管部门可以依法不予商业秘密保护。对已提出的信息保护要求，申请人可以以书面方式撤回。 新化学物质名称等标识信息的保护期限自首次登记或者备案之日起不超过五年。 从事新化学物质环境管理登记的工作人员和相关专家，不得披露依法应当予以保护的商业秘密。"},{"i":14,"n":"第十四条","txt":"为新化学物质环境管理登记提供测试数据的中华人民共和国境内测试机构，应当依法取得检验检测机构资质认定，严格按照化学物质测试相关标准开展测试工作；健康毒理学、生态毒理学测试机构还应当符合良好实验室管理规范。测试机构应当对其出具的测试结果的真实性和可靠性负责，并依法承担责任。 国务院生态环境主管部门组织对化学物质生态毒理学测试机构的测试情况及条件进行监督抽查。 出具健康毒理学或者生态毒理学测试数据的中华人民共和国境外测试机构应当符合国际通行的良好实验室管理要求。"},{"i":15,"n":"第十五条","txt":"申请办理常规登记的，申请人应当提交以下材料： （一）常规登记申请表； （二）新化学物质物理化学性质、健康毒理学和生态毒理学特性测试报告或者资料； （三）新化学物质环境风险评估报告，包括对拟申请登记的新化学物质可能造成的环境风险的评估，拟采取的环境风险控制措施及其适当性分析，以及是否存在不合理环境风险的评估结论； （四）落实或者传递环境风险控制措施和环境管理要求的承诺书，承诺书应当由企业事业单位的法定代表人或者其授权人签字，并加盖公章。 前款第二项规定的相关测试报告和资料，应当满足新化学物质环境风险评估的需要；生态毒理学测试报告应当包括使用中华人民共和国的供试生物按照相关标准的规定完成的测试数据。 对属于高危害化学物质的，申请人还应当提交新化学物质活动的社会经济效益分析材料，包括新化学物质在性能、环境友好性等方面是否较相同用途的在用化学物质具有相当或者明显优势的说明，充分论证申请活动的必"},{"i":16,"n":"第十六条","txt":"申请办理简易登记的，申请人应当提交以下材料： （一）简易登记申请表； （二）新化学物质物理化学性质，以及持久性、生物累积性和水生环境毒性等生态毒理学测试报告或者资料； （三）落实或者传递环境风险控制措施的承诺书，承诺书应当由企业事业单位的法定代表人或者其授权人签字，并加盖公章。 前款第二项规定的生态毒理学测试报告应当包括使用中华人民共和国的供试生物按照相关标准的规定完成的测试数据。 除前款规定的申请材料外，申请人还应当一并提交其已经掌握的新化学物质环境与健康危害特性和环境风险的其他信息。"},{"i":17,"n":"第十七条","txt":"同一申请人对分子结构相似、用途相同或者相近、测试数据相近的多个新化学物质，可以一并申请新化学物质环境管理登记。申请登记量根据每种物质申请登记量的总和确定。 两个以上申请人同时申请相同新化学物质环境管理登记的，可以共同提交申请材料，办理新化学物质环境管理联合登记。申请登记量根据每个申请人申请登记量的总和确定。"},{"i":18,"n":"第十八条","txt":"国务院生态环境主管部门收到新化学物质环境管理登记申请材料后，根据下列情况分别作出处理： （一）申请材料齐全、符合法定形式，或者申请人按照要求提交全部补正申请材料的，予以受理； （二）申请材料存在可以当场更正的错误的，允许申请人当场更正； （三）所申请物质不需要开展新化学物质环境管理登记的，或者申请材料存在法律法规规定不予受理的其他情形的，应当当场或者在五个工作日内作出不予受理的决定； （四）存在申请人及其代理人不符合本办法规定、申请材料不齐全以及其他不符合法定形式情形的，应当当场或者在五个工作日内一次性告知申请人需要补正的全部内容。逾期不告知的，自收到申请材料之日起即为受理。"},{"i":19,"n":"第十九条","txt":"国务院生态环境主管部门受理常规登记申请后，应当组织专家委员会和所属的化学物质环境管理技术机构进行技术评审。技术评审应当主要围绕以下内容进行： （一）新化学物质名称和标识； （二）新化学物质测试报告或者资料的质量； （三）新化学物质环境和健康危害特性； （四）新化学物质环境暴露情况和环境风险； （五）列入《中国现有化学物质名录》时是否实施新用途环境管理； （六）环境风险控制措施是否适当； （七）高危害化学物质申请活动的必要性； （八）商业秘密保护的必要性。 技术评审意见应当包括对前款规定内容的评审结论，以及是否准予登记的建议和有关环境管理要求的建议。 经技术评审认为申请人提交的申请材料不符合要求的，或者不足以对新化学物质的环境风险作出全面评估的，国务院生态环境主管部门可以要求申请人补充提供相关测试报告或者资料。"},{"i":20,"n":"第二十条","txt":"国务院生态环境主管部门受理简易登记申请后，应当组织其所属的化学物质环境管理技术机构进行技术评审。技术评审应当主要围绕以下内容进行： （一）新化学物质名称和标识； （二）新化学物质测试报告或者资料的质量； （三）新化学物质的持久性、生物累积性和毒性； （四）新化学物质的累积环境风险； （五）商业秘密保护的必要性。 技术评审意见应当包括对前款规定内容的评审结论，以及是否准予登记的建议。 经技术评审认为申请人提交的申请材料不符合要求的，国务院生态环境主管部门可以要求申请人补充提供相关测试报告或者资料。"},{"i":21,"n":"第二十一条","txt":"国务院生态环境主管部门对常规登记技术评审意见进行审查，根据下列情况分别作出决定： （一）未发现不合理环境风险的，予以登记，向申请人核发新化学物质环境管理常规登记证（以下简称常规登记证）。对高危害化学物质核发常规登记证，还应当符合申请活动必要性的要求； （二）发现有不合理环境风险的，或者不符合高危害化学物质申请活动必要性要求的，不予登记，书面通知申请人并说明理由。"},{"i":22,"n":"第二十二条","txt":"国务院生态环境主管部门对简易登记技术评审意见进行审查，根据下列情况分别作出决定： （一）对未发现同时具有持久性、生物累积性和毒性，且未发现累积环境风险的，予以登记，向申请人核发新化学物质环境管理简易登记证（以下简称简易登记证）； （二）不符合前项规定登记条件的，不予登记，书面通知申请人并说明理由。"},{"i":23,"n":"第二十三条","txt":"有下列情形之一的，国务院生态环境主管部门不予登记，书面通知申请人并说明理由： （一）在登记申请过程中使用隐瞒情况或者提供虚假材料等欺骗手段的； （二）未按照本办法第十九条第三款或者第二十条第三款的要求，拒绝或者未在六个月内补充提供相关测试报告或者资料的； （三）法律法规规定不予登记的其他情形。"},{"i":24,"n":"第二十四条","txt":"国务院生态环境主管部门作出登记决定前，应当对拟登记的新化学物质名称或者类名、申请人及其代理人、活动类型、新用途环境管理要求等信息进行公示。公示期限不得少于三个工作日。"},{"i":25,"n":"第二十五条","txt":"国务院生态环境主管部门受理新化学物质环境管理登记申请后，应当及时启动技术评审工作。常规登记的技术评审时间不得超过六十日，简易登记的技术评审时间不得超过三十日。国务院生态环境主管部门通知补充提供相关测试报告或者资料的，申请人补充相关材料所需时间不计入技术评审时限。 国务院生态环境主管部门应当自受理申请之日起二十个工作日内，作出是否予以登记的决定。二十个工作日内不能作出决定的，经国务院生态环境主管部门负责人批准，可以延长十个工作日，并将延长期限的理由告知申请人。 技术评审时间不计入本条第二款规定的审批时限。"},{"i":26,"n":"第二十六条","txt":"登记证应当载明下列事项： （一）登记证类型； （二）申请人及其代理人名称； （三）新化学物质中英文名称或者类名等标识信息； （四）申请用途； （五）申请登记量； （六）活动类型； （七）环境风险控制措施。 对于高危害化学物质以及具有持久性和生物累积性，或者具有持久性和毒性，或者具有生物累积性和毒性的新化学物质，常规登记证还应当载明下列一项或者多项环境管理要求： （一）限定新化学物质排放量或者排放浓度； （二）列入《中国现有化学物质名录》时实施新用途环境管理的要求； （三）提交年度报告； （四）其他环境管理要求。"},{"i":27,"n":"第二十七条","txt":"新化学物质环境管理登记申请受理后，国务院生态环境主管部门作出决定前，申请人可以依法撤回登记申请。"},{"i":28,"n":"第二十八条","txt":"国务院生态环境主管部门作出新化学物质环境管理登记决定后，应当在二十个工作日内公开新化学物质环境管理登记情况，包括登记的新化学物质名称或者类名、申请人及其代理人、活动类型、新用途环境管理要求等信息。"},{"i":29,"n":"第二十九条","txt":"对已取得常规登记证的新化学物质，在根据本办法第四十四条规定列入《中国现有化学物质名录》前，有下列情形之一的，登记证持有人应当重新申请办理登记： （一）生产或者进口数量拟超过申请登记量的； （二）活动类型拟由进口转为生产的； （三）拟变更新化学物质申请用途的； （四）拟变更环境风险控制措施的； （五）导致环境风险增大的其他情形。 重新申请办理登记的，申请人应当提交重新登记申请材料，说明相关事项变更的理由，重新编制并提交环境风险评估报告，重点说明变更后拟采取的环境风险控制措施及其适当性，以及是否存在不合理环境风险。"},{"i":30,"n":"第三十条","txt":"对已取得常规登记证的新化学物质，在根据本办法第四十四条规定列入《中国现有化学物质名录》前，除本办法第二十九条规定的情形外，登记证载明的其他信息发生变化的，登记证持有人应当申请办理登记证变更。 对已取得简易登记证的新化学物质，登记证载明的信息发生变化的，登记证持有人应当申请办理登记证变更。 申请办理登记证变更的，申请人应当提交变更理由及相关证明材料。其中，拟变更新化学物质中英文名称或者化学文摘社编号（CAS）等标识信息的，证明材料中应当充分论证变更前后的化学物质属于同一种化学物质。 国务院生态环境主管部门参照简易登记程序和时限受理并组织技术评审，作出登记证变更决定。其中，对于拟变更新化学物质中英文名称或者化学文摘社编号（CAS）等标识信息的，国务院生态环境主管部门可以组织专家委员会进行技术评审；对于无法判断变更前后化学物质属于同一种化学物质的，不予批准变更。"},{"i":31,"n":"第三十一条","txt":"对根据本办法第四十四条规定列入《中国现有化学物质名录》的下列化学物质，应当实施新用途环境管理： （一）高危害化学物质； （二）具有持久性和生物累积性，或者具有持久性和毒性，或者具有生物累积性和毒性的化学物质。 对高危害化学物质，登记证持有人变更用途的，或者登记证持有人之外的其他人将其用于工业用途的，应当在生产、进口或者加工使用前，向国务院生态环境主管部门申请办理新用途环境管理登记。 对本条第一款第二项所列化学物质，拟用于本办法第四十四条规定的允许用途外其他工业用途的，应当在生产、进口或者加工使用前，向国务院生态环境主管部门申请办理新用途环境管理登记。"},{"i":32,"n":"第三十二条","txt":"申请办理新用途环境管理登记的，申请人应当提交新用途环境管理登记申请表以及该化学物质用于新用途的环境暴露评估报告和环境风险控制措施等材料。对高危害化学物质，还应当提交社会经济效益分析材料，充分论证该物质用于所申请登记用途的必要性。 国务院生态环境主管部门收到申请材料后，按照常规登记程序受理和组织技术评审，根据下列情况分别作出处理，并书面通知申请人： （一）未发现不合理环境风险的，予以登记。对高危害化学物质，还应当符合申请用途必要性的要求； （二）发现有不合理环境风险，或者不符合高危害化学物质申请用途必要性要求的，不予登记。 国务院生态环境主管部门作出新用途环境管理登记决定后，应当在二十个工作日内公开予以登记的申请人及其代理人名称、涉及的化学物质名称或者类名、登记的新用途，以及相应的环境风险控制措施和环境管理要求。其中，不属于高危害化学物质的，在《中国现有化学物质名录》中增列该化学物质已登"},{"i":33,"n":"第三十三条","txt":"申请人取得登记证后，可以向国务院生态环境主管部门申请撤销登记证。"},{"i":34,"n":"第三十四条","txt":"有下列情形之一的，为了公共利益的需要，国务院生态环境主管部门可以依照《中华人民共和国行政许可法》的有关规定，变更或者撤回登记证： （一）根据本办法第四十二条的规定需要变更或者撤回的； （二）新化学物质环境管理登记内容不符合国家产业政策的； （三）相关法律、行政法规或者强制性标准发生变动的； （四）新化学物质环境管理登记内容与中华人民共和国缔结或者参加的国际条约要求相抵触的； （五）法律法规规定的应当变更或者撤回的其他情形。"},{"i":35,"n":"第三十五条","txt":"有下列情形之一的，国务院生态环境主管部门可以依照《中华人民共和国行政许可法》的有关规定，撤销登记证： （一）申请人或者其代理人以欺骗、贿赂等不正当手段取得登记证的； （二）国务院生态环境主管部门工作人员滥用职权、玩忽职守或者违反法定程序核发登记证的； （三）法律法规规定的应当撤销的其他情形。"},{"i":36,"n":"第三十六条","txt":"办理新化学物质环境管理备案的，应当提交备案表和符合本办法第十条第三款规定的相应情形的证明材料，并一并提交其已经掌握的新化学物质环境与健康危害特性和环境风险的其他信息。"},{"i":37,"n":"第三十七条","txt":"国务院生态环境主管部门收到新化学物质环境管理备案材料后，对完整齐全的备案材料存档备查，并发送备案回执。申请人提交备案材料后，即可按照备案内容开展新化学物质相关活动。 新化学物质环境管理备案事项或者相关信息发生变化时，申请人应当及时对备案信息进行变更。 国务院生态环境主管部门应当定期公布新化学物质环境管理备案情况。"},{"i":38,"n":"第三十八条","txt":"新化学物质的生产者、进口者、加工使用者应当向下游用户传递下列信息： （一）登记证号或者备案回执号； （二）新化学物质申请用途； （三）新化学物质环境和健康危害特性及环境风险控制措施； （四）新化学物质环境管理要求。 新化学物质的加工使用者可以要求供应商提供前款规定的新化学物质的相关信息。"},{"i":39,"n":"第三十九条","txt":"新化学物质的研究者、生产者、进口者和加工使用者应当建立新化学物质活动情况记录制度，如实记录新化学物质活动时间、数量、用途，以及落实环境风险控制措施和环境管理要求等情况。 常规登记和简易登记材料以及新化学物质活动情况记录等相关资料应当至少保存十年。备案材料以及新化学物质活动情况记录等相关资料应当至少保存三年。"},{"i":40,"n":"第四十条","txt":"常规登记新化学物质的生产者和加工使用者，应当落实环境风险控制措施和环境管理要求，并通过其官方网站或者其他便于公众知晓的方式公开环境风险控制措施和环境管理要求落实情况。"},{"i":41,"n":"第四十一条","txt":"登记证持有人应当在首次生产之日起六十日内，或者在首次进口并向加工使用者转移之日起六十日内，向国务院生态环境主管部门报告新化学物质首次活动情况。 常规登记证上载明的环境管理要求规定了提交年度报告要求的，登记证持有人应当自登记的次年起，每年4月30日前向国务院生态环境主管部门报告上一年度获准登记新化学物质的实际生产或者进口情况、向环境排放情况，以及环境风险控制措施和环境管理要求的落实情况。"},{"i":42,"n":"第四十二条","txt":"新化学物质的研究者、生产者、进口者和加工使用者发现新化学物质有新的环境或者健康危害特性或者环境风险的，应当及时向国务院生态环境主管部门报告；可能导致环境风险增加的，应当及时采取措施消除或者降低环境风险。 国务院生态环境主管部门根据全国新化学物质环境管理登记情况、实际生产或者进口情况、向环境排放情况，以及新发现的环境或者健康危害特性等，对环境风险可能持续增加的新化学物质，可以要求相关研究者、生产者、进口者和加工使用者，进一步提交相关环境或者健康危害、环境暴露数据信息。 国务院生态环境主管部门收到相关信息后，应当组织所属的化学物质环境管理技术机构和专家委员会进行技术评审；必要时，可以根据评审结果依法变更或者撤回相应的登记证。"},{"i":43,"n":"第四十三条","txt":"国务院生态环境主管部门应当将新化学物质环境管理登记情况、环境风险控制措施和环境管理要求、首次活动情况、年度报告等信息通报省级生态环境主管部门；省级生态环境主管部门应当将上述信息通报设区的市级生态环境主管部门。 设区的市级以上生态环境主管部门，应当对新化学物质生产者、进口者和加工使用者是否按要求办理新化学物质环境管理登记、登记事项的真实性、登记证载明事项以及本办法其他相关规定的落实情况进行监督抽查。 新化学物质的研究者、生产者、进口者和加工使用者应当如实提供相关资料，接受生态环境主管部门的监督抽查。"},{"i":44,"n":"第四十四条","txt":"取得常规登记证的新化学物质，自首次登记之日起满五年的，国务院生态环境主管部门应当将其列入《中国现有化学物质名录》，并予以公告。 对具有持久性和生物累积性，或者持久性和毒性，或者生物累积性和毒性的新化学物质，列入《中国现有化学物质名录》时应当注明其允许用途。 对高危害化学物质以及具有持久性和生物累积性，或者持久性和毒性，或者生物累积性和毒性的新化学物质，列入《中国现有化学物质名录》时，应当规定除年度报告之外的环境管理要求。 本条前三款规定适用于依照本办法第三十三条规定申请撤销的常规登记新化学物质。 简易登记和备案的新化学物质，以及依照本办法第三十四条、第三十五条规定被撤回或者撤销的常规登记新化学物质，不列入《中国现有化学物质名录》。"},{"i":45,"n":"第四十五条","txt":"根据《新化学物质环境管理办法》（环境保护部令第7号）的规定取得常规申报登记证的新化学物质，尚未列入《中国现有化学物质名录》的，应当自首次生产或者进口活动之日起满五年或者本办法施行之日起满五年，列入《中国现有化学物质名录》。 根据《新化学物质环境管理办法》（国家环境保护总局令第17号）的规定，取得正常申报环境管理登记的新化学物质，尚未列入《中国现有化学物质名录》的，应当自本办法施行之日起六个月内，列入《中国现有化学物质名录》。 本办法生效前已列入《中国现有化学物质名录》并实施物质名称等标识信息保护的，标识信息的保护期限最长至2025年12月31日止。"},{"i":46,"n":"第四十六条","txt":"违反本办法规定，以欺骗、贿赂等不正当手段取得新化学物质环境管理登记的，由国务院生态环境主管部门责令改正，处一万元以上三万元以下的罚款，并依法依规开展失信联合惩戒，三年内不再受理其新化学物质环境管理登记申请。"},{"i":47,"n":"第四十七条","txt":"违反本办法规定，有下列行为之一的，由国务院生态环境主管部门责令改正，处一万元以下的罚款；情节严重的，依法依规开展失信联合惩戒，一年内不再受理其新化学物质环境管理登记申请： （一）未按要求报送新化学物质首次活动情况或者上一年度获准登记新化学物质的实际生产或者进口情况，以及环境风险控制措施和环境管理要求的落实情况的； （二）未按要求报告新化学物质新的环境或者健康危害特性或者环境风险信息，或者未采取措施消除或者降低环境风险的，或者未提交环境或者健康危害、环境暴露数据信息的。"},{"i":48,"n":"第四十八条","txt":"违反本办法规定，有下列行为之一的，由设区的市级以上地方生态环境主管部门责令改正，处一万元以上三万元以下的罚款；情节严重的，依法依规开展失信联合惩戒，一年内不再受理其新化学物质环境管理登记申请： （一）未取得登记证生产或者进口新化学物质，或者加工使用未取得登记证的新化学物质的； （二）未按规定办理重新登记生产或者进口新化学物质的； （三）将未经国务院生态环境主管部门新用途环境管理登记审查或者审查后未予批准的化学物质，用于允许用途以外的其他工业用途的。"},{"i":49,"n":"第四十九条","txt":"违反本办法规定，有下列行为之一的，由设区的市级以上地方生态环境主管部门责令限期改正，处一万元以上三万元以下的罚款；情节严重的，依法依规开展失信联合惩戒，一年内不再受理其新化学物质环境管理登记申请： （一）未办理备案，或者未按照备案信息生产或者进口新化学物质，或者加工使用未办理备案的新化学物质的； （二）未按照登记证的规定生产、进口或者加工使用新化学物质的； （三）未办理变更登记，或者不按照变更内容生产或者进口新化学物质的； （四）未落实相关环境风险控制措施或者环境管理要求的，或者未按照规定公开相关信息的； （五）未向下游用户传递规定信息的，或者拒绝提供新化学物质的相关信息的； （六）未建立新化学物质活动等情况记录制度的，或者未记录新化学物质活动等情况或者保存相关资料的； （七）未落实《中国现有化学物质名录》列明的环境管理要求的。"},{"i":50,"n":"第五十条","txt":"专家委员会成员在新化学物质环境管理登记评审中弄虚作假，或者有其他失职行为，造成评审结果严重失实的，由国务院生态环境主管部门取消其专家委员会成员资格，并向社会公开。"},{"i":51,"n":"第五十一条","txt":"为新化学物质申请提供测试数据的测试机构出具虚假报告的，由国务院生态环境主管部门对测试机构处一万元以上三万元以下的罚款，对测试机构直接负责的主管人员和其他直接责任人员处一万元以上三万元以下的罚款，并依法依规开展失信联合惩戒，三年内不接受该测试机构出具的测试报告或者相关责任人员参与出具的测试报告。"},{"i":52,"n":"第五十二条","txt":"本办法中下列用语的含义： （一）环境风险，是指具有环境或者健康危害属性的化学物质在生产、加工使用、废弃及废弃处置过程中进入或者可能进入环境后，对环境和健康造成危害效应的程度和概率，不包括因生产安全事故、交通运输事故等突发事件造成的风险。 （二）高危害化学物质，是指同时具有持久性、生物累积性和毒性的化学物质，同时具有高持久性和高生物累积性的化学物质，或者其他具有同等环境或者健康危害性的化学物质。 （三）新化学物质加工使用，是指利用新化学物质进行分装、配制或者制造等生产经营活动，不包括贸易、仓储、运输等经营活动和使用含有新化学物质的物品的活动。"},{"i":53,"n":"第五十三条","txt":"根据《新化学物质环境管理办法》（环境保护部令第7号）和《新化学物质环境管理办法》（国家环境保护总局令第17号）的规定已办理新化学物质环境管理登记的，相关登记在本办法施行后继续有效。"},{"i":54,"n":"第五十四条","txt":"本办法由国务院生态环境主管部门负责解释。"},{"i":55,"n":"第五十五条","txt":"本办法自2021年1月1日起施行，原环境保护部发布的《新化学物质环境管理办法》（环境保护部令第7号）同时废止。"}],"heyufusheanquanjiandujiancharenyuanzhengjianguanli14e7e9":[{"i":1,"n":"第一条","txt":"为加强核与辐射安全监督检查人员证件管理，规范核与辐射安全监督检查工作，根据《中华人民共和国放射性污染防治法》、《中华人民共和国民用核设施安全监督管理条例》和《放射性同位素与射线装置安全和防护条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于核与辐射安全监督检查人员证件的申领、使用和管理。"},{"i":3,"n":"第三条","txt":"核与辐射安全监督检查人员证件是核与辐射安全监督检查人员依法开展核与辐射安全监督检查资格和身份的证明，分为《核安全监督员证》和《辐射安全监督员证》。 《核安全监督员证》发放范围为环境保护部（国家核安全局）及其派出机构从事核安全监督检查工作的人员。 《辐射安全监督员证》发放范围为县级以上环境保护主管部门从事辐射安全监督检查工作的人员。"},{"i":4,"n":"第四条","txt":"环境保护部（国家核安全局）负责全国核与辐射安全监督检查人员证件的管理工作。 省级环境保护主管部门负责本行政区域内《辐射安全监督员证》的管理工作。"},{"i":5,"n":"第五条","txt":"核与辐射安全监督检查人员证件的样式、编码方式和制作要求由环境保护部（国家核安全局）统一制定。"},{"i":6,"n":"第六条","txt":"持有《核安全监督员证》的人员有权进入核安全相关现场进行监督检查。持有《辐射安全监督员证》的人员有权进入辐射安全相关现场进行监督检查。 持有核与辐射安全监督检查人员证件的人员在进行核与辐射安全监督检查时，有权依法采取以下措施： （一）向被监督检查单位的有关人员进行调查、了解情况； （二）进入被监督检查单位进行现场调查或者核查； （三）查阅、复制相关文件、记录以及其他有关资料； （四）要求被监督检查单位提交有关情况说明或者后续处理报告； （五）有关法律、行政法规和规章规定的其他措施。 核与辐射安全监督检查人员在执行监督检查任务时，应当出示核与辐射安全监督检查人员证件。"},{"i":7,"n":"第七条","txt":"环境保护部（国家核安全局）及其派出机构、省级环境保护主管部门的核与辐射安全监督检查人员资格培训，由环境保护部（国家核安全局）统一组织；其他核与辐射安全监督检查人员的资格培训，由省级环境保护主管部门组织。 资格培训的教学大纲由环境保护部（国家核安全局）统一编制。省级环境保护主管部门可以结合本地实际补充培训内容。"},{"i":8,"n":"第八条","txt":"环境保护部（国家核安全局）负责发放《核安全监督员证》和省级以上《辐射安全监督员证》。 省级环境保护主管部门依照本办法的规定，负责发放本行政区域内设区的市级、县级环境保护主管部门《辐射安全监督员证》。"},{"i":9,"n":"第九条","txt":"经环境保护主管部门及其派出机构或者受委托从事核与辐射安全监督检查活动的单位推荐的工作人员，符合下列条件的，可以申请领取核与辐射安全监督检查人员证件： （一）具备本办法第十条规定的教育背景和工作经验； （二）满足本办法第十一条、第十二条规定的培训要求。 不具备本办法第十条、第十一条、第十二条规定的工作经验和培训要求，但具有本办法第十条规定的教育背景，经环境保护主管部门及其派出机构或者受委托从事核与辐射安全监督检查活动的单位人事部门批准到其单位工作，需要参加核与辐射安全监督检查的人员，可以申请领取临时核与辐射安全监督检查人员证件。"},{"i":10,"n":"第十条","txt":"申请领取核与辐射安全监督检查人员证件的人员，应当具备下列教育背景和工作经验条件之一： （一）具有理学、工学、医学等相关专业本科学历，且获得学士学位，并具有五年以上相关工作经验或者从事核与辐射安全监督检查工作三年以上； （二）获得理学、工学、医学等相关专业硕士以上学位，并具有三年以上相关工作经验或者从事核与辐射安全监督检查工作两年以上。 不具备前款规定条件，但具有大专以上同等学历，并从事核与辐射安全监督检查工作十年以上的人员，也可以申请领取核与辐射安全监督检查人员证件。"},{"i":11,"n":"第十一条","txt":"环境保护部（国家核安全局）及其派出机构人员申请领取《核安全监督员证》和《辐射安全监督员证》，应当参加环境保护部（国家核安全局）组织的初任业务培训并通过考核，并具备下列条件之一： （一）取得注册核安全工程师执业资格； （二）参加环境保护部（国家核安全局）组织的核与辐射安全监管中级或者高级培训并通过考核。"},{"i":12,"n":"第十二条","txt":"申请领取省级《辐射安全监督员证》的人员，应当具备下列条件之一： （一）取得注册核安全工程师执业资格； （二）参加环境保护部（国家核安全局）组织的省级辐射安全监管初级或者高级培训并通过考核； 申请领取省级以下《辐射安全监督员证》的培训要求，由省级环境保护主管部门规定。"},{"i":13,"n":"第十三条","txt":"核与辐射安全监督检查人员证件每半年核发一次。 申请领取核与辐射安全监督检查人员证件的，应当由申领人员所在单位于每年的3月31日或者9月30日之前向发证部门提出书面申请；发证部门收到申请后进行审查，认为符合本办法规定的发证条件的，核发核与辐射安全监督检查人员证件。 省级环境保护主管部门核发省级以下《辐射安全监督员证》的情况，应当在核发后一个月内报环境保护部（国家核安全局）备案。"},{"i":14,"n":"第十四条","txt":"核与辐射安全监督检查人员证件应当载明人员姓名、证件编号、所属单位、使用区域、有效期、发证日期和发证部门等信息，并加盖发证部门的公章或者证件专用章。 禁止伪造、变造核与辐射安全监督检查人员证件。"},{"i":15,"n":"第十五条","txt":"核与辐射安全监督检查人员证件持有人（以下简称“持证人”）应当按照证件载明的职责和区域范围从事核与辐射安全监督检查工作。"},{"i":16,"n":"第十六条","txt":"持证人应当妥善保管核与辐射安全监督检查人员证件，不得涂改、损毁或者转借他人。"},{"i":17,"n":"第十七条","txt":"核与辐射安全监督检查人员证件有效期为五年。临时核与辐射安全监督检查人员证件有效期为一年。 到期未换发的核与辐射安全监督检查人员证件，自行失效。"},{"i":18,"n":"第十八条","txt":"核与辐射安全监督检查人员证件在有效期内发生遗失、污损或者残缺的，由持证人所在单位向发证部门申请补发新证。发证部门应当及时补发。"},{"i":19,"n":"第十九条","txt":"持证人有下列情形之一的，可以由所在单位申请换发核与辐射安全监督检查人员证件： （一）证件有效期届满的； （二）持证人所在单位名称发生变化的； （三）持证人从事核与辐射安全监督检查工作的区域范围发生变更的； （四）其他应当换发核与辐射安全监督检查人员证件的情形。 因证件有效期届满申请换发核与辐射安全监督检查人员证件的持证人，应当按照发证部门的要求参加在岗培训。 申请换发核与辐射安全监督检查人员证件的程序适用本办法第十三条的规定。 换发核与辐射安全监督检查人员证件的，持证人应当将原证件交回所在单位。"},{"i":20,"n":"第二十条","txt":"持证人有下列情形之一的，持证人所在单位应当向发证部门申请注销核与辐射安全监督检查人员证件： （一）持证人退休的； （二）持证人调离核与辐射安全监督检查工作岗位的； （三）其他不适宜继续从事核与辐射安全监督检查工作的情形。"},{"i":21,"n":"第二十一条","txt":"持证人有下列行为之一的，由持证人所在单位给予批评教育，责令限期改正，并暂扣其核与辐射安全监督检查人员证件： （一）涂改、转借核与辐射安全监督检查人员证件的； （二）使用核与辐射安全监督检查人员证件从事与公务无关的活动的； （三）其他违反核与辐射安全监督检查人员证件管理相关规定的行为。 对暂扣核与辐射安全监督检查人员证件的人员，发证部门应当对其重新进行资格培训。证件暂扣期间，不得从事核与辐射安全监督检查工作。 所在单位暂扣核与辐射安全监督检查人员证件的情况应当及时报发证部门备案。"},{"i":22,"n":"第二十二条","txt":"持证人有下列行为之一的，由发证部门收回核与辐射安全监督检查人员证件： （一）受到刑事处罚、行政拘留或者记大过以上行政处分的； （二）以欺诈、舞弊、贿赂等不正当手段获取核与辐射安全监督检查人员证件的； （三）其他严重违反相关法律法规的行为。"},{"i":23,"n":"第二十三条","txt":"持证人所在单位有下列行为之一的，由发证部门给予通报批评，责令限期改正： （一）安排未取得核与辐射安全监督检查人员证件的人员从事核与辐射安全监督检查工作的； （二）对持证人和核与辐射安全监督检查人员证件管理不善导致严重后果的； （三） 其他违反核与辐射安全监督检查人员证件管理相关规定的行为。"},{"i":24,"n":"第二十四条","txt":"发证部门工作人员违反本办法的规定，滥用职权、徇私舞弊、玩忽职守，擅自发放或者越权发放核与辐射安全监督检查人员证件的，依法给予处分。"},{"i":25,"n":"第二十五条","txt":"本办法由环境保护部（国家核安全局）负责解释。"},{"i":26,"n":"第二十六条","txt":"本办法自2014年3月1日起施行。"}],"hedonglichangyanjiuduiheranliaoxunhuansheshianquande8e14":[{"i":1,"n":"第一条","txt":"为规范民用核动力厂、研究堆、核燃料循环设施等核设施安全许可活动，根据《中华人民共和国核安全法》《中华人民共和国行政许可法》《中华人民共和国民用核设施安全监督管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"在中华人民共和国领域及管辖的其他海域内，民用核动力厂、研究堆、核燃料循环设施（以下统称核设施）的选址、建造、运行、退役等安全许可事项的许可程序，适用本规定。 核设施转让、变更营运单位和迁移等活动的审查批准，适用本规定。"},{"i":3,"n":"第三条","txt":"核动力厂、研究堆、核燃料循环设施，是指： （一）核电厂、核热电厂、核供汽供热厂等核动力厂及装置； （二）核动力厂以外的研究堆、实验堆、临界装置等其他反应堆（以下统称研究堆），根据潜在危害由大到小可划分为Ⅰ类、Ⅱ类、Ⅲ类研究堆； （三）核燃料生产、加工、贮存和后处理设施等核燃料循环设施。 核设施配套建设的放射性废物处理、贮存设施的安全许可，应当在主体核设施的安全许可中一并办理许可手续。"},{"i":4,"n":"第四条","txt":"核设施营运单位申请核设施安全许可，以及办理核设施安全许可的变更、延续，应当依照本规定，报国家核安全局审查批准。"},{"i":5,"n":"第五条","txt":"核设施营运单位，应当具备保障核设施安全运行的能力，并符合下列条件： （一）有满足核安全要求的组织管理体系和质量保证、安全管理、岗位责任等制度； （二）有规定数量、合格的专业技术人员和管理人员； （三）具备与核设施安全相适应的安全评价、资源配置和财务能力； （四）具备必要的核安全技术支撑和持续改进能力； （五）具备应急响应能力和核损害赔偿财务保障能力； （六）法律、行政法规规定的其他条件。"},{"i":6,"n":"第六条","txt":"核设施营运单位应当按照有关核设施场址选择的要求完成核设施场址的安全评估论证，并在满足核安全技术评价要求的前提下，向国家核安全局提交核设施场址选择审查申请书和核设施选址安全分析报告，经审查符合核安全要求后，取得核设施场址选择审查意见书。"},{"i":7,"n":"第七条","txt":"核设施建造前，核设施营运单位应当向国家核安全局提出建造申请，并提交下列材料： （一）核设施建造申请书； （二）初步安全分析报告； （三）环境影响评价文件； （四）质量保证文件； （五）法律、行政法规规定的其他材料。 核设施营运单位取得核设施建造许可证后，方可开始与核设施安全有关的重要构筑物的建造（安装）或者基础混凝土的浇筑，并按照核设施建造许可证规定的范围和条件从事相关的建造活动。 核设施营运单位在提交核设施建造申请书时，本条第一款规定的初步安全分析报告中关于调试大纲的内容不具备提交条件的，可以在征得国家核安全局同意后，由核设施营运单位根据核设施建造进展情况，按照国家核安全局的要求补充提交。 核设施建造许可证的有效期不得超过十年。"},{"i":8,"n":"第八条","txt":"有下列情形之一的，核设施营运单位可以一并向国家核安全局提交核设施场址选择审查申请书和核设施建造申请书。国家核安全局在核发核设施建造许可证的同时出具核设施场址选择审查意见书： （一）新选场址拟建核设施为Ⅲ类研究堆的； （二）在现有场址新建研究堆，若新建研究堆对场址的安全要求不高于该场址已有核设施，且该场址已经过安全技术评价并得到国家核安全局的批准的； （三）在现有核燃料生产基地内建设核燃料循环前端设施（铀纯化转化、铀浓缩和元件制造设施）的； （四）由工厂制造或者总装、并在工厂内完成首次装料和调试的浮动式或者移动式核动力装置，其场址已经过安全评价并得到国家核安全局的批准的。"},{"i":9,"n":"第九条","txt":"核设施首次装投料前，核设施营运单位应当向国家核安全局提出运行申请，并提交下列材料： （一）核设施运行申请书； （二）最终安全分析报告； （三）质量保证文件； （四）应急预案； （五）法律、行政法规规定的其他材料。 核设施营运单位取得核设施运行许可证后，方可装投料，并应当按照核设施运行许可证规定的范围和条件进行装投料，以及装投料后的调试和运行等活动。"},{"i":10,"n":"第十条","txt":"核设施营运单位在提交核设施运行申请书时，本规定第九条规定的最终安全分析报告中下列章节或者内容不具备提交条件的，可以在征得国家核安全局同意后，由核设施营运单位根据核设施建造调试进展情况，按照国家核安全局的要求向国家核安全局补充提交： （一）维修大纲（不适用Ⅲ类研究堆及核燃料循环设施）； （二）在役检查大纲（不适用Ⅲ类研究堆及核燃料循环设施）； （三）装换料大纲（不适用Ⅲ类研究堆及核燃料循环设施）； （四）役前检查结果报告（不适用Ⅲ类研究堆及核燃料循环设施）； （五）实验和应用大纲（不适用研究堆之外的核设施）； （六）核设施装投料前调试报告。"},{"i":11,"n":"第十一条","txt":"核设施营运单位取得核设施运行许可证后，应当按照许可证规定的范围和条件运行核设施。 核设施营运单位应当按照批准的调试大纲所确定的顺序、方法等要求完成调试试验项目。核设施营运单位应当在调试大纲确定的所有调试试验项目完成后两个月内，向国家核安全局提交调试报告。 国家核安全局对核设施首次装投料以及装投料后的重要调试活动，可以设置控制点，并在运行许可文件中载明。"},{"i":12,"n":"第十二条","txt":"核设施运行许可证的有效期为设计寿期。 运行许可证有效期内，核设施营运单位应当按照要求对核设施进行定期安全评价，评价周期根据核设施具体情况和核安全法规和标准的变化情况确定，一般为十年。评价结果应当提交国家核安全局审查。"},{"i":13,"n":"第十三条","txt":"用于科学研究的核燃料循环设施，根据设施潜在风险和复杂程度，核设施营运单位可以向国家核安全局申请合并办理核设施安全许可事项。"},{"i":14,"n":"第十四条","txt":"拟转让核设施的，核设施拟受让单位应当符合本规定第五条规定的条件，并重新申请核设施安全许可。 前款规定的核设施安全许可申请,由持有核设施安全许可证的核设施营运单位和核设施拟受让单位共同向国家核安全局提出申请，并提交以下材料： （一）转让核设施的申请书； （二）核设施拟受让单位质量保证文件； （三）核设施拟受让单位应急预案； （四）其他需要申明的事项。 拟变更核设施营运单位的，依照本条第一款、第二款的规定执行。"},{"i":15,"n":"第十五条","txt":"国家核安全局审查认可转让核设施或者变更核设施营运单位的，向核设施的受让单位或者变更后的核设施营运单位重新颁发核设施安全许可证,并同时注销原核设施安全许可证。 核设施的受让单位或者变更后的核设施营运单位，应当继承原核设施营运单位在核设施安全管理方面的全部义务，并遵守原核设施营运单位在申请原核设施安全许可证时所作的全部承诺，但经核设施的受让单位和变更后的核设施营运单位申请并得到国家核安全局审查认可免除的义务和承诺除外。"},{"i":16,"n":"第十六条","txt":"迁移核设施的，核设施营运单位应当向国家核安全局提出申请，并提交下列材料： （一）核设施迁移申请书； （二）新场址的选址安全分析报告； （三）新场址的环境影响报告书； （四）新场址的应急预案； （五）核设施迁移活动的质量保证文件； （六）核设施安全分析报告相关内容的修订文件； （七）法律、行政法规规定的其他材料。 迁移核设施的申请取得国家核安全局批准后，核设施营运单位方可开始进行核设施迁移活动。 核设施迁移过程中存在核设施转让或者变更核设施营运单位情形的，适用本规定第十四条、第十五条的有关规定。"},{"i":17,"n":"第十七条","txt":"核设施终止运行后，核设施营运单位应当制定停闭期间的安全管理措施，采取安全的方式进行停闭管理，保证停闭期间的安全，确保退役所需的基本功能、技术人员和文件，并接受国家核安全局的监督检查。"},{"i":18,"n":"第十八条","txt":"核设施退役前，核设施营运单位应当向国家核安全局提出退役申请，并提交下列材料： （一）核设施退役申请书； （二）退役安全分析报告； （三）环境影响评价文件； （四）质量保证文件； （五）法律、行政法规规定的其他材料。 国家核安全局向核设施营运单位颁发退役批准书。核设施营运单位应当按照退役批准书的内容开展退役活动。"},{"i":19,"n":"第十九条","txt":"国家核安全局按照规定对核设施安全许可申请材料进行形式审查，申请材料不齐全或者不符合法定形式的，在五个工作日内一次告知申请单位需要补正的全部内容。对于申请材料齐全、符合法定形式，或者申请单位按照要求提交全部补正申请材料的，应当受理核设施安全许可申请。 国家核安全局受理或者不予受理核设施安全许可申请，应当出具书面凭证；需要对核设施安全许可申请组织技术审查的，应当一并告知申请单位技术审查的流程、计划节点和预计的技术审查时间。"},{"i":20,"n":"第二十条","txt":"核设施营运单位对核设施安全许可申请材料的真实性、准确性负责。核设施安全许可申请材料的格式和编写内容及形式，应当符合如下规定： （一）格式和内容满足国家核安全局相应的要求； （二）应当具有总目录；对篇幅较长的，应当有分卷目录； （三）所有文字、图纸和图表应当清晰，不使用放大设备能直接阅读； （四）对所使用的图例、符号应当给予说明； （五）涉及国家秘密、商业秘密和个人信息的内容应当予以注明。"},{"i":21,"n":"第二十一条","txt":"国家核安全局依照法定条件和程序，对核设施安全许可申请组织安全技术审查。 技术审查内容包括申请材料与法规标准的符合情况、分析计算结果复核、试验结果审核等。 技术审查流程包括文件审查、校核计算、试验验证、技术交流和专家咨询等。 国家核安全局根据核设施的种类和复杂程度，对技术审查时间作出适当的安排。核设施营运单位应当按照国家核安全局的要求答复国家核安全局在技术审查中提出的问题，必要时补充相关文件资料予以说明。 技术审查时间不计入作出核设施安全许可的期限。"},{"i":22,"n":"第二十二条","txt":"国家核安全局组织安全技术审查时，应当委托与许可申请单位没有利益关系的技术支持单位进行审评。受委托的技术支持单位应当对其技术评价结论的真实性、准确性负责。 国家核安全局在进行核设施重大安全问题技术决策时，应当咨询核安全专家委员会的意见。"},{"i":23,"n":"第二十三条","txt":"国家核安全局对满足核安全要求的核设施安全许可申请，在技术审查完成之日起二十个工作日内，依法作出准予许可的决定，予以公告；对不满足核安全要求的，应当书面通知申请单位并说明理由。 国家核安全局审批核设施建造、运行许可申请以及核设施转让或者变更核设施营运单位申请时，应当向国务院有关部门和核设施所在地省、自治区、直辖市人民政府征询意见。 国家核安全局审批核设施迁移申请时，应当向国务院有关部门以及核设施迁出地、迁入地的省、自治区、直辖市人民政府征询意见。"},{"i":24,"n":"第二十四条","txt":"核设施安全许可证件应当载明下列内容： （一）核设施安全许可的单位名称、注册地址和法定代表人； （二）核设施的名称和所在地址； （三）准予从事的核设施安全许可活动范围和条件； （四）有效期限； （五）发证机关、发证日期和证书编号。"},{"i":25,"n":"第二十五条","txt":"在核设施运行许可证的有效期内，国家核安全局可以根据法律、行政法规和新的核安全标准的要求，对许可证规定的事项作出合理调整。"},{"i":26,"n":"第二十六条","txt":"国家核安全局依法公开核设施安全许可文件。涉及国家秘密、商业秘密和个人信息的，按照国家有关规定执行。"},{"i":27,"n":"第二十七条","txt":"核设施营运单位变更单位名称、注册地址和法定代表人的，应当自变更之日起二十个工作日内，向国家核安全局办理许可证变更手续。"},{"i":28,"n":"第二十八条","txt":"核设施建造许可证有效期届满，尚未建造完成的，核设施营运单位应当在核设施建造许可证有效期届满三十日前向国家核安全局办理延期手续，经国家核安全局审查批准后方可继续建造活动。有下列情形之一且经评估不存在安全风险的，无需办理延期审批手续，核设施营运单位应当将安全风险评估报告提交国家核安全局备案： （一）国家政策或者行为导致核设施延期建造； （二）用于科学研究的核设施； （三）用于工程示范的核设施； （四）用于乏燃料后处理的核设施。"},{"i":29,"n":"第二十九条","txt":"核设施营运单位调整下列事项的，应当报国家核安全局批准： （一）作为颁发运行许可证依据的重要构筑物、系统和设备； （二）运行限值和条件； （三）国家核安全局批准的与核安全有关的程序和其他文件。"},{"i":30,"n":"第三十条","txt":"对在运行许可证有效期内长期不启动运行的核设施，需要改变原有运行限值和条件或者其他安全管理措施的，核设施营运单位应当制定长期停堆（运）计划和相应的管理措施，并依据本规定第二十九条的有关规定，报国家核安全局批准。 实施长期停堆（运）管理的核设施如需恢复正常运行的，应当依据本规定第二十九条的有关规定，报国家核安全局批准。"},{"i":31,"n":"第三十一条","txt":"核设施运行许可证有效期届满需要继续运行的，核设施营运单位应当对核设施是否符合核安全标准进行论证、验证。满足核安全标准要求的，应当于许可证有效期届满前五年，向国家核安全局提出运行许可证有效期延续申请，并提交下列材料： （一）核设施运行许可证有效期延续申请书； （二）核设施运行许可证有效期延续的安全论证、验证报告，以及老化管理大纲、修订的环境影响评价文件、核安全相关的工程改进措施和计划等与核设施安全论证、验证相关的材料； （三）增补或者修改的最终安全分析报告； （四）法律、行政法规规定的其他材料。 核设施运行许可证有效期届满，运行许可证有效期延续申请经国家核安全局审查批准后，核设施方可继续运行。未获得国家核安全局批准的，核设施不得继续运行。"},{"i":32,"n":"第三十二条","txt":"核设施运行许可证有效期延续的期限按照核设施的实际状态和安全评估情况确定，但每次不超过二十年。"},{"i":33,"n":"第三十三条","txt":"本规定有关的术语定义为： 研究堆：核动力厂以外的研究堆、实验堆、临界装置以及由外源驱动带功率运行的次临界系统等核设施或装置的统称，包括反应堆堆芯、辐照孔道、考验回路等实验装置，以及为支持其运行、保证安全和辐射防护的目的所设置的所有系统和构筑物，还包括燃料贮存、放射性废物贮存、放射性热室、实物保护系统等反应堆场址内与反应堆或实验装置有关的一切其它设施。 Ⅰ类研究堆：功率、剩余反应性和裂变产物总量都较高的研究堆，热功率范围10MW～300MW。这类研究堆一般在强迫循环下运行，通常必须设置高度可靠的停堆系统，需要设置应急冷却系统以保证堆芯余热的有效排出；对反应堆厂房或者其他包容结构需要有特殊的密封要求。 Ⅱ类研究堆：功率、剩余反应性和裂变产物总量属于中等的研究堆，热功率范围500kW～10MW。这类研究堆可采用自然对流冷却方式或强迫循环冷却方式排出热量；反应堆需要设置可靠的停堆系统，停堆后必"},{"i":34,"n":"第三十四条","txt":"本规定自2019年10月1日起施行。1993年12月31日国家核安全局发布的《核电厂安全许可证件的申请和颁发》、2006年1月28日国家核安全局发布的《研究堆安全许可证件的申请和颁发规定》同时废止。"}],"hedonglichangguanlitixianquanguiding":[{"i":1,"n":"第一条","txt":"为了推进核安全治理体系和治理能力现代化，强化核动力厂安全责任，保护公众和从业人员的安全与健康，保护生态环境，根据《中华人民共和国核安全法》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于中华人民共和国领域及管辖的其他海域内的核动力厂管理体系的建立和实施，其他民用核设施可以参照本规定执行。 本规定所称核动力厂管理体系，是指为确保核动力厂安全而建立的组织机构、管理制度、资源和工作过程等。"},{"i":3,"n":"第三条","txt":"核动力厂营运单位应当按照国家有关法律法规和本规定要求,建立和有效实施核动力厂管理体系，通过对所有安全相关工作过程（以下简称工作过程）、影响核安全和生态环境保护的要素进行有效管理，实现核安全和生态环境保护等目标。 对核动力厂控股的企业集团（以下简称企业集团）应当在其职责范围内采取有效措施满足本规定的适用要求。 为核动力厂营运单位提供设备、工程和服务等的单位（以下简称相关单位）应当采取有效措施满足本规定的适用要求。"},{"i":4,"n":"第四条","txt":"国务院核安全监督管理部门应当加强对核动力厂管理体系建立和实施情况的监督检查。"},{"i":5,"n":"第五条","txt":"鼓励任何单位和个人对核动力厂的安全隐患、违规操作、弄虚作假及其他影响安全的违法行为，向国务院核安全监督管理部门举报。 国务院核安全监督管理部门应当及时处理举报并对举报人的信息予以保密。对实名举报的，应当反馈处理结果等情况；查证属实的，可以对举报人给予奖励。 严禁举报人所在单位对举报人进行任何形式的压制和打击报复。"},{"i":6,"n":"第六条","txt":"核动力厂营运单位对核动力厂的核安全负全面责任，应当坚持安全第一、预防为主、责任明确、严格管理、纵深防御、全面保障的原则，在核动力厂建立并保持对放射性危害的有效防御，保障核安全，预防和应对核事故，安全利用核能，保护从业人员、公众和环境免受不当危害。 核动力厂营运单位应当承担以下核安全责任： （一）遵守国家有关法律法规要求，建立健全安全责任制，组织制定相关管理大纲、规章制度和程序，确保安全相关工作的有效实施； （二）确保核动力厂选址、设计、建造、运行和退役等满足核安全法律法规、标准、许可文件的规定和其他安全监管要求； （三）加强从业人员辐射防护和职业照射监控，确保从业人员具备管理控制核与辐射风险的相关知识和能力； （四）确保对核动力厂内所有放射性物质实施严格有效的管理控制，持续开展放射性流出物监测和场址周边辐射环境监测； （五）确保为核动力厂选址、设计、建造、运行和退役等全寿期安全提供资源"},{"i":7,"n":"第七条","txt":"企业集团应当加强核动力厂营运单位人员配置、核安全管理和财务保障，建立和实施有效的监督和考核制度。"},{"i":8,"n":"第八条","txt":"核动力厂营运单位可以通过合同约定的方式将核动力厂管理体系的具体工作委托给相关单位承担；委托行为不转移核动力厂营运单位承担的核安全全面责任。 核动力厂营运单位应当严格审查相关单位的资质或者能力，通过合同明确双方的权利、义务和责任，并对相关单位的活动进行有效管理，确保其满足本规定的要求。"},{"i":9,"n":"第九条","txt":"核动力厂营运单位主要负责人应当在以下方面作出承诺： （一）制定核安全和生态环境保护等方面的政策、目标和规划，建立清晰、协调、高效的安全决策机制和重大事项的安全审议机制； （二）明确不同层级从业人员的安全责任、权利和义务，为履行安全责任、实现安全目标提供必要的资源保障和程序方法等支持，建立科学合理的绩效评价和奖惩制度； （三）持续监督、评价核动力厂安全状况和管理体系运行情况，定期开展管理部门审查，促进全员参与安全管理，持续提升安全业绩，培育核安全文化； （四）与国务院核安全监督管理部门建立沟通机制，执行核安全相关法律法规规定的报告制度，报告核动力厂管理体系运行情况。"},{"i":10,"n":"第十条","txt":"核动力厂营运单位在安全生产、质量保证、职业健康等方面的政策、目标和规划应当与核安全和生态环境保护政策、目标和规划协调一致。核动力厂营运单位应当制定和有效实施核安全和生态环境保护政策、目标和规划的行动计划，并定期开展适宜性和符合性审查，及时纠正偏差。"},{"i":11,"n":"第十一条","txt":"核动力厂营运单位主要负责人应当履行下列职责： （一）指挥和调度管理体系的重大事项； （二）保证安全决策机制和安全审议机制有效运作； （三）协调解决工作过程之间的重大争议和冲突。"},{"i":12,"n":"第十二条","txt":"核动力厂营运单位负责安全综合管理的部门，应当具有足够的资源、职权和组织独立性，并履行下列职责： （一）管理、协调、监督、评价管理体系相关工作； （二）制止并纠正违章指挥、强令冒险作业、违规操作等行为； （三）发现重大安全隐患时，提出安全管理建议； （四）对安全相关重大不符合项、事件和事故的处理情况进行跟踪评价； （五）组织制定和实施管理体系评价计划，督促落实相关整改措施。"},{"i":13,"n":"第十三条","txt":"核动力厂营运单位应当确定管理体系各工作过程的责任部门，责任部门履行下列职责： （一）制定和实施所负责工作过程的管理大纲、规章制度和程序； （二）对所负责的工作过程进行有效的管理控制； （三）及时发现和纠正对安全不利的行为或者状态，实施经验反馈； （四）向本单位安全综合管理部门报告安全状况和趋势，落实整改措施。"},{"i":14,"n":"第十四条","txt":"核动力厂营运单位安全委员会等安全审议机构应当对重要安全事项进行审议，跟踪审议决议的落实情况，必要时开展风险分析和独立审查。 在核安全和生态环境保护等方面承担重要职责的本单位相关部门负责人、相关单位代表以及相关领域专家应当参加安全审议。 本条第一款规定的重要安全事项包括下列内容： （一）安全许可申请文件以及重要许可事项的调整； （二）核安全和生态环境保护等方面的绩效评价方法及改进措施； （三）安全相关组织机构、职责分工和资源配置等方面的重大调整； （四）可能影响安全的工作进度、资金等方面的管理制度和计划的重大调整； （五）本单位内部和对相关单位的绩效评价方法及其重大调整； （六）供应链管理相关重要事项和重要相关单位的变更； （七）重大不符合项、重大事件和事故的调查结果及整改措施； （八）核安全文化评估结果及改进措施； （九）其他重要安全事项。"},{"i":15,"n":"第十五条","txt":"核动力厂营运单位应当整合、实施、评价和持续改进管理体系，满足以下要求： （一）综合考虑安全生产、质量保证、生态环境、安全保卫、职业健康，以及组织、人员、社会、进度、经费等要素及其相互影响； （二）合理设置组织机构，确定承担决策、管理、执行和评价工作的部门职责、权限、接口关系和联络渠道等，有效管理内外部接口； （三）按照管理体系的要求开展各项工作，及时发现和处理管理体系存在的问题，形成并保存相应证据； （四）持续监测安全相关要素和工作过程的变化，识别和分析其对安全的影响和潜在风险，及时对管理体系作出适当调整。"},{"i":16,"n":"第十六条","txt":"核动力厂营运单位应当对管理体系文件的策划、编制、审批、发布、分发、修改和使用等提出明确要求，确保其协调自洽、易于理解和便于实施，并有效传达至相关单位。 管理体系文件应当包括下列内容： （一）管理体系总论，对管理体系进行综合描述与说明； （二）工作过程的管理大纲和规章制度； （三）对工作过程进行策划、实施和评价改进的流程、方法与要求。 核动力厂营运单位应当根据核安全和生态环境保护等管理需要，定期审查管理体系文件，及时进行评估和修订。 核动力厂营运单位管理体系文件应当报国务院核安全监督管理部门备案。"},{"i":17,"n":"第十七条","txt":"核动力厂营运单位应当依据分类分级管理原则，综合考虑下列因素，确定核动力厂管理体系的各项要求： （一）工作过程的安全重要性、复杂性和标准化程度； （二）相关单位的安全重要性、经验、业绩和人员能力水平； （三）工作过程实施不当可能造成的安全风险、后果和危害程度； （四）核动力厂后续阶段检查维修的可行性; （五）其他应当考虑的安全相关因素。"},{"i":18,"n":"第十八条","txt":"核动力厂营运单位可以对管理体系的下列事项明确分级要求： （一）管理大纲、规章制度和程序的适用范围、详细程度和审批权限； （二）人员培训、资格考核、岗位授权的范围和要求； （三）采购文件的类型、详细程度和可追溯性要求； （四）对工作过程的管理控制、验证措施和要求； （五）需要形成和保存的记录及其保存期限。"},{"i":19,"n":"第十九条","txt":"核动力厂营运单位应当对其安全相关能力和资源进行有效管理，在核动力厂选址、设计、建造、运行和退役全寿期以及应急响应期间具备下列能力： （一）安全领导和安全管理能力； （二）培育和建设核安全文化的能力； （三）工作过程的质量保证能力； （四）有规定数量的、合格的专业技术人员； （五）安全评价、资源配置和财务能力； （六）安全相关的技术支撑体系和持续改进能力； （七）事故应急响应能力和损害赔偿能力。"},{"i":20,"n":"第二十条","txt":"核动力厂营运单位应当采取下列措施，对从业人员进行有效管理，确保其安全有效开展工作： （一）制定适当的用工政策、激励晋升机制、人员配备和培训计划，确保安全相关岗位从业人员的数量、能力等持续满足需要； （二）制定和实施培训大纲，采用系统化培训方法开展安全相关知识技能和管理体系的培训，保证从业人员充分参与培训管理； （三）按照国家有关法律法规的要求，结合岗位的安全重要性，明确资格考核和岗位授权等要求并有效实施。"},{"i":21,"n":"第二十一条","txt":"核动力厂营运单位应当对财务资源进行有效管理，确定核动力厂全寿期财务资源需求，为有效维护核动力厂管理体系提供资金保障。"},{"i":22,"n":"第二十二条","txt":"核动力厂营运单位应当确定安全相关工作场所、软硬件设施、支持保障服务等基础设施和工作条件，并采取下列措施进行有效管理： （一）提供适宜的工作环境、培训设施、防护装置和物品，定期开展职业健康检查，合理设置工作时间和劳动强度，保障从业人员健康和安全； （二）明确场地管理和清洁要求，防止安全相关工作场所、设施设备、人员受到不必要的污染或者损伤； （三）持续监测核动力厂周边环境，有效防范自然或者人为因素对基础设施和核动力厂安全造成的不利影响。"},{"i":23,"n":"第二十三条","txt":"核动力厂营运单位应当采取下列措施，有效管理安全相关知识和信息，为工作实施、经验反馈和知识传承提供支持： （一）开展知识管理，系统收集、处理、维护和使用安全相关知识和信息，满足岗位及其人员的更迭需要，防止重要知识、信息和经验遗失； （二）开展信息化建设，利用先进信息技术为知识和信息管理提供安全可靠的平台和工具，采取有效措施保证网络和信息安全； （三）对用于核动力厂设计、安全分析计算和数据管理的安全重要计算机软件进行验证和确认，对安全重要控制系统软件及其数据进行验证和定期检查，对安全重要软件及其数据进行异地异质备份。"},{"i":24,"n":"第二十四条","txt":"核动力厂营运单位应当采取下列措施，有效管理安全重要物项和其他对核安全有潜在影响的物项： （一）对安全重要物项进行标识并建立台账，提供适宜的贮存条件、防护措施、运输和装卸设备，防止其错用、损坏、老化、变质、性能下降或者丢失； （二）对核动力厂系统、部件和构筑物制定定期试验、在役检查、维修等规程并严格执行，确保其可用性和可靠性； （三）根据安全重要性、使用情况、保质期、交货期、供应链不确定性等因素，适当确定核动力厂备品备件的库存清单和数量并确保其持续满足使用要求； （四）定期或者在使用前标定或者校准检查、测量、试验设备和装置，确保其具有合适的量程、灵敏度、准确度和精密度； （五）确定放射性物质、危险化学品和特种设备等有害或者高风险物质资产清单，对其进行有效管理和定期检查，确保其安全贮存、装卸、运输或者使用。"},{"i":25,"n":"第二十五条","txt":"核动力厂营运单位应当采取下列措施，对技术更新和物项替代进行有效管理，防范核动力厂长期运行中因物项老化或者技术过时引起的安全风险： （一）对已淘汰或者无后续供应物项制定和实施适当的管理策略，评价替换物项，确保其满足安全功能要求； （二）使用经验证的新技术、新物项取代老旧技术和物项，通过技术改进不断提升安全水平。"},{"i":26,"n":"第二十六条","txt":"核动力厂营运单位应当确定实现安全目标、满足安全要求、交付合格物项或者服务所需要的工作过程，明确工作过程的控制要求，确保工作过程之间的一致性和连续性。 工作过程的控制要求包括下列事项： （一）在核安全和生态环境保护等方面的适用要求； （二）存在的危害和风险以及必要时的预防和缓解措施； （三）工作过程管理、实施和评价验证的责任与接口关系； （四）工作过程的输入输出、接口及其相互影响和作用； （五）具体工作内容、流程、控制验证方法和要求； （六）需要编制、收集和保存的文件和记录要求。"},{"i":27,"n":"第二十七条","txt":"核动力厂营运单位应当根据安全重要性、功能属性和应用范围等因素，对工作过程进行分类管理。 核动力厂营运单位应当对工作过程进行策划、实施、评价和持续改进，识别和提供所需要的资源，确定影响工作过程实施的条件和要求，明确验收准则。 工作过程应当由合格的人员依据相关管理体系文件，使用合格的材料和设备，在适宜的环境条件下实施。特殊工艺过程应当在首次使用前进行验证。"},{"i":28,"n":"第二十八条","txt":"核动力厂营运单位应当采取下列措施对供应链进行有效管理： （一）采购文件应当充分体现物项或者服务需求，以及物项或者服务在核安全和生态环境保护等方面的要求； （二）对相关单位进行评价，建立、维护和持续优化合格供应商清单，识别和应对供应链潜在风险，保障供应链安全、可靠、稳定； （三）对相关单位工作进行验证，监控相关单位的外包行为，对相关单位提交的物项或者服务进行验收，对安全相关商品级物项进行关键性能验证； （四）对民用核安全设备设计、制造、安装和无损检验单位及其相关活动进行有效管理； （五）对采用工程总承包模式的核动力厂工程建设项目，要求工程总承包单位建立和有效实施满足本规定要求的工程建设项目的管理制度，并对管理制度的执行情况进行监督检查。"},{"i":29,"n":"第二十九条","txt":"核动力厂营运单位应当按照工作过程的内在逻辑和档案分类要求，有效管理安全相关记录和文档资料，确保档案完整、有效、系统、规范。对记录和文档的编码、收集、归档、索引、修改、复制、转录、借阅、储存和销毁等进行严格控制，保证记录和文档资料安全、完整、持续可读并能追溯涉及的物项或者活动。"},{"i":30,"n":"第三十条","txt":"核动力厂营运单位应当将核安全文化融入生产、经营、科研和管理等各环节，在制定目标政策、设置机构、分配资源、制定计划、安排进度和控制成本时，始终坚持安全第一的原则，科学规范地开展各项工作。 核动力厂营运单位的决策机构和管理部门应当通过承诺、决策和行为示范等，不断强化法治意识、责任意识、风险意识和诚信意识，持续培育和建设核安全文化。"},{"i":31,"n":"第三十一条","txt":"核动力厂营运单位应当组织开展核安全文化教育培训，制定安全重要岗位的行为准则，明确风险管理要求，及时识别、沟通和有效管控与工作及工作环境有关的风险；设置纵深防御体系，分析技术、人员和组织之间的相互作用和对安全的影响，利用实体屏障、组织管理和防止人为失误等措施，有效防范各类安全威胁。"},{"i":32,"n":"第三十二条","txt":"核动力厂营运单位应当建立核安全经验反馈体系，鼓励从业人员报告安全隐患和管理体系缺陷，对所报告事项、建造和运行事件及经验、行业良好实践和科技进步等信息进行及时筛选、评价和反馈，持续改进和提升安全管理水平。"},{"i":33,"n":"第三十三条","txt":"核动力厂营运单位应当明确违规操作和弄虚作假防控要求与措施，发现相关行为的，及时依法依规处理；审查验证为核动力厂物项或者服务提供检测的机构资质、合格证明文件或者记录等，保证其真实、完整、可追溯。"},{"i":34,"n":"第三十四条","txt":"核动力厂营运单位应当制定与政府相关部门、所有者、投资方、用户、从业人员、供应方、公众、社团组织、国际机构等相关方的沟通策略、计划和要求，妥善处理危机与冲突；依法开展信息公开和公众参与，就涉及公众利益的重大事项征求相关方意见，保障相关方的知情权、参与权和监督权。"},{"i":35,"n":"第三十五条","txt":"核动力厂营运单位应当定期组织开展核安全文化评估，评价本单位的核安全文化状态，促进核安全文化持续改进。"},{"i":36,"n":"第三十六条","txt":"核动力厂营运单位应当开展管理体系日常监督检查，通过巡查、活动观察、会议、工作指导、意见征集等形式，检查管理体系各工作过程的执行情况和存在的问题，并及时整改。"},{"i":37,"n":"第三十七条","txt":"核动力厂营运单位应当持续监测核动力厂安全状态，定期分析评价安全性能指标的变化趋势，调查、分析异常和不良趋势的原因并加以改进。"},{"i":38,"n":"第三十八条","txt":"核动力厂营运单位应当定期组织开展自我评估，并在国务院核安全监督管理部门例行核安全监督检查前对管理体系进行自查，对照监管要求和行业标杆查找问题，持续推动安全业绩提升和管理体系改进。"},{"i":39,"n":"第三十九条","txt":"核动力厂营运单位应当确定核动力厂全寿期不同阶段技术评价的项目、时机、范围、要求和预期结果，通过检查、试验、审查、应急演练、定期安全评价等方式，对安全重要物项和活动进行审查验证，合理可行地加以改进。"},{"i":40,"n":"第四十条","txt":"核动力厂营运单位应当定期组织开展管理体系内部监查，对重要的相关单位适时组织开展外部监查，必要时开展同行评估，系统评价管理体系各要素和工作过程的充分性、符合性和有效性，实施必要的管理改进。"},{"i":41,"n":"第四十一条","txt":"核动力厂营运单位应当定期开展管理部门审查，全面审议管理体系运行情况、安全业绩和核安全文化现状与问题、政策目标和规划实现情况、内外部环境的重大变化及其机遇和挑战等重大事项，确定管理体系的适宜性和有效性，对管理体系实施必要的调整和改进。"},{"i":42,"n":"第四十二条","txt":"核动力厂营运单位应当及时发现在核安全和生态环境保护等方面的不符合、事件或者事故，并按照相关要求进行报告、审查和处理。"},{"i":43,"n":"第四十三条","txt":"核动力厂营运单位应当及时纠正所有安全相关隐患、缺陷和问题，建立清单及信息库并对其进行动态管理；对重要不符合项、事件或者事故以及其他对安全有重要影响的缺陷，应当分析根本原因，制定和实施纠正措施，并建立跟踪系统，确保每项纠正措施得到落实。"},{"i":44,"n":"第四十四条","txt":"企业集团存在下列情形之一的，由国务院核安全监督管理部门责令限期整改，并对其主要负责人进行约谈，约谈结果应当向社会公开： （一）未为核动力厂营运单位人员配置、核安全管理和财务保障提供支持和便利的； （二）未建立合理有效的监督和考核制度，未督促干扰核动力厂营运单位依据本规定履行安全责任的。"},{"i":45,"n":"第四十五条","txt":"核动力厂营运单位存在下列情形之一的，由国务院核安全监督管理部门责令限期整改，并对其主要负责人进行约谈，约谈结果应当向社会公开： （一）未按照本规定要求对管理体系进行整合、实施、评价或者持续改进的； （二）未按照本规定要求制定或者实施核安全和生态环境保护等方面的政策、目标和规划的； （三）未按照本规定要求建立或者实施清晰、协调、高效的安全决策机制、重大事项的安全审议机制的； （四）未按照本规定要求为履行核安全责任提供足够的能力和资源保障的； （五）未按照本规定要求对供应链进行有效管理的； （六）未按照本规定要求组织开展核安全文化评估的； （七）其他在管理体系建立和实施中存在工作推进不力、问题突出的情形的。"},{"i":46,"n":"第四十六条","txt":"核动力厂营运单位和相关单位在管理体系的建立和实施过程中存在违法行为的，依据《中华人民共和国核安全法》等法律法规予以处罚。"},{"i":47,"n":"第四十七条","txt":"本规定中下列用语的含义： （一）核安全文化，是指各有关组织和个人以“安全第一”为根本方针，以维护公众健康和生态环境安全为最终目标，达成共识并付诸实践的价值观、行为准则和特性的总和。 （二）供应链，是指为核动力厂提供材料、零部件、设备、计算机软件、工程和服务等的供应网络，通常涉及核动力厂工程总承包单位、设计单位、制造单位、工程勘探和建设施工单位、技术服务单位、各级供应商和经销商等。"},{"i":48,"n":"第四十八条","txt":"本规定自2021年3月1日起施行。 附件：管理体系总论框架 附件 管理体系总论框架 核安全承诺（主要负责人签字） 一、前言 （一）目的与适用范围 （二）企业简介 （三）术语和定义 （四）编制依据 二、管理体系 （一）管理体系合规性说明 （二）管理体系总要求 （三）管理体系结构说明 （四）管理体系文件 （五）分类分级管理 三、管理职责 （一）安全责任 （二）安全领导和承诺 （三）政策、目标和规划 （四）组织机构和职责 （五）核安全文化 四、资源管理 （一）资源策划和提供 （二）人力资源管理 （三）财务资源管理 （四）基础设施和工作环境 （五）知识和信息管理 （六）物质资产管理 （七）技术更新和物项替代 五、过程实施 （一）过程实施的一般要求 （二）核心工作过程 （三）通用管理过程 （四）支持保障过程 六、评价改进 （一）日常监督 （二）安全状态监测 （三）自我评估 （四）独立评价 （五）"}],"hedonglichangyingyundanweiheanquanbaogaoguiding":[{"i":1,"n":"第一条","txt":"为了规范核动力厂营运单位核安全报告制度，根据《中华人民共和国核安全法》《中华人民共和国民用核设施安全监督管理条例》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"核动力厂营运单位对核安全负有全面责任,应当执行核安全报告制度，按照本规定的要求向国家核安全局或者核动力厂所在地区核与辐射安全监督站提交定期报告、重要活动报告、建造阶段事件报告、运行阶段事件报告和核事故应急报告。 核动力厂营运单位定期报告、重要活动报告、建造阶段事件报告、运行阶段事件报告和核事故应急报告的格式与具体要求，由国家核安全局另行规定。"},{"i":3,"n":"第三条","txt":"核动力厂营运单位定期报告包括建造阶段月度报告、运行阶段月度报告、安全性能指标季度报告、建造阶段年度报告、运行阶段年度报告和设备可靠性数据年度报告。"},{"i":4,"n":"第四条","txt":"核动力厂营运单位应当从取得建造许可证之日起，至取得运行许可证之日止，在每个月第十个工作日前，向核动力厂所在地区核与辐射安全监督站提交上个月建造情况的月度报告。 核动力厂建造多台核电机组的，可以将多台核电机组的建造情况综合成一份月度报告。"},{"i":5,"n":"第五条","txt":"核动力厂建造阶段月度报告包括下列内容： （一）上个月建造情况总结和下个月建造计划安排； （二）上个月发生的与建造有关的重要事件综述； （三）核电机组安全重要构筑物、系统和设备建造中存在的问题、纠正措施和经验反馈； （四）下个月计划开展的核安全有关重要活动； （五）其他应当报告的事项或者活动。"},{"i":6,"n":"第六条","txt":"核动力厂营运单位应当从取得运行许可证之日起，至取得退役批准书之日止，在每个月第十个工作日前，向核动力厂所在地区核与辐射安全监督站提交上个月运行情况的月度报告。 核动力厂运行多台核电机组的，可以将多台核电机组的运行情况综合成一份月度报告。"},{"i":7,"n":"第七条","txt":"核动力厂运行阶段月度报告包括下列内容： （一）核电机组运行数据； （二）核电机组月运行图； （三）核电机组安全重要设备状况； （四）重要修改活动； （五）核电机组安全屏障的完整性； （六）流出物排放情况； （七）固体放射性废物产生、处理、贮存和处置情况； （八）辐射防护情况； （九）运行事件与经验反馈； （十）下个月计划开展的核安全有关重要活动； （十一）其他应当报告的事项或者活动。"},{"i":8,"n":"第八条","txt":"核动力厂营运单位应当从取得运行许可证之日起，至取得退役批准书之日止，在每个季度的第一个月第十个工作日前，向国家核安全局提交前一季度的核动力厂安全性能指标季度报告。 核动力厂运行多台核电机组的，可以将多台核电机组的安全性能指标情况综合成一份季度报告。"},{"i":9,"n":"第九条","txt":"核动力厂安全性能指标季度报告的内容包括核动力厂安全性能指标相关的统计数据和各指标计算值。"},{"i":10,"n":"第十条","txt":"核动力厂营运单位应当在每年4月1日前，向国家核安全局提交前一年度建造或者运行情况的年度报告。 核动力厂建造或者运行多台核电机组的，可以将多台核电机组的建造或者运行情况和有关信息综合成一份年度报告。 4月1日是节假日的，核动力厂营运单位提交年度报告的届满之日顺延至节假日后第一个工作日。"},{"i":11,"n":"第十一条","txt":"核动力厂建造阶段年度报告包括下列内容： （一）核电机组安全重要构筑物、系统和设备建造情况总结和计划完成情况； （二）报告年份内发生的与核电机组安全重要构筑物、系统和设备建造有关的重要事件综述； （三）核电机组安全重要构筑物、系统和设备建造中存在的问题、纠正措施和经验反馈综述； （四）其他应当报告的问题和参考资料清单。"},{"i":12,"n":"第十二条","txt":"核动力厂运行阶段年度报告包括下列内容： （一）核电机组运行情况综述； （二）非计划降功率运行和停堆情况综述； （三）运行事件与经验反馈情况综述； （四）辐射防护情况综述; （五）应急准备情况综述； （六）已辐照核燃料元件的检验结果和核燃料元件的损坏情况； （七）人员培训情况； （八）其他应当报告的事项和活动综述。"},{"i":13,"n":"第十三条","txt":"核动力厂营运单位应当从取得运行许可证并完成首次换料大修之日的次日起，至取得退役批准书之日止，在每年6月1日前，向国家核安全局提交前一年度的核动力厂设备可靠性数据年度报告。 核动力厂运行多台核电机组的，可以将多台核电机组的设备可靠性数据情况综合成一份年度报告。 6月1日是节假日的，核动力厂营运单位提交核动力厂设备可靠性数据年度报告的届满之日顺延至节假日后第一个工作日。"},{"i":14,"n":"第十四条","txt":"核动力厂设备可靠性数据年度报告包括下列内容： （一）设备类综述、划分原则和设备详细信息等基础信息； （二）筛选统计准则、设备失效事件分析过程和设备失效事件记录等可靠性数据筛选统计过程； （三）设备可靠性数据采集统计结果、核电机组安全重要系统设备列的不可用时间与总的需求可用时间等数据统计结果。"},{"i":15,"n":"第十五条","txt":"核动力厂营运单位应当从获得选址阶段环境影响报告书批复之日起，至取得退役批准书之日止，对未纳入建造阶段月度报告和运行阶段月度报告的重要活动，以电子邮件等有效方式及时向核动力厂所在地区核与辐射安全监督站报告。"},{"i":16,"n":"第十六条","txt":"本规定第十五条规定的重要活动包括： （一）核动力厂营运单位组织的与核安全有关的重要调查、审查或者检查活动； （二）国家核安全局或者核动力厂所在地区核与辐射安全监督站确定的有关控制点的变更和后续计划安排； （三）核动力厂营运单位涉及核安全的重要活动、重要会议、论证、试验和纠正措施； （四）核动力厂营运单位进行的固体放射性废物或者乏燃料外运活动； （五）国家核安全局认为应当报告的涉及核安全的其他重要活动； （六）核动力厂营运单位认为应当报告的涉及核安全的其他重要活动。"},{"i":17,"n":"第十七条","txt":"核动力厂营运单位应当在取得运行许可证前，向国家核安全局报告下列建造事件： （一）核电机组安全重要构筑物、系统和设备以及与其有关的采购、土建、安装和调试等活动，与相关法律、行政法规、部门规章和国家强制性标准不一致的； （二）核电机组安全重要构筑物、系统和设备以及与其有关的土建、安装和调试等活动，与核动力厂建造许可文件中认可的初步安全分析报告不一致，导致核电机组安全重要构筑物、系统和设备的安全功能不能满足或者不能确定满足要求的； （三）核电机组安全重要构筑物、系统和设备及其相关活动，违反核动力厂建造许可文件规定的条件，或者未按照建造许可文件规定的条件完成相关论证、验证工作即开展相关活动的； （四）核电机组安全重要构筑物、系统和设备以及与其有关的土建、安装和调试等活动，与核动力厂营运单位在建造许可文件中承诺遵守的规范、标准或者技术条件要求不一致，导致核电机组安全重要构筑物、系统和设备的安全功"},{"i":18,"n":"第十八条","txt":"核动力厂营运单位应当在建造事件发生或者发现后二十四小时内，口头通告国家核安全局和核动力厂所在地区核与辐射安全监督站。口头通告的方式可以采取电话、当面陈述或者其他有效方式。 前款规定的口头通告的内容应当包括核动力厂名称、机组编号、事件发生时间、报告依据、事件摘要和报告人。"},{"i":19,"n":"第十九条","txt":"核动力厂营运单位应当在建造事件发生或者发现后三日内，向国家核安全局和核动力厂所在地区核与辐射安全监督站提交书面通告。第三日是节假日的，核动力厂营运单位提交书面通告的届满之日顺延至节假日后第一个工作日。 前款规定的书面通告的内容应当包括本规定第十八条规定的口头通告的内容，以及出现问题的构筑物、系统和设备及其供货商、制造厂或者施工单位等。"},{"i":20,"n":"第二十条","txt":"核动力厂营运单位应当在建造事件发生或者发现后三十日内，向国家核安全局提交建造事件报告。第三十日是节假日的，核动力厂营运单位提交建造事件报告的届满之日顺延至节假日后第一个工作日。 提交建造事件报告的期限已届满，核动力厂营运单位对建造事件的处理尚没有结论或者没有处理完毕的，可以先向国家核安全局提交阶段性建造事件报告，并在建造事件处理完毕后提交补充信息。 核动力厂建造事件报告的内容应当包括事件背景、事件描述、已经制定的或者正在进行的纠正措施、事件对工程质量和进度的影响、事件的原因分析和经验教训、事件对安全影响的分析等。"},{"i":21,"n":"第二十一条","txt":"国家核安全局认为核动力厂营运单位提交的建造事件报告不够清晰和完整的，应当要求核动力厂营运单位补充或者修改，并提交补充或者修改后的报告。"},{"i":22,"n":"第二十二条","txt":"核动力厂营运单位应当从取得运行许可证之日起，至取得退役批准书之日止，向国家核安全局报告下列运行事件： （一）核动力厂营运单位执行核动力厂运行限值和条件所要求的停堆； （二）核电机组超出安全限值或者安全系统整定值； （三）违反核动力厂运行限值和条件规定的操作或者状况； （四）导致核电机组主要实体屏障严重劣化或者处于明显降低核动力厂安全的没有分析过的状况； （五）任何对核电机组安全有现实威胁或者明显妨碍核动力厂现场人员执行安全运行有关职责的自然事件或者其他外部事件； （六）导致反应堆停堆保护系统和专设安全设施自动或者手动触发的事件； （七）任何可能妨碍构筑物或者系统实现停堆和保持安全停堆状态、排出堆芯余热、控制放射性物质释放、缓解事故后果等安全功能的事件或者状况； （八）同一原因或者状况导致具有停堆和保持安全停堆状态、排出堆芯余热、控制放射性物质释放、缓解事故后果等安全功能的系统的系列或者"},{"i":23,"n":"第二十三条","txt":"核动力厂营运单位应当在运行事件发生或者发现后二十四小时内，口头通告国家核安全局和核动力厂所在地区核与辐射安全监督站。口头通告的方式可以采取电话、当面陈述或者其他有效方式。 前款规定的口头通告的内容应当包括核动力厂名称、机组编号、事件发生时间、报告依据、事件发生前机组状态和功率水平、事件初步情况，以及口头通告时所处的状况。"},{"i":24,"n":"第二十四条","txt":"核动力厂营运单位应当在运行事件发生或者发现后三日内，向国家核安全局和核动力厂所在地区核与辐射安全监督站提交书面通告，并在书面通告中对运行事件进行初步事件分级。第三日是节假日的，核动力厂营运单位提交书面通告的届满之日顺延至节假日后第一个工作日。 前款规定的书面通告的内容应当包括本规定第二十三条规定的口头通告的内容，以及事件对运行的影响、放射性后果、出现问题的系统或者设备等。"},{"i":25,"n":"第二十五条","txt":"核动力厂营运单位应当在运行事件发生或者发现后三十日内，向国家核安全局提交运行事件报告，并在运行事件报告中对运行事件进行事件分级。第三十日是节假日的，核动力厂营运单位提交运行事件报告的届满之日顺延至节假日后第一个工作日。 提交运行事件报告的期限已届满，核动力厂营运单位对运行事件的处理尚没有结论或者没有处理完毕的，可以先向国家核安全局提交阶段性运行事件报告，并在运行事件处理完毕后提交补充信息。 核动力厂运行事件报告的内容包括事件描述、主要的失效、安全系统响应、事件原因分析、安全后果评估、纠正措施、事件分级、以往类似事件、事件编码等。"},{"i":26,"n":"第二十六条","txt":"国家核安全局认为核动力厂营运单位提交的运行事件报告不够清晰和完整的，应当要求核动力厂营运单位补充或者修改，并提交修改后的报告。"},{"i":27,"n":"第二十七条","txt":"核动力厂进入应急状态、应急状态变更或者应急状态终止后十五分钟内，核动力厂营运单位应当首先用电话，随后用传真或者其他约定的电子信息传输方式向国家核安全局和核动力厂所在地区核与辐射安全监督站发出核事故应急通告。"},{"i":28,"n":"第二十八条","txt":"核动力厂进入应急状态后，核动力厂营运单位应当保持与国家核安全局应急网络平台的畅通，直到应急状态终止。"},{"i":29,"n":"第二十九条","txt":"核动力厂进入厂房应急或者高于厂房应急状态后的一小时内，核动力厂营运单位应当采用电话、传真或者其他约定的电子信息传输方式向国家核安全局和核动力厂所在地区核与辐射安全监督站发出核事故应急报告，并在首次发出核事故应急报告之后持续发出核事故应急报告，直至应急状态终止。 同一应急状态下，核动力厂营运单位连续两次发出核事故应急报告的时间间隔不应超过一小时；事故态势得到控制后，核动力厂营运单位发出核事故应急报告的时间间隔可适当延长，但不得超过四小时。 核动力厂营运单位认为有必要时,可以向国家核安全局和核动力厂所在地区核与辐射安全监督站即时报送核事故应急报告，不受本条规定的时间间隔限制。"},{"i":30,"n":"第三十条","txt":"核动力厂应急状态终止后三十日内，核动力厂营运单位应当向国家核安全局提交核动力厂核事故最终评价报告，并在核事故最终评价报告中对核事件或者事故进行分级。 第三十日是节假日的，核动力厂营运单位提交核事故最终评价报告的届满之日顺延至节假日后第一个工作日。"},{"i":31,"n":"第三十一条","txt":"本规定中下列用语的含义： （一）核动力厂，是指核电厂、核热电厂、核供汽供热厂等核动力厂及装置。 （二）事件或者事故分级，是指按照国际核事件分级标准（INES）对运行事件或者事故进行的分级。考虑核事件对人和环境的影响、对设施放射性包容和控制的影响、对纵深防御能力的影响，将核事件分为七级，其中较低级别称为事件，分别为异常（1级）、一般事件（2级）、重要事件（3级）；较高级别称为事故，分别为影响范围有限的事故（4级）、影响范围较大的事故（5级）、重要事故（6级）和重大事故（7级）。对不具有安全意义的微小事件称为“偏差”，归为0级。 （三）核事故应急状态，根据《核电厂核事故应急管理条例》的有关规定，分为应急待命、厂房应急、场区应急和场外应急四级。"},{"i":32,"n":"第三十二条","txt":"核动力厂营运单位的核安全信息公开，按照《核安全信息公开办法》执行。"},{"i":33,"n":"第三十三条","txt":"本规定由国家核安全局负责解释。"},{"i":34,"n":"第三十四条","txt":"本规定自2021年1月1日起施行。1995年6月14日国家核安全局发布的《核电厂营运单位报告制度》同时废止。"}],"hecailiaoguanzhitiaolishishixize":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国核材料管制条例》（以下简称《条例》）第二十三条规定制定本实施细则。"},{"i":2,"n":"第二条","txt":"本实施细则适用于核材料许可证的申请、审查、核准、颁发和核材料的帐务衡算管理及实物保护。本实施细则所涉及的核材料管制的范围，按《条例》第二条办理。"},{"i":3,"n":"第三条","txt":"能源部委托中国核工业总公司负责全国核材料的管制，下设核材料管制办公室（以下简称“办公室”），具体负责核材料管制工作。"},{"i":4,"n":"第四条","txt":"核材料管制办公室的具体职责是：  （一）根据《条例》和本实施细则，拟订核材料管制的规章制度和技术规范； （二）按照《条例》规定，接受核材料许可证的申请，负责办理发放核材料许可证； （三）实施全国核材料管制，负责建立全国核材料帐务系统和检查许可证持有者的核材料帐务衡算管理及实物保护和保密工作。核材料帐务与衡算的具体格式另行规定； （四）向国家核安全局和国防科工委分别提交民用和军用核材料的季度报告（包括转让、盘存、帐务）及年度衡算报告； （五）在发生核材料被盗、破坏、丢失、非法转让和非法使用事件时，及时采取措施，并迅速将情况通报国家核安全局、国防科工委、公安部及其它有关部门。"},{"i":5,"n":"第五条","txt":"根据《条例》第十六条的规定，核材料许可证持有单位法人代表对所持有的核材料负有全面安全责任。"},{"i":6,"n":"第六条","txt":"核材料许可证持有单位必须设立负责机构或指定专人负责贯彻执行《条例》和本实施细则，其具体职责是： （一）制定本单位核材料衡算管理和实物保护的规章制度并负责实施； （二）按“办公室”的规定，上报核材料的转让、定期盘存和帐务衡算报告； （三）对核材料帐务衡算管理人员和实物保护人员进行业务培训及考核。"},{"i":7,"n":"第七条","txt":"核材料许可证持有单位在核材料发生被盗、破坏、丢失、非法转让和非法使用事件时，必须迅速采取措施，并立即报告当地公安部门、“办公室”、以及上级领导部门，并写出事故报告。"},{"i":8,"n":"第八条","txt":"为保证核材料合法利用和安全，根据《条例》第三条规定，国家对核材料实行许可证管理制度。"},{"i":9,"n":"第九条","txt":"申请核材料许可证的单位必须提前六个月提交核材料许可证申请报告。 已经持有核材料的单位，应在本实施细则颁布后一年内办完许可证手续。"},{"i":10,"n":"第十条","txt":"申请核材料许可证必须提交的文件： （一）核材料许可证申请报告（格式见附件一）； （二）核材料帐目与衡算管理实施计划（格式见附件二）；  （三）核材料实物保护与保密实施计划（格式见附件三）；  （四）其他必要的支持性文件。  上述文件送“办公室”前必须经其上级主管部门审核。"},{"i":11,"n":"第十一条","txt":"“办公室”接受许可证申请文件后，提出审查意见，经国家核安全局或国防科工委核准后，办理许可证发放手续。"},{"i":12,"n":"第十二条","txt":"核材料许可证的有效期、更改和中止的规定：  （一）核材料许可证的有效期在许可证中规定，逾期自行失效，需要延长许可证有效期的，必须在期满之前九十天内提出申请； （二）许可证申请中所涉及的核材料品种、数量、用途范围以及管制实施计划有变化时，许可证持有单位应按规定格式（见附件四）向“办公室”提交许可证更改申请，“办公室”审查后，提出答复意见，并报国家核安全局或国防科工委备案； （三）许可证申请中所涉及的核材料品种、数量、用途范围以及管制实施计划有重大变化或更改时，“办公室”有权通知许可证持有单位重新办理许可证； （四）许可证持有单位要求终止许可证时，应在完成核材料清理工作后，向“办公室”提交许可证终止申请报告（格式见附件五），由“办公室”审查核实注销许可证，并报国家核安全局或国防科工委备案。"},{"i":13,"n":"第十三条","txt":"全国核材料帐务系统的范围：  （一）凡属《条例》第二条所列管理范围内的核材料都要列入本帐务系统； （二）铀矿石及其初级产品（即核纯铀化合物之前的产品）、已移交给军队的核制品、以及免于登记的核材料不属于本帐务系统。"},{"i":14,"n":"第十四条","txt":"国内核材料转移必须符合下列规定： （一）调出单位应核实接收单位许可证，填写“核材料交接报告”报“办公室”； （二）一次或多次转让累计数量达到和超过《条例》第九条所列限额者，接收单位也必须持有核材料许可证；  （三）调入与调出双方对核材料数量有争议时，“办公室”有权作出核材料衡算帐目的仲裁决定，必要时委托第三方作出技术鉴定，其仲裁费用由败诉方支付。"},{"i":15,"n":"第十五条","txt":"核材料出入境必须符合下列规定： （一）事先填写《核材料出入境报告》报“办公室”； （二）核材料出境前，调出单位负责押运核材料至出境口岸货场。核材料入境后，接受单位负责从入境口岸货场接收核材料。经办核材料出入境的单位负责办理海关验收手续，双方安全责任以口岸货场为界线； （三）核材料出境口岸交接之后或入境口岸交接之前的运输安全责任，按国际有关规定处理。"},{"i":16,"n":"第十六条","txt":"持有核材料数量小于《条例》第九条所列限额的单位应遵守下列规定： （一）不需要办理核材料许可证，但必须办理核材料登记手续，在调入或再转让核材料时，填写“核材料交接报告”报“办公室”；  （二）核材料的持有者对所持有的核材料负全面安全责任，应采取管理措施，保证核材料的安全，防止核材料被盗、破坏与丢失； （三）遵守国家有关放射性物质的防护、安全处置与安全运输有关规定； （四）每年年末向“办公室”提出本年度有关核材料库存情况的报告，说明核材料的去向及剩余量，并接受监督、检查、指导。"},{"i":17,"n":"第十七条","txt":"对不致危害国家和人民群众安全的少量核材料制品（或含有少量核材料的制品），按《条例》第九条规定可免于登记，免于登记的核材料制品的品种和数量限额由“办公室”另行规定，免于登记的核材料制品的生产单位必须向“办公室”填写该部分“核材料交接报告”，报告其销售品种与数量。"},{"i":18,"n":"第十八条","txt":"根据《条例》第十一条规定，许可证持有单位必须建立核材料衡算制度，在持有核材料期间，进行衡算工作。"},{"i":19,"n":"第十九条","txt":"属下列情况的核材料，经测量和入帐后，其衡算工作即可终止：  （一）已经在反应堆中消耗的； （二）已经按规定手续转让到另一单位的；  （三）已经作为废气、废液排放，或者作为废物进行了处置，不再回收的。但临时存放仍可进行回收的物料除外。"},{"i":20,"n":"第二十条","txt":"许可证持有单位，根据各自的特点，把核设施划分成材料平衡区，按核材料分类进行衡算，每个平衡区要有完整的帐目，实行独立的材料衡算。"},{"i":21,"n":"第二十一条","txt":"许可证持有单位应建立核材料的实物盘存制度，其基本要求是： （一）每年至少进行一次全面、严格的实物盘存。对钚-239、铀-233及铀-235丰度大于20%的浓缩铀等核材料，每年至少进行两次实物盘存；  （二）规定记录和报告的截止日期，在规定时间内（一般在年底）进行盘存；  （三）制定实物盘存计划和工作程序，对盘存过程进行监督；  （四）为保证盘存准确可靠，必须做到：  1.按核材料的种类及物理化学形态进行分类盘存；  2.盘存中所有项目的核材料数量必须是测量值； 3.对设备中核材料的实物盘存和待回收物料，必须制定严格的措施，保证盘存质量；  4.排放或处置废气、废液、废物时必须测量其中的核材料含量。"},{"i":22,"n":"第二十二条","txt":"许可证持有单位应建立原始记录与报告制度，其基本要求是：  （一）核材料帐目的原始记录要求清楚、正确、系统和完整，至少保存五年； （二）帐目管理要系统、准确、及时，各单位按其特点，建立统计记录格式、统计程序和内部审计制度，要有专职的核材料统计人员具体负责统计工作； （三）许可证持有单位按照本实施细则第四条之（三）规定，向办公室提交核材料帐目与衡算报告。"},{"i":23,"n":"第二十三条","txt":"许可证持有单位应建立核材料衡算测量系统，其基本要求是： （一）测量系统要完整、可靠，测量的准确程度要达到附表一的要求；  （二）提供有关核材料收发、库存、损失及材料平衡情况的准确数据，进行误差分析并做出可靠评价；  （三）提出本单位材料衡算测量方案，其主要内容包括：使用的标准物质与标准源、取样和制样、仪器校正、测量方法、数据和资料的记录要求、统计处理和误差评价等。测量方案及测量方案的修改都要报“办公室”备案； （四）测量人员必须严格遵守分析测量操作规程，努力提高测量人员技术水平，建立技术培训和定期考核制度，考核不合格者不得参加测量工作。"},{"i":24,"n":"第二十四条","txt":"核材料衡算的方法及评价 （一）核材料衡算应采用闭合平衡方法，其基本公式如下：  不平衡差（MUF）=期初存量+调入量-期末存量-调出量-已知损失量； （二）当不衡差（MUF）大于其标准误差的2倍时，就认为材料未达到闭合平衡，有可能存在核材料的丢失、盗窃或非法转移。此时，许可证持有单位必须向“办公室”报告，并要求找出不平衡的原因和制定下一步改进的措施。“办公室”有权追查，并视情况作出处理意见； （三）各衡算单位必须标定测量系统的误差，并计算不平衡差的实际测量误差，当结果超过附表一限值标准时，衡算单位必须改进分析测量系统。附表一限值标准的实施日期在许可证文件中规定。"},{"i":25,"n":"第二十五条","txt":"根据《条例》第十二条规定，持有核材料的单位必须有保护核材料的措施，建立安全防范系统。根据核材料的质量、数量及危害性程度，划分为三个保护等级（附表二），实行分级管理。保护等级以下的核材料也应严格管理。"},{"i":26,"n":"第二十六条","txt":"固定场所核材料保护的基本要求：  （一）接触核材料的人员必须经过审查，不适宜的人员要及时调整；  （二）建立核材料实物保护制度、定期检查措施的落实情况，消除隐患，堵塞漏洞，确保安全； （三）建立专职或义务消防组织，制定防火制度，配备相应的装备器材，完善灭火措施；  （四）核材料实物保护措施应报当地公安部门并与其商定紧急情况处置方案。"},{"i":27,"n":"第二十七条","txt":"固定场所的警卫和守护：  （一）一级核材料部位设武装警卫，出入人员使用专门证件，严格控制非本单位工作人员进入，确因工作需要进入者，须经单位主管领导批准，履行登记手续，并由本单位人员陪同，库房实行“双人双锁”制度； （二）二级核材料部位设武装警卫，或固定专人昼夜看守。出入人员使用专门证件；  （三）三级核材料部位设专人看守，或将核材料存入安全装置内；  （四）警卫人员必须经过严格训练，配备必要的装备、器材，一旦发现破坏、抢劫、盗窃行为，应迅速干预制止，及时报告。"},{"i":28,"n":"第二十八条","txt":"固定场所的实体屏障： （一）一级核材料的场所至少要建立两道完整、可靠的实体屏障，储存一级核材料必须有保险库或保险柜； （二）二级核材料的场所要建立两道实体屏障，其中必须有一道是完整可靠的。储存二级核材料必须有坚固的库房或柜； （三）三级核材料的场所必须建立一道完整、可靠的实体屏障。"},{"i":29,"n":"第二十九条","txt":"固定场所的技术防范设施：  （一）一级核材料的场所、部位应装设报警、监视等技术防范装置组成的安全防范系统； （二）二级核材料的场所，其重要部位应装设报警或监视等技术防范装置； （三）无论采用哪一种技术防范措施，都应使之对非法侵入行为发出快速警报。"},{"i":30,"n":"第三十条","txt":"核材料运输保卫必须符合下列规定： （一）托运单位负责运输保卫，应会同运输、产品、安防和保卫等有关部门制定运输保卫方案，一级及二级核材料运输保卫措施必须向当地公安机关报告；  （二）除主管运输部门另有规定之外，核材料的运输必须有专人押运，  （三）一级核材料的运输必须派武装押运；  （四）对参加运输入员和保卫人员要进行安全保卫教育，提出明确的保卫要求，途中不准会客和私人通讯；  （五）运输工具要严格检查，严禁带故障起运，严禁非运输人员搭乘；  （六）运输路线、时间、始发和到达地点不得向无关人员泄漏；申报运输计划、填报货运单据一律使用核材料代号。"},{"i":31,"n":"第三十一条","txt":"核材料运输押运人员职责 （一）起运前认真核对产品件数、编号、封记，检查装载是否符合安全保卫要求，办理交接手续；  （二）途中检查产品包装和加固等安全状况； （三）停车、中转、交接时组织警卫守护； （四）途中发生破坏、偷盗、抢劫核材料的事故或案件，要妥善保护现场，并迅速向当地公安机关及上级领导部门报告，协助有关部门追查处理。"},{"i":32,"n":"第三十二条","txt":"核材料许可证持有单位必须交纳许可证工本费和许可证管理费，费用标准另定。"},{"i":33,"n":"第三十三条","txt":"本实施细则发布单位负责解释。"},{"i":34,"n":"第三十四条","txt":"本实施细则自发布之日起施行。"}],"heranliaoxunhuansheshidebaogaozhidu":[],"hedianchangchangzhixuanzeanquanguiding":[],"hedianchangyingyundanweideyingjizhunbeiheyingjixia3ae597":[{"i":1,"n":"第一条","txt":"根据《核电厂核事故应急管理条例》的有关规定，制定本实施细则。"},{"i":2,"n":"第二条","txt":"本实施细则适用于核电厂营运单位的应急准备和应急响应活动，以及国家核安全部门对这些活动的审评和监督。"},{"i":3,"n":"第三条","txt":"对核电厂营运单位的应急准备和应急响应进行审评、监督的依据是： （一） 国家核安全法规。 （二） 国家的与原子能、辐射防护、环境保护、公安、卫生和交通等有关的法律与法规。 （三） 国家核安全部门审查认可或批准的文件以及发布的其他指令。"},{"i":4,"n":"第四条","txt":"国家核安全部门的监督并不减轻核电厂营运单位对核电厂应急准备、应急响应所承担的责任。"},{"i":5,"n":"第五条","txt":"在核电厂不同阶段对核电厂营运单位及有关单位应急准备和应急响应的要求： （一）可行性研究阶段 在可行性研究报告中，应分析推荐厂址区域的人口特点、地理特征及其他环境特征和在核电厂整个预计寿期内执行应急计划的能力。 （二）设计阶段 在核电厂设计阶段，应对核电厂事故状态（包括严重事故）及其后果作出分析，对厂内的应急设施、应急设备和应急撤离路线作出安排。 在初步安全分析报告（PSAR）有关运行管理的章节中，应提出应急计划的初步方案，其内容包括应急计划的目的、依据的法规和适用范围，营运单位所设置的应急组织及其职责的框架，应急计划区范围的初步测算及其环境（人口、道路、交通等）概况，主要应急设施与设备的基本功能和位置，撤离路线。相关资料可引用PSAR的其他章节的有关内容。 （三）建造阶段 若新建核电厂厂址的邻近已有正在运行的核电厂，则新建核电查供应云单位应针对正在运行的核电厂在事故编制相应的应急准备程"},{"i":6,"n":"第六条","txt":"应急计划及其实施程序的制定 （一）核电厂营运单位应制定场内应急计划和相应的实施程序。 应急计划应根据核电厂可能发生的事故（包括设计基准事故和严重事故）及其对厂内、外的辐射影响以及核电厂厂址周围的自然条件和设备经济特征等制定。 核电厂营运单位应根据其场内应急计划，编写相应的应急计划实施程序。实施程序清单应列入应急计划中。 （二）应急计划应包括下列主要内容： 1.应急组织及其职责 应概述核电厂营运单位的运行组织和应急组织及其职责；应急组织负责制定应急计划和进行应急准备，统一指挥在应急状态下的应急响应，并负责与国家核安全部门及场外应急机构联系。 2.应急状态、干预水平和应急行动水平 应描述各应急状态的基本特征和不同应急状态下拟采取的应急响应行动，提出各种应急防护措施下使用的干预水平。应根据核电厂的设计特征和厂址特征提出应急行动水平。在申请首次装料批准书时，提出初步制定的应急行动水平；在申请运"},{"i":7,"n":"第七条","txt":"营运单位的应急组织应根据应急演习和练习的结果、核电厂实际发生的事件或事故的经验、核安全法规要求的变更、设施和设备的变动以及技术的进步等，对应急计划和实施程序进行定期、不定期复审和修订。营运单位应至少每二年一次对应急计划进行修订，经修订后的应急计划必须报国家核安全部门备案。应急人员替代表内记录的各项内容如有变动应及时更新和报告。"},{"i":8,"n":"第八条","txt":"国家核安全部门对营运单位申请核安全许可证件时提交的文件中关于应急准备、应急计划的有关内容进行的审评： （一）对可行性研究报告中厂址部分的评价 确定该厂址对实施应急计划和应急措施的可行性，审查厂址周围的人口密度和分布（特别是可能影响采取应急措施的特殊人群组情况）及其在核电厂预计寿期内的变化，特殊的地理特征，周围经济、工业、农业、生态和环境特征。审评结论作为《核电厂厂址选择审查意见书》的内容之一。 （二）对应急计划初步方案的审评 审查初步安全分析报告中有关应急计划的初步方案的资料是否足够，是否满足本实施细则中第五条第（二）款的要求。评价应急设施的设计和设备配置的合理性,应急计划初步方案的适宜性,应急计划区范围和撤离路线的设计是否满足要求。 （三）对应急计划的审评 审查申请者提供的资料是否齐全，是否满足本实施细则第六条第(二)款和有关规定的要求。评价该计划是否能保证在事故情况下采取及时的和后"},{"i":9,"n":"第九条","txt":"在核电厂运行期间，国家核安全部门对核电厂营运单位的应急准备状况执行应急响应的能力进行监督。监督的方式为日常的和例行的检查，检查的主要项目包括对应急组织、应急人员、程序、设施和物资以及对来自厂外的技术支援的检查，验证和检查是否符合有关核安全法规和应急计划的要求、是否做到常备不懈。 检查项目的主要内容如下： （一）应急组织。检查营运单位的应急组织是否符合应急计划的要求，是否保持高效、快速的应急响应能力，检查与国家核安全部门、场外应急组织联系的组织、人员、条件及程序。 （二）应急状态分级和应急行动水平。检查营运单位的应急状态分级准则和应急水平以及有关人员对这些文件的熟悉情况。 （三）应急人员的应急响应能力。检查应急人员具有完成应急响应的能力和知识，包括检查重要岗位应急人员连续24小时的应急能力，应急人员花名册，应急人员及时获得通知的手段及程序，应急人员对自己在应急状态下职责及与其他应急人员的"},{"i":10,"n":"第十条","txt":"国家核安全部门对营运单位应急准备的核安全监督的方法及其对营运单位的要求等，执行核安全法规《中华人民共和国民用核设施安全监督管理条例实施细则之二——核设施的安全监督》。为保证与国家核安全部门通信联络的及时可靠，营运单位应向其提供必要的条件（包括通信器材）。"},{"i":11,"n":"第十一条","txt":"在应急响应期间，国家核安全部门应对核电厂营运单位的响应活动和应急决策及其与场外应急组织的协调和提出的或采取的措施进行检查和评估，必要时进行干预；审查终止厂房应急状态及以上应急状态的条件。 在应急状态结束后，审查核电厂营运单位的后续行动和恢复活动，调查出现事故的原因和事故后果，评价营运单位对事故后果的分析，确定核电厂恢复运行、重新取证或退役。"},{"i":12,"n":"第十二条","txt":"核电厂营运单位应做好运行状态下的应急准备工作的年度计划，并对有关活动进行详细记录和存档工作。 根据国家核安全部门的要求提交应急准备工作的年度计划报告和上年度的总结报告。 （一） 应急准备工作的年度计划报告的内容主要包括： 1.应急培训和演习的计划与内容； 2.应急设备的维护计划和预计的可能变更； 3.有关应急文件的修订计划等。 （二）应急准备工作的年度总结报告内容主要包括： 1.应急培训和演习内容、参加人员和取得的效果等； 2.应急设施、设备、通信系统和给类应急器材的清单、状况、标定以及检查维修的结果。 （三）运行事件通告和报告，按核安全法规《中华人民共和国民用核设施安全监督管理条例实施细则之二附件一——核电厂营运单位报告制度》执行。"},{"i":13,"n":"第十三条","txt":"营运单位向国家核安全部门提交报告的时间为： 1.每次综合演习和联合演习结束后一个月内； 2.应急准备工作的年度计划和上年的总结报告在每年的第一季度末提交。"},{"i":14,"n":"第十四条","txt":"核电厂应急状态下和应急终止后的记录和报告： （一）应详细地记录应急期间的下列内容并存档： 1.事故始发过程和演变过程； 2.急期间的评价活动、监测结果、采取的补救措施、防护措施和执行的应急行动程序及时序等； 3.事故释放的源项和后果。 （二）营运单位应在发生事故并进入应急待命或高于应急待命状态后15分钟内，向国家核安全部门发出应急通告，并在进入厂房应急或以上应急状态后15分钟向所在省（自治区、直辖市）应急指挥中心发出应急通告。 （三）营运单位应在核事故发生并进入厂房应急或高于厂房应急状态后的45分钟内向国家核安全部门以及所在省（自治区、直辖市）应急指挥中心发出应急报告；在应急初始报告发出后，每隔1小时向国家核安全部门和所在省（自治区、直辖市）应急指挥中心发一次后续报告；在事故源项或应急状态级别变更时，必须立即用电话传真方式项国家核安全部门报告。事故发生一段时间后若核电厂事故状态变化相对"},{"i":15,"n":"第十五条","txt":"根据《中华人民共和国民用核设施安全监督管理条例》第三十八条、《中华人民共和国民用核设施安全监督管理条例》第二十一条的规定，有下列行为之一的，国家核安全部门可依其情节轻重，对营运单位给予警告、限期改进、停工或者停业整顿、吊销核安全许可证件的处罚： （一）不按照本实施细则的规定制定的应急计划，拒绝承担核电厂应急准备义务的； （二）玩忽职守，不能维持应急响应能力，使主要应急设施和（或）设备丧失功能的； （三）不按照规定报告、通报核事故真实情况的； （四）不按照规定执行已经国家核安全部门审批的应急响应计划的； （五）核事故使核安全重要物项的安全性能达不到规定的核安全标准时，或其他安全功能受到了损坏，未加纠正并未经国家核安全部门的审查批准擅自重新启动核电厂的； （六）其他违反本实施细则的。"},{"i":16,"n":"第十六条","txt":"本实施细则中下列用语的定义为： 应急 需要立即采取某些超出正常工作程序的行动以避免事故发生或减轻事故后果的状态。有时又称为紧急状态。 应急计划区 为在事故时能及时、有效地采取保护公众的防护行动，事先在核电厂周围建立的、制定有应急计划并做好应急准备的区域。 场区 具有确定的边界、在核电厂管理人员有效控制下的核电厂所在领域。 应急行动水平 用作应急状态分级基础的核电厂起始条件，如预先确定的、该核电厂及厂址特有的、可观测的阈值或判据。 应急准备 为应付核事故或辐射应急而进行的准备工作，包括制订应急计划，建立应急组织，准备必要的应急设施、设备与物资，以及进行人员培训与演习等。 应急响应 为控制或减轻核事故或辐射应急状态的后果而采取的紧急行动。 应急（响应）计划 经过审批的，描述营运单位的应急响应能力、组织、设施和设备以及和外部应急机构的协调和相互支持关系的文件。该文件海笔许有专门实施程序加以补"},{"i":17,"n":"第十七条","txt":"对核电厂以外的其他民用核设施的应急准备和应急响应的监督管理，可以根据具体情况，参照本实施细则的有关规定执行。"},{"i":18,"n":"第十八条","txt":"本实施细则由国家核安全局解释、补充和修改。"},{"i":19,"n":"第十九条","txt":"本实施细则自发布之日起施行。"}],"hedianchangzhiliangbaozhenganquanguiding":[],"hedianchangyunxinganquanguidingfujianyihedianchangec2653":[],"hesheshideanquanjiandu":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国民用核设施安全监督管理条例》（以下简称《条例》）第二十五条的规定，制定本实施细则。"},{"i":2,"n":"第二条","txt":"核安全监督的目的是通过检查核安全管理要求和许可证件规定条件的履行情况，督促纠正不符合核安全管理要求和许可证件规定条件的事项，必要时可采取强制性措施，以保障核设施的安全。"},{"i":3,"n":"第三条","txt":"本实施细则适用于对核设施在选址、设计、建造、调试、运行和退役各阶段与核安全有关的全部物项和活动（以下简称核设施物项与活动）的核安全监督。"},{"i":4,"n":"第四条","txt":"核安全监督的依据是： （一）国家核安全法规： （1）《中华人民共和国民用核设施安全监督管理条例》及其实施细则； （2）《中华人民共和国核材料管制条例》及其实施细则； （3）《中华人民共和国核电厂核事故应急管理条例》； （4）《核电厂厂址选择安全规定》； （5）《核电厂设计安全规定》； （6）《核电厂运行安全规定》； （7）《核电厂质量保证安全规定》； （8）《核电厂放射性废物管理安全规定》； （9）《民用核承压设备安全监督管理规定》及其实施细则； （10）《研究堆设计安全规定》； （11）《研究堆运行安全规定》； （12）《民用核燃料循环设施安全规定》； （13）国家核安全局发布的其他核安全法规。 （二）国家的与原子能、辐射防护、环境保护、公安、卫生和交通等有关的其他法律与法规。 （三）核设施环境影响报告批准书。 （四）核设施许可证件规定条件。 （五）国家核安全局审查认可或批准的文件；"},{"i":5,"n":"第五条","txt":"国家核安全部门的监督并不减轻核设施营运单位及有关单位对核设施所承担的核安全责任。"},{"i":6,"n":"第六条","txt":"核安全监督由国家核安全局及其地区监督站组织实施。"},{"i":7,"n":"第七条","txt":"国家核安全局在核安全监督工作中负领导责任，其具体职责为： （一）负责培训、考核核安全监督员，并授予核安全监督员证（核安全监督员应具备的条件见附录A）； （二）组织编制全国核设施的年度检查计划，批准地区监督站辖区内核设施的年度检查计划； （三）组织编制核设施监督项目表、监督检查大纲、检查程序等监督文件； （四）负责组织由局实施的例行核安全检查和非例行核安全检查； （五）负责组织对重大不符合项和核安全相关事件等进行评价，并对核设施的安全状况进行综合评价； （六）监督操纵人员资格的考核工作； （七）负责建立核设施运行状态数据库、事件库，并进行经验反馈的分析研究； （八）采取或授权采取执法行动。"},{"i":8,"n":"第八条","txt":"地区监督站作为国家核安全局的派出机构，负责派驻区核设施的核安全监督。其具体职责为： （一）编制和实施辖区内核设施的年度检查计划； （二）负责向核设施现场派遣并管理核安全检查组和核安全监督员； （三）负责日常核安全检查，组织由站实施的或参加由局实施的例行核安全检查和非例行核安全检查； （四）检查与督促营运单位执行报告制度； （五）参与检查操纵人员资格的考核工作； （六）评价或参与评价不符合项、核安全相关事件及核设施的安全状况； （七）处理违反核安全管理要求和许可证件规定条件的事项，对重大事项，及时向国家核安全局报告，并提出采取执法行动的建议，在国家核安全局授权时采取执法行动。"},{"i":9,"n":"第九条","txt":"现场核安全监督员是核安全监督的执行人员，其具体职责为： （一）向核设施营运单位及有关单位和人员宣传国家核安全政策和法规，并监督其执行法规和贯彻核安全文化的情况； （二）参加日常、例行和非例行核安全检查工作， （三）监督己批准的不符合项处理程序的实施，并向地区监督站提出评价意见的建议； （四）检查与核实核设施营运单位及有关单位遵守核安全管理要求和许可证件规定条件的情况，及时报地区监督站； （五）有权要求营运单位停止明显违反核安全管理要求和许可证件规定条件的行为以及紧急危及核安全的活动，并必须立即报地区监督站和国家核安全局追认核准。"},{"i":10,"n":"第十条","txt":"执行专项任务的核安全检查组、核安全监督员及受国家核安全局或地区监督站委托的人员（以下简称受委托人员）应在依法授权的范围内进行工作。"},{"i":11,"n":"第十一条","txt":"核安全监督员和受委托人员必须遵守营运单位及有关单位的保卫、保密和辐射防护等方面的规定，并保证未经营运单位和/或有关单位同意，不得将保密资料泄漏给任何第三方。"},{"i":12,"n":"第十二条","txt":"核安全检查连续贯彻于核设施选址、设计、建造、调试、运行和退役的全过程和所有重要活动。"},{"i":13,"n":"第十三条","txt":"核安全检查的目的是核实和监视营运单位及有关单位的核设施物项和活动是否满足核安全管理要求和许可证件规定的条件，督促营运单位及有关单位及时纠正缺陷和异常状态，以确保核设施选址、设计、建造、调 试、运行和退役符合批准的文件和有关要求。"},{"i":14,"n":"第十四条","txt":"核安全检查的范围主要是许可证件规定条件中所规定的范围，以及在审批许可证过程中确定需要检查的范围。"},{"i":15,"n":"第十五条","txt":"核安全检查可以分为日常的、例行的和非例行（特殊）的检查。非例行的检查可以是事先通知或事先不通知的。事先通知的检查一般在检查前一个月通知营运单位和/或有关单位，以便做好准备和安排。"},{"i":16,"n":"第十六条","txt":"核安全检查由核安全检查组、核安全监督员或受委托人员进行。核安全检查的主要方法为： （一）文件检查：对执行程序、试验程序、质量保证记录、试验结果和数据、运行维修记录以及缺陷和异常事件记录等作检查； （二）现场观察：在现场直接观察核设施物项或活动是否按有关规定和文件实施； （三）座谈和采访：召开营运单位及有关单位的领导、质保和质检人员以及有关人员参加的座谈会，或向他们专门采访，以了解情况； （四）测量或试验：必要时，可进行测量或试验，例如，尺寸测量、照相、录相及在营运单位协同下进行取样、放射性检测和无损探伤等。但这种测量、取样或试验并不代替营运单位和/或有关单位应做的测量和试验，也不减轻营运单位和/或有关单位的责任。"},{"i":17,"n":"第十七条","txt":"日常核安全检查是由现场核安全监督员所作的检查。现场核安全监督员应对影响核安全的重要活动、物项和记录进行检查，并做好检查记录。"},{"i":18,"n":"第十八条","txt":"例行核安全检查是核安全检查组或核安全监督员根据国家核安全局制定的检查大纲，对营运单位在核设施选址、设计、建造、调试、运行、退役各阶段的安全重要活动所进行的有计划的核安全检查。例行核安全检查的程序如下： （一）准备工作：国家核安全局（或地区监督站）在检查开始前一个月将检查的目的、要求和日期通知营运单位及有关单位。营运单位应在检查开始前十五天反馈意见，并做好接受检查的准备。 （二）检查前会议：在检查开始时召开会议，宣布检查的具体目的，提出有关单位应配合的工作内容，并确定检查日程表。 （三）检查的实施：例行核安全检查的实施应按确定的检查项目、程序和检查表格进行。 （四）检查后会议：在检查后会议上通告检查初步结果和要求。营运单位及有关单位可对检查初步结果陈述意见。 （五）检查报告：核安全检查组或核安全监督员在检查工作结束后以规定的格式写出检查报告，主要包括检查项目、经过、结果、评价以及对应采取"},{"i":19,"n":"第十九条","txt":"非例行核安全检查是国家核安全局或地区监督站根据工作需要进行的检查，是对意外的、非计划的或异常的情况或事件的响应。非例行核安全检查应根据检查项目具体情况，参照例行核安全检查的程序实施。"},{"i":20,"n":"第二十条","txt":"根据《条例》第七、十六和十七条的规定，营运单位及有关单位应积极主动地按如下要求接受和配合核安全检查： （一）在接受核安全检查时，必须如实地反映情况，根据检查要求提供或出示有关的工作程序、质保程序、文件和记录、数据和图纸，以及含有建造质量、测试结果、运行情况和维修经过等信息的各种资料； （二）当国家核安全局认为必要时，营运单位应对调试和运行期间的试验项目予以演示； （三）应保证核安全监督人员在执行任务时能自由地、迅速地进入核设施和有关生产场所的任何地区。只有当营运单位及有关单位能证明这种进入对安全有威胁时，才能对这种进入要求提出限制； （四）应在不危及核安全的前提下，保证核安全监督人员在执行任务时能自由地、及时地接触有关人员； （五）应为执行核安全检查的人员提供必要的条件，充分配合、协助做好核安全检查工作。"},{"i":21,"n":"第二十一条","txt":"国家核安全局可根据工作需要，在核设施建造、调试和运行阶段选定控制点和见证试验项目。营运单位应按国家核安全局的要求提供有关资料，并发出通知。"},{"i":22,"n":"第二十二条","txt":"营运单位应向地区监督站定期报告核设施的活动计划、进度、变更和核安全状况。"},{"i":23,"n":"第二十三条","txt":"营运单位必须执行核设施营运单位报告制度。报告制度包括： （一）定期报告； （二）重要活动通知； （三）建造阶段事件报告； （四）运行阶段事件报告； （五）核事故应急报告。 上述报告或通告的报告准则和要求见本细则附件。"},{"i":24,"n":"第二十四条","txt":"营运单位及有关单位内的质量保证、安全防护等部门有权直接向地区监督站或国家核安全局反映问题。他们的职权应受到尊重和保护。"},{"i":25,"n":"第二十五条","txt":"营运单位及有关单位有权检举核安全监督人员的渎职违法行为。"},{"i":26,"n":"第二十六条","txt":"根据《条例》第十八条的规定，为了保证现场工作人员、公众和环境辐射防护的需要，国家核安全局有权依法要求营运单位及有关单位消除有关核设施物项和活动中任何不安全因素。"},{"i":27,"n":"第二十七条","txt":"根据《条例》第十八、二十一和二十三条的规定，国家核安全局将按下列各款发布强制性命令： （一）在核设施选址、设计、建造、调试、运行和退役过程中对轻微违反核安全管理要求或许可证件规定条件，对不报或谎报事实真相，对无故拒绝核安全俭查，对无照上岗操作，国家核安全局向营运单位及有关单位发出警告。 （二）在核设施选址、设计、建造、调试、运行和退役过程中对严重违反核安全管理要求或许可证件规定条件的营运单位及有关单位，国家核安全局可责令限期改进或停业整顿；对调试、运行和退役过程中发生可能使现场工作人员和公众面临放射性危害，或者核设施与核安全有关的重要物项严重损坏无法修复，国家核安全局可责令停业整顿或停工；对未经批准从事核设施建造、运行、迁移、转让和退役的营运单位及有关单位，国家核安全局可责令停工。 （三）对拒绝执行强制性命令或严重违章操作致使核设施损坏、功能失常造成长期不合格或严重不合格，或发生对现场"},{"i":28,"n":"第二十八条","txt":"被处罚单位或个人对处罚不服时，按照《条例》第二十二条的规定办理。但是，在现场工作人员和公众面临严重超剂量辐射危害和环境可能受到严重污染的情况下，必须采取先执行后申诉的原则。"},{"i":29,"n":"第二十九条","txt":"国家核安全局采取的强制性命令应以书面形式通知核设施营运单位及有关单位。在非常情况下由地区监督站执行，事后补发通知。"},{"i":30,"n":"第三十条","txt":"对于不服从管理、违反规章制度或者强令他人违章作业，因而发生核事故，造成严重后果，构成犯罪的，将依法追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"本实施细则中下列用语的定义为： 核安全监督 核安全监督包括检查和处理、处罚、强制性命令，简称检查和执法。 核安全检查 国家核安全局、地区监督站、核安全检查组、核安全监督员、或受委托人员对营运单位及有关单位的物项与活动所进行的核实和监视。 核安全管理要求 国家、国家核安全局和其他政府部门发布的与核安全有关的法律、条例、 规定和实施细则所规定的要求。 国家核安全部门 国家核安全局及其地区监督站系统称国家核安全部门。"},{"i":32,"n":"第三十二条","txt":"本实施细则由国家核安全局解释、修改和制定相应的附件和附录。其附件与本实施细则具有同等的法律效力，其附录为参考文件。"},{"i":33,"n":"第三十三条","txt":"本实施细则自一九九五年十月一日起施行，一九八八年四月十四日国家核安全局发布的《中华人民共和国民用核设施安全监督管理条例实施细则之二-核电厂的安全监督》及其相应的附件同时废止。 附录A 核安全监督员应具备的条件 为保证核安全监督的质量，核安全监督员应具备的主要条件是： （一）具有大学以上文化水平或同等学历； （二）具有五年以上工程实践或三年以上核安全管理的经验，并能依法履行核安全监督工作及独立作出正确的判断和写出合格的报告； （三）熟知国家核安全法规，模范地遵守国家的法律和规定； （四）作风正派，办事公正，工作认真，态度谦虚。 国家核安全局根据工作需要，挑选具有上述条件的人员进行培训考核，考试合格者由国家核安全局发给“核安全监督员证”。"}],"minyongheanquanshebeiwusunjianyanrenyuanzigeguanlibbc1b9":[{"i":1,"n":"第一条","txt":"为了加强民用核安全设备无损检验人员（以下简称无损检验人员）的资格管理，保证民用核安全设备质量，根据《中华人民共和国核安全法》和《民用核安全设备监督管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于无损检验人员的资格考核和管理工作。 无损检验人员的资格等级分为Ⅰ级（初级）、Ⅱ级（中级）和Ⅲ级（高级）。"},{"i":3,"n":"第三条","txt":"从事民用核安全设备无损检验活动（以下简称无损检验活动）的人员应当依据本规定取得资格证书。"},{"i":4,"n":"第四条","txt":"国务院核安全监管部门负责无损检验人员的资格管理，统一组织资格考核，颁发资格证书，对无损检验人员资格及相关资格考核活动进行监督检查。"},{"i":5,"n":"第五条","txt":"民用核安全设备制造、安装、无损检验单位和民用核设施营运单位（以下简称聘用单位）应当聘用取得资格证书的人员开展无损检验活动，对无损检验人员进行岗位管理。"},{"i":6,"n":"第六条","txt":"本规定所称的无损检验方法是指无损检验活动中的超声检验（UT）、射线检验（RT）、涡流检验（ET）、泄漏检验（LT）、渗透检验（PT）、磁粉检验（MT）、目视检验（VT）以及国务院核安全监管部门认可的其他无损检验方法。"},{"i":7,"n":"第七条","txt":"Ⅰ级无损检验人员在Ⅱ级或者Ⅲ级无损检验人员的监督指导下方可承担下列工作： （一）安装和使用仪器设备； （二）按照无损检验规程进行无损检验操作； （三）记录检验数据。"},{"i":8,"n":"第八条","txt":"Ⅱ级无损检验人员承担下列工作： （一）根据确定的工艺，编制无损检验规程； （二）调整和校验仪器设备，实施无损检验活动； （三）依据标准、规范和无损检验规程，评价检验结果； （四）编制无损检验结果报告； （五）监督和指导Ⅰ级无损检验人员； （六）本规定第七条所列工作。"},{"i":9,"n":"第九条","txt":"Ⅲ级无损检验人员承担下列工作： （一）确定无损检验技术和工艺； （二）制定特殊的无损检验工艺； （三）对无损检验结果进行评定； （四）编制验收准则； （五）审核无损检验规程和结果报告； （六）本规定第八条所列工作。"},{"i":10,"n":"第十条","txt":"申请Ⅰ级资格考核的人员应当具备下列条件： （一）身体健康，裸视或者矫正视力达到4.8及以上，辨色视力正常； （二）大专及以上学历，工作满1年，或者中等职业教育、高中学历，工作满2年。"},{"i":11,"n":"第十一条","txt":"申请Ⅱ级资格考核的人员应当具备下列条件： （一）身体健康，裸视或者矫正视力达到4.8及以上，辨色视力正常； （二）持有拟申请方法Ⅰ级资格证书满2年且业绩良好，或者持有特种设备相应方法Ⅱ级资格证书满1年且业绩良好，或者持有特种设备相应方法Ⅲ级资格证书。"},{"i":12,"n":"第十二条","txt":"申请Ⅲ级资格考核的人员应当具备下列条件： （一）身体健康，裸视或者矫正视力达到4.8及以上，辨色视力正常； （二）持有超声检验（UT）、射线检验（RT）、涡流检验（ET）中1种及以上方法的Ⅱ级资格证书； （三）持有泄漏检验（LT）、渗透检验（PT）、磁粉检验（MT）、目视检验（VT）中1种及以上方法的Ⅱ级资格证书； （四）持有拟申请方法Ⅱ级资格证书满5年且业绩良好，或者持有特种设备相应方法Ⅲ级资格证书满2年且业绩良好。"},{"i":13,"n":"第十三条","txt":"有下列情形之一的人员，申请Ⅱ级或者Ⅲ级资格考核的，其有关工作年限在本规定第十一条或者第十二条有关规定基础上延长2年： （一）脱离无损检验工作1年以上的； （二）违反无损检验操作规程或者标准规范，未造成严重后果的。"},{"i":14,"n":"第十四条","txt":"有下列情形之一的人员，不得申请民用核安全设备无损检验人员资格考核： （一）被吊销资格证书的人员，自证书吊销之日起未满3年的； （二）依照本规定被给予不得申请资格考核的处理期限未满的。"},{"i":15,"n":"第十五条","txt":"国务院核安全监管部门制定考试计划，组织承担考核工作的单位（以下简称考核单位）实施资格考核。 考核单位负责管理检验设备、仪器，维护试块和试件，实施具体考试工作，出具考试结果报告。"},{"i":16,"n":"第十六条","txt":"申请人员由聘用单位组织报名参加资格考核，并提交下列材料： （一）申请表； （二）学历证明； （三）二级及以上医院出具的视力检查结果； （四）相关资格证书。"},{"i":17,"n":"第十七条","txt":"国务院核安全监管部门对申请材料进行审核，自收到材料之日起5个工作日内确认申请人员考试资格。"},{"i":18,"n":"第十八条","txt":"Ⅰ级和Ⅱ级的资格考核包括理论考试和操作考试。Ⅲ级的资格考核包括理论考试、操作考试和综合答辩。 资格考核按不同的检验方法和级别进行。"},{"i":19,"n":"第十九条","txt":"Ⅰ级和Ⅱ级的理论考试主要考查申请人员对核设施系统基本知识、核安全设备及质量保证相关知识、核安全文化和无损检验基础知识的理解和掌握程度，以及将有关无损检验技术应用于民用核安全设备的能力。 Ⅲ级的理论考试除包括前款规定的考查内容外，还应当考查申请人员对无损检验新技术、特殊工艺和相关标准规范的理解和应用能力。"},{"i":20,"n":"第二十条","txt":"操作考试主要考查申请人员正确应用无损检验仪器设备进行操作，出具检验结果并对结果进行评价的能力。"},{"i":21,"n":"第二十一条","txt":"综合答辩主要考查申请人员对民用核安全设备无损检验理论、方法和实践操作等方面的综合应用能力。"},{"i":22,"n":"第二十二条","txt":"所有考试成绩均达到合格标准视为资格考核合格。 考试成绩未达到合格标准的，可在考试结束日的次日起1年内至多补考两次，补考仍未合格的，视为本次考核不合格。"},{"i":23,"n":"第二十三条","txt":"国务院核安全监管部门收到考核单位的考试结果报告之日起20个工作日内完成审查，作出是否授予资格的决定。 资格证书由国务院核安全监管部门自授予资格决定之日起10个工作日内向合格的人员颁发。"},{"i":24,"n":"第二十四条","txt":"资格证书包括下列主要内容： （一）人员姓名、身份证号及聘用单位； （二）方法和级别； （三）有效期限； （四）证书编号。"},{"i":25,"n":"第二十五条","txt":"资格证书的有效期限为5年。"},{"i":26,"n":"第二十六条","txt":"资格证书有效期届满拟继续从事无损检验活动的人员，应当在证书有效期届满6个月前，由聘用单位组织向国务院核安全监管部门提出延续申请，并提交下列材料： （一）申请表； （二）二级及以上医院出具的视力检查结果； （三）资格证书有效期内从事无损检验活动的工作记录和业绩情况。"},{"i":27,"n":"第二十七条","txt":"对资格证书有效期内无损检验活动工作记录和业绩良好的，由国务院核安全监管部门作出准予延续的决定，资格证书有效期延续5年。对资格证书有效期内从事无损检验活动不符合国务院核安全监管部门有关工作记录和业绩管理要求的，不予延续，需要重新申领资格证书。"},{"i":28,"n":"第二十八条","txt":"已取得国外相关资格证书的境外单位无损检验人员，需经国务院核安全监管部门核准后，方可在中华人民共和国境内从事无损检验活动。"},{"i":29,"n":"第二十九条","txt":"申请核准的境外单位无损检验人员，应当由聘用单位组织提交下列材料： （一）持有的资格证书； （二）相关核安全设备无损检验活动业绩； （三）未发生过责任事故、重大技术失误的书面说明材料； （四）境内无损检验活动需求材料。"},{"i":30,"n":"第三十条","txt":"聘用单位应当对申请人员相关申请材料进行核实，确保材料真实、准确，没有隐瞒。"},{"i":31,"n":"第三十一条","txt":"聘用单位应当对本单位无损检验人员进行培训和岗位管理，保证其按照民用核安全设备标准和技术要求从事无损检验活动。 鼓励聘用单位对Ⅱ级和Ⅲ级无损检验人员在职称评定、薪酬待遇、荣誉激励等方面给予政策倾斜。"},{"i":32,"n":"第三十二条","txt":"无损检验人员应当按照无损检验规程进行无损检验活动，遵守从业操守，提高知识技能，严格尽职履责。无损检验人员对其出具的无损检验结果负责。"},{"i":33,"n":"第三十三条","txt":"无损检验结果报告的编制和审核应当由取得相应资格证书的无损检验人员承担，并经其聘用单位批准后方为有效。"},{"i":34,"n":"第三十四条","txt":"无损检验人员超出资格证书范围从事无损检验活动的，其检验结果无效。"},{"i":35,"n":"第三十五条","txt":"无损检验人员一般应当固定在一个单位执业，确需在两个单位执业的，应当报国务院核安全监管部门备案。 无损检验人员变更聘用单位的，应当由其聘用单位向国务院核安全监管部门提出资格证书变更申请，经审查同意后更换新的资格证书。变更后的资格证书有效期适用原资格证书有效期，原资格证书失效。"},{"i":36,"n":"第三十六条","txt":"任何单位和个人不得伪造、变造或者买卖资格证书。"},{"i":37,"n":"第三十七条","txt":"考核单位应当建立健全考核管理制度，配备与拟从事的资格考核活动相适应的考核场所、档案室、检验设备和仪器，具有相应的专业技术人员和管理人员。 考核工作人员应当严格按照考核管理规定实施资格考核，保证考核的公正公平。"},{"i":38,"n":"第三十八条","txt":"考核单位应当建立并管理无损检验人员考试档案。考试档案的保存期限为10年。"},{"i":39,"n":"第三十九条","txt":"无损检验人员资格管理中相关违法信息由国务院核安全监管部门记入社会诚信档案，及时向社会公开。"},{"i":40,"n":"第四十条","txt":"对国务院核安全监管部门依法进行的监督检查，被检查单位和人员应当予以配合，如实反映情况，提供必要资料，不得拒绝和阻碍。"},{"i":41,"n":"第四十一条","txt":"无损检验人员违反相关法律法规和国家相关规定的，由国务院核安全监管部门根据情节严重程度依法分类予以处罚。"},{"i":42,"n":"第四十二条","txt":"申请人员隐瞒有关情况或者提供虚假材料的，国务院核安全监管部门不予受理或者不予许可，并给予警告；申请人员1年内不得再次申请资格考核。"},{"i":43,"n":"第四十三条","txt":"无损检验人员以欺骗、贿赂等不正当手段取得资格证书的，由国务院核安全监管部门撤销其资格证书，3年内不得再次申请资格考核；构成犯罪的，依法追究刑事责任。"},{"i":44,"n":"第四十四条","txt":"无损检验人员违反无损检验规程导致无损检验结果报告严重错误的，依据《民用核安全设备监督管理条例》的相关规定，由国务院核安全监管部门吊销其资格证书。"},{"i":45,"n":"第四十五条","txt":"伪造、变造或者买卖资格证书的，依据《中华人民共和国治安管理处罚法》的相关规定予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":46,"n":"第四十六条","txt":"聘用单位聘用未取得相应资格证书的无损检验人员从事无损检验活动的，依据《中华人民共和国核安全法》的相关规定，由国务院核安全监管部门责令改正，处10万元以上50万元以下的罚款；拒不改正的，暂扣或者吊销许可证，对直接负责的主管人员和其他直接责任人员处2万元以上10万元以下的罚款。"},{"i":47,"n":"第四十七条","txt":"考核工作人员有下列行为之一的，由国务院核安全监管部门依据有关法律法规和国家相关规定予以处理： （一）以不正当手段协助他人取得考试资格或者取得相应证书的； （二）泄露考务实施工作中应当保密的信息的； （三）在评阅卷工作中，擅自更改评分标准或者不按评分标准进行评卷的； （四）指使或者纵容他人作弊，或者参与考场内外串通作弊的； （五）其他严重违纪违规行为。"},{"i":48,"n":"第四十八条","txt":"资格考核的具体内容和评定标准由国务院核安全监管部门制定发布。"},{"i":49,"n":"第四十九条","txt":"考核单位不得开展影响资格考核公平、公正的培训活动，不得收取考试费用。"},{"i":50,"n":"第五十条","txt":"本规定自2020年1月1日起施行。2007年12月28日原国家环境保护总局和国防科学技术工业委员会联合发布的《民用核安全设备无损检验人员资格管理规定》（国家环境保护总局令第44号）同时废止。"}],"minyongheanquanshebeihanjierenyuanzigeguanliguidinf8d55c":[{"i":1,"n":"第一条","txt":"为了加强民用核安全设备焊接人员（以下简称焊接人员）的资格管理，保证民用核安全设备质量，根据《中华人民共和国核安全法》和《民用核安全设备监督管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于焊接人员的资格考核和管理工作。"},{"i":3,"n":"第三条","txt":"从事民用核安全设备焊接活动（以下简称焊接活动）的人员应当依据本规定取得资格证书。"},{"i":4,"n":"第四条","txt":"国务院核安全监管部门负责焊接人员的资格管理，统一组织资格考核，颁发资格证书，对焊接人员资格及相关资格考核活动进行监督检查。"},{"i":5,"n":"第五条","txt":"民用核安全设备制造、安装单位和民用核设施营运单位（以下简称聘用单位）应当聘用取得资格证书的人员开展焊接活动，对焊接人员进行岗位管理。"},{"i":6,"n":"第六条","txt":"本规定所称的焊接人员是指从事民用核安全设备焊接操作的焊工、焊接操作工；焊接方法是指焊接活动中的电弧焊（包括焊条电弧焊、钨极惰性气体保护电弧焊、熔化极气体保护电弧焊、埋弧焊等）和高能束焊（包括电子束焊、激光焊等）以及国务院核安全监管部门认可的其他焊接方法。"},{"i":7,"n":"第七条","txt":"申请《民用核安全设备焊接人员资格证》资格考核的人员应当具备下列条件： （一）身体健康，裸视或者矫正视力达到4.8及以上，辨色视力正常； （二）中等职业教育或者高中及以上学历，工作满1年； （三）熟练的焊接操作技能。"},{"i":8,"n":"第八条","txt":"有下列情形之一的人员，不得申请《民用核安全设备焊接人员资格证》资格考核： （一）被吊销资格证书的人员，自证书吊销之日起未满3年的； （二）依照本规定被给予不得申请资格考核处理的期限未满的。"},{"i":9,"n":"第九条","txt":"国务院核安全监管部门制定考试计划，组织承担考核工作的单位（以下简称考核单位）实施资格考核。 考核单位负责编制考试用焊接工艺规程，实施具体考试工作，检验考试试件，出具考试结果报告。"},{"i":10,"n":"第十条","txt":"申请人员由聘用单位组织报名参加资格考核，并提交下列材料： （一）申请表； （二）学历证明； （三）二级及以上医院出具的视力检查结果。"},{"i":11,"n":"第十一条","txt":"国务院核安全监管部门对提交的材料进行审核，自收到材料之日起5个工作日内确认申请人员考试资格。"},{"i":12,"n":"第十二条","txt":"首次参加资格考核的申请人员应当通过理论考试和相应焊接方法的操作考试。参加增加焊接方法资格考核的申请人员只需要进行相应焊接方法的操作考试。 理论考试主要考查申请人员对核设施系统基本知识，核安全设备及质量保证相关知识，核安全文化，焊接工艺、设备、材料等焊接基本知识的理解和掌握程度。 操作考试主要考查申请人员按照焊接工艺规程及过程质量控制要求熟练地焊接规定的试件并获得合格焊接接头的能力。"},{"i":13,"n":"第十三条","txt":"所有考试成绩均达到合格标准视为资格考核合格。 考试成绩未达到合格标准的，可在考试结束日的次日起1年内至多补考两次，补考仍未合格的，视为本次考核不合格。"},{"i":14,"n":"第十四条","txt":"国务院核安全监管部门收到考核单位的考试结果报告之日起20个工作日内完成审查，作出是否授予资格的决定。 资格证书由国务院核安全监管部门自授予资格决定之日起10个工作日内向合格的人员颁发。"},{"i":15,"n":"第十五条","txt":"资格证书包括下列主要内容： （一）人员姓名、身份证号及聘用单位； （二）焊接方法； （三）有效期限； （四）证书编号。"},{"i":16,"n":"第十六条","txt":"资格证书的有效期限为5年。"},{"i":17,"n":"第十七条","txt":"资格证书有效期届满拟继续从事焊接活动的人员，应当在证书有效期届满6个月前，由聘用单位组织向国务院核安全监管部门提出延续申请，并提交下列材料： （一）申请表； （二）二级及以上医院出具的视力检查结果； （三）资格证书有效期内从事焊接活动的工作记录和业绩情况。"},{"i":18,"n":"第十八条","txt":"对资格证书有效期内焊接活动工作记录和业绩良好的，由国务院核安全监管部门作出准予延续的决定，资格证书有效期延续5年。对资格证书有效期内从事焊接活动不符合国务院核安全监管部门有关工作记录和业绩管理要求的，不予延续，需要重新申领资格证书。"},{"i":19,"n":"第十九条","txt":"已取得国外相关资格证书的境外单位焊接人员，需经国务院核安全监管部门核准后，方可在中华人民共和国境内从事焊接活动。"},{"i":20,"n":"第二十条","txt":"申请核准的境外单位焊接人员，应当由聘用单位组织提交下列材料： （一）持有的资格证书； （二）相关核安全设备焊接活动业绩； （三）未发生过责任事故、重大技术失误的书面说明材料； （四）境内焊接活动需求材料。"},{"i":21,"n":"第二十一条","txt":"聘用单位应当对申请人员相关申请材料进行核实，确保材料真实、准确，没有隐瞒。"},{"i":22,"n":"第二十二条","txt":"聘用单位应当对本单位焊接人员进行培训和岗位管理，按照民用核安全设备标准和技术要求实施焊接人员技能评定，合格后进行授权，并做好焊接人员连续操作记录管理。"},{"i":23,"n":"第二十三条","txt":"焊接人员应当按照焊接工艺规程开展焊接活动，遵守从业操守，提高知识技能，严格尽职履责。"},{"i":24,"n":"第二十四条","txt":"焊接人员一般应当固定在一个单位执业，确需在两个单位执业的，应当报国务院核安全监管部门备案。 焊接人员变更聘用单位的，应当由其聘用单位向国务院核安全监管部门提出资格证书变更申请，经审查同意后更换新的资格证书。变更后的资格证书有效期适用原资格证书有效期，原资格证书失效。"},{"i":25,"n":"第二十五条","txt":"任何单位和个人不得伪造、变造或者买卖资格证书。"},{"i":26,"n":"第二十六条","txt":"考核单位应当建立健全考核管理制度，配备与拟从事的资格考核活动相适应的考核场所、档案室、焊接设备和仪器，具有相应的专业技术人员和管理人员。 考核工作人员应当严格按照考核管理规定实施资格考核，保证考核的公正公平。"},{"i":27,"n":"第二十七条","txt":"考核单位应当建立并管理焊接人员考试档案。考试档案的保存期限为10年。"},{"i":28,"n":"第二十八条","txt":"焊接人员资格管理中相关违法信息由国务院核安全监管部门记入社会诚信档案，及时向社会公开。"},{"i":29,"n":"第二十九条","txt":"对国务院核安全监管部门依法进行的监督检查，被检查单位和人员应当予以配合，如实反映情况，提供必要资料，不得拒绝和阻碍。"},{"i":30,"n":"第三十条","txt":"焊接人员违反相关法律法规和国家相关规定的，由国务院核安全监管部门根据情节严重程度依法分类予以处罚。"},{"i":31,"n":"第三十一条","txt":"申请人员隐瞒有关情况或者提供虚假材料的，国务院核安全监管部门不予受理或者不予许可，并给予警告；申请人员1年内不得再次申请资格考核。"},{"i":32,"n":"第三十二条","txt":"焊接人员以欺骗、贿赂等不正当手段取得资格证书的，由国务院核安全监管部门撤销其资格证书，3年内不得再次申请资格考核；构成犯罪的，依法追究刑事责任。"},{"i":33,"n":"第三十三条","txt":"焊接人员违反焊接工艺规程导致严重焊接质量问题的，依据《民用核安全设备监督管理条例》的相关规定，由国务院核安全监管部门吊销其资格证书。"},{"i":34,"n":"第三十四条","txt":"伪造、变造或者买卖资格证书的，依据《中华人民共和国治安管理处罚法》的相关规定予以处罚；构成犯罪的，依法追究刑事责任。"},{"i":35,"n":"第三十五条","txt":"聘用单位聘用未取得相应资格证书的焊接人员从事焊接活动的，依据《中华人民共和国核安全法》的相关规定，由国务院核安全监管部门责令改正，处10万元以上50万元以下的罚款；拒不改正的，暂扣或者吊销许可证，对直接负责的主管人员和其他直接责任人员处2万元以上10万元以下的罚款。"},{"i":36,"n":"第三十六条","txt":"考核工作人员有下列行为之一的，由国务院核安全监管部门依据有关法律法规和国家相关规定予以处理： （一）以不正当手段协助他人取得考试资格或者取得相应证书的； （二）泄露考务实施工作中应当保密的信息的； （三）在评阅卷工作中，擅自更改评分标准或者不按评分标准进行评卷的； （四）指使或者纵容他人作弊，或者参与考场内外串通作弊的； （五）其他严重违纪违规行为。"},{"i":37,"n":"第三十七条","txt":"资格考核的具体内容和评定标准由国务院核安全监管部门制定发布。"},{"i":38,"n":"第三十八条","txt":"考核单位不得开展影响资格考核公平、公正的培训活动，不得收取考试费用。"},{"i":39,"n":"第三十九条","txt":"本规定自2020年1月1日起施行。2007年12月28日原国家环境保护总局发布的《民用核安全设备焊工焊接操作工资格管理规定》（国家环境保护总局令第45号）同时废止。"}],"minyongheanquanshebeishejizhizaoanzhuanghewusunjia319e46":[{"i":1,"n":"第一条","txt":"为了加强对民用核安全设备设计、制造、安装和无损检验活动的监督管理，根据《民用核安全设备监督管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"从事民用核安全设备设计、制造、安装和无损检验活动的单位，应当遵守本规定。 运离民用核设施现场进行民用核安全设备维修活动的，应当遵守民用核安全设备制造活动的有关规定。"},{"i":3,"n":"第三条","txt":"民用核安全设备目录由国务院核安全监管部门商国务院有关部门分批制定并发布。"},{"i":4,"n":"第四条","txt":"从事民用核安全设备设计、制造、安装和无损检验活动的单位，应当取得民用核安全设备设计、制造、安装和无损检验许可证，并按照许可证规定的种类、范围和条件从事民用核安全设备设计、制造、安装和无损检验活动。"},{"i":5,"n":"第五条","txt":"民用核设施营运单位，应当对民用核安全设备设计、制造、安装和无损检验活动进行质量管理和过程控制，做好监造和验收工作；对在役的民用核安全设备进行检查、试验、检验和维修，并对民用核安全设备的使用和运行安全承担全面责任。"},{"i":6,"n":"第六条","txt":"国务院核安全监管部门对民用核安全设备设计、制造、安装和无损检验活动实施监督管理。"},{"i":7,"n":"第七条","txt":"申请领取民用核安全设备设计、制造或者安装许可证的单位，应当按照拟从事的活动种类、设备类别和核安全级别向国务院核安全监管部门提出申请。 申请领取民用核安全设备无损检验许可证的单位，应当按照无损检验方法向国务院核安全监管部门提出申请。无损检验方法包括射线检验（RT）、超声检验（UT）、磁粉检验（MT）、涡流检验（ET）、渗透检验（PT）、泄漏检验（LT）、目视检验（VT）等。"},{"i":8,"n":"第八条","txt":"申请领取民用核安全设备设计、制造、安装或者无损检验许可证的单位，应当具备下列条： （一）具有法人资格； （二）有与拟从事活动相关或者相近的工作业绩，并且满5年以上； （三）有与拟从事活动相适应的、经考核合格的专业技术人员，其中从事民用核安全设备焊接和无损检验活动的专业技术人员应当取得相应的资格证书； （四）有与拟从事活动相适应的工作场所、设施和装备； （五）有健全的管理制度和完善的质量保证体系，以及符合核安全监督管理规定的质量保证大纲。 对申请领取不同设备类别和核安全级别的民用核安全设备设计、制造、安装或者无损检验许可证的单位的具体技术要求，由国务院核安全监管部门规定。 申请领取民用核安全设备制造或者安装许可证的单位，应当根据其申请的设备类别、核安全级别、活动范围、制造和安装工艺、材料牌号、结构型式等制作具有代表性的模拟件。 模拟件制作的具体要求由国务院核安全监管部门规定。 同时申请领"},{"i":9,"n":"第九条","txt":"申请领取民用核安全设备设计、制造、安装或者无损检验许可证的单位，应当提交申请书和符合第八条规定条件的证明文件，具有法人资格的证明文件除外。 申请领取民用核安全设备制造或者安装许可证的单位，还应当提交模拟件制作方案和质量计划等材料。 同时申请领取民用核安全设备设计和制造许可证的单位，还应当提交鉴定试验大纲和必要的相关文件。"},{"i":10,"n":"第十条","txt":"国务院核安全监管部门对提交的申请文件进行形式审查，符合条件的，应当予以受理。"},{"i":11,"n":"第十一条","txt":"国务院核安全监管部门在审查过程中，应当组织专家进行技术评审，并征求国务院核行业主管部门和其他有关部门的意见。技术评审方式包括文件审查、审评对话和现场检查等。 对需要进行模拟件制作活动的，技术评审还应当包括对模拟件制作活动方案、质量计划等材料的审查，以及制作过程中的现场监督见证等。 国务院核安全监管部门应当自受理之日起45个工作日内完成审查，对符合条件的，颁发许可证，予以公告；对不符合条件的，书面通知申请单位并说明理由。 依据第一款、第二款规定组织进行技术评审的时间，不计算在第三款规定的期限内。"},{"i":12,"n":"第十二条","txt":"取得民用核安全设备设计、制造、安装或者无损检验许可证的单位，可以从事相同活动种类、相同设备类别、相同设备品种及范围内的较低核安全级别的相关活动，但许可证特别注明的除外。"},{"i":13,"n":"第十三条","txt":"民用核安全设备设计、制造、安装和无损检验许可证应当包括下列主要内容： （一）单位名称、住所和法定代表人； （二）准予从事的活动种类和范围； （三）有效期限； （四）发证机关、发证日期和证书编号。"},{"i":14,"n":"第十四条","txt":"禁止无许可证或者不按照许可证规定的活动种类和范围从事民用核安全设备设计、制造、安装和无损检验活动。 禁止委托未取得相应许可证的单位进行民用核安全设备设计、制造、安装和无损检验活动。 禁止伪造、变造、转让许可证。"},{"i":15,"n":"第十五条","txt":"民用核安全设备设计、制造、安装和无损检验许可证有效期限为5年。"},{"i":16,"n":"第十六条","txt":"民用核安全设备设计、制造、安装和无损检验单位有下列情形之一的，应当于许可证有效期届满6个月前，向国务院核安全监管部门提出延续申请，并提交延续申请书和延续申请文件： （一）持证期间有相应的民用核安全设备设计、制造、安装或者无损检验活动业绩，并拟在许可证有效期届满后继续从事相关活动的； （二）正在从事民用核安全设备设计、制造、安装或者无损检验活动，且在许可证有效期届满时尚不能结束的。 持证期间无民用核安全设备设计、制造、安装和无损检验活动业绩的，应当按照本章规定的程序重新申请领取许可证。"},{"i":17,"n":"第十七条","txt":"对民用核安全设备设计、制造、安装和无损检验单位提出的许可证延续申请，国务院核安全监管部门应当在许可证有效期届满前作出是否准予延续的决定；逾期未作决定的，视为准予延续。"},{"i":18,"n":"第十八条","txt":"民用核安全设备设计、制造、安装和无损检验单位变更单位名称、住所或者法定代表人的，应当自变更登记之日起20日内，向国务院核安全监管部门申请办理许可证变更手续，并提交变更申请、变更说明和相关变更证明材料。 国务院核安全监管部门应当对申请变更的情况进行核实。情况属实的，换发许可证。变更后的许可证有效期适用原许可证的有效期。"},{"i":19,"n":"第十九条","txt":"民用核安全设备设计、制造、安装和无损检验单位变更许可证规定的活动种类或者范围的，应当向国务院核安全监管部门重新提出申请。"},{"i":20,"n":"第二十条","txt":"民用核安全设备设计、制造、安装和无损检验单位，应当提高核安全意识，建立并有效实施质量保证体系，确保民用核安全设备的质量和可靠性，并接受民用核设施营运单位的检查。"},{"i":21,"n":"第二十一条","txt":"民用核安全设备设计、制造、安装和无损检验单位应当根据其质量保证大纲和民用核设施营运单位的要求，在民用核安全设备设计、制造、安装和无损检验活动开始前，编制项目质量保证分大纲。项目质量保证分大纲应当适用、完整、接口关系明确，并经民用核设施营运单位审查认可。 民用核安全设备制造和安装单位应当根据具体活动编制相应的质量计划，并经民用核设施营运单位审查认可。 民用核安全设备设计、制造、安装和无损检验单位应当按照项目质量保证分大纲的要求，对所有过程进行控制，并对发现的问题进行处理和纠正。"},{"i":22,"n":"第二十二条","txt":"民用核安全设备设计单位在设计活动开始前，应当组织相关设计人员对民用核设施营运单位提出的设计要求进行消化、分析，充分掌握设计输入要求，并予以明确；确定设计接口控制措施、设计验证方式和内容以及设计变更控制措施。 设计单位在设计的各个阶段，应当按照确定的设计验证方式对其设计进行设计验证。设计验证人员应当具有一定的设计经验、校核能力以及相对独立性。 设计单位在设计活动中，对设计变更应当采取与原设计相当的控制措施。 在设计工作完成后，设计单位应当为该设计的使用单位提供必要的设计服务。"},{"i":23,"n":"第二十三条","txt":"民用核安全设备制造、安装单位在活动开始前，应当组织相关人员对设计提出的技术要求进行消化、分析，编制制造、安装过程执行文件，并严格执行。 制造、安装单位应当根据确定的特种工艺，完成必要的工艺试验和工艺评定。 制造、安装单位应当严格执行经民用核设施营运单位审查认可的质量计划。 制造、安装单位应当对民用核安全设备的制造、安装质量进行检验。未经检验或者经检验不合格的，不得交付验收。"},{"i":24,"n":"第二十四条","txt":"民用核安全设备无损检验单位应当对所承担的具体检验项目，结合检验对象的结构型式、材料特性等，编制无损检验规程，并严格执行。 无损检验单位应当客观、准确地出具无损检验结果报告。 无损检验工作应当由民用核安全设备无损检验Ⅱ级或者Ⅱ级以上无损检验人员为主操作。 无损检验结果报告应当由Ⅱ级或者Ⅱ级以上无损检验人员编制、审核，并履行相关审批手续。"},{"i":25,"n":"第二十五条","txt":"民用核安全设备设计、制造、安装和无损检验单位，不得将国务院核安全监管部门确定的关键工艺环节分包给其他单位。 关键工艺清单由国务院核安全监管部门制定。"},{"i":26,"n":"第二十六条","txt":"民用核设施营运单位对民用核安全设备的安全运行负全面责任。在民用核安全设备设计、制造、安装和无损检验活动开始前，民用核设施营运单位应当对民用核安全设备设计、制造、安装和无损检验单位编制的项目质量保证分大纲进行审查认可。 在民用核安全设备设计、制造、安装和无损检验活动中，民用核设施营运单位应当采取驻厂监造或者见证等方式对过程进行监督，并做好验收工作。有下列情形之一的，不得验收通过： （一）不能按照质量保证要求证明质量受控的； （二）出现重大质量问题未处理完毕的。"},{"i":27,"n":"第二十七条","txt":"民用核安全设备制造、安装、无损检验单位和民用核设施营运单位，应当聘用取得民用核安全设备焊工、焊接操作工和无损检验人员资格证书的人员进行民用核安全设备焊接和无损检验活动。 民用核安全设备焊工、焊接操作工和无损检验人员，应当严格按照操作规程进行民用核安全设备焊接和无损检验活动。"},{"i":28,"n":"第二十八条","txt":"民用核安全设备设计单位，应当在设计活动开始30日前，将下列文件报国务院核安全监管部门备案： （一）项目设计质量保证分大纲和程序清单； （二）设计内容和设计进度计划； （三）设计遵循的标准和规范目录清单，设计中使用的计算机软件清单； （四）设计验证活动清单。"},{"i":29,"n":"第二十九条","txt":"民用核安全设备制造、安装单位，应当在制造、安装活动开始30日前，将下列文件报国务院核安全监管部门备案： （一）项目制造、安装质量保证分大纲和大纲程序清单； （二）制造、安装技术规格书； （三）分包项目清单； （四）制造、安装质量计划。"},{"i":30,"n":"第三十条","txt":"民用核安全设备无损检验单位，应当在无损检验活动开始15日前，将下列文件报国务院核安全监管部门备案： （一）项目无损检验质量保证分大纲和大纲程序清单； （二）无损检验活动内容和进度计划； （三）无损检验遵循的标准、规范、目录清单和验收准则。"},{"i":31,"n":"第三十一条","txt":"民用核安全设备设计单位，应当在每季度开始7个工作日内，向国务院核安全监管部门提交上一季度活动情况报告，主要内容包括： （一）已完成的设计活动清单，以及下一季度计划开始和拟完成的设计活动清单； （二）设计变更清单； （三）设计验证完成清单。"},{"i":32,"n":"第三十二条","txt":"民用核安全设备制造、安装单位，应当在每季度开始7个工作日内，向国务院核安全监管部门提交上一季度活动情况报告，主要内容包括： （一）已完成的制造、安装活动清单，以及下一季度计划开始和拟完成的活动清单； （二）已完成的制造、安装质量计划清单； （三）制造、安装活动不符合项统计表。"},{"i":33,"n":"第三十三条","txt":"民用核安全设备无损检验单位，应当在完成无损检验10个工作日内，向国务院核安全监管部门报告无损检验内容和检验结果。"},{"i":34,"n":"第三十四条","txt":"民用核安全设备设计、制造、安装和无损检验单位，应当按照下列规定向国务院核安全监管部门报告： （一）开展涉及核安全的重要会议、论证等活动的，提前7个工作日报告； （二）出现重大质量问题的，在24小时内报告； （三）因影响民用核安全设备质量和核安全而导致民用核设施营运单位发出停工指令的，在3个工作日内通报。"},{"i":35,"n":"第三十五条","txt":"民用核安全设备设计、制造、安装和无损检验单位，应当对所从事的民用核安全设备设计、制造、安装和无损检验活动进行年度评估，并于每年4月1日前向国务院核安全监管部门提交上一年度的评估报告。 评估报告应当包括下列内容： （一）本单位工作场所、设施、装备和人员等变动情况； （二）质量保证体系实施情况； （三）重大质量问题处理情况； （四）民用核设施营运单位提出的整改要求落实情况； （五）国务院核安全监管部门及其派出机构提出的整改要求落实情况。"},{"i":36,"n":"第三十六条","txt":"国务院核安全监管部门及其派出机构有权对民用核安全设备设计、制造、安装和无损检验活动进行监督检查。 被检查单位应当对国务院核安全监管部门及其派出机构进行的监督检查给予配合，如实反映情况，提供必要的资料，不得拒绝和阻碍。对于监督检查中提出的整改要求，被检查单位应当认真落实。"},{"i":37,"n":"第三十七条","txt":"民用核安全设备监督检查的依据是： （一）《民用核安全设备监督管理条例》以及其他核安全监督管理规定； （二）民用核安全设备设计、制造、安装或者无损检验许可证的条件和范围； （三）民用核安全设备国家标准、行业标准和经国务院核安全监管部门认可的标准； （四）经国务院核安全监管部门审查认可的质量保证大纲及大纲程序。"},{"i":38,"n":"第三十八条","txt":"民用核安全设备监督检查人员应当具备下列条件： （一）具有大专以上文化程度或者同等学力； （二）在民用核安全设备方面具有五年以上工程实践或者三年以上核安全管理经验，掌握有关的专业知识，具备良好的沟通能力，能独立做出正确的判断； （三）熟知相关法律、行政法规和核安全监督管理规定； （四）作风正派，办事公正，工作认真，态度端正。"},{"i":39,"n":"第三十九条","txt":"民用核安全设备监督检查的内容包括： （一）许可证条件遵守情况； （二）相关人员的资格； （三）质量保证大纲的实施情况； （四）采用的技术标准及有关技术文件的符合性； （五）民用核安全设备设计、制造、安装或者无损检验活动重要过程的实施情况； （六）重大质量问题的调查和处理，以及整改要求的落实情况； （七）民用核安全设备设计、制造、安装或者无损检验活动的验收和鉴定； （八）营运单位的监造情况； （九）其他必要的监督内容。"},{"i":40,"n":"第四十条","txt":"国务院核安全监管部门及其派出机构，接到民用核安全设备设计、制造、安装和无损检验单位依据本规定报送的文件后，应当制定相应的监督计划并书面通知报送单位。民用核安全设备设计、制造、安装和无损检验单位应当根据监督计划的要求，做好接受监督检查的准备。 民用核安全设备设计、制造、安装和无损检验单位，应当根据相关活动的实际进度，在监督计划确定的活动实施10个工作日前，书面通知国务院核安全监管部门及其派出机构。"},{"i":41,"n":"第四十一条","txt":"民用核安全设备监督检查分为例行检查和非例行检查。非例行检查可以不预先通知。 监督检查分为综合性检查、专项检查和检查点检查，主要通过现场检查、文件检查、记录确认或者对话等方式进行： （一）综合性检查：包括质量保证检查和技术检查，质量保证检查主要检查质量保证大纲是否得到有效实施。技术检查主要抽查民用核安全设备的设计、制造、安装和无损检验过程是否符合标准、规范和相关技术文件的要求。 （二）专项检查：指当发生问题或者认为可能有问题时，由国务院核安全监管部门及其派出机构对被检查单位进行的专项任务检查。主要包括对某一技术方面或者质量保证大纲某一要素的实施情况所进行的检查，以及核实提出的整改要求落实情况。 （三）检查点检查：指对检查点进行的现场实施情况检查。 必要时，国务院核安全监管部门及其派出机构可以进行独立验证，验证方式包括计算复核和检验验证。 国务院核安全监管部门及其派出机构，在对民用核安全设"},{"i":42,"n":"第四十二条","txt":"国务院核安全监管部门及其派出机构实施监督检查时，应当对每次检查的内容、发现的问题以及处理情况做出记录，并由监督检查人员和被检查单位的有关负责人签字确认。确有必要时，应当保留客观证据。 被检查单位的有关负责人拒绝签字的，监督检查人员应当将有关情况记录在案。 国务院核安全监管部门及其派出机构应当将每次监督检查的情况以及相应的管理要求形成监督检查报告，并发送被检查单位以及相关单位。 被检查单位应当针对监督检查中提出的问题，采取相应的整改措施，并将整改报告上报国务院核安全监管部门及其派出机构。国务院核安全监管部门及其派出机构应当对整改报告进行审查，并在后续的监督检查中对被整改要求的落实情况进行跟踪验证。"},{"i":43,"n":"第四十三条","txt":"民用核安全设备监督检查人员在进行监督检查时，有权采取下列措施： （一）向被检查单位的法定代表人和其他有关人员调查、了解情况； （二）进入被检查单位进行现场调查或者核查； （三）查阅、复制相关文件、记录以及其他有关资料； （四）要求被检查单位提交有关情况说明或者后续处理报告。 民用核安全设备监督检查人员在监督检查时，对于违反核安全监督管理规定、许可证条件和范围以及民用核安全设备标准而导致核安全隐患或者出现质量问题的行为，应当立即予以制止，并立即上报国务院核安全监管部门及其派出机构。 国务院核安全监管部门及其派出机构对有证据表明可能存在重大质量问题的民用核安全设备或者其主要部件，有权予以暂时封存。民用核安全设备或者其主要部件被暂时封存的，应当完成后续处理，并由国务院核安全监管部门及其派出机构验证符合要求后，方可启封。 在进行监督检查时，民用核安全设备监督检查人员不得少于两人，并出示证件。监"},{"i":44,"n":"第四十四条","txt":"国务院核安全监管部门及其派出机构对民用核安全设备设计、制造、安装和无损检验活动实施的监督检查不减轻也不转移被检查单位对所从事的相关活动应当承担的责任。"},{"i":45,"n":"第四十五条","txt":"民用核安全设备设计、制造、安装和无损检验单位有下列行为之一的，由国务院核安全监管部门限期改正；逾期不改正的，处1万元以上3万元以下的罚款： （一）在民用核安全设备无损检验活动开始前，未按规定将有关文件报国务院核安全监管部门备案的； （二）未按规定向国务院核安全监管部门报告上一季度民用核安全设备设计、制造、安装或者无损检验情况的； （三）在民用核安全设备无损检验活动完成后，未向国务院核安全监管部门报告无损检验内容和检验结果的； （四）开展涉及核安全的重要会议、论证等活动，出现重大质量问题，或者因影响民用核安全设备质量和核安全而导致民用核设施营运单位发出停工指令，未向国务院核安全监管部门报告的。"},{"i":46,"n":"第四十六条","txt":"民用核安全设备设计、制造、安装和无损检验单位以及民用核设施营运单位，有其他违反本规定行为的，依据《民用核安全设备监督管理条例》及其他相关法律法规进行处罚。"},{"i":47,"n":"第四十七条","txt":"申请领取民用核安全设备制造或者安装许可证的单位，拟自行对其制造或者安装的民用核安全设备进行无损检验活动的，不需要单独申请领取无损检验许可证。"},{"i":48,"n":"第四十八条","txt":"本规定中有关术语的含义如下： （一）模拟件：指国务院核安全监管部门在审查民用核安全设备制造、安装许可证申请时，要求有关申请单位针对申请的目标产品，按照1：1或者适当比例制作的与目标产品在材料、结构型式、性能特点等方面相同或者相近的制品。该制品必须经历与目标产品或者样机一致的制作工序以及检验、鉴定试验过程等。 （二）鉴定试验：指在设计过程中，为了保证设计满足预先设定的设计性能指标而对模拟件（或者样机）实施的实物验证试验。鉴定试验包括功能试验、抗震试验和环境试验（包括老化试验和设计基准事故工况试验）等。 （三）检查点：指国务院核安全监管部门及其派出机构，根据民用核安全设备设计、制造、安装和无损检验单位报送文件，所选择的需检查的某一工作过程或者工作节点。根据检查方式的不同，检查点一般分记录确认点（R点）、现场见证点（W点）、停工待检点（H点）等三类。"},{"i":49,"n":"第四十九条","txt":"本规定自2008年1月1日起施行。1992年3月4日国家核安全局、机械电子工业部、能源部发布的《民用核承压设备安全监督管理规定（HAF601）》同时废止。"}],"minyongheranliaoxunhuansheshianquanguiding":[],"minyonghesheshicaozuorenyuanzigeguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强民用核设施（以下简称核设施）操作人员的资格管理，根据《中华人民共和国核安全法》《中华人民共和国民用核设施安全监督管理条例》等有关法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于下列核设施操作人员（以下简称操作人员）的执照申请、培训、考核、颁发，以及相关监督管理工作： （一）核电厂、核热电厂、核供汽供热厂等核动力厂及装置（以下统称核动力厂）； （二）核动力厂以外的研究堆、实验堆、临界装置等其他反应堆（以下统称研究堆）； （三）核燃料后处理生产设施（以下统称后处理设施）。 本规定所称操作人员，是指《中华人民共和国核安全法》《中华人民共和国民用核设施安全监督管理条例》等法律法规规定的核设施操纵人员或者核设施操纵员，即在核设施主控室中担任操作或者指导他人操作核设施控制系统工作的运行值班人员。"},{"i":3,"n":"第三条","txt":"操作人员应当按照本规定申请《操作员执照》或者《高级操作员执照》（以下统称执照）。 持有《操作员执照》的人员方可担任操作核设施控制系统的工作；持有《高级操作员执照》的人员方可担任操作或者指导他人操作核设施控制系统的工作。 申请执照人员，需要使用核设施控制系统进行操作培训的，应当取得核设施营运单位临时授权并在操作人员监护下方可进行。核设施营运单位和进行监护的操作人员对上述培训人员的活动负责。"},{"i":4,"n":"第四条","txt":"国务院核安全监督管理部门负责批准颁发执照，组织研究堆和后处理设施操作人员执照培训和考核，对操作人员资格有关工作进行监督管理。 国务院能源主管部门负责组织核动力厂操作人员执照培训和考核。"},{"i":5,"n":"第五条","txt":"对核设施营运单位实施控股管理的企业集团（以下简称企业集团）应当承担或者委托有能力的核设施营运单位承担执照申请、培训和考核工作。 无前款所称企业集团的核设施营运单位具备能力的，可以自行承担前款相关工作；没有能力的，应当委托有能力的单位承担。"},{"i":6,"n":"第六条","txt":"核设施营运单位应当聘用取得执照的人员从事核设施操作工作，加强岗位管理。"},{"i":7,"n":"第七条","txt":"申请《操作员执照》的人员应当具备下列条件： （一）身体健康； （二）具有中专及以上文化程度，其中核动力厂操作人员应当具有大专及以上文化程度； （三）经过培训，且考核合格。"},{"i":8,"n":"第八条","txt":"申请《高级操作员执照》的人员应当具备下列条件： （一）身体健康； （二）具有大专及以上文化程度； （三）经过培训，且考核合格； （四）担任操作员两年以上，且成绩优秀。 申请核动力厂《高级操作员执照》的人员,前款第四项规定的成绩优秀应当包括担任操作员两年内参加运行值班至少一千六百小时的条件。"},{"i":9,"n":"第九条","txt":"申请研究堆和后处理设施执照的人员，由承担执照申请工作的单位组织向国务院核安全监督管理部门提交申请材料。 申请核动力厂执照的人员，应当先参加国务院能源主管部门组织的执照培训和考核，并通过国务院能源主管部门审查后，由承担执照申请工作的单位组织向国务院核安全监督管理部门提交申请材料。"},{"i":10,"n":"第十条","txt":"申请材料应当通过全国一体化在线政务服务平台生态环境部政务服务大厅（网址：http://zwfw.mee.gov.cn，以下简称政务服务大厅）或者邮寄、当面递交等方式提交，包括下列内容： （一）申请表； （二）学历证明； （三）健康检查结果； （四）培训和考核情况。 申请核动力厂执照的，还应当提交国务院能源主管部门的审查意见；申请《高级操作员执照》的，还应当提交成绩证明材料。 申请材料应当真实、准确、完整。"},{"i":11,"n":"第十一条","txt":"国务院核安全监督管理部门对收到的申请材料进行审查。 申请材料不齐全或者不符合法定形式的，应当在五个工作日内一次告知需要补正的全部内容；逾期不告知的，自收到申请材料之日起即视为受理。 申请材料齐全、符合法定形式，或者按照要求提交全部补正申请材料的，应当在五个工作日内受理申请。"},{"i":12,"n":"第十二条","txt":"国务院核安全监督管理部门组织对受理的申请进行技术审查。 技术审查应当委托与承担执照申请工作的单位没有利益关系的技术支持单位进行。受委托的技术支持单位应当对其审查意见的真实性、准确性负责。 技术审查过程中，国务院核安全监督管理部门或者受委托的技术支持单位可以根据需要要求提交必要的支持性材料。"},{"i":13,"n":"第十三条","txt":"国务院核安全监督管理部门在技术审查完成之日起二十日内作出是否批准颁发执照的决定。执照包括下列内容： （一）持照人员身份信息； （二）所在核设施营运单位； （三）执照种类； （四）核设施名称； （五）执照有效期； （六）执照编号。"},{"i":14,"n":"第十四条","txt":"执照有效期为五年。 执照有效期届满拟继续从事核设施操作工作的人员，应当在执照有效期届满三个月前申请延续执照。"},{"i":15,"n":"第十五条","txt":"延续申请材料应当通过政务服务大厅或者邮寄、当面递交等方式提交，包括下列内容： （一）延续申请表； （二）执照有效期内健康检查结果； （三）再培训和延续考核情况。 申请延续核动力厂执照的，还应当提交国务院能源主管部门的审查意见。"},{"i":16,"n":"第十六条","txt":"国务院核安全监督管理部门应当自受理延续申请之日起，在执照有效期届满前完成审查，符合条件的予以延续，换发新执照；不符合条件的，不予延续。"},{"i":17,"n":"第十七条","txt":"执照有效期内拟转至执照载明的核设施以外的其他核设施继续从事核设施操作工作的人员，应当在执照有效期内申请变更执照。"},{"i":18,"n":"第十八条","txt":"变更申请材料应当通过政务服务大厅或者邮寄、当面递交等方式提交，包括下列内容： （一）变更申请表； （二）执照有效期内健康检查结果； （三）差异性培训和变更考核情况。 申请变更核动力厂执照的，还应当提交国务院能源主管部门的审查意见。 国务院核安全监督管理部门应当及时进行审查，符合条件的予以变更，换发新执照；不符合条件的，不予变更。"},{"i":19,"n":"第十九条","txt":"有下列情形之一的人员，不得申请执照： （一）被吊销执照的人员，自执照吊销之日起未满三年的； （二）按照本规定第三十八条、第三十九条的规定，受到不得申请执照的处理，期限尚未届满的。"},{"i":20,"n":"第二十条","txt":"申请执照的人员应当按照本规定的要求完成培训并通过申请考核。 前款所指申请考核包括笔试、口试和操作考试。"},{"i":21,"n":"第二十一条","txt":"申请《操作员执照》的人员应当培训和考核下列知识技能： （一）核设施的基础理论、系统设备、辐射防护等相关知识； （二）核设施的运行技术规格书等操作知识； （三）操作核设施控制系统的能力。"},{"i":22,"n":"第二十二条","txt":"申请《高级操作员执照》的人员应当培训和考核下列知识技能： （一）本规定第二十一条规定的知识技能； （二）核设施运行管理知识； （三）指导他人操作核设施控制系统的能力。"},{"i":23,"n":"第二十三条","txt":"申请延续执照的人员应当完成规定的再培训并通过延续考核，保持应当具备的知识技能并掌握核设施经验反馈、技术变更等情况。 申请延续执照的人员，执照有效期内工作成绩符合规定的，可以免予笔试，仅参加口试和操作考试；其中核动力厂操作人员的工作成绩中应当包括参加运行值班至少两千小时的条件。"},{"i":24,"n":"第二十四条","txt":"申请变更执照的人员应当根据拟转至核设施与原所在核设施对操作人员知识技能要求的差异，完成规定的差异性培训并通过变更考核。变更考核包括差异性笔试、口试和操作考试。 无法实施差异性培训和变更考核的，应当重新申请执照。"},{"i":25,"n":"第二十五条","txt":"操作人员培训应当按照培训大纲实施，兼顾理论知识与实际操作,注重安全文化和行为规范的培育。 培训大纲由承担培训工作的单位制定，包括培训组织分工、培训内容设置、培训管理评价以及培训资源保障等内容。 核动力厂培训大纲应当由国务院能源主管部门审定。研究堆和后处理设施培训大纲应当由国务院核安全监督管理部门审定。"},{"i":26,"n":"第二十六条","txt":"操作人员考核应当按照考核标准实施。 核动力厂操作人员考核标准由国务院能源主管部门制定，国务院核安全监督管理部门核准。研究堆、后处理设施考核标准由国务院核安全监督管理部门制定。 考核标准应当包括参加考核人员应当具备的条件、考评组织组成原则、考题编制要求、考核评定准则和合格标准等内容。"},{"i":27,"n":"第二十七条","txt":"申请、延续或者变更执照的人员所参加的笔试、口试和操作考试成绩均达到合格标准的，属于考核合格。"},{"i":28,"n":"第二十八条","txt":"操作人员资格管理有关责任单位应当明确责任部门，合理配置资源，建立并有效实施相关管理制度，严格落实有关要求。 各责任单位主要负责人应当加强对有关责任部门和人员履职情况的督促检查，切实履行管理责任。"},{"i":29,"n":"第二十九条","txt":"操作人员岗位配置应当满足安全运行需要，并在核设施营运单位提交给国务院核安全监督管理部门的最终安全分析报告中予以明确。"},{"i":30,"n":"第三十条","txt":"核设施运行值班负责人应当由具备相关工作经历、成绩优秀的操作人员担任。 核动力厂、I类和Ⅱ类研究堆、后处理设施的运行值班负责人应当具有两个以上操作人员岗位工作的经历，且持有《高级操作员执照》。"},{"i":31,"n":"第三十一条","txt":"核设施营运单位应当明确负责核设施运行管理的部门（以下简称运行部门）。 核动力厂、I类和Ⅱ类研究堆、后处理设施运行部门的主要负责人和分管运行的负责人应当具有担任运行值班负责人的经历，且至少一人持有所在核设施《高级操作员执照》。持有《高级操作员执照》的核动力厂运行部门负责人，运行值班应当同时满足下列条件： （一）每十二个月参加运行值班至少一百小时； （二）执照有效期内执行或者指导过启动、升降功率、换料运行等重要工作。 Ⅲ类研究堆运行部门的负责人中应当至少有一人持有《操作员执照》或者《高级操作员执照》。"},{"i":32,"n":"第三十二条","txt":"核设施营运单位应当严格操作人员岗位管理，明确岗位职责和任职要求，对操作人员进行岗位授权，合理安排运行值班、培训；对身体健康状况、参加培训情况、运行值班情况等不满足规定要求的操作人员，应当取消其岗位授权。 核动力厂操作人员的运行值班应当同时满足下列条件： （一）每十二个月参加运行值班至少四百小时； （二）每六个月参加运行值班至少一百五十小时。 不能同时满足前款规定条件的，核设施营运单位应当取消操作人员岗位授权。"},{"i":33,"n":"第三十三条","txt":"取消岗位授权的操作人员拟重新参加运行值班的，核设施营运单位应当安排必要的补充培训、岗位实践等，经评估合格后方可重新授权。"},{"i":34,"n":"第三十四条","txt":"操作人员应当遵守职业操守和行为规范，杜绝违规操作和弄虚作假，提高知识技能，严格尽职履责。 操作人员存在因饮酒、使用药物等可能影响履行岗位职责情形的，应当及时向所在核设施营运单位报告。核设施营运单位应当根据情况确定该操作人员是否可以参加运行值班。"},{"i":35,"n":"第三十五条","txt":"国务院核安全监督管理部门对操作人员资格管理有关工作进行监督检查。监督检查主要围绕以下事项开展： （一）培训大纲、培训计划、培训实施等培训管理情况； （二）考评组织、考核试题、考核实施、考核结果等考核管理情况； （三）人员配置、授权管理、运行值班等岗位管理情况。 监督检查主要通过文件审查、现场检查、记录确认或者谈话等方式进行，必要时可以抽查复验。"},{"i":36,"n":"第三十六条","txt":"对国务院核安全监督管理部门依法进行的监督检查，被检查单位和人员应当予以配合，如实反映情况，提供必要资料，不得拒绝和阻挠。"},{"i":37,"n":"第三十七条","txt":"操作人员有下列情形之一的，国务院核安全监督管理部门应当依法办理执照注销手续： （一）因身体健康等原因无法继续满足执照申请条件的； （二）执照依法被撤销、吊销的； （三）法律、行政法规规定的应当注销执照的其他情形。"},{"i":38,"n":"第三十八条","txt":"申请执照的人员隐瞒有关情况或者提供虚假材料的，国务院核安全监督管理部门依据《中华人民共和国行政许可法》的有关规定不予受理或者不予许可，并给予警告；被警告人员一年内不得再次申请。"},{"i":39,"n":"第三十九条","txt":"申请执照的人员以欺骗、贿赂等不正当手段取得执照的，由国务院核安全监督管理部门依据《中华人民共和国行政许可法》的有关规定撤销其执照，三年内不得再次申请。"},{"i":40,"n":"第四十条","txt":"操作人员有下列情形之一的，属于《中华人民共和国民用核设施安全监督管理条例》第二十一条第三项规定的“违章操纵”，国务院核安全监督管理部门应当依法予以处罚： （一）操作人员不符合核安全法律法规和本规定的条件的； （二）未按照规定程序操作导致后果的，或者虽未导致后果但在工作中未按照程序操作两次以上的； （三）超出执照范围从事核设施操作工作的。"},{"i":41,"n":"第四十一条","txt":"操作人员资格管理有关责任单位有下列情形之一的，由国务院核安全监督管理部门责令改正，给予警告，并可以处三万元以下的罚款： （一）执照申请过程中存在弄虚作假，谎报有关资料、事实等行为的； （二）未按有关规定对操作人员进行岗位授权或者取消岗位授权，或者隐瞒操作人员违章操作的。"},{"i":42,"n":"第四十二条","txt":"核设施营运单位聘用未取得《操作员执照》或者《高级操作员执照》的人员从事核设施操作工作的，依据《中华人民共和国核安全法》的相关规定予以处罚。 对国务院核安全监督管理部门或者其他有关部门依法进行的监督检查，企业集团或者核设施营运单位拒绝、阻挠的，依据《中华人民共和国核安全法》的相关规定予以处罚。"},{"i":43,"n":"第四十三条","txt":"操作人员考核工作人员有下列情形之一的，由国务院核安全监督管理部门、国务院能源主管部门按照职责分工，依据国家有关专业技术人员资格考试违纪违规处理规定，予以处理： （一）以不正当手段协助他人取得考核资格或者取得执照的； （二）泄露考务实施工作中应当保密的信息的； （三）在评阅卷工作中，擅自更改评分标准或者不按评分标准进行评卷的； （四）指使或者纵容他人作弊，或者参与考场内外串通作弊的； （五）其他严重违纪违规行为。"},{"i":44,"n":"第四十四条","txt":"本规定中下列用语的含义： （一）核设施控制系统，对于核动力厂和研究堆，是指影响反应堆反应性或者功率水平，或者影响专设安全设施状态的控制设备和装置；对于后处理设施，是指影响核设施物理、化学或者核过程的控制设备和装置。 （二）身体健康，是指体能、感知、表达和情绪等各方面能够满足从事核设施操作工作需要，不存在可能影响履行职责的健康问题，包括但不限于神经系统、心血管系统、内分泌系统、听觉、视觉、精神疾病或者缺陷。健康检查的具体判定由具备条件的医疗机构按照国家有关医学标准实施。"},{"i":45,"n":"第四十五条","txt":"本规定自2021年7月1日起施行。1993年12月31日国家核安全局发布的《核电厂操纵人员执照颁发和管理程序》同时废止。"}],"wurandikuaituranghuanjingguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强污染地块环境保护监督管理，防控污染地块环境风险，根据《中华人民共和国环境保护法》等法律法规和国务院发布的《土壤污染防治行动计划》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称疑似污染地块，是指从事过有色金属冶炼、石油加工、化工、焦化、电镀、制革等行业生产经营活动，以及从事过危险废物贮存、利用、处置活动的用地。 按照国家技术规范确认超过有关土壤环境标准的疑似污染地块，称为污染地块。 本办法所称疑似污染地块和污染地块相关活动，是指对疑似污染地块开展的土壤环境初步调查活动，以及对污染地块开展的土壤环境详细调查、风险评估、风险管控、治理与修复及其效果评估等活动。"},{"i":3,"n":"第三条","txt":"拟收回土地使用权的，已收回土地使用权的，以及用途拟变更为居住用地和商业、学校、医疗、养老机构等公共设施用地的疑似污染地块和污染地块相关活动及其环境保护监督管理，适用本办法。 不具备本条第一款情形的疑似污染地块和污染地块土壤环境管理办法另行制定。 放射性污染地块环境保护监督管理，不适用本办法。"},{"i":4,"n":"第四条","txt":"环境保护部对全国土壤环境保护工作实施统一监督管理。 地方各级环境保护主管部门负责本行政区域内的疑似污染地块和污染地块相关活动的监督管理。 按照国家有关规定，县级环境保护主管部门被调整为设区的市级环境保护主管部门派出分局的，由设区的市级环境保护主管部门组织所属派出分局开展疑似污染地块和污染地块相关活动的监督管理。"},{"i":5,"n":"第五条","txt":"环境保护部制定疑似污染地块和污染地块相关活动方面的环境标准和技术规范。"},{"i":6,"n":"第六条","txt":"环境保护部组织建立全国污染地块土壤环境管理信息系统（以下简称污染地块信息系统）。 县级以上地方环境保护主管部门按照环境保护部的规定，在本行政区域内组织建设和应用污染地块信息系统。 疑似污染地块和污染地块的土地使用权人应当按照环境保护部的规定，通过污染地块信息系统，在线填报并提交疑似污染地块和污染地块相关活动信息。 县级以上环境保护主管部门应当通过污染地块信息系统，与同级城乡规划、国土资源等部门实现信息共享。"},{"i":7,"n":"第七条","txt":"任何单位或者个人有权向环境保护主管部门举报未按照本办法规定开展疑似污染地块和污染地块相关活动的行为。"},{"i":8,"n":"第八条","txt":"环境保护主管部门鼓励和支持社会组织，对造成土壤污染、损害社会公共利益的行为，依法提起环境公益诉讼。"},{"i":9,"n":"第九条","txt":"土地使用权人应当按照本办法的规定，负责开展疑似污染地块和污染地块相关活动，并对上述活动的结果负责。"},{"i":10,"n":"第十条","txt":"按照“谁污染，谁治理”原则，造成土壤污染的单位或者个人应当承担治理与修复的主体责任。 责任主体发生变更的，由变更后继承其债权、债务的单位或者个人承担相关责任。 责任主体灭失或者责任主体不明确的，由所在地县级人民政府依法承担相关责任。 土地使用权依法转让的，由土地使用权受让人或者双方约定的责任人承担相关责任。 土地使用权终止的，由原土地使用权人对其使用该地块期间所造成的土壤污染承担相关责任。 土壤污染治理与修复实行终身责任制。"},{"i":11,"n":"第十一条","txt":"受委托从事疑似污染地块和污染地块相关活动的专业机构，或者受委托从事治理与修复效果评估的第三方机构，应当遵守有关环境标准和技术规范，并对相关活动的调查报告、评估报告的真实性、准确性、完整性负责。 受委托从事风险管控、治理与修复的专业机构，应当遵守国家有关环境标准和技术规范，按照委托合同的约定，对风险管控、治理与修复的效果承担相应责任。 受委托从事风险管控、治理与修复的专业机构，在风险管控、治理与修复等活动中弄虚作假，造成环境污染和生态破坏，除依照有关法律法规接受处罚外，还应当依法与造成环境污染和生态破坏的其他责任者承担连带责任。"},{"i":12,"n":"第十二条","txt":"县级环境保护主管部门应当根据国家有关保障工业企业场地再开发利用环境安全的规定，会同工业和信息化、城乡规划、国土资源等部门，建立本行政区域疑似污染地块名单，并及时上传污染地块信息系统。 疑似污染地块名单实行动态更新。"},{"i":13,"n":"第十三条","txt":"对列入疑似污染地块名单的地块，所在地县级环境保护主管部门应当书面通知土地使用权人。 土地使用权人应当自接到书面通知之日起六个月内完成土壤环境初步调查，编制调查报告，及时上传污染地块信息系统，并将调查报告主要内容通过其网站等便于公众知晓的方式向社会公开。 土壤环境初步调查应当按照国家有关环境标准和技术规范开展，调查报告应当包括地块基本信息、疑似污染地块是否为污染地块的明确结论等主要内容，并附具采样信息和检测报告。"},{"i":14,"n":"第十四条","txt":"设区的市级环境保护主管部门根据土地使用权人提交的土壤环境初步调查报告建立污染地块名录，及时上传污染地块信息系统，同时向社会公开，并通报各污染地块所在地县级人民政府。 对列入名录的污染地块，设区的市级环境保护主管部门应当按照国家有关环境标准和技术规范，确定该污染地块的风险等级。 污染地块名录实行动态更新。"},{"i":15,"n":"第十五条","txt":"县级以上地方环境保护主管部门应当对本行政区域具有高风险的污染地块，优先开展环境保护监督管理。"},{"i":16,"n":"第十六条","txt":"对列入污染地块名录的地块，设区的市级环境保护主管部门应当书面通知土地使用权人。 土地使用权人应当在接到书面通知后，按照国家有关环境标准和技术规范，开展土壤环境详细调查，编制调查报告，及时上传污染地块信息系统，并将调查报告主要内容通过其网站等便于公众知晓的方式向社会公开。 土壤环境详细调查报告应当包括地块基本信息,土壤污染物的分布状况及其范围,以及对土壤、地表水、地下水、空气污染的影响情况等主要内容，并附具采样信息和检测报告。"},{"i":17,"n":"第十七条","txt":"土地使用权人应当按照国家有关环境标准和技术规范，在污染地块土壤环境详细调查的基础上开展风险评估，编制风险评估报告，及时上传污染地块信息系统，并将评估报告主要内容通过其网站等便于公众知晓的方式向社会公开。 风险评估报告应当包括地块基本信息、应当关注的污染物、主要暴露途径、风险水平、风险管控以及治理与修复建议等主要内容。"},{"i":18,"n":"第十八条","txt":"污染地块土地使用权人应当根据风险评估结果，并结合污染地块相关开发利用计划，有针对性地实施风险管控。 对暂不开发利用的污染地块，实施以防止污染扩散为目的的风险管控。 对拟开发利用为居住用地和商业、学校、医疗、养老机构等公共设施用地的污染地块，实施以安全利用为目的的风险管控。"},{"i":19,"n":"第十九条","txt":"污染地块土地使用权人应当按照国家有关环境标准和技术规范，编制风险管控方案，及时上传污染地块信息系统，同时抄送所在地县级人民政府，并将方案主要内容通过其网站等便于公众知晓的方式向社会公开。 风险管控方案应当包括管控区域、目标、主要措施、环境监测计划以及应急措施等内容。"},{"i":20,"n":"第二十条","txt":"土地使用权人应当按照风险管控方案要求，采取以下主要措施： （一）及时移除或者清理污染源； （二）采取污染隔离、阻断等措施，防止污染扩散； （三）开展土壤、地表水、地下水、空气环境监测； （四）发现污染扩散的，及时采取有效补救措施。"},{"i":21,"n":"第二十一条","txt":"因采取风险管控措施不当等原因，造成污染地块周边的土壤、地表水、地下水或者空气污染等突发环境事件的，土地使用权人应当及时采取环境应急措施，并向所在地县级以上环境保护主管部门和其他有关部门报告。"},{"i":22,"n":"第二十二条","txt":"对暂不开发利用的污染地块，由所在地县级环境保护主管部门配合有关部门提出划定管控区域的建议，报同级人民政府批准后设立标识、发布公告，并组织开展土壤、地表水、地下水、空气环境监测。"},{"i":23,"n":"第二十三条","txt":"对拟开发利用为居住用地和商业、学校、医疗、养老机构等公共设施用地的污染地块，经风险评估确认需要治理与修复的，土地使用权人应当开展治理与修复。"},{"i":24,"n":"第二十四条","txt":"对需要开展治理与修复的污染地块，土地使用权人应当根据土壤环境详细调查报告、风险评估报告等，按照国家有关环境标准和技术规范，编制污染地块治理与修复工程方案，并及时上传污染地块信息系统。 土地使用权人应当在工程实施期间，将治理与修复工程方案的主要内容通过其网站等便于公众知晓的方式向社会公开。 工程方案应当包括治理与修复范围和目标、技术路线和工艺参数、二次污染防范措施等内容。"},{"i":25,"n":"第二十五条","txt":"污染地块治理与修复期间，土地使用权人或者其委托的专业机构应当采取措施，防止对地块及其周边环境造成二次污染；治理与修复过程中产生的废水、废气和固体废物，应当按照国家有关规定进行处理或者处置，并达到国家或者地方规定的环境标准和要求。 治理与修复工程原则上应当在原址进行；确需转运污染土壤的，土地使用权人或者其委托的专业机构应当将运输时间、方式、线路和污染土壤数量、去向、最终处置措施等，提前五个工作日向所在地和接收地设区的市级环境保护主管部门报告。 修复后的土壤再利用应当符合国家或者地方有关规定和标准要求。 治理与修复期间，土地使用权人或者其委托的专业机构应当设立公告牌和警示标识，公开工程基本情况、环境影响及其防范措施等。"},{"i":26,"n":"第二十六条","txt":"治理与修复工程完工后，土地使用权人应当委托第三方机构按照国家有关环境标准和技术规范，开展治理与修复效果评估，编制治理与修复效果评估报告，及时上传污染地块信息系统，并通过其网站等便于公众知晓的方式公开，公开时间不得少于两个月。 治理与修复效果评估报告应当包括治理与修复工程概况、环境保护措施落实情况、治理与修复效果监测结果、评估结论及后续监测建议等内容。"},{"i":27,"n":"第二十七条","txt":"污染地块未经治理与修复，或者经治理与修复但未达到相关规划用地土壤环境质量要求的，有关环境保护主管部门不予批准选址涉及该污染地块的建设项目环境影响报告书或者报告表。"},{"i":28,"n":"第二十八条","txt":"县级以上环境保护主管部门应当会同城乡规划、国土资源等部门，建立和完善污染地块信息沟通机制，对污染地块的开发利用实行联动监管。 污染地块经治理与修复，并符合相应规划用地土壤环境质量要求后，可以进入用地程序。"},{"i":29,"n":"第二十九条","txt":"县级以上环境保护主管部门及其委托的环境监察机构，有权对本行政区域内的疑似污染地块和污染地块相关活动进行现场检查。被检查单位应当予以配合，如实反映情况，提供必要的资料。实施现场检查的部门、机构及其工作人员应当为被检查单位保守商业秘密。"},{"i":30,"n":"第三十条","txt":"县级以上环境保护主管部门对疑似污染地块和污染地块相关活动进行监督检查时，有权采取下列措施： （一）向被检查单位调查、了解疑似污染地块和污染地块的有关情况； （二）进入被检查单位进行现场核查或者监测； （三）查阅、复制相关文件、记录以及其他有关资料； （四）要求被检查单位提交有关情况说明。"},{"i":31,"n":"第三十一条","txt":"设区的市级环境保护主管部门应当于每年的12月31日前，将本年度本行政区域的污染地块环境管理工作情况报省级环境保护主管部门。 省级环境保护主管部门应当于每年的1月31日前，将上一年度本行政区域的污染地块环境管理工作情况报环境保护部。"},{"i":32,"n":"第三十二条","txt":"违反本办法规定，受委托的专业机构在编制土壤环境初步调查报告、土壤环境详细调查报告、风险评估报告、风险管控方案、治理与修复方案过程中，或者受委托的第三方机构在编制治理与修复效果评估报告过程中，不负责任或者弄虚作假致使报告失实的，由县级以上环境保护主管部门将该机构失信情况记入其环境信用记录，并通过企业信用信息公示系统向社会公开。"},{"i":33,"n":"第三十三条","txt":"本办法自2017年7月1日起施行。"}],"wuranyuanzidongjiankongguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强污染源监管，实施污染物排放总量控制与排污许可证制度和排污收费制度，预防污染事故，提高环境管理科学化、信息化水平，根据《水污染防治法》、《大气污染防治法》、《环境噪声污染防治法》、《水污染防治法实施细则》、《建设项目环境保护管理条例》和《排污费征收使用管理条例》等有关环境保护法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于重点污染源自动监控系统的监督管理。 重点污染源水污染物、大气污染物和噪声排放自动监控系统的建设、管理和运行维护，必须遵守本办法。"},{"i":3,"n":"第三条","txt":"本办法所称自动监控系统，由自动监控设备和监控中心组成。 自动监控设备是指在污染源现场安装的用于监控、监测污染物排放的仪器、流量（速）计、污染治理设施运行记录仪和数据采集传输仪等仪器、仪表，是污染防治设施的组成部分。 监控中心是指环境保护部门通过通信传输线路与自动监控设备连接用于对重点污染源实施自动监控的计算机软件和设备等。"},{"i":4,"n":"第四条","txt":"自动监控系统经环境保护部门检查合格并正常运行的，其数据作为环境保护部门进行排污申报核定、排污许可证发放、总量控制、环境统计、排污费征收和现场环境执法等环境监督管理的依据，并按照有关规定向社会公开。"},{"i":5,"n":"第五条","txt":"国家环境保护总局负责指导全国重点污染源自动监控工作，制定有关工作制度和技术规范。 地方环境保护部门根据国家环境保护总局的要求按照统筹规划、保证重点、兼顾一般、量力而行的原则，确定需要自动监控的重点污染源，制定工作计划。"},{"i":6,"n":"第六条","txt":"环境监察机构负责以下工作： （一）参与制定工作计划，并组织实施； （二）核实自动监控设备的选用、安装、使用是否符合要求； （三）对自动监控系统的建设、运行和维护等进行监督检查； （四）本行政区域内重点污染源自动监控系统联网监控管理； （五）核定自动监控数据，并向同级环境保护部门和上级环境监察机构等联网报送； （六）对不按照规定建立或者擅自拆除、闲置、关闭及不正常使用自动监控系统的排污单位提出依法处罚的意见。"},{"i":7,"n":"第七条","txt":"环境监测机构负责以下工作： （一）指导自动监控设备的选用、安装和使用； （二）对自动监控设备进行定期比对监测，提出自动监控数据有效性的意见。"},{"i":8,"n":"第八条","txt":"环境信息机构负责以下工作： （一）指导自动监控系统的软件开发； （二）指导自动监控系统的联网，核实自动监控系统的联网是否符合国家环境保护总局制定的技术规范; （三）协助环境监察机构对自动监控系统的联网运行进行维护管理。"},{"i":9,"n":"第九条","txt":"任何单位和个人都有保护自动监控系统的义务，并有权对闲置、拆除、破坏以及擅自改动自动监控系统参数和数据等不正常使用自动监控系统的行为进行举报。"},{"i":10,"n":"第十条","txt":"列入污染源自动监控计划的排污单位，应当按照规定的时限建设、安装自动监控设备及其配套设施，配合自动监控系统的联网。"},{"i":11,"n":"第十一条","txt":"新建、改建、扩建和技术改造项目应当根据经批准的环境影响评价文件的要求建设、安装自动监控设备及其配套设施，作为环境保护设施的组成部分，与主体工程同时设计、同时施工、同时投入使用。"},{"i":12,"n":"第十二条","txt":"建设自动监控系统必须符合下列要求： （一）自动监控设备中的相关仪器应当选用经国家环境保护总局指定的环境监测仪器检测机构适用性检测合格的产品； （二）数据采集和传输符合国家有关污染源在线自动监控（监测）系统数据传输和接口标准的技术规范； （三）自动监控设备应安装在符合环境保护规范要求的排污口； （四）按照国家有关环境监测技术规范，环境监测仪器的比对监测应当合格； （五）自动监控设备与监控中心能够稳定联网； （六）建立自动监控系统运行、使用、管理制度。"},{"i":13,"n":"第十三条","txt":"自动监控设备的建设、运行和维护经费由排污单位自筹，环境保护部门可以给予补助；监控中心的建设和运行、维护经费由环境保护部门编报预算申请经费。"},{"i":14,"n":"第十四条","txt":"自动监控系统的运行和维护，应当遵守以下规定： （一）自动监控设备的操作人员应当按国家相关规定，经培训考核合格、持证上岗； （二）自动监控设备的使用、运行、维护符合有关技术规范； （三）定期进行比对监测； （四）建立自动监控系统运行记录； （五）自动监控设备因故障不能正常采集、传输数据时，应当及时检修并向环境监察机构报告，必要时应当采用人工监测方法报送数据。 自动监控系统由第三方运行和维护的，接受委托的第三方应当依据《环境污染治理设施运营资质许可管理办法》的规定，申请取得环境污染治理设施运营资质证书。"},{"i":15,"n":"第十五条","txt":"自动监控设备需要维修、停用、拆除或者更换的，应当事先报经环境监察机构批准同意。 环境监察机构应当自收到排污单位的报告之日起7日内予以批复；逾期不批复的，视为同意。"},{"i":16,"n":"第十六条","txt":"违反本办法规定，现有排污单位未按规定的期限完成安装自动监控设备及其配套设施的，由县级以上环境保护部门责令限期改正，并可处1万元以下的罚款。"},{"i":17,"n":"第十七条","txt":"违反本办法规定，新建、改建、扩建和技术改造的项目未安装自动监控设备及其配套设施，或者未经验收或者验收不合格的，主体工程即正式投入生产或者使用的，由审批该建设项目环境影响评价文件的环境保护部门依据《建设项目环境保护管理条例》责令停止主体工程生产或者使用，可以处10万元以下的罚款。"},{"i":18,"n":"第十八条","txt":"违反本办法规定，有下列行为之一的，由县级以上地方环境保护部门按以下规定处理： （一）故意不正常使用水污染物排放自动监控系统，或者未经环境保护部门批准，擅自拆除、闲置、破坏水污染物排放自动监控系统，排放污染物超过规定标准的； （二）不正常使用大气污染物排放自动监控系统，或者未经环境保护部门批准，擅自拆除、闲置、破坏大气污染物排放自动监控系统的； （三）未经环境保护部门批准，擅自拆除、闲置、破坏环境噪声排放自动监控系统，致使环境噪声排放超过规定标准的。 有前款第（一）项行为的，依据《水污染防治法》第四十八条和《水污染防治法实施细则》第四十一条的规定，责令恢复正常使用或者限期重新安装使用，并处10万元以下的罚款；有前款第（二）项行为的，依据《大气污染防治法》第四十六条的规定，责令停止违法行为，限期改正，给予警告或者处5万元以下罚款；有前款第（三）项行为的，依据《环境噪声污染防治法》第五十条的"},{"i":19,"n":"第十九条","txt":"本办法自2005年11月1日起施行。"}],"wuranyuanzidongjiankongsheshixianchangjiandujianchc0b44e":[{"i":1,"n":"第一条","txt":"为加强对污染源自动监控设施的现场监督检查，保障其正常运行，保证自动监控数据的真实、可靠和有效，根据《中华人民共和国水污染防治法》、《中华人民共和国大气污染防治法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称污染源自动监控设施，是指在污染源现场安装的用于监控、监测污染物排放的在线自动监测仪、流量（速）计、污染治理设施运行记录仪和数据采集传输仪器、仪表、传感器等设施，是污染防治设施的组成部分。"},{"i":3,"n":"第三条","txt":"本办法适用于各级环境保护主管部门对污染源自动监控设施的现场监督检查。"},{"i":4,"n":"第四条","txt":"污染源自动监控设施的现场监督检查，由各级环境保护主管部门或者其委托的行使现场监督检查职责的机构（以下统称监督检查机构）具体负责。 　　省级以下环境保护主管部门对污染源自动监控设施进行监督管理和现场监督检查的权限划分，由省级环境保护主管部门确定。"},{"i":5,"n":"第五条","txt":"实施污染源自动监控设施现场监督检查，应当与其他污染防治设施的现场检查相结合，并遵守国家有关法律法规、标准、技术规范以及环境保护主管部门的规定。"},{"i":6,"n":"第六条","txt":"污染源自动监控设施的生产者和销售者，应当保证其生产和销售的污染源自动监控设施符合国家规定的标准。 　　排污单位自行运行污染源自动监控设施的，应当保证其正常运行。由取得环境污染治理设施运营资质的单位（以下简称运营单位）运行污染源自动监控设施的，排污单位应当配合、监督运营单位正常运行；运营单位应当保证污染源自动监控设施正常运行。 　　污染源自动监控设施的生产者、销售者以及排污单位和运营单位应当接受和配合监督检查机构的现场监督检查，并按照要求提供相关技术资料。监督检查机构有义务为被检查单位保守在检查中获取的商业秘密。"},{"i":7,"n":"第七条","txt":"污染源自动监控设施建成后，组织建设的单位应当及时组织验收。经验收合格后，污染源自动监控设施方可投入使用。 　　排污单位或者其他污染源自动监控设施所有权单位，应当在污染源自动监控设施验收后五个工作日内，将污染源自动监控设施有关情况交有管辖权的监督检查机构登记备案。 　　污染源自动监控设施的主要设备或者核心部件更换、采样位置或者主要设备安装位置等发生重大变化的，应当重新组织验收。排污单位或者其他污染源自动监控设施所有权单位应当在重新验收合格后五个工作日内，向有管辖权的监督检查机构变更登记备案。 　　有管辖权的监督检查机构应当对污染源自动监控设施登记事项及时予以登记，作为现场监督检查的依据。"},{"i":8,"n":"第八条","txt":"污染源自动监控设施确需拆除或者停运的，排污单位或者运营单位应当事先向有管辖权的监督检查机构报告，经有管辖权的监督检查机构同意后方可实施。有管辖权的监督检查机构接到报告后，可以组织现场核实，并在接到报告后五个工作日内作出决定；逾期不作出决定的，视为同意。 　　污染源自动监控设施发生故障不能正常使用的，排污单位或者运营单位应当在发生故障后十二小时内向有管辖权的监督检查机构报告，并及时检修，保证在五个工作日内恢复正常运行。停运期间，排污单位或者运营单位应当按照有关规定和技术规范，采用手工监测等方式，对污染物排放状况进行监测，并报送监测数据。"},{"i":9,"n":"第九条","txt":"下级环境保护主管部门应当每季度向上一级环境保护主管部门报告污染源自动监控设施现场监督检查工作情况。省级环境保护主管部门应当于每年的1月30日前向环境保护部报送上一年度本行政区域污染源自动监控设施现场监督检查工作报告。"},{"i":10,"n":"第十条","txt":"污染源自动监控设施现场监督检查工作报告应当包括以下内容： 　　（一）辖区内污染源自动监控设施总体运行情况、存在的问题和建议； 　　（二）辖区内有关污染源自动监控设施违法行为及其查处情况和典型案例； 　　（三）污染源自动监控设施生产者、销售者和运营单位在辖区内服务质量评估。"},{"i":11,"n":"第十一条","txt":"上级环境保护主管部门应当定期组织对本辖区内下级环境保护主管部门污染源自动监控设施现场监督检查的工作情况进行督查，并实行专项考核。"},{"i":12,"n":"第十二条","txt":"污染源自动监控设施现场监督检查的有关情况，应当依法公开。"},{"i":13,"n":"第十三条","txt":"对污染源自动监控设施进行现场监督检查，应当重点检查以下内容： 　　（一）排放口规范化情况； 　　（二）污染源自动监控设施现场端建设规范化情况； 　　（三）污染源自动监控设施变更情况； 　　（四）污染源自动监控设施运行状况； 　　（五）污染源自动监控设施运行、维护、检修、校准校验记录； 　　（六）相关资质、证书、标志的有效性； 　　（七）企业生产工况、污染治理设施运行与自动监控数据的相关性。"},{"i":14,"n":"第十四条","txt":"污染源自动监控设施现场监督检查分为例行检查和重点检查。 　　监督检查机构应当对污染源自动监控设施定期进行例行检查。对国家重点监控企业污染源自动监控设施的例行检查每月至少一次；对其他企业污染源自动监控设施的例行检查每季度至少一次。 　　对涉嫌不正常运行、使用污染源自动监控设施或者有弄虚作假等违法情况的企业，监督检查机构应当进行重点检查。重点检查可以邀请有关部门和专家参加。 　　实施污染源自动监控设施例行检查或者重点检查的，可以根据情况，事先通知被检查单位，也可以不事先通知。"},{"i":15,"n":"第十五条","txt":"污染源自动监控设施的现场监督检查，按照下列程序进行： 　　（一）检查前准备工作，包括污染源自动监控设施登记备案情况、污染物排放及污染防治的有关情况，现场检查装备配备等； 　　（二）进行现场监督检查； 　　（三）认定运行正常的，结束现场监督检查； 　　（四）对涉嫌不正常运行、使用或者有弄虚作假等违法行为的，进行重点检查； 　　（五）经重点检查，认定有违法行为的，依法予以处罚。 　　污染源自动监控设施现场监督检查结果，应当及时反馈被检查单位。"},{"i":16,"n":"第十六条","txt":"现场监督检查人员应当按照有关技术规范要求填写现场监督检查表，制作现场监督检查笔录。 　　现场监督检查人员进行污染源自动监控设施现场监督检查时，可以采取以下措施： 　　（一）以拍照、录音、录像、仪器标定或者拷贝文件、数据等方式保存现场检查资料； 　　（二）使用快速监测仪器采样监测。必要时，由环境监测机构进行监督性监测或者比对监测并出具监测结果； 　　（三）要求排污单位或者运营单位对污染源自动监控设施的硬件、软件进行技术测试； 　　（四）封存有关样品、试剂等物质，并送交有关部门或者机构检测。"},{"i":17,"n":"第十七条","txt":"排污单位或者其他污染源自动监控设施所有权单位，未按照本办法第七条的规定向有管辖权的监督检查机构登记其污染源自动监控设施有关情况，或者登记情况不属实的，依照《中华人民共和国水污染防治法》第七十二条第（一）项或者《中华人民共和国大气污染防治法》第四十六条第（一）项的规定处罚。"},{"i":18,"n":"第十八条","txt":"排污单位或者运营单位有下列行为之一的，依照《中华人民共和国水污染防治法》第七十条或者《中华人民共和国大气污染防治法》第四十六条第（二）项的规定处罚： 　　（一）采取禁止进入、拖延时间等方式阻挠现场监督检查人员进入现场检查污染源自动监控设施的； 　　（二）不配合进行仪器标定等现场测试的； 　　（三）不按照要求提供相关技术资料和运行记录的； 　　（四）不如实回答现场监督检查人员询问的。"},{"i":19,"n":"第十九条","txt":"排污单位或者运营单位擅自拆除、闲置污染源自动监控设施，或者有下列行为之一的，依照《中华人民共和国水污染防治法》第七十三条或者《中华人民共和国大气污染防治法》第四十六条第（三）项的规定处罚： 　　（一）未经环境保护主管部门同意，部分或者全部停运污染源自动监控设施的； 　　（二）污染源自动监控设施发生故障不能正常运行，不按照规定报告又不及时检修恢复正常运行的； 　　（三）不按照技术规范操作，导致污染源自动监控数据明显失真的； 　　（四）不按照技术规范操作，导致传输的污染源自动监控数据明显不一致的； 　　（五）不按照技术规范操作，导致排污单位生产工况、污染治理设施运行与自动监控数据相关性异常的； 　　（六）擅自改动污染源自动监控系统相关参数和数据的； 　　（七）污染源自动监控数据未通过有效性审核或者有效性审核失效的； 　　（八）其他人为原因造成的污染源自动监控设施不正常运行的情况。"},{"i":20,"n":"第二十条","txt":"排污单位或者运营单位有下列行为之一的，依照《中华人民共和国水污染防治法》第七十条或者《中华人民共和国大气污染防治法》第四十六条第（二）项的规定处罚： 　　（一）将部分或者全部污染物不经规范的排放口排放，规避污染源自动监控设施监控的； 　　（二）违反技术规范，通过稀释、吸附、吸收、过滤等方式处理监控样品的； 　　（三）不按照技术规范的要求，对仪器、试剂进行变动操作的； 　　（四）违反技术规范的要求，对污染源自动监控系统功能进行删除、修改、增加、干扰，造成污染源自动监控系统不能正常运行，或者对污染源自动监控系统中存储、处理或者传输的数据和应用程序进行删除、修改、增加的操作的； 　　（五）其他欺骗现场监督检查人员，掩盖真实排污状况行为。"},{"i":21,"n":"第二十一条","txt":"排污单位排放污染物超过国家或者地方规定的污染物排放标准，或者超过重点污染物排放总量控制指标的，依照《中华人民共和国水污染防治法》第七十四条或者《中华人民共和国大气污染防治法》第四十八条的规定处罚。"},{"i":22,"n":"第二十二条","txt":"污染源自动监控设施生产者、销售者参与排污单位污染源自动监控设施运行弄虚作假的，由环境保护主管部门予以通报，公开该生产者、销售者名称及其产品型号；情节严重的，收回其环境保护适用性检测报告和环境保护产品认证证书。对已经安装使用该生产者、销售者生产、销售的同类产品的企业，环境保护主管部门应当加强重点检查。"},{"i":23,"n":"第二十三条","txt":"运营单位参与排污单位污染源自动监控设施运行弄虚作假的，依照《环境污染治理设施运营资质许可管理办法》的有关规定处罚。"},{"i":24,"n":"第二十四条","txt":"环境保护主管部门的工作人员有下列行为之一的，依法给予处分；构成犯罪的，依法追究刑事责任： 　　（一）不履行或者不按照规定履行对污染源自动监控设施现场监督检查职责的； 　　（二）对接到举报或者所发现的违法行为不依法予以查处的； 　　（三）包庇、纵容、参与排污单位或者运营单位弄虚作假的； 　　（四）其他玩忽职守、滥用职权或者徇私舞弊行为。"},{"i":25,"n":"第二十五条","txt":"排污单位通过污染源自动监控设施数据弄虚作假获取主要污染物年度削减量、有关环境保护荣誉称号或者评级的，由原核定削减量或者授予荣誉称号的环境保护主管部门予以撤销。 　　排污单位通过污染源自动监控设施数据弄虚作假，骗取国家优惠脱硫脱硝电价的，环境保护主管部门应当及时通报优惠电价核定部门，取消电价优惠。"},{"i":26,"n":"第二十六条","txt":"违反技术规范的要求，对污染源自动监控系统功能进行删除、修改、增加、干扰，造成污染源自动监控系统不能正常运行，或者对污染源自动监控系统中存储、处理或者传输的数据和应用程序进行删除、修改、增加的操作，构成违反治安管理行为的，由环境保护主管部门移送公安部门依据《中华人民共和国治安管理处罚法》第二十九条规定处理；涉嫌构成犯罪的，移送司法机关依照《中华人民共和国刑法》第二百八十六条追究刑事责任。"},{"i":27,"n":"第二十七条","txt":"本办法由环境保护部负责解释。"},{"i":28,"n":"第二十八条","txt":"污染源自动监控设施现场监督检查的技术规范和相关指南由环境保护部另行发布。"},{"i":29,"n":"第二十九条","txt":"本办法自2012年4月1日起施行。 　　附： 　　《治安管理处罚法》第二十九条　有下列行为之一的，处五日以下拘留；情节较重的，处五日以上十日以下拘留： 　　（一）违反国家规定，侵入计算机信息系统，造成危害的； 　　（二）违反国家规定，对计算机信息系统功能进行删除、修改、增加、干扰，造成计算机信息系统不能正常运行的； 　　（三）违反国家规定，对计算机信息系统中存储、处理、传输的数据和应用程序进行删除、修改、增加的； 　　（四）故意制作、传播计算机病毒等破坏性程序，影响计算机信息系统正常运行的。 　　《刑法》第二百八十六条　违反国家规定，对计算机信息系统功能进行删除、修改、增加、干扰，造成计算机信息系统不能正常运行，后果严重的，处五年以下有期徒刑或者拘役；后果特别严重的，处五年以上有期徒刑。 　　违反国家规定，对计算机信息系统中存储、处理或者传输的数据和应用程序进行删除、修改、增加的操作，"}],"xiaohaochouyangcengwuzhijinchukouguanlibanfa":[{"i":1,"n":"第一条","txt":"为履行《关于消耗臭氧层物质的蒙特利尔议定书》及其修正案，加强对我国消耗臭氧层物质进出口管理，根据《消耗臭氧层物质管理条例》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于进出口列入《中国进出口受控消耗臭氧层物质名录》的消耗臭氧层物质的活动。 《中国进出口受控消耗臭氧层物质名录》由国务院生态环境主管部门会同国务院商务主管部门、海关总署制定、调整和公布。"},{"i":3,"n":"第三条","txt":"国家对列入《中国进出口受控消耗臭氧层物质名录》的消耗臭氧层物质实行进出口配额许可证管理。"},{"i":4,"n":"第四条","txt":"国务院生态环境主管部门统一负责全国消耗臭氧层物质的监督管理工作。 国务院生态环境主管部门、国务院商务主管部门和海关总署联合设立国家消耗臭氧层物质进出口管理机构。"},{"i":5,"n":"第五条","txt":"国务院生态环境主管部门根据消耗臭氧层物质淘汰进展情况，商国务院商务主管部门确定国家消耗臭氧层物质年度进出口配额总量，并在每年12月20日前公布下一年度进出口配额总量。"},{"i":6,"n":"第六条","txt":"进出口消耗臭氧层物质的单位（以下简称进出口单位），应当向国家消耗臭氧层物质进出口管理机构申请消耗臭氧层物质进出口配额（以下简称进出口配额），领取消耗臭氧层物质进出口审批单（以下简称进出口审批单）。"},{"i":7,"n":"第七条","txt":"进出口单位应当在每年10月31日前向国家消耗臭氧层物质进出口管理机构申请下一年度进出口配额。 进出口单位申请进出口配额的，应当提交下列材料： （一）进出口配额申请书； （二）年度消耗臭氧层物质进出口计划表； （三）初次申请进出口配额的进出口单位，还应当提交营业执照。 未按时提交上述材料的，国家消耗臭氧层物质进出口管理机构不予受理进出口配额申请。"},{"i":8,"n":"第八条","txt":"国家消耗臭氧层物质进出口管理机构在核定进出口单位的年度进出口配额申请时，应当综合考虑下列因素： （一）遵守法律法规情况； （二）上一年度消耗臭氧层物质进出口计划及进出口配额完成情况； （三）其他影响消耗臭氧层物质进出口的因素。"},{"i":9,"n":"第九条","txt":"国家消耗臭氧层物质进出口管理机构应当在每年12月20日前对进出口配额做出发放与否的决定，并予以公告。"},{"i":10,"n":"第十条","txt":"在年度进出口配额指标内，进出口单位需要进出口消耗臭氧层物质的，应当向国家消耗臭氧层物质进出口管理机构申请领取进出口审批单。 有下列情形之一，进出口单位可以直接向国家消耗臭氧层物质进出口管理机构申请领取进出口审批单： （一）消耗臭氧层物质作为原料用途使用的； （二）实验室为了实验分析少量使用消耗臭氧层物质的； （三）海关为了防止有害生物传入传出使用消耗臭氧层物质实施检疫的； （四）消耗臭氧层物质来源为回收的； （五）国务院生态环境主管部门规定的可以直接申请领取进出口审批单的其他情形。"},{"i":11,"n":"第十一条","txt":"进出口单位申请领取进出口审批单应当提交下列材料： （一）消耗臭氧层物质进出口申请书； （二）对外贸易合同或者订单等相关材料，以及消耗臭氧层物质生产单位的供货证明； （三）特殊用途的消耗臭氧层物质的出口，出口单位应当提交进口国政府部门出具的进口许可证或者其他官方批准文件等材料； （四）初次申请领取进出口审批单的，还应当提交营业执照； （五）国家消耗臭氧层物质进出口管理机构认为需要提供的其他材料。"},{"i":12,"n":"第十二条","txt":"国家消耗臭氧层物质进出口管理机构应当自受理申请之日起二十个工作日内完成审查，作出是否批准的决定。予以批准的，向申请单位核发进出口审批单，并对获准核发进出口审批单的进出口单位名单进行公告；未予批准的，应当书面通知申请单位并说明理由。"},{"i":13,"n":"第十三条","txt":"进出口审批单有效期最长为九十日，不得超期或者跨年度使用。"},{"i":14,"n":"第十四条","txt":"进出口单位应当凭进出口审批单，向国务院商务主管部门或者受国务院商务主管部门委托的地方商务主管部门申请领取消耗臭氧层物质进出口许可证（以下简称进出口许可证）。 进出口许可证实行一批一证制。每份进出口许可证只能报关使用一次，当年有效，不得跨年度使用。 进出口许可证的申领和管理按照国务院商务主管部门有关规定执行。"},{"i":15,"n":"第十五条","txt":"进出口单位凭商务主管部门核发的进出口许可证向海关办理通关手续。"},{"i":16,"n":"第十六条","txt":"消耗臭氧层物质在中华人民共和国境内的海关特殊监管区域、保税监管场所与境外之间进出的，进出口单位应当依照本办法的规定申请领取进出口审批单、进出口许可证。 消耗臭氧层物质在中华人民共和国境内的海关特殊监管区域、保税监管场所与境内其他区域之间进出的，或者在上述海关特殊监管区域、保税监管场所之间进出的，不需要申请领取进出口审批单、进出口许可证。"},{"i":17,"n":"第十七条","txt":"进出口单位应当按照进出口许可证载明的内容从事消耗臭氧层物质的进出口活动。发生与进出口许可证载明的内容不符的情形的，进出口单位应当重新申请领取进出口许可证。"},{"i":18,"n":"第十八条","txt":"国务院生态环境主管部门建立消耗臭氧层物质进出口数据信息管理系统，收集、汇总消耗臭氧层物质的进出口数据信息。 国务院生态环境主管部门、国务院商务主管部门、海关总署应当建立信息共享机制，及时通报消耗臭氧层物质进出口、进出口单位信息和违法情况等信息。"},{"i":19,"n":"第十九条","txt":"生态环境主管部门、商务主管部门、海关等有关部门有权依法对进出口单位的消耗臭氧层物质进出口活动进行监督检查。被检查单位必须如实反映情况，提供必要资料，不得拒绝和阻碍。检查机关对监督检查中知悉的商业秘密负有保密义务。"},{"i":20,"n":"第二十条","txt":"进出口单位当年不能足额使用的进出口配额，应当于当年10月31日前报告并交还国家消耗臭氧层物质进出口管理机构。国家消耗臭氧层物质进出口管理机构可以根据实际情况对年度进出口配额进行调整分配。"},{"i":21,"n":"第二十一条","txt":"本办法规定的进出口配额申请书、年度消耗臭氧层物质进出口计划表、消耗臭氧层物质进出口申请书、进出口审批单等文件格式，由国务院生态环境主管部门统一制定并公布。"},{"i":22,"n":"第二十二条","txt":"本办法由国务院生态环境主管部门、国务院商务主管部门、海关总署依职责分工解释。"},{"i":23,"n":"第二十三条","txt":"本办法自2025年5月1日起施行。《消耗臭氧层物质进出口管理办法》（环境保护部、商务部、海关总署令第26号）同时废止。"}],"wenshiqitiziyuanjianpaijiaoyiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了推动实现我国碳达峰碳中和目标，控制和减少人为活动产生的温室气体排放，鼓励温室气体自愿减排行为，规范全国温室气体自愿减排交易及相关活动，根据党中央、国务院关于建设全国温室气体自愿减排交易市场的决策部署以及相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"全国温室气体自愿减排交易及相关活动的监督管理，适用本办法。"},{"i":3,"n":"第三条","txt":"全国温室气体自愿减排交易及相关活动应当坚持市场导向，遵循公平、公正、公开、诚信和自愿的原则。"},{"i":4,"n":"第四条","txt":"中华人民共和国境内依法成立的法人和其他组织，可以依照本办法开展温室气体自愿减排活动，申请温室气体自愿减排项目和减排量的登记。 符合国家有关规定的法人、其他组织和自然人，可以依照本办法参与温室气体自愿减排交易。"},{"i":5,"n":"第五条","txt":"生态环境部按照国家有关规定建设全国温室气体自愿减排交易市场，负责制定全国温室气体自愿减排交易及相关活动的管理要求和技术规范，并对全国温室气体自愿减排交易及相关活动进行监督管理和指导。 省级生态环境主管部门负责对本行政区域内温室气体自愿减排交易及相关活动进行监督管理。 设区的市级生态环境主管部门配合省级生态环境主管部门对本行政区域内温室气体自愿减排交易及相关活动实施监督管理。 市场监管部门、生态环境主管部门根据职责分工，对从事温室气体自愿减排项目审定与减排量核查的机构（以下简称审定与核查机构）及其审定与核查活动进行监督管理。"},{"i":6,"n":"第六条","txt":"生态环境部按照国家有关规定，组织建立统一的全国温室气体自愿减排注册登记机构（以下简称注册登记机构），组织建设全国温室气体自愿减排注册登记系统（以下简称注册登记系统）。 注册登记机构负责注册登记系统的运行和管理，通过该系统受理温室气体自愿减排项目和减排量的登记、注销申请，记录温室气体自愿减排项目相关信息和核证自愿减排量的登记、持有、变更、注销等信息。注册登记系统记录的信息是判断核证自愿减排量归属和状态的最终依据。 注册登记机构可以按照国家有关规定，制定温室气体自愿减排项目和减排量登记的具体业务规则，并报生态环境部备案。"},{"i":7,"n":"第七条","txt":"生态环境部按照国家有关规定，组织建立统一的全国温室气体自愿减排交易机构（以下简称交易机构），组织建设全国温室气体自愿减排交易系统（以下简称交易系统）。 交易机构负责交易系统的运行和管理，提供核证自愿减排量的集中统一交易与结算服务。 交易机构应当按照国家有关规定采取有效措施，维护市场健康发展，防止过度投机，防范金融等方面的风险。 交易机构可以按照国家有关规定，制定核证自愿减排量交易的具体业务规则，并报生态环境部备案。"},{"i":8,"n":"第八条","txt":"生态环境部负责组织制定并发布温室气体自愿减排项目方法学（以下简称项目方法学）等技术规范，作为相关领域自愿减排项目审定、实施与减排量核算、核查的依据。 项目方法学应当规定适用条件、减排量核算方法、监测方法、项目审定与减排量核查要求等内容，并明确可申请项目减排量登记的时间期限。 项目方法学应当根据经济社会发展、产业结构调整、行业发展阶段、应对气候变化政策等因素及时修订，条件成熟时纳入国家标准体系。"},{"i":9,"n":"第九条","txt":"申请登记的温室气体自愿减排项目应当有利于降碳增汇，能够避免、减少温室气体排放，或者实现温室气体的清除。"},{"i":10,"n":"第十条","txt":"申请登记的温室气体自愿减排项目应当具备下列条件： （一）具备真实性、唯一性和额外性； （二）属于生态环境部发布的项目方法学支持领域； （三）于2012年11月8日之后开工建设； （四）符合生态环境部规定的其他条件。 属于法律法规、国家政策规定有温室气体减排义务的项目，或者纳入全国和地方碳排放权交易市场配额管理的项目，不得申请温室气体自愿减排项目登记。"},{"i":11,"n":"第十一条","txt":"申请温室气体自愿减排项目登记的法人或者其他组织（以下简称项目业主）应当按照项目方法学等相关技术规范要求编制项目设计文件，并委托审定与核查机构对项目进行审定。 项目设计文件所涉数据和信息的原始记录、管理台账应当在该项目最后一期减排量登记后至少保存十年。"},{"i":12,"n":"第十二条","txt":"项目业主申请温室气体自愿减排项目登记前，应当通过注册登记系统公示项目设计文件，并对公示材料的真实性、完整性和有效性负责。 项目业主公示项目设计文件时，应当同步公示其所委托的审定与核查机构的名称。 项目设计文件公示期为二十个工作日。公示期间，公众可以通过注册登记系统提出意见。"},{"i":13,"n":"第十三条","txt":"审定与核查机构应当按照国家有关规定对申请登记的温室气体自愿减排项目的以下事项进行审定，并出具项目审定报告，上传至注册登记系统，同时向社会公开： （一）是否符合相关法律法规、国家政策； （二）是否属于生态环境部发布的项目方法学支持领域； （三）项目方法学的选择和使用是否得当； （四）是否具备真实性、唯一性和额外性； （五）是否符合可持续发展要求，是否对可持续发展各方面产生不利影响。 项目审定报告应当包括肯定或者否定的项目审定结论，以及项目业主对公示期间收到的公众意见处理情况的说明。 审定与核查机构应当对项目审定报告的合规性、真实性、准确性负责，并在项目审定报告中作出承诺。"},{"i":14,"n":"第十四条","txt":"审定与核查机构出具项目审定报告后，项目业主可以向注册登记机构申请温室气体自愿减排项目登记。 项目业主申请温室气体自愿减排项目登记时，应当通过注册登记系统提交项目申请表和审定与核查机构上传的项目设计文件、项目审定报告，并附具对项目唯一性以及所提供材料真实性、完整性和有效性负责的承诺书。"},{"i":15,"n":"第十五条","txt":"注册登记机构对项目业主提交材料的完整性、规范性进行审核，在收到申请材料之日起十五个工作日内对审核通过的温室气体自愿减排项目进行登记，并向社会公开项目登记情况以及项目业主提交的全部材料；申请材料不完整、不规范的，不予登记，并告知项目业主。"},{"i":16,"n":"第十六条","txt":"已登记的温室气体自愿减排项目出现项目业主主体灭失、项目不复存续等情形的，注册登记机构调查核实后，对已登记的项目进行注销。 项目业主可以自愿向注册登记机构申请对已登记的温室气体自愿减排项目进行注销。 温室气体自愿减排项目注销情况应当通过注册登记系统向社会公开；注销后的项目不得再次申请登记。"},{"i":17,"n":"第十七条","txt":"经注册登记机构登记的温室气体自愿减排项目可以申请项目减排量登记。申请登记的项目减排量应当可测量、可追溯、可核查，并具备下列条件： （一）符合保守性原则； （二）符合生态环境部发布的项目方法学； （三）产生于2020年9月22日之后； （四）在可申请项目减排量登记的时间期限内； （五）符合生态环境部规定的其他条件。 项目业主可以分期申请项目减排量登记。每期申请登记的项目减排量的产生时间应当在其申请登记之日前五年以内。"},{"i":18,"n":"第十八条","txt":"项目业主申请项目减排量登记的，应当按照项目方法学等相关技术规范要求编制减排量核算报告，并委托审定与核查机构对减排量进行核查。项目业主不得委托负责项目审定的审定与核查机构开展该项目的减排量核查。 减排量核算报告所涉数据和信息的原始记录、管理台账应当在该温室气体自愿减排项目最后一期减排量登记后至少保存十年。 项目业主应当加强对温室气体自愿减排项目实施情况的日常监测。鼓励项目业主采用信息化、智能化措施加强数据管理。"},{"i":19,"n":"第十九条","txt":"项目业主申请项目减排量登记前，应当通过注册登记系统公示减排量核算报告，并对公示材料的真实性、完整性和有效性负责。 项目业主公示减排量核算报告时，应当同步公示其所委托的审定与核查机构的名称。 减排量核算报告公示期为二十个工作日。公示期间，公众可以通过注册登记系统提出意见。"},{"i":20,"n":"第二十条","txt":"审定与核查机构应当按照国家有关规定对减排量核算报告的下列事项进行核查，并出具减排量核查报告，上传至注册登记系统，同时向社会公开： （一）是否符合项目方法学等相关技术规范要求； （二）项目是否按照项目设计文件实施； （三）减排量核算是否符合保守性原则。 减排量核查报告应当确定经核查的减排量，并说明项目业主对公示期间收到的公众意见处理情况。 审定与核查机构应当对减排量核查报告的合规性、真实性、准确性负责，并在减排量核查报告中作出承诺。"},{"i":21,"n":"第二十一条","txt":"审定与核查机构出具减排量核查报告后，项目业主可以向注册登记机构申请项目减排量登记；申请登记的项目减排量应当与减排量核查报告确定的减排量一致。 项目业主申请项目减排量登记时，应当通过注册登记系统提交项目减排量申请表和审定与核查机构上传的减排量核算报告、减排量核查报告，并附具对减排量核算报告真实性、完整性和有效性负责的承诺书。"},{"i":22,"n":"第二十二条","txt":"注册登记机构对项目业主提交材料的完整性、规范性进行审核，在收到申请材料之日起十五个工作日内对审核通过的项目减排量进行登记，并向社会公开减排量登记情况以及项目业主提交的全部材料；申请材料不完整、不规范的，不予登记，并告知项目业主。 经登记的项目减排量称为“核证自愿减排量”，单位以“吨二氧化碳当量（tCO2e）”计。"},{"i":23,"n":"第二十三条","txt":"全国温室气体自愿减排交易市场的交易产品为核证自愿减排量。生态环境部可以根据国家有关规定适时增加其他交易产品。"},{"i":24,"n":"第二十四条","txt":"从事核证自愿减排量交易的交易主体，应当在注册登记系统和交易系统开设账户。"},{"i":25,"n":"第二十五条","txt":"核证自愿减排量的交易应当通过交易系统进行。 核证自愿减排量交易可以采取挂牌协议、大宗协议、单向竞价及其他符合规定的交易方式。"},{"i":26,"n":"第二十六条","txt":"注册登记机构根据交易机构提供的成交结果，通过注册登记系统为交易主体及时变更核证自愿减排量的持有数量和持有状态等相关信息。 注册登记机构和交易机构应当按照国家有关规定，实现系统间数据及时、准确、安全交换。"},{"i":27,"n":"第二十七条","txt":"交易主体违反关于核证自愿减排量登记、结算或者交易相关规定的，注册登记机构和交易机构可以按照国家有关规定，对其采取限制交易措施。"},{"i":28,"n":"第二十八条","txt":"核证自愿减排量按照国家有关规定用于抵销全国碳排放权交易市场和地方碳排放权交易市场碳排放配额清缴、大型活动碳中和、抵销企业温室气体排放等用途的，应当在注册登记系统中予以注销。 鼓励参与主体为了公益目的，自愿注销其所持有的核证自愿减排量。"},{"i":29,"n":"第二十九条","txt":"核证自愿减排量跨境交易和使用的具体规定，由生态环境部会同有关部门另行制定。"},{"i":30,"n":"第三十条","txt":"审定与核查机构纳入认证机构管理，应当按照《中华人民共和国认证认可条例》《认证机构管理办法》等关于认证机构的规定，公正、独立和有效地从事审定与核查活动。 审定与核查机构应当具备与从事审定与核查活动相适应的技术和管理能力，并且符合以下条件： （一）具备开展审定与核查活动相配套的固定办公场所和必要的设施； （二）具备十名以上相应领域具有审定与核查能力的专职人员，其中至少有五名人员具有二年及以上温室气体排放审定与核查工作经历； （三）建立完善的审定与核查活动管理制度； （四）具备开展审定与核查活动所需的稳定的财务支持，建立与业务风险相适应的风险基金或者保险，有应对风险的能力； （五）符合审定与核查机构相关标准要求； （六）近五年无严重失信记录。 开展审定与核查机构审批时，市场监管总局会同生态环境部根据工作需要制定并公布审定与核查机构需求信息，组织相关领域专家组成专家评审委员会，对审批申请进行评"},{"i":31,"n":"第三十一条","txt":"审定与核查机构应当遵守法律法规和市场监管总局、生态环境部发布的相关规定，在批准的业务范围内开展相关活动，保证审定与核查活动过程的完整、客观、真实，并做出完整记录，归档留存，确保审定与核查过程和结果具有可追溯性。鼓励审定与核查机构获得认可。 审定与核查机构应当加强行业自律。审定与核查机构及其工作人员应当对其出具的审定报告与核查报告的合规性、真实性、准确性负责，不得弄虚作假，不得泄露项目业主的商业秘密。"},{"i":32,"n":"第三十二条","txt":"审定与核查机构应当每年向市场监管总局和生态环境部提交工作报告，并对报告内容的真实性负责。 审定与核查机构提交的工作报告应当对审定与核查机构遵守项目审定与减排量核查法律法规和技术规范的情况、从事审定与核查活动的情况、从业人员的工作情况等作出说明。"},{"i":33,"n":"第三十三条","txt":"市场监管总局、生态环境部共同组建审定与核查技术委员会，协调解决审定与核查有关技术问题，研究提出相关工作建议，提升审定与核查活动的一致性、科学性和合理性，为审定与核查活动监督管理提供技术支撑。"},{"i":34,"n":"第三十四条","txt":"生态环境部负责指导督促地方对温室气体自愿减排交易及相关活动开展监督检查，查处具有典型意义和重大社会影响的违法行为。 省级生态环境主管部门可以会同有关部门，对已登记的温室气体自愿减排项目与核证自愿减排量的真实性、合规性组织开展监督检查，受理对本行政区域内温室气体自愿减排项目提出的公众举报，查处违法行为。 设区的市级生态环境主管部门按照省级生态环境主管部门的统一部署配合开展现场检查。 省级以上生态环境主管部门可以通过政府购买服务等方式，委托依法成立的技术服务机构提供监督检查方面的技术支撑。"},{"i":35,"n":"第三十五条","txt":"市场监管部门依照法律法规和相关规定，对审定与核查活动实施日常监督检查，查处违法行为。结合随机抽查、行政处罚、投诉举报、严重失信名单以及大数据分析等信息，对审定与核查机构实行分类监管。 生态环境主管部门与市场监管部门建立信息共享与协调工作机制。对于监督检查过程中发现的审定与核查活动问题线索，生态环境主管部门应当及时向市场监管部门移交。"},{"i":36,"n":"第三十六条","txt":"生态环境主管部门对项目业主进行监督检查时，可以采取下列措施： （一）要求被检查单位提供有关资料，查阅、复制相关信息； （二）进入被检查单位的生产、经营、储存等场所进行调查； （三）询问被检查单位负责人或者其他有关人员； （四）要求被检查单位就执行本办法规定的有关情况作出说明。 被检查单位应当予以配合，如实反映情况，提供必要资料，不得拒绝和阻挠。"},{"i":37,"n":"第三十七条","txt":"生态环境主管部门、市场监管部门、注册登记机构、交易机构、审定与核查机构及其相关工作人员应当忠于职守、依法办事、公正廉洁，不得利用职务便利牟取不正当利益，不得参与核证自愿减排量交易以及其他可能影响审定与核查公正性的活动。 审定与核查机构不得接受任何可能对审定与核查活动的客观公正产生影响的资助，不得从事可能对审定与核查活动的客观公正产生影响的开发、营销、咨询等活动，不得与委托的项目业主存在资产、管理方面的利益关系，不得为项目业主编制项目设计文件和减排量核算报告。 交易主体不得通过欺诈、相互串通、散布虚假信息等方式操纵或者扰乱全国温室气体自愿减排交易市场。"},{"i":38,"n":"第三十八条","txt":"注册登记机构和交易机构应当保证注册登记系统和交易系统安全稳定可靠运行，并定期向生态环境部报告全国温室气体自愿减排登记、交易相关活动和机构运行情况，及时报告对温室气体自愿减排交易市场有重大影响的相关事项。相关内容可以抄送省级生态环境主管部门。"},{"i":39,"n":"第三十九条","txt":"注册登记机构和交易机构应当对已登记的温室气体自愿减排项目建立项目档案，记录、留存相关信息。"},{"i":40,"n":"第四十条","txt":"市场监管部门、生态环境主管部门应当依法加强信用监督管理，将相关行政处罚信息纳入国家企业信用信息公示系统。"},{"i":41,"n":"第四十一条","txt":"鼓励公众、新闻媒体等对温室气体自愿减排交易及相关活动进行监督。任何单位和个人都有权举报温室气体自愿减排交易及相关活动中的弄虚作假等违法行为。"},{"i":42,"n":"第四十二条","txt":"违反本办法规定，拒不接受或者阻挠监督检查，或者在接受监督检查时弄虚作假的，由实施监督检查的生态环境主管部门或者市场监管部门责令改正，可以处一万元以上十万元以下的罚款。"},{"i":43,"n":"第四十三条","txt":"项目业主在申请温室气体自愿减排项目或者减排量登记时提供虚假材料的，由省级以上生态环境主管部门责令改正，处一万元以上十万元以下的罚款；存在篡改、伪造数据等故意弄虚作假行为的，省级以上生态环境主管部门还应当通知注册登记机构撤销项目登记，三年内不再受理该项目业主提交的温室气体自愿减排项目和减排量登记申请。 项目业主因实施前款规定的弄虚作假行为取得虚假核证自愿减排量的，由省级以上生态环境主管部门通知注册登记机构和交易机构对该项目业主持有的核证自愿减排量暂停交易，责令项目业主注销与虚假部分同等数量的减排量；逾期未按要求注销的，由省级以上生态环境主管部门通知注册登记机构强制注销，对不足部分责令退回，处五万元以上十万元以下的罚款，不再受理该项目业主提交的温室气体自愿减排量项目和减排量申请。"},{"i":44,"n":"第四十四条","txt":"审定与核查机构有下列行为之一的，由实施监督检查的市场监管部门依照《中华人民共和国认证认可条例》责令改正，处五万元以上二十万元以下的罚款，有违法所得的，没收违法所得；情节严重的，责令停业整顿，直至撤销批准文件，并予公布： （一）超出批准的业务范围开展审定与核查活动的； （二）增加、减少、遗漏审定与核查基本规范、规则规定的程序的。 审定与核查机构出具虚假报告，或者出具报告的结论严重失实的，由市场监管部门依照《中华人民共和国认证认可条例》撤销批准文件，并予公布；对直接负责的主管人员和负有直接责任的审定与核查人员，撤销其执业资格。 审定与核查机构接受可能对审定与核查活动的客观公正产生影响的资助，或者从事可能对审定与核查活动的客观公正产生影响的产品开发、营销等活动，或者与项目业主存在资产、管理方面的利益关系的，由市场监管部门依照《中华人民共和国认证认可条例》责令停业整顿；情节严重的，撤销批准文件"},{"i":45,"n":"第四十五条","txt":"交易主体违反本办法规定，操纵或者扰乱全国温室气体自愿减排交易市场的，由生态环境部给予通报批评，并处一万元以上十万元以下的罚款。"},{"i":46,"n":"第四十六条","txt":"生态环境主管部门、市场监管部门、注册登记机构、交易机构的相关工作人员有滥用职权、玩忽职守、徇私舞弊行为的，由其所属单位或者上级行政机关责令改正并依法予以处分。 前述单位相关工作人员有泄露有关商业秘密或者其他构成违反国家交易监督管理规定行为的，依照其他有关法律法规的规定处理。"},{"i":47,"n":"第四十七条","txt":"违反本办法规定，涉嫌构成犯罪的，依法移送司法机关。"},{"i":48,"n":"第四十八条","txt":"本办法中下列用语的含义： 温室气体，是指大气中吸收和重新放出红外辐射的自然和人为的气态成分，包括二氧化碳（CO2）、甲烷（CH4）、氧化亚氮（N2O）、氢氟碳化物（HFCs）、全氟化碳（PFCs）、六氟化硫（SF6）和三氟化氮（NF3）。 审定与核查机构，是指依法设立，从事温室气体自愿减排项目审定或者温室气体自愿减排项目减排量核查活动的合格评定机构。 唯一性，是指项目未参与其他温室气体减排交易机制，不存在项目重复认定或者减排量重复计算的情形。 额外性，是指作为温室气体自愿减排项目实施时，与能够提供同等产品和服务的其他替代方案相比，在内部收益率财务指标等方面不是最佳选择，存在融资、关键技术等方面的障碍，但是作为自愿减排项目实施有助于克服上述障碍，并且相较于相关项目方法学确定的基准线情景，具有额外的减排效果，即项目的温室气体排放量低于基准线排放量，或者温室气体清除量高于基准线清除量。 保守"},{"i":49,"n":"第四十九条","txt":"2017年3月14日前获得国家应对气候变化主管部门备案的温室气体自愿减排项目应当按照本办法规定，重新申请项目登记；已获得备案的减排量可以按照国家有关规定继续使用。"},{"i":50,"n":"第五十条","txt":"本办法由生态环境部、市场监管总局在各自的职责范围内解释。"},{"i":51,"n":"第五十一条","txt":"本办法自公布之日起施行。"}],"huanbaojubaorexiangongzuoguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强环保举报热线工作的规范化管理，畅通群众举报渠道，维护和保障人民群众的合法环境权益，根据《信访条例》以及环境保护法律、法规的有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织通过拨打环保举报热线电话，向各级环境保护主管部门举报环境污染或者生态破坏事项，请求环境保护主管部门依法处理的，适用本办法。 环保举报热线应当使用“12369”特服电话号码，各地名称统一为“12369”环保举报热线。 承担“12369”环保举报热线工作的机构依法受理的举报事项，称举报件。"},{"i":3,"n":"第三条","txt":"环保举报热线工作应当遵循下列原则： （一）属地管理、分级负责，谁主管、谁负责； （二）依法受理，及时办理； （三）维护公众对环境保护工作的知情权、参与权和监督权； （四）调查研究，实事求是，妥善处理，解决问题。"},{"i":4,"n":"第四条","txt":"环保举报热线要做到有报必接、违法必查，事事有结果、件件有回音。 除发生不可抗力情形外，环保举报热线应当保证畅通。"},{"i":5,"n":"第五条","txt":"承担环保举报热线工作机构的职责是： （一）依法受理环境污染、生态破坏的举报事项； （二）对举报件及时转送、交办、催办、督办; （三）向上级交办部门报告交办件的办理结果； （四）研究、分析环保举报热线工作情况，向环境保护主管部门提出改进工作的意见和建议； （五）向本级和上一级环境保护主管部门提交年度工作报告，报告举报事项受理情况以及举报件的转送、交办、答复、催办、督办等情况； （六）检查、指导和考核下级环保举报热线工作，总结交流工作经验，组织工作人员培训。 各地承担环保举报热线工作的机构可以根据实际情况依法履行其他工作职责，或者承担当地人民政府授予的其他职责。"},{"i":6,"n":"第六条","txt":"环保举报热线工作人员应当具备以下条件： （一）遵纪守法，政治立场坚定，熟悉环境保护业务，了解相关的法律、法规和政策，经业务培训并且考核合格； （二）热爱本职工作，有较强的事业心和责任感； （三）大专以上文化程度； （四）掌握受理举报事项的基本知识和技能，有较强的协调能力和沟通能力； （五）作风正派，实事求是； （六）严格遵守各项规章制度。"},{"i":7,"n":"第七条","txt":"环保举报热线工作人员接听举报电话，应当耐心细致，用语规范，准确据实记录举报时间、被举报单位的名称和地址、举报内容、举报人的姓名和联系方式、诉求目的等信息，并区分情况，分别按照下列方式处理： （一）对属于各级环境保护主管部门职责范围的环境污染和生态破坏的举报事项，应当予以受理。 （二）对不属于环境保护主管部门处理的举报事项不予受理，但应当告知举报人依法向有关机关提出。 （三）对依法应当通过诉讼、仲裁、行政复议等法定途径解决或者已经进入上述程序的，应当告知举报人依照有关法律、法规规定向有关机关和单位提出。 （四）举报事项已经受理，举报人再次提出同一举报事项的，不予受理，但应当告知举报人受理情况和办理结果的查询方式。 （五）举报人对环境保护主管部门做出的举报件答复不服，仍以同一事实和理由提出举报的，不予受理，但应当告知举报人可以依照《信访条例》的规定提请复查或者复核。 （六）对涉及突发环境事"},{"i":8,"n":"第八条","txt":"属于本级环境保护主管部门办理的举报件，承担环保举报热线工作的机构受理后，应当在3个工作日内转送本级环境保护主管部门有关内设机构。"},{"i":9,"n":"第九条","txt":"属于下级环境保护主管部门办理的举报件，承担环保举报热线工作的机构受理后，应当通过“12369”环保举报热线管理系统于3个工作日内向下级承担环保举报热线工作的机构交办。 地方各级环保举报热线工作人员应当即时接收上级交办的举报件，并按规定及时进行处理。"},{"i":10,"n":"第十条","txt":"举报件应当自受理之日起60日内办结。情况复杂的，经本级环境保护主管部门负责人批准，可以适当延长办理期限，并告知举报人延期理由，但延长期限不得超过30日。 对上级交办的举报件，下级承担环保举报热线工作的机构应当按照交办的时限要求办结，并将办理结果报告上级交办机构；情况复杂的，经本级环境保护主管部门负责人批准，并向交办机构说明情况，可以适当延长办理期限，并告知举报人延期理由。"},{"i":11,"n":"第十一条","txt":"举报件办结后，举报件办理部门应当将举报件办理结果及时答复举报人并转送承担环保举报热线工作的机构。 对上级交办的举报件，负责办理的下级环境保护主管部门应当在办理后及时将办理结果向上级交办机构报告；上级交办机构发现报告内容不全或者事实不清的，可以退回原办理部门重新办理。 举报件办理结果应当由环境保护主管部门负责人签发，并说明举报事项、查处情况、处理意见、答复情况等。"},{"i":12,"n":"第十二条","txt":"举报件办理部门未及时转送或者报告办理结果的，环保举报热线工作人员应当及时催办。"},{"i":13,"n":"第十三条","txt":"上级承担环保举报热线工作的机构发现向下级交办的举报件有下列情形之一的，应当向环境保护主管部门报告，由环境保护主管部门按照有关规定及时督办： （一）办结后处理决定未得到落实的； （二）问题久拖不决，群众反复举报的； （三）办理时弄虚作假的； （四）未按照规定程序办理的； （五）其他需要督办的情形。"},{"i":14,"n":"第十四条","txt":"各级承担环保举报热线工作的机构应当视情况抽查、回访已经办结的举报件，听取意见，改进工作。"},{"i":15,"n":"第十五条","txt":"各级环境保护主管部门应当建立健全环保举报热线工作规章制度，确保环保举报热线工作有章可循、规范有序。"},{"i":16,"n":"第十六条","txt":"各级承担环保举报热线工作的机构应当对各类举报信息和办理情况进行汇总、分析，提出建议，并向本级环境保护主管部门和上级承担环保举报热线工作的机构报告。"},{"i":17,"n":"第十七条","txt":"各级环境保护主管部门应当定期分析总结环保举报热线工作情况，并根据工作需要，向有关单位和部门通报。"},{"i":18,"n":"第十八条","txt":"各级环境保护主管部门应当通过电视、报刊、网络等媒体宣传环保举报热线，提高公众的参与意识和监督意识。"},{"i":19,"n":"第十九条","txt":"各级环境保护主管部门应当定期组织开展环保举报热线工作人员政治理论学习和业务工作培训，加强队伍建设，不断提高工作人员的思想觉悟和业务水平。"},{"i":20,"n":"第二十条","txt":"各级承担环保举报热线工作的机构应当健全保密管理制度，完善保密防护措施，加强保密检查，并积极开展保密宣传教育。"},{"i":21,"n":"第二十一条","txt":"各级承担环保举报热线工作的机构应当妥善保存相关书面材料或者录音资料，并按照档案管理的有关规范建立档案。"},{"i":22,"n":"第二十二条","txt":"各级环境保护主管部门应当结合本单位工作实际，制定环保举报热线工作表彰和奖励制度，对事迹突出、成绩显著的工作人员或者单位给予表彰和奖励。"},{"i":23,"n":"第二十三条","txt":"各级环境保护主管部门应当积极争取当地财政部门资金支持，将环保举报热线的建设、运行、管理、维护等资金纳入财政预算，确保环保举报热线工作及其管理系统正常运行。"},{"i":24,"n":"第二十四条","txt":"各级环境保护主管部门以及环保举报热线工作人员玩忽职守、滥用职权、徇私舞弊的，依法给予处分；涉嫌犯罪的，依法移送司法机关追究刑事责任。 环境保护主管部门及其工作人员对举报人进行打击报复的，依法给予处分；涉嫌犯罪的，依法移送司法机关追究刑事责任。"},{"i":25,"n":"第二十五条","txt":"本办法未作规定的事项，按照《信访条例》和《环境信访办法》的有关规定执行。 地方各级环境保护主管部门可以结合本地实际情况制定实施细则。"},{"i":26,"n":"第二十六条","txt":"本办法自2011年3月1日起施行。"}],"huanjingbaohuzhuguanbumenshishianrilianxuchufabanf874f8f":[{"i":1,"n":"第一条","txt":"为规范实施按日连续处罚，依据《中华人民共和国环境保护法》、《中华人民共和国行政处罚法》等法律，制定本办法。"},{"i":2,"n":"第二条","txt":"县级以上环境保护主管部门对企业事业单位和其他生产经营者（以下称排污者）实施按日连续处罚的，适用本办法。"},{"i":3,"n":"第三条","txt":"实施按日连续处罚，应当坚持教育与处罚相结合的原则，引导和督促排污者及时改正环境违法行为。"},{"i":4,"n":"第四条","txt":"环境保护主管部门实施按日连续处罚，应当依法向社会公开行政处罚决定和责令改正违法行为决定等相关信息。"},{"i":5,"n":"第五条","txt":"排污者有下列行为之一，受到罚款处罚，被责令改正,拒不改正的，依法作出罚款处罚决定的环境保护主管部门可以实施按日连续处罚： （一）超过国家或者地方规定的污染物排放标准，或者超过重点污染物排放总量控制指标排放污染物的； （二）通过暗管、渗井、渗坑、灌注或者篡改、伪造监测数据，或者不正常运行防治污染设施等逃避监管的方式排放污染物的； （三）排放法律、法规规定禁止排放的污染物的； （四）违法倾倒危险废物的； （五）其他违法排放污染物行为。"},{"i":6,"n":"第六条","txt":"地方性法规可以根据环境保护的实际需要, 增加按日连续处罚的违法行为的种类。"},{"i":7,"n":"第七条","txt":"环境保护主管部门检查发现排污者违法排放污染物的，应当进行调查取证,并依法作出行政处罚决定。 按日连续处罚决定应当在前款规定的行政处罚决定之后作出。"},{"i":8,"n":"第八条","txt":"环境保护主管部门可以当场认定违法排放污染物的，应当在现场调查时向排污者送达责令改正违法行为决定书，责令立即停止违法排放污染物行为。 需要通过环境监测认定违法排放污染物的，环境监测机构应当按照监测技术规范要求进行监测。环境保护主管部门应当在取得环境监测报告后三个工作日内向排污者送达责令改正违法行为决定书，责令立即停止违法排放污染物行为。"},{"i":9,"n":"第九条","txt":"责令改正违法行为决定书应当载明下列事项： （一）排污者的基本情况，包括名称或者姓名、营业执照号码或者居民身份证号码、组织机构代码、地址以及法定代表人或者主要负责人姓名等； （二）环境违法事实和证据； （三）违反法律、法规或者规章的具体条款和处理依据； （四）责令立即改正的具体内容； （五）拒不改正可能承担按日连续处罚的法律后果； （六）申请行政复议或者提起行政诉讼的途径和期限； （七）环境保护主管部门的名称、印章和决定日期。"},{"i":10,"n":"第十条","txt":"环境保护主管部门应当在送达责令改正违法行为决定书之日起三十日内，以暗查方式组织对排污者违法排放污染物行为的改正情况实施复查。"},{"i":11,"n":"第十一条","txt":"排污者在环境保护主管部门实施复查前，可以向作出责令改正违法行为决定书的环境保护主管部门报告改正情况，并附具相关证明材料。"},{"i":12,"n":"第十二条","txt":"环境保护主管部门复查时发现排污者拒不改正违法排放污染物行为的，可以对其实施按日连续处罚。 环境保护主管部门复查时发现排污者已经改正违法排放污染物行为或者已经停产、停业、关闭的，不启动按日连续处罚。"},{"i":13,"n":"第十三条","txt":"排污者具有下列情形之一的，认定为拒不改正： （一）责令改正违法行为决定书送达后,环境保护主管部门复查发现仍在继续违法排放污染物的； （二）拒绝、阻挠环境保护主管部门实施复查的。"},{"i":14,"n":"第十四条","txt":"复查时排污者被认定为拒不改正违法排放污染物行为的，环境保护主管部门应当按照本办法第八条的规定再次作出责令改正违法行为决定书并送达排污者，责令立即停止违法排放污染物行为，并应当依照本办法第十条、第十二条的规定对排污者再次进行复查。"},{"i":15,"n":"第十五条","txt":"环境保护主管部门实施按日连续处罚应当符合法律规定的行政处罚程序。"},{"i":16,"n":"第十六条","txt":"环境保护主管部门决定实施按日连续处罚的，应当依法作出处罚决定书。 处罚决定书应当载明下列事项： （一）排污者的基本情况，包括名称或者姓名、营业执照号码或者居民身份证号码、组织机构代码、地址以及法定代表人或者主要负责人姓名等； （二）初次检查发现的环境违法行为及该行为的原处罚决定、拒不改正的违法事实和证据； （三）按日连续处罚的起止时间和依据； （四）按照按日连续处罚规则决定的罚款数额; （五）按日连续处罚的履行方式和期限； （六）申请行政复议或者提起行政诉讼的途径和期限； （七）环境保护主管部门名称、印章和决定日期。"},{"i":17,"n":"第十七条","txt":"按日连续处罚的计罚日数为责令改正违法行为决定书送达排污者之日的次日起，至环境保护主管部门复查发现违法排放污染物行为之日止。再次复查仍拒不改正的，计罚日数累计执行。"},{"i":18,"n":"第十八条","txt":"再次复查时违法排放污染物行为已经改正，环境保护主管部门在之后的检查中又发现排污者有本办法第五条规定的情形的，应当重新作出处罚决定，按日连续处罚的计罚周期重新起算。按日连续处罚次数不受限制。"},{"i":19,"n":"第十九条","txt":"按日连续处罚每日的罚款数额，为原处罚决定书确定的罚款数额。 按照按日连续处罚规则决定的罚款数额，为原处罚决定书确定的罚款数额乘以计罚日数。"},{"i":20,"n":"第二十条","txt":"环境保护主管部门针对违法排放污染物行为实施按日连续处罚的，可以同时适用责令排污者限制生产、停产整治或者查封、扣押等措施；因采取上述措施使排污者停止违法排污行为的，不再实施按日连续处罚。"},{"i":21,"n":"第二十一条","txt":"本办法由国务院环境保护主管部门负责解释。"},{"i":22,"n":"第二十二条","txt":"本办法自2015年1月1日起施行。"}],"huanjingbaohuzhuguanbumenshishichafengkouyabanfa":[{"i":1,"n":"第一条","txt":"为规范实施查封、扣押，依据《中华人民共和国环境保护法》、《中华人民共和国行政强制法》等法律，制定本办法。"},{"i":2,"n":"第二条","txt":"对企业事业单位和其他生产经营者（以下称排污者）违反法律法规规定排放污染物，造成或者可能造成严重污染，县级以上环境保护主管部门对造成污染物排放的设施、设备实施查封、扣押的，适用本办法。"},{"i":3,"n":"第三条","txt":"环境保护主管部门实施查封、扣押所需经费，应当列入本机关的行政经费预算，由同级财政予以保障。"},{"i":4,"n":"第四条","txt":"排污者有下列情形之一的，环境保护主管部门依法实施查封、扣押： （一）违法排放、倾倒或者处置含传染病病原体的废物、危险废物、含重金属污染物或者持久性有机污染物等有毒物质或者其他有害物质的； （二）在饮用水水源一级保护区、自然保护区核心区违反法律法规规定排放、倾倒、处置污染物的； （三）违反法律法规规定排放、倾倒化工、制药、石化、印染、电镀、造纸、制革等工业污泥的； （四）通过暗管、渗井、渗坑、灌注或者篡改、伪造监测数据，或者不正常运行防治污染设施等逃避监管的方式违反法律法规规定排放污染物的； （五）较大、重大和特别重大突发环境事件发生后，未按照要求执行停产、停排措施，继续违反法律法规规定排放污染物的； （六）法律、法规规定的其他造成或者可能造成严重污染的违法排污行为。 有前款第一项、第二项、第三项、第六项情形之一的，环境保护主管部门可以实施查封、扣押；已造成严重污染或者有前款第四项、第五"},{"i":5,"n":"第五条","txt":"环境保护主管部门查封、扣押排污者造成污染物排放的设施、设备，应当符合有关法律的规定。不得重复查封、扣押排污者已被依法查封的设施、设备。 对不易移动的或者有特殊存放要求的设施、设备，应当就地查封。查封时，可以在该设施、设备的控制装置等关键部件或者造成污染物排放所需供水、供电、供气等开关阀门张贴封条。"},{"i":6,"n":"第六条","txt":"具备下列情形之一的排污者，造成或者可能造成严重污染的，环境保护主管部门应当按照有关环境保护法律法规予以处罚，可以不予实施查封、扣押： （一）城镇污水处理、垃圾处理、危险废物处置等公共设施的运营单位； （二）生产经营业务涉及基本民生、公共利益的； （三）实施查封、扣押可能影响生产安全的。"},{"i":7,"n":"第七条","txt":"环境保护主管部门实施查封、扣押的，应当依法向社会公开查封、扣押决定，查封、扣押延期情况和解除查封、扣押决定等相关信息。"},{"i":8,"n":"第八条","txt":"实施查封、扣押的程序包括调查取证、审批、决定、执行、送达、解除。"},{"i":9,"n":"第九条","txt":"环境保护主管部门实施查封、扣押前，应当做好调查取证工作。 查封、扣押的证据包括现场检查笔录、调查询问笔录、环境监测报告、视听资料、证人证言和其他证明材料。"},{"i":10,"n":"第十条","txt":"需要实施查封、扣押的，应当书面报经环境保护主管部门负责人批准；案情重大或者社会影响较大的，应当经环境保护主管部门案件审查委员会集体审议决定。"},{"i":11,"n":"第十一条","txt":"环境保护主管部门决定实施查封、扣押的，应当制作查封、扣押决定书和清单。 查封、扣押决定书应当载明下列事项： （一）排污者的基本情况，包括名称或者姓名、营业执照号码或者居民身份证号码、组织机构代码、地址以及法定代表人或者主要负责人姓名等； （二）查封、扣押的依据和期限； （三）查封、扣押设施、设备的名称、数量和存放地点等； （四）排污者应当履行的相关义务及申请行政复议或者提起行政诉讼的途径和期限； （五）环境保护主管部门的名称、印章和决定日期。"},{"i":12,"n":"第十二条","txt":"实施查封、扣押应当符合下列要求： （一）由两名以上具有行政执法资格的环境行政执法人员实施，并出示执法身份证件； （二）通知排污者的负责人或者受委托人到场，当场告知实施查封、扣押的依据以及依法享有的权利、救济途径，并听取其陈述和申辩； （三）制作现场笔录，必要时可以进行现场拍摄。现场笔录的内容应当包括查封、扣押实施的起止时间和地点等； （四）当场清点并制作查封、扣押设施、设备清单，由排污者和环境保护主管部门分别收执。委托第三人保管的，应同时交第三人收执。执法人员可以对上述过程进行现场拍摄； （五）现场笔录和查封、扣押设施、设备清单由排污者和执法人员签名或者盖章； （六）张贴封条或者采取其他方式，明示环境保护主管部门已实施查封、扣押。"},{"i":13,"n":"第十三条","txt":"情况紧急，需要当场实施查封、扣押的，应当在实施后二十四小时内补办批准手续。环境保护主管部门负责人认为不需要实施查封、扣押的，应当立即解除。"},{"i":14,"n":"第十四条","txt":"查封、扣押决定书应当当场交付排污者负责人或者受委托人签收。排污者负责人或者受委托人应当签名或者盖章，注明日期。 实施查封、扣押过程中，排污者负责人或者受委托人拒不到场或者拒绝签名、盖章的，环境行政执法人员应当予以注明，并可以邀请见证人到场，由见证人和环境行政执法人员签名或者盖章。"},{"i":15,"n":"第十五条","txt":"查封、扣押的期限不得超过三十日；情况复杂的，经本级环境保护主管部门负责人批准可以延长，但延长期限不得超过三十日。法律、法规另有规定的除外。 延长查封、扣押的决定应当及时书面告知排污者，并说明理由。"},{"i":16,"n":"第十六条","txt":"对就地查封的设施、设备，排污者应当妥善保管，不得擅自损毁封条、变更查封状态或者启用已查封的设施、设备。 对扣押的设施、设备，环境保护主管部门应当妥善保管，也可以委托第三人保管。扣押期间设施、设备的保管费用由环境保护主管部门承担。"},{"i":17,"n":"第十七条","txt":"查封的设施、设备造成损失的，由排污者承担。扣押的设施、设备造成损失的，由环境保护主管部门承担；因受委托第三人原因造成损失的，委托的环境保护主管部门先行赔付后，可以向受委托第三人追偿。"},{"i":18,"n":"第十八条","txt":"排污者在查封、扣押期限届满前，可以向决定实施查封、扣押的环境保护主管部门提出解除申请，并附具相关证明材料。"},{"i":19,"n":"第十九条","txt":"环境保护主管部门应当自收到解除查封、扣押申请之日起五个工作日内，组织核查，并根据核查结果分别作出如下决定： （一）确已改正违反法律法规规定排放污染物行为的，解除查封、扣押； （二）未改正违反法律法规规定排放污染物行为的，维持查封、扣押。"},{"i":20,"n":"第二十条","txt":"环境保护主管部门实施查封、扣押后，应当及时查清事实，有下列情形之一的，应当立即作出解除查封、扣押决定： （一）对违反法律法规规定排放污染物行为已经作出行政处罚或者处理决定，不再需要实施查封、扣押的； （二）查封、扣押期限已经届满的； （三）其他不再需要实施查封、扣押的情形。"},{"i":21,"n":"第二十一条","txt":"查封、扣押措施被解除的，环境保护主管部门应当立即通知排污者，并自解除查封、扣押决定作出之日起三个工作日内送达解除决定。 扣押措施被解除的，还应当通知排污者领回扣押物；无法通知的，应当进行公告，排污者应当自招领公告发布之日起六十日内领回；逾期未领回的，所造成的损失由排污者自行承担。 扣押物无法返还的，环境保护主管部门可以委托拍卖机构依法拍卖或者变卖，所得款项上缴国库。"},{"i":22,"n":"第二十二条","txt":"排污者涉嫌环境污染犯罪已由公安机关立案侦查的，环境保护主管部门应当依法移送查封、扣押的设施、设备及有关法律文书、清单。"},{"i":23,"n":"第二十三条","txt":"环境保护主管部门对查封后的设施、设备应当定期检视其封存情况。 排污者阻碍执法、擅自损毁封条、变更查封状态或者隐藏、转移、变卖、启用已查封的设施、设备的，环境保护主管部门应当依据《中华人民共和国治安管理处罚法》等法律法规及时提请公安机关依法处理。"},{"i":24,"n":"第二十四条","txt":"本办法由国务院环境保护主管部门负责解释。"},{"i":25,"n":"第二十五条","txt":"本办法自2015年1月1日起施行。"}],"huanjingbaohuzhuguanbumenshishixianzhishengchantin3134c9":[{"i":1,"n":"第一条","txt":"为规范实施限制生产、停产整治措施，依据《中华人民共和国环境保护法》，制定本办法。"},{"i":2,"n":"第二条","txt":"县级以上环境保护主管部门对超过污染物排放标准或者超过重点污染物排放总量控制指标排放污染物的企业事业单位和其他生产经营者（以下称排污者），责令采取限制生产、停产整治措施的，适用本办法。"},{"i":3,"n":"第三条","txt":"环境保护主管部门作出限制生产、停产整治决定时，应当责令排污者改正或者限期改正违法行为，并依法实施行政处罚。"},{"i":4,"n":"第四条","txt":"环境保护主管部门实施限制生产、停产整治的，应当依法向社会公开限制生产、停产整治决定，限制生产延期情况和解除限制生产、停产整治的日期等相关信息。"},{"i":5,"n":"第五条","txt":"排污者超过污染物排放标准或者超过重点污染物日最高允许排放总量控制指标的，环境保护主管部门可以责令其采取限制生产措施。"},{"i":6,"n":"第六条","txt":"排污者有下列情形之一的,环境保护主管部门可以责令其采取停产整治措施: （一）通过暗管、渗井、渗坑、灌注或者篡改、伪造监测数据，或者不正常运行防治污染设施等逃避监管的方式排放污染物，超过污染物排放标准的； （二）非法排放含重金属、持久性有机污染物等严重危害环境、损害人体健康的污染物超过污染物排放标准三倍以上的； （三）超过重点污染物排放总量年度控制指标排放污染物的； （四） 被责令限制生产后仍然超过污染物排放标准排放污染物的； （五） 因突发事件造成污染物排放超过排放标准或者重点污染物排放总量控制指标的； （六）法律、法规规定的其他情形。"},{"i":7,"n":"第七条","txt":"具备下列情形之一的排污者，超过污染物排放标准或者超过重点污染物排放总量控制指标排放污染物的，环境保护主管部门应当按照有关环境保护法律法规予以处罚，可以不予实施停产整治： （一）城镇污水处理、垃圾处理、危险废物处置等公共设施的运营单位； （二）生产经营业务涉及基本民生、公共利益的； （三）实施停产整治可能影响生产安全的。"},{"i":8,"n":"第八条","txt":"排污者有下列情形之一的，由环境保护主管部门报经有批准权的人民政府责令停业、关闭： （一）两年内因排放含重金属、持久性有机污染物等有毒物质超过污染物排放标准受过两次以上行政处罚，又实施前列行为的； （二）被责令停产整治后拒不停产或者擅自恢复生产的； （三）停产整治决定解除后，跟踪检查发现又实施同一违法行为的； （四）法律法规规定的其他严重环境违法情节的。"},{"i":9,"n":"第九条","txt":"环境保护主管部门在作出限制生产、停产整治决定前，应当做好调查取证工作。 责令限制生产、停产整治的证据包括现场检查笔录、调查询问笔录、环境监测报告、视听资料、证人证言和其他证明材料。"},{"i":10,"n":"第十条","txt":"作出限制生产、停产整治决定前，应当书面报经环境保护主管部门负责人批准；案情重大或者社会影响较大的，应当经环境保护主管部门案件审查委员会集体审议决定。"},{"i":11,"n":"第十一条","txt":"环境保护主管部门作出限制生产、停产整治决定前，应当告知排污者有关事实、依据及其依法享有的陈述、申辩或者要求举行听证的权利；就同一违法行为进行行政处罚的，可以在行政处罚事先告知书或者行政处罚听证告知书中一并告知。"},{"i":12,"n":"第十二条","txt":"环境保护主管部门作出限制生产、停产整治决定的，应当制作责令限制生产决定书或者责令停产整治决定书，也可以在行政处罚决定书中载明。"},{"i":13,"n":"第十三条","txt":"责令限制生产决定书和责令停产整治决定书应当载明下列事项： （一）排污者的基本情况，包括名称或者姓名、营业执照号码或者居民身份证号码、组织机构代码、地址以及法定代表人或者主要负责人姓名等； （二）违法事实、证据，以及作出限制生产、停产整治决定的依据； （三）责令限制生产、停产整治的改正方式、期限； （四） 排污者应当履行的相关义务及申请行政复议或者提起行政诉讼的途径和期限； （五）环境保护主管部门的名称、印章和决定日期。"},{"i":14,"n":"第十四条","txt":"环境保护主管部门应当自作出限制生产、停产整治决定之日起七个工作日内将决定书送达排污者。"},{"i":15,"n":"第十五条","txt":"限制生产一般不超过三个月；情况复杂的，经本级环境保护主管部门负责人批准，可以延长，但延长期限不得超过三个月。 停产整治的期限，自责令停产整治决定书送达排污者之日起，至停产整治决定解除之日止。"},{"i":16,"n":"第十六条","txt":"排污者应当在收到责令限制生产决定书或者责令停产整治决定书后立即整改，并在十五个工作日内将整改方案报作出决定的环境保护主管部门备案并向社会公开。整改方案应当确定改正措施、工程进度、资金保障和责任人员等事项。 被限制生产的排污者在整改期间，不得超过污染物排放标准或者重点污染物日最高允许排放总量控制指标排放污染物，并按照环境监测技术规范进行监测或者委托有条件的环境监测机构开展监测，保存监测记录。"},{"i":17,"n":"第十七条","txt":"排污者完成整改任务的，应当在十五个工作日内将整改任务完成情况和整改信息社会公开情况，报作出限制生产、停产整治决定的环境保护主管部门备案，并提交监测报告以及整改期间生产用电量、用水量、主要产品产量与整改前的对比情况等材料。限制生产、停产整治决定自排污者报环境保护主管部门备案之日起解除。"},{"i":18,"n":"第十八条","txt":"排污者有下列情形之一的，限制生产、停产整治决定自行终止： （一）依法被撤销、解散、宣告破产或者因其他原因终止营业的； （二）被有批准权的人民政府依法责令停业、关闭的。"},{"i":19,"n":"第十九条","txt":"排污者被责令限制生产、停产整治后，环境保护主管部门应当按照相关规定对排污者履行限制生产、停产整治措施的情况实施后督察，并依法进行处理或者处罚。"},{"i":20,"n":"第二十条","txt":"排污者解除限制生产、停产整治后，环境保护主管部门应当在解除之日起三十日内对排污者进行跟踪检查。"},{"i":21,"n":"第二十一条","txt":"本办法由国务院环境保护主管部门负责解释。"},{"i":22,"n":"第二十二条","txt":"本办法自2015年1月1日起施行。"}],"huanjingbaohugongzhongcanyubanfa":[{"i":1,"n":"第一条","txt":"为保障公民、法人和其他组织获取环境信息、参与和监督环境保护的权利，畅通参与渠道，促进环境保护公众参与依法有序发展，根据《环境保护法》及有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于公民、法人和其他组织参与制定政策法规、实施行政许可或者行政处罚、监督违法行为、开展宣传教育等环境保护公共事务的活动。"},{"i":3,"n":"第三条","txt":"环境保护公众参与应当遵循依法、有序、自愿、便利的原则。"},{"i":4,"n":"第四条","txt":"环境保护主管部门可以通过征求意见、问卷调查，组织召开座谈会、专家论证会、听证会等方式征求公民、法人和其他组织对环境保护相关事项或者活动的意见和建议。 公民、法人和其他组织可以通过电话、信函、传真、网络等方式向环境保护主管部门提出意见和建议。"},{"i":5,"n":"第五条","txt":"环境保护主管部门向公民、法人和其他组织征求意见时，应当公布以下信息： （一）相关事项或者活动的背景资料； （二）征求意见的起止时间； （三）公众提交意见和建议的方式； （四）联系部门和联系方式。 公民、法人和其他组织应当在征求意见的时限内提交书面意见和建议。"},{"i":6,"n":"第六条","txt":"环境保护主管部门拟组织问卷调查征求意见的，应当对相关事项的基本情况进行说明。调查问卷所设问题应当简单明确、通俗易懂。调查的人数及其范围应当综合考虑相关事项或者活动的环境影响范围和程度、社会关注程度、组织公众参与所需要的人力和物力资源等因素。"},{"i":7,"n":"第七条","txt":"环境保护主管部门拟组织召开座谈会、专家论证会征求意见的，应当提前将会议的时间、地点、议题、议程等事项通知参会人员，必要时可以通过政府网站、主要媒体等途径予以公告。 参加专家论证会的参会人员应当以相关专业领域专家、环保社会组织中的专业人士为主，同时应当邀请可能受相关事项或者活动直接影响的公民、法人和其他组织的代表参加。"},{"i":8,"n":"第八条","txt":"法律、法规规定应当听证的事项，环境保护主管部门应当向社会公告，并举行听证。 环境保护主管部门组织听证应当遵循公开、公平、公正和便民的原则，充分听取公民、法人和其他组织的意见，并保证其陈述意见、质证和申辩的权利。 除涉及国家秘密、商业秘密或者个人隐私外，听证应当公开举行。"},{"i":9,"n":"第九条","txt":"环境保护主管部门应当对公民、法人和其他组织提出的意见和建议进行归类整理、分析研究，在作出环境决策时予以充分考虑，并以适当的方式反馈公民、法人和其他组织。"},{"i":10,"n":"第十条","txt":"环境保护主管部门支持和鼓励公民、法人和其他组织对环境保护公共事务进行舆论监督和社会监督。"},{"i":11,"n":"第十一条","txt":"公民、法人和其他组织发现任何单位和个人有污染环境和破坏生态行为的，可以通过信函、传真、电子邮件、“12369”环保举报热线、政府网站等途径，向环境保护主管部门举报。"},{"i":12,"n":"第十二条","txt":"公民、法人和其他组织发现地方各级人民政府、县级以上环境保护主管部门不依法履行职责的，有权向其上级机关或者监察机关举报。"},{"i":13,"n":"第十三条","txt":"接受举报的环境保护主管部门应当依照有关法律、法规规定调查核实举报的事项，并将调查情况和处理结果告知举报人。"},{"i":14,"n":"第十四条","txt":"接受举报的环境保护主管部门应当对举报人的相关信息予以保密，保护举报人的合法权益。"},{"i":15,"n":"第十五条","txt":"对保护和改善环境有显著成绩的单位和个人，依法给予奖励。 国家鼓励县级以上环境保护主管部门推动有关部门设立环境保护有奖举报专项资金。"},{"i":16,"n":"第十六条","txt":"环境保护主管部门可以通过提供法律咨询、提交书面意见、协助调查取证等方式，支持符合法定条件的环保社会组织依法提起环境公益诉讼。"},{"i":17,"n":"第十七条","txt":"环境保护主管部门应当在其职责范围内加强宣传教育工作，普及环境科学知识，增强公众的环保意识、节约意识；鼓励公众自觉践行绿色生活、绿色消费，形成低碳节约、保护环境的社会风尚。"},{"i":18,"n":"第十八条","txt":"环境保护主管部门可以通过项目资助、购买服务等方式，支持、引导社会组织参与环境保护活动。"},{"i":19,"n":"第十九条","txt":"法律、法规和环境保护部制定的其他部门规章对环境保护公众参与另有规定的，从其规定。"},{"i":20,"n":"第二十条","txt":"本办法自2015年9月1日起施行。"}],"huanjingbaohudanganguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强环境保护档案的形成、管理和保护工作，开发利用环境保护档案信息资源，根据《中华人民共和国档案法》及其实施办法、《中华人民共和国环境保护法》等相关法律法规，结合环境保护工作实际，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称环境保护档案，是指各级环境保护主管部门及其派出机构、直属单位（以下简称环境保护部门），在环境保护各项工作和活动中形成的，对国家、社会和单位具有利用价值、应当归档保存的各种形式和载体的历史记录，主要包括文书档案、音像（照片、录音、录像）档案、科技档案、会计档案、人事档案、基建档案及电子档案等。"},{"i":3,"n":"第三条","txt":"环境保护档案工作是环境保护部门的重要职责，实行统一领导、分级管理。"},{"i":4,"n":"第四条","txt":"国务院环境保护主管部门对环境保护档案管理工作实行监督和指导，在业务上接受国家档案行政管理部门的监督和指导。 地方各级环境保护主管部门对本行政区域内环境保护档案管理工作实行监督和指导，在业务上接受同级档案行政管理部门和上级环境保护主管部门的监督和指导。"},{"i":5,"n":"第五条","txt":"环境保护部门应当加强对档案工作的领导，完善档案工作管理体制，确定档案机构或者档案工作人员负责管理本单位的档案，并对所属单位的档案工作实行监督和指导。"},{"i":6,"n":"第六条","txt":"环境保护部门应当将档案工作纳入本部门发展规划和年度工作计划，列入工作考核检查内容，及时研究并协调解决档案工作中的重大问题，确保档案工作与本部门整体工作同步协调发展。"},{"i":7,"n":"第七条","txt":"环境保护部门应当按照部门预算编制和管理的有关规定，科学合理核定档案工作经费，并列入同级财政预算，加强对档案工作经费的审计和绩效考核，确保科学使用、专款专用。"},{"i":8,"n":"第八条","txt":"环境保护部门应当按照国家有关档案管理的规定，确定文件材料的具体接收范围，包括本部门在各项工作和活动中形成的具有利用价值、应当归档保存的各种形式和载体的历史记录，以及与本部门有关的撤销或者合并部门的全部档案。"},{"i":9,"n":"第九条","txt":"环境保护部门应当将档案信息化建设纳入本部门信息化建设同步实施，推进文档一体化管理，实现资源数字化、利用网络化、管理智能化。"},{"i":10,"n":"第十条","txt":"环境保护部门应当为开展档案管理工作提供必要条件。档案管理人员办公室、档案库房、阅档室和档案整理间应当分开。"},{"i":11,"n":"第十一条","txt":"环境保护部门应当加强档案基础设施建设，改善档案安全管理条件，提供符合设计规范的专用库房，配备防盗、防火、防潮、防水、防尘、防光、防鼠、防虫等安全设施，以及计算机、复印机、打印机、扫描仪、照相机、摄像机、防磁柜等工作设备。"},{"i":12,"n":"第十二条","txt":"环境保护部门应当将档案管理人员培训、交流、使用列入干部培养和选拔任用统一规划，统筹安排，为档案管理人员学习培训、挂职锻炼、交流任职等创造条件。档案管理人员的职务晋升或者职称评定、业务能力考核，按照国家有关规定执行，并享有专业人员的同等待遇。"},{"i":13,"n":"第十三条","txt":"环境保护部门应当按照《中华人民共和国保守国家秘密法》等有关法律法规，确保环境保护档案安全保密和有效利用。"},{"i":14,"n":"第十四条","txt":"环境保护部门的档案管理机构应当履行下列职责: （一）贯彻执行国家档案法律法规和工作方针、政策。经国家档案行政管理部门同意，国务院环境保护主管部门的档案管理机构负责研究制定环境保护档案管理规章制度、行业标准和技术规范并组织实施。地方各级环境保护主管部门的档案管理机构依据上级环境保护主管部门和档案行政管理部门的相关制度要求，制定本行政区域内环境保护档案管理工作制度并组织实施。 （二）负责本部门档案的统一管理，地方各级环境保护主管部门的档案管理机构对本行政区域内环境保护档案管理工作进行监督和指导。 （三）负责编制本部门档案管理经费年度预算，将档案资料收集整理、保管保护、开发利用，设备购置和运行维护，信息化建设，以及档案宣传培训等项目经费列入预算。 （四）负责本部门档案信息化工作，参与本部门电子文件全过程管理工作，组织实施本部门档案数字化加工、电子文件归档和电子档案管理以及重要档案异地、异质备"},{"i":15,"n":"第十五条","txt":"环境保护部门的文件（项目）承办单位在本部门档案管理机构的指导下，履行下列职责： （一）负责本单位文件（项目）材料的收集、整理和归档。 （二）负责督促指导文件（项目）承办人分类整理文件材料，做到齐全完整、分类清楚、排列有序，并按照规定向本部门档案管理机构移交。 （三）重大建设项目、重大科研项目、重大生态保护项目承办单位负责制定专项档案管理规定、归档范围和保管期限，报环境保护部门的档案管理机构同意后，由项目承办单位组织实施。"},{"i":16,"n":"第十六条","txt":"环境保护文件材料归档范围应当全面、系统地反映综合管理和政策法规、科学技术、环境影响评价、环境监测、污染防治、生态保护、核与辐射安全监管、环境监察执法等业务活动。"},{"i":17,"n":"第十七条","txt":"环境保护部门在部署污染源普查、环境质量调查等专项工作时，应当明确文件材料的归档要求；在检查专项工作进度时，应当检查文件材料的收集、整理情况；重大建设项目、重大科研项目和重大生态保护项目文件材料不符合归档要求的，不得进行项目鉴定、验收和申报奖项。"},{"i":18,"n":"第十八条","txt":"环境保护文件材料归档工作一般应于次年3月底前完成。文件（项目）承办单位根据下列情形，按要求将应归档文件及电子文件同步移交本部门档案管理机构进行归档，任何人不得据为己有或者拒绝归档： （一）文书材料应当在文件办理完毕后及时归档； （二）重大会议和活动等文件材料，应当在会议和活动结束后一个月内归档； （三）科研项目、建设项目文件材料应当在成果鉴定和项目验收后两个月内归档，周期较长的科研项目、建设项目可以按完成阶段分期归档； （四）一般仪器设备随机文件材料，应当在开箱验收或者安装调试后七日内归档，重要仪器设备开箱验收应当由档案管理人员现场监督随机文件材料归档。"},{"i":19,"n":"第十九条","txt":"环境保护部门应当加强对不同门类、各种形式和载体档案的管理，确保环境保护档案真实、齐全、完整。"},{"i":20,"n":"第二十条","txt":"环境保护档案的分类、著录、标引，依照《中国档案分类法 环境保护档案分类表》《环境保护档案著录细则》《环境保护档案管理规范》等文件的有关规定执行，其相应的电子文件材料应当按照有关要求同步归档。 文书材料的整理归档，依照《归档文件整理规则》（DA/T 22-2015）的有关规定执行。 照片资料的整理归档，依照《照片档案管理规范》（GB/T 11821-2002）的有关规定执行。 录音、录像资料的整理归档，依照录音、录像管理的有关规定执行。 科技文件的整理归档，依照《科学技术档案案卷构成的一般要求》（GB/T 11822-2008）的有关规定执行。 会计资料的整理归档，依照《会计档案管理办法》（财政部、国家档案局令第79号）的有关规定执行。 人事文件材料的整理归档，依照《干部档案工作条例》（组通字〔1991〕13号）、《干部档案整理工作细则》（组通字〔1991〕11号）、《干部人事档案材料收"},{"i":21,"n":"第二十一条","txt":"环境保护部门的档案管理机构应当定期检查档案保管状态，调试库房温度、湿度，及时对破损或者变质的档案进行修复。"},{"i":22,"n":"第二十二条","txt":"环境保护档案的鉴定应当定期进行。 环境保护部门成立环境保护档案鉴定小组进行鉴定工作，鉴定小组由环境保护部门分管档案工作的负责人、办公厅（室）负责人，以及档案管理机构、保密部门和文件（项目）承办单位有关人员组成。 对保管期限变动、密级调整和需要销毁的档案，应当提请本部门环境保护档案鉴定小组鉴定。鉴定工作结束后，环境保护档案鉴定小组应当形成鉴定报告，提出鉴定意见。"},{"i":23,"n":"第二十三条","txt":"环境保护档案的销毁应当按照相关规定办理，并履行销毁批准手续。未经鉴定、未履行批准销毁手续的档案，严禁销毁。 对经过环境保护档案鉴定小组鉴定确认无保存价值需要销毁的档案，应当进行登记造册，报本部门分管档案工作负责人批准后销毁。档案销毁清册永久保存。 环境保护档案的销毁由档案管理机构组织实施。销毁档案时，档案管理机构与保密部门应当分别指派人员共同进行现场监督，并在销毁清册上签字确认。档案销毁后，应当及时调整档案柜（架），并在目录及检索工具中注明。"},{"i":24,"n":"第二十四条","txt":"环境保护部门撤销或者变动时，应当妥善保管环境保护档案，向相关接收部门或者同级档案管理部门移交，并向上级环境保护主管部门报告。"},{"i":25,"n":"第二十五条","txt":"文件（项目）承办单位的工作人员退休或者工作岗位变动时，应当及时对属于归档范围的文件材料进行整理、归档，并办理移交手续，不得带走或者毁弃。"},{"i":26,"n":"第二十六条","txt":"环境保护部门的档案管理机构应当积极开发环境保护档案信息资源，并根据环境保护工作实际需要，对现有档案信息资源进行综合加工和深度开发，为环境保护工作提供服务。"},{"i":27,"n":"第二十七条","txt":"环境保护部门应当积极开展环境保护档案的利用工作，建立健全档案利用制度，明确相应的利用范围和审批程序，确保档案合理利用。"},{"i":28,"n":"第二十八条","txt":"环境保护档案一般以数字副本代替档案原件提供利用。档案原件原则上不得带出档案室。 利用环境保护档案的单位或者个人应当负责所利用档案的安全和保密，不得擅自转借，不得对档案原件进行折叠、剪贴、抽取、拆散，严禁在档案原件上勾画、涂抹、填注、加字、改字，或者以其他方式损毁档案。"},{"i":29,"n":"第二十九条","txt":"有下列事迹之一的，依照国家有关规定给予表扬、表彰或者奖励： （一）在环境保护档案的收集、整理或者开发利用等方面做出显著成绩的; （二）对环境保护档案的保护和现代化管理做出显著成绩的； （三）将个人所有的具有重要或者珍贵价值的环境保护档案捐赠给国家的； （四）执行档案法律法规表现突出的。"},{"i":30,"n":"第三十条","txt":"在环境保护档案工作中有违法违纪行为的，依法依规给予处分；情节严重，涉嫌构成犯罪的，依法移送司法机关追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"地方各级环境保护主管部门可以根据本办法，结合本地实际情况，联合同级档案行政管理部门制定实施细则，并报上级档案行政管理部门和环境保护主管部门备案。"},{"i":32,"n":"第三十二条","txt":"本办法自2017年3月1日起施行。1994年10月6日公布的《环境保护档案管理办法》（原国家环境保护局 国家档案局令第13号）同时废止。"}],"huanjingbaohufaguizhidingchengxubanfa":[{"i":1,"n":"第一条","txt":"为了规范环境保护法规的制定程序，保证立法质量，根据《立法法》、《行政法规制定程序条例》、《部门规章制定程序条例》、《法规部门规章备案条例》和《全面推进依法行政实施纲要》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称“环境保护法规”，是指国家环境保护总局（以下简称总局），根据全国人大有关机关的委托, 或者根据法律、行政法规的授权，或者根据职权，制定的下列规范性文件： （一）根据全国人大有关机关的委托起草的环境保护法律的草案代拟稿; （二）拟报送国务院的环境保护法律或者行政法规的送审稿； （三）环境保护部门规章。"},{"i":3,"n":"第三条","txt":"环境保护法律、行政法规的立项、起草、审查、送审，环境保护部门规章的立项、起草、审查、决定、公布、备案和解释，适用本办法。 其他国家机关或者部门发送总局征求意见的有关法律、法规和部门规章的征求意见稿的办理程序，适用本办法的有关规定。"},{"i":4,"n":"第四条","txt":"总局于每年年初编制本年度立法计划。 年度立法计划确定的环境保护法律或者行政法规类立法项目，分为第一类、第二类和第三类立法项目： （一）已被列入全国人大常委会立法规划或者国务院年度立法计划，总局年内必须报出或者已报出需要配合全国人大或者国务院有关立法工作机构审查的立法项目，列入第一类立法项目； （二）立法依据充分、立法思路清晰、所要解决的问题为环境保护管理工作急需、拟确立的主要制度和措施可行、总局力争年内报出的立法项目，列入第二类立法项目； （三）需要研究、论证和起草的立法项目，列入第三类立法项目。"},{"i":5,"n":"第五条","txt":"环境保护部门规章的立法项目根据实际工作需要适时确定，不做立法计划安排。 国务院领导指示需要开展环境立法研究的项目，总局应当及时开展有关工作。"},{"i":6,"n":"第六条","txt":"除已被列入全国人大常委会立法规划或者国务院年度立法计划的立法项目外，总局有关司（办、局）认为需要制定环境保护法规的，应当于每年1月底前提出立项建议。 提出立项建议，应当填写立法项目申报表(见附件1)，并提交有关立法必要性、所要解决的主要问题和拟确立的主要制度和措施的书面说明材料，并可附具国内外有关立法参考资料。"},{"i":7,"n":"第七条","txt":"法规司对立项建议汇总研究，提出总局年度立法计划的建议稿，报总局局务会议审议决定。"},{"i":8,"n":"第八条","txt":"经总局局务会议审议通过的年度立法计划是总局本年度立法工作依据。"},{"i":9,"n":"第九条","txt":"具体负责起草环境保护法规工作的司（办、局），应当组织有关立法工作者、实际工作者和专家学者，承担立法起草工作。 法规司应当适时参加有关环境保护法规的起草工作。"},{"i":10,"n":"第十条","txt":"起草环境保护法规，应当广泛收集资料,深入调查研究，广泛听取有关机关、组织和公民的意见。 听取意见可以采取召开讨论会、专家论证会、部门协调会、企业代表座谈会、听证会等多种形式。"},{"i":11,"n":"第十一条","txt":"负责起草工作的司（办、局）完成环境保护法规初稿后，应当征求总局其他有关司（办、局）和有关直属单位的意见，并根据反馈意见，对初稿进行修改，形成环境保护法规征求意见稿草案，经负责起草工作的司（办、局）主要负责人签署后，报送总局局长专题会议审议。 局长专题会议重点就环境保护法规征求意见稿草案涉及的主要法律制度和措施的必要性和可行性，设定的行政许可和行政处罚的适当性和合法性等内容进行审议。"},{"i":12,"n":"第十二条","txt":"负责起草工作的司（办、局）应当根据总局局长专题会议审议意见，对征求意见稿草案进行修改，形成环境保护法规征求意见稿及其说明,以总局局函发送省级环境保护部门、国务院有关部门征求意见。 负责起草工作的司（办、局）可以根据环境保护法规征求意见稿内容所涉及的范围，征求有关地方人民政府、省级以下环境保护部门、有代表性的企业和公民的意见。 征求意见稿的说明，应当包括立法必要性、主要制度和措施等主要内容的说明。"},{"i":13,"n":"第十三条","txt":"环境保护法规直接涉及公民、法人或者其他组织切身利益的，可以公布征求意见稿，公开征求意见。 环境保护部门规章影响贸易和投资的，应当按照国家有关规定履行对外通报程序，公布征求意见稿。 环境保护法规的征求意见稿，可以在《中国环境报》和总局网站等媒体公布。"},{"i":14,"n":"第十四条","txt":"起草环境保护法规，涉及国务院其他部门的职能或者与国务院其他部门职能关系紧密的，负责起草工作的司（办、局）应当充分征求其他部门的意见；与其他部门有不同意见的，应当充分协商；经过充分协商不能取得一致意见的，负责起草工作的司（办、局）应当在环境保护法规草案送审稿说明中说明情况和理由。"},{"i":15,"n":"第十五条","txt":"负责起草工作的司（办、局）根据征求的意见，对征求意见稿及其说明进行修改,形成环境保护法规草案送审稿及其说明，连同其他有关材料，经负责起草工作的司（办、局）主要负责人签署后，移送法规司审查。 草案送审稿的说明，应当包括立法必要性、起草过程、主要制度和措施的说明、征求意见情况以及未采纳意见的处理情况等内容。 其他有关材料，主要包括：目前管理现状和存在的主要问题分析，草案规定的主要制度和措施的必要性和可行性的专项论证材料，征求意见及其处理情况汇总表、对未采纳的主要不同意见的说明，有关立法调研报告和国内外包括法规条文在内的其他立法参考资料。"},{"i":16,"n":"第十六条","txt":"对未按照本办法第三章的有关规定征求意见或者准备有关论证材料的，法规司可以转送负责起草工作的司（办、局）补办有关程序或者补充有关论证材料。"},{"i":17,"n":"第十七条","txt":"法规司会同负责起草工作的司（办、局），主要从下列方面对环境保护法规草案送审稿进行审查： （一）设定的环境保护行政许可项目是否符合《行政许可法》和其他有关法律、法规和国务院其他法规性文件关于设定行政许可的规定； （二）设定的环境保护行政处罚是否符合《行政处罚法》和其他有关法律、行政法规和国务院其他法规性文件关于设定行政处罚的规定； （三）是否与国家有关法规和政策协调、衔接； （四）是否符合立法技术要求。"},{"i":18,"n":"第十八条","txt":"在审查过程中，法规司认为环境保护法规草案送审稿涉及的法律问题需要进一步研究的，法规司可以组织实地调查，并可召开座谈会、论证会，听取意见。 环境保护法规草案送审稿创设行政许可事项，或者直接涉及公民、法人或者其他组织切身利益，有关机关、组织或者公民对其有重大意见分歧的，法规司和负责起草工作的司（办、局）可以向社会公开征求意见，也可以采取听证会等形式，听取有关机关、组织和公民的意见。"},{"i":19,"n":"第十九条","txt":"法规司会同负责起草工作的司（办、局）应当在20个工作日内完成环境保护部门规章草案送审稿的修改，在40个工作日内完成环境保护法律、行政法规草案送审稿的修改，形成环境保护法规草案送审稿。因涉及有关方面重大意见分歧需要协调等特殊情形的，可适当延长审查时限，但最长不得超过60个工作日。 法规司负责提出法规送审签报，经负责起草工作的司（办、局）会签后，连同环境保护法规草案及其起草说明和审查说明以及有关专项论证材料目录，提请总局局务会议审议。 起草说明应当包括立法必要性、起草过程、主要制度和措施的说明、征求意见情况以及未采纳意见的处理等情况的说明。 审查说明应当包括立法依据、行政许可和行政处罚设定的合法性、环境保护法规草案与有关法律、法规协调一致性等问题的说明。"},{"i":20,"n":"第二十条","txt":"对环境保护法规草案送审稿规定的管理体制、主要制度或者措施，有关方面存在重大分歧的，法规司会同负责起草工作的司（办、局）可以在环境保护法规草案中提出一种或多种备选方案，提交局长专题会议审议。"},{"i":21,"n":"第二十一条","txt":"环境保护法规草案应当经总局局务会议审议。"},{"i":22,"n":"第二十二条","txt":"审议环境保护法规草案时，负责起草工作的司（办、局）做起草说明，并负责就具体管理现状、主要管理制度和措施的必要性、可行性等专业性问题做说明或答辩。 法规司做审查说明，并负责就行政许可、行政处罚设定的合法性和环境保护法规草案与其他法律、法规的衔接等法律问题做说明和答辩。"},{"i":23,"n":"第二十三条","txt":"法规司应当会同负责起草工作的司（办、局），根据总局局务会议审议意见对环境保护部门规章草案进行修改，形成环境保护部门规章，报请总局局长签署命令予以公布。 法规司应当会同负责起草工作的司（办、局），根据总局局务会议审议意见对环境保护法律或者行政法规草案进行修改，形成环境保护法律或者行政法规送审稿，并以总局文件形式报送国务院。 总局根据全国人大有关机关委托起草的环境保护法律草案代拟稿，以总局局函报送委托机关。 报送环境保护法律或者行政法规送审稿、环境保护法律草案代拟稿，应当附送有关专项论证材料。"},{"i":24,"n":"第二十四条","txt":"公布环境保护部门规章的命令应当载明该环境保护部门规章的序号、名称、通过日期、施行日期、总局局长署名以及公布日期。环境保护部门规章公布格式见附件2。 总局与国务院有关部门联合发布的环境保护部门规章由有关部门首长共同署名公布；总局为主办机关的，使用总局的命令序号。"},{"i":25,"n":"第二十五条","txt":"环境保护部门规章签署公布后，《中国环境报》和总局网站应当及时刊载。"},{"i":26,"n":"第二十六条","txt":"经《国务院公报》刊载的环境保护部门规章文本为标准文本。在《中国环境报》上刊载的环境保护部门规章文本也为标准文本。"},{"i":27,"n":"第二十七条","txt":"环境保护部门规章应当自公布之日起30日后施行；但公布后不立即施行将有碍环境保护部门规章施行的，可以自公布之日起施行。"},{"i":28,"n":"第二十八条","txt":"环境保护部门规章应当自公布之日起30日内，由法规司依照《立法法》和《法规部门规章备案条例》的规定，办理具体的备案工作。 报送环境保护部门规章备案，应当提交备案报告、部门规章文本和说明，并按照规定的格式装订成册，一式十份。环境保护部门规章备案格式见附件3。 法规司应当于每年1月31日前将上一年度所制定的环境保护部门规章目录报国务院法制办公室。"},{"i":29,"n":"第二十九条","txt":"环境保护部门规章解释权属于总局。由总局与国务院有关部门联合发布的部门规章，由总局和国务院有关部门联合解释。 环境保护部门规章有下列情况之一的，由依据前款规定享有解释权的机关解释： （一）环境保护部门规章的规定需要进一步明确具体含义的； （二）环境保护部门规章制定后出现新的情况，需要明确适用依据的。 环境保护部门规章解释的办理程序，适用《环境保护法规解释管理办法》的有关规定。 环境保护部门规章的解释和环境保护部门规章具有同等效力。"},{"i":30,"n":"第三十条","txt":"环境保护法律、行政法规具体适用过程中的解释，适用《全国人民代表大会常务委员会关于加强法律解释工作的决议》、《国务院办公厅关于行政法规解释权限和程序问题的通知》和《环境保护法规解释管理办法》的有关规定。"},{"i":31,"n":"第三十一条","txt":"其他国家机关或者部门组织起草法律、行政法规或者部门规章，发送总局征求意见的，由法规司归口受理，并根据所涉及的内容分送有关司（办、局）征求意见。"},{"i":32,"n":"第三十二条","txt":"各有关司（办、局）应当按照确定的时限提出意见，返回法规司。 法规司根据是否与环境保护法律、行政法规、部门规章协调、衔接的原则，负责汇总研究，拟定函复意见。"},{"i":33,"n":"第三十三条","txt":"对其他国家机关或者部门组织起草法律、行政法规或者部门规章的征求意见稿，总局各有关司（办、局）之间存在较大意见分歧的，法规司负责进行协调；经协调仍不能达成一致意见的，报总局局长专题会议研究、协调。"},{"i":34,"n":"第三十四条","txt":"其他国家机关或者部门组织起草法律、行政法规或者部门规章的征求意见稿拟设立的管理体制、主要制度或者措施，与环境保护法律、行政法规、部门规章存在重大矛盾或者交叉，或者对环境保护部门监督管理工作具有重大影响的，法规司应当商有关司（办、局）提出意见和建议，报请总局局长专题会议或者局务会议研究。"},{"i":35,"n":"第三十五条","txt":"环境保护部门规章影响贸易和投资的，应当在公布后按照有关规定翻译英文译本，按照规定程序对外公布。 环境保护法律、行政法规由总局负责起草的，应当在公布后按照有关规定翻译成英文译本。 环境保护法规英文译本由总局国际司提出英文译本初稿，经负责起草工作的司（办、局）审核后，由法规司按照有关规定对外公布或者报送有关国家机关审查。 环境保护法规少数民族语言翻译工作按照国家有关规定执行。"},{"i":36,"n":"第三十六条","txt":"总局应当经常对环境保护部门规章进行清理，发现与新公布的法律、行政法规或者其他上位法的规定不一致的，或者与法律、行政法规或者其他上位法的规定相抵触的，或者出现不适应新出现的情况的，应当及时修改或者废止。 修改、废止环境保护部门规章的程序，依照本办法的有关规定执行。"},{"i":37,"n":"第三十七条","txt":"编辑出版正式版本、外文版本的环境保护法规汇编，由法规司依照《法规汇编编辑出版管理规定》的有关规定执行。"},{"i":38,"n":"第三十八条","txt":"本办法自2005年6月1日起施行。 1990年3月12日国家环境保护局发布的《国家环境保护局法规性文件管理办法》同时废止。 附件：1．立法项目申报表 2．部门规章公布格式 3．部门规章备案格式 4．环保法规主要制定程序流程图 　　 附件一： 20 年立法项目申报表 司 法规名称 法律／行政法规 计划总局报出时间 移送法规司审查时间 具体项目承办人 项目负责人 立法依据 立法目的 主要法律制度和措施 设立的行政许可 目前法规起草情况 备注 处长签字：　　　　　　　　　　　司长签字： 附件二：部门规章公布格式 国家环境保护总局令 第×号 　　《　　　　　　　　　》已经×年×月×日国家环境保护总局局务会议审议通过，现予公布，自×年×月×日起施行。 　　 国家环境保护总局局长：（签名） 　　 ×年×月×日 附件三：部门规章备案格式 国家环境保护总局 ××规备字〔　〕号 关于《　　　　　　》的备"}],"huanjingbaohuxingzhengxuketingzhengzanxingbanfa":[{"i":1,"n":"第一条","txt":"为了规范环境保护行政许可活动，保障和监督环境保护行政主管部门依法行政，提高环境保护行政许可的科学性、公正性、合理性和民主性，保护公民、法人和其他组织的合法权益，根据《中华人民共和国行政许可法》、《中华人民共和国环境影响评价法》等有关法律法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"县级以上人民政府环境保护行政主管部门实施环境保护行政许可时，适用本办法进行听证。"},{"i":3,"n":"第三条","txt":"听证由拟作出环境保护行政许可决定的环境保护行政主管部门组织。"},{"i":4,"n":"第四条","txt":"环境保护行政主管部门组织听证，应当遵循公开、公平、公正和便民的原则，充分听取公民、法人和其他组织的意见，保证其陈述意见、质证和申辩的权利。 除涉及国家秘密、商业秘密或者个人隐私外，听证应当公开举行。 公开举行的听证，公民、法人或者其他组织可以申请参加旁听。"},{"i":5,"n":"第五条","txt":"实施环境保护行政许可，有下列情形之一的，适用本办法： （一）按照法律、法规、规章的规定，实施环境保护行政许可应当组织听证的； （二）实施涉及公共利益的重大环境保护行政许可，环境保护行政主管部门认为需要听证的； （三）环境保护行政许可直接涉及申请人与他人之间重大利益关系，申请人、利害关系人依法要求听证的。"},{"i":6,"n":"第六条","txt":"除国家规定需要保密的建设项目外，建设本条所列项目的单位，在报批环境影响报告书前，未依法征求有关单位、专家和公众的意见，或者虽然依法征求了有关单位、专家和公众的意见，但存在重大意见分歧的，环境保护行政主管部门在审查或者重新审核建设项目环境影响评价文件之前，可以举行听证会，征求项目所在地有关单位和居民的意见： （一）对环境可能造成重大影响、应当编制环境影响报告书的建设项目； （二）可能产生油烟、恶臭、噪声或者其他污染，严重影响项目所在地居民生活环境质量的建设项目。"},{"i":7,"n":"第七条","txt":"对可能造成不良环境影响并直接涉及公众环境权益的工业、农业、畜牧业、林业、能源、水利、交通、城市建设、旅游、自然资源开发的有关专项规划，设区的市级以上人民政府在审批该专项规划草案和作出决策之前，指定环境保护行政主管部门对环境影响报告书进行审查的，环境保护行政主管部门可以举行听证会，征求有关单位、专家和公众对环境影响报告书草案的意见。国家规定需要保密的规划除外。"},{"i":8,"n":"第八条","txt":"环境保护行政许可的听证活动，由承担许可职能的环境保护行政主管部门组织，并由其指定听证主持人具体实施。 听证主持人应当由环境保护行政主管部门许可审查机构内审查该行政许可申请的工作人员以外的人员担任。 环境行政许可事项重大复杂，环境保护行政主管部门决定举行听证，由许可审查机构的人员担任听证主持人可能影响公正处理的，由法制机构工作人员担任听证主持人。 记录员由听证主持人指定。"},{"i":9,"n":"第九条","txt":"听证主持人在听证活动中行使下列职权： （一）决定举行听证的时间、地点和方式； （二）决定听证的延期、中止或者终结； （三）决定证人是否出席作证； （四）就听证事项进行询问； （五）接收并审核有关证据，必要时可要求听证参加人提供或者补充证据； （六）指挥听证活动，维护听证秩序，对违反听证纪律的行为予以警告直至责令其退场； （七）对听证笔录进行审阅； （八）法律、法规和规章赋予的其他职权。 记录员具体承担听证准备和听证记录工作。"},{"i":10,"n":"第十条","txt":"听证主持人在听证活动中承担下列义务： （一）决定将有关听证的通知及时送达行政许可申请人、利害关系人、行政许可审查人员、鉴定人、翻译人员等听证参加人； （二）公正地主持听证，保证当事人行使陈述权、申辩权和质证权； （三）符合回避情形的，应当自行回避； （四）保守听证案件涉及的国家秘密、商业秘密和个人隐私。 记录员应当如实制作听证笔录，并承担本条第（四）项所规定的义务。"},{"i":11,"n":"第十一条","txt":"听证主持人有下列情形之一的，应当自行回避。环境保护行政许可申请人或者利害关系人有权以口头或者书面方式申请其回避： （一）是被听证的行政许可的审查人员，或者是行政许可审查人员的近亲属； （二）是被听证的行政许可的当事人，或者是被听证的行政许可当事人、代理人的近亲属； （三）与行政许可结果有直接利害关系的； （四）与被听证的行政许可当事人有其他关系，可能影响公正听证的。 前款规定，适用于环境鉴定、监测人员。 行政许可申请人或者利害关系人申请听证主持人回避的，应说明理由，由组织听证的环境保护行政主管部门负责人决定是否回避。在是否回避的决定作出之前，被申请回避的听证主持人应当暂停参与听证工作。"},{"i":12,"n":"第十二条","txt":"环境保护行政许可申请人、利害关系人享有下列权利： （一）要求或者放弃听证； （二）依法申请听证主持人回避； （三）可以亲自参加听证，也可以委托一至二人代理参加听证； （四）就听证事项进行陈述、申辩和举证； （五）对证据进行质证； （六）听证结束前进行最后陈述； （七）审阅并核对听证笔录； （八）查阅案卷。"},{"i":13,"n":"第十三条","txt":"环境保护行政许可申请人、利害关系人承担下列义务： （一）按照组织听证的环境保护行政主管部门指定的时间、地点出席听证会； （二）依法举证； （三）如实回答听证主持人的询问； （四）遵守听证纪律。 听证申请人无正当理由不出席听证会的，视同放弃听证权利。 听证申请人违反听证纪律，情节严重被听证主持人责令退场的，视同放弃听证权利。 环境鉴定人、监测人、证人、翻译人员等听证参加人，应当承担第（三）项和第（四）项义务。"},{"i":14,"n":"第十四条","txt":"行政许可申请人、利害关系人或者其法定代理人，委托他人代理参加听证的，应当向组织听证的环境保护行政主管部门提交由委托人签名或者盖章的授权委托书。 授权委托书应当载明委托事项及权限。"},{"i":15,"n":"第十五条","txt":"组织听证的环境保护行政主管部门可以通知了解被听证的行政许可事项的单位和个人出席听证会。 有关单位应当支持了解被听证的行政许可事项的单位和个人出席听证会。 证人确有困难不能出席听证会的，可以提交有本人签名或者盖章的书面证言。"},{"i":16,"n":"第十六条","txt":"环境保护行政许可事项需要进行鉴定或者监测的，应当委托符合条件的鉴定或者监测机构。接受委托的机构有权了解有关材料，必要时可以询问行政许可申请人、利害关系人或者证人。 鉴定或者监测机构应当提交签名或者盖章的书面鉴定或者监测结论。"},{"i":17,"n":"第十七条","txt":"环境保护行政主管部门对本办法第五条第（一）项和第（二）项规定的环境保护行政许可事项，决定举行听证的，应在听证举行的10日前，通过报纸、网络或者布告等适当方式，向社会公告。 公告内容应当包括被听证的许可事项和听证会的时间、地点，以及参加听证会的方法。"},{"i":18,"n":"第十八条","txt":"组织听证的环境保护行政主管部门可以根据场地等条件，确定参加听证会的人数。"},{"i":19,"n":"第十九条","txt":"参加环境保护行政许可听证的公民、法人或者其他组织人数众多的，可以推举代表人参加听证。"},{"i":20,"n":"第二十条","txt":"环境保护行政主管部门对本办法第五条第（三）项规定的环境保护行政许可事项，在作出行政许可决定之前，应当告知行政许可申请人、利害关系人享有要求听证的权利，并送达《环境保护行政许可听证告知书》。 《环境保护行政许可听证告知书》应当载明下列事项： （一）行政许可申请人、利害关系人的姓名或者名称； （二）被听证的行政许可事项； （三）对被听证的行政许可的初步审查意见、证据和理由； （四）告知行政许可申请人、利害关系人有申请听证的权利； （五）告知申请听证的期限和听证的组织机关。 送达《环境保护行政许可听证告知书》可以采取直接送达、委托送达、邮寄送达等形式，并由行政许可申请人、利害关系人在送达回执上签字。 行政许可申请人、利害关系人人数众多或者其他必要情形时，可以通过报纸、网络或者布告等适当方式，将《环境保护行政许可听证告知书》向社会公告。"},{"i":21,"n":"第二十一条","txt":"行政许可申请人、利害关系人要求听证的，应当在收到听证告知书之日起5日内以书面形式提出听证申请。"},{"i":22,"n":"第二十二条","txt":"《环境保护行政许可听证申请书》包括以下内容： （一）听证申请人的姓名、地址； （二）申请听证的具体要求； （三）申请听证的依据、理由； （四）其他相关材料。"},{"i":23,"n":"第二十三条","txt":"组织行政许可听证的环境保护行政主管部门收到听证申请书后，应当对申请材料进行审查。申请材料不齐备的，应当一次性告知听证申请人补正。"},{"i":24,"n":"第二十四条","txt":"听证申请有下列情形之一的，组织听证的环境保护行政主管部门不予受理，并书面说明理由： （一）听证申请人不是该环境保护行政许可的申请人、利害关系人的； （二）听证申请未在收到《环境保护行政许可听证告知书》后５个工作日内提出的； （三）其他不符合申请听证条件的。"},{"i":25,"n":"第二十五条","txt":"组织听证的环境保护行政主管部门经过审核，对符合听证条件的听证申请，应当受理，并在20日内组织听证。"},{"i":26,"n":"第二十六条","txt":"组织听证的环境保护行政主管部门应当在听证举行的７日前，将《环境保护行政许可听证通知书》分别送达行政许可申请人、利害关系人，并由其在送达回执上签字。 《环境保护行政许可听证通知书》应当载明下列事项： （一）行政许可申请人、利害关系人的姓名或者名称； （二）听证的事由与依据； （三）听证举行的时间、地点和方式； （四）听证主持人、行政许可审查人员的姓名、职务； （五）告知行政许可申请人、利害关系人预先准备证据、通知证人等事项； （六）告知行政许可申请人、利害关系人参加听证的权利和义务； （七）其他注意事项。 申请人、利害关系人人数众多或者其他必要情形时，可以通过报纸、网络或者布告等适当方式，向社会公告。"},{"i":27,"n":"第二十七条","txt":"环境保护行政许可申请人、利害关系人接到听证通知后，应当按时到场；无正当理由不到场的，或者未经听证主持人允许中途退场的，视为放弃听证权利，并记入听证笔录。"},{"i":28,"n":"第二十八条","txt":"环境保护行政许可听证会按以下程序进行： （一）听证主持人宣布听证会场纪律，告知听证申请人、利害关系人的权利和义务，询问并核实听证参加人的身份，宣布听证开始； （二）记录员宣布听证所涉许可事项、听证主持人和听证员的姓名、工作单位和职务； （三）行政许可审查人员提出初步审查意见、理由和证据； （四）行政许可申请人、利害关系人就该行政许可事项进行陈述和申辩，提出有关证据，对行政许可审查人员提出的证据进行质证； （五）行政许可审查人员和行政许可申请人、利害关系人进行辩论； （六）行政许可申请人、利害关系人做最后陈述； （七）主持人宣布听证结束。 在听证过程中，主持人可以向行政许可审查人员、行政许可申请人、利害关系人和证人发问，有关人员应当如实回答。"},{"i":29,"n":"第二十九条","txt":"组织听证的环境保护行政主管部门，对听证会必须制作笔录。 听证笔录应当载明下列事项，并由听证员和记录员签名： （一）听证所涉许可事项； （二）听证主持人和记录员的姓名、职务； （三）听证参加人的基本情况； （四）听证的时间、地点； （五）听证公开情况； （六）行政许可审查人员提出的初步审查意见、理由和证据； （七）行政许可申请人、利害关系人和其他听证参加人的主要观点、理由和依据； （八）延期、中止或者终止的说明； （九）听证主持人对听证活动中有关事项的处理情况； （十）听证主持人认为应当笔录的其他事项。 听证结束后，听证笔录应交陈述意见的行政许可申请人、利害关系人审核无误后签字或者盖章。无正当理由拒绝签字或者盖章的，应当记入听证笔录。"},{"i":30,"n":"第三十条","txt":"听证终结后，听证主持人应当及时将听证笔录报告本部门负责人。 环境保护行政主管部门应当根据听证笔录，作出环境保护行政许可决定，并应当在许可决定中附具对听证会反映的主要观点采纳或者不采纳的说明。"},{"i":31,"n":"第三十一条","txt":"有下列情形之一的，可以延期举行听证： （一）因不可抗力事由致使听证无法按期举行的； （二）行政许可申请人、利害关系人临时申请听证主持人回避的； （三）行政许可申请人、利害关系人申请延期，并有正当理由的； （四）可以延期的其他情形。 延期听证的，组织听证的环境保护行政主管部门应当书面通知听证参加人。"},{"i":32,"n":"第三十二条","txt":"有下列情形之一的，中止听证： （一）听证主持人认为听证过程中提出的新的事实、理由、依据有待进一步调查核实或者鉴定的； （二）申请听证的公民死亡、法人或者其他组织终止，尚未确定权利、义务承受人的； （三）其他需要中止听证的情形。 中止听证的，组织听证的环境保护行政主管部门应当书面通知听证参加人。"},{"i":33,"n":"第三十三条","txt":"延期、中止听证的情形消失后，由组织听证的环境保护行政主管部门决定是否恢复听证，并书面通知听证参加人。"},{"i":34,"n":"第三十四条","txt":"有下列情形之一的，应当终止听证： （一）行政许可申请人、利害关系人在告知后明确放弃听证权利的； （二）听证申请人撤回听证要求的； （三）听证申请人无正当理由不参加听证的； （四）听证申请人在听证过程中声明退出的； （五）听证申请人未经听证主持人允许中途退场的； （六）听证申请人为法人或者其他组织的，该法人或者其他组织终止后，承受其权利的法人或者组织放弃听证权利的； （七）听证申请人违反听证纪律，情节严重，被听证主持人责令退场的； （八）需要终止听证的其他情形。"},{"i":35,"n":"第三十五条","txt":"环境保护行政主管部门及其工作人员违反《中华人民共和国行政许可法》的规定，有下列情形之一的，由有关机关依法责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予行政处分： （一）对法律、法规、规章规定应当组织听证的环境保护行政许可事项，不组织听证的； （二）对符合法定条件的环境保护行政许可听证申请，不予受理的； （三）在受理、审查、决定环境保护行政许可过程中，未向申请人、利害关系人履行法定告知义务的； （四）未依法说明不受理环境保护行政许可听证申请或者不予听证的理由的。"},{"i":36,"n":"第三十六条","txt":"环境保护行政主管部门的听证主持人、记录员，在听证时玩忽职守、滥用职权、徇私舞弊的，依法给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":37,"n":"第三十七条","txt":"《环境保护行政许可听证公告》、《环境保护行政许可听证告知书》、《环境保护行政许可听证申请书》、《环境保护行政许可听证通知书》和《送达回执》的格式，由国家环境保护总局统一规范。"},{"i":38,"n":"第三十八条","txt":"环境保护行政主管部门组织听证所需经费，应当根据《中华人民共和国行政许可法》第五十八条的规定，列入本行政机关的预算，由本级财政予以保障。"},{"i":39,"n":"第三十九条","txt":"环境保护行政主管部门受权起草的环境保护法律、法规，或者依职权起草的环境保护规章，直接涉及公民、法人或者其他组织切身利益，有关机关、组织或者公民对草案有重大意见分歧的，环境保护行政主管部门可以采取听证会形式，听取社会意见。 环境立法听证会，除适用《规章制定程序条例》等法律法规规定的程序外，可以参照本办法关于听证组织和听证程序的规定执行。"},{"i":40,"n":"第四十条","txt":"本办法自2004年7月1日起施行。 附件： 1．《环境保护行政许可听证公告》格式 2．《环境保护行政许可听证告知书》格式 3．《环境保护行政许可听证申请书》格式 4．《环境保护行政许可听证通知书》格式 5．《送达回执》格式 附件一： ×××环境保护局 环境保护行政许可听证公告 ××× [×] ×号 根据《中华人民共和国行政许可法》第四十六条（和《 》第 条）的规定，我局定于 年 月 日 时 分，在 （地点） 就 （环境保护行政许可事项） 举行听证。 如申请参加该听证会，可在 年 月 日到我局办理有关申请手续。 我局通讯地址及邮政编码： 联系人： 联系电话： 传真： 在参加听证前，须作好以下准备： 1、携带有关证据材料； 2、通知有关证人出席作证； 3、委托代理人参加的，须提前办理委托代理手续。 ×××环境保护局（印章） ×年×月×日 附件二： ×××环境保护局 环境保护行政许可听证告知"}],"huanjingyingxiangpingjiagongzhongcanyubanfa":[{"i":1,"n":"第一条","txt":"为规范环境影响评价公众参与，保障公众环境保护知情权、参与权、表达权和监督权，依据《中华人民共和国环境保护法》《中华人民共和国环境影响评价法》《规划环境影响评价条例》《建设项目环境保护管理条例》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于可能造成不良环境影响并直接涉及公众环境权益的工业、农业、畜牧业、林业、能源、水利、交通、城市建设、旅游、自然资源开发的有关专项规划的环境影响评价公众参与，和依法应当编制环境影响报告书的建设项目的环境影响评价公众参与。 国家规定需要保密的情形除外。"},{"i":3,"n":"第三条","txt":"国家鼓励公众参与环境影响评价。 环境影响评价公众参与遵循依法、有序、公开、便利的原则。"},{"i":4,"n":"第四条","txt":"专项规划编制机关应当在规划草案报送审批前，举行论证会、听证会，或者采取其他形式，征求有关单位、专家和公众对环境影响报告书草案的意见。"},{"i":5,"n":"第五条","txt":"建设单位应当依法听取环境影响评价范围内的公民、法人和其他组织的意见，鼓励建设单位听取环境影响评价范围之外的公民、法人和其他组织的意见。"},{"i":6,"n":"第六条","txt":"专项规划编制机关和建设单位负责组织环境影响报告书编制过程的公众参与，对公众参与的真实性和结果负责。 专项规划编制机关和建设单位可以委托环境影响报告书编制单位或者其他单位承担环境影响评价公众参与的具体工作。"},{"i":7,"n":"第七条","txt":"专项规划环境影响评价的公众参与，本办法未作规定的，依照《中华人民共和国环境影响评价法》《规划环境影响评价条例》的相关规定执行。"},{"i":8,"n":"第八条","txt":"建设项目环境影响评价公众参与相关信息应当依法公开，涉及国家秘密、商业秘密、个人隐私的，依法不得公开。法律法规另有规定的，从其规定。 生态环境主管部门公开建设项目环境影响评价公众参与相关信息，不得危及国家安全、公共安全、经济安全和社会稳定。"},{"i":9,"n":"第九条","txt":"建设单位应当在确定环境影响报告书编制单位后7个工作日内，通过其网站、建设项目所在地公共媒体网站或者建设项目所在地相关政府网站（以下统称网络平台），公开下列信息： （一）建设项目名称、选址选线、建设内容等基本情况，改建、扩建、迁建项目应当说明现有工程及其环境保护情况； （二）建设单位名称和联系方式； （三）环境影响报告书编制单位的名称； （四）公众意见表的网络链接； （五）提交公众意见表的方式和途径。 在环境影响报告书征求意见稿编制过程中，公众均可向建设单位提出与环境影响评价相关的意见。 公众意见表的内容和格式，由生态环境部制定。"},{"i":10,"n":"第十条","txt":"建设项目环境影响报告书征求意见稿形成后，建设单位应当公开下列信息，征求与该建设项目环境影响有关的意见： （一）环境影响报告书征求意见稿全文的网络链接及查阅纸质报告书的方式和途径； （二）征求意见的公众范围； （三）公众意见表的网络链接； （四）公众提出意见的方式和途径； （五）公众提出意见的起止时间。 建设单位征求公众意见的期限不得少于10个工作日。"},{"i":11,"n":"第十一条","txt":"依照本办法第十条规定应当公开的信息，建设单位应当通过下列三种方式同步公开： （一）通过网络平台公开，且持续公开期限不得少于10个工作日； （二）通过建设项目所在地公众易于接触的报纸公开，且在征求意见的10个工作日内公开信息不得少于2次； （三）通过在建设项目所在地公众易于知悉的场所张贴公告的方式公开，且持续公开期限不得少于10个工作日。 鼓励建设单位通过广播、电视、微信、微博及其他新媒体等多种形式发布本办法第十条规定的信息。"},{"i":12,"n":"第十二条","txt":"建设单位可以通过发放科普资料、张贴科普海报、举办科普讲座或者通过学校、社区、大众传播媒介等途径，向公众宣传与建设项目环境影响有关的科学知识，加强与公众互动。"},{"i":13,"n":"第十三条","txt":"公众可以通过信函、传真、电子邮件或者建设单位提供的其他方式，在规定时间内将填写的公众意见表等提交建设单位，反映与建设项目环境影响有关的意见和建议。 公众提交意见时，应当提供有效的联系方式。鼓励公众采用实名方式提交意见并提供常住地址。 对公众提交的相关个人信息，建设单位不得用于环境影响评价公众参与之外的用途，未经个人信息相关权利人允许不得公开。法律法规另有规定的除外。"},{"i":14,"n":"第十四条","txt":"对环境影响方面公众质疑性意见多的建设项目，建设单位应当按照下列方式组织开展深度公众参与： （一）公众质疑性意见主要集中在环境影响预测结论、环境保护措施或者环境风险防范措施等方面的，建设单位应当组织召开公众座谈会或者听证会。座谈会或者听证会应当邀请在环境方面可能受建设项目影响的公众代表参加。 （二）公众质疑性意见主要集中在环境影响评价相关专业技术方法、导则、理论等方面的，建设单位应当组织召开专家论证会。专家论证会应当邀请相关领域专家参加，并邀请在环境方面可能受建设项目影响的公众代表列席。 建设单位可以根据实际需要，向建设项目所在地县级以上地方人民政府报告，并请求县级以上地方人民政府加强对公众参与的协调指导。县级以上生态环境主管部门应当在同级人民政府指导下配合做好相关工作。"},{"i":15,"n":"第十五条","txt":"建设单位决定组织召开公众座谈会、专家论证会的，应当在会议召开的10个工作日前，将会议的时间、地点、主题和可以报名的公众范围、报名办法，通过网络平台和在建设项目所在地公众易于知悉的场所张贴公告等方式向社会公告。 建设单位应当综合考虑地域、职业、受教育水平、受建设项目环境影响程度等因素，从报名的公众中选择参加会议或者列席会议的公众代表，并在会议召开的5个工作日前通知拟邀请的相关专家，并书面通知被选定的代表。"},{"i":16,"n":"第十六条","txt":"建设单位应当在公众座谈会、专家论证会结束后5个工作日内，根据现场记录，整理座谈会纪要或者专家论证结论，并通过网络平台向社会公开座谈会纪要或者专家论证结论。座谈会纪要和专家论证结论应当如实记载各种意见。"},{"i":17,"n":"第十七条","txt":"建设单位组织召开听证会的，可以参考环境保护行政许可听证的有关规定执行。"},{"i":18,"n":"第十八条","txt":"建设单位应当对收到的公众意见进行整理，组织环境影响报告书编制单位或者其他有能力的单位进行专业分析后提出采纳或者不采纳的建议。 建设单位应当综合考虑建设项目情况、环境影响报告书编制单位或者其他有能力的单位的建议、技术经济可行性等因素，采纳与建设项目环境影响有关的合理意见，并组织环境影响报告书编制单位根据采纳的意见修改完善环境影响报告书。 对未采纳的意见，建设单位应当说明理由。未采纳的意见由提供有效联系方式的公众提出的，建设单位应当通过该联系方式，向其说明未采纳的理由。"},{"i":19,"n":"第十九条","txt":"建设单位向生态环境主管部门报批环境影响报告书前，应当组织编写建设项目环境影响评价公众参与说明。公众参与说明应当包括下列主要内容： （一）公众参与的过程、范围和内容； （二）公众意见收集整理和归纳分析情况； （三）公众意见采纳情况，或者未采纳情况、理由及向公众反馈的情况等。 公众参与说明的内容和格式，由生态环境部制定。"},{"i":20,"n":"第二十条","txt":"建设单位向生态环境主管部门报批环境影响报告书前，应当通过网络平台，公开拟报批的环境影响报告书全文和公众参与说明。"},{"i":21,"n":"第二十一条","txt":"建设单位向生态环境主管部门报批环境影响报告书时，应当附具公众参与说明。"},{"i":22,"n":"第二十二条","txt":"生态环境主管部门受理建设项目环境影响报告书后，应当通过其网站或者其他方式向社会公开下列信息： （一） 环境影响报告书全文； （二） 公众参与说明； （三） 公众提出意见的方式和途径。 公开期限不得少于10个工作日。"},{"i":23,"n":"第二十三条","txt":"生态环境主管部门对环境影响报告书作出审批决定前，应当通过其网站或者其他方式向社会公开下列信息： （一） 建设项目名称、建设地点； （二） 建设单位名称； （三） 环境影响报告书编制单位名称； （四） 建设项目概况、主要环境影响和环境保护对策与措施； （五） 建设单位开展的公众参与情况； （六） 公众提出意见的方式和途径。 公开期限不得少于5个工作日。 生态环境主管部门依照第一款规定公开信息时，应当通过其网站或者其他方式同步告知建设单位和利害关系人享有要求听证的权利。 生态环境主管部门召开听证会的，依照环境保护行政许可听证的有关规定执行。"},{"i":24,"n":"第二十四条","txt":"在生态环境主管部门受理环境影响报告书后和作出审批决定前的信息公开期间，公民、法人和其他组织可以依照规定的方式、途径和期限，提出对建设项目环境影响报告书审批的意见和建议，举报相关违法行为。 生态环境主管部门对收到的举报，应当依照国家有关规定处理。必要时，生态环境主管部门可以通过适当方式向公众反馈意见采纳情况。"},{"i":25,"n":"第二十五条","txt":"生态环境主管部门应当对公众参与说明内容和格式是否符合要求、公众参与程序是否符合本办法的规定进行审查。 经综合考虑收到的公众意见、相关举报及处理情况、公众参与审查结论等，生态环境主管部门发现建设项目未充分征求公众意见的，应当责成建设单位重新征求公众意见，退回环境影响报告书。"},{"i":26,"n":"第二十六条","txt":"生态环境主管部门参考收到的公众意见，依照相关法律法规、标准和技术规范等审批建设项目环境影响报告书。"},{"i":27,"n":"第二十七条","txt":"生态环境主管部门应当自作出建设项目环境影响报告书审批决定之日起7个工作日内，通过其网站或者其他方式向社会公告审批决定全文，并依法告知提起行政复议和行政诉讼的权利及期限。"},{"i":28,"n":"第二十八条","txt":"建设单位应当将环境影响报告书编制过程中公众参与的相关原始资料，存档备查。"},{"i":29,"n":"第二十九条","txt":"建设单位违反本办法规定，在组织环境影响报告书编制过程的公众参与时弄虚作假，致使公众参与说明内容严重失实的，由负责审批环境影响报告书的生态环境主管部门将该建设单位及其法定代表人或主要负责人失信信息记入环境信用记录，向社会公开。"},{"i":30,"n":"第三十条","txt":"公众提出的涉及征地拆迁、财产、就业等与建设项目环境影响评价无关的意见或者诉求，不属于建设项目环境影响评价公众参与的内容。公众可以依法另行向其他有关主管部门反映。"},{"i":31,"n":"第三十一条","txt":"对依法批准设立的产业园区内的建设项目，若该产业园区已依法开展了规划环境影响评价公众参与且该建设项目性质、规模等符合经生态环境主管部门组织审查通过的规划环境影响报告书和审查意见，建设单位开展建设项目环境影响评价公众参与时，可以按照以下方式予以简化： （一）免予开展本办法第九条规定的公开程序，相关应当公开的内容纳入本办法第十条规定的公开内容一并公开； （二）本办法第十条第二款和第十一条第一款规定的10个工作日的期限减为5个工作日； （三）免予采用本办法第十一条第一款第三项规定的张贴公告的方式。"},{"i":32,"n":"第三十二条","txt":"核设施建设项目建造前的环境影响评价公众参与依照本办法有关规定执行。 堆芯热功率300兆瓦以上的反应堆设施和商用乏燃料后处理厂的建设单位应当听取该设施或者后处理厂半径15公里范围内公民、法人和其他组织的意见；其他核设施和铀矿冶设施的建设单位应当根据环境影响评价的具体情况，在一定范围内听取公民、法人和其他组织的意见。 大型核动力厂建设项目的建设单位应当协调相关省级人民政府制定项目建设公众沟通方案，以指导与公众的沟通工作。"},{"i":33,"n":"第三十三条","txt":"土地利用的有关规划和区域、流域、海域的建设、开发利用规划的编制机关，在组织进行规划环境影响评价的过程中，可以参照本办法的有关规定征求公众意见。"},{"i":34,"n":"第三十四条","txt":"本办法自2019年1月1日起施行。《环境影响评价公众参与暂行办法》自本办法施行之日起废止。其他文件中有关环境影响评价公众参与的规定与本办法规定不一致的，适用本办法。"}],"huanjingjianchabanfa":[{"i":1,"n":"第一条","txt":"为加强和规范环境监察工作，加强环境监察队伍建设，提升环境监察效能，根据《中华人民共和国环境保护法》等有关法律、法规，结合环境监察工作实际，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称环境监察，是指环境保护主管部门依据环境保护法律、法规、规章和其他规范性文件实施的行政执法活动。"},{"i":3,"n":"第三条","txt":"环境监察应当遵循以下原则： （一）教育和惩戒相结合； （二）严格执法和引导自觉守法相结合； （三）证据确凿，程序合法，定性准确，处理恰当； （四）公正、公开、高效。"},{"i":4,"n":"第四条","txt":"环境保护部对全国环境监察工作实施统一监督管理。 县级以上地方环境保护主管部门负责本行政区域的环境监察工作。 各级环境保护主管部门所属的环境监察机构（以下简称“环境监察机构”），负责具体实施环境监察工作。"},{"i":5,"n":"第五条","txt":"环境监察机构对本级环境保护主管部门负责，并接受上级环境监察机构的业务指导和监督。 各级环境保护主管部门应当加强对环境监察机构的领导，建立健全工作协调机制，并为环境监察机构提供必要的工作条件。"},{"i":6,"n":"第六条","txt":"环境监察机构的主要任务包括： （一）监督环境保护法律、法规、规章和其他规范性文件的执行； （二）现场监督检查污染源的污染物排放情况、污染防治设施运行情况、环境保护行政许可执行情况、建设项目环境保护法律法规的执行情况等； （三）现场监督检查自然保护区、畜禽养殖污染防治等生态和农村环境保护法律法规执行情况； （四）具体负责排放污染物申报登记、排污费核定和征收； （五）查处环境违法行为； （六）查办、转办、督办对环境污染和生态破坏的投诉、举报，并按照环境保护主管部门确定的职责分工，具体负责环境污染和生态破坏纠纷的调解处理； （七）参与突发环境事件的应急处置； （八）对严重污染环境和破坏生态问题进行督查； （九）依照职责，具体负责环境稽查工作； （十）法律、法规、规章和规范性文件规定的其他职责。"},{"i":7,"n":"第七条","txt":"各级环境监察机构可以命名为环境监察局。省级、设区的市级、县级环境监察机构，也可以分别以环境监察总队、环境监察支队、环境监察大队命名。 县级环境监察机构的分支（派出）机构和乡镇级环境监察机构的名称，可以命名为环境监察中队或者环境监察所。"},{"i":8,"n":"第八条","txt":"环境监察机构的设置和人员构成，应当根据本行政区域范围大小、经济社会发展水平、人口规模、污染源数量和分布、生态保护和环境执法任务量等因素科学确定。"},{"i":9,"n":"第九条","txt":"环境监察机构的工作经费，应当按照国家有关规定列入环境保护主管部门预算，由本级财政予以保障。"},{"i":10,"n":"第十条","txt":"环境监察机构的办公用房、执法业务用房及执法车辆、调查取证器材等执法装备，应当符合国家环境监察标准化建设及验收要求。 环境监察机构的执法车辆应当喷涂统一的环境监察执法标识。"},{"i":11,"n":"第十一条","txt":"录用环境监察机构的工作人员（以下简称“环境监察人员”），应当符合《中华人民共和国公务员法》的有关规定。"},{"i":12,"n":"第十二条","txt":"环境保护主管部门应当根据工作需要，制定环境监察培训五年规划和年度计划，组织开展分级分类培训。 设区的市级、县级环境监察机构的主要负责人和省级以上环境监察人员的岗位培训，由环境保护部统一组织。其他环境监察人员的岗位培训，由省级环境保护主管部门组织。 环境监察人员参加培训的情况，应当作为环境监察人员考核、任职的主要依据。"},{"i":13,"n":"第十三条","txt":"从事现场执法工作的环境监察人员进行现场检查时，有权依法采取以下措施： （一）进入有关场所进行勘察、采样、监测、拍照、录音、录像、制作笔录； （二）查阅、复制相关资料； （三）约见、询问有关人员，要求说明相关事项，提供相关材料； （四）责令停止或者纠正违法行为； （五）适用行政处罚简易程序，当场作出行政处罚决定； （六）法律、法规、规章规定的其他措施。 实施现场检查时，从事现场执法工作的环境监察人员不得少于两人，并出示《中国环境监察执法证》等行政执法证件，表明身份，说明执法事项。"},{"i":14,"n":"第十四条","txt":"从事现场执法工作的环境监察人员，应当持有《中国环境监察执法证》。 对参加岗位培训，并经考试取得培训合格证书的环境监察人员，经核准后颁发《中国环境监察执法证》。《中国环境监察执法证》颁发、使用、管理的具体办法，由环境保护部另行制定。"},{"i":15,"n":"第十五条","txt":"各级环境监察机构应当建立健全保密制度，完善保密措施，落实保密责任，指定专人管理保密的日常工作。"},{"i":16,"n":"第十六条","txt":"环境监察人员应当严格遵守有关廉政纪律和要求。"},{"i":17,"n":"第十七条","txt":"各级环境保护主管部门应当建立健全对环境监察人员的考核制度。 对工作表现突出、有显著成绩的环境监察人员，给予表彰和奖励。对在环境监察工作中违法违纪的环境监察人员，依法给予处分，可以暂扣、收回《中国环境监察执法证》；涉嫌构成犯罪的，依法移送司法机关追究刑事责任。"},{"i":18,"n":"第十八条","txt":"环境监察机构应当根据本行政区域环境保护工作任务、污染源数量、类型、管理权限等，制定环境监察工作年度计划。 环境监察工作年度计划报同级环境保护主管部门批准后实施，并抄送上一级环境监察机构。"},{"i":19,"n":"第十九条","txt":"环境监察机构应当根据环境监察工作年度计划，组织现场检查。现场检查可以采取例行检查或者重点检查的方式进行。"},{"i":20,"n":"第二十条","txt":"对排污者申报的排放污染物的种类、数量，环境监察机构负责依法进行核定。"},{"i":21,"n":"第二十一条","txt":"环境监察机构应当按照排污费征收标准和核定的污染物种类、数量，负责向排污者征收排污费。 对减缴、免缴、缓缴排污费的申请，环境监察机构应当依法审核。"},{"i":22,"n":"第二十二条","txt":"违反环境保护法律、法规和规章规定的，环境保护主管部门应当责令违法行为人改正或者限期改正，并依法实施行政处罚。"},{"i":23,"n":"第二十三条","txt":"对违反环境保护法律、法规，严重污染环境或者造成重大社会影响的环境违法案件，环境保护主管部门可以提出明确要求，督促有关部门限期办理，并向社会公开办理结果。"},{"i":24,"n":"第二十四条","txt":"环境监察机构负责组织实施环境行政执法后督察，监督环境行政处罚、行政命令等具体行政行为的执行。"},{"i":25,"n":"第二十五条","txt":"企业事业单位严重污染环境或者造成严重生态破坏的，环境保护主管部门或者环境监察机构可以约谈单位负责人，督促其限期整改。 对未完成环境保护目标任务或者发生重大、特大突发环境事件的，环境保护主管部门或者环境监察机构可以约谈下级地方人民政府负责人，要求地方人民政府依法履行职责，落实整改措施，并可以提出改进工作的建议。"},{"i":26,"n":"第二十六条","txt":"对依法受理的案件，属于本机关管辖的，环境保护主管部门应当按照规定的时限和程序依法处理；属于环境保护主管部门管辖但不属于本机关管辖的，受理案件的环境保护主管部门应当移送有管辖权的环境保护主管部门处理；不属于环境保护主管部门管辖的，受理案件的环境保护主管部门应当移送有管辖权的机关处理。 环境保护主管部门应当加强与司法机关的配合和协作，并可以根据工作需要，联合其他部门共同执法。"},{"i":27,"n":"第二十七条","txt":"相邻行政区域的环境保护主管部门应当相互通报环境监察执法信息，加强沟通、协调和配合。 同一区域、流域内的环境保护主管部门应当加强信息共享，开展联合检查和执法活动。 环境监察机构应当加强信息统计，并以专题报告、定期报告、统计报表等形式，向同级环境保护主管部门和上级环境监察机构报告本行政区域的环境监察工作情况。 环境保护主管部门应当依法公开环境监察的有关信息。"},{"i":28,"n":"第二十八条","txt":"上级环境保护主管部门应当对下级环境保护主管部门在环境监察工作中依法履行职责、行使职权和遵守纪律的情况进行稽查。"},{"i":29,"n":"第二十九条","txt":"对环境监察工作中形成的污染源监察、建设项目检查、排放污染物申报登记、排污费征收、行政处罚等材料，应当及时进行整理，立卷归档。"},{"i":30,"n":"第三十条","txt":"上级环境监察机构应当对下一级环境保护主管部门的环境监察工作进行年度考核。"},{"i":31,"n":"第三十一条","txt":"环境保护主管部门所属的其他机构，可以按照环境保护主管部门确定的职责分工，参照本办法，具体实施其职责范围内的环境监察工作。"},{"i":32,"n":"第三十二条","txt":"本办法由环境保护部负责解释。"},{"i":33,"n":"第三十三条","txt":"本办法自2012年9月1日起施行。《环境监理工作暂行办法》（〔91〕环监字第338号）、《环境监理工作制度（试行）》（环监〔1996〕888号）、《环境监理工作程序（试行）》（环监〔1996〕888号）、《环境监理政务公开制度》（环发〔1999〕15号）同时废止。"}],"huanjingjianchazhifazhengjianguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强环境监察执法证件管理，规范环境监察执法人员的执法行为，根据《中华人民共和国环境保护法》、《中华人民共和国行政处罚法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于环境监察执法证件的申领、使用和管理。"},{"i":3,"n":"第三条","txt":"环境监察执法证件是环境监察执法人员依法开展环境监察执法活动资格和身份的证明。"},{"i":4,"n":"第四条","txt":"环境保护部负责全国环境监察执法证件的管理工作。 省级环境保护主管部门负责本行政区域内环境监察执法证件的管理工作。 环境保护部环境监察局、省级环境监察机构负责具体实施环境监察执法证件管理工作。"},{"i":5,"n":"第五条","txt":"环境监察执法证件的样式、编码方式和制作要求由环境保护部统一制定。"},{"i":6,"n":"第六条","txt":"从事现场执法工作的环境监察执法人员进行现场检查时，有权依法采取以下措施： （一）进入有关场所进行勘察、采样、监测、拍照、录音、录像、制作笔录； （二）查阅、复制相关资料； （三）约见、询问有关人员，要求说明相关事项，提供相关材料； （四）责令停止或者纠正违法行为； （五）适用行政处罚简易程序，当场作出行政处罚决定； （六）法律、法规、规章规定的其他措施。 环境监察执法人员在执行环境监察执法任务时，应当出示环境监察执法证件或者有效的地方行政执法证件。 未取得环境监察执法证件的，不得从事环境监察执法工作。"},{"i":7,"n":"第七条","txt":"县级以上环境保护主管部门具有正式编制拟从事环境监察执法工作的人员，具备下列条件的，可以申请领取环境监察执法证件： （一）具有全日制大专以上学历； （二）在环境保护主管部门工作满一年； （三）熟悉环境保护法律、法规、规章和环境监察执法的业务知识； （四）参加环境监察执法资格培训并经考试合格。"},{"i":8,"n":"第八条","txt":"环境保护部负责组织以下人员的执法资格培训和考试： （一）省级以上环境保护主管部门拟从事环境监察执法工作的 人员； （二）设区的市级环境保护主管部门及其环境监察机构负责人； （三）县级环境保护主管部门负责人、县级环境监察机构主要 负责人。 前款规定之外的其他申领人员的执法资格培训和考试由省级环境保护主管部门组织。"},{"i":9,"n":"第九条","txt":"环境监察执法资格培训的教学大纲由环境保护部统一编制。省级环境保护主管部门可以结合本地实际补充培训内容。"},{"i":10,"n":"第十条","txt":"环境监察执法人员每五年至少参加一次执法资格培训并经考试合格。"},{"i":11,"n":"第十一条","txt":"申请领取环境监察执法证件的，申领人员应当向本级环境保护主管部门的环境监察机构提出书面申请。 收到申请的环境监察机构依照本办法的规定进行审核，并通过全国环境监察队伍管理系统逐级审核上报至环境保护部环境监察局。 环境保护部环境监察局对收到的申请进行审核，对属于本级环境保护主管部门的申领人员，认为符合本办法第七条规定的，报请环境保护部核发环境监察执法证件；对其他申领人员，认为符合本办法第七条规定，可以确认其环境监察执法人员资格的，告知省级环境保护主管部门核发环境监察执法证件。"},{"i":12,"n":"第十二条","txt":"县级以上环境监察机构负责本级环境保护主管部门环境监察执法证件持有人（以下简称“持证人”）在全国环境监察队伍管理系统中的信息更新维护。"},{"i":13,"n":"第十三条","txt":"环境监察执法证件应当载明人员姓名、证件编号、所属单位、使用区域、发证日期和发证部门等信息，并加盖发证部门的公章。 禁止伪造、变造环境监察执法证件。"},{"i":14,"n":"第十四条","txt":"持证人应当按照证件载明的职责和区域范围从事环境监察执法工作。 下级环境监察执法人员受上级环境保护主管部门委派开展异地环境监察执法活动的，不受环境监察执法证件规定的区域范围限制。"},{"i":15,"n":"第十五条","txt":"持证人应当妥善保管环境监察执法证件，不得涂改、损毁或者转借他人。"},{"i":16,"n":"第十六条","txt":"环境监察执法证件每两年审验一次。持证人所在单位应当将证件统一报送发证部门审验。 发证部门应当对以下事项进行审验： （一）环境监察执法证件所载信息是否与持证人实际情况相符； （二）持证人是否持有有效的环境监察执法资格培训合格证明。 逾期未审验的环境监察执法证件，自行失效；经审验不合格的，由发证部门收回环境监察执法证件。"},{"i":17,"n":"第十七条","txt":"持证人遗失环境监察执法证件的，应当及时向其所在的环境保护主管部门报告，由其所在的环境保护主管部门逐级报告至发证部门。发证部门应当在核实后及时补发新证。"},{"i":18,"n":"第十八条","txt":"有下列情形之一的，持证人或者其所在单位应当申请换发环境监察执法证件： （一）持证人所在单位名称发生变化的； （二）持证人从事环境监察执法的区域范围发生变更的； （三）持证人所持环境监察执法证件污损、残缺的； （四）持证人职务、级别发生变化的； （五）其他应当换发环境监察执法证件的情形。 申请换发环境监察执法证件的，应当将原证件交回发证部门；发证部门应当及时换发新证。"},{"i":19,"n":"第十九条","txt":"有下列情形之一的，持证人或者其所在单位应当向发证部门申请注销环境监察执法证件： （一）持证人退休的； （二）持证人调离环境监察执法工作岗位的； （三）其他应当注销环境监察执法证件的情形。 注销的环境监察执法证件应当交回发证部门。"},{"i":20,"n":"第二十条","txt":"持证人有下列行为之一的，由县级以上环境保护主管部门给予批评教育，责令限期改正，并暂扣其环境监察执法证件： （一）涂改、转借环境监察执法证件的； （二）使用环境监察执法证件从事与公务无关的活动的； （三）违反环境监察执法人员行为规范的； （四）其他违反环境监察执法证件管理相关规定的行为。 对暂扣环境监察执法证件的人员，发证部门应当对其重新进行环境监察执法资格培训。证件暂扣期间，不得从事环境监察执法工作。 暂扣环境监察执法证件的情况应当及时报发证部门备案。"},{"i":21,"n":"第二十一条","txt":"持证人有下列行为之一的，由发证部门收回环境监察执法证件： （一）受到刑事处罚、行政拘留或者记大过以上行政处分的； （二）以欺诈、舞弊、贿赂等不正当手段获取环境监察执法证件的； （三）违反廉洁执法相关规定且情节严重的； （四）其他严重违反相关法律法规的行为。"},{"i":22,"n":"第二十二条","txt":"环境保护主管部门有下列行为之一的，由上级环境保护主管部门给予通报批评，责令限期改正： （一）安排未取得环境监察执法证件的人员从事环境监察执法工作的； （二）对持证人和环境监察执法证件管理不善导致严重后果的； （三）其他违反环境监察执法证件管理相关规定的行为。"},{"i":23,"n":"第二十三条","txt":"发证部门工作人员违反本办法的规定，滥用职权、徇私舞弊、玩忽职守，擅自发放或者越权发放环境监察执法证件的，依法给予处分。"},{"i":24,"n":"第二十四条","txt":"本办法由环境保护部负责解释。"},{"i":25,"n":"第二十五条","txt":"本办法自2014年3月1日起施行。原国家环境保护局发布的《环境监理执法标志管理办法》（国家环境保护局令第9号）同时废止。"}],"huanjingjianceguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强环境监测管理，根据《环境保护法》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于县级以上环境保护部门下列环境监测活动的管理： （一）环境质量监测； （二）污染源监督性监测； （三）突发环境污染事件应急监测； （四）为环境状况调查和评价等环境管理活动提供监测数据的其他环境监测活动。"},{"i":3,"n":"第三条","txt":"环境监测工作是县级以上环境保护部门的法定职责。 县级以上环境保护部门应当按照数据准确、代表性强、方法科学、传输及时的要求，建设先进的环境监测体系，为全面反映环境质量状况和变化趋势，及时跟踪污染源变化情况，准确预警各类环境突发事件等环境管理工作提供决策依据。"},{"i":4,"n":"第四条","txt":"县级以上环境保护部门对本行政区域环境监测工作实施统一监督管理，履行下列主要职责： （一）制定并组织实施环境监测发展规划和年度工作计划； （二）组建直属环境监测机构，并按照国家环境监测机构建设标准组织实施环境监测能力建设； （三）建立环境监测工作质量审核和检查制度； （四）组织编制环境监测报告，发布环境监测信息； （五）依法组建环境监测网络，建立网络管理制度，组织网络运行管理； （六）组织开展环境监测科学技术研究、国际合作与技术交流。 国家环境保护总局适时组建直属跨界环境监测机构。"},{"i":5,"n":"第五条","txt":"县级以上环境保护部门所属环境监测机构具体承担下列主要环境监测技术支持工作： （一）开展环境质量监测、污染源监督性监测和突发环境污染事件应急监测； （二）承担环境监测网建设和运行，收集、管理环境监测数据，开展环境状况调查和评价，编制环境监测报告； （三）负责环境监测人员的技术培训； （四）开展环境监测领域科学研究，承担环境监测技术规范、方法研究以及国际合作和交流； （五）承担环境保护部门委托的其他环境监测技术支持工作。"},{"i":6,"n":"第六条","txt":"国家环境保护总局负责依法制定统一的国家环境监测技术规范。 省级环境保护部门对国家环境监测技术规范未作规定的项目，可以制定地方环境监测技术规范，并报国家环境保护总局备案。"},{"i":7,"n":"第七条","txt":"县级以上环境保护部门负责统一发布本行政区域的环境污染事故、环境质量状况等环境监测信息。 有关部门间环境监测结果不一致的，由县级以上环境保护部门报经同级人民政府协调后统一发布。 环境监测信息未经依法发布，任何单位和个人不得对外公布或者透露。 属于保密范围的环境监测数据、资料、成果，应当按照国家有关保密的规定进行管理。"},{"i":8,"n":"第八条","txt":"县级以上环境保护部门所属环境监测机构依据本办法取得的环境监测数据，应当作为环境统计、排污申报核定、排污费征收、环境执法、目标责任考核等环境管理的依据。"},{"i":9,"n":"第九条","txt":"县级以上环境保护部门按照环境监测的代表性分别负责组织建设国家级、省级、市级、县级环境监测网，并分别委托所属环境监测机构负责运行。"},{"i":10,"n":"第十条","txt":"环境监测网由各环境监测要素的点位（断面）组成。 环境监测点位（断面）的设置、变更、运行，应当按照国家环境保护总局有关规定执行。 各大水系或者区域的点位（断面），属于国家级环境监测网。"},{"i":11,"n":"第十一条","txt":"环境保护部门所属环境监测机构按照其所属的环境保护部门级别，分为国家级、省级、市级、县级四级。 上级环境监测机构应当加强对下级环境监测机构的业务指导和技术培训。"},{"i":12,"n":"第十二条","txt":"环境保护部门所属环境监测机构应当具备与所从事的环境监测业务相适应的能力和条件，并按照经批准的环境保护规划规定的要求和时限，逐步达到国家环境监测能力建设标准。 环境保护部门所属环境监测机构从事环境监测的专业技术人员，应当进行专业技术培训，并经国家环境保护总局统一组织的环境监测岗位考试考核合格，方可上岗。"},{"i":13,"n":"第十三条","txt":"县级以上环境保护部门应当对本行政区域内的环境监测质量进行审核和检查。 各级环境监测机构应当按照国家环境监测技术规范进行环境监测，并建立环境监测质量管理体系，对环境监测实施全过程质量管理，并对监测信息的准确性和真实性负责。"},{"i":14,"n":"第十四条","txt":"县级以上环境保护部门应当建立环境监测数据库，对环境监测数据实行信息化管理，加强环境监测数据收集、整理、分析、储存，并按照国家环境保护总局的要求定期将监测数据逐级报上一级环境保护部门。 各级环境保护部门应当逐步建立环境监测数据信息共享制度。"},{"i":15,"n":"第十五条","txt":"环境监测工作，应当使用统一标志。 环境监测人员佩戴环境监测标志，环境监测站点设立环境监测标志，环境监测车辆印制环境监测标志，环境监测报告附具环境监测标志。 环境监测统一标志由国家环境保护总局制定。"},{"i":16,"n":"第十六条","txt":"任何单位和个人不得损毁、盗窃环境监测设施。"},{"i":17,"n":"第十七条","txt":"县级以上环境保护部门应当协调有关部门，将环境监测网建设投资、运行经费等环境监测工作所需经费全额纳入同级财政年度经费预算。"},{"i":18,"n":"第十八条","txt":"县级以上环境保护部门及其工作人员、环境监测机构及环境监测人员有下列行为之一的，由任免机关或者监察机关按照管理权限依法给予行政处分；涉嫌犯罪的，移送司法机关依法处理： （一）未按照国家环境监测技术规范从事环境监测活动的； （二）拒报或者两次以上不按照规定的时限报送环境监测数据的； （三）伪造、篡改环境监测数据的； （四）擅自对外公布环境监测信息的。"},{"i":19,"n":"第十九条","txt":"排污者拒绝、阻挠环境监测工作人员进行环境监测活动或者弄虚作假的，由县级以上环境保护部门依法给予行政处罚;构成违反治安管理行为的,由公安机关依法给予治安处罚；构成犯罪的,依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"损毁、盗窃环境监测设施的，县级以上环境保护部门移送公安机关，由公安机关依照《治安管理处罚法》的规定处10日以上15日以下拘留；构成犯罪的，依法追究刑事责任。"},{"i":21,"n":"第二十一条","txt":"排污者必须按照县级以上环境保护部门的要求和国家环境监测技术规范，开展排污状况自我监测。 排污者按照国家环境监测技术规范，并经县级以上环境保护部门所属环境监测机构检查符合国家规定的能力要求和技术条件的，其监测数据作为核定污染物排放种类、数量的依据。 不具备环境监测能力的排污者，应当委托环境保护部门所属环境监测机构或者经省级环境保护部门认定的环境监测机构进行监测；接受委托的环境监测机构所从事的监测活动，所需经费由委托方承担，收费标准按照国家有关规定执行。 经省级环境保护部门认定的环境监测机构，是指非环境保护部门所属的、从事环境监测业务的机构，可以自愿向所在地省级环境保护部门申请证明其具备相适应的环境监测业务能力认定，经认定合格者，即为经省级环境保护部门认定的环境监测机构。 经省级环境保护部门认定的环境监测机构应当接受所在地环境保护部门所属环境监测机构的监督检查。"},{"i":22,"n":"第二十二条","txt":"辐射环境监测的管理，参照本办法执行。"},{"i":23,"n":"第二十三条","txt":"本办法自2007年9月1日起施行。"}],"huanjingjianguanzhongdiandanweimingluguanlibanfa":[{"i":1,"n":"第一条","txt":"为了加强对环境监管重点单位的监督管理，强化精准治污，根据《中华人民共和国环境保护法》和水、大气、噪声、土壤等污染防治法律，以及地下水管理、排污许可管理等行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法所称环境监管重点单位，包括依法确定的水环境重点排污单位、地下水污染防治重点排污单位、大气环境重点排污单位、噪声重点排污单位、土壤污染重点监管单位，以及环境风险重点管控单位。 同一企业事业单位可以同时属于不同类别的环境监管重点单位。"},{"i":3,"n":"第三条","txt":"国务院生态环境主管部门负责指导、协调和监督环境监管重点单位名录的确定和管理，建立、运行环境监管重点单位名录信息平台。 省级生态环境主管部门负责协调和监督本行政区域环境监管重点单位名录的确定和发布。 设区的市级生态环境主管部门负责本行政区域环境监管重点单位名录的确定、管理和发布。"},{"i":4,"n":"第四条","txt":"环境监管重点单位应当依法履行自行监测、信息公开等生态环境法律义务，采取措施防治环境污染，防范环境风险。 各级生态环境主管部门应当加强对环境监管重点单位的监督管理。"},{"i":5,"n":"第五条","txt":"水环境重点排污单位应当根据本行政区域的水环境容量、重点水污染物排放总量控制指标的要求以及排污单位排放水污染物的种类、数量和浓度等因素确定。 具备下列条件之一的，应当列为水环境重点排污单位： （一）化学需氧量、氨氮、总氮、总磷中任一种水污染物近三年内任一年度排放量大于设区的市级生态环境主管部门设定的筛选排放量限值的工业企业； （二）设有污水排放口的规模化畜禽养殖场； （三）工业废水集中处理厂，以及日处理能力10万吨以上或者日处理工业废水量2万吨以上的城镇生活污水处理厂。 设区的市级生态环境主管部门设定筛选排放量限值，应当确保所筛选的水环境重点排污单位工业水污染物排放量之和，不低于该行政区域排放源统计调查的工业水污染物排放总量的65%。"},{"i":6,"n":"第六条","txt":"地下水污染防治重点排污单位应当根据本行政区域地下水污染防治需要、排污单位排放有毒有害物质情况等因素确定。 具备下列条件之一的，应当列为地下水污染防治重点排污单位： （一）位于地下水污染防治重点区内且设有水污染物排放口的企业事业单位； （二）一级和二级环境监督管理尾矿库的运营、管理单位； （三）涉及填埋处置的危险废物处置场的运营、管理单位； （四）日处理能力500吨以上的生活垃圾填埋场的运营、管理单位。"},{"i":7,"n":"第七条","txt":"大气环境重点排污单位应当根据本行政区域的大气环境承载力、重点大气污染物排放总量控制指标的要求以及排污单位排放大气污染物的种类、数量和浓度等因素确定。 具备下列条件之一的，应当列为大气环境重点排污单位： （一）二氧化硫、氮氧化物、颗粒物、挥发性有机物中任一种大气污染物近三年内任一年度排放量大于设区的市级生态环境主管部门设定的筛选排放量限值的工业企业； （二）太阳能光伏玻璃行业企业，其他玻璃制造、玻璃制品、玻璃纤维行业中以天然气为燃料的规模以上企业； （三）陶瓷、耐火材料行业中以煤、石油焦、油、发生炉煤气为燃料的企业； （四）陶瓷、耐火材料行业中以天然气为燃料的规模以上企业； （五）工业涂装行业规模以上企业，全部使用符合国家规定的水性、无溶剂、辐射固化、粉末等四类低挥发性有机物含量涂料的除外； （六）包装印刷行业规模以上企业，全部使用符合国家规定的低挥发性有机物含量油墨的除外。 设区的市级"},{"i":8,"n":"第八条","txt":"生产、加工使用或者排放重点管控新污染物清单中所列化学物质的企业事业单位，应当纳入重点排污单位。"},{"i":9,"n":"第九条","txt":"噪声重点排污单位应当根据本行政区域噪声排放状况、声环境质量改善要求等因素确定。 具备下列条件之一的工业企业，应当列为噪声重点排污单位： （一）位于噪声敏感建筑物集中区域或者厂界外200米范围内存在噪声敏感建筑物集中区域，且造成噪声污染的； （二）影响所在行政区域完成声环境质量改善规划设定目标的； （三）噪声污染问题突出、群众反映强烈的。"},{"i":10,"n":"第十条","txt":"土壤污染重点监管单位应当根据本行政区域土壤污染防治需要、有毒有害物质排放情况等因素确定。 具备下列条件之一的，应当列为土壤污染重点监管单位： （一）有色金属矿采选、有色金属冶炼、石油开采、石油加工、化工、焦化、电镀、制革行业规模以上企业； （二）位于土壤污染潜在风险高的地块，且生产、使用、贮存、处置或者排放有毒有害物质的企业； （三）位于耕地土壤重金属污染突出地区的涉镉排放企业。"},{"i":11,"n":"第十一条","txt":"具备下列条件之一的，可以列为环境风险重点管控单位： （一）年产生危险废物100吨以上的企业； （二）具有危险废物自行利用处置设施的企业； （三）持有危险废物经营许可证的企业； （四）生活垃圾填埋场（含已封场的）或者生活垃圾焚烧厂的运营维护单位； （五）矿产资源（除铀、钍矿外）开发利用活动中原矿、中间产品、尾矿（渣）或者其他残留物中铀（钍）系单个核素含量超过1Bq/g的企业。"},{"i":12,"n":"第十二条","txt":"排污许可分类管理名录规定的实施排污许可重点管理的企业事业单位，应当列为重点排污单位。 《固定污染源排污许可分类管理名录（2019年版）》规定的实施排污许可重点管理的条件为“纳入重点排污单位名录”的企业事业单位，根据本办法第五条、第七条的规定不再符合重点排污单位筛选条件的，设区的市级生态环境主管部门应当及时予以调整。"},{"i":13,"n":"第十三条","txt":"设区的市级生态环境主管部门可以根据本行政区域环境质量状况、环境质量改善要求、污染物排放情况、有毒有害物质以及环境风险管控要求等，将确有必要实施重点监管的企业事业单位列入环境监管重点单位名录。"},{"i":14,"n":"第十四条","txt":"设区的市级生态环境主管部门应当在每年1月底前提出本年度环境监管重点单位初步名录，上传至环境监管重点单位名录信息平台。 省级以上生态环境主管部门可以于每年2月底前，通过环境监管重点单位名录信息平台，提出对环境监管重点单位初步名录的调整建议。 设区的市级生态环境主管部门可以根据省级以上生态环境主管部门提出的调整建议，对本年度环境监管重点单位初步名录进行调整，并于3月底前确定本年度环境监管重点单位名录，依法向社会公布。"},{"i":15,"n":"第十五条","txt":"列入环境监管重点单位名录的企业事业单位，在名录存续期间出现不符合本办法规定的筛选条件情形的，应当在确定下一年度环境监管重点单位名录时予以调整。"},{"i":16,"n":"第十六条","txt":"本办法由国务院生态环境主管部门负责解释。"},{"i":17,"n":"第十七条","txt":"本办法自2023年1月1日起施行。《关于印发<重点排污单位名录管理规定（试行）>的通知》（环办监测〔2017〕86号）同时废止。"}],"shengtaihuanjingbiaozhunguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强生态环境标准管理工作，依据《中华人民共和国环境保护法》《中华人民共和国标准化法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于生态环境标准的制定、实施、备案和评估。"},{"i":3,"n":"第三条","txt":"本办法所称生态环境标准，是指由国务院生态环境主管部门和省级人民政府依法制定的生态环境保护工作中需要统一的各项技术要求。"},{"i":4,"n":"第四条","txt":"生态环境标准分为国家生态环境标准和地方生态环境标准。 国家生态环境标准包括国家生态环境质量标准、国家生态环境风险管控标准、国家污染物排放标准、国家生态环境监测标准、国家生态环境基础标准和国家生态环境管理技术规范。国家生态环境标准在全国范围或者标准指定区域范围执行。 地方生态环境标准包括地方生态环境质量标准、地方生态环境风险管控标准、地方污染物排放标准和地方其他生态环境标准。地方生态环境标准在发布该标准的省、自治区、直辖市行政区域范围或者标准指定区域范围执行。 有地方生态环境质量标准、地方生态环境风险管控标准和地方污染物排放标准的地区，应当依法优先执行地方标准。"},{"i":5,"n":"第五条","txt":"国家和地方生态环境质量标准、生态环境风险管控标准、污染物排放标准和法律法规规定强制执行的其他生态环境标准，以强制性标准的形式发布。法律法规未规定强制执行的国家和地方生态环境标准，以推荐性标准的形式发布。 强制性生态环境标准必须执行。 推荐性生态环境标准被强制性生态环境标准或者规章、行政规范性文件引用并赋予其强制执行效力的，被引用的内容必须执行，推荐性生态环境标准本身的法律效力不变。"},{"i":6,"n":"第六条","txt":"国务院生态环境主管部门依法制定并组织实施国家生态环境标准，评估国家生态环境标准实施情况，开展地方生态环境标准备案，指导地方生态环境标准管理工作。 省级人民政府依法制定地方生态环境质量标准、地方生态环境风险管控标准和地方污染物排放标准，并报国务院生态环境主管部门备案。机动车等移动源大气污染物排放标准由国务院生态环境主管部门统一制定。 地方各级生态环境主管部门在各自职责范围内组织实施生态环境标准。"},{"i":7,"n":"第七条","txt":"制定生态环境标准，应当遵循合法合规、体系协调、科学可行、程序规范等原则。 制定国家生态环境标准，应当根据生态环境保护需求编制标准项目计划，组织相关事业单位、行业协会、科研机构或者高等院校等开展标准起草工作，广泛征求国家有关部门、地方政府及相关部门、行业协会、企业事业单位和公众等方面的意见，并组织专家进行审查和论证。具体工作程序与要求由国务院生态环境主管部门另行制定。"},{"i":8,"n":"第八条","txt":"制定生态环境标准，不得增加法律法规规定之外的行政权力事项或者减少法定职责；不得设定行政许可、行政处罚、行政强制等事项，增加办理行政许可事项的条件，规定出具循环证明、重复证明、无谓证明的内容；不得违法减损公民、法人和其他组织的合法权益或者增加其义务；不得超越职权规定应由市场调节、企业和社会自律、公民自我管理的事项；不得违法制定含有排除或者限制公平竞争内容的措施，违法干预或者影响市场主体正常生产经营活动，违法设置市场准入和退出条件等。 生态环境标准中不得规定采用特定企业的技术、产品和服务，不得出现特定企业的商标名称，不得规定采用尚在保护期内的专利技术和配方不公开的试剂，不得规定使用国家明令禁止或者淘汰使用的试剂。"},{"i":9,"n":"第九条","txt":"生态环境标准发布时，应当留出适当的实施过渡期。 生态环境质量标准、生态环境风险管控标准、污染物排放标准等标准发布前，应当明确配套的污染防治、监测、执法等方面的指南、标准、规范及相关制定或者修改计划，以及标准宣传培训方案，确保标准有效实施。"},{"i":10,"n":"第十条","txt":"为保护生态环境，保障公众健康，增进民生福祉，促进经济社会可持续发展，限制环境中有害物质和因素，制定生态环境质量标准。"},{"i":11,"n":"第十一条","txt":"生态环境质量标准包括大气环境质量标准、水环境质量标准、海洋环境质量标准、声环境质量标准、核与辐射安全基本标准。"},{"i":12,"n":"第十二条","txt":"制定生态环境质量标准，应当反映生态环境质量特征，以生态环境基准研究成果为依据，与经济社会发展和公众生态环境质量需求相适应，科学合理确定生态环境保护目标。"},{"i":13,"n":"第十三条","txt":"生态环境质量标准应当包括下列内容： （一） 功能分类； （二） 控制项目及限值规定； （三） 监测要求； （四） 生态环境质量评价方法； （五） 标准实施与监督等。"},{"i":14,"n":"第十四条","txt":"生态环境质量标准是开展生态环境质量目标管理的技术依据，由生态环境主管部门统一组织实施。 实施大气、水、海洋、声环境质量标准，应当按照标准规定的生态环境功能类型划分功能区，明确适用的控制项目指标和控制要求，并采取措施达到生态环境质量标准的要求。 实施核与辐射安全基本标准，应当确保核与辐射的公众暴露风险可控。"},{"i":15,"n":"第十五条","txt":"为保护生态环境，保障公众健康，推进生态环境风险筛查与分类管理，维护生态环境安全，控制生态环境中的有害物质和因素，制定生态环境风险管控标准。"},{"i":16,"n":"第十六条","txt":"生态环境风险管控标准包括土壤污染风险管控标准以及法律法规规定的其他环境风险管控标准。"},{"i":17,"n":"第十七条","txt":"制定生态环境风险管控标准，应当根据环境污染状况、公众健康风险、生态环境风险、环境背景值和生态环境基准研究成果等因素，区分不同保护对象和用途功能，科学合理确定风险管控要求。"},{"i":18,"n":"第十八条","txt":"生态环境风险管控标准应当包括下列内容： （一） 功能分类； （二） 控制项目及风险管控值规定； （三） 监测要求； （四） 风险管控值使用规则； （五） 标准实施与监督等。"},{"i":19,"n":"第十九条","txt":"生态环境风险管控标准是开展生态环境风险管理的技术依据。 实施土壤污染风险管控标准，应当按照土地用途分类管理，管控风险，实现安全利用。"},{"i":20,"n":"第二十条","txt":"为改善生态环境质量，控制排入环境中的污染物或者其他有害因素，根据生态环境质量标准和经济、技术条件，制定污染物排放标准。 国家污染物排放标准是对全国范围内污染物排放控制的基本要求。地方污染物排放标准是地方为进一步改善生态环境质量和优化经济社会发展，对本行政区域提出的国家污染物排放标准补充规定或者更加严格的规定。"},{"i":21,"n":"第二十一条","txt":"污染物排放标准包括大气污染物排放标准、水污染物排放标准、固体废物污染控制标准、环境噪声排放控制标准和放射性污染防治标准等。 水和大气污染物排放标准，根据适用对象分为行业型、综合型、通用型、流域（海域）或者区域型污染物排放标准。 行业型污染物排放标准适用于特定行业或者产品污染源的排放控制；综合型污染物排放标准适用于行业型污染物排放标准适用范围以外的其他行业污染源的排放控制；通用型污染物排放标准适用于跨行业通用生产工艺、设备、操作过程或者特定污染物、特定排放方式的排放控制；流域（海域）或者区域型污染物排放标准适用于特定流域（海域）或者区域范围内的污染源排放控制。"},{"i":22,"n":"第二十二条","txt":"制定行业型或者综合型污染物排放标准，应当反映所管控行业的污染物排放特征，以行业污染防治可行技术和可接受生态环境风险为主要依据，科学合理确定污染物排放控制要求。 制定通用型污染物排放标准，应当针对所管控的通用生产工艺、设备、操作过程的污染物排放特征，或者特定污染物、特定排放方式的排放特征，以污染防治可行技术、可接受生态环境风险、感官阈值等为主要依据，科学合理确定污染物排放控制要求。 制定流域（海域）或者区域型污染物排放标准，应当围绕改善生态环境质量、防范生态环境风险、促进转型发展，在国家污染物排放标准基础上作出补充规定或者更加严格的规定。"},{"i":23,"n":"第二十三条","txt":"污染物排放标准应当包括下列内容： （一）适用的排放控制对象、排放方式、排放去向等情形； （二）排放控制项目、指标、限值和监测位置等要求，以及必要的技术和管理措施要求； （三）适用的监测技术规范、监测分析方法、核算方法及其记录要求； （四）达标判定要求； （五）标准实施与监督等。"},{"i":24,"n":"第二十四条","txt":"污染物排放标准按照下列顺序执行： （一）地方污染物排放标准优先于国家污染物排放标准；地方污染物排放标准未规定的项目，应当执行国家污染物排放标准的相关规定。 （二）同属国家污染物排放标准的，行业型污染物排放标准优先于综合型和通用型污染物排放标准；行业型或者综合型污染物排放标准未规定的项目，应当执行通用型污染物排放标准的相关规定。 （三）同属地方污染物排放标准的，流域（海域）或者区域型污染物排放标准优先于行业型污染物排放标准，行业型污染物排放标准优先于综合型和通用型污染物排放标准。流域（海域）或者区域型污染物排放标准未规定的项目，应当执行行业型或者综合型污染物排放标准的相关规定；流域（海域）或者区域型、行业型或者综合型污染物排放标准均未规定的项目，应当执行通用型污染物排放标准的相关规定。"},{"i":25,"n":"第二十五条","txt":"污染物排放标准规定的污染物排放方式、排放限值等是判定污染物排放是否超标的技术依据。排放污染物或者其他有害因素，应当符合污染物排放标准规定的各项控制要求。"},{"i":26,"n":"第二十六条","txt":"为监测生态环境质量和污染物排放情况，开展达标评定和风险筛查与管控，规范布点采样、分析测试、监测仪器、卫星遥感影像质量、量值传递、质量控制、数据处理等监测技术要求，制定生态环境监测标准。"},{"i":27,"n":"第二十七条","txt":"生态环境监测标准包括生态环境监测技术规范、生态环境监测分析方法标准、生态环境监测仪器及系统技术要求、生态环境标准样品等。"},{"i":28,"n":"第二十八条","txt":"制定生态环境监测标准应当配套支持生态环境质量标准、生态环境风险管控标准、污染物排放标准的制定和实施，以及优先控制化学品环境管理、国际履约等生态环境管理及监督执法需求，采用稳定可靠且经过验证的方法，在保证标准的科学性、合理性、普遍适用性的前提下提高便捷性，易于推广使用。"},{"i":29,"n":"第二十九条","txt":"生态环境监测技术规范应当包括监测方案制定、布点采样、监测项目与分析方法、数据分析与报告、监测质量保证与质量控制等内容。 生态环境监测分析方法标准应当包括试剂材料、仪器与设备、样品、测定操作步骤、结果表示等内容。 生态环境监测仪器及系统技术要求应当包括测定范围、性能要求、检验方法、操作说明及校验等内容。"},{"i":30,"n":"第三十条","txt":"制定生态环境质量标准、生态环境风险管控标准和污染物排放标准时，应当采用国务院生态环境主管部门制定的生态环境监测分析方法标准；国务院生态环境主管部门尚未制定适用的生态环境监测分析方法标准的，可以采用其他部门制定的监测分析方法标准。 对生态环境质量标准、生态环境风险管控标准和污染物排放标准实施后发布的生态环境监测分析方法标准，未明确是否适用于相关标准的，国务院生态环境主管部门可以组织开展适用性、等效性比对；通过比对的，可以用于生态环境质量标准、生态环境风险管控标准和污染物排放标准中控制项目的测定。"},{"i":31,"n":"第三十一条","txt":"对地方生态环境质量标准、地方生态环境风险管控标准或者地方污染物排放标准中规定的控制项目，国务院生态环境主管部门尚未制定适用的国家生态环境监测分析方法标准的，可以在地方生态环境质量标准、地方生态环境风险管控标准或者地方污染物排放标准中规定相应的监测分析方法，或者采用地方生态环境监测分析方法标准。适用于该控制项目监测的国家生态环境监测分析方法标准实施后，地方生态环境监测分析方法不再执行。"},{"i":32,"n":"第三十二条","txt":"为统一规范生态环境标准的制订技术工作和生态环境管理工作中具有通用指导意义的技术要求，制定生态环境基础标准，包括生态环境标准制订技术导则，生态环境通用术语、图形符号、编码和代号（代码）及其相应的编制规则等。"},{"i":33,"n":"第三十三条","txt":"制定生态环境标准制订技术导则，应当明确标准的定位、基本原则、技术路线、技术方法和要求，以及对标准文本及编制说明等材料的内容和格式要求。"},{"i":34,"n":"第三十四条","txt":"制定生态环境通用术语、图形符号、编码和代号（代码）编制规则等，应当借鉴国际标准和国内标准的相关规定，做到准确、通用、可辨识，力求简洁易懂。"},{"i":35,"n":"第三十五条","txt":"制定生态环境标准，应当符合相应类别生态环境标准制订技术导则的要求，采用生态环境基础标准规定的通用术语、图形符号、编码和代号（代码）编制规则等，做到标准内容衔接、体系协调、格式规范。 在生态环境保护工作中使用专业用语和名词术语，设置图形标志，对档案信息进行分类、编码等，应当采用相应的术语、图形、编码技术标准。"},{"i":36,"n":"第三十六条","txt":"为规范各类生态环境保护管理工作的技术要求，制定生态环境管理技术规范，包括大气、水、海洋、土壤、固体废物、化学品、核与辐射安全、声与振动、自然生态、应对气候变化等领域的管理技术指南、导则、规程、规范等。"},{"i":37,"n":"第三十七条","txt":"制定生态环境管理技术规范应当有明确的生态环境管理需求，内容科学合理，针对性和可操作性强，有利于规范生态环境管理工作。"},{"i":38,"n":"第三十八条","txt":"生态环境管理技术规范为推荐性标准，在相关领域环境管理中实施。"},{"i":39,"n":"第三十九条","txt":"地方生态环境质量标准、地方生态环境风险管控标准和地方污染物排放标准可以对国家相应标准中未规定的项目作出补充规定，也可以对国家相应标准中已规定的项目作出更加严格的规定。"},{"i":40,"n":"第四十条","txt":"对本行政区域内没有国家污染物排放标准的特色产业、特有污染物，或者国家有明确要求的特定污染源或者污染物，应当补充制定地方污染物排放标准。 有下列情形之一的，应当制定比国家污染物排放标准更严格的地方污染物排放标准： （一）产业密集、环境问题突出的； （二）现有污染物排放标准不能满足行政区域内环境质量要求的； （三）行政区域环境形势复杂，无法适用统一的污染物排放标准的。 国务院生态环境主管部门应当加强对地方污染物排放标准制定工作的指导。"},{"i":41,"n":"第四十一条","txt":"制定地方流域（海域）或者区域型污染物排放标准，应当按照生态环境质量改善要求，进行合理分区，确定污染物排放控制要求，促进流域（海域）或者区域内行业优化布局、调整结构、转型升级。"},{"i":42,"n":"第四十二条","txt":"制定地方生态环境标准，或者提前执行国家污染物排放标准中相应排放控制要求的，应当根据本行政区域生态环境质量改善需求和经济、技术条件，进行全面评估论证，并充分听取各方意见。"},{"i":43,"n":"第四十三条","txt":"地方生态环境质量标准、地方生态环境风险管控标准和地方污染物排放标准发布后，省级人民政府或者其委托的省级生态环境主管部门应当依法报国务院生态环境主管部门备案。"},{"i":44,"n":"第四十四条","txt":"地方生态环境质量标准、地方生态环境风险管控标准和地方污染物排放标准报国务院生态环境主管部门备案时，应当提交标准文本、编制说明、发布文件等材料。 标准编制说明应当设立专章，说明与该标准适用范围相同或者交叉的国家生态环境标准中控制要求的对比分析情况。"},{"i":45,"n":"第四十五条","txt":"国务院生态环境主管部门收到地方生态环境标准备案材料后，予以备案，并公开相关备案信息；发现问题的，可以告知相关省级生态环境主管部门，建议按照法定程序修改。"},{"i":46,"n":"第四十六条","txt":"依法提前实施国家机动车大气污染物排放标准中相应阶段排放限值的，应当报国务院生态环境主管部门备案。"},{"i":47,"n":"第四十七条","txt":"新发布实施的国家生态环境质量标准、生态环境风险管控标准或者污染物排放标准规定的控制要求严于现行的地方生态环境质量标准、生态环境风险管控标准或者污染物排放标准的，地方生态环境质量标准、生态环境风险管控标准或者污染物排放标准，应当依法修订或者废止。"},{"i":48,"n":"第四十八条","txt":"为掌握生态环境标准实际执行情况及存在的问题，提升生态环境标准科学性、系统性、适用性，标准制定机关应当根据生态环境和经济社会发展形势，结合相关科学技术进展和实际工作需要，组织评估生态环境标准实施情况，并根据评估结果对标准适时进行修订。"},{"i":49,"n":"第四十九条","txt":"强制性生态环境标准应当定期开展实施情况评估，与其配套的推荐性生态环境标准实施情况可以同步开展评估。"},{"i":50,"n":"第五十条","txt":"生态环境质量标准实施评估，应当依据生态环境基准研究进展，针对生态环境质量特征的演变，评估标准技术内容的科学合理性。 生态环境风险管控标准实施评估，应当依据环境背景值、生态环境基准和环境风险评估研究进展，针对环境风险特征的演变，评估标准风险管控要求的科学合理性。 污染物排放标准实施评估，应当关注标准实施中普遍反映的问题，重点评估标准规定内容的执行情况，论证污染控制项目、排放限值等设置的合理性，分析标准实施的生态环境效益、经济成本、达标技术和达标率，开展影响标准实施的制约因素分析并提出解决建议。 生态环境监测标准和生态环境管理技术规范的实施评估，应当结合标准使用过程中反馈的问题、建议和相关技术手段的发展，重点评估标准规定内容的适用性和科学性，以及与生态环境质量标准、生态环境风险管控标准和污染物排放标准的协调性。"},{"i":51,"n":"第五十一条","txt":"生态环境标准由其制定机关委托的出版机构出版、发行，依法公开。省级以上人民政府生态环境主管部门应当在其网站上公布相关的生态环境标准，供公众免费查阅、下载。"},{"i":52,"n":"第五十二条","txt":"生态环境标准由其制定机关负责解释，标准解释与标准正文具有同等效力。相关技术单位可以受标准制定机关委托，对标准内容提供技术咨询。"},{"i":53,"n":"第五十三条","txt":"本办法由国务院生态环境主管部门负责解释。"},{"i":54,"n":"第五十四条","txt":"本办法自2021年2月1日起施行。《环境标准管理办法》（国家环境保护总局令第3号）和《地方环境质量标准和污染物排放标准备案管理办法》（环境保护部令第9号）同时废止。"}],"shengtaihuanjingtongjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为加强和规范生态环境统计管理，保障生态环境统计资料真实性、准确性、完整性和及时性，发挥统计支撑生态环境工作重要作用，根据《中华人民共和国环境保护法》《中华人民共和国统计法》《中华人民共和国统计法实施条例》等有关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"生态环境统计基本任务是对生态环境状况和生态环境保护工作情况进行统计调查、统计分析，提供统计资料和统计咨询意见，实行统计监督。 生态环境统计内容包括生态环境质量、环境污染及其防治、生态保护、应对气候变化、核与辐射安全、生态环境管理及其他有关生态环境保护事项。"},{"i":3,"n":"第三条","txt":"生态环境统计工作实行统一管理、分级负责的管理体制。 生态环境部在国家统计局业务指导下，对全国生态环境统计工作进行统一管理，制定生态环境统计规章制度、标准规范、工作计划，组织实施全国生态环境统计工作，汇总、管理和公布全国生态环境统计资料。 地方各级生态环境主管部门在上级生态环境主管部门和本级人民政府统计机构指导下，组织实施本行政区域生态环境统计工作。"},{"i":4,"n":"第四条","txt":"各级生态环境主管部门应当根据生态环境统计任务和本地区、本部门生态环境管理需要，在下列方面加强对生态环境统计工作的领导和监督： （一）将生态环境统计事业发展纳入生态环境工作计划，并组织实施； （二）明确生态环境统计机构； （三）安排并保障生态环境统计业务经费和人员； （四）按时完成上级生态环境主管部门依法布置的统计任务，采取措施保障统计资料的真实性、准确性、完整性和及时性； （五）开展生态环境统计科学研究，改进和完善生态环境统计制度和方法； （六）防范和惩治生态环境统计造假、弄虚作假； （七）落实生态环境统计改革任务； （八）建立生态环境统计工作奖惩制度。"},{"i":5,"n":"第五条","txt":"国家机关、企业事业单位、其他生产经营者和个人等生态环境统计调查对象，应当依照有关法律、法规和本办法的规定，真实、准确、完整、及时地提供生态环境统计调查所需的资料，不得提供不真实或者不完整的统计资料，不得迟报、拒报统计资料。"},{"i":6,"n":"第六条","txt":"各级生态环境主管部门应当根据统计任务需要，明确承担统一组织协调生态环境统计工作职责的综合机构（以下简称生态环境统计综合机构）及其人员。"},{"i":7,"n":"第七条","txt":"各级生态环境统计综合机构的职责是： （一）制定生态环境统计工作规章制度和工作计划，并组织实施； （二）建立健全生态环境统计指标体系，归口管理、按照规定申报生态环境统计调查项目； （三）开展生态环境统计分析和预测； （四）实行生态环境统计质量控制和监督，采取措施保障统计资料的真实性、准确性、完整性和及时性； （五）收集、汇总和审核生态环境统计资料，建立和管理生态环境统计数据库，支撑相关生态环境管理工作，按照规定提供对外公布所需的生态环境统计资料，审核对外共享的生态环境统计调查项目范围内的资料； （六）按照规定向上级生态环境主管部门和本级人民政府统计机构报送生态环境统计资料； （七）指导下级生态环境主管部门和统计调查对象的生态环境统计工作，组织业务培训； （八）开展生态环境统计科研和生态环境统计业务的交流与合作； （九）承担生态环境统计的保密工作。"},{"i":8,"n":"第八条","txt":"各级生态环境主管部门承担相关生态环境统计调查任务的职能机构负责其业务范围内的统计工作，其职责是： （一）编制业务范围内的生态环境统计调查制度，提交同级生态环境统计综合机构审核并按照规定配合完成生态环境统计调查项目申报工作，经批准或者备案后组织实施； （二）收集、汇总、审核其业务范围内的生态环境统计资料，并按照统计调查制度要求，报送上级生态环境主管部门和同级生态环境统计综合机构； （三）落实生态环境统计数据质量控制要求，保障统计数据质量； （四）开展生态环境统计分析，对相关业务工作提出建议； （五）承担相关生态环境统计的保密工作。"},{"i":9,"n":"第九条","txt":"作为生态环境统计调查对象的国家机关、企业事业单位、其他生产经营者应当依法履行下列生态环境统计义务： （一）按照国家有关规定设置生态环境统计原始记录、统计台账，建立健全统计资料的审核、签署、交接、归档等管理制度； （二）按照规定报送和提供生态环境统计资料，管理生态环境统计调查表和基本生态环境统计资料。 生态环境统计资料的审核、签署人员应当对其审核、签署的统计资料的真实性、准确性和完整性负责。"},{"i":10,"n":"第十条","txt":"各级生态环境主管部门及其生态环境统计人员在生态环境统计工作中依法行使统计调查、统计报告、统计监督职权。"},{"i":11,"n":"第十一条","txt":"生态环境统计人员应当具备相应的专业知识和业务能力。各级生态环境主管部门应当提高其统计人员专业素质，保障统计队伍稳定性。 各级生态环境主管部门应当加强专业培训和职业道德教育，定期对生态环境统计人员和统计调查对象相关工作人员开展培训。"},{"i":12,"n":"第十二条","txt":"生态环境统计调查项目分为综合性调查项目和专项调查项目，调查方法分为全面调查、重点调查、抽样调查等，调查周期包括年度、半年度、季度、月度等。"},{"i":13,"n":"第十三条","txt":"生态环境部执行相关法律、行政法规、国务院的决定和履行本部门职责，需要开展统计活动的，应当制定相应的部门统计调查项目。 生态环境部制定的统计调查项目，统计调查对象属于生态环境部管辖系统或者利用行政记录加工获取统计资料的，报国家统计局备案；统计调查对象超出生态环境部管辖系统的，报国家统计局审批。"},{"i":14,"n":"第十四条","txt":"地方各级生态环境主管部门制定的统计调查项目，报本级人民政府统计机构审批，其主要内容不得与生态环境部制定的统计调查项目内容重复、矛盾。"},{"i":15,"n":"第十五条","txt":"制定生态环境统计调查项目应当遵循以下原则： （一）制定新的生态环境统计调查项目，应当就项目必要性、可行性、科学性进行论证，征求有关地方、部门、统计调查对象和专家的意见，并按照会议制度集体讨论决定，重要统计调查项目应当进行试点； （二）可以通过行政记录和大数据加工整理获得统计资料的，不再重复开展统计调查；可以通过已经批准实施的各种统计调查整理获得统计资料的，不再重复开展统计调查； （三）统计调查应当尽量减少调查频率，缩小调查规模，降低调查成本，减轻基层统计人员和统计调查对象负担。抽样调查、重点调查可以满足需要的，不得开展全面调查；一次性调查可以满足需要的，不得进行经常性调查； （四）生态环境统计调查项目不得与国家统计调查项目的内容重复、矛盾。"},{"i":16,"n":"第十六条","txt":"制定生态环境统计调查项目，应当同时制定该项目的统计调查制度。 生态环境统计调查制度应当对调查目的、内容、方法、对象、组织方式、调查表式、统计资料的报送和公布等作出规定。 变更统计调查制度的内容，应当报经原审批机关批准或者原备案机关备案。"},{"i":17,"n":"第十七条","txt":"生态环境统计调查项目经批准或者备案后，应当在统计调查表的右上角标明表号、制定机关、批准文号或者备案文号、有效期限等标志。 对未标明前款规定的标志或者超过有效期限的统计调查表，生态环境统计调查对象有权拒绝填报。"},{"i":18,"n":"第十八条","txt":"生态环境统计调查表中的指标必须有确定的涵义、数据采集来源和计算方法。 生态环境部制定全国性生态环境统计调查表，并对其指标的涵义、数据采集来源、计算方法等作出统一说明。"},{"i":19,"n":"第十九条","txt":"在生态环境统计调查中，排放源排放量按照监测数据法、产排污系数/排放因子法、物料衡算法等方法进行核算。 排污许可证执行报告中报告的污染物排放量可以作为生态环境统计的依据。 生态环境部组织制定统一的排放源产排污系数，按照规定程序发布，并适时评估修订。"},{"i":20,"n":"第二十条","txt":"各级生态环境主管部门应当严格按照批准或者备案的生态环境统计调查制度组织实施生态环境统计调查。"},{"i":21,"n":"第二十一条","txt":"各级生态环境主管部门应当建立健全生态环境统计工作流程规范和数据质量控制制度，严格实施数据采集、核算、汇总、审核、分析等环节的全流程质量控制。"},{"i":22,"n":"第二十二条","txt":"各级生态环境主管部门应当建立生态环境统计调查对象名录库，并实施动态管理。"},{"i":23,"n":"第二十三条","txt":"各级生态环境主管部门组织实施生态环境统计调查，应当就生态环境统计调查对象的法定填报义务、主要指标涵义和有关填报要求等，向统计调查对象作出说明。"},{"i":24,"n":"第二十四条","txt":"国家机关、企业事业单位、其他生产经营者作为生态环境统计调查对象提供统计资料，应当由填报人员和单位负责人签字，并加盖公章。个人作为生态环境统计调查对象提供统计资料，应当由本人签字。统计调查制度规定不需要签字、加盖公章的除外。 统计调查对象使用网络提供统计资料的，按照国家有关规定执行。"},{"i":25,"n":"第二十五条","txt":"各级生态环境主管部门应当严格落实统计数据审核要求，采取资料核查、现场核查以及其他有效方式，对统计调查对象提供的统计资料进行审核。统计资料不完整或者存在明显错误的，由统计调查对象依法予以补充或者改正。"},{"i":26,"n":"第二十六条","txt":"各级生态环境主管部门及其统计人员应当对其负责搜集、审核、录入的统计资料与统计调查对象报送的统计资料的一致性负责，不得伪造、篡改统计资料，不得要求统计调查对象或者其他机构、人员提供不真实的统计资料。"},{"i":27,"n":"第二十七条","txt":"各级生态环境主管部门应当加强统计信息化建设，将生态环境统计信息化建设列入发展计划，积极推动现代信息技术的应用，完善生态环境统计信息系统，推进统计信息搜集、处理、传输、共享、存储技术和统计数据库现代化。"},{"i":28,"n":"第二十八条","txt":"各级生态环境主管部门应当推动使用行政记录、大数据等手段搜集整理统计资料，充分运用先进技术方法，提高生态环境统计信息挖掘、处理和分析能力，提供多样化统计产品，提升统计分析应用水平。"},{"i":29,"n":"第二十九条","txt":"各级生态环境主管部门可以根据需要通过向社会购买服务等方式组织实施统计调查和资料开发。"},{"i":30,"n":"第三十条","txt":"生态环境统计资料是制定生态环境政策、规划、计划，开展生态环境考核、履约等工作的基本依据。"},{"i":31,"n":"第三十一条","txt":"各级生态环境主管部门应当按照国家有关规定建立统计资料的保存、管理制度，建立健全信息共享机制，推进生态环境统计资料共享和应用。"},{"i":32,"n":"第三十二条","txt":"各级生态环境主管部门应当按照国家有关规定和已批准或者备案的生态环境统计调查制度，公布生态环境统计资料，并按照要求提供给本级人民政府统计机构。"},{"i":33,"n":"第三十三条","txt":"各级生态环境主管部门的相关职能机构应当在规定期限内，将其组织实施统计调查所获得的生态环境统计资料，报送同级生态环境统计综合机构。"},{"i":34,"n":"第三十四条","txt":"生态环境统计资料应当纳入生态环境统计年报或者以其他形式统一公布。 任何单位和个人不得违反规定公布生态环境统计资料，公布前不得违反规定对外提供。"},{"i":35,"n":"第三十五条","txt":"各级生态环境主管部门制定生态环境政策、中长期规划和年度计划，开展考核、履约等工作，需要使用生态环境统计资料的，应当以生态环境统计综合机构提供的资料为准。"},{"i":36,"n":"第三十六条","txt":"各级生态环境主管部门应当执行国家有关统计资料保密管理的规定，加强对生态环境统计资料的保密管理。"},{"i":37,"n":"第三十七条","txt":"各级生态环境主管部门应当严格执行国家有关网络安全法律法规要求，建立健全网络安全保护制度，加强生态环境统计信息系统及数据库的安全建设和运维管理。"},{"i":38,"n":"第三十八条","txt":"各级生态环境主管部门和国家机关、企业事业单位、其他生产经营者等生态环境统计调查对象应当建立生态环境统计资料档案。 生态环境统计资料档案的保管、调用和移交，应当遵守国家有关统计资料管理和档案管理的规定。"},{"i":39,"n":"第三十九条","txt":"生态环境统计调查中获得的能够识别或者推断单个统计调查对象身份的资料应当依法严格管理，除作为统计执法依据外，不得直接作为对统计调查对象实施行政许可、行政处罚等具体行政行为的依据，不得用于完成统计任务以外的目的。"},{"i":40,"n":"第四十条","txt":"各级生态环境主管部门应当建立健全防范和惩治生态环境统计造假、弄虚作假责任体系，明确领导班子、相关负责人以及生态环境统计人员的责任。"},{"i":41,"n":"第四十一条","txt":"各级生态环境主管部门应当建立监督检查工作机制和相关制度，组织开展生态环境统计监督检查工作。 监督检查事项包括： （一）生态环境主管部门遵守、执行生态环境统计法律法规规章情况； （二）生态环境主管部门建立防范和惩治生态环境统计造假、弄虚作假责任制情况； （三）生态环境统计调查对象遵守生态环境统计法律法规规章、统计调查制度情况； （四）法律法规规章规定的其他事项。"},{"i":42,"n":"第四十二条","txt":"生态环境统计调查对象应当配合生态环境主管部门的监督检查工作。 任何单位和个人不得拒绝、阻碍对生态环境统计工作的监督检查。"},{"i":43,"n":"第四十三条","txt":"各级生态环境主管部门应当积极协助本级人民政府统计机构查处生态环境统计违法行为，及时移送有关统计违法案件材料。"},{"i":44,"n":"第四十四条","txt":"各级生态环境主管部门应当对在改革和完善生态环境统计制度、统计调查方法，组织实施统计调查任务，进行生态环境统计分析、预测和监督，开展生态环境统计科学研究等方面做出重要贡献的机构或者个人，给予表扬或者奖励。"},{"i":45,"n":"第四十五条","txt":"生态环境部定期对全国生态环境统计工作进行评估，按照规定对成绩突出的单位和个人进行表彰或者表扬。"},{"i":46,"n":"第四十六条","txt":"生态环境主管部门有下列行为之一的，依照《中华人民共和国统计法》《中华人民共和国统计法实施条例》予以处罚；对直接负责的主管人员和其他直接责任人员，依法予以处分： （一）未经批准擅自组织实施生态环境统计调查的； （二）未经批准擅自变更生态环境统计调查制度内容的； （三）未执行批准或者备案的生态环境统计调查制度的； （四）拒报、迟报或者伪造、篡改生态环境统计资料的； （五）要求生态环境统计调查对象或者其他机构、人员提供不真实的生态环境统计资料的； （六）违法公布生态环境统计资料的； （七）泄露生态环境统计调查对象的商业秘密、个人信息或者提供、泄露在生态环境统计调查中获得的能够识别或者推断单个生态环境统计调查对象身份的资料的； （八）其他违反法律法规规定的行为。"},{"i":47,"n":"第四十七条","txt":"生态环境统计调查对象有下列行为之一的，依照《中华人民共和国统计法》《中华人民共和国统计法实施条例》予以处罚；国家机关、企业事业单位或者其他生产经营者作为生态环境统计调查对象，其直接负责的主管人员和其他直接责任人员属于国家工作人员的，依法予以处分： （一）拒绝提供生态环境统计资料或者经催报后仍未按时提供生态环境统计资料的； （二）提供不真实或者不完整的生态环境统计资料的； （三）拒绝、阻碍生态环境统计调查、监督检查的； （四）转移、隐匿、篡改、毁弃或者拒绝提供原始记录和凭证、统计台账、统计调查表及其他相关证明和资料的； （五）其他违反法律法规规定的行为。"},{"i":48,"n":"第四十八条","txt":"全国污染源普查依照《全国污染源普查条例》规定组织实施。"},{"i":49,"n":"第四十九条","txt":"本办法自公布之日起施行。《环境统计管理办法》（国家环保总局令第37号）同时废止。"}],"shengtaihuanjingxingzhengchufabanfa":[{"i":1,"n":"第一条","txt":"为了规范生态环境行政处罚的实施，监督和保障生态环境主管部门依法实施行政处罚，维护公共利益和社会秩序，保护公民、法人或者其他组织的合法权益，根据《中华人民共和国行政处罚法》《中华人民共和国行政强制法》《中华人民共和国环境保护法》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"公民、法人或者其他组织违反生态环境保护法律、法规或者规章规定，应当给予行政处罚的，依照《中华人民共和国行政处罚法》和本办法规定的程序实施。"},{"i":3,"n":"第三条","txt":"实施生态环境行政处罚，纠正违法行为，应当坚持教育与处罚相结合，服务与管理相结合，引导和教育公民、法人或者其他组织自觉守法。"},{"i":4,"n":"第四条","txt":"实施生态环境行政处罚，应当依法维护公民、法人及其他组织的合法权益。对实施行政处罚过程中知悉的国家秘密、商业秘密或者个人隐私，应当依法予以保密。"},{"i":5,"n":"第五条","txt":"生态环境行政处罚遵循公正、公开原则。"},{"i":6,"n":"第六条","txt":"有下列情形之一的，执法人员应当自行申请回避，当事人也有权申请其回避： （一）是本案当事人或者当事人近亲属的； （二）本人或者近亲属与本案有直接利害关系的； （三）与本案有其他关系可能影响公正执法的； （四）法律、法规或者规章规定的其他回避情形。 申请回避，应当说明理由。生态环境主管部门应当对回避申请及时作出决定并通知申请人。 生态环境主管部门主要负责人的回避，由该部门负责人集体讨论决定；生态环境主管部门其他负责人的回避，由该部门主要负责人决定；其他执法人员的回避，由该部门负责人决定。"},{"i":7,"n":"第七条","txt":"对当事人的同一个违法行为，不得给予两次以上罚款的行政处罚。同一个违法行为违反多个法律规范应当给予罚款处罚的，按照罚款数额高的规定处罚。 实施行政处罚，适用违法行为发生时的法律、法规、规章的规定。但是，作出行政处罚决定时，法律、法规、规章已经被修改或者废止，且新的规定处罚较轻或者不认为是违法的，适用新的规定。"},{"i":8,"n":"第八条","txt":"根据法律、行政法规，生态环境行政处罚的种类包括： （一）警告、通报批评； （二）罚款、没收违法所得、没收非法财物； （三）暂扣许可证件、降低资质等级、吊销许可证件、一定时期内不得申请行政许可； （四）限制开展生产经营活动、责令停产整治、责令停产停业、责令关闭、限制从业、禁止从业； （五）责令限期拆除； （六）行政拘留； （七）法律、行政法规规定的其他行政处罚种类。"},{"i":9,"n":"第九条","txt":"生态环境主管部门实施行政处罚时，应当责令当事人改正或者限期改正违法行为。 责令改正违法行为决定可以单独下达，也可以与行政处罚决定一并下达。 责令改正或者限期改正不适用行政处罚程序的规定。"},{"i":10,"n":"第十条","txt":"生态环境行政处罚应当由具有行政执法资格的执法人员实施。执法人员不得少于两人，法律另有规定的除外。"},{"i":11,"n":"第十一条","txt":"生态环境主管部门在法定职权范围内实施生态环境行政处罚。 法律、法规授权的生态环境保护综合行政执法机构等组织在法定授权范围内实施生态环境行政处罚。"},{"i":12,"n":"第十二条","txt":"生态环境主管部门可以在其法定权限内书面委托符合《中华人民共和国行政处罚法》第二十一条规定条件的组织实施行政处罚。 受委托组织应当依照《中华人民共和国行政处罚法》和本办法的有关规定实施行政处罚。"},{"i":13,"n":"第十三条","txt":"生态环境行政处罚由违法行为发生地的具有行政处罚权的生态环境主管部门管辖。法律、行政法规另有规定的，从其规定。"},{"i":14,"n":"第十四条","txt":"两个以上生态环境主管部门都有管辖权的，由最先立案的生态环境主管部门管辖。 对管辖发生争议的，应当协商解决，协商不成的，报请共同的上一级生态环境主管部门指定管辖；也可以直接由共同的上一级生态环境主管部门指定管辖。"},{"i":15,"n":"第十五条","txt":"下级生态环境主管部门认为其管辖的案件重大、疑难或者实施处罚有困难的，可以报请上一级生态环境主管部门指定管辖。 上一级生态环境主管部门认为确有必要的，经通知下级生态环境主管部门和当事人，可以对下级生态环境主管部门管辖的案件直接管辖，或者指定其他有管辖权的生态环境主管部门管辖。 上级生态环境主管部门可以将其管辖的案件交由有管辖权的下级生态环境主管部门实施行政处罚。"},{"i":16,"n":"第十六条","txt":"对不属于本机关管辖的案件，生态环境主管部门应当移送有管辖权的生态环境主管部门处理。 受移送的生态环境主管部门对管辖权有异议的，应当报请共同的上一级生态环境主管部门指定管辖，不得再自行移送。"},{"i":17,"n":"第十七条","txt":"生态环境主管部门发现不属于本部门管辖的案件，应当按照有关要求和时限移送有管辖权的机关处理。 对涉嫌违法依法应当实施行政拘留的案件，生态环境主管部门应当移送公安机关或者海警机构。 违法行为涉嫌犯罪的，生态环境主管部门应当及时将案件移送司法机关。不得以行政处罚代替刑事处罚。 对涉嫌违法依法应当由人民政府责令停业、关闭的案件，生态环境主管部门应当报有批准权的人民政府。"},{"i":18,"n":"第十八条","txt":"除依法可以当场作出的行政处罚外，生态环境主管部门对涉嫌违反生态环境保护法律、法规和规章的违法行为，应当进行初步审查，并在十五日内决定是否立案。特殊情况下，经本机关负责人批准，可以延长十五日。法律、法规另有规定的除外。"},{"i":19,"n":"第十九条","txt":"经审查，符合下列四项条件的，予以立案： （一）有初步证据材料证明有涉嫌违反生态环境保护法律、法规和规章的违法行为； （二）依法应当或者可以给予行政处罚； （三）属于本机关管辖； （四）违法行为未超过《中华人民共和国行政处罚法》规定的追责期限。"},{"i":20,"n":"第二十条","txt":"对已经立案的案件，根据新情况发现不符合本办法第十九条立案条件的，应当撤销立案。"},{"i":21,"n":"第二十一条","txt":"生态环境主管部门对登记立案的生态环境违法行为，应当指定专人负责，全面、客观、公正地调查，收集有关证据。"},{"i":22,"n":"第二十二条","txt":"生态环境主管部门在办理行政处罚案件时，需要其他行政机关协助调查取证的，可以向有关机关发送协助调查函，提出协助请求。 生态环境主管部门在办理行政处罚案件时，需要其他生态环境主管部门协助调查取证的，可以发送协助调查函。收到协助调查函的生态环境主管部门对属于本机关职权范围的协助事项应当依法予以协助。无法协助的，应当及时函告请求协助调查的生态环境主管部门。"},{"i":23,"n":"第二十三条","txt":"执法人员在调查或者进行检查时，应当主动向当事人或者有关人员出示执法证件。当事人或者有关人员有权要求执法人员出示执法证件。执法人员不出示执法证件的，当事人或者有关人员有权拒绝接受调查或者检查。 当事人或者有关人员应当如实回答询问，并协助调查或者检查，不得拒绝、阻挠或者在接受检查时弄虚作假。询问或者检查应当制作笔录。"},{"i":24,"n":"第二十四条","txt":"执法人员有权采取下列措施： （一）进入有关场所进行检查、勘察、监测、录音、拍照、录像； （二）询问当事人及有关人员，要求其说明相关事项和提供有关材料； （三）查阅、复制生产记录、排污记录和其他有关材料。 必要时，生态环境主管部门可以采取暗查或者其他方式调查。在调查或者检查时，可以组织监测等技术人员提供技术支持。"},{"i":25,"n":"第二十五条","txt":"执法人员负有下列责任： （一）对当事人的基本情况、违法事实、危害后果、违法情节等情况进行全面、客观、及时、公正的调查； （二）依法收集与案件有关的证据，不得以暴力、威胁、引诱、欺骗以及其他违法手段获取证据； （三）询问当事人，应当告知其依法享有的权利； （四）听取当事人、证人或者其他有关人员的陈述、申辩，并如实记录。"},{"i":26,"n":"第二十六条","txt":"生态环境行政处罚证据包括： （一）书证； （二）物证； （三）视听资料； （四）电子数据； （五）证人证言； （六）当事人的陈述； （七）鉴定意见； （八）勘验笔录、现场笔录。 证据必须经查证属实，方可作为认定案件事实的根据。 以非法手段取得的证据，不得作为认定案件事实的根据。"},{"i":27,"n":"第二十七条","txt":"生态环境主管部门立案前依法取得的证据材料，可以作为案件的证据。 其他机关依法依职权调查收集的证据材料，可以作为案件的证据。"},{"i":28,"n":"第二十八条","txt":"对有关物品或者场所进行检查（勘察）时，应当制作现场检查（勘察）笔录，并可以根据实际情况进行音像记录。 现场检查（勘察）笔录应当载明现场检查起止时间、地点，执法人员基本信息，当事人或者有关人员基本信息，执法人员出示执法证件、告知当事人或者有关人员申请回避权利和配合调查义务情况，现场检查情况等信息，并由执法人员、当事人或者有关人员签名或者盖章。 当事人不在场、拒绝签字或者盖章的，执法人员应当在现场检查（勘察）笔录中注明。"},{"i":29,"n":"第二十九条","txt":"生态环境主管部门现场检查时，可以按照相关技术规范要求现场采样，获取的监测（检测）数据可以作为认定案件事实的证据。 执法人员应当将采样情况记入现场检查（勘察）笔录，可以采取拍照、录像记录采样情况。 生态环境主管部门取得监测（检测）报告或者鉴定意见后，应当将监测（检测）、鉴定结果告知当事人。"},{"i":30,"n":"第三十条","txt":"排污单位应当依法对自动监测数据的真实性和准确性负责，不得篡改、伪造。 实行自动监测数据标记规则行业的排污单位，应当按照国务院生态环境主管部门的规定对数据进行标记。经过标记的自动监测数据，可以作为认定案件事实的证据。 同一时段的现场监测（检测）数据与自动监测数据不一致，现场监测（检测）符合法定的监测标准和监测方法的，以该现场监测（检测）数据作为认定案件事实的证据。"},{"i":31,"n":"第三十一条","txt":"生态环境主管部门依照法律、行政法规规定利用电子技术监控设备收集、固定违法事实的，依照《中华人民共和国行政处罚法》有关规定执行。"},{"i":32,"n":"第三十二条","txt":"在证据可能灭失或者以后难以取得的情况下，经生态环境主管部门负责人批准，执法人员可以对与涉嫌违法行为有关的证据采取先行登记保存措施。 情况紧急的，执法人员需要当场采取先行登记保存措施的，可以采用即时通讯方式报请生态环境主管部门负责人同意，并在实施后二十四小时内补办批准手续。 先行登记保存有关证据，应当当场清点，开具清单，由当事人和执法人员签名或者盖章。 先行登记保存期间，当事人或者有关人员不得损毁、销毁或者转移证据。"},{"i":33,"n":"第三十三条","txt":"对于先行登记保存的证据，应当在七日内采取以下措施： （一）根据情况及时采取记录、复制、拍照、录像等证据保全措施； （二）需要鉴定的，送交鉴定； （三）根据有关法律、法规规定可以查封、扣押的，决定查封、扣押； （四）违法事实不成立，或者违法事实成立但依法不应当查封、扣押或者没收的，决定解除先行登记保存措施。 超过七日未作出处理决定的，先行登记保存措施自动解除。"},{"i":34,"n":"第三十四条","txt":"生态环境主管部门实施查封、扣押等行政强制措施，应当有法律、法规的明确规定，按照《中华人民共和国行政强制法》及相关规定执行。"},{"i":35,"n":"第三十五条","txt":"有下列情形之一的，经生态环境主管部门负责人批准，中止案件调查： （一）行政处罚决定须以相关案件的裁判结果或者其他行政决定为依据，而相关案件尚未审结或者其他行政决定尚未作出的； （二）涉及法律适用等问题，需要送请有权机关作出解释或者确认的； （三）因不可抗力致使案件暂时无法调查的； （四）因当事人下落不明致使案件暂时无法调查的； （五）其他应当中止调查的情形。 中止调查的原因消除后，应当立即恢复案件调查。"},{"i":36,"n":"第三十六条","txt":"有下列情形之一致使案件调查无法继续进行的，经生态环境主管部门负责人批准，调查终止： （一）涉嫌违法的公民死亡的； （二）涉嫌违法的法人、其他组织终止，无法人或者其他组织承受其权利义务的； （三）其他依法应当终止调查的情形。"},{"i":37,"n":"第三十七条","txt":"有下列情形之一的，终结调查： （一）违法事实清楚、法律手续完备、证据充分的； （二）违法事实不成立的； （三）其他依法应当终结调查的情形。"},{"i":38,"n":"第三十八条","txt":"调查终结的，案件调查人员应当制作调查报告，提出已查明违法行为的事实和证据、初步处理意见，移送进行案件审查。 本案的调查人员不得作为本案的审查人员。"},{"i":39,"n":"第三十九条","txt":"案件审查的主要内容包括： （一）本机关是否有管辖权； （二）违法事实是否清楚； （三）证据是否合法充分； （四）调查取证是否符合法定程序； （五）是否超过行政处罚追责期限； （六）适用法律、法规、规章是否准确，裁量基准运用是否适当。"},{"i":40,"n":"第四十条","txt":"违法事实不清、证据不充分或者调查程序违法的，审查人员应当退回调查人员补充调查取证或者重新调查取证。"},{"i":41,"n":"第四十一条","txt":"行使生态环境行政处罚裁量权应当符合立法目的，并综合考虑以下情节： （一）违法行为造成的环境污染、生态破坏以及社会影响； （二）当事人的主观过错程度； （三）违法行为的具体方式或者手段； （四）违法行为持续的时间； （五）违法行为危害的具体对象； （六）当事人是初次违法还是再次违法； （七）当事人改正违法行为的态度和所采取的改正措施及效果。 同类违法行为的情节相同或者相似、社会危害程度相当的，行政处罚种类和幅度应当相当。"},{"i":42,"n":"第四十二条","txt":"违法行为轻微并及时改正，没有造成生态环境危害后果的，不予行政处罚。初次违法且生态环境危害后果轻微并及时改正的，可以不予行政处罚。 当事人有证据足以证明没有主观过错的，不予行政处罚。法律、行政法规另有规定的，从其规定。 对当事人的违法行为依法不予行政处罚的，生态环境主管部门应当对当事人进行教育。"},{"i":43,"n":"第四十三条","txt":"当事人有下列情形之一的，应当从轻或者减轻行政处罚： （一）主动消除或者减轻生态环境违法行为危害后果的； （二）受他人胁迫或者诱骗实施生态环境违法行为的； （三）主动供述生态环境主管部门尚未掌握的生态环境违法行为的； （四）配合生态环境主管部门查处生态环境违法行为有立功表现的； （五）法律、法规、规章规定其他应当从轻或者减轻行政处罚的。"},{"i":44,"n":"第四十四条","txt":"生态环境主管部门在作出行政处罚决定之前，应当告知当事人拟作出的行政处罚内容及事实、理由、依据和当事人依法享有的陈述、申辩、要求听证等权利，当事人在收到告知书后五日内进行陈述、申辩；未依法告知当事人，或者拒绝听取当事人的陈述、申辩的，不得作出行政处罚决定，当事人明确放弃陈述或者申辩权利的除外。"},{"i":45,"n":"第四十五条","txt":"当事人进行陈述、申辩的，生态环境主管部门应当充分听取当事人意见，将当事人的陈述、申辩材料归入案卷。对当事人提出的事实、理由和证据，应当进行复核。当事人提出的事实、理由或者证据成立的，应当予以采纳；不予采纳的，应当说明理由。 不得因当事人的陈述、申辩而给予更重的处罚。"},{"i":46,"n":"第四十六条","txt":"拟作出以下行政处罚决定，当事人要求听证的，生态环境主管部门应当组织听证： （一）较大数额罚款； （二）没收较大数额违法所得、没收较大价值非法财物； （三）暂扣许可证件、降低资质等级、吊销许可证件、一定时期内不得申请行政许可； （四）限制开展生产经营活动、责令停产整治、责令停产停业、责令关闭、限制从业、禁止从业； （五）其他较重的行政处罚； （六）法律、法规、规章规定的其他情形。 当事人不承担组织听证的费用。"},{"i":47,"n":"第四十七条","txt":"听证应当依照以下程序组织： （一）当事人要求听证的，应当在生态环境主管部门告知后五日内提出； （二）生态环境主管部门应当在举行听证的七日前，通知当事人及有关人员听证的时间、地点； （三）除涉及国家秘密、商业秘密或者个人隐私依法予以保密外，听证公开举行； （四）听证由生态环境主管部门指定的非本案调查人员主持；当事人认为主持人与本案有直接利害关系的，有权申请回避； （五）当事人可以亲自参加听证，也可以委托一至二人代理； （六）当事人及其代理人无正当理由拒不出席听证或者未经许可中途退出听证的，视为放弃听证权利，生态环境主管部门终止听证； （七）举行听证时，调查人员提出当事人违法的事实、证据和行政处罚建议，当事人进行申辩和质证； （八）听证应当制作笔录。笔录应当交当事人或者其代理人核对无误后签字或者盖章。当事人或者其代理人拒绝签字或者盖章的，由听证主持人在笔录中注明。"},{"i":48,"n":"第四十八条","txt":"听证结束后，生态环境主管部门应当根据听证笔录，依照本办法第五十三条的规定，作出决定。"},{"i":49,"n":"第四十九条","txt":"有下列情形之一，生态环境主管部门负责人作出行政处罚决定之前，应当由生态环境主管部门负责重大执法决定法制审核的机构或者法制审核人员进行法制审核；未经法制审核或者审核未通过的，不得作出决定： （一）涉及重大公共利益的； （二）直接关系当事人或者第三人重大权益，经过听证程序的； （三）案件情况疑难复杂、涉及多个法律关系的； （四）法律、法规规定应当进行法制审核的其他情形。 设区的市级以上生态环境主管部门可以根据实际情况，依法对应当进行法制审核的案件范围作出具体规定。 初次从事行政处罚决定法制审核的人员，应当通过国家统一法律职业资格考试取得法律职业资格。"},{"i":50,"n":"第五十条","txt":"法制审核的内容包括： （一）行政执法主体是否合法，是否超越执法机关法定权限； （二）行政执法人员是否具备执法资格； （三）行政执法程序是否合法； （四）案件事实是否清楚，证据是否合法充分； （五）适用法律、法规、规章是否准确，裁量基准运用是否适当； （六）行政执法文书是否完备、规范； （七）违法行为是否涉嫌犯罪、需要移送司法机关。"},{"i":51,"n":"第五十一条","txt":"法制审核以书面审核为主。对案情复杂、法律争议较大的案件，生态环境主管部门可以组织召开座谈会、专家论证会开展审核工作。 生态环境主管部门进行法制审核时，可以请相关领域专家、法律顾问提出书面意见。 对拟作出的处罚决定进行法制审核后，应当区别不同情况以书面形式提出如下意见： （一）主要事实清楚，证据充分，程序合法，内容适当，未发现明显法律风险的，提出同意的意见； （二）主要事实不清，证据不充分，程序不当或者适用依据不充分，存在明显法律风险，但是可以改进或者完善的，指出存在的问题，并提出改进或者完善的建议； （三）存在明显法律风险，且难以改进或者完善的，指出存在的问题，提出不同意的审核意见。"},{"i":52,"n":"第五十二条","txt":"对情节复杂或者重大违法行为给予行政处罚的，作出处罚决定的生态环境主管部门负责人应当集体讨论决定。 有下列情形之一的，属于情节复杂或者重大违法行为给予行政处罚的案件： （一）情况疑难复杂、涉及多个法律关系的； （二）拟罚款、没收违法所得、没收非法财物数额五十万元以上的； （三）拟吊销许可证件、一定时期内不得申请行政许可的； （四）拟责令停产整治、责令停产停业、责令关闭、限制从业、禁止从业的； （五）生态环境主管部门负责人认为应当提交集体讨论的其他案件。 集体讨论情况应当予以记录。 地方性法规、地方政府规章另有规定的，从其规定。"},{"i":53,"n":"第五十三条","txt":"生态环境主管部门负责人经过审查，根据不同情况，分别作出如下决定： （一）确有应受行政处罚的违法行为的，根据情节轻重及具体情况，作出行政处罚决定； （二）违法行为轻微，依法可以不予行政处罚的，不予行政处罚； （三）违法事实不能成立的，不予行政处罚； （四）违法行为涉嫌犯罪的，移送司法机关。"},{"i":54,"n":"第五十四条","txt":"生态环境主管部门向司法机关移送涉嫌生态环境犯罪案件之前已经依法作出的警告、责令停产停业、暂扣或者吊销许可证件等行政处罚决定，不停止执行。 涉嫌犯罪案件的移送办理期间，不计入行政处罚期限。"},{"i":55,"n":"第五十五条","txt":"决定给予行政处罚的，应当制作行政处罚决定书。 对同一当事人的两个或者两个以上环境违法行为，可以分别制作行政处罚决定书，也可以列入同一行政处罚决定书。 符合本办法第五十三条第二项规定的情况，决定不予行政处罚的，应当制作不予行政处罚决定书。"},{"i":56,"n":"第五十六条","txt":"行政处罚决定书应当载明以下内容： （一）当事人的基本情况，包括当事人姓名或者名称，居民身份证号码或者统一社会信用代码、住址或者住所地、法定代表人（负责人）姓名等； （二）违反法律、法规或者规章的事实和证据； （三）当事人陈述、申辩的采纳情况及理由；符合听证条件的，还应当载明听证的情况； （四）行政处罚的种类、依据，以及行政处罚裁量基准运用的理由和依据； （五）行政处罚的履行方式和期限； （六）不服行政处罚决定，申请行政复议、提起行政诉讼的途径和期限； （七）作出行政处罚决定的生态环境主管部门名称和作出决定的日期，并加盖印章。"},{"i":57,"n":"第五十七条","txt":"生态环境主管部门应当自立案之日起九十日内作出处理决定。因案情复杂或者其他原因，不能在规定期限内作出处理决定的，经生态环境主管部门负责人批准，可以延长三十日。案情特别复杂或者有其他特殊情况，经延期仍不能作出处理决定的，应当由生态环境主管部门负责人集体讨论决定是否继续延期，决定继续延期的，继续延长期限不得超过三十日。 案件办理过程中，中止、听证、公告、监测（检测）、评估、鉴定、认定、送达等时间不计入前款所指的案件办理期限。"},{"i":58,"n":"第五十八条","txt":"行政处罚决定书应当在宣告后当场交付当事人；当事人不在场的，应当在七日内将行政处罚决定书送达当事人。 生态环境主管部门可以根据需要将行政处罚决定书抄送与案件有关的单位和个人。"},{"i":59,"n":"第五十九条","txt":"生态环境主管部门送达执法文书，可以采取直接送达、留置送达、委托送达、邮寄送达、电子送达、转交送达、公告送达等法律规定的方式。 送达行政处罚文书应当使用送达回证并存档。"},{"i":60,"n":"第六十条","txt":"当事人同意并签订确认书的，生态环境主管部门可以采用传真、电子邮件、移动通信等能够确认其收悉的电子方式送达执法文书，并通过拍照、截屏、录音、录像等方式予以记录。传真、电子邮件、移动通信等到达当事人特定系统的日期为送达日期。"},{"i":61,"n":"第六十一条","txt":"生态环境主管部门应当依法公开其作出的生态环境行政处罚决定。"},{"i":62,"n":"第六十二条","txt":"生态环境主管部门依法公开生态环境行政处罚决定的下列信息： （一）行政处罚决定书文号； （二）被处罚的公民姓名，被处罚的法人或者其他组织名称和统一社会信用代码、法定代表人（负责人）姓名； （三）主要违法事实； （四）行政处罚结果和依据； （五）作出行政处罚决定的生态环境主管部门名称和作出决定的日期。"},{"i":63,"n":"第六十三条","txt":"涉及国家秘密或者法律、行政法规禁止公开的信息的，以及公开后可能危及国家安全、公共安全、经济安全、社会稳定的行政处罚决定信息，不予公开。"},{"i":64,"n":"第六十四条","txt":"公开行政处罚决定时，应当隐去以下信息： （一）公民的肖像、居民身份证号码、家庭住址、通信方式、出生日期、银行账号、健康状况、财产状况等个人隐私信息； （二）本办法第六十二条第（二）项规定以外的公民姓名，法人或者其他组织的名称和统一社会信用代码、法定代表人（负责人）姓名； （三）法人或者其他组织的银行账号； （四）未成年人的姓名及其他可能识别出其身份的信息； （五）当事人的生产配方、工艺流程、购销价格及客户名称等涉及商业秘密的信息； （六）法律、法规规定的其他应当隐去的信息。"},{"i":65,"n":"第六十五条","txt":"生态环境行政处罚决定应当自作出之日起七日内公开。法律、行政法规另有规定的，从其规定。"},{"i":66,"n":"第六十六条","txt":"公开的行政处罚决定被依法变更、撤销、确认违法或者确认无效的，生态环境主管部门应当在三日内撤回行政处罚决定信息并公开说明理由。"},{"i":67,"n":"第六十七条","txt":"违法事实确凿并有法定依据，对公民处以二百元以下、对法人或者其他组织处以三千元以下罚款或者警告的行政处罚的，可以适用简易程序，当场作出行政处罚决定。法律另有规定的，从其规定。"},{"i":68,"n":"第六十八条","txt":"当场作出行政处罚决定时，应当遵守下列简易程序： （一）执法人员应当向当事人出示有效执法证件； （二）现场查清当事人的违法事实，并依法取证； （三）向当事人说明违法的事实、拟给予行政处罚的种类和依据、罚款数额、时间、地点，告知当事人享有的陈述、申辩权利； （四）听取当事人的陈述和申辩。当事人提出的事实、理由或者证据成立的，应当采纳； （五）填写预定格式、编有号码、盖有生态环境主管部门印章的行政处罚决定书，由执法人员签名或者盖章，并将行政处罚决定书当场交付当事人；当事人拒绝签收的，应当在行政处罚决定书上注明； （六）告知当事人如对当场作出的行政处罚决定不服，可以依法申请行政复议或者提起行政诉讼，并告知申请行政复议、提起行政诉讼的途径和期限。 以上过程应当制作笔录。 执法人员当场作出的行政处罚决定，应当在决定之日起三日内报所属生态环境主管部门备案。"},{"i":69,"n":"第六十九条","txt":"当事人应当在行政处罚决定书载明的期限内，履行处罚决定。 申请行政复议或者提起行政诉讼的，行政处罚决定不停止执行，法律另有规定的除外。"},{"i":70,"n":"第七十条","txt":"当事人到期不缴纳罚款的，作出行政处罚决定的生态环境主管部门可以每日按罚款数额的百分之三加处罚款，加处罚款的数额不得超出罚款的数额。"},{"i":71,"n":"第七十一条","txt":"当事人在法定期限内不申请行政复议或者提起行政诉讼，又不履行行政处罚决定的，作出处罚决定的生态环境主管部门可以自期限届满之日起三个月内依法申请人民法院强制执行。"},{"i":72,"n":"第七十二条","txt":"作出加处罚款的强制执行决定前或者申请人民法院强制执行前，生态环境主管部门应当依法催告当事人履行义务。"},{"i":73,"n":"第七十三条","txt":"当事人实施违法行为，受到处以罚款、没收违法所得或者没收非法财物等处罚后，发生企业分立、合并或者其他资产重组等情形，由承受当事人权利义务的法人、其他组织作为被执行人。"},{"i":74,"n":"第七十四条","txt":"确有经济困难，需要延期或者分期缴纳罚款的，当事人应当在行政处罚决定书确定的缴纳期限届满前，向作出行政处罚决定的生态环境主管部门提出延期或者分期缴纳的书面申请。 批准当事人延期或者分期缴纳罚款的，应当制作同意延期（分期）缴纳罚款通知书，并送达当事人和收缴罚款的机构。 生态环境主管部门批准延期、分期缴纳罚款的，申请人民法院强制执行的期限，自暂缓或者分期缴纳罚款期限结束之日起计算。"},{"i":75,"n":"第七十五条","txt":"依法没收的非法财物，应当按照国家规定处理。 销毁物品，应当按照国家有关规定处理；没有规定的，经生态环境主管部门负责人批准，由两名以上执法人员监督销毁，并制作销毁记录。 处理物品应当制作清单。"},{"i":76,"n":"第七十六条","txt":"罚款、没收的违法所得或者没收非法财物拍卖的款项，应当全部上缴国库，任何单位或者个人不得以任何形式截留、私分或者变相私分。 罚款、没收的违法所得或者没收非法财物拍卖的款项，不得同作出行政处罚决定的生态环境主管部门及其工作人员的考核、考评直接或者变相挂钩。"},{"i":77,"n":"第七十七条","txt":"有下列情形之一的，执法人员应当制作结案审批表，经生态环境主管部门负责人批准后予以结案： （一）责令改正和行政处罚决定由当事人履行完毕的； （二）生态环境主管部门依法申请人民法院强制执行行政处罚决定，人民法院依法受理的； （三）不予行政处罚等无须执行的； （四）按照本办法第三十六条规定终止案件调查的； （五）按照本办法第十七条规定完成案件移送，且依法无须由生态环境主管部门再作出行政处罚决定的； （六）行政处罚决定被依法撤销的； （七）生态环境主管部门认为可以结案的其他情形。"},{"i":78,"n":"第七十八条","txt":"结案的行政处罚案件，应当按照下列要求将案件材料立卷归档： （一）一案一卷，案卷可以分正卷、副卷； （二）各类文书齐全，手续完备； （三）书写文书用签字笔、钢笔或者打印； （四）案卷装订应当规范有序，符合文档要求。"},{"i":79,"n":"第七十九条","txt":"正卷按下列顺序装订： （一）行政处罚决定书及送达回证； （二）立案审批材料； （三）调查取证及证据材料； （四）行政处罚事先告知书、听证告知书、听证通知书等法律文书及送达回证； （五）听证笔录； （六）财物处理材料； （七）执行材料； （八）结案材料； （九）其他有关材料。 副卷按下列顺序装订： （一）投诉、申诉、举报等案源材料； （二）涉及当事人有关商业秘密的材料； （三）听证报告； （四）审查意见； （五）法制审核材料、集体讨论记录； （六）其他有关材料。"},{"i":80,"n":"第八十条","txt":"案卷归档后，任何单位、个人不得修改、增加、抽取案卷材料。案卷保管及查阅，按档案管理有关规定执行。"},{"i":81,"n":"第八十一条","txt":"生态环境主管部门应当建立行政处罚案件统计制度，并按照生态环境部有关环境统计的规定向上级生态环境主管部门报送本行政区域的行政处罚情况。"},{"i":82,"n":"第八十二条","txt":"上级生态环境主管部门负责对下级生态环境主管部门的行政处罚工作情况进行监督检查。"},{"i":83,"n":"第八十三条","txt":"生态环境主管部门应当建立行政处罚备案制度。 下级生态环境主管部门对上级生态环境主管部门督办的处罚案件，应当在结案后二十日内向上一级生态环境主管部门备案。"},{"i":84,"n":"第八十四条","txt":"生态环境主管部门实施行政处罚应当接受社会监督。公民、法人或者其他组织对生态环境主管部门实施行政处罚的行为，有权申诉或者检举；生态环境主管部门应当认真审查，发现有错误的，应当主动改正。"},{"i":85,"n":"第八十五条","txt":"生态环境主管部门发现行政处罚决定有文字表述错误、笔误或者计算错误，以及行政处罚决定书部分内容缺失等情形，但未损害公民、法人或者其他组织的合法权益的，应当予以补正或者更正。 补正或者更正应当以书面决定的方式及时作出。"},{"i":86,"n":"第八十六条","txt":"生态环境主管部门通过接受申诉和检举，或者通过备案审查等途径，发现下级生态环境主管部门的行政处罚决定违法或者显失公正的，应当督促其纠正。 依法应当给予行政处罚，而有关生态环境主管部门不给予行政处罚的，有处罚权的上级生态环境主管部门可以直接作出行政处罚决定。"},{"i":87,"n":"第八十七条","txt":"生态环境主管部门可以通过案件评查或者其他方式评议、考核行政处罚工作，加强对行政处罚的监督检查，规范和保障行政处罚的实施。对在行政处罚工作中做出显著成绩的单位和个人，可以依照国家或者地方的有关规定给予表彰和奖励。"},{"i":88,"n":"第八十八条","txt":"当事人有违法所得，除依法应当退赔的外，应当予以没收。违法所得是指实施违法行为所取得的款项。 法律、行政法规对违法所得的计算另有规定的，从其规定。"},{"i":89,"n":"第八十九条","txt":"本办法第四十六条所称“较大数额”“较大价值”，对公民是指人民币（或者等值物品价值）五千元以上、对法人或者其他组织是指人民币（或者等值物品价值）二十万元以上。 地方性法规、地方政府规章对“较大数额”“较大价值”另有规定的，从其规定。"},{"i":90,"n":"第九十条","txt":"本办法中“三日”“五日”“七日”的规定是指工作日，不含法定节假日。 期间开始之日，不计算在内。期间届满的最后一日是节假日的，以节假日后的第一日为期间届满的日期。期间不包括在途时间，行政处罚文书在期满前交邮的，视为在有效期内。"},{"i":91,"n":"第九十一条","txt":"本办法未作规定的其他事项，适用《中华人民共和国行政处罚法》《中华人民共和国行政强制法》等有关法律、法规和规章的规定。"},{"i":92,"n":"第九十二条","txt":"本办法自2023年7月1日起施行。原环境保护部发布的《环境行政处罚办法》（环境保护部令第8号）同时废止。"}],"shengtaihuanjingbujianshexiangmuhuanjingyingxiangbaa2635":[{"i":1,"n":"第一条","txt":"为了规范生态环境部建设项目环境影响报告书、环境影响报告表（以下简称环境影响报告书（表））审批程序，提高审批效率和服务水平，落实深化“放管服”改革、优化营商环境要求，保障公民、法人和其他组织的合法权益，根据《中华人民共和国行政许可法》《中华人民共和国环境影响评价法》《建设项目环境保护管理条例》，以及海洋环境保护、放射性污染防治、大气污染防治、水污染防治等生态环境法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于生态环境部负责审批的建设项目环境影响报告书（表）的审批。"},{"i":3,"n":"第三条","txt":"生态环境部审批建设项目环境影响报告书（表），坚持依法依规、科学决策、公开公正、便民高效的原则。"},{"i":4,"n":"第四条","txt":"依法应当编制环境影响报告书（表）的建设项目，建设单位应当在开工建设前将环境影响报告书（表）报生态环境部审批。 建设项目的环境影响报告书（表）经批准后，建设项目的性质、规模、地点、采用的生产工艺或者防治污染、防止生态破坏的措施发生重大变动的，建设单位应当在发生重大变动的建设内容开工建设前重新将环境影响报告书（表）报生态环境部审批。"},{"i":5,"n":"第五条","txt":"对国家确定的重大基础设施、民生工程和国防科研生产项目，生态环境部可以根据建设单位、环境影响报告书（表）编制单位或者有关部门提供的信息，提前指导，主动服务，加快审批。"},{"i":6,"n":"第六条","txt":"建设单位向生态环境部申请报批环境影响报告书（表）的，除国家规定需要保密的情形外，应当在全国一体化在线政务服务平台生态环境部政务服务大厅（网址：http://zwfw.mee.gov.cn，以下简称政务服务大厅）提交下列材料，并对材料的真实性负责： （一）建设项目环境影响报告书（表）报批申请书； （二）建设项目环境影响报告书（表）。环境影响报告书（表）涉及国家秘密、商业秘密和个人隐私的，建设单位应当自行作出删除、遮盖等区分处理； （三）编制环境影响报告书的建设项目的公众参与说明。 除前款规定材料外，建设单位还应当通过邮寄或者现场递交等方式，向生态环境部提交下列材料纸质版，以及光盘等移动电子存储设备一份： （一）建设项目环境影响报告书（表）全本，一式三份； （二）编制环境影响报告书的建设项目的公众参与说明，一式三份； （三）通过政务服务大厅线上提交的建设项目环境影响报告书（表）对全本中不宜"},{"i":7,"n":"第七条","txt":"生态环境部对建设单位提交的申请材料，根据下列情况分别作出处理： （一）依法不需要编制环境影响报告书（表）的，应当即时告知建设单位不予受理； （二）对不属于生态环境部审批的环境影响报告书（表），不予受理，并告知建设单位向有关机关申请； （三）环境影响报告书（表）由列入《建设项目环境影响报告书（表）编制监督管理办法》规定的限期整改名单或者“黑名单”的编制单位、编制人员编制的，应当告知建设单位不予受理； （四）申请材料不齐全或者不符合法定形式的，应当当场或者在五个工作日内一次性告知建设单位需要补正的内容，逾期不告知的，自收到申请材料之日起即视为受理。可以当场补正的，应当允许建设单位当场补正； （五）申请材料齐全、符合法定形式，或者建设单位按要求提交全部补正申请材料的，予以受理，并出具电子受理通知单；国家规定需要保密的或者其他不适宜网上受理的，出具纸质受理通知单。"},{"i":8,"n":"第八条","txt":"生态环境部受理报批的建设项目环境影响报告书（表）后，应当按照《环境影响评价公众参与办法》的规定，公开环境影响报告书（表）、公众参与说明、公众提出意见的方式和途径。环境影响报告书的公开期限不得少于十个工作日，环境影响报告表的公开期限不得少于五个工作日。"},{"i":9,"n":"第九条","txt":"生态环境部负责审批的建设项目环境影响报告书（表）需要进行技术评估的，生态环境部应当在受理申请后一个工作日内出具委托函，委托技术评估机构开展技术评估。对符合本规定第五条规定情形的，技术评估机构应当根据生态环境部的要求做好提前指导。"},{"i":10,"n":"第十条","txt":"受委托的技术评估机构应当在委托函确定的期限内提交技术评估报告，并对技术评估结论负责。 技术评估报告应当包括下列内容： （一）明确的技术评估结论； （二）环境影响报告书（表）存在的质量问题及处理建议； （三）审批时需重点关注的问题。 环境影响报告书（表）的技术评估期限不超过三十个工作日；情况特别复杂的，生态环境部可以根据实际情况适当延长技术评估期限。"},{"i":11,"n":"第十一条","txt":"生态环境部主要从下列方面对建设项目环境影响报告书（表）进行审查： （一）建设项目类型及其选址、布局、规模等是否符合生态环境保护法律法规和相关法定规划、区划，是否符合规划环境影响报告书及审查意见，是否符合区域生态保护红线、环境质量底线、资源利用上线和生态环境准入清单管控要求； （二）建设项目所在区域生态环境质量是否满足相应环境功能区划要求、区域环境质量改善目标管理要求、区域重点污染物排放总量控制要求； （三）拟采取的污染防治措施能否确保污染物排放达到国家和地方排放标准；拟采取的生态保护措施能否有效预防和控制生态破坏；可能产生放射性污染的，拟采取的防治措施能否有效预防和控制放射性污染； （四）改建、扩建和技术改造项目，是否针对项目原有环境污染和生态破坏提出有效防治措施； （五）环境影响报告书（表）编制内容、编制质量是否符合有关要求。 对区域生态环境质量现状符合环境功能区划要求的，生态环境部"},{"i":12,"n":"第十二条","txt":"生态环境部对环境影响报告书（表）作出审批决定前，应当按照《环境影响评价公众参与办法》规定，向社会公开建设项目和环境影响报告书（表）基本情况等信息，并同步告知建设单位和利害关系人享有要求听证的权利。 生态环境部召开听证会的，依照环境保护行政许可听证有关规定执行。"},{"i":13,"n":"第十三条","txt":"建设项目环境影响报告书（表）审查过程中，建设单位申请撤回环境影响报告书（表）审批申请的，生态环境部可以终止该建设项目环境影响评价审批程序，并退回建设单位提交的所有申请材料。"},{"i":14,"n":"第十四条","txt":"生态环境部审批建设项目环境影响报告书（表），技术评估机构对建设项目环境影响报告书（表）进行技术评估，不得向建设单位、环境影响报告书（表）编制单位收取或者转嫁任何费用。"},{"i":15,"n":"第十五条","txt":"建设项目环境影响报告书（表）审查过程中，发现建设单位存在擅自开工建设、环境影响报告书（表）存在质量问题等违反环境影响评价有关法律法规行为的，应当依法依规予以处理；建设单位有关责任人员属于公职人员的，应当按照国家有关规定将案件移送有管辖权的监察机关，依纪依规依法给予处分。"},{"i":16,"n":"第十六条","txt":"对经审查通过的建设项目环境影响报告书（表），生态环境部依法作出予以批准的决定，并书面通知建设单位。 对属于《建设项目环境保护管理条例》规定不予批准情形的建设项目环境影响报告书（表），生态环境部依法作出不予批准的决定，通知建设单位，并说明理由。"},{"i":17,"n":"第十七条","txt":"生态环境部应当自作出环境影响报告书（表）审批决定之日起七个工作日内，在生态环境部网站向社会公告审批决定全文，并依法告知建设单位提起行政复议和行政诉讼的权利和期限。国家规定需要保密的除外。"},{"i":18,"n":"第十八条","txt":"生态环境部审批环境影响报告书的期限，依法不超过六十日；审批环境影响报告表的期限，依法不超过三十日。依法需要进行听证、专家评审、技术评估的，所需时间不计算在审批期限内。"},{"i":19,"n":"第十九条","txt":"依法应当由生态环境部负责审批环境影响报告书（表）的建设项目，生态环境部可以委托建设项目所在的流域（海域）生态环境监管机构或者省级生态环境主管部门审批该建设项目的环境影响报告书（表），并将受委托的行政机关和受委托实施审批的内容向社会公告。 受委托行政机关在委托范围内以生态环境部的名义实施审批，不得再次委托其他机构审批建设项目环境影响报告书（表）。生态环境部对所委托事项的批准决定负责。"},{"i":20,"n":"第二十条","txt":"实行告知承诺审批制审批建设项目环境影响报告书（表）的有关办法，由生态环境部另行制定。"},{"i":21,"n":"第二十一条","txt":"本规定自2021年1月1日起实施。《国家环境保护总局建设项目环境影响评价文件审批程序规定》（国家环境保护总局令第29号）同时废止。"}],"shengtaihuanjingbuxingzhengfuyibanfa":[{"i":1,"n":"第一条","txt":"为防止和纠正违法的或者不当的行政行为，保护公民、法人和其他组织的合法权益，监督和保障生态环境部依法行使职权，发挥行政复议化解行政争议的主渠道作用，依据《中华人民共和国行政复议法》等法律、行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"生态环境部受理行政复议申请、办理行政复议案件，适用本办法。"},{"i":3,"n":"第三条","txt":"行政复议工作坚持中国共产党的领导。 生态环境部履行行政复议职责，应当遵循合法、公正、公开、高效、便民、为民的原则，坚持有错必纠，保障法律、法规的正确实施。"},{"i":4,"n":"第四条","txt":"生态环境部办理行政复议案件，可以进行调解。 调解应当遵循合法、自愿的原则，不得损害国家利益、社会公共利益和他人合法权益，不得违反法律、法规的强制性规定。"},{"i":5,"n":"第五条","txt":"生态环境部法制工作部门是生态环境部行政复议机构，具体办理行政复议案件。生态环境部行政复议机构同时组织办理生态环境部的行政应诉事项。"},{"i":6,"n":"第六条","txt":"生态环境部行政复议机构中初次从事行政复议工作的人员，应当通过国家统一法律职业资格考试取得法律职业资格，并参加统一职前培训。"},{"i":7,"n":"第七条","txt":"对在生态环境部行政复议工作中做出显著成绩的单位和个人，按照国家有关规定给予表彰和奖励。"},{"i":8,"n":"第八条","txt":"生态环境部应当确保行政复议机构的人员配备与所承担的工作任务相适应，提高行政复议人员专业素质，根据工作需要保障办案场所、装备等设施。行政复议工作经费列入本级预算。"},{"i":9,"n":"第九条","txt":"生态环境部管辖下列行政复议案件： （一）对生态环境部作出的行政行为不服的； （二）对生态环境部依法设立的派出机构依照法律、行政法规、部门规章规定，以派出机构的名义作出的行政行为不服的； （三）对生态环境部管理的法律、行政法规、部门规章授权的组织作出的行政行为不服的。 前款规定的生态环境部、生态环境部依法设立的派出机构和生态环境部管理的法律、行政法规、部门规章授权的组织，以下简称为生态环境部及其派出机构、管理的组织。 公民、法人或者其他组织对生态环境部和其他国务院部门以共同名义作出的同一行政行为不服的，可以向生态环境部或者其他共同作出行政行为的国务院部门提出行政复议申请，由生态环境部和其他作出行政行为的国务院部门共同作出行政复议决定。"},{"i":10,"n":"第十条","txt":"公民、法人或者其他组织可以依照行政复议法第十一条规定的行政复议范围，向生态环境部申请行政复议。 下列事项不属于行政复议范围： （一）国防、外交等国家行为； （二）行政法规、规章或者行政机关制定、发布的具有普遍约束力的决定、命令等规范性文件； （三）生态环境部及其派出机构、管理的组织对本机关工作人员的奖惩、任免等决定； （四）生态环境部及其派出机构、管理的组织对民事纠纷作出的调解。 信访事项按照《信访工作条例》有关规定办理。"},{"i":11,"n":"第十一条","txt":"公民、法人或者其他组织认为被复议的行政行为所依据的规范性文件不合法，在对行政行为申请行政复议时，可以依据行政复议法第十三条的规定，一并向生态环境部提出对该规范性文件的附带审查申请。"},{"i":12,"n":"第十二条","txt":"依照行政复议法规定申请行政复议的公民、法人或者其他组织是申请人。 同一行政复议案件申请人人数众多的，可以由申请人推选代表人参加行政复议。 代表人参加行政复议的行为对其所代表的申请人发生效力，但是代表人变更行政复议请求、撤回行政复议申请、承认第三人请求的，应当经被代表的申请人同意。"},{"i":13,"n":"第十三条","txt":"申请人以外的同被申请行政复议的行政行为或者行政复议案件处理结果有利害关系的公民、法人或者其他组织，可以作为第三人申请参加行政复议，或者由生态环境部行政复议机构通知其作为第三人参加行政复议。 第三人不参加行政复议，不影响行政复议案件的审理。"},{"i":14,"n":"第十四条","txt":"申请人、第三人可以委托一至二名律师、基层法律服务工作者或者其他代理人代为参加行政复议。 申请人、第三人委托代理人的，应当向生态环境部行政复议机构提交授权委托书、委托人及被委托人的身份证明文件。授权委托书应当载明委托事项、权限和期限。申请人、第三人变更或者解除代理人权限的，应当书面告知生态环境部行政复议机构。"},{"i":15,"n":"第十五条","txt":"公民、法人或者其他组织认为生态环境部及其派出机构、管理的组织的行政行为侵犯其合法权益的，可以自知道或者应当知道该行政行为之日起六十日内提出行政复议申请；但是法律规定的申请期限超过六十日的除外。 因不可抗力或者其他正当理由耽误法定申请期限的，申请期限自障碍消除之日起继续计算。 生态环境部及其派出机构、管理的组织作出行政行为时，未告知公民、法人或者其他组织申请行政复议的权利、行政复议机关和申请期限的，申请期限自公民、法人或者其他组织知道或者应当知道申请行政复议的权利、行政复议机关和申请期限之日起计算，但是自知道或者应当知道行政行为内容之日起最长不得超过一年。 因不动产提出的行政复议申请自行政行为作出之日起超过二十年，其他行政复议申请自行政行为作出之日起超过五年的，生态环境部不予受理。"},{"i":16,"n":"第十六条","txt":"申请人申请行政复议，可以书面申请；书面申请有困难的，也可以口头申请。 书面申请的，可以通过邮寄或者生态环境部指定的互联网渠道等方式提交行政复议申请书，也可以当面提交行政复议申请书。生态环境部及其派出机构、管理的组织通过互联网渠道送达行政行为决定书的，应当同时提供提交行政复议申请书的互联网渠道。 口头申请的，生态环境部应当当场记录申请人的基本情况、行政复议请求、申请行政复议的主要事实、理由和时间。 申请人对两个以上行政行为不服的，应当分别申请行政复议。"},{"i":17,"n":"第十七条","txt":"有下列情形之一的，申请人应当先向生态环境部申请行政复议，对行政复议决定不服的，可以再依法向人民法院提起行政诉讼： （一）对生态环境部及其派出机构、管理的组织当场作出的行政处罚决定不服的； （二）认为生态环境部及其派出机构、管理的组织存在行政复议法第十一条规定的未履行法定职责情形的； （三）申请政府信息公开，生态环境部及其派出机构、管理的组织不予公开的； （四）法律、行政法规规定应当先申请行政复议的其他情形。 对前款规定的情形，生态环境部及其派出机构、管理的组织在作出行政行为时应当告知公民、法人或者其他组织先向生态环境部申请行政复议。"},{"i":18,"n":"第十八条","txt":"生态环境部收到行政复议申请后，应当在五日内进行审查。对符合下列规定的，生态环境部应当予以受理： （一）有明确的申请人和符合行政复议法规定的被申请人； （二）申请人与被申请行政复议的行政行为有利害关系； （三）有具体的行政复议请求和理由； （四）在法定申请期限内提出； （五）属于行政复议法规定的行政复议范围； （六）属于生态环境部的管辖范围； （七）行政复议机关未受理过该申请人就同一行政行为提出的行政复议申请，并且人民法院未受理过该申请人就同一行政行为提起的行政诉讼。 对不符合前款规定的行政复议申请，生态环境部应当在审查期限内决定不予受理并说明理由；不属于生态环境部管辖的，还应当在不予受理决定中告知申请人有管辖权的行政复议机关。 行政复议申请的审查期限届满，生态环境部未作出不予受理决定的，审查期限届满之日起视为受理。"},{"i":19,"n":"第十九条","txt":"行政复议申请材料不齐全或者表述不清楚，无法判断行政复议申请是否符合本办法第十八条第一款规定的，生态环境部应当自收到申请之日起五日内书面通知申请人补正。补正通知应当一次性载明需要补正的事项。 申请人应当自收到补正通知之日起十日内提交补正材料。有正当理由不能按期补正的，生态环境部可以延长合理的补正期限。无正当理由逾期不补正的，视为申请人放弃行政复议申请，并记录在案。 生态环境部收到补正材料后，依照本办法第十八条的规定处理。"},{"i":20,"n":"第二十条","txt":"生态环境部受理行政复议申请后，发现该行政复议申请不符合本办法第十八条第一款规定的，应当决定驳回申请并说明理由。"},{"i":21,"n":"第二十一条","txt":"生态环境部行政复议机构应当指定行政复议人员负责办理行政复议案件。 行政复议人员对办理行政复议案件过程中知悉的国家秘密、商业秘密和个人隐私，应当予以保密。"},{"i":22,"n":"第二十二条","txt":"被申请人对其作出的行政行为的合法性、适当性负有举证责任。 有下列情形之一的，申请人应当提供证据： （一）认为被申请人不履行法定职责的，提供曾经要求被申请人履行法定职责的证据，但是被申请人应当依职权主动履行法定职责或者申请人因正当理由不能提供的除外； （二）提出行政赔偿请求的，提供受行政行为侵害而造成损害的证据，但是因被申请人原因导致申请人无法举证的，由被申请人承担举证责任； （三）法律、法规规定需要申请人提供证据的其他情形。"},{"i":23,"n":"第二十三条","txt":"生态环境部有权向有关单位和个人调查取证，查阅、复制、调取有关文件和资料，向有关人员进行询问。 调查取证时，行政复议人员不得少于两人，并应当出示行政复议工作证件。 被调查取证的单位和个人应当积极配合行政复议人员的工作，不得拒绝或者阻挠。"},{"i":24,"n":"第二十四条","txt":"行政复议期间涉及专门事项需要鉴定的，当事人可以自行委托鉴定机构进行鉴定，也可以申请生态环境部行政复议机构委托鉴定机构进行鉴定。 案件复杂、涉及专业问题以及其他需要现场勘验情形的，可以委托专业机构进行现场勘验。 鉴定、现场勘验所用时间不计入行政复议审理期限。鉴定、现场勘验的启动和终止，应当告知申请人。"},{"i":25,"n":"第二十五条","txt":"行政复议期间有行政复议法第三十九条规定的中止情形的，行政复议中止。 行政复议中止的原因消除后，应当及时恢复行政复议案件的审理。 生态环境部中止、恢复行政复议案件的审理，应当书面告知当事人。"},{"i":26,"n":"第二十六条","txt":"行政复议期间有行政复议法第四十一条规定的终止情形的，生态环境部决定终止行政复议。"},{"i":27,"n":"第二十七条","txt":"行政复议期间行政行为不停止执行；但是有行政复议法第四十二条规定情形的，应当停止执行。"},{"i":28,"n":"第二十八条","txt":"适用普通程序审理的行政复议案件，生态环境部行政复议机构应当自行政复议申请受理之日起七日内，将行政复议申请书副本或者行政复议申请笔录复印件发送被申请人。被申请人应当自收到行政复议申请书副本或者行政复议申请笔录复印件之日起十日内，提出书面答复，并提交作出行政行为的证据、依据和其他有关材料。"},{"i":29,"n":"第二十九条","txt":"适用普通程序审理的行政复议案件，生态环境部行政复议机构应当当面或者通过互联网、电话等方式听取当事人的意见，并将听取的意见记录在案。因当事人原因不能听取意见的，可以书面审理。"},{"i":30,"n":"第三十条","txt":"审理重大、疑难、复杂的行政复议案件，生态环境部行政复议机构应当组织听证。 生态环境部行政复议机构认为有必要听证，或者申请人请求听证的，生态环境部行政复议机构可以组织听证。 听证由一名行政复议人员任主持人，两名以上行政复议人员任听证员，一名记录员制作听证笔录。"},{"i":31,"n":"第三十一条","txt":"生态环境部审理下列复议案件，认为事实清楚、权利义务关系明确、争议不大的，可以适用简易程序： （一）被申请行政复议的行政行为是当场作出； （二）被申请行政复议的行政行为是警告或者通报批评； （三）案件涉及款额三千元以下； （四）属于政府信息公开案件。 除前款规定以外的行政复议案件，当事人各方同意适用简易程序的，可以适用简易程序。"},{"i":32,"n":"第三十二条","txt":"适用简易程序审理的行政复议案件，生态环境部行政复议机构应当自受理行政复议申请之日起三日内，将行政复议申请书副本或者行政复议申请笔录复印件发送被申请人。被申请人应当自收到行政复议申请书副本或者行政复议申请笔录复印件之日起五日内，提出书面答复，并提交作出行政行为的证据、依据和其他有关材料。 适用简易程序审理的行政复议案件，可以书面审理。 适用简易程序审理的行政复议案件，生态环境部行政复议机构认为不宜适用简易程序的，经生态环境部行政复议机构的负责人批准，可以转为普通程序审理。"},{"i":33,"n":"第三十三条","txt":"申请人依照行政复议法第十三条的规定提出对有关规范性文件的附带审查申请的，或者生态环境部对被申请人作出的行政行为进行审查时，认为其依据不合法的，生态环境部依据行政复议法第五十六条、第五十七条、第五十八条、第五十九条、第六十条的规定进行处理。"},{"i":34,"n":"第三十四条","txt":"行政复议期间，申请人、第三人及其委托代理人可以按照规定查阅、复制被申请人提出的书面答复、作出行政行为的证据、依据和其他有关材料，除涉及国家秘密、商业秘密、个人隐私或者可能危及国家安全、公共安全、社会稳定的情形外，生态环境部行政复议机构应当同意。"},{"i":35,"n":"第三十五条","txt":"当事人在行政复议决定作出前可以自愿达成和解，和解内容不得损害国家利益、社会公共利益和他人合法权益，不得违反法律、法规的强制性规定。 当事人达成和解后，由申请人向生态环境部行政复议机构撤回行政复议申请。生态环境部行政复议机构准予撤回行政复议申请、生态环境部决定终止行政复议的，申请人不得再以同一事实和理由提出行政复议申请。但是，申请人能够证明撤回行政复议申请违背其真实意愿的除外。"},{"i":36,"n":"第三十六条","txt":"当事人经调解达成协议的，生态环境部应当制作行政复议调解书，经各方当事人签字或者签章，并加盖生态环境部印章，即具有法律效力。 调解未达成协议或者调解书生效前一方反悔的，生态环境部应当依法审查或者及时作出行政复议决定。"},{"i":37,"n":"第三十七条","txt":"生态环境部依照行政复议法审理行政复议案件，由生态环境部行政复议机构对行政行为进行审查，提出意见，经生态环境部的负责人同意或者集体讨论通过后，以生态环境部的名义作出行政复议决定。 生态环境部作出行政复议决定，应当制作行政复议决定书，并加盖生态环境部印章。 行政复议决定书一经送达，即发生法律效力。"},{"i":38,"n":"第三十八条","txt":"被申请人不按照本办法第二十八条、第三十二条的规定提出书面答复、提交作出行政行为的证据、依据和其他有关材料的，视为该行政行为没有证据、依据，生态环境部决定撤销、部分撤销该行政行为，确认该行政行为违法、无效或者决定被申请人在一定期限内履行，但是行政行为涉及第三人合法权益，第三人提供证据的除外。"},{"i":39,"n":"第三十九条","txt":"适用普通程序审理的行政复议案件，生态环境部应当自受理申请之日起六十日内作出行政复议决定；但是法律规定的行政复议期限少于六十日的除外。情况复杂，不能在规定期限内作出行政复议决定的，经生态环境部行政复议机构的负责人批准，可以适当延长，并书面告知当事人；但是延长期限最多不得超过三十日。 适用简易程序审理的行政复议案件，生态环境部应当自受理申请之日起三十日内作出行政复议决定。"},{"i":40,"n":"第四十条","txt":"生态环境部在办理行政复议案件过程中，发现被申请人或者其他下级行政机关的有关行政行为违法或者不当的，可以向其制发行政复议意见书。有关机关应当自收到行政复议意见书之日起六十日内，将纠正相关违法或者不当行政行为的情况报送生态环境部。"},{"i":41,"n":"第四十一条","txt":"被申请人不履行或者无正当理由拖延履行行政复议决定书、调解书、意见书的，生态环境部应当责令其限期履行，并可以约谈被申请人的有关负责人或者予以通报批评。"},{"i":42,"n":"第四十二条","txt":"申请人、第三人逾期不起诉又不履行行政复议决定书、调解书的，按照下列规定分别处理： （一）维持行政行为的行政复议决定书，由作出行政行为的生态环境部及其派出机构、管理的组织依法强制执行，或者申请人民法院强制执行； （二）变更行政行为的行政复议决定书，由生态环境部依法强制执行，或者申请人民法院强制执行； （三）行政复议调解书，由生态环境部依法强制执行，或者申请人民法院强制执行。"},{"i":43,"n":"第四十三条","txt":"生态环境部依照行政复议法等法律、行政法规和国务院有关规定，加强对下级生态环境主管部门依法行政、行政复议答复与行政应诉有关工作的指导。"},{"i":44,"n":"第四十四条","txt":"办结的行政复议案件应当一案一档，由承办人员按时间顺序将案件材料进行整理，立卷归档。"},{"i":45,"n":"第四十五条","txt":"生态环境部应当按照国务院行政复议机构有关行政复议案件和行政应诉案件统计的要求，向国务院行政复议机构报送行政复议和行政应诉情况。"},{"i":46,"n":"第四十六条","txt":"本办法关于行政复议期间有关“三日”“五日”“七日”“十日”的规定是指工作日，不含法定休假日。 期间开始之日，不计算在内。期间届满的最后一日是节假日的，以节假日后的第一日为期间届满的日期。期间不包括在途时间，行政复议文书在期满前交邮的，不算过期。"},{"i":47,"n":"第四十七条","txt":"本办法自2024年6月1日起施行。2008年12月30日原环境保护部发布的《环境行政复议办法》同时废止。"}],"shenghuolajifenshaofadianchangzidongjianceshujuyin353606":[{"i":1,"n":"第一条","txt":"为规范生活垃圾焚烧发电厂自动监测数据使用，推动生活垃圾焚烧发电厂达标排放，依法查处环境违法行为，根据《中华人民共和国环境保护法》《中华人民共和国大气污染防治法》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于投入运行的生活垃圾焚烧发电厂（以下简称垃圾焚烧厂）。"},{"i":3,"n":"第三条","txt":"设区的市级以上地方生态环境主管部门应当将垃圾焚烧厂列入重点排污单位名录。 垃圾焚烧厂应当按照有关法律法规和标准规范安装使用自动监测设备，与生态环境主管部门的监控设备联网。 垃圾焚烧厂应当按照《固定污染源烟气（SO2、NOX、颗粒物）排放连续监测技术规范》（HJ75）等标准规范要求，对自动监测设备开展质量控制和质量保证工作，保证自动监测设备正常运行，保存原始监测记录，并确保自动监测数据的真实、准确、完整、有效。"},{"i":4,"n":"第四条","txt":"垃圾焚烧厂应当按照生活垃圾焚烧发电厂自动监测数据标记规则（以下简称标记规则）,及时在自动监控系统企业端,如实标记每台焚烧炉工况和自动监测异常情况。 自动监测设备发生故障，或者进行检修、校准的，垃圾焚烧厂应当按照标记规则及时标记；未标记的，视为数据有效。"},{"i":5,"n":"第五条","txt":"生态环境主管部门可以利用自动监控系统收集环境违法行为证据。自动监测数据可以作为判定垃圾焚烧厂是否存在环境违法行为的证据。"},{"i":6,"n":"第六条","txt":"一个自然日内，垃圾焚烧厂任一焚烧炉排放烟气中颗粒物、氮氧化物、二氧化硫、氯化氢、一氧化碳等污染物的自动监测日均值数据，有一项或者一项以上超过《生活垃圾焚烧污染控制标准》（GB18485）或者地方污染物排放标准规定的相应污染物24小时均值限值或者日均值限值，可以认定其污染物排放超标。 自动监测日均值数据的计算，按照《污染物在线监控（监测）系统数据传输标准》（HJ212）执行。 对二噁英类等暂不具备自动监测条件的污染物，以生态环境主管部门执法监测获取的监测数据作为超标判定依据。"},{"i":7,"n":"第七条","txt":"垃圾焚烧厂应当按照国家有关规定，确保正常工况下焚烧炉炉膛内热电偶测量温度的5分钟均值不低于850℃。"},{"i":8,"n":"第八条","txt":"生态环境主管部门开展行政执法时，可以按照监测技术规范要求采集一个样品进行执法监测，获取的监测数据可以作为行政执法的证据。 生态环境主管部门执法监测获取的监测数据与自动监测数据不一致的，以生态环境主管部门执法监测获取的监测数据作为行政执法的证据。"},{"i":9,"n":"第九条","txt":"生态环境主管部门执法人员现场调查取证时，应当提取自动监测数据，制作调查询问笔录或者现场检查（勘察）笔录，并对提取过程进行拍照或者摄像，或者采取其他方式记录执法过程。 经现场调查核实垃圾焚烧厂污染物超标排放行为属实的，生态环境主管部门应当当场责令垃圾焚烧厂改正违法行为，并依法下达责令改正违法行为决定书。 生态环境主管部门执法人员现场调查时，可以根据垃圾焚烧厂的违法情形，收集下列证据： （一）当事人的身份证明； （二）调查询问笔录或者现场检查（勘察）笔录； （三）提取的热电偶测量温度的五分钟均值数据、自动监测日均值数据或者数据缺失情况； （四）自动监测设备运行参数记录、运行维护记录； （五）相关生产记录、污染防治设施运行管理台账等； （六）自动监控系统企业端焚烧炉工况、自动监测异常情况数据及标记记录； （七）其他需要的证据。 生态环境主管部门执法人员现场从自动监测设备提取的数据，应当由垃圾"},{"i":10,"n":"第十条","txt":"根据本规定第六条认定为污染物排放超标的，依照《中华人民共和国大气污染防治法》第九十九条第二项的规定处罚。对一个自然月内累计超标5天以上的，应当依法责令限制生产或者停产整治。 垃圾焚烧厂存在下列情形之一，按照标记规则及时在自动监控系统企业端如实标记的，不认定为污染物排放超标： （一）一个自然年内，每台焚烧炉标记为“启炉”“停炉”“故障”“事故”，且颗粒物浓度的小时均值不大于150毫克/立方米的时段，累计不超过60小时的； （二）一个自然年内，每台焚烧炉标记为“烘炉”“停炉降温”的时段，累计不超过700小时的； （三）标记为“停运”的。"},{"i":11,"n":"第十一条","txt":"垃圾焚烧厂正常工况下焚烧炉炉膛内热电偶测量温度的五分钟均值低于850℃，一个自然日内累计超过5次的，认定为“未按照国家有关规定采取有利于减少持久性有机污染物排放的技术方法和工艺”，依照《中华人民共和国大气污染防治法》第一百一十七条第七项的规定处罚。 下列情形不认定为“未按照国家有关规定采取有利于减少持久性有机污染物排放的技术方法和工艺”： （一）因不可抗力导致焚烧炉炉膛内热电偶测量温度的五分钟均值低于850℃，提前采取了有效措施控制烟气中二噁英类污染物排放，按照标记规则标记为“炉温异常”的； （二）标记为“停运”的。"},{"i":12,"n":"第十二条","txt":"垃圾焚烧厂违反本规定第三条第三款，导致自动监测数据缺失或者无效的，认定为“未保证自动监测设备正常运行”，依照《中华人民共和国大气污染防治法》第一百条第三项的规定处罚。 下列情形不认定为“未保证自动监测设备正常运行”： （一）在一个季度内，每台焚烧炉标记为“烟气排放连续监测系统（CEMS）维护”的时段，累计不超过30小时的； （二）标记为“停运”的。"},{"i":13,"n":"第十三条","txt":"垃圾焚烧厂通过下列行为排放污染物的，认定为“通过逃避监管的方式排放大气污染物”，依照《中华人民共和国大气污染防治法》第九十九条第三项的规定处罚： （一）未按照标记规则虚假标记的； （二）篡改、伪造自动监测数据的。"},{"i":14,"n":"第十四条","txt":"垃圾焚烧厂任一焚烧炉出现污染物排放超标，或者未按照国家有关规定采取有利于减少持久性有机污染物排放的技术方法和工艺的情形，持续数日的，按照其违法的日数依法分别处罚；不同焚烧炉分别出现上述违法情形的，依法分别处罚。"},{"i":15,"n":"第十五条","txt":"垃圾焚烧厂5日内多次出现污染物超标排放，或者未按照国家有关规定采取有利于减少持久性有机污染物排放的技术方法和工艺的情形的，生态环境主管部门执法人员可以合并开展现场调查，分别收集每个违法行为的证据，分别制作行政处罚决定书或者列入同一行政处罚决定书。"},{"i":16,"n":"第十六条","txt":"篡改、伪造自动监测数据或者干扰自动监测设备排放污染物，涉嫌构成犯罪的，生态环境主管部门应当依法移送司法机关，追究刑事责任。"},{"i":17,"n":"第十七条","txt":"垃圾焚烧厂因污染物排放超标等环境违法行为被依法处罚的，应当依照国家有关规定，核减或者暂停拨付其国家可再生能源电价附加补贴资金。"},{"i":18,"n":"第十八条","txt":"生活垃圾焚烧发电厂自动监测数据标记规则由生态环境部另行制定。"},{"i":19,"n":"第十九条","txt":"本规定由生态环境部负责解释。"},{"i":20,"n":"第二十条","txt":"本规定自2020年1月1日起施行。"}],"dianzifeiwuwuranhuanjingfangzhiguanlibanfa":[{"i":1,"n":"第一条","txt":"为了防治电子废物污染环境，加强对电子废物的环境管理，根据《固体废物污染环境防治法》，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内拆解、利用、处置电子废物污染环境的防治。　　 产生、贮存电子废物污染环境的防治，也适用本办法；有关法律、行政法规另有规定的，从其规定。　　 电子类危险废物相关活动污染环境的防治，适用《固体废物污染环境防治法》有关危险废物管理的规定。"},{"i":3,"n":"第三条","txt":"国家环境保护总局对全国电子废物污染环境防治工作实施监督管理。　　 县级以上地方人民政府环境保护行政主管部门对本行政区域内电子废物污染环境防治工作实施监督管理。"},{"i":4,"n":"第四条","txt":"任何单位和个人都有保护环境的义务，并有权对造成电子废物污染环境的单位和个人进行控告和检举。"},{"i":5,"n":"第五条","txt":"新建、改建、扩建拆解、利用、处置电子废物的项目，建设单位（包括个体工商户）应当依据国家有关规定，向所在地设区的市级以上地方人民政府环境保护行政主管部门报批环境影响报告书或者环境影响报告表（以下统称环境影响评价文件）。　　 前款规定的环境影响评价文件，应当包括下列内容：　　 （一）建设项目概况；　　 （二）建设项目是否纳入地方电子废物拆解利用处置设施建设规划；　　 （三）选择的技术和工艺路线是否符合国家产业政策和电子废物拆解利用处置环境保护技术规范和管理要求，是否与所拆解利用处置的电子废物类别相适应；　　 （四）建设项目对环境可能造成影响的分析和预测；　　 （五）环境保护措施及其经济、技术论证；　　 （六）对建设项目实施环境监测的方案；　　 （七）对本项目不能完全拆解、利用或者处置的电子废物以及其他固体废物或者液态废物的妥善利用或者处置方案；　　 （八）环境影响评价结论。"},{"i":6,"n":"第六条","txt":"建设项目竣工后，建设单位（包括个体工商户）应当向审批该建设项目环境影响评价文件的环境保护行政主管部门申请该建设项目需要采取的环境保护措施验收。　　 前款规定的环境保护措施验收，应当包括下列内容：　　 （一）配套建设的环境保护设施是否竣工；　　 （二）是否配备具有相关专业资质的技术人员，建立管理人员和操作人员培训制度和计划；　　 （三）是否建立电子废物经营情况记录簿制度；　　 （四）是否建立日常环境监测制度；　　 （五）是否落实不能完全拆解、利用或者处置的电子废物以及其他固体废物或者液态废物的妥善利用或者处置方案；　　 （六）是否具有与所处理的电子废物相适应的分类、包装、车辆以及其他收集设备；　　 （七）是否建立防范因火灾、爆炸、化学品泄漏等引发的突发环境污染事件的应急机制。"},{"i":7,"n":"第七条","txt":"负责审批环境影响评价文件的县级以上人民政府环境保护行政主管部门应当及时将具备下列条件的单位（包括个体工商户），列入电子废物拆解利用处置单位（包括个体工商户）临时名录，并予以公布：　　 （一）已依法办理工商登记手续，取得营业执照；　　 （二）建设项目的环境保护措施经环境保护行政主管部门验收合格。　　 负责审批环境影响评价文件的县级以上人民政府环境保护行政主管部门，对近三年内没有两次以上（含两次）违反环境保护法律、法规和没有本办法规定的下列违法行为的列入临时名录的单位（包括个体工商户），列入电子废物拆解利用处置单位（包括个体工商户）名录，予以公布并定期调整：　　 （一）超过国家或者地方规定的污染物排放标准排放污染物的；　　 （二）随意倾倒、堆放所产生的固体废物或液态废物的；　　 （三）将未完全拆解、利用或者处置的电子废物提供或者委托给列入名录且具有相应经营范围的拆解利用处置单位（包括个体工"},{"i":8,"n":"第八条","txt":"建设电子废物集中拆解利用处置区的，应当严格规划，符合国家环境保护总局制定的有关技术规范的要求。"},{"i":9,"n":"第九条","txt":"从事拆解、利用、处置电子废物活动的单位（包括个体工商户）应当按照环境保护措施验收的要求对污染物排放进行日常定期监测。　　 从事拆解、利用、处置电子废物活动的单位（包括个体工商户）应当按照电子废物经营情况记录簿制度的规定，如实记载每批电子废物的来源、类型、重量或者数量、收集（接收）、拆解、利用、贮存、处置的时间；运输者的名称和地址；未完全拆解、利用或者处置的电子废物以及固体废物或液态废物的种类、重量或者数量及去向等。　　 监测报告及经营情况记录簿应当保存三年。"},{"i":10,"n":"第十条","txt":"从事拆解、利用、处置电子废物活动的单位（包括个体工商户），应当按照经验收合格的培训制度和计划进行培训。"},{"i":11,"n":"第十一条","txt":"拆解、利用和处置电子废物，应当符合国家环境保护总局制定的有关电子废物污染防治的相关标准、技术规范和技术政策的要求。　　 禁止使用落后的技术、工艺和设备拆解、利用和处置电子废物。　　 禁止露天焚烧电子废物。　　 禁止使用冲天炉、简易反射炉等设备和简易酸浸工艺利用、处置电子废物。　　 禁止以直接填埋的方式处置电子废物。　　 拆解、利用、处置电子废物应当在专门作业场所进行。作业场所应当采取防雨、防地面渗漏的措施，并有收集泄漏液体的设施。拆解电子废物，应当首先将铅酸电池、镉镍电池、汞开关、阴极射线管、多氯联苯电容器、制冷剂等去除并分类收集、贮存、利用、处置。　　 贮存电子废物，应当采取防止因破碎或者其他原因导致电子废物中有毒有害物质泄漏的措施。破碎的阴极射线管应当贮存在有盖的容器内。电子废物贮存期限不得超过一年。"},{"i":12,"n":"第十二条","txt":"县级以上人民政府环境保护行政主管部门有权要求拆解、利用、处置电子废物的单位定期报告电子废物经营活动情况。　　 县级以上人民政府环境保护行政主管部门应当通过书面核查和实地检查等方式进行监督检查，并将监督检查情况和处理结果予以记录，由监督检查人员签字后归档。监督抽查和监测一年不得少于一次。　　 县级以上人民政府环境保护行政主管部门发现有不符合环境保护措施验收合格时条件、情节轻微的，可以责令限期整改；经及时整改并未造成危害后果的，可以不予处罚。"},{"i":13,"n":"第十三条","txt":"本办法施行前已经从事拆解、利用、处置电子废物活动的单位（包括个体工商户），具备下列条件的，可以自本办法施行之日起120日内，按照本办法的规定，向所在地设区的市级以上地方人民政府环境保护行政主管部门申请核准列入临时名录，并提供下列相关证明文件：　　 （一）已依法办理工商登记手续，取得营业执照；　　 （二）环境保护设施已经环境保护行政主管部门竣工验收合格；　　 （三）已经符合或者经过整改符合本办法规定的环境保护措施验收条件，能够达到电子废物拆解利用处置环境保护技术规范和管理要求；　　 （四）污染物排放及所产生固体废物或者液态废物的利用或者处置符合环境保护设施竣工验收时的要求。　　 设区的市级以上地方人民政府环境保护行政主管部门应当自受理申请之日起20个工作日内，对申请单位提交的证明材料进行审查，并对申请单位的经营设施进行现场核查，符合条件的，列入临时名录，并予以公告；不符合条件的，书面通知"},{"i":14,"n":"第十四条","txt":"电子电器产品、电子电气设备的生产者应当依据国家有关法律、行政法规或者规章的规定，限制或者淘汰有毒有害物质在产品或者设备中的使用。　　 电子电器产品、电子电气设备的生产者、进口者和销售者，应当依据国家有关规定公开产品或者设备所含铅、汞、镉、六价铬、多溴联苯（PBB）、多溴二苯醚（PBDE）等有毒有害物质，以及不当利用或者处置可能对环境和人类健康影响的信息，产品或者设备废弃后以环境无害化方式利用或者处置的方法提示。　　 电子电器产品、电子电气设备的生产者、进口者和销售者，应当依据国家有关规定建立回收系统,回收废弃产品或者设备，并负责以环境无害化方式贮存、利用或者处置。"},{"i":15,"n":"第十五条","txt":"有下列情形之一的，应当将电子废物提供或者委托给列入名录（包括临时名录）的具有相应经营范围的拆解利用处置单位（包括个体工商户）进行拆解、利用或者处置：　　 （一）产生工业电子废物的单位，未自行以环境无害化方式拆解、利用或者处置的；　　 （二）电子电器产品、电子电气设备生产者、销售者、进口者、使用者、翻新或者维修者、再制造者，废弃电子电器产品、电子电气设备的；　　 （三）拆解利用处置单位（包括个体工商户），不能完全拆解、利用或者处置电子废物的；　　 （四）有关行政主管部门在行政管理活动中，依法收缴的非法生产或者进口的电子电器产品、电子电气设备需要拆解、利用或者处置的。"},{"i":16,"n":"第十六条","txt":"产生工业电子废物的单位，应当记录所产生工业电子废物的种类、重量或者数量、自行或者委托第三方贮存、拆解、利用、处置情况等；并依法向所在地县级以上地方人民政府环境保护行政主管部门提供电子废物的种类、产生量、流向、拆解、利用、贮存、处置等有关资料。　　 记录资料应当保存三年。"},{"i":17,"n":"第十七条","txt":"以整机形式转移含铅酸电池、镉镍电池、汞开关、阴极射线管和多氯联苯电容器的废弃电子电器产品或者电子电气设备等电子类危险废物的，适用《固体废物污染环境防治法》第二十三条的规定。　　 转移过程中应当采取防止废弃电子电器产品或者电子电气设备破碎的措施。"},{"i":18,"n":"第十八条","txt":"县级以上人民政府环境保护行政主管部门违反本办法规定，不依法履行监督管理职责的，由本级人民政府或者上级环境保护行政主管部门依法责令改正；对负有责任的主管人员和其他直接责任人员，依据国家有关规定给予行政处分；构成犯罪的，依法追究刑事责任。"},{"i":19,"n":"第十九条","txt":"违反本办法规定，拒绝现场检查的，由县级以上人民政府环境保护行政主管部门依据《固体废物污染环境防治法》责令限期改正；拒不改正或者在检查时弄虚作假的，处2000元以上2万元以下的罚款；情节严重，但尚构不成刑事处罚的，并由公安机关依据《治安管理处罚法》处5日以上10日以下拘留；构成犯罪的，依法追究刑事责任。"},{"i":20,"n":"第二十条","txt":"违反本办法规定，任何个人或者未列入名录（包括临时名录）的单位（包括个体工商户）从事拆解、利用、处置电子废物活动的，按照下列规定予以处罚：　　 （一）未获得环境保护措施验收合格的，由审批该建设项目环境影响评价文件的人民政府环境保护行政主管部门依据《建设项目环境保护管理条例》责令停止拆解、利用、处置电子废物活动，可以处10万元以下罚款；　　 （二）未取得营业执照的，由工商行政管理部门依据《无照经营查处取缔办法》依法予以取缔，没收专门用于从事无照经营的工具、设备、原材料、产品等财物，并处5万元以上50万元以下的罚款。"},{"i":21,"n":"第二十一条","txt":"违反本办法规定，有下列行为之一的，由所在地县级以上人民政府环境保护行政主管部门责令限期整改，并处3万元以下罚款：　　 （一）将未完全拆解、利用或者处置的电子废物提供或者委托给列入名录（包括临时名录）且具有相应经营范围的拆解利用处置单位（包括个体工商户）以外的单位或者个人从事拆解、利用、处置活动的；　　 （二）拆解、利用和处置电子废物不符合有关电子废物污染防治的相关标准、技术规范和技术政策的要求，或者违反本办法规定的禁止性技术、工艺、设备要求的；　　 （三）贮存、拆解、利用、处置电子废物的作业场所不符合要求的；　　 （四）未按规定记录经营情况、日常环境监测数据、所产生工业电子废物的有关情况等，或者环境监测数据、经营情况记录弄虚作假的；　　 （五）未按培训制度和计划进行培训的；　　 （六）贮存电子废物超过一年的。"},{"i":22,"n":"第二十二条","txt":"列入名录（包括临时名录）的单位（包括个体工商户）违反《固体废物污染环境防治法》等有关法律、行政法规规定，有下列行为之一的，依据有关法律、行政法规予以处罚：　　 （一）擅自关闭、闲置或者拆除污染防治设施、场所的；　　 （二）未采取无害化处置措施，随意倾倒、堆放所产生的固体废物或液态废物的；　　 （三）造成固体废物或液态废物扬散、流失、渗漏或者其他环境污染等环境违法行为的；　　 （四）不正常使用污染防治设施的。　　 有前款第一项、第二项、第三项行为的，分别依据《固体废物污染环境防治法》第六十八条规定，处以1万元以上10万元以下罚款；有前款第四项行为的，依据《水污染防治法》、《大气污染防治法》有关规定予以处罚。"},{"i":23,"n":"第二十三条","txt":"列入名录（包括临时名录）的单位（包括个体工商户）违反《固体废物污染环境防治法》等有关法律、行政法规规定，有造成固体废物或液态废物严重污染环境的下列情形之一的，由所在地县级以上人民政府环境保护行政主管部门依据《固体废物污染环境防治法》和《国务院关于落实科学发展观加强环境保护的决定》的规定，责令限其在三个月内进行治理，限产限排，并不得建设增加污染物排放总量的项目；逾期未完成治理任务的，责令其在三个月内停产整治；逾期仍未完成治理任务的，报经本级人民政府批准关闭：　　 （一）危害生活饮用水水源的；　　 （二）造成地下水或者土壤重金属环境污染的；　　 （三）因危险废物扬散、流失、渗漏造成环境污染的；　　 （四）造成环境功能丧失无法恢复环境原状的； （五）其他造成固体废物或者液态废物严重污染环境的情形。"},{"i":24,"n":"第二十四条","txt":"县级以上人民政府环境保护行政主管部门发现有违反本办法的行为，依据有关法律、法规和本办法的规定应当由工商行政管理部门或者公安机关行使行政处罚权的，应当及时移送有关主管部门依法予以处罚。"},{"i":25,"n":"第二十五条","txt":"本办法中下列用语的含义：　　 （一）电子废物，是指废弃的电子电器产品、电子电气设备(以下简称产品或者设备)及其废弃零部件、元器件和国家环境保护总局会同有关部门规定纳入电子废物管理的物品、物质。包括工业生产活动中产生的报废产品或者设备、报废的半成品和下脚料，产品或者设备维修、翻新、再制造过程产生的报废品，日常生活或者为日常生活提供服务的活动中废弃的产品或者设备，以及法律法规禁止生产或者进口的产品或者设备。　　 （二）工业电子废物，是指在工业生产活动中产生的电子废物，包括维修、翻新和再制造工业单位以及拆解利用处置电子废物的单位（包括个体工商户），在生产活动及相关活动中产生的电子废物。　　 （三）电子类危险废物，是指列入国家危险废物名录或者根据国家规定的危险废物鉴别标准和鉴别方法认定的具有危险特性的电子废物。包括含铅酸电池、镉镍电池、汞开关、阴极射线管和多氯联苯电容器等的产品或者设备等。"},{"i":26,"n":"第二十六条","txt":"本办法自2008年2月1日起施行。"}],"bingyuanweishengwushiyanshishengwuanquanhuanjinggu5fe5b6":[{"i":1,"n":"第一条","txt":"为规范病原微生物实验室(以下简称“实验室”)生物安全环境管理工作，根据《病原微生物实验室生物安全管理条例》和有关环境保护法律和行政法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于中华人民共和国境内的实验室及其从事实验活动的生物安全环境管理。  本办法所称的病原微生物，是指能够使人或者动物致病的微生物。  本办法所称的实验活动，是指实验室从事与病原微生物菌(毒)种、样品有关的研究、教学、检测、诊断等活动。"},{"i":3,"n":"第三条","txt":"国家根据实验室对病原微生物的生物安全防护水平，并依照实验室生物安全国家标准的规定，将实验室分为一级、二级、三级和四级。  一级、二级实验室不得从事高致病性病原微生物实验活动。"},{"i":4,"n":"第四条","txt":"国家环境保护总局制定并颁布实验室污染控制标准、环境管理技术规范和环境监督检查制度。"},{"i":5,"n":"第五条","txt":"国家环境保护总局设立病原微生物实验室生物安全环境管理专家委员会。专家委员会主要由环境保护、病原微生物以及实验室管理方面的专家组成。  病原微生物实验室生物安全环境管理专家委员会的主要职责是：审议有关实验室污染控制标准和环境管理技术规范，提出审议建议；审查有关实验室环境影响评价文件，提出审查建议。"},{"i":6,"n":"第六条","txt":"新建、改建、扩建实验室，应当按照国家环境保护规定,执行环境影响评价制度。  实验室环境影响评价文件应当对病原微生物实验活动对环境可能造成的影响进行分析和预测，并提出预防和控制措施。"},{"i":7,"n":"第七条","txt":"新建、改建、扩建三级、四级实验室或者生产、进口移动式三级、四级实验室，应当编制环境影响报告书，并按照规定程序报国家环境保护总局审批。  承担三级、四级实验室环境影响评价工作的环境影响评价机构，应当具备甲级评价资质和相应的评价范围。"},{"i":8,"n":"第八条","txt":"实验室应当按照国家环境保护规定、经审批的环境影响评价文件以及环境保护行政主管部门批复文件的要求，安装或者配备污染防治设施、设备。  污染防治设施、设备必须经环境保护行政主管部门验收合格后，实验室方可投入运行或者使用。"},{"i":9,"n":"第九条","txt":"建成并通过国家认可的三级、四级实验室，应当在取得生物安全实验室证书后15日内填报三级、四级病原微生物实验室备案表（见附表），报所在地的县级人民政府环境保护行政主管部门。"},{"i":10,"n":"第十条","txt":"县级人民政府环境保护行政主管部门应当自收到三级、四级病原微生物实验室备案表之日起10日内，报设区的市级人民政府环境保护行政主管部门；设区的市级人民政府环境保护行政主管部门应当自收到三级、四级病原微生物实验室备案表之日起10日内，报省级人民政府环境保护行政主管部门；省级人民政府环境保护行政主管部门应当自收到三级、四级病原微生物实验室备案表之日起10日内，报国家环境保护总局。"},{"i":11,"n":"第十一条","txt":"实验室的设立单位对实验活动产生的废水、废气和危险废物承担污染防治责任。  实验室应当依照国家环境保护规定和实验室污染控制标准、环境管理技术规范的要求，建立、健全实验室废水、废气和危险废物污染防治管理的规章制度，并设置专（兼）职人员，对实验室产生的废水、废气及危险废物处置是否符合国家法律、行政法规及本办法规定的情况进行检查、督促和落实。"},{"i":12,"n":"第十二条","txt":"实验室排放废水、废气的，应当按照国家环境保护总局的有关规定，执行排污申报登记制度。  实验室产生危险废物的，必须按照危险废物污染环境防治的有关规定，向所在地县级以上地方人民政府环境保护行政主管部门申报危险废物的种类、产生量、流向、贮存、处置等有关资料。"},{"i":13,"n":"第十三条","txt":"实验室对其产生的废水，必须按照国家有关规定进行无害化处理；符合国家有关排放标准后，方可排放。"},{"i":14,"n":"第十四条","txt":"实验室进行实验活动时，必须按照国家有关规定保证大气污染防治设施的正常运转；排放废气不得违反国家有关标准或者规定。"},{"i":15,"n":"第十五条","txt":"实验室必须按照下列规定，妥善收集、贮存和处置其实验活动产生的危险废物，防止环境污染：  （一）建立危险废物登记制度，对其产生的危险废物进行登记。登记内容应当包括危险废物的来源、种类、重量或者数量、处置方法、最终去向以及经办人签名等项目。登记资料至少保存3年。  （二）及时收集其实验活动中产生的危险废物，并按照类别分别置于防渗漏、防锐器穿透等符合国家有关环境保护要求的专用包装物、容器内，并按国家规定要求设置明显的危险废物警示标识和说明。  （三）配备符合国家法律、行政法规和有关技术规范要求的危险废物暂时贮存柜（箱）或者其他设施、设备。  （四）按照国家有关规定对危险废物就地进行无害化处理，并根据就近集中处置的原则，及时将经无害化处理后的危险废物交由依法取得危险废物经营许可证的单位集中处置。  （五）转移危险废物的，应当按照《固体废物污染环境防治法》和国家环境保护总局的有关规定，执行危险废"},{"i":16,"n":"第十六条","txt":"实验室建立并保留的实验档案应当如实记录与生物安全相关的实验活动和设施、设备工作状态情况，以及实验活动产生的废水、废气和危险废物无害化处理、集中处置以及检验的情况。"},{"i":17,"n":"第十七条","txt":"实验室应当制定环境污染应急预案，报所在地县级人民政府环境保护行政主管部门备案，并定期进行演练。  实验室产生危险废物的，应当按照国家危险废物污染环境防治的规定，制定意外事故的防范措施和应急预案，并向所在地县级以上地方人民政府环境保护行政主管部门备案。  《病原微生物实验室生物安全管理条例》施行前已经投入使用的三级实验室,应当按照所在地县级人民政府环境保护行政主管部门的要求,限期制定环境污染应急预案和监测计划,并报环境保护行政主管部门备案。"},{"i":18,"n":"第十八条","txt":"实验室发生泄露或者扩散，造成或者可能造成严重环境污染或者生态破坏的，应当立即采取应急措施，通报可能受到危害的单位和居民，并向当地人民政府环境保护行政主管部门和有关部门报告，接受调查处理。  当地人民政府环境保护行政主管部门应当按照国家环境保护总局污染事故报告程序规定报告上级人民政府环境保护行政主管部门。"},{"i":19,"n":"第十九条","txt":"县级以上人民政府环境保护行政主管部门应当定期对管辖范围内的实验室废水、废气和危险废物的污染防治情况进行监督检查。发现有违法行为的，应当责令其限期整改。检查情况和处理结果应当予以记录，由检查人员签字后归档并反馈被检查单位。"},{"i":20,"n":"第二十条","txt":"县级以上人民政府环境保护行政主管部门在履行监督检查职责时，有权进入被检查单位和病原微生物泄漏或者扩散现场调查取证，采集样品，查阅、复制有关资料，被检查单位应当予以配合，不得拒绝、阻挠。  需要进入三级或者四级实验室调查取证、采集样品的，应当指定或者委托专业机构实施。  环境保护行政主管部门应当为实验室保守技术秘密和业务秘密。"},{"i":21,"n":"第二十一条","txt":"违反本办法有关规定，有下列情形之一的，由县级以上人民政府环境保护行政主管部门责令限期改正,给予警告;逾期不改正的,处1000元以下罚款：  （一）未建立实验室污染防治管理的规章制度，或者未设置专（兼）职人员的；  （二）未对产生的危险废物进行登记或者未保存登记资料的；  （三）未制定环境污染应急预案的。  违反本办法规定的其他行为，环境保护法律、行政法规已有处罚规定的,适用其规定。"},{"i":22,"n":"第二十二条","txt":"环境保护行政主管部门应当及时向社会公告依据本办法被予以处罚的实验室名单，并将受到处罚的实验室名单通报中国实验室国家认可委员会。"},{"i":23,"n":"第二十三条","txt":"本办法自2006年5月1日起施行。    附件：三级、四级病原微生物实验室备案表 　　 附件：   三级、四级病原微生物实验室备案表   备案日期： 单位名称   法定代表人姓名   地址   邮编   实验室名称   实验室负责人   电话   传真   联系人   主管部门   实验室       安全等级 □三级 □四级 规划部门       审批文件编号   批准日期   主管部门       审批文件编号   批准日期   科技主管部门       审批文件编号   批准日期   环保主管部门       审批文件编号   批准日期   开展的实验       活动内容简述   应提交的       备案附件材料 □ 环境应急预案 □ 废水、废气和危险废物的处理设施和技术方案 实验活动       变更情况   备案单位保证书 本备案表中所申报的内容和所附资料均真实、合法。如"}],"yanjiuduiyingyundanweiheanquanbaogaoguiding":[{"i":1,"n":"第一条","txt":"为了规范研究堆营运单位核安全报告制度，根据《中华人民共和国核安全法》《中华人民共和国民用核设施安全监督管理条例》等法律法规，制定本规定。"},{"i":2,"n":"第二条","txt":"研究堆营运单位对核安全负有全面责任,应当执行核安全报告制度，在建造阶段和运行阶段向国家核安全局或者研究堆所在地区核与辐射安全监督站提交定期报告、重要活动报告、事件报告和核事故应急报告。报告的格式与具体要求，由国家核安全局另行规定。 本规定所称建造阶段为从取得建造许可证之日起，至取得运行许可证之日止；运行阶段为从取得运行许可证之日起，至研究堆终止运行进入停闭管理之日止。 终止运行进入停闭管理、尚未取得退役批准书的研究堆，其核安全报告适用研究堆停闭管理的相关规定。"},{"i":3,"n":"第三条","txt":"研究堆营运单位定期报告包括建造阶段月度报告、年度报告和运行阶段月度报告、年度报告。 研究堆营运单位应当在每个月第十个工作日前，向研究堆所在地区核与辐射安全监督站提交上个月的月度报告;在每年4月1日前，向国家核安全局提交上一年度的年度报告。 营运单位建造或者运行多个研究堆的，可以将多个研究堆的有关信息合并成一份报告。 Ⅲ类研究堆、处于长期停堆管理期间的研究堆，可以不执行运行阶段月度报告，仅执行运行阶段年度报告。"},{"i":4,"n":"第四条","txt":"建造阶段月度报告包括下列内容： （一）上个月建造情况总结和下个月建造计划安排； （二）上个月发生的与安全重要构筑物、系统和设备有关的重要事件综述； （三）安全重要构筑物、系统和设备建造中存在的问题、纠正措施和经验反馈； （四）核安全监管部门所提核安全监管要求落实情况; （五）下个月计划开展的核安全有关重要活动； （六）其他应当报告的事项或者活动。"},{"i":5,"n":"第五条","txt":"运行阶段月度报告包括下列内容： （一）研究堆运行、应用情况； （二）异常、故障和事件情况； （三）维修、检查和修改情况； （四）堆芯变更、燃料操作、固体放射性废物产生、处理和贮存、流出物排放等事项或者活动情况； （五）人员培训及主要运行和安全管理岗位人员变化情况； （六）核安全监管部门所提核安全监管要求落实情况; （七）下个月计划开展的核安全有关重要活动； （八）其他应当报告的事项或者活动。"},{"i":6,"n":"第六条","txt":"建造阶段年度报告包括下列内容： （一）安全重要构筑物、系统和设备建造进展和质量情况总结； （二）报告年份内发生的与安全重要构筑物、系统和设备有关的重要事件综述； （三）安全重要构筑物、系统和设备建造中存在的问题、纠正措施和经验反馈综述； （四）核安全监管部门所提核安全监管要求落实情况综述； （五）其他应当报告的问题和参考资料清单。"},{"i":7,"n":"第七条","txt":"处于长期停堆管理期间的研究堆，运行阶段年度报告包括下列内容： （一）安全重要构筑物、系统和设备的监测、试验、维护和巡视检查情况； （二）燃料管理和放射性废物贮存情况； （三）实物保护系统运行及人员值守情况；    （四）其他应当报告的事项和活动综述。 前款规定以外的研究堆，运行阶段年度报告包括下列内容： （一）研究堆运行、应用情况综述； （二）非计划降功率运行和停堆情况、安全系统故障、运行事件与经验反馈情况综述； （三）维修、检查和修改情况综述； （四）放射性废物管理情况综述； （五）辐射防护和人员培训情况综述; （六）核安全监管部门所提核安全监管要求落实情况综述； （七）其他应当报告的事项和活动综述。"},{"i":8,"n":"第八条","txt":"对未纳入建造阶段月度报告和运行阶段月度报告的重要活动，研究堆营运单位应当以公文、信函、电子邮件或者传真等有效方式，在进行有关重要活动前及时向研究堆所在地区核与辐射安全监督站报告。"},{"i":9,"n":"第九条","txt":"本规定第八条规定的重要活动包括： （一）研究堆营运单位组织的与核安全有关的重要调查、审查或者检查活动； （二）国家核安全局或者研究堆所在地区核与辐射安全监督站确定的有关控制点时间变更和后续计划安排； （三）研究堆营运单位与核安全有关的重要会议、论证、试验和纠正措施； （四）研究堆营运单位进行的新燃料进场、放射性废物或者乏燃料现场转移或者外运活动； （五）国家核安全局或者研究堆营运单位认为应当报告的涉及核安全的其他重要活动；"},{"i":10,"n":"第十条","txt":"建造阶段研究堆安全重要构筑物、系统和设备以及与其有关的采购、土建、安装和调试等活动出现以下情况的，研究堆营运单位应向国家核安全局报告建造事件： （一）与相关法律、行政法规、部门规章和国家强制性标准不一致； （二）违反研究堆建造许可文件规定的条件，或者未按照建造许可文件规定的条件完成相关论证、验证工作即开展相关活动； （三）与研究堆建造许可文件中认可的初步安全分析报告、质量保证大纲不一致，或者与研究堆营运单位在建造许可申请文件中承诺遵守的规范、标准或者技术条件要求不一致，导致研究堆安全重要构筑物、系统和设备的安全功能不能满足或者不能确定满足要求； （四）构成研究堆实体屏障的重要设备或者构筑物受到严重损伤，导致其安全功能不能满足或者不能确定满足要求； （五）发生共因事件或者故障； （六）发生原设计未预计或者结果超出设计范围的情况，导致安全功能可能受到不利影响； （七）发现故意破坏、造假和欺"},{"i":11,"n":"第十一条","txt":"运行阶段研究堆营运单位应向国家核安全局报告下列运行事件： （一）研究堆营运单位执行研究堆运行限值和条件所要求的停堆； （二）研究堆超出安全限值、安全系统整定值，或者超出实验的安全限值、安全系统整定值； （三）违反研究堆运行限值和条件，或者违反实验的运行限值和条件规定的操作或者状况； （四）研究堆主要实体屏障严重劣化，或者出现导致研究堆安全水平明显降低的没有分析过的状况； （五）导致反应堆保护系统、专设安全设施自动或者手动触发的事件； （六）任何可能妨碍构筑物或者系统实现安全停堆和保持安全停堆状态、排出堆芯余热、控制放射性物质释放、缓解事故后果等安全功能的事件； （七）同一原因导致安全系统的系列或者通道同时失效的事件，这些系统包括具有停堆和保持安全停堆状态、排出堆芯余热、控制放射性物质释放、缓解事故后果、事故后监测等安全功能的系统； （八）在运行阶段发现的，由于设计、采购、土建、安装、调"},{"i":12,"n":"第十二条","txt":"研究堆营运单位应当在建造事件、运行事件发生或者发现后二十四小时内，口头通告国家核安全局和研究堆所在地区核与辐射安全监督站。口头通告的方式可以采取电话、当面陈述或者其他有效方式。 建造事件口头通告的内容应当包括研究堆名称、事件发生时间、报告依据、事件摘要和报告人。 运行事件口头通告的内容应当包括研究堆名称、事件发生时间、报告依据、事件发生前研究堆状态和功率水平、事件初步情况，以及口头通告时所处的状况。"},{"i":13,"n":"第十三条","txt":"研究堆营运单位应当在建造事件、运行事件发生或者发现后三日内，向国家核安全局和研究堆所在地区核与辐射安全监督站提交书面通告。 建造事件书面通告的内容应当包括本规定第十二条规定的口头通告的内容，以及出现问题的构筑物、系统和设备及其供货商、制造厂或者施工单位等。 运行事件书面通告的内容应当包括本规定第十二条规定的口头通告的内容，以及初步事件分级、事件对运行的影响、放射性后果、出现问题的系统或者设备等。"},{"i":14,"n":"第十四条","txt":"研究堆营运单位应当在建造事件、运行事件发生或者发现后三十日内，向国家核安全局提交事件报告。 提交事件报告的期限已届满，研究堆营运单位对事件的处理尚没有结论或者没有处理完毕的，可以先向国家核安全局提交阶段性事件报告及下阶段的工作内容和计划，并在事件处理完毕后提交补充信息。 建造事件报告的内容应当包括事件背景、事件描述、已经制定的或者正在进行的纠正措施、事件对工程质量和进度的影响、事件的原因分析和经验教训、事件对安全影响的分析等。 运行事件报告的内容包括事件描述、主要的失效、安全系统响应、事件原因分析、安全后果评估、纠正措施、事件分级、以往类似事件、事件编码等。"},{"i":15,"n":"第十五条","txt":"国家核安全局认为研究堆营运单位提交的事件报告不够清晰和完整的，研究堆营运单位应当在对事件报告内容进行补充或者修改后重新提交。"},{"i":16,"n":"第十六条","txt":"研究堆进入应急状态、应急状态变更或者应急状态终止后三十分钟内，研究堆营运单位应当首先用电话，随后用传真或者其他约定的电子信息传输方式向国家核安全局和研究堆所在地区核与辐射安全监督站发出核事故应急通告。"},{"i":17,"n":"第十七条","txt":"研究堆进入应急状态后，研究堆营运单位应当保持与国家核安全局应急通讯平台的畅通，直到应急状态终止。"},{"i":18,"n":"第十八条","txt":"研究堆进入厂房应急或者高于厂房应急状态后的一小时内，研究堆营运单位应当首先用电话，随后用传真或者其他约定的电子信息传输方式向国家核安全局和研究堆所在地区核与辐射安全监督站发出核事故应急报告，并在首次发出核事故应急报告之后持续发出核事故应急报告，直至应急状态终止。 同一应急状态下，研究堆营运单位连续两次发出核事故应急报告的时间间隔不应超过两小时；事故态势得到控制后，研究堆营运单位发出核事故应急报告的时间间隔可适当延长，但不得超过六小时。 研究堆营运单位认为有必要时,可以向国家核安全局和研究堆所在地区核与辐射安全监督站即时报送核事故应急报告，不受本条规定的时间间隔限制。"},{"i":19,"n":"第十九条","txt":"研究堆应急状态终止后三十日内，研究堆营运单位应当向国家核安全局提交研究堆核事故评价报告，并在核事故评价报告中对核事件或者事故进行分级。"},{"i":20,"n":"第二十条","txt":"研究堆营运单位提交月度报告、年度报告、事件书面通告、事件报告和核事故评价报告的届满之日是节假日的，顺延至节假日后第一个工作日。"},{"i":21,"n":"第二十一条","txt":"本规定中事件或者事故分级，是指按照国际核事件分级标准（INES）对运行事件或者事故进行的分级。"},{"i":22,"n":"第二十二条","txt":"研究堆营运单位的核安全信息公开，按照有关规定执行。"},{"i":23,"n":"第二十三条","txt":"本规定由国家核安全局负责解释。"},{"i":24,"n":"第二十四条","txt":"本规定自2024年9月1日起施行。1995年6月14日国家核安全局发布的《研究堆营运单位报告制度》同时废止。"}],"yanjiuduishejianquanguiding":[],"yanjiuduiyunxinganquanguiding":[],"tanpaifangquanjiaoyiguanlibanfa":[{"i":1,"n":"第一条","txt":"为落实党中央、国务院关于建设全国碳排放权交易市场的决策部署，在应对气候变化和促进绿色低碳发展中充分发挥市场机制作用，推动温室气体减排，规范全国碳排放权交易及相关活动，根据国家有关温室气体排放控制的要求，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于全国碳排放权交易及相关活动，包括碳排放配额分配和清缴，碳排放权登记、交易、结算，温室气体排放报告与核查等活动，以及对前述活动的监督管理。"},{"i":3,"n":"第三条","txt":"全国碳排放权交易及相关活动应当坚持市场导向、循序渐进、公平公开和诚实守信的原则。"},{"i":4,"n":"第四条","txt":"生态环境部按照国家有关规定建设全国碳排放权交易市场。 全国碳排放权交易市场覆盖的温室气体种类和行业范围，由生态环境部拟订，按程序报批后实施，并向社会公开。"},{"i":5,"n":"第五条","txt":"生态环境部按照国家有关规定，组织建立全国碳排放权注册登记机构和全国碳排放权交易机构，组织建设全国碳排放权注册登记系统和全国碳排放权交易系统。 全国碳排放权注册登记机构通过全国碳排放权注册登记系统，记录碳排放配额的持有、变更、清缴、注销等信息，并提供结算服务。全国碳排放权注册登记系统记录的信息是判断碳排放配额归属的最终依据。 全国碳排放权交易机构负责组织开展全国碳排放权集中统一交易。 全国碳排放权注册登记机构和全国碳排放权交易机构应当定期向生态环境部报告全国碳排放权登记、交易、结算等活动和机构运行有关情况，以及应当报告的其他重大事项，并保证全国碳排放权注册登记系统和全国碳排放权交易系统安全稳定可靠运行。"},{"i":6,"n":"第六条","txt":"生态环境部负责制定全国碳排放权交易及相关活动的技术规范，加强对地方碳排放配额分配、温室气体排放报告与核查的监督管理，并会同国务院其他有关部门对全国碳排放权交易及相关活动进行监督管理和指导。 省级生态环境主管部门负责在本行政区域内组织开展碳排放配额分配和清缴、温室气体排放报告的核查等相关活动，并进行监督管理。 设区的市级生态环境主管部门负责配合省级生态环境主管部门落实相关具体工作，并根据本办法有关规定实施监督管理。"},{"i":7,"n":"第七条","txt":"全国碳排放权注册登记机构和全国碳排放权交易机构及其工作人员，应当遵守全国碳排放权交易及相关活动的技术规范，并遵守国家其他有关主管部门关于交易监管的规定。"},{"i":8,"n":"第八条","txt":"温室气体排放单位符合下列条件的，应当列入温室气体重点排放单位（以下简称重点排放单位）名录： （一）属于全国碳排放权交易市场覆盖行业； （二）年度温室气体排放量达到2.6万吨二氧化碳当量。"},{"i":9,"n":"第九条","txt":"省级生态环境主管部门应当按照生态环境部的有关规定，确定本行政区域重点排放单位名录，向生态环境部报告，并向社会公开。"},{"i":10,"n":"第十条","txt":"重点排放单位应当控制温室气体排放，报告碳排放数据，清缴碳排放配额，公开交易及相关活动信息，并接受生态环境主管部门的监督管理。"},{"i":11,"n":"第十一条","txt":"存在下列情形之一的，确定名录的省级生态环境主管部门应当将相关温室气体排放单位从重点排放单位名录中移出： （一）连续二年温室气体排放未达到2.6万吨二氧化碳当量的； （二）因停业、关闭或者其他原因不再从事生产经营活动，因而不再排放温室气体的。"},{"i":12,"n":"第十二条","txt":"温室气体排放单位申请纳入重点排放单位名录的，确定名录的省级生态环境主管部门应当进行核实；经核实符合本办法第八条规定条件的，应当将其纳入重点排放单位名录。"},{"i":13,"n":"第十三条","txt":"纳入全国碳排放权交易市场的重点排放单位，不再参与地方碳排放权交易试点市场。"},{"i":14,"n":"第十四条","txt":"生态环境部根据国家温室气体排放控制要求，综合考虑经济增长、产业结构调整、能源结构优化、大气污染物排放协同控制等因素，制定碳排放配额总量确定与分配方案。 省级生态环境主管部门应当根据生态环境部制定的碳排放配额总量确定与分配方案，向本行政区域内的重点排放单位分配规定年度的碳排放配额。"},{"i":15,"n":"第十五条","txt":"碳排放配额分配以免费分配为主，可以根据国家有关要求适时引入有偿分配。"},{"i":16,"n":"第十六条","txt":"省级生态环境主管部门确定碳排放配额后，应当书面通知重点排放单位。 重点排放单位对分配的碳排放配额有异议的，可以自接到通知之日起七个工作日内，向分配配额的省级生态环境主管部门申请复核；省级生态环境主管部门应当自接到复核申请之日起十个工作日内，作出复核决定。"},{"i":17,"n":"第十七条","txt":"重点排放单位应当在全国碳排放权注册登记系统开立账户，进行相关业务操作。"},{"i":18,"n":"第十八条","txt":"重点排放单位发生合并、分立等情形需要变更单位名称、碳排放配额等事项的，应当报经所在地省级生态环境主管部门审核后，向全国碳排放权注册登记机构申请变更登记。全国碳排放权注册登记机构应当通过全国碳排放权注册登记系统进行变更登记，并向社会公开。"},{"i":19,"n":"第十九条","txt":"国家鼓励重点排放单位、机构和个人，出于减少温室气体排放等公益目的自愿注销其所持有的碳排放配额。 自愿注销的碳排放配额，在国家碳排放配额总量中予以等量核减，不再进行分配、登记或者交易。相关注销情况应当向社会公开。"},{"i":20,"n":"第二十条","txt":"全国碳排放权交易市场的交易产品为碳排放配额，生态环境部可以根据国家有关规定适时增加其他交易产品。"},{"i":21,"n":"第二十一条","txt":"重点排放单位以及符合国家有关交易规则的机构和个人，是全国碳排放权交易市场的交易主体。"},{"i":22,"n":"第二十二条","txt":"碳排放权交易应当通过全国碳排放权交易系统进行，可以采取协议转让、单向竞价或者其他符合规定的方式。 全国碳排放权交易机构应当按照生态环境部有关规定，采取有效措施，发挥全国碳排放权交易市场引导温室气体减排的作用，防止过度投机的交易行为，维护市场健康发展。"},{"i":23,"n":"第二十三条","txt":"全国碳排放权注册登记机构应当根据全国碳排放权交易机构提供的成交结果，通过全国碳排放权注册登记系统为交易主体及时更新相关信息。"},{"i":24,"n":"第二十四条","txt":"全国碳排放权注册登记机构和全国碳排放权交易机构应当按照国家有关规定，实现数据及时、准确、安全交换。"},{"i":25,"n":"第二十五条","txt":"重点排放单位应当根据生态环境部制定的温室气体排放核算与报告技术规范，编制该单位上一年度的温室气体排放报告，载明排放量，并于每年3月31日前报生产经营场所所在地的省级生态环境主管部门。排放报告所涉数据的原始记录和管理台账应当至少保存五年。 重点排放单位对温室气体排放报告的真实性、完整性、准确性负责。 重点排放单位编制的年度温室气体排放报告应当定期公开，接受社会监督，涉及国家秘密和商业秘密的除外。"},{"i":26,"n":"第二十六条","txt":"省级生态环境主管部门应当组织开展对重点排放单位温室气体排放报告的核查，并将核查结果告知重点排放单位。核查结果应当作为重点排放单位碳排放配额清缴依据。 省级生态环境主管部门可以通过政府购买服务的方式委托技术服务机构提供核查服务。技术服务机构应当对提交的核查结果的真实性、完整性和准确性负责。"},{"i":27,"n":"第二十七条","txt":"重点排放单位对核查结果有异议的，可以自被告知核查结果之日起七个工作日内，向组织核查的省级生态环境主管部门申请复核；省级生态环境主管部门应当自接到复核申请之日起十个工作日内，作出复核决定。"},{"i":28,"n":"第二十八条","txt":"重点排放单位应当在生态环境部规定的时限内，向分配配额的省级生态环境主管部门清缴上年度的碳排放配额。清缴量应当大于等于省级生态环境主管部门核查结果确认的该单位上年度温室气体实际排放量。"},{"i":29,"n":"第二十九条","txt":"重点排放单位每年可以使用国家核证自愿减排量抵销碳排放配额的清缴，抵销比例不得超过应清缴碳排放配额的5%。相关规定由生态环境部另行制定。 用于抵销的国家核证自愿减排量，不得来自纳入全国碳排放权交易市场配额管理的减排项目。"},{"i":30,"n":"第三十条","txt":"上级生态环境主管部门应当加强对下级生态环境主管部门的重点排放单位名录确定、全国碳排放权交易及相关活动情况的监督检查和指导。"},{"i":31,"n":"第三十一条","txt":"设区的市级以上地方生态环境主管部门根据对重点排放单位温室气体排放报告的核查结果，确定监督检查重点和频次。 设区的市级以上地方生态环境主管部门应当采取“双随机、一公开”的方式，监督检查重点排放单位温室气体排放和碳排放配额清缴情况，相关情况按程序报生态环境部。"},{"i":32,"n":"第三十二条","txt":"生态环境部和省级生态环境主管部门，应当按照职责分工，定期公开重点排放单位年度碳排放配额清缴情况等信息。"},{"i":33,"n":"第三十三条","txt":"全国碳排放权注册登记机构和全国碳排放权交易机构应当遵守国家交易监管等相关规定，建立风险管理机制和信息披露制度，制定风险管理预案，及时公布碳排放权登记、交易、结算等信息。 全国碳排放权注册登记机构和全国碳排放权交易机构的工作人员不得利用职务便利谋取不正当利益，不得泄露商业秘密。"},{"i":34,"n":"第三十四条","txt":"交易主体违反本办法关于碳排放权注册登记、结算或者交易相关规定的，全国碳排放权注册登记机构和全国碳排放权交易机构可以按照国家有关规定，对其采取限制交易措施。"},{"i":35,"n":"第三十五条","txt":"鼓励公众、新闻媒体等对重点排放单位和其他交易主体的碳排放权交易及相关活动进行监督。 重点排放单位和其他交易主体应当按照生态环境部有关规定，及时公开有关全国碳排放权交易及相关活动信息，自觉接受公众监督。"},{"i":36,"n":"第三十六条","txt":"公民、法人和其他组织发现重点排放单位和其他交易主体有违反本办法规定行为的，有权向设区的市级以上地方生态环境主管部门举报。 接受举报的生态环境主管部门应当依法予以处理，并按照有关规定反馈处理结果，同时为举报人保密。"},{"i":37,"n":"第三十七条","txt":"生态环境部、省级生态环境主管部门、设区的市级生态环境主管部门的有关工作人员，在全国碳排放权交易及相关活动的监督管理中滥用职权、玩忽职守、徇私舞弊的，由其上级行政机关或者监察机关责令改正，并依法给予处分。"},{"i":38,"n":"第三十八条","txt":"全国碳排放权注册登记机构和全国碳排放权交易机构及其工作人员违反本办法规定，有下列行为之一的，由生态环境部依法给予处分，并向社会公开处理结果： （一）利用职务便利谋取不正当利益的； （二）有其他滥用职权、玩忽职守、徇私舞弊行为的。 全国碳排放权注册登记机构和全国碳排放权交易机构及其工作人员违反本办法规定，泄露有关商业秘密或者有构成其他违反国家交易监管规定行为的，依照其他有关规定处理。"},{"i":39,"n":"第三十九条","txt":"重点排放单位虚报、瞒报温室气体排放报告，或者拒绝履行温室气体排放报告义务的，由其生产经营场所所在地设区的市级以上地方生态环境主管部门责令限期改正，处一万元以上三万元以下的罚款。逾期未改正的，由重点排放单位生产经营场所所在地的省级生态环境主管部门测算其温室气体实际排放量，并将该排放量作为碳排放配额清缴的依据；对虚报、瞒报部分，等量核减其下一年度碳排放配额。"},{"i":40,"n":"第四十条","txt":"重点排放单位未按时足额清缴碳排放配额的，由其生产经营场所所在地设区的市级以上地方生态环境主管部门责令限期改正，处二万元以上三万元以下的罚款；逾期未改正的，对欠缴部分，由重点排放单位生产经营场所所在地的省级生态环境主管部门等量核减其下一年度碳排放配额。"},{"i":41,"n":"第四十一条","txt":"违反本办法规定，涉嫌构成犯罪的，有关生态环境主管部门应当依法移送司法机关。"},{"i":42,"n":"第四十二条","txt":"本办法中下列用语的含义： （一）温室气体：是指大气中吸收和重新放出红外辐射的自然和人为的气态成分，包括二氧化碳（CO2）、甲烷（CH4）、氧化亚氮（N2O）、氢氟碳化物（HFCs）、全氟化碳（PFCs）、六氟化硫（SF6）和三氟化氮（NF3）。 （二）碳排放：是指煤炭、石油、天然气等化石能源燃烧活动和工业生产过程以及土地利用变化与林业等活动产生的温室气体排放，也包括因使用外购的电力和热力等所导致的温室气体排放。 （三）碳排放权：是指分配给重点排放单位的规定时期内的碳排放额度。 （四）国家核证自愿减排量：是指对我国境内可再生能源、林业碳汇、甲烷利用等项目的温室气体减排效果进行量化核证，并在国家温室气体自愿减排交易注册登记系统中登记的温室气体减排量。"},{"i":43,"n":"第四十三条","txt":"本办法自2021年2月1日起施行。"}],"tufahuanjingshijianxinxibaogaobanfa":[{"i":1,"n":"第一条","txt":"为了规范突发环境事件信息报告工作，提高环境保护主管部门应对突发环境事件的能力，依据《中华人民共和国突发事件应对法》、《国家突发公共事件总体应急预案》、《国家突发环境事件应急预案》及相关法律法规的规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于环境保护主管部门对突发环境事件的信息报告。 突发环境事件分为特别重大（Ⅰ级）、重大（Ⅱ级）、较大（Ⅲ级）和一般（Ⅳ级）四级。 核与辐射突发环境事件的信息报告按照核安全有关法律法规执行。"},{"i":3,"n":"第三条","txt":"突发环境事件发生地设区的市级或者县级人民政府环境保护主管部门在发现或者得知突发环境事件信息后，应当立即进行核实，对突发环境事件的性质和类别做出初步认定。 对初步认定为一般（IV级）或者较大（III级）突发环境事件的，事件发生地设区的市级或者县级人民政府环境保护主管部门应当在四小时内向本级人民政府和上一级人民政府环境保护主管部门报告。 对初步认定为重大（II级）或者特别重大（I级）突发环境事件的，事件发生地设区的市级或者县级人民政府环境保护主管部门应当在两小时内向本级人民政府和省级人民政府环境保护主管部门报告，同时上报环境保护部。省级人民政府环境保护主管部门接到报告后，应当进行核实并在一小时内报告环境保护部。 突发环境事件处置过程中事件级别发生变化的，应当按照变化后的级别报告信息。"},{"i":4,"n":"第四条","txt":"发生下列一时无法判明等级的突发环境事件，事件发生地设区的市级或者县级人民政府环境保护主管部门应当按照重大（II级）或者特别重大（I级）突发环境事件的报告程序上报： （一）对饮用水水源保护区造成或者可能造成影响的； （二）涉及居民聚居区、学校、医院等敏感区域和敏感人群的； （三）涉及重金属或者类金属污染的； （四）有可能产生跨省或者跨国影响的； （五）因环境污染引发群体性事件，或者社会影响较大的； （六）地方人民政府环境保护主管部门认为有必要报告的其他突发环境事件。"},{"i":5,"n":"第五条","txt":"上级人民政府环境保护主管部门先于下级人民政府环境保护主管部门获悉突发环境事件信息的，可以要求下级人民政府环境保护主管部门核实并报告相应信息。下级人民政府环境保护主管部门应当依照本办法的规定报告信息。"},{"i":6,"n":"第六条","txt":"向环境保护部报告突发环境事件有关信息的，应当报告总值班室，同时报告环境保护部环境应急指挥领导小组办公室。环境保护部环境应急指挥领导小组办公室应当根据情况向部内相关司局通报有关信息。"},{"i":7,"n":"第七条","txt":"环境保护部在接到下级人民政府环境保护主管部门重大（II级）或者特别重大（I级）突发环境事件以及其他有必要报告的突发环境事件信息后，应当及时向国务院总值班室和中共中央办公厅秘书局报告。"},{"i":8,"n":"第八条","txt":"突发环境事件已经或者可能涉及相邻行政区域的，事件发生地环境保护主管部门应当及时通报相邻区域同级人民政府环境保护主管部门，并向本级人民政府提出向相邻区域人民政府通报的建议。接到通报的环境保护主管部门应当及时调查了解情况，并按照本办法第三条、第四条的规定报告突发环境事件信息。"},{"i":9,"n":"第九条","txt":"上级人民政府环境保护主管部门接到下级人民政府环境保护主管部门以电话形式报告的突发环境事件信息后，应当如实、准确做好记录，并要求下级人民政府环境保护主管部门及时报告书面信息。 对于情况不够清楚、要素不全的突发环境事件信息，上级人民政府环境保护主管部门应当要求下级人民政府环境保护主管部门及时核实补充信息。"},{"i":10,"n":"第十条","txt":"县级以上人民政府环境保护主管部门应当建立突发环境事件信息档案，并按照有关规定向上一级人民政府环境保护主管部门报送本行政区域突发环境事件的月度、季度、半年度和年度报告以及统计情况。上一级人民政府环境保护主管部门定期对报告及统计情况进行通报。"},{"i":11,"n":"第十一条","txt":"报告涉及国家秘密的突发环境事件信息，应当遵守国家有关保密的规定。"},{"i":12,"n":"第十二条","txt":"突发环境事件的报告分为初报、续报和处理结果报告。 初报在发现或者得知突发环境事件后首次上报；续报在查清有关基本情况、事件发展情况后随时上报；处理结果报告在突发环境事件处理完毕后上报。"},{"i":13,"n":"第十三条","txt":"初报应当报告突发环境事件的发生时间、地点、信息来源、事件起因和性质、基本过程、主要污染物和数量、监测数据、人员受害情况、饮用水水源地等环境敏感点受影响情况、事件发展趋势、处置情况、拟采取的措施以及下一步工作建议等初步情况，并提供可能受到突发环境事件影响的环境敏感点的分布示意图。 续报应当在初报的基础上，报告有关处置进展情况。 处理结果报告应当在初报和续报的基础上，报告处理突发环境事件的措施、过程和结果，突发环境事件潜在或者间接危害以及损失、社会影响、处理后的遗留问题、责任追究等详细情况。"},{"i":14,"n":"第十四条","txt":"突发环境事件信息应当采用传真、网络、邮寄和面呈等方式书面报告；情况紧急时，初报可通过电话报告，但应当及时补充书面报告。 书面报告中应当载明突发环境事件报告单位、报告签发人、联系人及联系方式等内容，并尽可能提供地图、图片以及相关的多媒体资料。"},{"i":15,"n":"第十五条","txt":"在突发环境事件信息报告工作中迟报、谎报、瞒报、漏报有关突发环境事件信息的，给予通报批评；造成后果的，对直接负责的主管人员和其他直接责任人员依法依纪给予处分；构成犯罪的，移送司法机关依法追究刑事责任。"},{"i":16,"n":"第十六条","txt":"本办法由环境保护部解释。"},{"i":17,"n":"第十七条","txt":"本办法自2011年5月1日起施行。《环境保护行政主管部门突发环境事件信息报告办法（试行）》（环发〔2006〕50号）同时废止。 附录： 突发环境事件分级标准 按照突发事件严重性和紧急程度，突发环境事件分为特别重大（Ⅰ级）、重大（Ⅱ级）、较大（Ⅲ级）和一般（Ⅳ级）四级。 1 特别重大（Ⅰ级）突发环境事件。 凡符合下列情形之一的，为特别重大突发环境事件： （1）因环境污染直接导致10人以上死亡或100人以上中毒的； （2）因环境污染需疏散、转移群众5万人以上的； （3）因环境污染造成直接经济损失1亿元以上的； （4）因环境污染造成区域生态功能丧失或国家重点保护物种灭绝的； （5）因环境污染造成地市级以上城市集中式饮用水水源地取水中断的； （6）1、2类放射源失控造成大范围严重辐射污染后果的；核设施发生需要进入场外应急的严重核事故，或事故辐射后果可能影响邻省和境外的，或按照“国际核事件分级（"}],"tufahuanjingshijianyingjiguanlibanfa":[{"i":1,"n":"第一条","txt":"为预防和减少突发环境事件的发生，控制、减轻和消除突发环境事件引起的危害，规范突发环境事件应急管理工作，保障公众生命安全、环境安全和财产安全，根据《中华人民共和国环境保护法》《中华人民共和国突发事件应对法》《国家突发环境事件应急预案》及相关法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"各级环境保护主管部门和企业事业单位组织开展的突发环境事件风险控制、应急准备、应急处置、事后恢复等工作，适用本办法。 本办法所称突发环境事件，是指由于污染物排放或者自然灾害、生产安全事故等因素，导致污染物或者放射性物质等有毒有害物质进入大气、水体、土壤等环境介质，突然造成或者可能造成环境质量下降，危及公众身体健康和财产安全，或者造成生态环境破坏，或者造成重大社会影响，需要采取紧急措施予以应对的事件。 突发环境事件按照事件严重程度，分为特别重大、重大、较大和一般四级。 核设施及有关核活动发生的核与辐射事故造成的辐射污染事件按照核与辐射相关规定执行。重污染天气应对工作按照《大气污染防治行动计划》等有关规定执行。 造成国际环境影响的突发环境事件的涉外应急通报和处置工作，按照国家有关国际合作的相关规定执行。"},{"i":3,"n":"第三条","txt":"突发环境事件应急管理工作坚持预防为主、预防与应急相结合的原则。"},{"i":4,"n":"第四条","txt":"突发环境事件应对，应当在县级以上地方人民政府的统一领导下，建立分类管理、分级负责、属地管理为主的应急管理体制。 县级以上环境保护主管部门应当在本级人民政府的统一领导下，对突发环境事件应急管理日常工作实施监督管理，指导、协助、督促下级人民政府及其有关部门做好突发环境事件应对工作。"},{"i":5,"n":"第五条","txt":"县级以上地方环境保护主管部门应当按照本级人民政府的要求，会同有关部门建立健全突发环境事件应急联动机制，加强突发环境事件应急管理。 相邻区域地方环境保护主管部门应当开展跨行政区域的突发环境事件应急合作，共同防范、互通信息，协力应对突发环境事件。"},{"i":6,"n":"第六条","txt":"企业事业单位应当按照相关法律法规和标准规范的要求，履行下列义务： （一）开展突发环境事件风险评估； （二）完善突发环境事件风险防控措施； （三）排查治理环境安全隐患； （四）制定突发环境事件应急预案并备案、演练； （五）加强环境应急能力保障建设。 发生或者可能发生突发环境事件时，企业事业单位应当依法进行处理，并对所造成的损害承担责任。"},{"i":7,"n":"第七条","txt":"环境保护主管部门和企业事业单位应当加强突发环境事件应急管理的宣传和教育，鼓励公众参与，增强防范和应对突发环境事件的知识和意识。"},{"i":8,"n":"第八条","txt":"企业事业单位应当按照国务院环境保护主管部门的有关规定开展突发环境事件风险评估，确定环境风险防范和环境安全隐患排查治理措施。"},{"i":9,"n":"第九条","txt":"企业事业单位应当按照环境保护主管部门的有关要求和技术规范，完善突发环境事件风险防控措施。 前款所指的突发环境事件风险防控措施，应当包括有效防止泄漏物质、消防水、污染雨水等扩散至外环境的收集、导流、拦截、降污等措施。"},{"i":10,"n":"第十条","txt":"企业事业单位应当按照有关规定建立健全环境安全隐患排查治理制度，建立隐患排查治理档案，及时发现并消除环境安全隐患。 对于发现后能够立即治理的环境安全隐患，企业事业单位应当立即采取措施，消除环境安全隐患。对于情况复杂、短期内难以完成治理，可能产生较大环境危害的环境安全隐患，应当制定隐患治理方案，落实整改措施、责任、资金、时限和现场应急预案，及时消除隐患。"},{"i":11,"n":"第十一条","txt":"县级以上地方环境保护主管部门应当按照本级人民政府的统一要求，开展本行政区域突发环境事件风险评估工作，分析可能发生的突发环境事件，提高区域环境风险防范能力。"},{"i":12,"n":"第十二条","txt":"县级以上地方环境保护主管部门应当对企业事业单位环境风险防范和环境安全隐患排查治理工作进行抽查或者突击检查，将存在重大环境安全隐患且整治不力的企业信息纳入社会诚信档案, 并可以通报行业主管部门、投资主管部门、证券监督管理机构以及有关金融机构。"},{"i":13,"n":"第十三条","txt":"企业事业单位应当按照国务院环境保护主管部门的规定，在开展突发环境事件风险评估和应急资源调查的基础上制定突发环境事件应急预案，并按照分类分级管理的原则，报县级以上环境保护主管部门备案。"},{"i":14,"n":"第十四条","txt":"县级以上地方环境保护主管部门应当根据本级人民政府突发环境事件专项应急预案，制定本部门的应急预案，报本级人民政府和上级环境保护主管部门备案。"},{"i":15,"n":"第十五条","txt":"突发环境事件应急预案制定单位应当定期开展应急演练，撰写演练评估报告，分析存在问题，并根据演练情况及时修改完善应急预案。"},{"i":16,"n":"第十六条","txt":"环境污染可能影响公众健康和环境安全时，县级以上地方环境保护主管部门可以建议本级人民政府依法及时公布环境污染公共监测预警信息，启动应急措施。"},{"i":17,"n":"第十七条","txt":"县级以上地方环境保护主管部门应当建立本行政区域突发环境事件信息收集系统，通过“12369”环保举报热线、新闻媒体等多种途径收集突发环境事件信息，并加强跨区域、跨部门突发环境事件信息交流与合作。"},{"i":18,"n":"第十八条","txt":"县级以上地方环境保护主管部门应当建立健全环境应急值守制度，确定应急值守负责人和应急联络员并报上级环境保护主管部门。"},{"i":19,"n":"第十九条","txt":"企业事业单位应当将突发环境事件应急培训纳入单位工作计划，对从业人员定期进行突发环境事件应急知识和技能培训，并建立培训档案，如实记录培训的时间、内容、参加人员等信息。"},{"i":20,"n":"第二十条","txt":"县级以上环境保护主管部门应当定期对从事突发环境事件应急管理工作的人员进行培训。 省级环境保护主管部门以及具备条件的市、县级环境保护主管部门应当设立环境应急专家库。 县级以上地方环境保护主管部门和企业事业单位应当加强环境应急处置救援能力建设。"},{"i":21,"n":"第二十一条","txt":"县级以上地方环境保护主管部门应当加强环境应急能力标准化建设，配备应急监测仪器设备和装备，提高重点流域区域水、大气突发环境事件预警能力。"},{"i":22,"n":"第二十二条","txt":"县级以上地方环境保护主管部门可以根据本行政区域的实际情况，建立环境应急物资储备信息库，有条件的地区可以设立环境应急物资储备库。 企业事业单位应当储备必要的环境应急装备和物资，并建立完善相关管理制度。"},{"i":23,"n":"第二十三条","txt":"企业事业单位造成或者可能造成突发环境事件时，应当立即启动突发环境事件应急预案，采取切断或者控制污染源以及其他防止危害扩大的必要措施，及时通报可能受到危害的单位和居民，并向事发地县级以上环境保护主管部门报告，接受调查处理。 应急处置期间，企业事业单位应当服从统一指挥，全面、准确地提供本单位与应急处置相关的技术资料，协助维护应急现场秩序，保护与突发环境事件相关的各项证据。"},{"i":24,"n":"第二十四条","txt":"获知突发环境事件信息后，事件发生地县级以上地方环境保护主管部门应当按照《突发环境事件信息报告办法》规定的时限、程序和要求，向同级人民政府和上级环境保护主管部门报告。"},{"i":25,"n":"第二十五条","txt":"突发环境事件已经或者可能涉及相邻行政区域的，事件发生地环境保护主管部门应当及时通报相邻区域同级环境保护主管部门，并向本级人民政府提出向相邻区域人民政府通报的建议。"},{"i":26,"n":"第二十六条","txt":"获知突发环境事件信息后，县级以上地方环境保护主管部门应当立即组织排查污染源，初步查明事件发生的时间、地点、原因、污染物质及数量、周边环境敏感区等情况。"},{"i":27,"n":"第二十七条","txt":"获知突发环境事件信息后，县级以上地方环境保护主管部门应当按照《突发环境事件应急监测技术规范》开展应急监测，及时向本级人民政府和上级环境保护主管部门报告监测结果。"},{"i":28,"n":"第二十八条","txt":"应急处置期间，事发地县级以上地方环境保护主管部门应当组织开展事件信息的分析、评估，提出应急处置方案和建议报本级人民政府。"},{"i":29,"n":"第二十九条","txt":"突发环境事件的威胁和危害得到控制或者消除后，事发地县级以上地方环境保护主管部门应当根据本级人民政府的统一部署，停止应急处置措施。"},{"i":30,"n":"第三十条","txt":"应急处置工作结束后，县级以上地方环境保护主管部门应当及时总结、评估应急处置工作情况，提出改进措施，并向上级环境保护主管部门报告。"},{"i":31,"n":"第三十一条","txt":"县级以上地方环境保护主管部门应当在本级人民政府的统一部署下，组织开展突发环境事件环境影响和损失等评估工作，并依法向有关人民政府报告。"},{"i":32,"n":"第三十二条","txt":"县级以上环境保护主管部门应当按照有关规定开展事件调查，查清突发环境事件原因，确认事件性质，认定事件责任，提出整改措施和处理意见。"},{"i":33,"n":"第三十三条","txt":"县级以上地方环境保护主管部门应当在本级人民政府的统一领导下，参与制定环境恢复工作方案，推动环境恢复工作。"},{"i":34,"n":"第三十四条","txt":"企业事业单位应当按照有关规定，采取便于公众知晓和查询的方式公开本单位环境风险防范工作开展情况、突发环境事件应急预案及演练情况、突发环境事件发生及处置情况，以及落实整改要求情况等环境信息。"},{"i":35,"n":"第三十五条","txt":"突发环境事件发生后，县级以上地方环境保护主管部门应当认真研判事件影响和等级，及时向本级人民政府提出信息发布建议。履行统一领导职责或者组织处置突发事件的人民政府，应当按照有关规定统一、准确、及时发布有关突发事件事态发展和应急处置工作的信息。"},{"i":36,"n":"第三十六条","txt":"县级以上环境保护主管部门应当在职责范围内向社会公开有关突发环境事件应急管理的规定和要求，以及突发环境事件应急预案及演练情况等环境信息。 县级以上地方环境保护主管部门应当对本行政区域内突发环境事件进行汇总分析，定期向社会公开突发环境事件的数量、级别，以及事件发生的时间、地点、应急处置概况等信息。"},{"i":37,"n":"第三十七条","txt":"企业事业单位违反本办法规定，导致发生突发环境事件，《中华人民共和国突发事件应对法》《中华人民共和国水污染防治法》《中华人民共和国大气污染防治法》《中华人民共和国固体废物污染环境防治法》等法律法规已有相关处罚规定的，依照有关法律法规执行。 较大、重大和特别重大突发环境事件发生后，企业事业单位未按要求执行停产、停排措施，继续违反法律法规规定排放污染物的，环境保护主管部门应当依法对造成污染物排放的设施、设备实施查封、扣押。"},{"i":38,"n":"第三十八条","txt":"企业事业单位有下列情形之一的，由县级以上环境保护主管部门责令改正，可以处一万元以上三万元以下罚款： （一）未按规定开展突发环境事件风险评估工作，确定风险等级的； （二）未按规定开展环境安全隐患排查治理工作，建立隐患排查治理档案的； （三）未按规定将突发环境事件应急预案备案的； （四）未按规定开展突发环境事件应急培训，如实记录培训情况的； （五）未按规定储备必要的环境应急装备和物资； （六）未按规定公开突发环境事件相关信息的。"},{"i":39,"n":"第三十九条","txt":"本办法由国务院环境保护主管部门负责解释。"},{"i":40,"n":"第四十条","txt":"本办法自2015年 6月5日起施行。"}],"tufahuanjingshijiandiaochachulibanfa":[{"i":1,"n":"第一条","txt":"为规范突发环境事件调查处理工作，依照《中华人民共和国环境保护法》、《中华人民共和国突发事件应对法》等法律法规，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于对突发环境事件的原因、性质、责任的调查处理。 核与辐射突发事件的调查处理，依照核与辐射安全有关法律法规执行。"},{"i":3,"n":"第三条","txt":"突发环境事件调查应当遵循实事求是、客观公正、权责一致的原则,及时、准确查明事件原因，确认事件性质，认定事件责任，总结事件教训，提出防范和整改措施建议以及处理意见。"},{"i":4,"n":"第四条","txt":"环境保护部负责组织重大和特别重大突发环境事件的调查处理；省级环境保护主管部门负责组织较大突发环境事件的调查处理；事发地设区的市级环境保护主管部门视情况组织一般突发环境事件的调查处理。 上级环境保护主管部门可以视情况委托下级环境保护主管部门开展突发环境事件调查处理，也可以对由下级环境保护主管部门负责的突发环境事件直接组织调查处理，并及时通知下级环境保护主管部门。 下级环境保护主管部门对其负责的突发环境事件，认为需要由上一级环境保护主管部门调查处理的，可以报请上一级环境保护主管部门决定。"},{"i":5,"n":"第五条","txt":"突发环境事件调查应当成立调查组，由环境保护主管部门主要负责人或者主管环境应急管理工作的负责人担任组长，应急管理、环境监测、环境影响评价管理、环境监察等相关机构的有关人员参加。 环境保护主管部门可以聘请环境应急专家库内专家和其他专业技术人员协助调查。 环境保护主管部门可以根据突发环境事件的实际情况邀请公安、交通运输、水利、农业、卫生、安全监管、林业、地震等有关部门或者机构参加调查工作。 调查组可以根据实际情况分为若干工作小组开展调查工作。工作小组负责人由调查组组长确定。"},{"i":6,"n":"第六条","txt":"调查组成员和受聘请协助调查的人员不得与被调查的突发环境事件有利害关系。 调查组成员和受聘请协助调查的人员应当遵守工作纪律，客观公正地调查处理突发环境事件，并在调查处理过程中恪尽职守，保守秘密。未经调查组组长同意，不得擅自发布突发环境事件调查的相关信息。"},{"i":7,"n":"第七条","txt":"开展突发环境事件调查，应当制定调查方案，明确职责分工、方法步骤、时间安排等内容。"},{"i":8,"n":"第八条","txt":"开展突发环境事件调查，应当对突发环境事件现场进行勘查，并可以采取以下措施： （一）通过取样监测、拍照、录像、制作现场勘查笔录等方法记录现场情况，提取相关证据材料； （二）进入突发环境事件发生单位、突发环境事件涉及的相关单位或者工作场所，调取和复制相关文件、资料、数据、记录等； （三）根据调查需要，对突发环境事件发生单位有关人员、参与应急处置工作的知情人员进行询问，并制作询问笔录。 进行现场勘查、检查或者询问，不得少于两人。 突发环境事件发生单位的负责人和有关人员在调查期间应当依法配合调查工作，接受调查组的询问，并如实提供相关文件、资料、数据、记录等。因客观原因确实无法提供的，可以提供相关复印件、复制品或者证明该原件、原物的照片、录像等其他证据，并由有关人员签字确认。 现场勘查笔录、检查笔录、询问笔录等，应当由调查人员、勘查现场有关人员、被询问人员签名。 开展突发环境事件调查，应当制作调"},{"i":9,"n":"第九条","txt":"突发环境事件调查应当查明下列情况： （一）突发环境事件发生单位基本情况； （二）突发环境事件发生的时间、地点、原因和事件经过； （三）突发环境事件造成的人身伤亡、直接经济损失情况，环境污染和生态破坏情况； （四）突发环境事件发生单位、地方人民政府和有关部门日常监管和事件应对情况； （五）其他需要查明的事项。"},{"i":10,"n":"第十条","txt":"环境保护主管部门应当按照所在地人民政府的要求，根据突发环境事件应急处置阶段污染损害评估工作的有关规定，开展应急处置阶段污染损害评估。 应急处置阶段污染损害评估报告或者结论是编写突发环境事件调查报告的重要依据。"},{"i":11,"n":"第十一条","txt":"开展突发环境事件调查，应当查明突发环境事件发生单位的下列情况： （一）建立环境应急管理制度、明确责任人和职责的情况； （二）环境风险防范设施建设及运行的情况； （三）定期排查环境安全隐患并及时落实环境风险防控措施的情况； （四）环境应急预案的编制、备案、管理及实施情况； （五）突发环境事件发生后的信息报告或者通报情况； （六）突发环境事件发生后，启动环境应急预案，并采取控制或者切断污染源防止污染扩散的情况； （七）突发环境事件发生后，服从应急指挥机构统一指挥，并按要求采取预防、处置措施的情况； （八）生产安全事故、交通事故、自然灾害等其他突发事件发生后，采取预防次生突发环境事件措施的情况； （九）突发环境事件发生后，是否存在伪造、故意破坏事发现场，或者销毁证据阻碍调查的情况。"},{"i":12,"n":"第十二条","txt":"开展突发环境事件调查，应当查明有关环境保护主管部门环境应急管理方面的下列情况： （一）按规定编制环境应急预案和对预案进行评估、备案、演练等的情况，以及按规定对突发环境事件发生单位环境应急预案实施备案管理的情况； （二）按规定赶赴现场并及时报告的情况； （三）按规定组织开展环境应急监测的情况； （四）按职责向履行统一领导职责的人民政府提出突发环境事件处置或者信息发布建议的情况； （五）突发环境事件已经或者可能涉及相邻行政区域时，事发地环境保护主管部门向相邻行政区域环境保护主管部门的通报情况； （六）接到相邻行政区域突发环境事件信息后，相关环境保护主管部门按规定调查了解并报告的情况； （七）按规定开展突发环境事件污染损害评估的情况。"},{"i":13,"n":"第十三条","txt":"开展突发环境事件调查，应当收集地方人民政府和有关部门在突发环境事件发生单位建设项目立项、审批、验收、执法等日常监管过程中和突发环境事件应对、组织开展突发环境事件污染损害评估等环节履职情况的证据材料。"},{"i":14,"n":"第十四条","txt":"开展突发环境事件调查，应当在查明突发环境事件基本情况后，编写突发环境事件调查报告。"},{"i":15,"n":"第十五条","txt":"突发环境事件调查报告应当包括下列内容： （一）突发环境事件发生单位的概况和突发环境事件发生经过； （二）突发环境事件造成的人身伤亡、直接经济损失，环境污染和生态破坏的情况； （三）突发环境事件发生的原因和性质； （四）突发环境事件发生单位对环境风险的防范、隐患整改和应急处置情况； （五）地方政府和相关部门日常监管和应急处置情况； （六）责任认定和对突发环境事件发生单位、责任人的处理建议； （七）突发环境事件防范和整改措施建议； （八）其他有必要报告的内容。"},{"i":16,"n":"第十六条","txt":"特别重大突发环境事件、重大突发环境事件的调查期限为六十日；较大突发环境事件和一般突发环境事件的调查期限为三十日。突发环境事件污染损害评估所需时间不计入调查期限。 调查组应当按照前款规定的期限完成调查工作，并向同级人民政府和上一级环境保护主管部门提交调查报告。 调查期限从突发环境事件应急状态终止之日起计算。"},{"i":17,"n":"第十七条","txt":"环境保护主管部门应当依法向社会公开突发环境事件的调查结论、环境影响和损失的评估结果等信息。"},{"i":18,"n":"第十八条","txt":"突发环境事件调查过程中发现突发环境事件发生单位涉及环境违法行为的，调查组应当及时向相关环境保护主管部门提出处罚建议。相关环境保护主管部门应当依法对事发单位及责任人员予以行政处罚；涉嫌构成犯罪的，依法移送司法机关追究刑事责任。发现其他违法行为的，环境保护主管部门应当及时向有关部门移送。 发现国家行政机关及其工作人员、突发环境事件发生单位中由国家行政机关任命的人员涉嫌违法违纪的，环境保护主管部门应当依法及时向监察机关或者有关部门提出处分建议。"},{"i":19,"n":"第十九条","txt":"对于连续发生突发环境事件，或者突发环境事件造成严重后果的地区，有关环境保护主管部门可以约谈下级地方人民政府主要领导。"},{"i":20,"n":"第二十条","txt":"环境保护主管部门应当将突发环境事件发生单位的环境违法信息记入社会诚信档案，并及时向社会公布。"},{"i":21,"n":"第二十一条","txt":"环境保护主管部门可以根据调查报告，对下级人民政府、下级环境保护主管部门下达督促落实突发环境事件调查报告有关防范和整改措施建议的督办通知，并明确责任单位、工作任务和完成时限。 接到督办通知的有关人民政府、环境保护主管部门应当在规定时限内，书面报送事件防范和整改措施建议的落实情况。"},{"i":22,"n":"第二十二条","txt":"本办法由环境保护部负责解释。"},{"i":23,"n":"第二十三条","txt":"本办法自2015年3月1日起施行。"}],"jinchukouhuanbaoyongweishengwujunjihuanjinganquang36c4f6":[{"i":1,"n":"第一条","txt":"为加强进出口环保用微生物菌剂环境安全管理，维护环境安全，根据《中华人民共和国国境卫生检疫法》及其实施细则、《中华人民共和国环境保护法》等有关规定，制定本办法。"},{"i":2,"n":"第二条","txt":"本办法适用于进出口环保用微生物菌剂环境安全管理。 本办法所称环保用微生物菌剂，是指从自然界分离纯化或者经人工选育等现代生物技术手段获得的，主要用于水、大气、土壤、固体废物污染检测、治理和修复的一种或者多种微生物菌种。"},{"i":3,"n":"第三条","txt":"国家对进出口环保用微生物菌剂的环境安全管理，实行检测和环境安全评价制度。"},{"i":4,"n":"第四条","txt":"环保用微生物菌剂进出口经营者，应当是依法成立的从事生产或者使用微生物菌剂的企业事业法人，并具备微生物菌剂安全生产、使用、储藏、运输和应急处置的能力。 进口环保用微生物菌剂，应当按照本办法的规定申请获得《微生物菌剂样品环境安全证明》，并凭该样品环境安全证明依法办理卫生检疫审批和现场查验。"},{"i":5,"n":"第五条","txt":"环境保护部对进出口环保用微生物菌剂环境安全实施监督管理。省、自治区、直辖市环境保护行政主管部门依照本办法对辖区内进出口环保用微生物菌剂环境安全实施监督管理。 国家质量监督检验检疫总局统一管理全国进出口环保用微生物菌剂的卫生检疫监督管理工作；国家质量监督检验检疫总局设在各地的出入境检验检疫机构对辖区内进出口环保用微生物菌剂实施卫生检疫监督管理。"},{"i":6,"n":"第六条","txt":"环境保护部会同国家质量监督检验检疫总局设立环保用微生物环境安全评价专家委员会，负责对微生物菌剂样品的环境安全性进行评审。"},{"i":7,"n":"第七条","txt":"进口经营者应当向微生物菌剂使用活动所在地省、自治区、直辖市环境保护行政主管部门提交下列材料，先行申请办理环保用微生物菌剂样品入境手续： （一）进口经营者与境外经营者签订的微生物菌剂进口合同或者合同意向书的复印件； （二）进口经营者主管人员和专业技术人员具备的微生物生产、应用和安全操作的专业学历或者资格证书复印件； （三）微生物菌剂生产、使用、储藏、运输、处理的环境安全控制措施和突发环境事件应急预案； （四）出口国政府主管部门出具的微生物菌剂环境安全证明； （五）微生物菌剂在出口国的生产和应用情况； （六）拟进口用于检测和环境安全评价样品的最低数量和规格； （七）微生物菌剂环境安全性的其他证明资料。 前款所列材料，应当用中文或者中、英文对照文本，一式三份。"},{"i":8,"n":"第八条","txt":"省、自治区、直辖市环境保护行政主管部门应当自受理进口样品申请之日起30日内，对申请材料进行审查，材料齐备、内容属实的，核发《环保用微生物菌剂样品入境通知单》。 必要时，省、自治区、直辖市环境保护行政主管部门可以组织专家进行技术审查，审查合格的，核发《环保用微生物菌剂样品入境通知单》。 《环保用微生物菌剂样品入境通知单》必须注明进口样品的数量和规格。《环保用微生物菌剂样品入境通知单》一式两份，一份用于样品检疫审批，一份用于样品环境安全评价数量核销。"},{"i":9,"n":"第九条","txt":"直属检验检疫局凭《环保用微生物菌剂样品入境通知单》，签发样品卫生检疫审批单。 样品入境口岸检验检疫机构凭样品卫生检疫审批单，对样品的数量、规格、外包装情况进行现场查验。对样品查验合格的，准予入境。"},{"i":10,"n":"第十条","txt":"进口经营者，应当委托微生物检测和环境安全评价机构对样品进行检测和环境安全评价。 接受委托的检测和环境安全评价机构，应当是从事微生物研究的合格实验室（GLP），或者中国合格评定国家认可委员会认可的国家级专业机构。"},{"i":11,"n":"第十一条","txt":"样品检测和环境安全评价机构应当按照环境保护部制定的《环保用微生物菌剂检测规程》和《环保用微生物菌剂使用环境安全评价导则》，对进口微生物菌剂进行检测和环境安全评价，出具样品检测和环境安全评价报告，并对检测数据和评价结论的真实性、准确性负责。 检测和环境安全评价报告，应当包括下列内容： （一）微生物菌剂的微生物学检测鉴定； （二）微生物菌剂的安全性试验； （三）微生物菌剂的评价； （四）微生物菌剂的卫生学安全评价； （五）微生物菌剂及各类终产物的生态安全评价； （六）微生物菌剂的生产或者使用环境评价。 检测和环境安全评价报告，还应当附具下列内容： （一）微生物菌剂出口国已有的环境安全评价资料； （二）检测和环境安全评价机构及其代理机构资质信息。 样品检测和环境安全评价报告，一式三份。"},{"i":12,"n":"第十二条","txt":"样品检测和环境安全评价结束后，检测和环境安全评价机构应当将微生物菌剂样品全部安全销毁，不得保留或者移作他用。"},{"i":13,"n":"第十三条","txt":"进口经营者应当将样品全数交验。检测和环境安全评价机构应当根据《环保用微生物菌剂样品入境通知单》，核对样品数量和规格；对数量和规格与《环保用微生物菌剂样品入境通知单》中不一致的，不得出具样品检测和环境安全评价报告。"},{"i":14,"n":"第十四条","txt":"进口经营者，应当向环保用微生物菌剂使用活动所在地省、自治区、直辖市环境保护行政主管部门提交样品检测和环境安全评价报告。"},{"i":15,"n":"第十五条","txt":"省、自治区、直辖市环境保护行政主管部门应当自收到进口经营者提交的样品检测和环境安全评价报告之日起30日内进行审核，签署审核意见，连同申报材料、检测和环境安全评价报告一式三份报环境保护部。 环境保护部自收到申报材料之日起5个工作日内，将申报材料提交环保用微生物环境安全评价专家委员会。"},{"i":16,"n":"第十六条","txt":"环保用微生物环境安全评价专家委员会应当自收到申报材料之日起15个工作日内完成评审，提出《环保用微生物菌剂样品环境安全性评审意见》，报环境保护部。"},{"i":17,"n":"第十七条","txt":"《环保用微生物菌剂样品环境安全性评审意见》，应当包括下列内容： （一）进口经营者申报的微生物菌剂主要成分与检测机构的检测结果是否一致； （二）微生物菌剂中是否含有对人体健康和生态环境构成危险或者较大风险的微生物菌种（群）； （三）微生物菌剂是否已经在出口国进行安全生产和使用； （四）项目负责人和工作人员是否具备微生物生产、应用和安全操作专业学历或者资格； （五）微生物菌剂生产、使用、储藏、运输和处理的环境安全控制措施和事故处置应急预案是否可行。"},{"i":18,"n":"第十八条","txt":"环境保护部依据《环保用微生物菌剂样品环境安全性评审意见》，对检测和环境安全评价合格的微生物菌剂，出具《环保用微生物菌剂样品环境安全证明》。"},{"i":19,"n":"第十九条","txt":"同一进口经营者的同一商品(项目)名称微生物菌剂，应当申请一个《环保用微生物菌剂样品环境安全证明》。 已获得《环保用微生物菌剂样品环境安全证明》的同一微生物菌剂，有两个以上商品(项目)名称的，应当报环境保护部备案。"},{"i":20,"n":"第二十条","txt":"《环保用微生物菌剂样品环境安全证明》有效期为三年。 有效期届满后仍然需要进口该微生物菌剂的，进口经营者需要重新办理《环保用微生物菌剂样品环境安全证明》。"},{"i":21,"n":"第二十一条","txt":"任何单位和个人不得转让、伪造、涂改或者变造《环保用微生物菌剂样品环境安全证明》。"},{"i":22,"n":"第二十二条","txt":"进出口经营者按照《出入境特殊物品卫生检疫管理规定》的规定，向直属检验检疫局提出卫生检疫审批申请。进口经营者还应当提供环境保护部出具的《环保用微生物菌剂样品环境安全证明》。 直属检验检疫局对准予进出口的，出具《出入境特殊物品卫生检疫审批单》。"},{"i":23,"n":"第二十三条","txt":"口岸检验检疫机构凭《出入境特殊物品卫生检疫审批单》受理环保用微生物菌剂报检，实施现场检疫查验，并按照有关规定抽样送专业的环保微生物菌剂符合检测实验室进行检验，经符合性检验及卫生学检验合格的，方可放行。"},{"i":24,"n":"第二十四条","txt":"口岸检验检疫机构对首次送检的环保用微生物菌剂，应当在20个工作日内完成检验；对首次检验已经合格的，应当在10个工作日内完成检验。"},{"i":25,"n":"第二十五条","txt":"进出口经营者应当采取环保用微生物菌剂生产、使用、储藏、运输和处理的环境安全控制措施，制定事故处置应急预案。 进出口经营者应当保留环保用微生物菌剂生产、使用、储藏、运输和处理记录。"},{"i":26,"n":"第二十六条","txt":"进出口经营者应当于每年1月31日前，将上一年度环保用微生物菌剂生产或者使用环境安全管理情况和本年度环保用微生物菌剂进出口计划，报省、自治区、直辖市环境保护行政主管部门备案。"},{"i":27,"n":"第二十七条","txt":"环保用微生物菌剂在进出口、生产或者使用过程中，出现异常情况，或者有新的科学依据证明对人体健康和生态环境构成危害的，环境保护部应当撤销其《环保用微生物菌剂样品环境安全证明》，监督进口单位销毁该微生物菌剂，并向国家质量监督检验检疫总局通报有关情况。"},{"i":28,"n":"第二十八条","txt":"进出口经营者应当向环保用微生物菌剂生产或者使用活动所在地省、自治区、直辖市环境保护行政主管部门备案。变更环保用微生物菌剂生产或者使用活动所在地的，应当分别向变更前和变更后生产或者使用活动所在地省、自治区、直辖市环境保护行政主管部门办理备案变更。"},{"i":29,"n":"第二十九条","txt":"违反本办法规定，样品检测和环境安全评价结束后，未将微生物菌剂样品全部安全销毁的，由检测和环境安全评价机构所在地省、自治区、直辖市环境行政主管部门责令改正；拒不改正的，可以处一万元以上三万元以下的罚款，并由环境保护主管部门指定有能力的单位代为销毁，所需费用由违法者承担。 检测和环境安全评价机构出具虚假样品检测和环境安全评价结论的，环境保护部不再受理该评价机构做出的样品检测和环境安全评价报告。"},{"i":30,"n":"第三十条","txt":"伪造或者涂改检疫单、证的，检验检疫机构可以给予警告或者处以5000元以下的罚款。 违反本办法规定，转让、伪造、涂改或者变造《环保用微生物菌剂样品环境安全证明》的，或者隐瞒有关情况、提供虚假材料的，由环境保护部撤销《环保用微生物菌剂样品环境安全证明》，直属检验检疫局吊销《出入境特殊物品卫生检疫审批单》；构成犯罪的，依法追究刑事责任。"},{"i":31,"n":"第三十一条","txt":"违反本办法规定，未妥善保存微生物菌剂生产、使用、储藏、运输和处理记录，或者未执行微生物菌剂生产、使用、储藏、运输和处理的环境安全控制措施和事故处置应急预案的，由省、自治区、直辖市环境保护行政主管部门责令改正；拒不改正的，处一万元以上三万元以下罚款。"},{"i":32,"n":"第三十二条","txt":"有关国际公约、双边或者多边协议、进口国法律的规定以及合同约定，需要对出口环保用微生物菌剂样品进行环境安全评价和环境安全证明的，参照本办法第三、四章执行。"},{"i":33,"n":"第三十三条","txt":"进出口环保用微生物菌剂涉及动植物安全的，应当符合《中华人民共和国进出境动植物检疫法》等法律法规规定，并办理进境动植物检疫特许审批。"},{"i":34,"n":"第三十四条","txt":"进口经营者委托代理进口申请的，其代理人除提交第七条规定的申请材料外，还应当提供与进口经营者签订的协议以及营业执照原件。"},{"i":35,"n":"第三十五条","txt":"《环保用微生物菌剂样品入境通知单》和《环保用微生物菌剂样品环境安全证明》的格式与内容，由环境保护部统一制定。"},{"i":36,"n":"第三十六条","txt":"本办法自2010年5月1日起施行。"}],"jinkouminyongheanquanshebeijianduguanliguiding":[{"i":1,"n":"第一条","txt":"为了加强对进口民用核安全设备的监督管理，根据《民用核安全设备监督管理条例》，制定本规定。"},{"i":2,"n":"第二条","txt":"本规定适用于为中华人民共和国境内民用核设施进行民用核安全设备设计、制造、安装和无损检验活动的境外单位（以下简称“境外单位”）的注册登记管理以及进口民用核安全设备的安全检验。"},{"i":3,"n":"第三条","txt":"国务院核安全监管部门负责对境外单位进行注册登记管理，并对其从事的民用核安全设备设计、制造、安装和无损检验活动实施监督检查。 国务院核安全监管部门及其所属的检验机构依法对进口民用核安全设备进行安全检验。"},{"i":4,"n":"第四条","txt":"民用核设施营运单位，应当在民用核安全设备的对外贸易合同中，明确约定下列主要内容： （一）境外单位应当配合国务院核安全监管部门的监督检查； （二）有关进口民用核安全设备监造、装运前检验、监装和验收等方面的要求； （三）进口民用核安全设备的技术条件和安全检验的相关事项。"},{"i":5,"n":"第五条","txt":"境外单位应当事先到国务院核安全监管部门申请注册登记。 拟从事民用核安全设备设计、制造或者安装活动的，应当按照活动种类（设计、制造、安装）、设备类别和核安全级别提出申请。 拟从事民用核安全设备无损检验活动的，应当按照无损检验方法提出申请。无损检验方法包括：射线检验（RT）、超声检验（UT）、磁粉检验（MT）、涡流检验（ET）、渗透检验（PT）、泄漏检验（LT）、目视检验（VT）等。"},{"i":6,"n":"第六条","txt":"申请注册登记的境外单位，应当符合《民用核安全设备监督管理条例》第三十一条规定的条件，主要包括： （一）遵守中华人民共和国法律、行政法规的规定； （二）为所在国家（地区）合法设立的经营企业； （三）具有与拟从事活动相关的工作业绩，并且满5年以上； （四）具有与拟从事活动相适应的工作场所、设施和装备，以及经考核合格的专业技术人员； （五）具有与拟从事活动相适应的质量保证体系； （六）已取得所在国核安全监管部门规定的相应资质； （七）使用的民用核安全设备设计、制造、安装和无损检验技术是成熟的或者经过验证的； （八）采用中华人民共和国的民用核安全设备国家标准、行业标准或者国务院核安全监管部门认可的标准。"},{"i":7,"n":"第七条","txt":"申请注册登记的，应当提交下列申请材料： （一）境外单位注册登记申请书； （二）经营企业在所在国家（地区）合法设立的证明材料； （三）已取得所在国核安全监管部门规定资质的证明材料，或者已取得其他相关资质的证明材料； （四）从事核设施核安全设备活动业绩的说明材料； （五）与拟从事的民用核安全设备活动相关的能力说明材料，包括人员配备、厂房、装备、技术能力以及标准规范执行能力等； （六）相应的质量保证大纲或者质量管理手册； （七）国务院核安全监管部门要求提交的其他材料。 申请单位提交的上述材料应当为中文或者中英文对照文本。"},{"i":8,"n":"第八条","txt":"国务院核安全监管部门收到注册登记申请后，应当对提交的申请材料进行形式审查，符合条件的，予以受理。"},{"i":9,"n":"第九条","txt":"国务院核安全监管部门应当在受理申请后45个工作日内完成审查，对符合条件的，准予注册登记，颁发《中华人民共和国民用核安全设备活动境外单位注册登记确认书》，并予以公告；对不符合条件的，书面通知申请单位，并说明理由。 在审查过程中，国务院核安全监管部门可以组织专家进行技术评审，必要时可以派员到境外申请单位进行现场核查。技术评审和现场核查所需时间不计算在前款规定的期限内。"},{"i":10,"n":"第十条","txt":"注册登记确认书分为四类： （一）中华人民共和国民用核安全设备境外设计单位注册登记确认书； （二）中华人民共和国民用核安全设备境外制造单位注册登记确认书； （三）中华人民共和国民用核安全设备境外安装单位注册登记确认书； （四）中华人民共和国民用核安全设备境外无损检验单位注册登记确认书。"},{"i":11,"n":"第十一条","txt":"注册登记确认书应当载明下列内容： （一）单位名称、所在国家（地区）、住所和法定代表人； （二）准予注册登记的活动种类和范围； （三）注册登记的有效期限； （四）注册登记确认书编号； （五）注册登记确认书发证机关和发证日期。"},{"i":12,"n":"第十二条","txt":"国务院核安全监管部门在完成境外单位注册登记后，应当将注册登记情况抄送国务院核行业主管部门和其他有关部门。 国务院核安全监管部门应当定期公布境外单位的注册登记情况。"},{"i":13,"n":"第十三条","txt":"注册登记确认书有效期限为5年。 注册登记确认书有效期届满，境外单位需要继续从事相关活动的，应当于注册登记确认书有效期届满6个月前，重新向国务院核安全监管部门提出注册登记申请。"},{"i":14,"n":"第十四条","txt":"经注册登记的境外单位，变更单位的名称、所在国家（地区）、住所或者法定代表人的，应当自其在所在国家（地区）变更登记之日起30日内，向国务院核安全监管部门提交下列材料，申请办理注册登记确认书变更手续： （一）注册登记变更申请书； （二）变更情况说明及相关证明材料； （三）国务院核安全监管部门要求提交的其他材料。 国务院核安全监管部门应当对境外单位注册登记确认书变更情况进行核实。情况属实的，准予办理注册登记确认书变更手续。变更后的注册登记确认书有效期适用原注册登记确认书的有效期。"},{"i":15,"n":"第十五条","txt":"变更注册登记的活动种类或者范围的，应当向国务院核安全监管部门重新提出申请。"},{"i":16,"n":"第十六条","txt":"禁止无注册登记确认书或者不按照注册登记确认书规定的活动种类和范围从事民用核安全设备设计、制造、安装和无损检验活动。 禁止境外单位委托未取得民用核安全设备相关许可证的境内单位或者未取得注册登记确认书的境外单位，为中华人民共和国境内民用核设施进行民用核安全设备设计、制造、安装和无损检验活动。 禁止伪造、变造、转让注册登记确认书。"},{"i":17,"n":"第十七条","txt":"经注册登记的境外单位，为中华人民共和国境内民用核设施进行民用核安全设备设计、制造、安装和无损检验活动时，应当遵守中华人民共和国相关的法律、行政法规和核安全监督管理规定，并对其从事的相应活动质量负责。"},{"i":18,"n":"第十八条","txt":"经注册登记的境外单位，为境内民用核设施进行民用核安全设备设计、制造、安装和无损检验活动时，应当接受国务院核安全监管部门及其派出机构的监督检查，如实反映情况，并提供必要资料。"},{"i":19,"n":"第十九条","txt":"民用核设施营运单位，应当自对外贸易合同生效之日起20个工作日内，向国务院核安全监管部门及其派出机构提交书面报告。书面报告的内容应当包括合同的有关质量与技术条款、合同的技术附件、交付日期、总体进度等。 营运单位应当在相关民用核安全设备设计、制造、安装和无损检验活动开始1个月前，向国务院核安全监管部门及其派出机构提交书面报告。书面报告的内容应当包括相关民用核安全设备设计、制造、安装和无损检验活动的内容、进度安排、质量计划以及营运单位监造计划。"},{"i":20,"n":"第二十条","txt":"国务院核安全监管部门及其派出机构，应当根据民用核设施营运单位按照本规定提交的相关报告，确定需要监督检查的内容，制定相应的监督检查计划，并书面通知营运单位。 营运单位应当在监督检查计划中确定的检查点开工2个月前，书面通知国务院核安全监管部门及其派出机构。"},{"i":21,"n":"第二十一条","txt":"国务院核安全监管部门及其派出机构，在对境外单位从事的民用核安全设备设计、制造、安装和无损检验活动进行监督检查时，有权采取下列措施： （一）向相关单位的法定代表人和其他有关人员了解情况； （二）进入相关单位进行现场检查； （三）查阅、复制相关文件、记录以及其他有关资料； （四）对发现的质量问题或者缺陷，责成民用核设施营运单位调查处理，并提交有关情况说明及后续处理报告。 国务院核安全监管部门及其派出机构在进行监督检查时，营运单位应当派员在现场配合。"},{"i":22,"n":"第二十二条","txt":"国务院核安全监管部门及其派出机构在进行监督检查时，应当对检查内容、发现问题及处理情况作出记录，并由监督检查人员、民用核设施营运单位人员和被监督检查单位有关负责人签字确认。 被监督检查单位有关负责人拒绝签字的，监督检查人员应当将有关情况记录在案。"},{"i":23,"n":"第二十三条","txt":"民用核设施营运单位应当对进口民用核安全设备进行监造、装运前检验、监装，并对进口民用核安全设备质量进行验收。"},{"i":24,"n":"第二十四条","txt":"民用核设施营运单位应当配备足够数量并具备相应专业知识和业务能力的监造、装运前检验、监装和验收人员。"},{"i":25,"n":"第二十五条","txt":"民用核设施营运单位应当制定监造、装运前检验、监装和验收计划，编制相应的检查要求。 负责监造、装运前检验、监装和验收的人员，应当执行监造、装运前检验、监装和验收计划以及检查要求。"},{"i":26,"n":"第二十六条","txt":"民用核设施营运单位应当对进口民用核安全设备设计活动的质量进行验证。"},{"i":27,"n":"第二十七条","txt":"民用核设施营运单位应当对进口民用核安全设备无损检验活动的质量进行验证。 前款规定的验证，可以采取现场见证、文件审查等方式进行。必要时，可以进行抽查复验。"},{"i":28,"n":"第二十八条","txt":"民用核设施营运单位应当对经注册登记的境外单位的质量保证大纲或者质量管理手册的实施情况进行监查。"},{"i":29,"n":"第二十九条","txt":"民用核设施营运单位的相关人员，应当对检查、验证或者监查的内容、发现的问题以及处理情况作出记录。发现有不符合合同或者有关规定的，营运单位应当及时处理，并将相关情况报国务院核安全监管部门备案。"},{"i":30,"n":"第三十条","txt":"国务院核安全监管部门及其所属的检验机构依法对进口民用核安全设备进行安全检验。安全检验可以采取独立检验或者验证的方式。 未经安全检验或者经安全检验不合格的进口民用核安全设备，不得在中华人民共和国境内的民用核设施上运行使用。"},{"i":31,"n":"第三十一条","txt":"进口民用核安全设备安全检验的依据主要包括： （一）中华人民共和国法律、行政法规和核安全监督管理规定； （二）民用核安全设备国家标准、行业标准或者境外单位注册登记申请时经国务院核安全监管部门认可的标准； （三）对外贸易合同； （四）相关设备技术规格书。"},{"i":32,"n":"第三十二条","txt":"从事进口民用核安全设备安全检验的人员，应当熟悉相关法律法规、标准及有关技术文件，并具备相应的检验技能。"},{"i":33,"n":"第三十三条","txt":"进口民用核安全设备到达口岸前，民用核设施营运单位应当向国务院核安全监管部门及其所属的检验机构报检，并提供下列材料： （一）进口民用核安全设备报检申请表； （二）装箱清单； （三）产品质量合格证书。 营运单位提交的上述材料应当为中文或者英文。"},{"i":34,"n":"第三十四条","txt":"国务院核安全监管部门及其所属的检验机构应当审查民用核设施营运单位按照本规定提交的报检材料。必要时，可以对到岸设备进行检查。 对符合要求的，签发《进口民用核安全设备口岸检查放行单》。营运单位持《进口民用核安全设备口岸检查放行单》依照有关法律法规的规定到相关机构办理商检手续。 对不符合要求的，国务院核安全监管部门及其所属的检验机构应当书面通知营运单位，并说明理由。"},{"i":35,"n":"第三十五条","txt":"民用核设施营运单位应当在进口民用核安全设备计划开箱检查20个工作日前，向国务院核安全监管部门及其所属的检验机构申报，并提交下列材料： （一）进口民用核安全设备装配总图、出厂检验试验报告等产品竣工文件； （二）营运单位监造、装运前检验和监装以及验收结果报告； （三）国务院核安全监管部门监督检查发现问题的处理和关闭情况报告； （四）进口民用核安全设备活动不符合项情况，以及较大和重大不符合项记录； （五）国务院核安全监管部门要求提交的其他材料。 营运单位提交的上述材料应当为中文或者英文。 国务院核安全监管部门及其所属的检验机构应当对上述开箱检查申报材料进行审查，并派安全检验人员在开箱检查前到达现场进行见证。 安全检验人员未到场前，营运单位不得进行开箱检查。"},{"i":36,"n":"第三十六条","txt":"开箱检查后，国务院核安全监管部门及其所属的检验机构应当在20个工作日内，出具开箱检查报告。 经检查不合格的，国务院核安全监管部门及其所属的检验机构应当在报告中说明不合格的原因，民用核设施营运单位不得进行安装调试活动。"},{"i":37,"n":"第三十七条","txt":"国务院核安全监管部门及其所属的检验机构应当对安装和装料前调试阶段涉及安全性能的试验进行检查。 民用核设施营运单位应当在进口民用核安全设备涉及安全性能的试验开始30个工作日前，通知国务院核安全监管及其所属的检验机构。国务院核安全监管部门及其所属的检验机构应当进行必要的选点见证，并制作见证记录。 国务院核安全监管部门及其所属的检验机构应当在进口民用核安全设备涉及安全性能的全部试验结束之日起30个工作日内，出具检查报告。"},{"i":38,"n":"第三十八条","txt":"国务院核安全监管部门及其所属的检验机构应当在完成文件记录检查、开箱检查、安装和装料前调试阶段涉及安全性能的试验检查后，出具安全检验报告。 对安全检验不合格的，民用核设施营运单位不得运行使用。"},{"i":39,"n":"第三十九条","txt":"进口民用核安全设备监督检查人员和安全检验人员，应当为被检查的单位保守技术秘密和业务秘密；不得滥用职权侵犯企业的合法权益，或者利用职务上的便利索取、收受财物；不得从事或者参与民用核安全设备经营活动。"},{"i":40,"n":"第四十条","txt":"国务院核安全监管部门及其所属的检验机构的安全检验不减轻也不转移境外单位和民用核设施营运单位的相关责任。"},{"i":41,"n":"第四十一条","txt":"国务院核安全监管部门及其派出机构、所属的检验机构和有关工作人员有下列行为之一的，对直接负责的主管人员和其他直接责任人员，依法给予处分；构成犯罪的，依法追究刑事责任： （一）对符合本规定的注册登记申请，不予受理或者注册登记的； （二）发现违反本规定的行为不予查处，或者接到举报后不依法处理的； （三）泄露被检查单位的技术秘密或者业务秘密的； （四）滥用职权侵犯企业的合法权益，或者利用职务上的便利索取、收受财物的； （五）从事或者参与民用核安全设备经营活动的； （六）在进口民用核安全设备监督管理工作中有其他违法行为的。"},{"i":42,"n":"第四十二条","txt":"境外单位有下列行为之一的，国务院核安全监管部门可以根据情节轻重，暂扣或者收回注册登记确认书： （一）违反中华人民共和国相关的法律、行政法规和核安全监督管理规定的； （二）不按照注册登记确认书规定的活动种类和范围从事民用核安全设备设计、制造、安装和无损检验活动的； （三）变更单位的名称、所在国家（地区）、住所或者法定代表人，未按规定办理注册登记确认书变更手续的； （四）涂改、转让注册登记确认书及其他弄虚作假行为的。"},{"i":43,"n":"第四十三条","txt":"申请民用核安全设备制造、安装活动注册登记的境外单位，拟自行对其制造、安装的民用核安全设备进行无损检验活动的，不需要单独申请无损检验活动注册登记。"},{"i":44,"n":"第四十四条","txt":"民用核设施营运单位委托民用核安全设备成套供应商、民用核设施核岛建造总承包商或者民用核安全设备持证单位采购设备的，由被委托的采购单位承担本规定中规定的营运单位的相关责任。但营运单位应当对进口民用核安全设备的使用和运行安全承担全面责任。"},{"i":45,"n":"第四十五条","txt":"本规定中有关术语的含义如下： 安全检验：是指在境外单位检验合格，以及民用核设施营运单位监造、装运前检验和监装合格的前提下，对进口民用核安全设备安全性能进行的检查或者验证，包括活动过程中形成的相关文件记录检查、开箱检查、以及安装和装料前调试阶段涉及安全性能的试验检查三个阶段。"},{"i":46,"n":"第四十六条","txt":"本规定自2008年1月1日起施行。"}],"zhongdianguankongxinwuranwuqingdan":[{"i":1,"n":"第一条","txt":"根据《中华人民共和国环境保护法》《中共中央 国务院关于深入打好污染防治攻坚战的意见》以及国务院办公厅印发的《新污染物治理行动方案》等相关法律法规和规范性文件，制定本清单。"},{"i":2,"n":"第二条","txt":"新污染物主要来源于有毒有害化学物质的生产和使用。 本清单根据有毒有害化学物质的环境风险，结合监管实际，经过技术可行性和经济社会影响评估后确定。"},{"i":3,"n":"第三条","txt":"对列入本清单的新污染物，应当按照国家有关规定采取禁止、限制、限排等环境风险管控措施。"},{"i":4,"n":"第四条","txt":"各级生态环境、工业和信息化、农业农村、商务、市场监督管理等部门以及海关，应当按照职责分工依法加强对新污染物的管控、治理。"},{"i":5,"n":"第五条","txt":"本清单根据实际情况实行动态调整。"},{"i":6,"n":"第六条","txt":"本清单自2023年3月1日起施行。 附表 重点管控新污染物清单 编号 新污染物名称 CAS号 主要环境风险管控措施    一   全氟辛基磺酸及其盐类和全氟辛基磺酰氟 （PFOS类） 例如： 1763-23-1 307-35-7 2795-39-3 29457-72-5 29081-56-9 70225-14-8 56773-42-3 251099-16-8 1.禁止生产。 2.禁止加工使用（以下用途除外）。   （1）用于生产灭火泡沫药剂（该用途的豁免期至2023年12月31日止）。 3.将PFOS类用于生产灭火泡沫药剂的企业，应当依法实施强制性清洁生产审核。 4.进口或出口全氟辛基磺酸及其盐类和全氟辛基磺酰氟，应办理有毒化学品进（出）口环境管理放行通知单。自2024年1月1日起，禁止进出口。 5.已禁止使用的，或者所有者申报废弃的，或者有关部门依法收缴或接收且需要销毁的全氟辛基磺酸"}]};
